Pager usage is off.
DO
-- ═══ TAKI · لقطةُ عقل القاعدة الحيّة ═══
-- @@VOLATILE الخادم: محلّي-داخل-الحاوية
-- القاعدة: postgres
-- النسخة: PostgreSQL 17.6
-- @@VOLATILE وُلِّدت: 2026-11-09 00:17 (توقيت الرياض)
-- 🪤 مولَّدٌ آلياً بـscripts/export-db-logic.sh — لا يُحرَّر بيد.
--    وهو لقطةٌ للمقارنة والتعافي، وليس ملفَّ هجرة: لا تُشغّله.



-- ═══ FUNCTION _admin_require_ctx() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._admin_require_ctx()
 RETURNS void
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid   text;
  v_ctx   text;
  v_reqs  text[];
  v_admin boolean;
  v_super boolean;
  v_perms text[];
BEGIN
  v_uid := auth.uid()::text;
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'forbidden: admin required' USING ERRCODE = '42501';
  END IF;

  SELECT (u.user_type = 'admin'), u.is_super_admin, u.admin_permissions
    INTO v_admin, v_super, v_perms
    FROM public.users u WHERE u.id = v_uid;

  IF NOT COALESCE(v_admin, false) THEN
    RAISE EXCEPTION 'forbidden: admin required' USING ERRCODE = '42501';
  END IF;
  IF COALESCE(v_super, false) THEN
    RETURN;                       -- المدير الأعلى: بلا قيود، كما كان دائماً
  END IF;

  GET DIAGNOSTICS v_ctx = PG_CONTEXT;

  SELECT array_agg(DISTINCT r.required_perm) INTO v_reqs
    FROM public.admin_rpc_permissions r
   WHERE v_ctx ~ ('function ' || r.rpc_name || '\(');

  IF v_reqs IS NULL THEN
    RETURN;                       -- غير مُخرَّطة: أي أدمن — لا يُقفل أحد أبداً
  END IF;

  IF NOT (COALESCE(v_perms, '{}'::text[]) && v_reqs) THEN
    RAISE EXCEPTION 'forbidden: this account does not have any of the % permissions', v_reqs
      USING ERRCODE = '42501';
  END IF;
END;
$function$
;


-- ═══ FUNCTION _apply_merchant_payment(p_provider text, p_merchant_id text, p_payment_ref text, p_amount numeric, p_barcode text, p_status text, p_vat numeric) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._apply_merchant_payment(p_provider text, p_merchant_id text, p_payment_ref text, p_amount numeric, p_barcode text, p_status text DEFAULT 'paid'::text, p_vat numeric DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_b public.bookings%ROWTYPE; v_rows integer; v_amt text;
BEGIN
  -- 🔴 v15.45 — القفلُ الأخير، وهذه هي الدالّةُ التي تختم `paid_at` فعلاً.
  -- كلُّ الحرّاس قبلها تحرس **الطريق** (pay_provider_on ⇐ _gateway_secrets
  -- ⇐ gatewayLive في الدالّة الحافة)، وهي وحدها كانت بلا فحصٍ خاصّ بها —
  -- فنداءٌ بـservice_role يلتفّ على الطريق كلّه ويختم طلباً «مدفوعاً» بصفر
  -- ريال. ولا يُقاس أمانٌ بعدد الأقفال على الطريق بل بقفلٍ على الباب نفسِه.
  IF lower(COALESCE(p_provider, '')) IN ('sim', 'simulated')
     AND COALESCE(p_status, '') = 'paid'
     AND NOT public.taki_is_lab() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SIM_NOT_ALLOWED');
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = p_barcode;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'BOOKING_NOT_FOUND'); END IF;

  INSERT INTO public.platform_payment_log
    (booking_barcode, merchant_id, buyer_id, amount, vat_amount, provider, payment_ref, status)
  VALUES (p_barcode, p_merchant_id, v_b.user_id, p_amount, COALESCE(p_vat, 0), p_provider, p_payment_ref, p_status)
  ON CONFLICT (provider, payment_ref) DO NOTHING;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  IF v_rows = 0 THEN RETURN jsonb_build_object('ok', true, 'duplicate', true); END IF;

  IF p_status = 'paid' THEN
    UPDATE public.bookings
    SET paid_at = now(), payment_provider = p_provider, payment_ref = p_payment_ref, paid_amount = p_amount
    WHERE barcode = p_barcode AND paid_at IS NULL;
    UPDATE public.merchant_gateways SET fail_count = 0, updated_at = now() WHERE merchant_id = p_merchant_id;

    v_amt := trim(to_char(p_amount, 'FM999999990.09'));
    IF p_provider = 'sim' THEN
      INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES
        ('ntf_pay_b_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         v_b.user_id,
         '🧪 (تجريبي) تمت محاكاة دفعتك', '(Test) Simulated payment recorded',
         'وضع تجريبي: سُجّلت محاكاة دفع ' || v_amt || ' ر.س للحجز ' || p_barcode || ' — لم يُخصم أي مبلغ حقيقي.',
         'Test mode: a simulated payment of ' || v_amt || ' SAR was recorded for booking ' || p_barcode || ' — no real money was charged.',
         'booking', jsonb_build_object('audience', 'buyer', 'barcode', p_barcode)),
        ('ntf_pay_s_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         p_merchant_id,
         '🧪 (تجريبي) محاكاة دفعة على حجز', '(Test) Simulated payment on a booking',
         'وضع تجريبي: سُجّلت محاكاة دفع ' || v_amt || ' ر.س على الحجز ' || p_barcode || ' — تنبيه: لا يوجد أي مبلغ حقيقي، هذه تجربة للنظام فقط.',
         'Test mode: a simulated payment of ' || v_amt || ' SAR was recorded on booking ' || p_barcode || ' — note: NO real money was received.',
         'booking', jsonb_build_object('audience', 'seller', 'barcode', p_barcode));
    ELSE
      INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES
        ('ntf_pay_b_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         v_b.user_id,
         '💳 تم استلام دفعتك بنجاح', 'Payment received',
         'تم دفع ' || v_amt || ' ر.س إلكترونياً لحساب التاجر مباشرة. حجزك: ' || p_barcode,
         'Paid ' || v_amt || ' SAR directly to the merchant. Booking: ' || p_barcode,
         'booking', jsonb_build_object('audience', 'buyer', 'barcode', p_barcode)),
        ('ntf_pay_s_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
         p_merchant_id,
         '💰 دفعة جديدة وصلت حسابك', 'New payment received',
         'استلمت ' || v_amt || ' ر.س في حساب بوابتك عن الحجز ' || p_barcode || ' — المبلغ في حسابك مباشرة دون أي عمولة.',
         'You received ' || v_amt || ' SAR in your gateway account for booking ' || p_barcode || '.',
         'booking', jsonb_build_object('audience', 'seller', 'barcode', p_barcode));
    END IF;
  END IF;

  RETURN jsonb_build_object('ok', true);
END $function$
;


-- ═══ FUNCTION _booking_amount_due(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._booking_amount_due(p_barcode text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT round(COALESCE(
           b.total_amount,
           (public.taki_booking_amount(b.deal_id, b.booked_quantity, b.selected_options, b.delivery_fee)->>'total')::numeric,
           0), 2)
    FROM public.bookings b
   WHERE b.barcode = upper(btrim(p_barcode));
$function$
;


-- ═══ FUNCTION _booking_card(p_barcode text, p_role text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._booking_card(p_barcode text, p_role text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'barcode', b.barcode, 'backup_code', b.backup_code,
    'user_name', COALESCE(b.user_name,'—'), 'user_phone', COALESCE(b.user_phone,'—'),
    'shop_name', COALESCE(NULLIF(u.shop,''), NULLIF(u.name,''), '—'),
    'deal_name', COALESCE(d.item_name,'العرض'), 'deal_id', b.deal_id,
    'quantity', b.booked_quantity, 'status', b.status,
    'notes', COALESCE(b.notes,''), 'merchant_note', COALESCE(b.merchant_note,''),
    'prep_time', b.prep_time, 'sort_at', b.booked_at, 'booked_at', b.booked_at,
    'expiry_time', b.expiry_time,
    'unread', (SELECT count(*) FROM booking_messages m
               WHERE m.barcode = b.barcode
                 AND m.sender_role <> p_role AND m.read_at IS NULL),
    'fulfillment', COALESCE(b.fulfillment,'pickup'),
    'delivery_fee', b.delivery_fee,
    'delivery_label',   b.delivery_address->>'label',
    'delivery_details', b.delivery_address->>'details',
    'delivery_phone',   b.delivery_address->>'phone',
    'delivery_lat',     b.delivery_address->>'lat',
    'delivery_lng',     b.delivery_address->>'lng',
    -- v14.42 — حالة التوصيل من القاعدة: بلا هذا يقرأ البوت الحالةَ من ذاكرة
    -- المحادثة التي تُمسح مع كل إعادة تشغيل، فيعرض «ابدأ البثّ» وهو جارٍ.
    'dlv_status', (SELECT dt.status FROM delivery_tracks dt WHERE dt.barcode = b.barcode),
    'payment_method', b.payment_method,
    'paid', b.paid_at IS NOT NULL,
    'paid_amount', b.paid_amount,
    'total_amount', b.total_amount,
    'role', p_role
  )
  FROM public.bookings b
  LEFT JOIN public.deals d ON d.id = b.deal_id
  LEFT JOIN public.users u ON u.id = b.store_id
  WHERE b.barcode = p_barcode;
$function$
;


-- ═══ FUNCTION _bot_gate_ok() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._bot_gate_ok()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_hdr    text;
  v_sent   text;
BEGIN
  -- v15.79 — تعطيلٌ صريحٌ وغائبٌ افتراضاً. والقيمةُ المطلوبةُ `'1'` بعينها.
  IF COALESCE((SELECT value FROM public.app_secrets WHERE key = 'bot_gate_bypass'), '') = '1' THEN
    RETURN true;
  END IF;

  v_hdr := current_setting('request.headers', true);

  -- لا ترويسات = نداءٌ من داخل القاعدة (مشغّل/كرون/خدمي) لا من متصفّح.
  -- PostgREST يضع الترويسات دائماً، فهذا الفرع غير قابل للوصول من الشبكة.
  IF v_hdr IS NULL OR v_hdr = '' THEN
    RETURN true;
  END IF;

  IF NOT (v_hdr IS JSON) THEN          -- PG16+ ; القاعدة هنا 17.6
    RETURN false;
  END IF;

  v_sent := v_hdr::json ->> 'x-bot-secret';
  IF v_sent IS NULL OR v_sent = '' THEN
    RETURN false;
  END IF;

  -- نافذةُ التدوير: السرُّ والسرُّ التالي مقبولان معاً (كما كانت).
  RETURN EXISTS (
    SELECT 1 FROM public.app_secrets
     WHERE key IN ('bot_gateway_secret', 'bot_gateway_secret_next')
       AND value IS NOT NULL AND value <> ''
       AND value = v_sent
  );
END $function$
;


-- ═══ FUNCTION _bot_gen_barcode() INVOKER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._bot_gen_barcode()
 RETURNS text
 LANGUAGE sql
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.taki_new_order_code();
$function$
;


-- ═══ FUNCTION _bot_profile(v_user users) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._bot_profile(v_user users)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sp store_profiles%ROWTYPE;
BEGIN
  IF v_user.user_type = 'seller' THEN
    SELECT * INTO v_sp FROM store_profiles WHERE store_id = v_user.id LIMIT 1;
  END IF;
  RETURN jsonb_build_object(
    'id', v_user.id, 'name', v_user.name, 'phone', v_user.phone,
    'user_type', v_user.user_type, 'shop', v_user.shop,
    'is_suspended', COALESCE(v_user.is_suspended, false),
    'is_super_admin', COALESCE(v_user.is_super_admin, false),
    'admin_permissions', COALESCE(v_user.admin_permissions, ARRAY[]::text[]),
    'subscription_plan', v_sp.subscription_plan,
    'subscription_expires_at', v_sp.subscription_expires_at,
    'lat', v_user.lat,
    'lng', v_user.lng,
    'bot_lang', COALESCE(v_user.bot_lang, 'ar')
  );
END;
$function$
;


-- ═══ FUNCTION _bot_uid(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._bot_uid(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT id FROM public.users
   WHERE deleted_at IS NULL
     AND public._bot_gate_ok()
     AND ( (p_telegram_id IS NOT NULL AND telegram_id     = p_telegram_id)
        OR (p_whatsapp_id IS NOT NULL AND whatsapp_chat_id = p_whatsapp_id) )
   LIMIT 1;
$function$
;


-- ═══ FUNCTION _broadcast_campaign_core(p_campaign_id text, p_force boolean) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._broadcast_campaign_core(p_campaign_id text, p_force boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE camp RECORD; affected INTEGER := 0;
BEGIN
  SELECT * INTO camp FROM public.promotional_campaigns WHERE id = p_campaign_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'Campaign % not found', p_campaign_id; END IF;

  -- v15.51 — الإعادةُ تمحو **أثرَ الإرسال** وحده ولا تمحو المشاهدة: حذفُ الصفّ
  -- كان يُلغي سجلَّ من رأى البانر أيضاً، وهو بيانٌ لا يُستعاد.
  IF p_force THEN
    UPDATE public.promo_impressions SET notified_at = NULL WHERE campaign_id = camp.id;
  END IF;

  WITH aud AS (
    -- 🪤 الجمهورُ لا يُطابَق بـ`user_type` حرفياً: متجرُ ناصر يملكه حسابُ أدمن،
    --    فـ«البائعون» كانت تستثنيه. قاعدةُ المشروع: `<> 'buyer'` لا `= 'seller'`.
    SELECT u.id
      FROM public.users u
     WHERE ( camp.target_audience = 'all'
          OR (camp.target_audience = 'seller' AND u.user_type <> 'buyer')
          OR (camp.target_audience = 'buyer'  AND u.user_type =  'buyer')
          OR (camp.target_audience NOT IN ('all','seller','buyer') AND u.user_type = camp.target_audience))
       AND u.deleted_at IS NULL
       AND COALESCE(u.is_suspended, false) = false
       AND public.taki_user_in_campaign(u.id, camp.target_city, camp.target_region)
  ),
  fresh AS (
    SELECT a.id FROM aud a
     WHERE NOT EXISTS (SELECT 1 FROM public.promo_impressions p
                        WHERE p.campaign_id = camp.id AND p.user_id = a.id
                          AND p.notified_at IS NOT NULL)
  ),
  ins AS (
    INSERT INTO public.notifications (
      user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    SELECT f.id, camp.title_ar, camp.title_en, camp.body_ar, camp.body_en, 'marketing',
      jsonb_build_object(
        'campaignId',    camp.id,
        'audience',      'buyer',
        'imageUrl',      camp.image_url,
        'actionUrl',     camp.action_url,
        'actionLabelAr', camp.action_label_ar,
        'actionLabelEn', camp.action_label_en,
        -- 🪤 البوتان يقرآن الشرطة السفلية. مفتاحٌ واحد بالسنام كان يعني أن زرّ
        -- الحملة لا يظهر في تيليجرام ولا واتساب أبداً، وناصر يملأ «رابط عند
        -- الضغط» ولا يجد أحدٌ ما يضغطه.
        'action_url',    camp.action_url,
        'image_url',     camp.image_url,
        'action_label_ar', camp.action_label_ar,
        'action_label_en', camp.action_label_en),
      NOW()
      FROM fresh f
    RETURNING user_id
  )
  INSERT INTO public.promo_impressions (campaign_id, user_id, seen_at, notified_at)
  SELECT camp.id, i.user_id, NOW(), NOW() FROM ins i
  ON CONFLICT (campaign_id, user_id) DO UPDATE SET notified_at = NOW();

  GET DIAGNOSTICS affected = ROW_COUNT;

  UPDATE public.promotional_campaigns
     SET current_impressions = COALESCE(current_impressions, 0) + affected,
         last_broadcast_at = NOW()
   WHERE id = camp.id;

  RETURN affected;
END $function$
;


-- ═══ FUNCTION _bump_gateway_fail(p_merchant_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._bump_gateway_fail(p_merchant_id text)
 RETURNS integer
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  UPDATE public.merchant_gateways
  SET fail_count = fail_count + 1, updated_at = now()
  WHERE merchant_id = p_merchant_id
  RETURNING fail_count;
$function$
;


-- ═══ FUNCTION _gateway_masked(p_merchant_id text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._gateway_masked(p_merchant_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE WHEN p_merchant_id IS NULL THEN NULL ELSE
    COALESCE(
      CASE WHEN g.merchant_id IS NULL THEN NULL ELSE jsonb_build_object(
        'provider',              g.provider,
        'publishable_key',       g.publishable_key,
        'extra_config',          g.extra_config,
        'key_last4',             g.key_last4,
        'has_secret',            public._gateway_secret_live(g.merchant_id),
        'has_webhook_secret',    EXISTS (SELECT 1 FROM vault.secrets s WHERE s.id = g.webhook_secret_id),
        'payment_modes',         g.payment_modes,
        'is_enabled',            g.is_enabled,
        'disabled_by_admin',     g.disabled_by_admin,
        'fail_count',            g.fail_count,
        'verified_at',           g.verified_at,
        'agreement_accepted_at', g.agreement_accepted_at,
        'provider_enabled',      public.pay_provider_on(g.provider)
      ) END,
      '{}'::jsonb
    )
    || jsonb_build_object(
        'direct_pay_enabled', public.direct_pay_on(),
        'enabled_providers',
          COALESCE((SELECT jsonb_agg(k.key) FROM (
            SELECT e.key FROM public.platform_settings ps,
                 LATERAL jsonb_each(ps.value) e
            WHERE ps.key = 'enabled_pay_providers' AND e.value = 'true'::jsonb
          ) k), '[]'::jsonb)
      )
  END
  FROM (SELECT 1) x
  LEFT JOIN public.merchant_gateways g ON g.merchant_id = p_merchant_id;
$function$
;


-- ═══ FUNCTION _gateway_secret_live(p_merchant_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._gateway_secret_live(p_merchant_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1
    FROM public.merchant_gateways g
    JOIN vault.secrets s ON s.id = g.secret_key_id
    WHERE g.merchant_id = p_merchant_id
  );
$function$
;


-- ═══ FUNCTION _gateway_secrets(p_merchant_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._gateway_secrets(p_merchant_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE g public.merchant_gateways%ROWTYPE; v_sk text; v_ws text;
BEGIN
  SELECT * INTO g FROM public.merchant_gateways WHERE merchant_id = p_merchant_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF g.secret_key_id IS NOT NULL THEN
    SELECT ds.decrypted_secret INTO v_sk FROM vault.decrypted_secrets ds WHERE ds.id = g.secret_key_id;
  END IF;
  IF g.webhook_secret_id IS NOT NULL THEN
    SELECT ds.decrypted_secret INTO v_ws FROM vault.decrypted_secrets ds WHERE ds.id = g.webhook_secret_id;
  END IF;
  RETURN jsonb_build_object(
    'provider', g.provider, 'publishable_key', g.publishable_key, 'extra_config', g.extra_config,
    'secret_key', v_sk, 'webhook_secret', v_ws,
    'is_enabled', g.is_enabled, 'disabled_by_admin', g.disabled_by_admin,
    'verified_at', g.verified_at, 'payment_modes', g.payment_modes, 'fail_count', g.fail_count,
    'provider_enabled', public.pay_provider_on(g.provider));
END $function$
;


-- ═══ FUNCTION _gateway_write(p_merchant_id text, p_provider text, p_publishable_key text, p_secret_key text, p_webhook_secret text, p_extra jsonb, p_actor_id text, p_actor_type text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._gateway_write(p_merchant_id text, p_provider text, p_publishable_key text, p_secret_key text, p_webhook_secret text, p_extra jsonb, p_actor_id text, p_actor_type text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row public.merchant_gateways%ROWTYPE;
  v_sk  text := NULLIF(btrim(COALESCE(p_secret_key, '')), '');
  v_ws  text := NULLIF(btrim(COALESCE(p_webhook_secret, '')), '');
  v_provider_changed boolean := false;
  v_by_admin boolean := (p_actor_id IS DISTINCT FROM p_merchant_id);
  v_sk_name text := 'mg_' || p_merchant_id || '_sk';
  v_ws_name text := 'mg_' || p_merchant_id || '_whs';
  v_sk_id uuid;
  v_ws_id uuid;
  v_back  text;
BEGIN
  IF p_provider IS NULL OR p_provider NOT IN ('sim','moyasar','tap','paytabs','payfort','hyperpay','checkout') THEN
    RAISE EXCEPTION 'BAD_PROVIDER';
  END IF;

  SELECT * INTO v_row FROM public.merchant_gateways WHERE merchant_id = p_merchant_id;
  IF NOT FOUND THEN
    INSERT INTO public.merchant_gateways (merchant_id, provider)
    VALUES (p_merchant_id, p_provider) RETURNING * INTO v_row;
  END IF;
  v_provider_changed := (v_row.provider IS DISTINCT FROM p_provider);

  -- 🪤 v14.44 — المؤشِّر لا يُصدَّق إلا إذا حلّ إلى صفٍّ في الخزنة. ومؤشِّرٌ
  -- معلَّق يُشفى بالاسم القانوني إن وُجد (اسم الخزنة فريد، فإنشاء ثانٍ بنفس
  -- الاسم كان سيفشل، والكتابة على مؤشِّرٍ ميت كانت تمرّ صامتة).
  SELECT s.id INTO v_sk_id FROM vault.secrets s WHERE s.id = v_row.secret_key_id;
  IF v_sk_id IS NULL THEN
    SELECT s.id INTO v_sk_id FROM vault.secrets s WHERE s.name = v_sk_name;
  END IF;
  SELECT s.id INTO v_ws_id FROM vault.secrets s WHERE s.id = v_row.webhook_secret_id;
  IF v_ws_id IS NULL THEN
    SELECT s.id INTO v_ws_id FROM vault.secrets s WHERE s.name = v_ws_name;
  END IF;

  -- الوضع التجريبي لا يطلب مفاتيح — سر داخلي عشوائي يُولَّد له
  IF p_provider = 'sim' AND v_sk IS NULL AND (v_provider_changed OR v_sk_id IS NULL) THEN
    v_sk := md5(random()::text || clock_timestamp()::text) || md5(random()::text || p_merchant_id);
  END IF;

  -- المؤشِّران يُكتبان بما حُلّ فعلاً: مؤشِّرٌ معلَّق لا اسم له في الخزنة
  -- يصير NULL هنا فلا يبقى صفٌّ يدّعي مفتاحاً لا وجود له.
  UPDATE public.merchant_gateways SET
    provider          = p_provider,
    publishable_key   = COALESCE(NULLIF(btrim(COALESCE(p_publishable_key,'')), ''), publishable_key),
    extra_config      = COALESCE(p_extra, extra_config),
    secret_key_id     = v_sk_id,
    webhook_secret_id = v_ws_id,
    key_last4         = CASE WHEN v_sk_id IS NULL THEN NULL ELSE key_last4 END,
    verified_at       = CASE WHEN v_provider_changed OR v_sk IS NOT NULL OR v_ws IS NOT NULL
                               OR v_sk_id IS DISTINCT FROM v_row.secret_key_id
                             THEN NULL ELSE verified_at END,
    is_enabled        = CASE WHEN v_provider_changed OR v_sk_id IS NULL THEN false ELSE is_enabled END,
    fail_count        = 0,
    updated_at        = now()
  WHERE merchant_id = p_merchant_id;

  IF v_sk IS NOT NULL THEN
    IF v_sk_id IS NULL THEN
      v_sk_id := vault.create_secret(v_sk, v_sk_name, 'TAKI merchant gateway secret key');
    ELSE
      PERFORM vault.update_secret(v_sk_id, v_sk);
    END IF;

    -- الإثبات: اقرأ ما كُتب. `vault.update_secret` على مؤشِّرٍ ميت تُرجع
    -- void بلا خطأ وتكتب صفر صفوف — فالقراءة وحدها تكشف الفشل.
    SELECT ds.decrypted_secret INTO v_back FROM vault.decrypted_secrets ds WHERE ds.id = v_sk_id;
    IF v_back IS DISTINCT FROM v_sk THEN
      RAISE EXCEPTION 'SECRET_WRITE_FAILED';
    END IF;

    UPDATE public.merchant_gateways
    SET secret_key_id = v_sk_id, key_last4 = right(v_sk, 4)
    WHERE merchant_id = p_merchant_id;
  END IF;

  IF v_ws IS NOT NULL THEN
    IF v_ws_id IS NULL THEN
      v_ws_id := vault.create_secret(v_ws, v_ws_name, 'TAKI merchant gateway webhook secret');
    ELSE
      PERFORM vault.update_secret(v_ws_id, v_ws);
    END IF;

    SELECT ds.decrypted_secret INTO v_back FROM vault.decrypted_secrets ds WHERE ds.id = v_ws_id;
    IF v_back IS DISTINCT FROM v_ws THEN
      RAISE EXCEPTION 'SECRET_WRITE_FAILED';
    END IF;

    UPDATE public.merchant_gateways SET webhook_secret_id = v_ws_id WHERE merchant_id = p_merchant_id;
  END IF;

  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (p_actor_id, p_actor_type, 'gateway_keys_updated', 'merchant_gateway', p_merchant_id,
          jsonb_build_object('provider', p_provider, 'by_admin', v_by_admin,
                             'secret_changed', v_sk IS NOT NULL, 'webhook_changed', v_ws IS NOT NULL));
  INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES ('ntf_gw_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
          p_merchant_id,
          '🔐 تحديث بيانات بوابة الدفع', 'Payment gateway credentials updated',
          CASE WHEN v_by_admin
            THEN 'قامت الإدارة بإعداد/تحديث بوابة الدفع لمتجرك. تجدها في لوحتك ← بطاقة «💳 بوابة الدفع».'
            ELSE 'تم تحديث بيانات بوابة الدفع لمتجرك. إن لم تكن أنت من قام بذلك فأوقف البوابة فوراً وتواصل مع الإدارة.' END,
          CASE WHEN v_by_admin
            THEN 'The platform admin configured/updated your store''s payment gateway.'
            ELSE 'Your store''s payment gateway credentials were updated. If this was not you, disable the gateway immediately and contact support.' END,
          'system', jsonb_build_object('audience', 'seller'));

  RETURN public._gateway_masked(p_merchant_id);
END $function$
;


-- ═══ FUNCTION _refund_notify(p_user_id text, p_title_ar text, p_title_en text, p_body_ar text, p_body_en text, p_barcode text, p_audience text, p_event text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._refund_notify(p_user_id text, p_title_ar text, p_title_en text, p_body_ar text, p_body_en text, p_barcode text, p_audience text, p_event text)
 RETURNS void
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES ('ntf_rf_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
          p_user_id, p_title_ar, p_title_en, p_body_ar, p_body_en, 'booking',
          jsonb_build_object('audience', p_audience, 'event', p_event, 'barcode', p_barcode));
$function$
;


-- ═══ FUNCTION _stamp_gateway_verified(p_merchant_id text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._stamp_gateway_verified(p_merchant_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_prov text;
BEGIN
  SELECT lower(coalesce(provider,'')) INTO v_prov
    FROM public.merchant_gateways WHERE merchant_id = p_merchant_id;
  IF v_prov = 'sim' THEN RAISE EXCEPTION 'SIM_NOT_ALLOWED'; END IF;
  UPDATE public.merchant_gateways
     SET verified_at = now(), fail_count = 0, updated_at = now()
   WHERE merchant_id = p_merchant_id;
  -- كتابةٌ بصفر صفوفٍ ليست نجاحاً — والمنادي يظنّ أنها كذلك.
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
END
$function$
;


-- ═══ FUNCTION _taki_apply_package(p_store_id text, p_package_id integer, p_expires_at timestamp with time zone, p_auto_renew boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_apply_package(p_store_id text, p_package_id integer, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_auto_renew boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pkg   jsonb;
  v_price numeric; v_disc numeric; v_days integer; v_max integer; v_net numeric;
  v_now   timestamptz := now();
  v_end   timestamptz;
BEGIN
  SELECT pkg INTO v_pkg
    FROM public.platform_settings ps,
         LATERAL jsonb_array_elements(ps.value) AS pkg
   WHERE ps.key = 'location_packages' AND (pkg->>'id')::int = p_package_id
   LIMIT 1;
  IF v_pkg IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unknown_package');
  END IF;
  IF COALESCE((v_pkg->>'active')::boolean, false) IS NOT TRUE THEN
    RETURN jsonb_build_object('success', false, 'error', 'package_inactive');
  END IF;

  v_price := COALESCE((v_pkg->>'price')::numeric, 0);
  v_disc  := COALESCE((v_pkg->>'discount')::numeric, 0);
  v_days  := COALESCE((v_pkg->>'durationDays')::int, 30);
  v_max   := COALESCE((v_pkg->>'max')::int, 1);
  v_net   := round(v_price * (1 - (v_disc / 100.0)), 2);

  -- 🔴 تاريخُ المتجر هو الحاكم إن وُجد، ومدّةُ الكتالوج ارتدادٌ لمسار
  --    البوّابة وحده (حيث لا متجرَ يُحدّد تاريخاً). وبهذا:
  --      • تُصبح الاستعادةُ المتكرّرة بلا أثر (نفسُ التاريخ يُكتب).
  --      • وتزول الفجوةُ الشهريّة: تاريخُ أبل **هو** موعدُ التحصيل التالي.
  v_end := COALESCE(p_expires_at, v_now + make_interval(days => v_days));
  IF v_end <= v_now THEN
    RETURN jsonb_build_object('success', false, 'error', 'expiry_in_past',
                              'expires_at', v_end);
  END IF;

  INSERT INTO public.store_profiles (
    store_id, subscription_plan, subscription_started_at, subscription_expires_at,
    subscription_amount, max_branches, subscription_package_id,
    auto_renew, subscription_canceled_at, updated_at)
  VALUES (p_store_id, 'premium', v_now, v_end, v_net, v_max, p_package_id,
          COALESCE(p_auto_renew, true),
          CASE WHEN p_auto_renew IS FALSE THEN v_now ELSE NULL END, v_now)
  ON CONFLICT (store_id) DO UPDATE SET
    subscription_plan        = EXCLUDED.subscription_plan,
    -- 🪤 وبدايةُ الاشتراك لا تُعاد عند التجديد: إعادتُها تُفقد تاريخَ أوّل
    --    اشتراكٍ وتُفسد تقاريرَ الأقدميّة والاستبقاء.
    subscription_started_at  = COALESCE(public.store_profiles.subscription_started_at,
                                        EXCLUDED.subscription_started_at),
    -- ولا تُقصَّر صلاحيّةٌ قائمةٌ بتاريخٍ أقدم (إشعارٌ متأخّرٌ أو خارجُ ترتيب).
    subscription_expires_at  = GREATEST(EXCLUDED.subscription_expires_at,
                                        COALESCE(public.store_profiles.subscription_expires_at,
                                                 EXCLUDED.subscription_expires_at)),
    subscription_amount      = EXCLUDED.subscription_amount,
    max_branches             = EXCLUDED.max_branches,
    subscription_package_id  = EXCLUDED.subscription_package_id,
    -- 🔴 وحالةُ التجديد تُحترم: NULL تعني «لا تمسّها» (مسارُ البوّابة
    --    يُفعّلها، والمتجرُ يقول حالتَه الحقيقيّة).
    auto_renew               = CASE WHEN p_auto_renew IS NULL THEN true ELSE p_auto_renew END,
    subscription_canceled_at = CASE
                                 WHEN p_auto_renew IS FALSE
                                   THEN COALESCE(public.store_profiles.subscription_canceled_at, v_now)
                                 ELSE NULL END,
    updated_at               = EXCLUDED.updated_at;

  RETURN jsonb_build_object('success', true, 'plan', 'premium', 'amount', v_net,
    'days', v_days, 'max_branches', v_max,
    'expires_at', (SELECT subscription_expires_at FROM public.store_profiles
                    WHERE store_id = p_store_id),
    'package_ar', v_pkg->>'ar', 'net', v_net,
    'from_store_date', p_expires_at IS NOT NULL);
END $function$
;


-- ═══ FUNCTION _taki_apply_package_dry(p_package_id integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_apply_package_dry(p_package_id integer)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN pkg IS NULL THEN jsonb_build_object('success', false, 'error', 'unknown_package')
    WHEN COALESCE((pkg->>'active')::boolean, false) IS NOT TRUE
      THEN jsonb_build_object('success', false, 'error', 'package_inactive')
    ELSE jsonb_build_object('success', true,
      'net', round(COALESCE((pkg->>'price')::numeric, 0)
                   * (1 - (COALESCE((pkg->>'discount')::numeric, 0) / 100.0)), 2),
      'days', COALESCE((pkg->>'durationDays')::int, 30),
      'max_branches', COALESCE((pkg->>'max')::int, 1))
  END
  FROM (SELECT (SELECT pkg FROM public.platform_settings ps,
                       LATERAL jsonb_array_elements(ps.value) AS pkg
                 WHERE ps.key = 'location_packages'
                   AND (pkg->>'id')::int = p_package_id LIMIT 1) AS pkg) q;
$function$
;


-- ═══ FUNCTION _taki_client_ip() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_client_ip()
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  -- 🔴 المقدارُ الوحيد الذي يُعدَّل: عددُ الوسائط التي تُلحقها سلسلةُ
  --    وكلائنا بآخر الترويسة. اليومَ **واحد** (Kong). والسلسلةُ:
  --      المتصفّح → Caddy (الحافة، بلا trusted_proxies) → Kong → PostgREST
  --    وCloudflare اليومَ سحابةٌ رمادية (DNS فقط). فلحظةَ تخضيرها
  --    يصير العددُ **٢** — ولا موضعَ آخرَ يُعدَّل.
  c_hops  constant int := 1;
  v_raw   text;
  v_arr   text[];
  v_keep  int;
  v_i     int;
  v_cand  text;
BEGIN
  BEGIN
    v_raw := COALESCE(
               nullif(current_setting('request.headers', true), '')::json ->> 'x-forwarded-for',
               nullif(current_setting('request.headers', true), '')::json ->> 'x-real-ip');
  EXCEPTION WHEN OTHERS THEN
    v_raw := NULL;        -- ترويسةٌ مشوّهة ليست سبباً لإسقاط الطلب
  END;
  IF v_raw IS NULL OR btrim(v_raw) = '' THEN RETURN NULL; END IF;

  v_arr  := string_to_array(v_raw, ',');
  v_keep := COALESCE(array_length(v_arr, 1), 0) - c_hops;
  -- ترويسةٌ أقصرُ من السلسلة (مثلاً `x-real-ip` وهي مفردةٌ دائماً) ⇒ الأوّل
  IF v_keep < 1 THEN v_keep := 1; END IF;

  -- 🔴 شبكةُ أمانٍ لا تجميل: لو أخطأ `c_hops` فاستُقرّ على عنوانٍ خاصّ،
  --    صار الحدُّ دلواً عالمياً — فيُتزحزح يساراً حتى أوّلِ عنوانٍ عامّ.
  --    ولا يُتزحزح يميناً أبداً: اليمينُ هو وسيطُنا نحن.
  v_i := v_keep;
  WHILE v_i >= 1 LOOP
    v_cand := nullif(btrim(v_arr[v_i]), '');
    IF v_cand IS NOT NULL AND v_cand !~
       '^(10\.|127\.|169\.254\.|172\.(1[6-9]|2[0-9]|3[01])\.|192\.168\.|0\.|::1$|[fF][cCdD])'
    THEN
      RETURN v_cand;
    END IF;
    v_i := v_i - 1;
  END LOOP;

  -- كلُّ السلسلة خاصّة (نداءٌ من داخل الشبكة) ⇒ كما كانت الدالّةُ تماماً.
  -- وNULL هنا غيرُ خطِر بعد البند ② : يصير الدلوُ `noip` المشترك، فالمهاجمُ
  -- الذي يُفلت من الاستنباط يَخنق **نفسه** ولا يمسّ أحداً.
  RETURN nullif(btrim(v_arr[1]), '');
END
$function$
;


-- ═══ FUNCTION _taki_deal_branches_sync() DEFINER owner=postgres search_path=search_path=public, pg_catalog anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_deal_branches_sync()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    DELETE FROM public.deal_branches WHERE deal_id = OLD.id;
    RETURN NULL;
  END IF;
  PERFORM public._taki_rebuild_deal_branches(NEW.id);
  RETURN NULL;
END
$function$
;


-- ═══ FUNCTION _taki_deal_loc_keys(p_location_id text, p_lat double precision, p_lng double precision, p_locations jsonb) INVOKER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_deal_loc_keys(p_location_id text, p_lat double precision, p_lng double precision, p_locations jsonb)
 RETURNS SETOF text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_location_id IS NOT NULL AND p_location_id <> 'other'
         AND p_location_id NOT LIKE 'custom\_%' ESCAPE '\'
    THEN 'loc:' || p_location_id
    ELSE 'geo:' || ROUND(COALESCE(p_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(p_lng,0)::numeric,3)::text
  END
  UNION
  SELECT CASE
    WHEN NULLIF(e->>'locationId','') IS NOT NULL AND e->>'locationId' <> 'other'
         AND e->>'locationId' NOT LIKE 'custom\_%' ESCAPE '\'
    THEN 'loc:' || (e->>'locationId')
    ELSE 'geo:' || ROUND(COALESCE(NULLIF(e->>'lat','')::numeric,0),3)::text || ',' || ROUND(COALESCE(NULLIF(e->>'lng','')::numeric,0),3)::text
  END
  FROM jsonb_array_elements(
         CASE WHEN p_locations IS NOT NULL AND jsonb_typeof(p_locations) = 'array'
              THEN p_locations ELSE '[]'::jsonb END) e
  WHERE COALESCE(e->>'id','') <> 'primary';
$function$
;


-- ═══ FUNCTION _taki_hook_url_ok(p_url text) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_hook_url_ok(p_url text)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_auth text; v_host text; v_port text; v_tld text;
BEGIN
  IF p_url IS NULL THEN RETURN false; END IF;
  -- لا تهذيبَ ولا توحيدَ حالة: ما لا يبدأ حرفياً بـ`https://` مرفوضٌ كما كان،
  -- فلا تُوسَّع المدخلاتُ المقبولةُ بحجّة التحسين.
  IF left(p_url, 8) <> 'https://' THEN RETURN false; END IF;
  IF length(p_url) < 12 OR length(p_url) > 500 THEN RETURN false; END IF;
  IF p_url ~ '[[:space:][:cntrl:]]' THEN RETURN false; END IF;

  v_auth := lower(split_part(split_part(split_part(substr(p_url, 9), '/', 1), '?', 1), '#', 1));
  IF v_auth !~ '^[a-z0-9.-]+(:[0-9]{1,5})?$' THEN RETURN false; END IF;

  v_host := split_part(v_auth, ':', 1);
  v_port := CASE WHEN v_auth ~ ':' THEN split_part(v_auth, ':', 2) ELSE '' END;
  IF v_port NOT IN ('', '443') THEN RETURN false; END IF;

  IF v_host !~ '^([a-z0-9]([a-z0-9-]*[a-z0-9])?\.)+[a-z]{2,63}$' THEN RETURN false; END IF;

  v_tld := split_part(v_host, '.', (length(v_host) - length(replace(v_host, '.', '')))::int + 1);
  -- 🪤 سببٌ ثانٍ **مستقلّ** لا تجميل: لاحقاتُ الاستخدام الخاصّ (RFC 6761/6762
  --    و`.internal` و`.corp`) تمرّ من شرط الحروف الخالصة وتُشير إلى شبكةٍ
  --    داخليّة. وتُسمّى هنا صريحةً ولا تُترك للشكل.
  IF v_tld IN ('local','localhost','internal','intranet','corp','home','lan',
               'test','example','invalid','onion','i2p','alt') THEN
    RETURN false;
  END IF;

  RETURN true;
END
$function$
;


-- ═══ FUNCTION _taki_job_stalled(p_last_run timestamp with time zone, p_every_min integer, p_alive_since timestamp with time zone, p_first_seen timestamp with time zone, p_now timestamp with time zone) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_job_stalled(p_last_run timestamp with time zone, p_every_min integer, p_alive_since timestamp with time zone, p_first_seen timestamp with time zone DEFAULT NULL::timestamp with time zone, p_now timestamp with time zone DEFAULT now())
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT
    -- الخادمُ لم يُكمل فترةً واحدةً من فترات هذه الوظيفة منذ عودته
    -- ⇒ لا تُتَّهم: غيابُها مُفسَّرٌ بالتوقّف لا بعطلٍ فيها.
    CASE WHEN p_alive_since IS NULL
           OR p_now - p_alive_since < make_interval(mins => COALESCE(p_every_min, 1440) + 10)
         THEN false
    -- ولا تُتَّهم وظيفةٌ رُصدت حديثاً ولم تمضِ فترتُها بعد
         WHEN p_first_seen IS NOT NULL
          AND p_now - p_first_seen < make_interval(mins => COALESCE(p_every_min, 1440) + 10)
         THEN false
    -- لم تعمل قطّ، والخادمُ حيٌّ منذ فترةٍ كاملة ⇒ عطلٌ حقيقيّ
         WHEN p_last_run IS NULL THEN true
    -- 🪤 والمقارنةُ من **أحدثِ** الزمنين: آخرِ تشغيلٍ أو عودةِ الخادم.
    --    فبعد توقّفٍ طويل لا تُحسب أيّامُ التوقّف على الوظيفة.
         ELSE GREATEST(p_last_run, p_alive_since)
              < p_now - make_interval(mins => COALESCE(p_every_min, 1440) * 3 + 10)
    END;
$function$
;


-- ═══ FUNCTION _taki_jpath(p_body jsonb, p_path text) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_jpath(p_body jsonb, p_path text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE WHEN p_body IS NULL OR COALESCE(btrim(p_path),'') = '' THEN NULL
              ELSE p_body #>> string_to_array(btrim(p_path), '.') END;
$function$
;


-- ═══ FUNCTION _taki_km(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_km(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
 RETURNS double precision
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
AS $function$
  SELECT 2 * 6371 * asin(least(1.0, sqrt(
      power(sin(radians(lat2 - lat1) / 2), 2)
    + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2))));
$function$
;


-- ═══ FUNCTION _taki_loc_declare(p_deal_id text, p_el jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_loc_declare(p_deal_id text, p_el jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_out jsonb := p_el; v_loc text := p_el->>'id'; v_oh int; k text; v int;
BEGIN
  IF (p_el ? 'quantity') AND NULLIF(p_el->>'quantity','') IS NOT NULL THEN
    v_oh := GREATEST(0, (p_el->>'quantity')::int);
    v_out := jsonb_set(v_out, '{onHand}', to_jsonb(v_oh), true);
    v_out := jsonb_set(v_out, '{quantity}',
               to_jsonb(GREATEST(0, v_oh - public.taki_open_holds(p_deal_id, NULL, v_loc))));
  END IF;

  IF (p_el ? 'variantQtys') AND jsonb_typeof(p_el->'variantQtys') = 'object' THEN
      -- 🔴 v15.34 — `jsonb_set` ذو المسار المركّب يُنشئ **المفتاح الأخير وحده**،
      -- فإن غاب الكائنُ الأب أعاد المُدخَلَ كما هو **بلا خطأ**. والقياس: صفرٌ من
      -- خمسة فروعٍ في الإنتاج يحمل `variantOnHand` مقابل اثنين يحملان `variantQtys`.
      -- (والصوابُ مكتوبٌ أصلاً في `_taki_loc_seed` ولم يُنسخ إلى أخواته.)
    IF NOT (v_out ? 'variantOnHand') THEN v_out := jsonb_set(v_out, '{variantOnHand}', '{}'::jsonb, true); END IF;
    FOR k, v IN SELECT key, NULLIF(value #>> '{}','')::int
                  FROM jsonb_each(p_el->'variantQtys') LOOP
      CONTINUE WHEN v IS NULL;
      v_out := jsonb_set(v_out, ARRAY['variantOnHand', k], to_jsonb(GREATEST(0, v)), true);
      v_out := jsonb_set(v_out, ARRAY['variantQtys', k],
                 to_jsonb(GREATEST(0, v - public.taki_open_holds(p_deal_id, k, v_loc))), true);
    END LOOP;
  END IF;

  RETURN v_out;
END
$function$
;


-- ═══ FUNCTION _taki_loc_on_hand(p_deal_id text, p_el jsonb, p_inc jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_loc_on_hand(p_deal_id text, p_el jsonb, p_inc jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_out jsonb := p_el; v_loc text := p_el->>'id'; v_oh int; k text; v int;
BEGIN
  IF p_inc IS NULL THEN RETURN v_out; END IF;

  IF (p_inc ? 'onHand') AND NULLIF(p_inc->>'onHand','') IS NOT NULL THEN
    v_oh := GREATEST(0, (p_inc->>'onHand')::int);
    v_out := jsonb_set(v_out, '{onHand}', to_jsonb(v_oh));
    v_out := jsonb_set(v_out, '{quantity}',
                       to_jsonb(GREATEST(0, v_oh - public.taki_open_holds(p_deal_id, NULL, v_loc))));
  END IF;

  IF (p_inc ? 'variantOnHand') AND jsonb_typeof(p_inc->'variantOnHand') = 'object' THEN
      -- 🔴 v15.34 — `jsonb_set` ذو المسار المركّب يُنشئ **المفتاح الأخير وحده**،
      -- فإن غاب الكائنُ الأب أعاد المُدخَلَ كما هو **بلا خطأ**. والقياس: صفرٌ من
      -- خمسة فروعٍ في الإنتاج يحمل `variantOnHand` مقابل اثنين يحملان `variantQtys`.
      -- (والصوابُ مكتوبٌ أصلاً في `_taki_loc_seed` ولم يُنسخ إلى أخواته.)
    IF NOT (v_out ? 'variantOnHand') THEN v_out := jsonb_set(v_out, '{variantOnHand}', '{}'::jsonb, true); END IF;
    IF NOT (v_out ? 'variantQtys')   THEN v_out := jsonb_set(v_out, '{variantQtys}',   '{}'::jsonb, true); END IF;
    FOR k, v IN SELECT key, NULLIF(value #>> '{}','')::int
                  FROM jsonb_each(p_inc->'variantOnHand') LOOP
      CONTINUE WHEN v IS NULL;
      v_out := jsonb_set(v_out, ARRAY['variantOnHand', k], to_jsonb(GREATEST(0, v)), true);
      v_out := jsonb_set(v_out, ARRAY['variantQtys', k],
                 to_jsonb(GREATEST(0, v - public.taki_open_holds(p_deal_id, k, v_loc))), true);
    END LOOP;
  END IF;

  RETURN v_out;
END
$function$
;


-- ═══ FUNCTION _taki_loc_seed(p_deal_id text, p_el jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_loc_seed(p_deal_id text, p_el jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_out jsonb := p_el; v_loc text := p_el->>'id'; k text; v int;
BEGIN
  IF (p_el ? 'quantity') AND NULLIF(p_el->>'quantity','') IS NOT NULL
     AND NOT (p_el ? 'onHand') THEN
    v_out := jsonb_set(v_out, '{onHand}', to_jsonb(GREATEST(0,
               (p_el->>'quantity')::int + public.taki_open_holds(p_deal_id, NULL, v_loc))));
  END IF;

  IF (p_el ? 'variantQtys') AND jsonb_typeof(p_el->'variantQtys') = 'object'
     AND NOT (p_el ? 'variantOnHand') THEN
    v_out := jsonb_set(v_out, '{variantOnHand}', '{}'::jsonb, true);
    FOR k, v IN SELECT key, NULLIF(value #>> '{}','')::int
                  FROM jsonb_each(p_el->'variantQtys') LOOP
      CONTINUE WHEN v IS NULL;
      v_out := jsonb_set(v_out, ARRAY['variantOnHand', k], to_jsonb(GREATEST(0,
                 v + public.taki_open_holds(p_deal_id, k, v_loc))), true);
    END LOOP;
  END IF;

  RETURN v_out;
END
$function$
;


-- ═══ FUNCTION _taki_point_in_polygon(p_pts jsonb, p_lat double precision, p_lng double precision) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_point_in_polygon(p_pts jsonb, p_lat double precision, p_lng double precision)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE n int; i int; j int; xi float8; yi float8; xj float8; yj float8; inside boolean := false;
BEGIN
  IF p_pts IS NULL OR jsonb_typeof(p_pts) <> 'array' THEN RETURN false; END IF;
  n := jsonb_array_length(p_pts);
  IF n < 3 THEN RETURN false; END IF;
  j := n - 1;
  FOR i IN 0 .. n - 1 LOOP
    yi := (p_pts->i->>0)::float8; xi := (p_pts->i->>1)::float8;
    yj := (p_pts->j->>0)::float8; xj := (p_pts->j->>1)::float8;
    IF ((yi > p_lat) <> (yj > p_lat))
       AND (p_lng < (xj - xi) * (p_lat - yi) / (yj - yi) + xi) THEN
      inside := NOT inside;
    END IF;
    j := i;
  END LOOP;
  RETURN inside;
END
$function$
;


-- ═══ FUNCTION _taki_provider_headers(p_provider text, p_tok jsonb) INVOKER owner=supabase_admin search_path=NOT_SET anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_provider_headers(p_provider text, p_tok jsonb)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE lower(COALESCE(p_provider, ''))
    WHEN 'salla' THEN jsonb_build_object(
      'Authorization', 'Bearer ' || COALESCE(p_tok->>'access_token', ''),
      'Accept', 'application/json')
    -- 🔴 ترويستان بقيمتين **مختلفتين**: `authorization` توكنُ التطبيق (JWT)
    --    و`access_token` توكنُ المتجر. وخلطُهما يُنتج ٤٠١ دائماً.
    -- 🪤 ويُرسل توكنُ المتجر **بالاسمين** بنفس القيمة: وثيقتُهم تمنع إرسالهما
    --    بقيمتين **مختلفتين** وحدها، وبعضُ نقاط النهاية موثَّقةٌ بـ`Access-Token`
    --    وبعضُها بـ`X-Manager-Token` وأولويّتُهما غيرُ مُثبتة. فالاسمان معاً
    --    يُغطّيان الاثنين بلا مخالفةٍ للوثيقة.
    -- 🪤 و`Accept-Language` صريحاً: وثيقتُهم «Defaults to `en` if not specified»
    --    — والاعتمادُ على افتراضٍ موثَّقٍ أضعفُ من كتابته.
    WHEN 'zid' THEN jsonb_build_object(
      'Authorization',   'Bearer ' || COALESCE(p_tok->>'authorization', ''),
      'X-Manager-Token', COALESCE(p_tok->>'access_token', ''),
      'Access-Token',    COALESCE(p_tok->>'access_token', ''),
      'Accept',          'application/json',
      'Accept-Language', 'en')
    ELSE jsonb_build_object('Accept', 'application/json') END;
$function$
;


-- ═══ FUNCTION _taki_provider_map(p_provider text) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_provider_map(p_provider text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE lower(COALESCE(p_provider, ''))
    -- سلّة: غلافٌ حول المنتج (مؤكَّد من docs.salla.dev/webhook-events/products.md)
    -- 🪤 و`data.quantity` تُحلّ على `product.created` وحده: الأحداثُ الستّة
    --    الحالية لا تحمل كمّيةً إطلاقاً، فتعود الحمولةُ «غير مفهومة» وتُحفظ
    --    — وهو السلوكُ الصحيح، والرقمُ يُقرأ من `GET /products/quantities`.
    WHEN 'salla' THEN '{"id":"data.id","qty":"data.quantity","source":"salla-docs",
                        "skip_when":[{"path":"data.unlimited_quantity","equals":"true"}]}'::jsonb
    -- زد: المنتجُ في الجذر بلا غلاف (مؤكَّد من مخطّط docs.zid.sa المضمّن)
    -- 🔴 و`skip_when` هو جوهرُ v15.15: جذرُ الكمّية صفرٌ **دائماً** لمنتجٍ له
    --    أصناف، والحقيقةُ في `variants[].stocks[]`. فصفرُ الجذر لا يُكتب.
    WHEN 'zid'   THEN '{"id":"id","qty":"quantity","source":"zid-docs",
                        "skip_when":[{"path":"structure","equals":"parent"},
                                     {"path":"has_options","equals":"true"},
                                     {"path":"is_infinite","equals":"true"},
                                     {"path":"is_external_product","equals":"true"}]}'::jsonb
    ELSE NULL END;
$function$
;


-- ═══ FUNCTION _taki_provider_read(p_provider text) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_provider_read(p_provider text)
 RETURNS jsonb
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE lower(COALESCE(p_provider, ''))
    -- سلّة — https://docs.salla.dev/product/product-details-sku.md
    -- 🪤 و`rpm` هنا **٦٠ لا ١٢٠** عمداً: أدنى باقةٍ موثَّقة ١٢٠/دقيقة، لكنّ
    --    وثيقةَ سلّة **لا تقول** هل الحصّة لكلّ تطبيقٍ أم مشتركةٌ بين كلّ
    --    تطبيقات المتجر (زد تقول «per application per store» صراحةً وسلّة لا).
    --    ⇒ يُفترض الأسوأ: نصفُ الأدنى. وتاجرٌ يستعمل تطبيقاتٍ أخرى لا يتعطّل
    --      بسببنا.
    WHEN 'salla' THEN jsonb_build_object(
      'shape',  'salla',
      'base',   'https://api.salla.dev/admin/v2',
      'path',   '/products/sku/{id}',
      'rpm',    60,
      'doc',    'https://docs.salla.dev/product/product-details-sku.md',
      'rate_doc','https://docs.salla.dev/rate-limiting.md')
    -- زد — https://docs.zid.sa/list-product-stocks.md
    -- 🪤 و٦٠/دقيقة **أرضيّةٌ لا عقد**: «can be configured by Zid, so treat
    --    60/60s as a floor, not a contract». ⇒ نصيبُنا ٤٠٪ منها لا أكثر.
    WHEN 'zid' THEN jsonb_build_object(
      'shape',  'zid',
      'base',   'https://api.zid.sa',
      'path',   '/v1/products/{id}/stocks/',
      'rpm',    60,
      'doc',    'https://docs.zid.sa/list-product-stocks.md',
      'rate_doc','https://docs.zid.sa/rate-limiting-644369m0.md')
    ELSE NULL END;
$function$
;


-- ═══ FUNCTION _taki_rebuild_deal_branches(p_deal_id text) DEFINER owner=postgres search_path=search_path=public, pg_catalog anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_rebuild_deal_branches(p_deal_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE d public.deals%ROWTYPE;
BEGIN
  DELETE FROM public.deal_branches WHERE deal_id = p_deal_id;
  SELECT * INTO d FROM public.deals WHERE id = p_deal_id;
  IF NOT FOUND OR d.status = 'deleted' THEN RETURN; END IF;

  IF jsonb_typeof(d.locations) = 'array' AND jsonb_array_length(d.locations) > 1 THEN
    INSERT INTO public.deal_branches (deal_id, branch_id, lat, lng, location_id, branch_name, region, city, quantity)
    SELECT d.id,
           COALESCE(NULLIF(e->>'id',''), 'b' || ord::text),
           COALESCE(kn.lat, NULLIF(e->>'lat','')::double precision),
           COALESCE(kn.lng, NULLIF(e->>'lng','')::double precision),
           NULLIF(e->>'locationId',''),
           COALESCE(NULLIF(e->>'name',''), kn.name, ''),
           COALESCE(NULLIF(e->>'region',''), c.region_id, d.region),
           COALESCE(NULLIF(e->>'city',''),   kn.city_id,  d.city),
           CASE WHEN d.loc_qty_mode = 'per_location'
                THEN NULLIF(e->>'quantity','')::integer ELSE NULL END
    FROM jsonb_array_elements(d.locations) WITH ORDINALITY AS t(e, ord)
    LEFT JOIN public.locations kn ON kn.id = NULLIF(e->>'locationId','')
    LEFT JOIN public.cities    c  ON c.id  = kn.city_id
    ON CONFLICT (deal_id, branch_id) DO NOTHING;
  ELSE
    INSERT INTO public.deal_branches (deal_id, branch_id, lat, lng, location_id, branch_name, region, city, quantity)
    SELECT d.id, 'primary',
           COALESCE(kn.lat, d.map_lat),
           COALESCE(kn.lng, d.map_lng),
           d.location_id,
           COALESCE(kn.name, d.custom_location_name, ''),
           d.region, d.city, NULL
    FROM (SELECT 1) z
    LEFT JOIN public.locations kn ON kn.id = d.location_id;
  END IF;
END
$function$
;


-- ═══ FUNCTION _taki_set_off(p_deal_id text, p_on boolean, p_variant_id text, p_location_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_set_off(p_deal_id text, p_on boolean, p_variant_id text, p_location_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_on boolean := COALESCE(p_on, false); v_new jsonb;
BEGIN
  -- (أ) العرضُ كلُّه
  IF p_variant_id IS NULL AND p_location_id IS NULL THEN
    UPDATE public.deals SET sold_out = v_on WHERE id = p_deal_id;
    RETURN jsonb_build_object('ok', true, 'level', 'deal', 'off', v_on);
  END IF;

  -- (ب) صنفٌ في كلّ الفروع
  IF p_variant_id IS NOT NULL AND p_location_id IS NULL THEN
    UPDATE public.deals d SET variants = (
      SELECT jsonb_agg(CASE WHEN e->>'id' = p_variant_id
                            THEN jsonb_set(e, '{off}', to_jsonb(v_on), true) ELSE e END ORDER BY t.ord)
        FROM jsonb_array_elements(d.variants) WITH ORDINALITY AS t(e, ord))
     WHERE d.id = p_deal_id AND d.variants IS NOT NULL AND jsonb_typeof(d.variants) = 'array';
    RETURN jsonb_build_object('ok', true, 'level', 'variant', 'off', v_on);
  END IF;

  -- (ج) فرعٌ كاملاً، أو (د) صنفٌ داخل فرع
  UPDATE public.deals d SET locations = (
    SELECT jsonb_agg(CASE WHEN e->>'id' <> p_location_id THEN e
                          WHEN p_variant_id IS NULL THEN jsonb_set(e, '{off}', to_jsonb(v_on), true)
                          -- 🔴 v15.34 — نفسُ سهو المسار المركّب: `variantOff` غائبٌ عن
                          -- كلّ عنصرٍ في الإنتاج (صفرٌ من خمسة)، فكان زرُّ «نفد هذا النوع
                          -- في هذا الفرع» يُرجع ok:true ولا يكتب شيئاً **منذ v15.07**.
                          ELSE jsonb_set(CASE WHEN e ? 'variantOff' THEN e
                                              ELSE jsonb_set(e, '{variantOff}', '{}'::jsonb, true) END,
                                         ARRAY['variantOff', p_variant_id], to_jsonb(v_on), true)
                     END ORDER BY t.ord)
      FROM jsonb_array_elements(d.locations) WITH ORDINALITY AS t(e, ord))
   WHERE d.id = p_deal_id AND d.locations IS NOT NULL AND jsonb_typeof(d.locations) = 'array';
  RETURN jsonb_build_object('ok', true,
    'level', CASE WHEN p_variant_id IS NULL THEN 'location' ELSE 'variant_at_location' END, 'off', v_on);
END
$function$
;


-- ═══ FUNCTION _taki_stock_app(p_provider text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_stock_app(p_provider text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v text;
BEGIN
  SELECT value INTO v FROM public.app_secrets
   WHERE key = 'stock_' || lower(COALESCE(p_provider,'')) || '_app';
  IF v IS NULL OR btrim(v) = '' THEN RETURN NULL; END IF;
  RETURN v::jsonb;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END
$function$
;


-- ═══ FUNCTION _taki_stock_apply(p_integration_id uuid, p_items jsonb, p_observed_at timestamp with time zone, p_event_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_stock_apply(p_integration_id uuid, p_items jsonb, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_event_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_i     public.stock_integrations%ROWTYPE;
  v_at    timestamptz := COALESCE(p_observed_at, now());
  v_it    jsonb;
  v_link  public.stock_links%ROWTYPE;
  v_ok    int := 0; v_skip int := 0;
  v_unmatched jsonb := '[]'::jsonb;
  v_skipwhy   jsonb := '[]'::jsonb;   -- v15.16 skip: لماذا لم يُكتب
  v_res   jsonb;
  v_n     int;
BEGIN
  SELECT * INTO v_i FROM public.stock_integrations
   WHERE id = p_integration_id AND is_enabled AND direction IN ('in','both');
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'UNKNOWN_KEY'); END IF;

  IF p_event_id IS NULL OR btrim(p_event_id) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'EVENT_ID_REQUIRED',
      'hint', 'send a unique id per push so a retry cannot apply twice');
  END IF;
  BEGIN
    INSERT INTO public.stock_inbox (integration_id, event_id) VALUES (v_i.id, btrim(p_event_id));
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('ok', true, 'duplicate', true, 'event_id', p_event_id);
  END;

  IF p_items IS NULL OR jsonb_typeof(p_items) <> 'array' OR jsonb_array_length(p_items) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ITEMS_REQUIRED');
  END IF;
  IF jsonb_array_length(p_items) > 500 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOO_MANY_ITEMS', 'max', 500);
  END IF;

  FOR v_it IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    SELECT * INTO v_link FROM public.stock_links
     WHERE integration_id = v_i.id AND external_id = v_it->>'external_id';
    IF NOT FOUND THEN
      v_unmatched := v_unmatched || to_jsonb(COALESCE(v_it->>'external_id',''));
      CONTINUE;
    END IF;
    -- v15.20 item 2 — رقمٌ عشريٌّ أو نصٌّ كان يرفع استثناءً فيُجهض الدفعةَ
    --   كلَّها بـ٥٠٠. ونظامٌ يبيع بالوزن يرسل 1.5 — وهو قطاعٌ مُعلَنٌ مدعوماً.
    BEGIN
      v_n := NULLIF(btrim(COALESCE(v_it->>'on_hand','')), '')::int;
    EXCEPTION WHEN OTHERS THEN
      v_n := NULL;
      v_skipwhy := v_skipwhy || to_jsonb('QTY_NOT_AN_INTEGER'::text);
      v_skip := v_skip + 1; CONTINUE;
    END;
    IF v_n IS NULL OR v_n < 0 THEN
      v_skip := v_skip + 1;
      v_skipwhy := v_skipwhy || to_jsonb(CASE WHEN v_n IS NULL THEN 'QTY_MISSING' ELSE 'QTY_NEGATIVE' END::text);
      CONTINUE;
    END IF;
    -- v15.20 item 4 — محورُ الربط يجب أن يوجد في العرض فعلاً: رابطٌ على
    --   صنفٍ في عرضٍ بلا أصناف يتجاهله `taki_set_on_hand` بصمتٍ ويردّ
    --   `ok:true` — فيُعَدّ تطبيقاً والرقمُ لم يتحرّك.
    IF v_link.variant_id IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.deals d, jsonb_array_elements(COALESCE(d.variants,'[]'::jsonb)) e
          WHERE d.id = v_link.deal_id AND e->>'id' = v_link.variant_id) THEN
      v_skip := v_skip + 1;
      v_skipwhy := v_skipwhy || to_jsonb('LINK_VARIANT_MISSING'::text);
      CONTINUE;
    END IF;
    IF v_link.location_id IS NOT NULL AND NOT EXISTS (
         SELECT 1 FROM public.deals d, jsonb_array_elements(COALESCE(d.locations,'[]'::jsonb)) e
          WHERE d.id = v_link.deal_id AND e->>'id' = v_link.location_id) THEN
      v_skip := v_skip + 1;
      v_skipwhy := v_skipwhy || to_jsonb('LINK_LOCATION_MISSING'::text);
      CONTINUE;
    END IF;

    v_res := public.taki_set_on_hand(
      v_link.deal_id,
      CASE WHEN v_link.variant_id IS NULL AND v_link.location_id IS NULL THEN v_n ELSE NULL END,
      CASE WHEN v_link.variant_id IS NOT NULL AND v_link.location_id IS NULL
           THEN jsonb_build_array(jsonb_build_object('id', v_link.variant_id, 'onHand', v_n)) END,
      CASE WHEN v_link.location_id IS NOT NULL THEN jsonb_build_array(
             CASE WHEN v_link.variant_id IS NULL
                  THEN jsonb_build_object('id', v_link.location_id, 'onHand', v_n)
                  ELSE jsonb_build_object('id', v_link.location_id,
                         'variantOnHand', jsonb_build_object(v_link.variant_id, v_n)) END) END,
      v_at, 'sync');
    -- v15.16 skip — `taki_set_on_hand` تُرجع `ok:true` مع `skipped` ولا تكتب
    --   شيئاً (UNLIMITED · STALE_OBSERVATION). وعدُّها تطبيقاً كان يجعل
    --   الشاشة تقول «فُهمت وطُبّقت» والرقمُ لم يتحرّك.
    -- 🔴 ويُنقل هذا الإصلاحُ هنا **عمداً ومقيساً**: الاستخراجُ من نصٍّ قديم
    --    كان سيُرجع العيب، والحارسُ في أعلى الملفّ هو الذي كشفه.
    IF COALESCE((v_res->>'ok')::boolean, false)
       AND COALESCE(v_res->>'skipped', '') = '' THEN
      v_ok := v_ok + 1;
    ELSE
      v_skip := v_skip + 1;
      v_skipwhy := v_skipwhy || to_jsonb(COALESCE(NULLIF(v_res->>'skipped', ''),
                                                  NULLIF(v_res->>'error', ''), 'FAILED'));
    END IF;
  END LOOP;

  UPDATE public.stock_integrations SET last_seen_at = now() WHERE id = v_i.id;
  RETURN jsonb_build_object('ok', true, 'applied', v_ok, 'skipped', v_skip,
                            'skip_reasons', v_skipwhy,
                            'unmatched', v_unmatched, 'observed_at', v_at);
END
$function$
;


-- ═══ FUNCTION _taki_stock_enqueue(p_integration_id uuid, p_external_id text, p_reason text, p_signal_event text, p_debounce_seconds integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_stock_enqueue(p_integration_id uuid, p_external_id text, p_reason text, p_signal_event text DEFAULT NULL::text, p_debounce_seconds integer DEFAULT 10)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_store text; v_id bigint; v_due timestamptz;
BEGIN
  SELECT store_id INTO v_store FROM public.stock_integrations WHERE id = p_integration_id;
  IF v_store IS NULL THEN RETURN NULL; END IF;
  v_due := now() + make_interval(secs => GREATEST(COALESCE(p_debounce_seconds, 10), 0));
  INSERT INTO public.stock_refresh_queue
    (integration_id, store_id, external_id, reason, signal_event, due_at)
  VALUES (p_integration_id, v_store, NULLIF(btrim(COALESCE(p_external_id,'')),''),
          p_reason, NULLIF(btrim(COALESCE(p_signal_event,'')),''), v_due)
  ON CONFLICT (integration_id, COALESCE(external_id, '*')) WHERE status = 'pending'
  DO UPDATE SET
    -- الأقربُ يفوز: إشارةٌ جديدةٌ لا تُؤخّر قراءةً كانت أوشكت.
    due_at       = LEAST(stock_refresh_queue.due_at, EXCLUDED.due_at),
    signal_event = COALESCE(EXCLUDED.signal_event, stock_refresh_queue.signal_event)
  RETURNING id INTO v_id;
  RETURN v_id;
END
$function$
;


-- ═══ FUNCTION _taki_stock_event(p_deal_id text, p_variant_id text, p_location_id text, p_reason text, p_delta integer, p_on_hand_after integer, p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_stock_event(p_deal_id text, p_variant_id text, p_location_id text, p_reason text, p_delta integer, p_on_hand_after integer, p_barcode text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_store text;
BEGIN
  SELECT store_id INTO v_store FROM public.deals WHERE id = p_deal_id;
  IF v_store IS NULL THEN RETURN; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.stock_integrations
                  WHERE store_id = v_store AND is_enabled
                    AND direction IN ('out','both') AND webhook_url IS NOT NULL) THEN
    RETURN;
  END IF;
  INSERT INTO public.stock_events
    (store_id, deal_id, variant_id, location_id, reason, delta, on_hand_after, barcode)
  VALUES (v_store, p_deal_id, p_variant_id, p_location_id, p_reason, p_delta, p_on_hand_after, p_barcode);
END
$function$
;


-- ═══ FUNCTION _taki_stock_parse_read(p_provider text, p_body jsonb, p_external_id text, p_location_id text) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_stock_parse_read(p_provider text, p_body jsonb, p_external_id text, p_location_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sh  text := lower(COALESCE(public._taki_provider_read(p_provider)->>'shape', ''));
  v_r   jsonb;
  v_q   bigint := NULL;
  v_any boolean := false;
BEGIN
  IF p_body IS NULL OR jsonb_typeof(p_body) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'BODY_NOT_OBJECT');
  END IF;

  -- ╭─ سلّة ──────────────────────────────────────────────────────────────╮
  IF v_sh = 'salla' THEN
    IF jsonb_typeof(COALESCE(p_body->'data', 'null'::jsonb)) <> 'object' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'NO_DATA');
    END IF;
    -- الصنفُ أوّلاً: سطرٌ في `data.skus[]` يحمل نفس الـSKU المربوط
    FOR v_r IN SELECT * FROM jsonb_array_elements(
                 CASE WHEN jsonb_typeof(COALESCE(p_body->'data'->'skus','null'::jsonb)) = 'array'
                      THEN p_body->'data'->'skus' ELSE '[]'::jsonb END) LOOP
      IF COALESCE(v_r->>'sku', '') = p_external_id THEN
        IF lower(COALESCE(v_r->>'unlimited_quantity', '')) IN ('true', '1') THEN
          RETURN jsonb_build_object('ok', false, 'reason', 'UNLIMITED');
        END IF;
        IF COALESCE(v_r->>'stock_quantity', '') ~ '^[0-9]+$' THEN
          RETURN jsonb_build_object('ok', true, 'on_hand', (v_r->>'stock_quantity')::int,
                                    'level', 'variant');
        END IF;
        RETURN jsonb_build_object('ok', false, 'reason', 'QTY_NOT_A_NUMBER');
      END IF;
    END LOOP;
    -- وإلّا فالمنتجُ كلُّه
    IF lower(COALESCE(p_body->'data'->>'unlimited_quantity', '')) IN ('true', '1') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'UNLIMITED');
    END IF;
    IF COALESCE(p_body->'data'->>'quantity', '') ~ '^[0-9]+$' THEN
      RETURN jsonb_build_object('ok', true, 'on_hand', (p_body->'data'->>'quantity')::int,
                                'level', 'product');
    END IF;
    RETURN jsonb_build_object('ok', false, 'reason', 'QTY_NOT_A_NUMBER');
  END IF;

  -- ╭─ زد ───────────────────────────────────────────────────────────────╮
  IF v_sh = 'zid' THEN
    IF jsonb_typeof(COALESCE(p_body->'results', 'null'::jsonb)) <> 'array' THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'NO_RESULTS');
    END IF;
    FOR v_r IN SELECT * FROM jsonb_array_elements(p_body->'results') LOOP
      -- فرعٌ بعينه إن كان السطرُ مربوطاً بفرع، وإلّا فكلُّ الفروع
      CONTINUE WHEN p_location_id IS NOT NULL
                AND COALESCE(v_r->'location'->>'id', '') <> p_location_id;
      -- 🔴 «بلا حدّ» يُسقط السطرَ كلَّه ولا يُجمع صفراً: `available_quantity`
      --    تأتي `null` مع `is_infinite: true` في مثال وثيقتهم نفسه.
      IF lower(COALESCE(v_r->>'is_infinite', '')) IN ('true', '1') THEN
        RETURN jsonb_build_object('ok', false, 'reason', 'UNLIMITED');
      END IF;
      IF COALESCE(v_r->>'available_quantity', '') ~ '^[0-9]+$' THEN
        v_q := COALESCE(v_q, 0) + (v_r->>'available_quantity')::bigint;
        v_any := true;
      END IF;
    END LOOP;
    IF NOT v_any THEN
      RETURN jsonb_build_object('ok', false, 'reason',
        CASE WHEN p_location_id IS NULL THEN 'NO_USABLE_RECORD' ELSE 'LOCATION_NOT_FOUND' END);
    END IF;
    -- 🪤 سقفٌ عاقل: `taki_set_on_hand` ترفض السالب، ولا شيءَ يرفض رقماً خرافياً.
    IF v_q > 1000000 THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'QTY_ABSURD', 'got', v_q);
    END IF;
    RETURN jsonb_build_object('ok', true, 'on_hand', v_q::int,
      'level', CASE WHEN p_location_id IS NULL THEN 'all_locations' ELSE 'location' END);
  END IF;

  RETURN jsonb_build_object('ok', false, 'reason', 'NO_SHAPE');
END
$function$
;


-- ═══ FUNCTION _taki_stock_renew_at(p_provider text, p_tok jsonb) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_stock_renew_at(p_provider text, p_tok jsonb)
 RETURNS timestamp with time zone
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT CASE
    -- بلا رمزِ تحديثٍ لا تجديدَ ممكن (وتُوسَم حالتُه في مكانٍ آخر)
    WHEN COALESCE(btrim(COALESCE(p_tok->>'refresh_token','')), '') = '' THEN NULL
    -- 🔴 سلّة: التوكنُ ١٤ يوماً ورمزُ التحديث شهر ⇒ الحاكمُ هو التوكن.
    --    (docs.salla.dev/authorization.md: «Access tokens expire after 2 weeks
    --     (14 days)» و«A refresh token lasts for 1 month»)
    WHEN lower(COALESCE(p_provider,'')) = 'salla' THEN now() + interval '11 days'
    -- 🔴 زد: التوكنُ ثلاثُ سنوات ورمزُ التحديث **سنةٌ واحدة** ⇒ الحاكمُ هو
    --    الرمز. (docs.zid.sa/oauth-troubleshooting.md: «The refresh token
    --    lasts 1 year while the access token lasts 3»)
    WHEN lower(COALESCE(p_provider,'')) = 'zid'   THEN now() + interval '10 months'
    -- ومزوّدٌ مجهولُ العمر: شهرٌ احتياطاً، فأقصرُ الأعمار المعروفة شهر.
    ELSE now() + interval '25 days' END;
$function$
;


-- ═══ FUNCTION _taki_stock_token(p_integration_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_stock_token(p_integration_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_json text; v_t jsonb;
BEGIN
  SELECT s.decrypted_secret INTO v_json
    FROM vault.decrypted_secrets s
   WHERE s.name = 'stock_tok:' || p_integration_id::text;
  IF v_json IS NULL OR btrim(v_json) = '' THEN RETURN NULL; END IF;
  BEGIN
    v_t := v_json::jsonb;
  EXCEPTION WHEN OTHERS THEN
    -- 🪤 سرٌّ مشوّهٌ ليس توكناً: يُعاد NULL فيُقال «غير متّصل»، ولا يُنفَّذ
    --    نداءٌ بترويسةٍ فارغة (٤٠١ تُحسب فشلاً وتُقرّب دائرةَ زد القاطعة).
    RETURN NULL;
  END;
  IF COALESCE(btrim(v_t->>'access_token'), '') = '' THEN RETURN NULL; END IF;
  RETURN v_t;
END
$function$
;


-- ═══ FUNCTION _taki_stock_token_expiry(p_tok jsonb) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_stock_token_expiry(p_tok jsonb)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 IMMUTABLE
AS $function$
DECLARE v numeric;
BEGIN
  v := NULLIF(btrim(COALESCE(p_tok->>'expires_in', '')), '')::numeric;
  IF v IS NOT NULL AND v > 0 THEN RETURN now() + make_interval(secs => v::int); END IF;
  v := NULLIF(btrim(COALESCE(p_tok->>'expires', '')), '')::numeric;
  IF v IS NULL OR v <= 0 THEN RETURN NULL; END IF;
  IF v > 1000000000 THEN RETURN to_timestamp(v); END IF;
  RETURN now() + make_interval(secs => v::int);
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END
$function$
;


-- ═══ FUNCTION _taki_stock_token_set(p_integration_id uuid, p_tok jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_stock_token_set(p_integration_id uuid, p_tok jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_name text := 'stock_tok:' || p_integration_id::text; v_id uuid; v_back jsonb;
BEGIN
  IF p_tok IS NULL OR COALESCE(btrim(p_tok->>'access_token'), '') = '' THEN RETURN false; END IF;
  SELECT id INTO v_id FROM vault.secrets WHERE name = v_name;
  IF v_id IS NULL THEN
    PERFORM vault.create_secret(p_tok::text, v_name, 'TAKI stock integration token');
  ELSE
    PERFORM vault.update_secret(v_id, p_tok::text, v_name, 'TAKI stock integration token');
  END IF;
  -- 🔴 تُثبَت بقراءة: `vault.update_secret` على مؤشّرٍ ميت تكتب صفرَ صفوفٍ
  --    بلا أيّ استثناء — فحفظٌ بلا قراءةٍ بعده **وهم** (درسٌ مدفوع في v14.44).
  v_back := public._taki_stock_token(p_integration_id);
  RETURN v_back IS NOT NULL
     AND COALESCE(v_back->>'access_token','') = COALESCE(p_tok->>'access_token','');
END
$function$
;


-- ═══ FUNCTION _taki_sub_payment_ok(p_uid text, p_package_id integer, p_net numeric) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_sub_payment_ok(p_uid text, p_package_id integer, p_net numeric)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(p_net, 0) <= 0 OR EXISTS (
    SELECT 1 FROM public.subscription_payments sp
     WHERE sp.merchant_id = p_uid
       AND sp.status = 'paid'
       -- 🔴 مرجعُ البوّابة شرطٌ لا تجميل: الدفعاتُ التي تكتبها الواجهةُ بعد
       --    المحاكاة تأتي **بلا مرجع**، فهي لا تُمرّر هذا الشرط أبداً.
       AND COALESCE(sp.gateway_reference, '') <> ''
       AND sp.amount >= p_net
       AND sp.created_at > now() - interval '2 hours');
$function$
;


-- ═══ FUNCTION _taki_sync_deal_auth_counts() DEFINER owner=postgres search_path=search_path=public, pg_catalog anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_sync_deal_auth_counts()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_deal text := COALESCE(NEW.deal_id, OLD.deal_id);
BEGIN
  -- تحديث جزئي لا يمسّ status، فلا يستفزّ tr_guard_deal_publish.
  UPDATE public.deals d
     SET auth_real_count = (SELECT count(*) FROM public.deal_authenticity_votes v
                             WHERE v.deal_id = v_deal AND v.is_real),
         auth_fake_count = (SELECT count(*) FROM public.deal_authenticity_votes v
                             WHERE v.deal_id = v_deal AND NOT v.is_real)
   WHERE d.id = v_deal;
  RETURN NULL;
END
$function$
;


-- ═══ FUNCTION _taki_sync_deal_bookings_count() DEFINER owner=postgres search_path=search_path=public, pg_catalog anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_sync_deal_bookings_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_deal text := COALESCE(NEW.deal_id, OLD.deal_id);
BEGIN
  IF v_deal IS NULL THEN RETURN NULL; END IF;
  -- تحديث جزئي لا يمسّ status فلا يستفزّ tr_guard_deal_publish
  UPDATE public.deals d
     SET bookings_count = (SELECT count(*) FROM public.bookings b
                            WHERE b.deal_id = v_deal AND b.status <> 'cancelled')
   WHERE d.id = v_deal;
  RETURN NULL;
END
$function$
;


-- ═══ FUNCTION _taki_sync_deal_rating_stats() DEFINER owner=postgres search_path=search_path=public, pg_catalog anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_sync_deal_rating_stats()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE v_deal text := COALESCE(NEW.deal_id, OLD.deal_id);
BEGIN
  UPDATE public.deals d
     SET rating_avg   = COALESCE(s.avg_score, 0),
         rating_count = COALESCE(s.n, 0)
    FROM (SELECT round(avg(r.score)::numeric, 2) AS avg_score, count(*) AS n
            FROM public.ratings r
           WHERE r.deal_id = v_deal AND r.deleted_at IS NULL) s
   WHERE d.id = v_deal;
  RETURN NULL;
END
$function$
;


-- ═══ FUNCTION _taki_urlenc(p text) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_urlenc(p text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  SELECT COALESCE(string_agg(
    CASE WHEN c ~ '^[A-Za-z0-9._~-]$' THEN c
         ELSE (SELECT string_agg('%' || upper(substring(h FROM n FOR 2)), '' ORDER BY n)
                 FROM (SELECT encode(convert_to(c, 'UTF8'), 'hex') AS h) e,
                      generate_series(1, length(e.h), 2) AS n)
    END, '' ORDER BY i), '')
    FROM regexp_split_to_table(COALESCE(p, ''), '') WITH ORDINALITY AS t(c, i);
$function$
;


-- ═══ FUNCTION _taki_user_is_admin(p_user_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_user_is_admin(p_user_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$ SELECT EXISTS (SELECT 1 FROM users WHERE id = p_user_id AND user_type = 'admin'); $function$
;


-- ═══ FUNCTION _taki_wathq_cfg() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_wathq_cfg()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'env', c.env,
    'base', CASE c.env
              WHEN 'sandbox' THEN 'https://api.wathq.sa/sandbox/commercial-registration'
              ELSE                'https://api.wathq.sa/commercial-registration'
            END,
    'check_owners', c.check_owners,
    'convert_cr',   c.convert_cr,
    'monthly_cap_sar', c.monthly_cap_sar,
    -- 🪤 السقفُ المحليّ ١/ثانية لا ٥: سقفُهم ٥/ثانية، والنبضةُ كلَّ دقيقة
    --    فـ٦٠ نداءً في النبضة تبقى تحت الخُمس. التوفيرُ هنا ليس بخلاً بل
    --    فسحةٌ لأن السقفَ مشتركٌ مع أيّ نداءٍ آخر للمنصّة.
    'per_run_cap', 60,
    'endpoints', jsonb_build_object(
      'status', jsonb_build_object(
        'path', '/status/{id}', 'price', 0.00,
        'query', 'includeDates=true&language=ar'),
      'crnational', jsonb_build_object(
        'path', '/crNationalNumber/{id}', 'price', 2.00, 'query', ''),
      'owners', jsonb_build_object(
        'path', '/owners/{id}', 'price', 5.00, 'query', 'language=ar')
    ))
  FROM public.wathq_config c WHERE c.id;
$function$
;


-- ═══ FUNCTION _taki_wathq_enqueue(p_ver_id text, p_kind text, p_arg text, p_due timestamp with time zone) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_wathq_enqueue(p_ver_id text, p_kind text, p_arg text, p_due timestamp with time zone DEFAULT now())
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id bigint;
BEGIN
  IF p_arg IS NULL OR btrim(p_arg) = '' THEN RETURN NULL; END IF;
  INSERT INTO public.store_verification_checks (ver_id, kind, arg, due_at)
  VALUES (p_ver_id, p_kind, btrim(p_arg), p_due)
  ON CONFLICT (ver_id, kind, arg) WHERE status IN ('pending', 'awaiting')
  DO UPDATE SET due_at = LEAST(store_verification_checks.due_at, EXCLUDED.due_at)
  RETURNING id INTO v_id;
  RETURN v_id;
END
$function$
;


-- ═══ FUNCTION _taki_wathq_key() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public._taki_wathq_key()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT s.decrypted_secret FROM vault.decrypted_secrets s
   WHERE s.name = 'app_secret:wathq_api_key' LIMIT 1;
$function$
;


-- ═══ FUNCTION _taki_wathq_parse_crnational(p_body jsonb) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_wathq_parse_crnational(p_body jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v text;
BEGIN
  IF p_body IS NULL THEN RETURN NULL; END IF;
  -- الردُّ قد يكون كائناً بمفتاحٍ أو نصّاً مجرّداً — كلاهما يُقبل.
  IF jsonb_typeof(p_body) = 'string' THEN
    v := p_body #>> '{}';
  ELSE
    v := COALESCE(p_body->>'crNationalNumber', p_body->>'id',
                  p_body->>'nationalNumber', p_body->>'entityNumber');
  END IF;
  IF v IS NULL OR v !~ '^[0-9]{6,15}$' THEN RETURN NULL; END IF;
  RETURN v;
END
$function$
;


-- ═══ FUNCTION _taki_wathq_parse_owners(p_body jsonb) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_wathq_parse_owners(p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_arr jsonb; v_names text[] := '{}'; v_el jsonb; v_n text;
BEGIN
  IF p_body IS NULL THEN RETURN jsonb_build_object('ok', false, 'why', 'NO_BODY'); END IF;

  IF jsonb_typeof(p_body) = 'array' THEN
    v_arr := p_body;
  ELSIF jsonb_typeof(p_body) = 'object' AND jsonb_typeof(p_body->'parties') = 'array' THEN
    v_arr := p_body->'parties';
  ELSIF jsonb_typeof(p_body) = 'object' AND jsonb_typeof(p_body->'owners') = 'array' THEN
    v_arr := p_body->'owners';
  ELSIF jsonb_typeof(p_body) = 'object' THEN
    v_arr := jsonb_build_array(p_body);          -- مثالُهم المفرد
  ELSE
    RETURN jsonb_build_object('ok', false, 'why', 'SHAPE_UNKNOWN');
  END IF;

  FOR v_el IN SELECT * FROM jsonb_array_elements(v_arr) LOOP
    v_n := COALESCE(v_el->>'name', v_el#>>'{identity,name}');
    IF v_n IS NOT NULL AND btrim(v_n) <> '' THEN
      v_names := v_names || btrim(v_n);
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'count', jsonb_array_length(v_arr),
                            'names', to_jsonb(v_names));
END
$function$
;


-- ═══ FUNCTION _taki_wathq_parse_status(p_body jsonb) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_wathq_parse_status(p_body jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sid int; v_name text; v_conf text; v_due date;
BEGIN
  IF p_body IS NULL OR jsonb_typeof(p_body) <> 'object' THEN
    RETURN jsonb_build_object('ok', false, 'why', 'BODY_NOT_OBJECT');
  END IF;

  -- 🪤 المعرّفُ قد يأتي عدداً أو نصّاً حسب المسار — يُقرأ نصّاً ثمّ يُحوَّل.
  BEGIN v_sid := (p_body->>'id')::int; EXCEPTION WHEN OTHERS THEN v_sid := NULL; END;
  v_name := COALESCE(p_body->>'name', p_body->>'nameAr');

  -- التواريخُ كائناتٌ {gregorian, hijri} حين يُطلب includeDates=true.
  -- 🔴 ولا نقرأ الهجريّ إطلاقاً: نسختا الوثيقة تنشران ترتيبين متعاكسين
  --    لنفس الحقل (الإنتاج `1423-07-28` والاختبار `28-07-1423`)، فتحليلُه
  --    تخمينُ ترتيب. والميلاديُّ وحده كافٍ.
  v_conf := COALESCE(p_body#>>'{confirmationDate,gregorian}',
                     p_body#>>'{reactivationDate,gregorian}');
  BEGIN
    IF v_conf IS NOT NULL THEN v_due := (v_conf::date) + interval '1 year'; END IF;
  EXCEPTION WHEN OTHERS THEN v_due := NULL;
  END;

  RETURN jsonb_build_object(
    'ok', v_sid IS NOT NULL,
    'status_id',   v_sid,
    'status_name', v_name,
    'active',      public._taki_wathq_status_ok(v_sid),
    'confirmation_date', v_conf,
    'confirmation_due',  v_due,
    'suspension_date', p_body#>>'{suspensionDate,gregorian}',
    'deletion_date',   p_body#>>'{deletionDate,gregorian}');
END
$function$
;


-- ═══ FUNCTION _taki_wathq_status_ok(p_id integer) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_wathq_status_ok(p_id integer)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$ SELECT p_id = 1; $function$
;


-- ═══ FUNCTION _taki_zone_contains(z store_delivery_zones, p_lat double precision, p_lng double precision) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public._taki_zone_contains(z store_delivery_zones, p_lat double precision, p_lng double precision)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE PARALLEL SAFE
AS $function$
DECLARE a_lat float8; a_lng float8; b_lat float8; b_lng float8;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL THEN RETURN false; END IF;
  IF z.kind = 'circle' THEN
    RETURN public._taki_km(z.center_lat, z.center_lng, p_lat, p_lng) <= z.radius_km;
  ELSIF z.kind = 'rect' THEN
    a_lat := (z.points->0->>0)::float8; a_lng := (z.points->0->>1)::float8;
    b_lat := (z.points->1->>0)::float8; b_lng := (z.points->1->>1)::float8;
    RETURN p_lat BETWEEN least(a_lat, b_lat) AND greatest(a_lat, b_lat)
       AND p_lng BETWEEN least(a_lng, b_lng) AND greatest(a_lng, b_lng);
  ELSE
    RETURN public._taki_point_in_polygon(z.points, p_lat, p_lng);
  END IF;
END
$function$
;


-- ═══ FUNCTION account_exists(p_email text, p_phone text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.account_exists(p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_email_taken boolean := false;
  v_phone_taken boolean := false;
  v_ip          text;
BEGIN
  v_ip := public._taki_client_ip();
  -- v15.79 — بلا شرطٍ (انظر `find_email_by_phone`). ولا دلوَ رقمٍ هنا عن
  -- قصد: `p_phone` تُقرأ **خاماً** (`WHERE phone = p_phone`) فمفتاحٌ على
  -- نصٍّ غيرِ مطبَّعٍ يُنشئ صفَّ عدٍّ لكلّ صيغةِ كتابة — والبديلُ (تطبيعٌ
  -- هنا) يغيّر دلالةَ الفحص. فالحدُّ على العنوان وحده، والبندُ مُسجَّلٌ في
  -- التقرير بوصفه خياراً مؤجَّلاً لا نسياناً.
  PERFORM public.taki_rate_check('acex1m:' || COALESCE(v_ip, 'noip'), 20, 60,
    '⏳ محاولات كثيرة خلال وقت قصير — انتظر دقيقة ثم أعد المحاولة.');
  PERFORM public.taki_rate_check('acex1h:' || COALESCE(v_ip, 'noip'), 200, 3600,
    '⏳ محاولات كثيرة — أعد المحاولة بعد قليل.');

  IF p_email IS NOT NULL AND length(btrim(p_email)) > 0 THEN
    SELECT EXISTS(SELECT 1 FROM public.users WHERE email ILIKE p_email AND deleted_at IS NULL) INTO v_email_taken;
  END IF;
  IF p_phone IS NOT NULL AND length(btrim(p_phone)) > 0 THEN
    SELECT EXISTS(SELECT 1 FROM public.users WHERE phone = p_phone AND deleted_at IS NULL) INTO v_phone_taken;
  END IF;
  RETURN jsonb_build_object('email_taken', v_email_taken, 'phone_taken', v_phone_taken);
END;
$function$
;


-- ═══ FUNCTION acknowledge_booking(p_barcode text, p_merchant_note text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.acknowledge_booking(p_barcode text, p_merchant_note text DEFAULT NULL::text)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    caller text := auth.uid()::text;
    updated public.bookings;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
    END IF;

    UPDATE public.bookings
    SET status = 'acknowledged',
        merchant_note = COALESCE(p_merchant_note, merchant_note)
    WHERE barcode = p_barcode
      AND status = 'pending'
      AND caller = store_id
    RETURNING * INTO updated;

    IF updated.barcode IS NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.bookings
            WHERE barcode = p_barcode AND caller = store_id
        ) THEN
            RAISE EXCEPTION 'الحجز ليس في حالة انتظار' USING ERRCODE = 'P0001';
        ELSE
            RAISE EXCEPTION 'لم يتم العثور على الحجز أو ليست لديك صلاحية' USING ERRCODE = 'P0001', HINT = 'P0002';
        END IF;
    END IF;

    RETURN updated;
END;
$function$
;


-- ═══ FUNCTION adjust_deal_quantity() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.adjust_deal_quantity()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_sel    jsonb;
  v_dir    int;
  v_need   int;
  v_rows   int;
  v_capped boolean;
BEGIN
    v_need := GREATEST(COALESCE(NEW.booked_quantity, 1), 1);

    IF TG_OP = 'INSERT' THEN
        v_dir := -1;
    ELSIF TG_OP = 'UPDATE' AND NEW.status = 'cancelled' AND OLD.status IS DISTINCT FROM 'cancelled' THEN
        v_dir := 1;
    ELSE
        RETURN NEW;
    END IF;

    SELECT NOT COALESCE(d.is_unlimited, false) AND COALESCE(d.initial_quantity, 0) > 0
      INTO v_capped FROM deals d WHERE d.id = NEW.deal_id;

    IF v_dir = -1 THEN
        IF COALESCE(v_capped, false) THEN
            UPDATE deals SET quantity = quantity - v_need
             WHERE id = NEW.deal_id AND quantity >= v_need;
            GET DIAGNOSTICS v_rows = ROW_COUNT;
            IF v_rows = 0 THEN
                RAISE EXCEPTION 'نفدت الكمية — سبقك مشترون آخرون إليها'
                    USING ERRCODE = 'P0001', HINT = 'P0010';
            END IF;
        ELSE
            UPDATE deals SET quantity = GREATEST(0, COALESCE(quantity, 0) - v_need)
             WHERE id = NEW.deal_id AND COALESCE(is_unlimited, false) = FALSE;
        END IF;
    ELSE
        UPDATE deals SET quantity = COALESCE(quantity, 0) + v_need
         WHERE id = NEW.deal_id AND COALESCE(is_unlimited, false) = FALSE;
    END IF;

    IF NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
      FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
        CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
        UPDATE deals d SET variants = (
          SELECT jsonb_agg(
            CASE WHEN e->>'id' = v_sel->>'c' AND (e ? 'qty') AND NULLIF(e->>'qty','') IS NOT NULL
                 THEN jsonb_set(e, '{qty}', to_jsonb(GREATEST(0,
                        (e->>'qty')::int + v_dir * GREATEST(COALESCE((v_sel->>'qty')::int,1),1))))
                 ELSE e END)
          FROM jsonb_array_elements(d.variants) e)
        WHERE d.id = NEW.deal_id
          AND d.variants IS NOT NULL AND jsonb_typeof(d.variants) = 'array'
          AND (v_dir = 1 OR COALESCE((
                SELECT NULLIF(e2->>'qty','')::int FROM jsonb_array_elements(d.variants) e2
                 WHERE e2->>'id' = v_sel->>'c' LIMIT 1), 2147483647)
              >= GREATEST(COALESCE((v_sel->>'qty')::int,1),1));
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_dir = -1 AND v_rows = 0
           AND EXISTS (SELECT 1 FROM deals d2
                        WHERE d2.id = NEW.deal_id
                          AND d2.variants IS NOT NULL
                          AND jsonb_typeof(d2.variants) = 'array') THEN
            RAISE EXCEPTION 'نفدت كمية النوع المختار — سبقك مشترون آخرون إليه'
                USING ERRCODE = 'P0001', HINT = 'P0010';
        END IF;
      END LOOP;
    END IF;

    IF NEW.location_id IS NOT NULL THEN
      UPDATE deals d SET locations = (
        SELECT jsonb_agg(
          CASE WHEN e->>'id' = NEW.location_id AND (e ? 'quantity') AND NULLIF(e->>'quantity','') IS NOT NULL
               THEN jsonb_set(e, '{quantity}', to_jsonb(GREATEST(0,
                      (e->>'quantity')::int + v_dir * v_need)))
               ELSE e END)
        FROM jsonb_array_elements(d.locations) e)
      WHERE d.id = NEW.deal_id
        AND d.loc_qty_mode = 'per_location'
        AND d.locations IS NOT NULL AND jsonb_typeof(d.locations) = 'array'
        AND (v_dir = 1 OR COALESCE((
              SELECT NULLIF(e2->>'quantity','')::int FROM jsonb_array_elements(d.locations) e2
               WHERE e2->>'id' = NEW.location_id LIMIT 1), 2147483647) >= v_need);
      GET DIAGNOSTICS v_rows = ROW_COUNT;
      IF v_dir = -1 AND v_rows = 0
         AND EXISTS (SELECT 1 FROM deals d2
                      WHERE d2.id = NEW.deal_id AND d2.loc_qty_mode = 'per_location'
                        AND d2.locations IS NOT NULL AND jsonb_typeof(d2.locations) = 'array') THEN
          RAISE EXCEPTION 'نفدت كمية هذا الفرع — سبقك مشترون آخرون إليها'
              USING ERRCODE = 'P0001', HINT = 'P0010';
      END IF;
    END IF;

    IF NEW.location_id IS NOT NULL
       AND NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
      FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
        CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
        UPDATE deals d SET locations = (
          SELECT jsonb_agg(
            CASE WHEN e->>'id' = NEW.location_id
                  AND (e ? 'variantQtys')
                  AND ((e->'variantQtys') ? (v_sel->>'c'))
                  AND NULLIF(e->'variantQtys'->>(v_sel->>'c'),'') IS NOT NULL
                 THEN jsonb_set(e, ARRAY['variantQtys', v_sel->>'c'], to_jsonb(GREATEST(0,
                        (e->'variantQtys'->>(v_sel->>'c'))::int + v_dir * GREATEST(COALESCE((v_sel->>'qty')::int,1),1))))
                 ELSE e END)
          FROM jsonb_array_elements(d.locations) e)
        WHERE d.id = NEW.deal_id
          AND d.loc_qty_mode = 'per_location'
          AND d.locations IS NOT NULL AND jsonb_typeof(d.locations) = 'array'
          AND (v_dir = 1 OR COALESCE((
                SELECT NULLIF(e2->'variantQtys'->>(v_sel->>'c'),'')::int
                  FROM jsonb_array_elements(d.locations) e2
                 WHERE e2->>'id' = NEW.location_id AND (e2 ? 'variantQtys') LIMIT 1), 2147483647)
              >= GREATEST(COALESCE((v_sel->>'qty')::int,1),1));
        GET DIAGNOSTICS v_rows = ROW_COUNT;
        IF v_dir = -1 AND v_rows = 0
           AND EXISTS (SELECT 1 FROM deals d2
                        WHERE d2.id = NEW.deal_id AND d2.loc_qty_mode = 'per_location'
                          AND d2.locations IS NOT NULL AND jsonb_typeof(d2.locations) = 'array') THEN
            RAISE EXCEPTION 'نفد هذا النوع في الفرع المختار — سبقك مشترون آخرون إليه'
                USING ERRCODE = 'P0001', HINT = 'P0010';
        END IF;
      END LOOP;
    END IF;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION admin_activity_heatmap(p_days integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_activity_heatmap(p_days integer DEFAULT 30)
 RETURNS TABLE(dow integer, hour integer, cnt integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT EXTRACT(DOW   FROM created_at AT TIME ZONE 'Asia/Riyadh')::INT,
           EXTRACT(HOUR  FROM created_at AT TIME ZONE 'Asia/Riyadh')::INT,
           COUNT(*)::INT
    FROM activity_log
    WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    GROUP BY 1, 2
    ORDER BY 1, 2;
END;
$function$
;


-- ═══ FUNCTION admin_ai_analyst(p_days integer) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_analyst(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    d int := GREATEST(7, LEAST(365, COALESCE(p_days, 30)));
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 30)))::text || ' days')::interval;
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

    SELECT jsonb_build_object(
      'generated_at', now(),
      'days', d,

      'peak_hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings WHERE created_at >= since GROUP BY 1) t),
      'peak_days', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'n', n) ORDER BY dow), '[]'::jsonb)
        FROM (SELECT extract(dow FROM created_at AT TIME ZONE 'Asia/Riyadh')::int dow, count(*) n
              FROM bookings WHERE created_at >= since GROUP BY 1) t),

      'funnel', (
        SELECT jsonb_build_object(
          'deal_views',  (SELECT count(*) FROM analytics_events WHERE kind='deal_view'  AND created_at >= since),
          'store_views', (SELECT count(*) FROM analytics_events WHERE kind='store_view' AND created_at >= since),
          'bookings',    (SELECT count(*) FROM bookings WHERE created_at >= since),
          'completed',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status='completed'),
          'cancelled',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status IN ('cancelled','canceled','expired'))
        )),

      'monthly', (
        SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.mon), '[]'::jsonb) FROM (
          SELECT to_char(gs, 'YYYY-MM') mon,
            (SELECT count(*) FROM users u WHERE u.user_type='seller' AND u.deleted_at IS NULL AND date_trunc('month', u.created_at AT TIME ZONE 'Asia/Riyadh') = gs) new_sellers,
            (SELECT count(*) FROM users u WHERE u.user_type='buyer'  AND u.deleted_at IS NULL AND date_trunc('month', u.created_at AT TIME ZONE 'Asia/Riyadh') = gs) new_buyers,
            (SELECT count(*) FROM bookings b WHERE date_trunc('month', b.created_at AT TIME ZONE 'Asia/Riyadh') = gs) bookings,
            (SELECT COALESCE(sum(p.amount),0) FROM subscription_payments p WHERE p.status='paid' AND date_trunc('month', p.paid_at AT TIME ZONE 'Asia/Riyadh') = gs) revenue
          FROM generate_series(date_trunc('month', (now() AT TIME ZONE 'Asia/Riyadh') - interval '5 months'),
                               date_trunc('month', now() AT TIME ZONE 'Asia/Riyadh'), interval '1 month') gs
        ) m),

      'seasonal', (
        SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.mon), '[]'::jsonb) FROM (
          SELECT to_char(date_trunc('month', b.created_at AT TIME ZONE 'Asia/Riyadh'), 'YYYY-MM') mon, count(*) bookings
          FROM bookings b WHERE b.created_at >= now() - interval '12 months' GROUP BY 1
        ) m),

      'renewals', (
        SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb ORDER BY r.mon), '[]'::jsonb) FROM (
          SELECT to_char(date_trunc('month', p.period_end AT TIME ZONE 'Asia/Riyadh'), 'YYYY-MM') mon,
                 count(*) expired,
                 count(*) FILTER (WHERE EXISTS (
                   SELECT 1 FROM subscription_payments p2
                   WHERE p2.merchant_id = p.merchant_id AND p2.status='paid'
                     AND p2.period_start > p.period_start
                     AND p2.period_start <= p.period_end + interval '21 days'
                 )) renewed
          FROM subscription_payments p
          WHERE p.status='paid' AND p.period_end >= now() - interval '6 months' AND p.period_end <= now()
          GROUP BY 1
        ) r),

      'sellers', (
        SELECT COALESCE(jsonb_agg(row_to_json(s)::jsonb), '[]'::jsonb) FROM (
          SELECT u.id, COALESCE(NULLIF(btrim(u.shop),''), u.name) shop,
                 -- مدينة التاجر = المدينة الأكثر تكراراً في عروضه
                 (SELECT dl.city FROM deals dl WHERE dl.store_id=u.id AND COALESCE(btrim(dl.city),'') <> ''
                   GROUP BY dl.city ORDER BY count(*) DESC LIMIT 1) city,
                 u.created_at, u.last_active_at,
                 sp.subscription_plan plan, sp.subscription_expires_at expires_at,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active') active_deals,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status<>'active') inactive_deals,
                 (SELECT count(*) FROM bookings b WHERE b.store_id=u.id AND b.created_at >= now() - interval '30 days') bookings_30,
                 (SELECT count(*) FROM bookings b WHERE b.store_id=u.id AND b.created_at >= now() - interval '60 days' AND b.created_at < now() - interval '30 days') bookings_prev30,
                 (SELECT count(*) FROM analytics_events e WHERE e.store_id=u.id AND e.kind='deal_view'  AND e.created_at >= now() - interval '30 days') deal_views_30,
                 (SELECT count(*) FROM analytics_events e WHERE e.store_id=u.id AND e.kind='store_view' AND e.created_at >= now() - interval '30 days') store_views_30,
                 (SELECT round(avg(r.score)::numeric, 1) FROM ratings r WHERE r.store_id=u.id AND r.deleted_at IS NULL) rating_avg,
                 (SELECT count(*) FROM ratings r WHERE r.store_id=u.id AND r.deleted_at IS NULL) rating_count,
                 (SELECT dl.category FROM deals dl LEFT JOIN bookings b2 ON b2.deal_id=dl.id
                   WHERE dl.store_id=u.id GROUP BY dl.category
                   ORDER BY count(b2.barcode) DESC NULLS LAST LIMIT 1) top_category,
                 (SELECT round(avg(COALESCE(array_length(dl.images,1),0))::numeric,1)
                   FROM deals dl WHERE dl.store_id=u.id AND dl.status='active') avg_images,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active'
                   AND COALESCE(array_length(dl.images,1),0) <= 1) weak_image_deals,
                 (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active'
                   AND length(COALESCE(dl.description,'')) < 20) weak_desc_deals,
                 COALESCE((u.working_hours->>'enabled')::boolean, false) has_hours
          FROM users u
          LEFT JOIN store_profiles sp ON sp.store_id = u.id
          WHERE u.user_type IN ('seller','admin') AND u.deleted_at IS NULL AND u.is_suspended IS NOT TRUE
            AND (u.user_type='seller' OR COALESCE(NULLIF(btrim(u.shop),''),'') <> '')
        ) s),

      'cities', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 15
        ) c),
      'regions', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.region),''),'غير محدد') region,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 13
        ) c),
      'categories', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') category,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 20
        ) c),
      'malls', (
        SELECT COALESCE(jsonb_agg(row_to_json(m)::jsonb ORDER BY m.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(l.name, dl.custom_location_name, 'غير محدد') mall,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') deals,
                 count(b.barcode) bookings
          FROM deals dl
          LEFT JOIN locations l ON l.id = dl.location_id
          LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= since
          GROUP BY 1 ORDER BY count(b.barcode) DESC LIMIT 12
        ) m),

      -- مدن نشاط المشترين = أين يحجزون فعلاً
      'buyers_by_city', (
        SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.buyers DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city,
                 count(DISTINCT b.user_id) buyers, count(*) bookings
          FROM bookings b JOIN deals dl ON dl.id = b.deal_id
          WHERE b.created_at >= now() - interval '90 days'
          GROUP BY 1 ORDER BY 2 DESC LIMIT 15
        ) t),

      'content', (
        SELECT jsonb_build_object(
          'active_deals', count(*),
          'no_image',  count(*) FILTER (WHERE COALESCE(array_length(images,1),0) = 0),
          'one_image', count(*) FILTER (WHERE COALESCE(array_length(images,1),0) = 1),
          'no_desc',   count(*) FILTER (WHERE length(COALESCE(description,'')) < 20)
        ) FROM deals WHERE status='active'),

      'buyers', (
        SELECT jsonb_build_object(
          'total',      (SELECT count(*) FROM users WHERE user_type='buyer' AND deleted_at IS NULL),
          'active_30',  (SELECT count(DISTINCT b.user_id) FROM bookings b WHERE b.created_at >= now() - interval '30 days'),
          'with_booking', (SELECT count(DISTINCT b.user_id) FROM bookings b),
          'repeaters',  (SELECT count(*) FROM (SELECT b.user_id FROM bookings b GROUP BY b.user_id HAVING count(*) >= 2) t),
          'dormant_30', (SELECT count(*) FROM users u WHERE u.user_type='buyer' AND u.deleted_at IS NULL
                           AND COALESCE(u.last_active_at, u.created_at) < now() - interval '30 days')
        ))
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_ai_custom(p_start text, p_end text, p_hour_from integer, p_hour_to integer, p_dow integer, p_city text, p_category text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_custom(p_start text, p_end text, p_hour_from integer DEFAULT 0, p_hour_to integer DEFAULT 23, p_dow integer DEFAULT NULL::integer, p_city text DEFAULT NULL::text, p_category text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    d1 date := COALESCE(NULLIF(btrim(p_start),'')::date, (now() AT TIME ZONE 'Asia/Riyadh')::date - 30);
    d2 date := COALESCE(NULLIF(btrim(p_end),'')::date,   (now() AT TIME ZONE 'Asia/Riyadh')::date);
    f int := LEAST(23, GREATEST(0, COALESCE(p_hour_from, 0)));
    t int := LEAST(23, GREATEST(0, COALESCE(p_hour_to, 23)));
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    IF d2 < d1 THEN RAISE EXCEPTION 'نهاية الفترة قبل بدايتها'; END IF;
    IF d2 - d1 > 400 THEN d1 := d2 - 400; END IF;

    SELECT jsonb_build_object(
      'start', d1, 'end', d2, 'from', f, 'to', t, 'dow', p_dow, 'city', p_city, 'category', p_category,
      'totals', (
        WITH bw AS (
          SELECT b.*, dl.city dcity, dl.category dcat FROM bookings b
          JOIN deals dl ON dl.id = b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
        ), ew AS (
          SELECT e.* FROM analytics_events e
          LEFT JOIN deals dl ON dl.id = e.deal_id
          WHERE (e.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND CASE WHEN f <= t
                  THEN extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND (p_city IS NULL OR e.kind='search' OR dl.city = p_city)
            AND (p_category IS NULL OR e.kind='search' OR dl.category = p_category)
        ), dw AS (
          SELECT d.id FROM deals d
          WHERE (to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND CASE WHEN f <= t
                  THEN extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND (p_city IS NULL OR d.city = p_city)
            AND (p_category IS NULL OR d.category = p_category)
        )
        SELECT jsonb_build_object(
          'bookings',  (SELECT count(*) FROM bw),
          'completed', (SELECT count(*) FROM bw WHERE status='completed'),
          'cancelled', (SELECT count(*) FROM bw WHERE status='cancelled'),
          'cancel_buyer',  (SELECT count(*) FROM bw WHERE status='cancelled' AND cancelled_by='buyer'),
          'cancel_seller', (SELECT count(*) FROM bw WHERE status='cancelled' AND cancelled_by='seller'),
          'cancel_system', (SELECT count(*) FROM bw WHERE status='cancelled' AND cancelled_by='system'),
          'buyers',    (SELECT count(DISTINCT user_id) FROM bw),
          'sellers',   (SELECT count(DISTINCT store_id) FROM bw),
          'qty',       (SELECT COALESCE(sum(booked_quantity),0) FROM bw),
          'views',     (SELECT count(*) FROM ew WHERE kind IN ('deal_view','store_view')),
          'clicks',    (SELECT count(*) FROM ew WHERE kind='deal_click'),
          'searches',  (SELECT count(*) FROM ew WHERE kind='search'),
          'deals_published', (SELECT count(*) FROM dw)
        )),
      -- منحنى يومي عبر الفترة (لرسم الاتجاه)
      'daily', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('d', d0, 'n', n) ORDER BY d0), '[]'::jsonb) FROM (
          SELECT (b.created_at AT TIME ZONE 'Asia/Riyadh')::date d0, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1) x),
      -- توزيع الساعات داخل الشريحة
      'hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb) FROM (
          SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
          GROUP BY 1) x),
      'top_cities', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_categories', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_malls', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(l.name, dl.custom_location_name, 'غير محدد') name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id LEFT JOIN locations l ON l.id=dl.location_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_stores', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(u.shop),''), u.name) name, count(*) n,
                 count(*) FILTER (WHERE b.status='completed') ok, count(*) FILTER (WHERE b.status='cancelled') bad
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id JOIN users u ON u.id=b.store_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY 1 ORDER BY 2 DESC LIMIT 6) x),
      'top_deals', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT dl.item_name name, dl.shop_name shop, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE (b.created_at AT TIME ZONE 'Asia/Riyadh')::date BETWEEN d1 AND d2
            AND (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
          GROUP BY dl.id, dl.item_name, dl.shop_name ORDER BY count(*) DESC LIMIT 5) x)
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_ai_funnel(p_days integer) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_funnel(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 30)))::text || ' days')::interval;
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      'funnel', (SELECT jsonb_build_object(
        'store_views', (SELECT count(*) FROM analytics_events WHERE kind='store_view' AND created_at >= since),
        'deal_views',  (SELECT count(*) FROM analytics_events WHERE kind='deal_view'  AND created_at >= since),
        'clicks',      (SELECT count(*) FROM analytics_events WHERE kind='deal_click' AND created_at >= since),
        'bookings',    (SELECT count(*) FROM bookings WHERE created_at >= since),
        'completed',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status='completed'),
        'cancelled',   (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled'),
        'cancel_buyer',  (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by='buyer'),
        'cancel_seller', (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by='seller'),
        'cancel_system', (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by='system'),
        'cancel_legacy', (SELECT count(*) FROM bookings WHERE created_at >= since AND status='cancelled' AND cancelled_by IS NULL)
      )),
      'by_city', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city,
                 count(*) bookings,
                 count(*) FILTER (WHERE b.status='completed') completed,
                 count(*) FILTER (WHERE b.status='cancelled') cancelled,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='buyer') c_buyer,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='seller') c_seller,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='system') c_system
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since GROUP BY 1
        ) c),
      'by_category', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') category,
                 count(*) bookings,
                 count(*) FILTER (WHERE b.status='completed') completed,
                 count(*) FILTER (WHERE b.status='cancelled') cancelled,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='buyer') c_buyer,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='seller') c_seller,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='system') c_system
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since GROUP BY 1
        ) c),
      'by_store', (
        SELECT COALESCE(jsonb_agg(row_to_json(s)::jsonb ORDER BY s.cancelled DESC), '[]'::jsonb) FROM (
          SELECT b.store_id, COALESCE(NULLIF(btrim(u.shop),''), u.name) shop,
                 (SELECT dl2.city FROM deals dl2 WHERE dl2.store_id=b.store_id AND COALESCE(btrim(dl2.city),'')<>'' GROUP BY dl2.city ORDER BY count(*) DESC LIMIT 1) city,
                 count(*) bookings,
                 count(*) FILTER (WHERE b.status='completed') completed,
                 count(*) FILTER (WHERE b.status='cancelled') cancelled,
                 count(*) FILTER (WHERE b.status='cancelled' AND b.cancelled_by='seller') c_seller
          FROM bookings b JOIN users u ON u.id=b.store_id
          WHERE b.created_at >= since GROUP BY b.store_id, u.shop, u.name
        ) s),
      -- الاحتفاظ: أفواج المشترين شهرياً — كم عاد وحجز مرة ثانية؟
      'retention', (
        SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb ORDER BY r.cohort), '[]'::jsonb) FROM (
          SELECT to_char(date_trunc('month', f.first_at AT TIME ZONE 'Asia/Riyadh'), 'YYYY-MM') cohort,
                 count(*) buyers,
                 count(*) FILTER (WHERE f.total >= 2) returned
          FROM (SELECT b.user_id, min(b.created_at) first_at, count(*) total
                FROM bookings b GROUP BY b.user_id) f
          GROUP BY 1
        ) r)
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_ai_hours(p_days integer, p_city text, p_category text, p_dow integer) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_hours(p_days integer DEFAULT 30, p_city text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_dow integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 30)))::text || ' days')::interval;
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      'hours', (
        SELECT COALESCE(jsonb_agg(row_to_json(t)::jsonb ORDER BY t.h), '[]'::jsonb) FROM (
          SELECT gs.h,
            COALESCE(b.bookings, 0) bookings,
            COALESCE(b.completed, 0) completed,
            COALESCE(b.cancelled, 0) cancelled,
            COALESCE(b.buyers, 0) buyers,
            COALESCE(b.sellers, 0) sellers,
            COALESCE(e.views, 0) views,
            COALESCE(e.clicks, 0) clicks
          FROM generate_series(0, 23) gs(h)
          LEFT JOIN (
            SELECT extract(hour FROM bk.created_at AT TIME ZONE 'Asia/Riyadh')::int h,
                   count(*) bookings,
                   count(*) FILTER (WHERE bk.status='completed') completed,
                   count(*) FILTER (WHERE bk.status='cancelled') cancelled,
                   count(DISTINCT bk.user_id) buyers,
                   count(DISTINCT bk.store_id) sellers
            FROM bookings bk JOIN deals dl ON dl.id = bk.deal_id
            WHERE bk.created_at >= since
              AND (p_city IS NULL OR dl.city = p_city)
              AND (p_category IS NULL OR dl.category = p_category)
              AND (p_dow IS NULL OR extract(dow FROM bk.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            GROUP BY 1
          ) b ON b.h = gs.h
          LEFT JOIN (
            SELECT extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int h,
                   count(*) FILTER (WHERE e.kind='deal_view') views,
                   count(*) FILTER (WHERE e.kind='deal_click') clicks
            FROM analytics_events e LEFT JOIN deals dl ON dl.id = e.deal_id
            WHERE e.created_at >= since AND e.kind IN ('deal_view','deal_click')
              AND (p_city IS NULL OR dl.city = p_city)
              AND (p_category IS NULL OR dl.category = p_category)
              AND (p_dow IS NULL OR extract(dow FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
            GROUP BY 1
          ) e ON e.h = gs.h
        ) t),
      -- إجماليات الفلتر الحالي (كل الساعات) — المشترون/التجار مميزون فعلياً
      'totals', (
        SELECT jsonb_build_object(
          'bookings', count(*),
          'completed', count(*) FILTER (WHERE bk.status='completed'),
          'cancelled', count(*) FILTER (WHERE bk.status='cancelled'),
          'buyers', count(DISTINCT bk.user_id),
          'sellers', count(DISTINCT bk.store_id)
        )
        FROM bookings bk JOIN deals dl ON dl.id = bk.deal_id
        WHERE bk.created_at >= since
          AND (p_city IS NULL OR dl.city = p_city)
          AND (p_category IS NULL OR dl.category = p_category)
          AND (p_dow IS NULL OR extract(dow FROM bk.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow))
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_ai_hours(p_from integer, p_to integer, p_dow integer, p_days integer) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_hours(p_from integer DEFAULT 0, p_to integer DEFAULT 23, p_dow integer DEFAULT NULL::integer, p_days integer DEFAULT 90)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    since timestamptz := now() - (GREATEST(7, LEAST(365, COALESCE(p_days, 90)))::text || ' days')::interval;
    f int := LEAST(23, GREATEST(0, COALESCE(p_from, 0)));
    t int := LEAST(23, GREATEST(0, COALESCE(p_to, 23)));
    res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

    SELECT jsonb_build_object(
      'from', f, 'to', t, 'dow', p_dow, 'days', GREATEST(7, LEAST(365, COALESCE(p_days, 90))),
      'totals', (
        WITH bw AS (
          SELECT b.* FROM bookings b
          WHERE b.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
        ), ew AS (
          SELECT e.* FROM analytics_events e
          WHERE e.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
        ), dw AS (
          SELECT d.id FROM deals d
          WHERE to_timestamp(d.created_at / 1000.0) >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM to_timestamp(d.created_at / 1000.0) AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
        )
        SELECT jsonb_build_object(
          'bookings',  (SELECT count(*) FROM bw),
          'completed', (SELECT count(*) FROM bw WHERE status='completed'),
          'cancelled', (SELECT count(*) FROM bw WHERE status='cancelled'),
          'buyers',    (SELECT count(DISTINCT user_id) FROM bw),
          'sellers',   (SELECT count(DISTINCT store_id) FROM bw),
          'views',     (SELECT count(*) FROM ew WHERE kind IN ('deal_view','store_view')),
          'clicks',    (SELECT count(*) FROM ew WHERE kind='deal_click'),
          'searches',  (SELECT count(*) FROM ew WHERE kind='search'),
          'deals_published', (SELECT count(*) FROM dw)
        )),
      'top_categories', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.category),''),'other') category, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
          GROUP BY 1 ORDER BY 2 DESC LIMIT 3) x),
      'top_cities', (
        SELECT COALESCE(jsonb_agg(row_to_json(x)::jsonb ORDER BY x.n DESC), '[]'::jsonb) FROM (
          SELECT COALESCE(NULLIF(btrim(dl.city),''),'غير محدد') city, count(*) n
          FROM bookings b JOIN deals dl ON dl.id=b.deal_id
          WHERE b.created_at >= since
            AND CASE WHEN f <= t
                  THEN extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN f AND t
                  ELSE (extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int >= f
                     OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int <= t) END
            AND (p_dow IS NULL OR extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int = p_dow)
          GROUP BY 1 ORDER BY 2 DESC LIMIT 3) x),
      'heatmap', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'h', h, 'n', n)), '[]'::jsonb) FROM (
          SELECT extract(dow  FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int dow,
                 extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h,
                 count(*) n
          FROM bookings b WHERE b.created_at >= since GROUP BY 1, 2) x)
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_ai_matrix(p_city text, p_category text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_matrix(p_city text DEFAULT NULL::text, p_category text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      'city', p_city, 'category', p_category,
      -- حجوزات ٩٠ يوماً حسب الساعة (تاريخ غني منذ انطلاق المنصة)
      'hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings b JOIN deals dl ON dl.id = b.deal_id
              WHERE b.created_at >= now() - interval '90 days'
                AND (p_city IS NULL OR dl.city = p_city)
                AND (p_category IS NULL OR dl.category = p_category)
              GROUP BY 1) t),
      -- مشاهدات/نقرات حسب الساعة (منذ بدء تسجيل الأحداث v12.38)
      'view_hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM analytics_events e JOIN deals dl ON dl.id = e.deal_id
              WHERE e.kind IN ('deal_view','deal_click')
                AND (p_city IS NULL OR dl.city = p_city)
                AND (p_category IS NULL OR dl.category = p_category)
              GROUP BY 1) t),
      'totals', (
        SELECT jsonb_build_object(
          'bookings_30', (SELECT count(*) FROM bookings b JOIN deals dl ON dl.id=b.deal_id
                          WHERE b.created_at >= now() - interval '30 days'
                            AND (p_city IS NULL OR dl.city = p_city)
                            AND (p_category IS NULL OR dl.category = p_category)),
          'views_30', (SELECT count(*) FROM analytics_events e JOIN deals dl ON dl.id=e.deal_id
                       WHERE e.kind='deal_view' AND e.created_at >= now() - interval '30 days'
                         AND (p_city IS NULL OR dl.city = p_city)
                         AND (p_category IS NULL OR dl.category = p_category)),
          'clicks_30', (SELECT count(*) FROM analytics_events e JOIN deals dl ON dl.id=e.deal_id
                        WHERE e.kind='deal_click' AND e.created_at >= now() - interval '30 days'
                          AND (p_city IS NULL OR dl.city = p_city)
                          AND (p_category IS NULL OR dl.category = p_category)),
          'active_deals', (SELECT count(*) FROM deals dl WHERE dl.status='active'
                             AND (p_city IS NULL OR dl.city = p_city)
                             AND (p_category IS NULL OR dl.category = p_category)),
          'stores', (SELECT count(DISTINCT dl.store_id) FROM deals dl WHERE dl.status='active'
                       AND (p_city IS NULL OR dl.city = p_city)
                       AND (p_category IS NULL OR dl.category = p_category))
        )),
      'top_deals', (
        SELECT COALESCE(jsonb_agg(row_to_json(td)::jsonb ORDER BY td.bookings DESC), '[]'::jsonb) FROM (
          SELECT dl.item_name, dl.shop_name, count(b.barcode) bookings, COALESCE(dl.views,0) views
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id AND b.created_at >= now() - interval '90 days'
          WHERE (p_city IS NULL OR dl.city = p_city)
            AND (p_category IS NULL OR dl.category = p_category)
          GROUP BY dl.id, dl.item_name, dl.shop_name, dl.views
          ORDER BY count(b.barcode) DESC LIMIT 5) td)
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_ai_pulse2() DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_pulse2()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT jsonb_build_object(
      -- تفاعل كل قسم: مشاهدات/نقرات/حجوزات ٣٠ يوماً → من يحتاج تخفيضات
      'cat_engagement', (
        SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY (c.views_30 + c.clicks_30) DESC), '[]'::jsonb) FROM (
          SELECT dl.category,
                 count(DISTINCT dl.id) FILTER (WHERE dl.status='active') active_deals,
                 (SELECT count(*) FROM analytics_events e WHERE e.kind='deal_view'
                    AND e.created_at >= now() - interval '30 days'
                    AND e.deal_id IN (SELECT id FROM deals dx WHERE dx.category = dl.category)) views_30,
                 (SELECT count(*) FROM analytics_events e WHERE e.kind='deal_click'
                    AND e.created_at >= now() - interval '30 days'
                    AND e.deal_id IN (SELECT id FROM deals dx WHERE dx.category = dl.category)) clicks_30,
                 (SELECT count(*) FROM bookings b JOIN deals dx ON dx.id=b.deal_id
                    WHERE dx.category = dl.category AND b.created_at >= now() - interval '30 days') bookings_30
          FROM deals dl GROUP BY dl.category
        ) c),
      -- أعلى كلمات البحث ٣٠ يوماً + نطاقها
      'searches', (
        SELECT COALESCE(jsonb_agg(row_to_json(s)::jsonb ORDER BY s.n DESC), '[]'::jsonb) FROM (
          SELECT query q, count(*) n, count(DISTINCT COALESCE(user_id, id::text)) searchers,
                 mode() WITHIN GROUP (ORDER BY source) top_scope
          FROM analytics_events WHERE kind='search' AND created_at >= now() - interval '30 days'
          GROUP BY query ORDER BY count(*) DESC LIMIT 15
        ) s),
      'search_total_30', (SELECT count(*) FROM analytics_events WHERE kind='search' AND created_at >= now() - interval '30 days')
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_ai_seller_competitors(p_store_id text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_seller_competitors(p_store_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_city text; v_cat text; res jsonb;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    SELECT dl.city INTO v_city FROM deals dl
     WHERE dl.store_id = p_store_id AND COALESCE(btrim(dl.city),'') <> ''
     GROUP BY dl.city ORDER BY count(*) DESC LIMIT 1;
    SELECT dl.category INTO v_cat FROM deals dl
      LEFT JOIN bookings b ON b.deal_id = dl.id
     WHERE dl.store_id = p_store_id
     GROUP BY dl.category ORDER BY count(b.barcode) DESC NULLS LAST LIMIT 1;

    SELECT COALESCE(jsonb_agg(row_to_json(c)::jsonb ORDER BY c.bookings_30 DESC), '[]'::jsonb) INTO res FROM (
      SELECT u.id, COALESCE(NULLIF(btrim(u.shop),''), u.name) shop,
             (SELECT count(*) FROM bookings b WHERE b.store_id=u.id AND b.created_at >= now() - interval '30 days') bookings_30,
             (SELECT count(*) FROM deals dl WHERE dl.store_id=u.id AND dl.status='active') active_deals,
             (SELECT round(avg(r.score)::numeric,1) FROM ratings r WHERE r.store_id=u.id AND r.deleted_at IS NULL) rating_avg,
             (SELECT count(*) FROM analytics_events e WHERE e.store_id=u.id AND e.kind IN ('deal_view','store_view')
                AND e.created_at >= now() - interval '30 days') views_30
      FROM users u
      WHERE u.user_type IN ('seller','admin') AND u.deleted_at IS NULL AND u.id <> p_store_id
        AND EXISTS (SELECT 1 FROM deals dx WHERE dx.store_id=u.id
                      AND dx.category IS NOT DISTINCT FROM v_cat
                      AND (v_city IS NULL OR dx.city = v_city))
      ORDER BY 3 DESC LIMIT 3
    ) c;
    RETURN jsonb_build_object('city', v_city, 'category', v_cat, 'competitors', COALESCE(res, '[]'::jsonb));
END $function$
;


-- ═══ FUNCTION admin_ai_seller_report(p_store_id text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_ai_seller_report(p_store_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    res jsonb; v_city text; v_cat text;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

    SELECT dl.city INTO v_city FROM deals dl
     WHERE dl.store_id = p_store_id AND COALESCE(btrim(dl.city),'') <> ''
     GROUP BY dl.city ORDER BY count(*) DESC LIMIT 1;
    SELECT dl.category INTO v_cat FROM deals dl
      LEFT JOIN bookings b ON b.deal_id = dl.id
     WHERE dl.store_id = p_store_id
     GROUP BY dl.category ORDER BY count(b.barcode) DESC NULLS LAST LIMIT 1;

    SELECT jsonb_build_object(
      'store_id', p_store_id,
      'city', v_city,
      'top_category', v_cat,
      'hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings b WHERE b.store_id=p_store_id AND b.created_at >= now() - interval '90 days' GROUP BY 1) t),
      'days', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('dow', dow, 'n', n) ORDER BY dow), '[]'::jsonb)
        FROM (SELECT extract(dow FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int dow, count(*) n
              FROM bookings b WHERE b.store_id=p_store_id AND b.created_at >= now() - interval '90 days' GROUP BY 1) t),
      'weekly', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('w', w, 'n', n) ORDER BY wk), '[]'::jsonb)
        FROM (SELECT date_trunc('week', b.created_at AT TIME ZONE 'Asia/Riyadh') wk,
                     to_char(date_trunc('week', b.created_at AT TIME ZONE 'Asia/Riyadh'), 'MM-DD') w,
                     count(*) n
              FROM bookings b WHERE b.store_id=p_store_id AND b.created_at >= now() - interval '8 weeks'
              GROUP BY 1, 2) t),
      'cat_city_hours', (
        SELECT COALESCE(jsonb_agg(jsonb_build_object('h', h, 'n', n) ORDER BY h), '[]'::jsonb)
        FROM (SELECT extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int h, count(*) n
              FROM bookings b JOIN deals dl ON dl.id = b.deal_id
              WHERE dl.category IS NOT DISTINCT FROM v_cat
                AND (v_city IS NULL OR dl.city = v_city)
                AND b.created_at >= now() - interval '90 days' GROUP BY 1) t),
      'cat_city_avg_bookings_30', (
        SELECT round(avg(cnt)::numeric, 1) FROM (
          SELECT count(b.barcode) cnt
          FROM users u2
          LEFT JOIN bookings b ON b.store_id = u2.id AND b.created_at >= now() - interval '30 days'
          WHERE u2.user_type IN ('seller','admin') AND u2.deleted_at IS NULL AND u2.id <> p_store_id
            AND EXISTS (SELECT 1 FROM deals dx WHERE dx.store_id=u2.id
                          AND dx.category IS NOT DISTINCT FROM v_cat
                          AND (v_city IS NULL OR dx.city = v_city))
          GROUP BY u2.id
        ) t),
      'top_deal', (
        SELECT to_jsonb(td) FROM (
          SELECT dl.item_name, count(b.barcode) bookings, COALESCE(dl.views,0) views
          FROM deals dl LEFT JOIN bookings b ON b.deal_id = dl.id
          WHERE dl.store_id = p_store_id
          GROUP BY dl.id, dl.item_name, dl.views ORDER BY count(b.barcode) DESC LIMIT 1
        ) td),
      'last_booking_at', (SELECT max(b.created_at) FROM bookings b WHERE b.store_id = p_store_id)
    ) INTO res;
    RETURN res;
END $function$
;


-- ═══ FUNCTION admin_apply_subscription(p_store_id text, p_plan text, p_started_at timestamp with time zone, p_expires_at timestamp with time zone, p_discount numeric, p_amount numeric, p_notes text, p_send_notification boolean, p_max_branches integer, p_package_id integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_apply_subscription(p_store_id text, p_plan text, p_started_at timestamp with time zone DEFAULT now(), p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_discount numeric DEFAULT 0, p_amount numeric DEFAULT 199, p_notes text DEFAULT NULL::text, p_send_notification boolean DEFAULT true, p_max_branches integer DEFAULT NULL::integer, p_package_id integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT; v_caller_id TEXT; v_user_name TEXT; v_pkg_id INT; v_max INT;
BEGIN
  PERFORM public._admin_require_ctx();
    v_caller_id := auth.uid()::text;
    SELECT user_type INTO v_caller_role FROM users WHERE id = v_caller_id;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Admin only'; END IF;
    IF p_plan NOT IN ('free','trial','premium') THEN RAISE EXCEPTION 'Invalid plan: %', p_plan; END IF;
    IF p_max_branches IS NOT NULL AND p_max_branches < 1 THEN
        RAISE EXCEPTION 'Invalid package size: %', p_max_branches;
    END IF;

    SELECT name INTO v_user_name FROM users WHERE id = p_store_id;
    IF v_user_name IS NULL THEN RAISE EXCEPTION 'Store not found: %', p_store_id; END IF;

    -- v13.16: معرّف الباقة — إن لم يُمرَّر، استنتجه من عدد المواقع المطلوب
    v_pkg_id := p_package_id;
    IF v_pkg_id IS NULL AND p_max_branches IS NOT NULL THEN
      SELECT (e->>'id')::int INTO v_pkg_id
        FROM jsonb_array_elements(
               (SELECT value FROM platform_settings WHERE key='location_packages')) e
       WHERE (e->>'max')::int = p_max_branches
       ORDER BY (e->>'id')::int LIMIT 1;
    END IF;

    INSERT INTO store_profiles (
        store_id, subscription_plan, subscription_started_at,
        subscription_expires_at, discount_percentage, subscription_amount,
        admin_notes, max_branches, subscription_package_id, updated_at
    ) VALUES (
        p_store_id, p_plan, p_started_at, p_expires_at,
        COALESCE(p_discount, 0), COALESCE(p_amount, 199),
        p_notes, COALESCE(p_max_branches, 3), v_pkg_id, NOW()
    )
    ON CONFLICT (store_id) DO UPDATE SET
        subscription_plan = EXCLUDED.subscription_plan,
        subscription_started_at = EXCLUDED.subscription_started_at,
        subscription_expires_at = EXCLUDED.subscription_expires_at,
        discount_percentage = EXCLUDED.discount_percentage,
        subscription_amount = EXCLUDED.subscription_amount,
        admin_notes = EXCLUDED.admin_notes,
        max_branches = COALESCE(p_max_branches, store_profiles.max_branches, 3),
        subscription_package_id = COALESCE(v_pkg_id, store_profiles.subscription_package_id),
        updated_at = NOW();

    IF p_plan <> 'free' THEN
        UPDATE store_profiles SET subscription_canceled_at = NULL WHERE store_id = p_store_id;
    END IF;

    IF p_send_notification THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type)
        VALUES (
            p_store_id,
            CASE p_plan WHEN 'premium' THEN '🌟 تم تفعيل اشتراكك المميز'
                        WHEN 'trial'   THEN '🎁 لديك فترة تجريبية جديدة'
                        ELSE '✅ تم تحديث اشتراكك' END,
            CASE p_plan WHEN 'premium' THEN '🌟 Premium subscription activated'
                        WHEN 'trial'   THEN '🎁 New trial period granted'
                        ELSE '✅ Subscription updated' END,
            CASE WHEN p_discount > 0
                 THEN 'تم تطبيق خصم ' || p_discount || '٪ على اشتراكك. صالح حتى ' || COALESCE(to_char(p_expires_at, 'YYYY-MM-DD'), 'بدون انتهاء') || '.'
                 ELSE 'اشتراكك ' || p_plan || ' فعّال حتى ' || COALESCE(to_char(p_expires_at, 'YYYY-MM-DD'), 'إشعار آخر') || '.' END,
            'Your ' || p_plan || ' subscription is active until ' || COALESCE(to_char(p_expires_at, 'YYYY-MM-DD'), 'further notice') || '.',
            'system'
        );
    END IF;

    INSERT INTO activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
    VALUES (v_caller_id, 'admin', 'admin_apply_subscription', 'store', p_store_id,
        jsonb_build_object('plan', p_plan, 'discount', p_discount, 'amount', p_amount,
                           'expires_at', p_expires_at, 'max_branches', p_max_branches,
                           'package_id', v_pkg_id));

    SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = p_store_id;
    RETURN jsonb_build_object('success', true, 'store_id', p_store_id,
        'store_name', v_user_name, 'plan', p_plan,
        'max_branches', v_max, 'package_id', v_pkg_id);
END $function$
;


-- ═══ FUNCTION admin_authenticity_stats(p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_sort text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_authenticity_stats(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 20, p_sort text DEFAULT 'fake'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_limit integer := greatest(1, least(coalesce(p_limit, 20), 2000));
  v_sort text := CASE WHEN p_sort IN ('fake','real','fake_pct','real_pct') THEN p_sort ELSE 'fake' END;
  v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  WITH votes AS (
    SELECT * FROM deal_authenticity_votes WHERE created_at >= v_from AND created_at < v_to
  ),
  tot AS (
    SELECT count(*) AS n,
           count(*) FILTER (WHERE is_real) AS r,
           count(*) FILTER (WHERE NOT is_real) AS f
    FROM votes
  ),
  by_deal AS (
    SELECT v2.deal_id, max(v2.store_id) AS store_id, count(*) AS n,
           count(*) FILTER (WHERE v2.is_real) AS r,
           count(*) FILTER (WHERE NOT v2.is_real) AS f
    FROM votes v2 GROUP BY v2.deal_id
  ),
  deal_rows AS (
    SELECT bd.*, d.item_name, d.status AS deal_status, coalesce(u.shop, u.name) AS shop
    FROM by_deal bd
    LEFT JOIN deals d ON d.id = bd.deal_id
    LEFT JOIN users u ON u.id = bd.store_id
    ORDER BY
      CASE v_sort
        WHEN 'real'     THEN bd.r::numeric
        WHEN 'fake'     THEN bd.f::numeric
        WHEN 'real_pct' THEN bd.r::numeric / bd.n
        ELSE                 bd.f::numeric / bd.n
      END DESC,
      bd.n DESC
    LIMIT v_limit
  ),
  by_store AS (
    SELECT v3.store_id, count(*) AS n,
           count(*) FILTER (WHERE v3.is_real) AS r,
           count(*) FILTER (WHERE NOT v3.is_real) AS f
    FROM votes v3 GROUP BY v3.store_id
  ),
  store_rows AS (
    SELECT bs.*, coalesce(u.shop, u.name) AS shop
    FROM by_store bs LEFT JOIN users u ON u.id = bs.store_id
    ORDER BY
      CASE v_sort
        WHEN 'real'     THEN bs.r::numeric
        WHEN 'fake'     THEN bs.f::numeric
        WHEN 'real_pct' THEN bs.r::numeric / bs.n
        ELSE                 bs.f::numeric / bs.n
      END DESC,
      bs.n DESC
    LIMIT v_limit
  )
  SELECT jsonb_build_object(
    'total', (SELECT n FROM tot),
    'real',  (SELECT r FROM tot),
    'fake',  (SELECT f FROM tot),
    'deals', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'deal_id', dr.deal_id, 'item_name', dr.item_name, 'deal_status', dr.deal_status,
        'store_id', dr.store_id, 'shop', dr.shop, 'votes', dr.n, 'real', dr.r, 'fake', dr.f)) FROM deal_rows dr), '[]'::jsonb),
    'stores', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'store_id', sr.store_id, 'shop', sr.shop, 'votes', sr.n, 'real', sr.r, 'fake', sr.f)) FROM store_rows sr), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END $function$
;


-- ═══ FUNCTION admin_booking_funnel(p_days integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_booking_funnel(p_days integer DEFAULT 30)
 RETURNS TABLE(total_views integer, unique_viewers integer, total_bookings integer, unique_bookers integer, conversion_pct numeric, avg_views_per_booker numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_total_views INT;
    v_unique_viewers INT;
    v_total_bookings INT;
    v_unique_bookers INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    SELECT COUNT(*), COUNT(DISTINCT user_id)
      INTO v_total_views, v_unique_viewers
    FROM activity_log
    WHERE action = 'view_deal'
      AND created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL;

    SELECT COUNT(*), COUNT(DISTINCT user_id)
      INTO v_total_bookings, v_unique_bookers
    FROM activity_log
    WHERE action = 'book'
      AND created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL;

    RETURN QUERY SELECT
        COALESCE(v_total_views, 0)::INT,
        COALESCE(v_unique_viewers, 0)::INT,
        COALESCE(v_total_bookings, 0)::INT,
        COALESCE(v_unique_bookers, 0)::INT,
        CASE WHEN COALESCE(v_unique_viewers, 0) = 0 THEN 0
             ELSE ROUND(100.0 * v_unique_bookers / v_unique_viewers, 1) END,
        CASE WHEN COALESCE(v_unique_bookers, 0) = 0 THEN 0
             ELSE ROUND(v_total_views::NUMERIC / v_unique_bookers, 1) END;
END;
$function$
;


-- ═══ FUNCTION admin_bot_analytics() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_bot_analytics()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb; v_cut bigint;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  -- 🪤 `30::bigint` قبل الضرب: بدونه يُحسب الطرفان `int4` فيتجاوز السقف.
  v_cut := (EXTRACT(EPOCH FROM NOW()) * 1000)::bigint - (30::bigint * 86400000);
  SELECT jsonb_build_object(
    'tg_linked',   (SELECT count(*) FROM users WHERE telegram_id IS NOT NULL AND deleted_at IS NULL),
    'wa_linked',   (SELECT count(*) FROM users WHERE whatsapp_chat_id IS NOT NULL AND deleted_at IS NULL),
    'both_linked', (SELECT count(*) FROM users WHERE telegram_id IS NOT NULL AND whatsapp_chat_id IS NOT NULL AND deleted_at IS NULL),
    'total_users', (SELECT count(*) FROM users WHERE deleted_at IS NULL),
    'lang_ar',     (SELECT count(*) FROM users WHERE (bot_lang='ar' OR bot_lang IS NULL) AND (telegram_id IS NOT NULL OR whatsapp_chat_id IS NOT NULL) AND deleted_at IS NULL),
    'lang_en',     (SELECT count(*) FROM users WHERE bot_lang='en' AND (telegram_id IS NOT NULL OR whatsapp_chat_id IS NOT NULL) AND deleted_at IS NULL),
    'bookings_total', jsonb_build_object(
       'web',      (SELECT count(*) FROM bookings WHERE source='web'),
       'telegram', (SELECT count(*) FROM bookings WHERE source='telegram'),
       'whatsapp', (SELECT count(*) FROM bookings WHERE source='whatsapp')),
    'bookings_30d', jsonb_build_object(
       'web',      (SELECT count(*) FROM bookings WHERE source='web'      AND booked_at >= v_cut),
       'telegram', (SELECT count(*) FROM bookings WHERE source='telegram' AND booked_at >= v_cut),
       'whatsapp', (SELECT count(*) FROM bookings WHERE source='whatsapp' AND booked_at >= v_cut)),
    'deals_total', jsonb_build_object(
       'web',      (SELECT count(*) FROM deals WHERE source='web'),
       'telegram', (SELECT count(*) FROM deals WHERE source='telegram'),
       'whatsapp', (SELECT count(*) FROM deals WHERE source='whatsapp'))
  ) INTO v;
  RETURN v;
END;
$function$
;


-- ═══ FUNCTION admin_broadcast_notification(p_title_ar text, p_body_ar text, p_audience text, p_type text, p_meta jsonb, p_inapp boolean, p_email boolean) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_broadcast_notification(p_title_ar text, p_body_ar text DEFAULT ''::text, p_audience text DEFAULT 'all'::text, p_type text DEFAULT 'system'::text, p_meta jsonb DEFAULT '{}'::jsonb, p_inapp boolean DEFAULT true, p_email boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_notified int := 0;
    v_emailed  int := 0;
    v_html     text;
    v_type     text;
    r RECORD;
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'forbidden: admin only';
    END IF;
    IF COALESCE(btrim(p_title_ar), '') = '' THEN
        RETURN jsonb_build_object('success', false, 'error', 'empty_title');
    END IF;
    -- v14.78 — النوع يُتحقّق منه أوّلاً: كان يُمرَّر كما يصل، فأي قيمةٍ خارج
    -- القيد تُفجّر الإدراج برسالةٍ إنجليزية خام يراها المدير كما رآها ناصر.
    v_type := public.taki_notification_type_guard(p_type);
    IF NOT p_inapp AND NOT p_email THEN
        RETURN jsonb_build_object('success', true, 'notified', 0, 'emailed', 0);
    END IF;

    IF p_inapp THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        SELECT u.id,
               p_title_ar, p_title_ar,
               COALESCE(p_body_ar, ''), COALESCE(p_body_ar, ''),
               v_type,
               COALESCE(p_meta, '{}'::jsonb) || jsonb_build_object('broadcast', true),
               NOW()
        FROM users u
        WHERE u.deleted_at IS NULL
          AND CASE
                -- «التجار» يشمل حسابات الأدمن المالكة لمتاجر (قاعدة v11.79)
                WHEN p_audience = 'sellers' THEN u.user_type IN ('seller', 'admin')
                WHEN p_audience = 'buyers'  THEN u.user_type IN ('buyer', 'admin')
                ELSE TRUE
              END;
        GET DIAGNOSTICS v_notified = ROW_COUNT;
    END IF;

    IF p_email THEN
        -- Minimal HTML-escape so a title with < or & can't break the email.
        v_html := '<p style="font-size:15px;line-height:1.9;margin:0">'
                  || replace(replace(replace(replace(COALESCE(p_body_ar, ''),
                       '&', '&amp;'), '<', '&lt;'), '>', '&gt;'), E'\n', '<br>')
                  || '</p>';
        FOR r IN
            SELECT u.id FROM users u
            WHERE u.deleted_at IS NULL
              AND CASE
                    WHEN p_audience = 'sellers' THEN u.user_type IN ('seller', 'admin')
                    WHEN p_audience = 'buyers'  THEN u.user_type IN ('buyer', 'admin')
                    ELSE TRUE
                  END
        LOOP
            -- taki_queue_email validates the address and skips bot placeholders.
            IF public.taki_queue_email(r.id, 'admin_broadcast', p_title_ar,
                                       public.taki_email_wrap(p_title_ar, v_html)) THEN
                v_emailed := v_emailed + 1;
            END IF;
        END LOOP;
    END IF;

    RETURN jsonb_build_object('success', true, 'notified', v_notified, 'emailed', v_emailed);
END $function$
;


-- ═══ FUNCTION admin_browse_no_book(p_days integer, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_browse_no_book(p_days integer DEFAULT 30, p_limit integer DEFAULT 20)
 RETURNS TABLE(user_id text, name text, phone text, views_count integer, last_viewed_at timestamp with time zone, deals_seen integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

  RETURN QUERY
  WITH window_views AS (
      SELECT al.user_id AS uid,
             count(*)::int AS views_count,
             max(al.created_at) AS last_viewed_at,
             count(DISTINCT al.entity_id)::int AS deals_seen
        FROM activity_log al
       WHERE al.action = 'view_deal'
         AND al.created_at >= NOW() - (p_days || ' days')::interval
         AND al.user_id IS NOT NULL
       GROUP BY al.user_id
  ),
  window_books AS (
      SELECT DISTINCT al.user_id AS uid
        FROM activity_log al
       WHERE al.action = 'book'
         AND al.created_at >= NOW() - (p_days || ' days')::interval
         AND al.user_id IS NOT NULL
  )
  -- 🪤 الأعمدة مؤهَّلةٌ بأسماءٍ لا تصادم عمودَ الإخراج (`uid` لا `user_id`):
  --    بلا ذلك يلتبس `user_id` داخل الاستعلام الفرعي فتفشل الدالّة كلّها.
  SELECT wv.uid, u.name, u.phone, wv.views_count, wv.last_viewed_at, wv.deals_seen
    FROM window_views wv
    JOIN users u ON u.id = wv.uid
   WHERE wv.uid NOT IN (SELECT wb.uid FROM window_books wb)
     AND u.deleted_at IS NULL
   ORDER BY wv.views_count DESC
   LIMIT p_limit;
END;
$function$
;


-- ═══ FUNCTION admin_campaign_audience(p_campaign_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_campaign_audience(p_campaign_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE camp RECORD; v_all int; v_hit int; v_new int;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT * INTO camp FROM public.promotional_campaigns WHERE id = p_campaign_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;

  SELECT count(*) INTO v_all FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL AND COALESCE(u.is_suspended,false) = false;

  SELECT count(*) INTO v_hit FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL AND COALESCE(u.is_suspended,false) = false
    AND public.taki_user_in_campaign(u.id, camp.target_city, camp.target_region);

  SELECT count(*) INTO v_new FROM public.users u
  WHERE (camp.target_audience = 'all' OR u.user_type = camp.target_audience)
    AND u.deleted_at IS NULL AND COALESCE(u.is_suspended,false) = false
    AND public.taki_user_in_campaign(u.id, camp.target_city, camp.target_region)
    AND NOT EXISTS (SELECT 1 FROM public.promo_impressions p
                    WHERE p.campaign_id = camp.id AND p.user_id = u.id);

  RETURN jsonb_build_object('ok', true, 'eligible', v_all, 'targeted', v_hit,
                            'will_receive', v_new,
                            'targeted_city', camp.target_city, 'targeted_region', camp.target_region);
END $function$
;


-- ═══ FUNCTION admin_category_funnel(p_days integer, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_category_funnel(p_days integer DEFAULT 30, p_limit integer DEFAULT 12)
 RETURNS TABLE(category text, views integer, bookings integer, conversion_pct numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH win AS (
        SELECT al.action, al.entity_id, al.created_at
        FROM activity_log al
        WHERE al.action IN ('view_deal', 'book')
          AND al.entity_id IS NOT NULL
          AND al.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    ),
    joined AS (
        SELECT COALESCE(d.category, 'غير مصنّف') AS cat,
               COUNT(*) FILTER (WHERE win.action = 'view_deal') AS views,
               COUNT(*) FILTER (WHERE win.action = 'book') AS books
        FROM win
        LEFT JOIN deals d ON d.id = win.entity_id
        GROUP BY 1
    )
    SELECT joined.cat::TEXT,
           joined.views::INT,
           joined.books::INT,
           CASE WHEN joined.views = 0 THEN 0
                ELSE ROUND(100.0 * joined.books / joined.views, 1) END
    FROM joined
    WHERE joined.views > 0
    ORDER BY joined.views DESC
    LIMIT GREATEST(p_limit, 1);
END;
$function$
;


-- ═══ FUNCTION admin_churned_subscribers(p_days integer, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_churned_subscribers(p_days integer DEFAULT 90, p_limit integer DEFAULT 100)
 RETURNS TABLE(store_id text, name text, shop text, phone text, plan text, ended_at timestamp with time zone, days_since_churn integer, last_amount numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT u.id::TEXT,
           u.name::TEXT,
           u.shop::TEXT,
           u.phone::TEXT,
           sp.subscription_plan::TEXT,
           sp.subscription_expires_at,
           GREATEST(0, EXTRACT(DAY FROM (now() - sp.subscription_expires_at))::INT) AS days_since,
           sp.subscription_amount
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE u.user_type = 'seller'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND sp.subscription_expires_at IS NOT NULL
      AND sp.subscription_expires_at < now()
      AND sp.subscription_expires_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
      AND (sp.subscription_plan IS NULL OR sp.subscription_plan IN ('free', 'expired'))
    ORDER BY sp.subscription_expires_at DESC
    LIMIT GREATEST(p_limit, 1);
END;
$function$
;


-- ═══ FUNCTION admin_complaint_reply(p_id uuid, p_body text, p_status text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_complaint_reply(p_id uuid, p_body text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_owner text; v_subject text; v_body text;
BEGIN
  v_uid := auth.uid()::text;
  IF NOT public.taki_admin_perm('tab_reports') THEN
    RAISE EXCEPTION 'forbidden: tab_reports required';
  END IF;

  v_body := btrim(COALESCE(p_body, ''));
  IF v_body = '' THEN RAISE EXCEPTION 'empty reply'; END IF;

  SELECT c.user_id, COALESCE(NULLIF(btrim(c.subject), ''), 'شكواك')
    INTO v_owner, v_subject
    FROM public.complaints c WHERE c.id = p_id;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'complaint not found'; END IF;

  INSERT INTO public.complaint_replies (complaint_id, author_id, author_role, body)
  VALUES (p_id, v_uid, 'admin', v_body);

  IF p_status IS NOT NULL THEN
    IF p_status NOT IN ('open','reviewing','resolved','dismissed') THEN
      RAISE EXCEPTION 'Bad status';
    END IF;
    UPDATE public.complaints
       SET status = p_status,
           resolved_by = CASE WHEN p_status IN ('resolved','dismissed') THEN v_uid ELSE resolved_by END,
           resolved_at = CASE WHEN p_status IN ('resolved','dismissed') THEN now() ELSE resolved_at END
     WHERE id = p_id;
  END IF;

  -- 🔴 هذا هو جوهر الإصلاح: قبله كانت الإدارة تغيّر الحالة إلى «تم الحل»
  --    و**لا يصل صاحب الشكوى شيء** بأي صورة.
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (
    v_owner,
    'ردٌّ على شكواك',
    'Reply to your complaint',
    left(v_body, 160),
    left(v_body, 160),
    'system',
    jsonb_build_object('audience', 'user', 'kind', 'complaint_reply', 'complaint_id', p_id)
  );

  RETURN jsonb_build_object('ok', true, 'complaint_id', p_id, 'notified', v_owner);
END;
$function$
;


-- ═══ FUNCTION admin_custom_draw(p_source text, p_role text, p_from timestamp with time zone, p_to timestamp with time zone, p_count integer, p_title text, p_preview boolean) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_custom_draw(p_source text, p_role text DEFAULT 'all'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_count integer DEFAULT 1, p_title text DEFAULT ''::text, p_preview boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_count integer := greatest(1, least(coalesce(p_count, 1), 500));
  v_pick integer;
  v_role text := CASE WHEN p_role IN ('all','buyers','sellers') THEN p_role ELSE 'all' END;
  v_pool integer := 0;
  v_win jsonb;
  v_id uuid;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_source NOT IN ('buyers_booked','stores_booked','registered') THEN
    RAISE EXCEPTION 'bad source';
  END IF;
  -- preview = عينة عشوائية للعجلة الدوّارة فقط (لا سحب ولا حفظ)
  v_pick := CASE WHEN p_preview THEN 40 ELSE v_count END;

  IF p_source = 'buyers_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.user_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone, 'shop', NULL)) INTO v_win
      FROM (SELECT u.id, u.name, u.phone FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.user_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT v_pick) t;

  ELSIF p_source = 'stores_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.store_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone, 'shop', t.shop)) INTO v_win
      FROM (SELECT u.id, u.name, u.phone, coalesce(u.shop, u.name) AS shop FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.store_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT v_pick) t;

  ELSE -- registered
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND u.created_at >= v_from AND u.created_at < v_to
       AND (v_role = 'all'
            OR (v_role = 'buyers'  AND u.user_type = 'buyer')
            OR (v_role = 'sellers' AND u.user_type = 'seller'));
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone, 'shop', t.shop)) INTO v_win
      FROM (SELECT u.id, u.name, u.phone, u.shop FROM users u
             WHERE u.deleted_at IS NULL
               AND u.created_at >= v_from AND u.created_at < v_to
               AND (v_role = 'all'
                    OR (v_role = 'buyers'  AND u.user_type = 'buyer')
                    OR (v_role = 'sellers' AND u.user_type = 'seller'))
             ORDER BY random() LIMIT v_pick) t;
  END IF;

  IF v_pool = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'empty_pool');
  END IF;

  IF p_preview THEN
    RETURN jsonb_build_object('success', true, 'preview', true, 'pool', v_pool, 'sample', coalesce(v_win, '[]'::jsonb));
  END IF;

  INSERT INTO admin_draws (title, source, role_filter, from_ts, to_ts, winners_count, pool_size, winners, created_by)
  VALUES (coalesce(btrim(p_title), ''), p_source, v_role, p_from, p_to, v_count, v_pool, coalesce(v_win, '[]'::jsonb), auth.uid()::text)
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'id', v_id, 'pool', v_pool, 'winners', coalesce(v_win, '[]'::jsonb));
END $function$
;


-- ═══ FUNCTION admin_custom_draw_preview(p_source text, p_role text, p_from timestamp with time zone, p_to timestamp with time zone) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_custom_draw_preview(p_source text, p_role text DEFAULT 'all'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_role text := CASE WHEN p_role IN ('all','buyers','sellers') THEN p_role ELSE 'all' END;
  v_pool integer := 0;
  v_sample jsonb;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_source NOT IN ('buyers_booked','stores_booked','registered') THEN
    RAISE EXCEPTION 'bad source';
  END IF;

  IF p_source = 'buyers_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.user_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone)) INTO v_sample
      FROM (SELECT u.id, coalesce(u.name,'مشارك') AS name, coalesce(u.phone,'') AS phone FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.user_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT 40) t;

  ELSIF p_source = 'stores_booked' THEN
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND EXISTS (SELECT 1 FROM bookings b
                    WHERE b.store_id = u.id AND b.status <> 'cancelled'
                      AND b.created_at >= v_from AND b.created_at < v_to);
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone)) INTO v_sample
      FROM (SELECT u.id, coalesce(u.shop, u.name, 'متجر') AS name, coalesce(u.phone,'') AS phone FROM users u
             WHERE u.deleted_at IS NULL
               AND EXISTS (SELECT 1 FROM bookings b
                            WHERE b.store_id = u.id AND b.status <> 'cancelled'
                              AND b.created_at >= v_from AND b.created_at < v_to)
             ORDER BY random() LIMIT 40) t;

  ELSE
    SELECT count(*) INTO v_pool FROM users u
     WHERE u.deleted_at IS NULL
       AND u.created_at >= v_from AND u.created_at < v_to
       AND (v_role = 'all'
            OR (v_role = 'buyers'  AND u.user_type = 'buyer')
            OR (v_role = 'sellers' AND u.user_type = 'seller'));
    SELECT jsonb_agg(jsonb_build_object('id', t.id, 'name', t.name, 'phone', t.phone)) INTO v_sample
      FROM (SELECT u.id, coalesce(u.shop, u.name, 'مشارك') AS name, coalesce(u.phone,'') AS phone FROM users u
             WHERE u.deleted_at IS NULL
               AND u.created_at >= v_from AND u.created_at < v_to
               AND (v_role = 'all'
                    OR (v_role = 'buyers'  AND u.user_type = 'buyer')
                    OR (v_role = 'sellers' AND u.user_type = 'seller'))
             ORDER BY random() LIMIT 40) t;
  END IF;

  RETURN jsonb_build_object('pool', v_pool, 'sample', coalesce(v_sample, '[]'::jsonb));
END $function$
;


-- ═══ FUNCTION admin_daily_metrics(p_days integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_daily_metrics(p_days integer DEFAULT 30)
 RETURNS TABLE(day_key text, day_label text, events integer, bookings integer, new_users integer, completed_bookings integer, cancelled_bookings integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH days AS (
        SELECT date_trunc('day', now() AT TIME ZONE 'Asia/Riyadh')::DATE - n AS d
        FROM generate_series(0, GREATEST(p_days, 1) - 1) AS n
    ),
    events_per_day AS (
        SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d, COUNT(*) AS c
        FROM activity_log
        WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
        GROUP BY 1
    ),
    bookings_per_day AS (
        SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d,
               COUNT(*) AS c,
               COUNT(*) FILTER (WHERE status = 'completed') AS done,
               COUNT(*) FILTER (WHERE status = 'cancelled') AS cancelled
        FROM bookings
        WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
        GROUP BY 1
    ),
    new_per_day AS (
        SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d, COUNT(*) AS c
        FROM users
        WHERE created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
          AND user_type = 'buyer'
        GROUP BY 1
    )
    SELECT to_char(days.d, 'YYYY-MM-DD')::TEXT,
           to_char(days.d, 'DD/MM')::TEXT,
           COALESCE(e.c, 0)::INT,
           COALESCE(b.c, 0)::INT,
           COALESCE(n.c, 0)::INT,
           COALESCE(b.done, 0)::INT,
           COALESCE(b.cancelled, 0)::INT
    FROM days
    LEFT JOIN events_per_day e ON e.d = days.d
    LEFT JOIN bookings_per_day b ON b.d = days.d
    LEFT JOIN new_per_day n ON n.d = days.d
    ORDER BY days.d ASC;
END;
$function$
;


-- ═══ FUNCTION admin_delete_flag(p_id uuid) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delete_flag(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  DELETE FROM public.moderation_flags WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  RETURN jsonb_build_object('success', true);
END $function$
;


-- ═══ FUNCTION admin_delete_location(p_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delete_location(p_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  DELETE FROM locations WHERE id = p_id;
  RETURN jsonb_build_object('success', true);
END; $function$
;


-- ═══ FUNCTION admin_delete_message(p_message_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delete_message(p_message_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_caller TEXT;
BEGIN
    v_caller := auth.uid()::text;
    IF NOT public.is_admin(v_caller) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    DELETE FROM public.booking_messages WHERE id = p_message_id;
    INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
    VALUES (v_caller, 'admin', 'admin_delete_message', 'booking_message', p_message_id, '{}'::jsonb);
    RETURN jsonb_build_object('success', TRUE);
END $function$
;


-- ═══ FUNCTION admin_delete_rating(p_rating_id text, p_reason text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delete_rating(p_rating_id text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_r public.ratings%ROWTYPE; v_msg text;
BEGIN
  IF NOT public.taki_admin_perm('action_delete_deals') THEN
    RAISE EXCEPTION 'ليست لديك صلاحية حذف التقييمات';
  END IF;
  IF COALESCE(btrim(p_reason),'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'REASON_REQUIRED');
  END IF;
  SELECT * INTO v_r FROM public.ratings WHERE id = p_rating_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF v_r.deleted_at IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_DELETED');
  END IF;

  -- حذفٌ ناعم: المتوسط والعدد على `deals` يُعاد حسابهما بمشغّل التقييمات،
  -- والصفّ يبقى دليلاً على ما جرى.
  UPDATE public.ratings SET deleted_at = now() WHERE id = p_rating_id;

  v_msg := '🚫 حذفت إدارة تاكي تقييمك — ' || btrim(p_reason) || '.';
  INSERT INTO public.user_warnings (user_id, user_role, reason, admin_id)
  VALUES (v_r.user_id, 'buyer', v_msg, auth.uid()::text);
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (v_r.user_id, '🚫 حذف تقييم', '🚫 Review removed', v_msg, v_msg, 'system',
          jsonb_build_object('audience','user'));
  RETURN jsonb_build_object('ok', true);
END $function$
;


-- ═══ FUNCTION admin_delete_warning(p_warning_id uuid) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delete_warning(p_warning_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  DELETE FROM public.pending_warnings WHERE warning_id = p_warning_id AND sent_at IS NULL;
  DELETE FROM public.user_warnings WHERE id = p_warning_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  RETURN jsonb_build_object('success', true);
END $function$
;


-- ═══ FUNCTION admin_delivery_orders(p_status text, p_limit integer, p_offset integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delivery_orders(p_status text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v jsonb; v_lim int := GREATEST(1, LEAST(200, COALESCE(p_limit,50)));
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.booked_at DESC), '[]'::jsonb) INTO v
  FROM (
    SELECT b.barcode, b.status, b.booked_at, b.total_amount, b.delivery_fee,
           b.user_name, b.user_phone,
           COALESCE(NULLIF(u.shop,''), u.name) AS store_name, b.store_id,
           d.item_name, b.payment_method, (b.paid_at IS NOT NULL) AS paid,
           b.delivery_address->>'label'   AS addr_label,
           b.delivery_address->>'details' AS addr_details,
           dt.status AS track_status, dt.updated_at AS track_at
    FROM bookings b
    LEFT JOIN users u ON u.id = b.store_id
    LEFT JOIN deals d ON d.id = b.deal_id
    LEFT JOIN delivery_tracks dt ON dt.barcode = b.barcode
    WHERE b.fulfillment = 'delivery'
      AND (p_status IS NULL OR b.status = p_status)
    ORDER BY b.booked_at DESC
    LIMIT v_lim OFFSET GREATEST(0, COALESCE(p_offset,0))
  ) t;
  RETURN jsonb_build_object('ok', true, 'rows', v,
    'total', (SELECT count(*) FROM bookings WHERE fulfillment='delivery'
                AND (p_status IS NULL OR status = p_status)));
END $function$
;


-- ═══ FUNCTION admin_delivery_overview() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delivery_overview()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT jsonb_build_object(
    'global_on',       public.taki_delivery_globally_on(),
    'orders_delivery', (SELECT count(*) FROM bookings WHERE fulfillment = 'delivery'),
    'orders_pickup',   (SELECT count(*) FROM bookings WHERE COALESCE(fulfillment,'pickup') = 'pickup'),
    'revenue_delivery',(SELECT COALESCE(SUM(total_amount),0) FROM bookings WHERE fulfillment='delivery' AND status='completed'),
    'fees_collected',  (SELECT COALESCE(SUM(delivery_fee),0) FROM bookings WHERE fulfillment='delivery' AND status='completed'),
    'stores_enabled',  (SELECT count(*) FROM store_profiles WHERE delivery_enabled AND NOT delivery_blocked_by_admin),
    'stores_blocked',  (SELECT count(*) FROM store_profiles WHERE delivery_blocked_by_admin),
    'zones',           (SELECT count(*) FROM store_delivery_zones WHERE is_active),
    'tracks_live',     (SELECT count(*) FROM delivery_tracks WHERE status IN ('on_the_way','arrived')),
    'by_status',       (SELECT COALESCE(jsonb_object_agg(status, n), '{}'::jsonb)
                        FROM (SELECT status, count(*) n FROM bookings
                              WHERE fulfillment='delivery' GROUP BY status) t)
  ) INTO v;
  RETURN v;
END $function$
;


-- ═══ FUNCTION admin_delivery_stores() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_delivery_stores()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.store_name), '[]'::jsonb) INTO v
  FROM (
    SELECT sp.store_id,
           COALESCE(NULLIF(u.shop,''), u.name, '—') AS store_name,
           sp.delivery_enabled, sp.delivery_blocked_by_admin, sp.delivery_block_reason,
           sp.delivery_fee, sp.delivery_min_order, sp.delivery_eta_min, sp.delivery_payment,
           (SELECT count(*) FROM store_delivery_zones z WHERE z.store_id = sp.store_id AND z.is_active) AS zones,
           (SELECT count(*) FROM bookings b WHERE b.store_id = sp.store_id AND b.fulfillment='delivery') AS orders
    FROM store_profiles sp
    LEFT JOIN users u ON u.id = sp.store_id
    WHERE sp.delivery_enabled OR sp.delivery_blocked_by_admin
  ) t;
  RETURN jsonb_build_object('ok', true, 'rows', v);
END $function$
;


-- ═══ FUNCTION admin_demote_user(target_id text, target_role text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_demote_user(target_id text, target_role text DEFAULT 'buyer'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  IF target_role NOT IN ('buyer','seller') THEN
    RAISE EXCEPTION 'target_role must be buyer or seller';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users u WHERE u.id = target_id AND u.is_super_admin = TRUE) THEN
    RAISE EXCEPTION 'cannot demote super admin';
  END IF;
  UPDATE public.users u
  SET user_type = target_role,
      admin_permissions = '{}'::TEXT[]
  WHERE u.id = target_id AND u.user_type = 'admin';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target is not a staff admin';
  END IF;
END;
$function$
;


-- ═══ FUNCTION admin_first_members(p_kind text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_first_members(p_kind text DEFAULT 'all'::text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_limit integer := greatest(1, least(coalesce(p_limit, 100), 20000));
  v_kind text := CASE WHEN p_kind IN ('all','buyers','sellers') THEN p_kind ELSE 'all' END;
  v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'id', t.id, 'name', t.name, 'shop', t.shop, 'phone', t.phone,
           'user_type', t.user_type, 'created_at', t.created_at) ORDER BY t.created_at ASC), '[]'::jsonb)
    INTO v
    FROM (
      SELECT u.id, u.name, u.shop, u.phone, u.user_type, u.created_at
        FROM users u
       WHERE u.deleted_at IS NULL
         AND u.created_at >= v_from AND u.created_at < v_to
         AND (v_kind = 'all'
              OR (v_kind = 'buyers'  AND u.user_type = 'buyer')
              OR (v_kind = 'sellers' AND u.user_type = 'seller'))
       ORDER BY u.created_at ASC
       LIMIT v_limit
    ) t;
  RETURN coalesce(v, '[]'::jsonb);
END $function$
;


-- ═══ FUNCTION admin_geo_insights(p_days integer, p_region text, p_city text, p_lat double precision, p_lng double precision, p_radius_km double precision, p_date text, p_hour_from integer, p_hour_to integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_geo_insights(p_days integer DEFAULT 7, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_radius_km double precision DEFAULT NULL::double precision, p_date text DEFAULT NULL::text, p_hour_from integer DEFAULT NULL::integer, p_hour_to integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_days int := least(greatest(coalesce(p_days,7),1),90);
  v_today date := (now() AT TIME ZONE 'Asia/Riyadh')::date;
  v_day_from date;
  v_day_to   date;
  v_from timestamptz;
  v_to   timestamptz;
  v_hf int := coalesce(p_hour_from, 0);
  v_ht int := coalesce(p_hour_to, 23);
  v_has_hours boolean := (p_hour_from IS NOT NULL OR p_hour_to IS NOT NULL);
  v_has_area boolean := (p_region IS NOT NULL) OR (p_city IS NOT NULL)
                        OR (p_lat IS NOT NULL AND p_lng IS NOT NULL AND p_radius_km IS NOT NULL AND p_radius_km > 0);
  v_out jsonb;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden'; END IF;

  IF p_date IS NOT NULL AND p_date <> '' THEN
    v_day_from := p_date::date; v_day_to := p_date::date;
  ELSE
    v_day_from := v_today - (v_days-1); v_day_to := v_today;
  END IF;
  v_from := (v_day_from::timestamp) AT TIME ZONE 'Asia/Riyadh';
  v_to   := ((v_day_to + 1)::timestamp) AT TIME ZONE 'Asia/Riyadh';
  v_hf := least(greatest(v_hf,0),23); v_ht := least(greatest(v_ht,0),23);

  WITH ulocs AS (
    SELECT u.id, u.user_type, u.lat, u.lng, u.created_at AS joined_at, c.city_id, c.region_id
    FROM users u
    LEFT JOIN LATERAL (
      SELECT g.city_id, g.region_id FROM sa_cities_geo g
      WHERE u.lat IS NOT NULL AND u.lng IS NOT NULL
      ORDER BY (g.lat-u.lat)*(g.lat-u.lat) + (g.lng-u.lng)*(g.lng-u.lng) ASC
      LIMIT 1
    ) c ON true
    WHERE u.deleted_at IS NULL
  ),
  area_users AS (
    SELECT id FROM ulocs
    WHERE (p_region IS NULL OR region_id = p_region)
      AND (p_city IS NULL OR city_id = p_city)
      AND (p_lat IS NULL OR p_lng IS NULL OR p_radius_km IS NULL OR p_radius_km <= 0
           OR (lat IS NOT NULL AND
               6371*acos(least(1, greatest(-1,
                 sin(radians(p_lat))*sin(radians(lat)) +
                 cos(radians(p_lat))*cos(radians(lat))*cos(radians(lng - p_lng))))) <= p_radius_km))
  ),
  ev AS (
    SELECT e.*, (e.created_at AT TIME ZONE 'Asia/Riyadh')::date AS d,
           extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int AS hr
    FROM analytics_events e
    WHERE e.created_at >= v_from AND e.created_at < v_to
      AND (NOT v_has_hours OR extract(hour FROM e.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN v_hf AND v_ht)
      AND (NOT v_has_area OR (e.user_id IS NOT NULL AND e.user_id IN (SELECT id FROM area_users)))
  ),
  bk_all AS (
    SELECT b.*, (b.created_at AT TIME ZONE 'Asia/Riyadh')::date AS d
    FROM bookings b
    WHERE b.created_at >= v_from AND b.created_at < v_to
      AND (NOT v_has_hours OR extract(hour FROM b.created_at AT TIME ZONE 'Asia/Riyadh')::int BETWEEN v_hf AND v_ht)
      AND (NOT v_has_area OR b.user_id IN (SELECT id FROM area_users))
  ),
  bk AS (SELECT * FROM bk_all WHERE status <> 'cancelled'),
  days AS (
    SELECT generate_series(v_day_from, v_day_to, interval '1 day')::date AS d
  ),
  daily AS (
    SELECT dd.d,
      coalesce(e.actives,0) AS actives, coalesce(e.opens,0) AS opens,
      coalesce(b.bookers,0) AS bookers, coalesce(b.bookings,0) AS bookings
    FROM days dd
    LEFT JOIN (
      SELECT d, count(DISTINCT user_id) AS actives,
             count(*) FILTER (WHERE kind='app_open') AS opens
      FROM ev GROUP BY d
    ) e ON e.d = dd.d
    LEFT JOIN (
      SELECT d, count(DISTINCT user_id) AS bookers, count(*) AS bookings
      FROM bk GROUP BY d
    ) b ON b.d = dd.d
    ORDER BY dd.d
  ),
  hours AS (
    SELECT h AS hr,
      coalesce((SELECT count(*) FROM ev WHERE ev.hr = h AND ev.kind='app_open'),0) AS opens,
      coalesce((SELECT count(DISTINCT ev.user_id) FROM ev WHERE ev.hr = h),0) AS actives
    FROM generate_series(0,23) h
  ),
  srcs AS (
    SELECT coalesce(source,'web') AS source,
           count(DISTINCT user_id) AS users,
           count(*) FILTER (WHERE kind='app_open') AS opens
    FROM ev WHERE source IN ('web','telegram','whatsapp') GROUP BY 1
  ),
  bksrc AS (
    SELECT coalesce(source,'web') AS source, count(*) AS bookings FROM bk GROUP BY 1
  ),
  cats AS (
    SELECT d2.category, count(*) AS views,
           count(DISTINCT e.user_id) AS viewers
    FROM ev e JOIN deals d2 ON d2.id = e.deal_id
    WHERE e.kind = 'deal_view'
    GROUP BY 1 ORDER BY views DESC LIMIT 20
  ),
  regions AS (
    SELECT ul.region_id,
      count(*)::int AS registered,
      count(*) FILTER (WHERE ul.user_type = 'buyer')::int AS buyers,
      count(*) FILTER (WHERE ul.user_type IN ('seller','admin'))::int AS sellers,
      (SELECT count(DISTINCT e.user_id) FROM ev e JOIN ulocs u2 ON u2.id = e.user_id WHERE u2.region_id = ul.region_id) AS actives
    FROM ulocs ul
    WHERE ul.region_id IS NOT NULL
    GROUP BY ul.region_id
  ),
  city_daily AS (
    SELECT ul.city_id, ul.region_id, e.d, count(DISTINCT e.user_id) AS n
    FROM ev e JOIN ulocs ul ON ul.id = e.user_id
    WHERE e.user_id IS NOT NULL AND ul.city_id IS NOT NULL
    GROUP BY 1,2,3
  ),
  city_reg AS (
    SELECT city_id, count(*)::int AS registered FROM ulocs WHERE city_id IS NOT NULL GROUP BY city_id
  ),
  cities AS (
    SELECT cd.city_id, cd.region_id,
      coalesce(cr.registered,0) AS registered,
      (SELECT count(DISTINCT e2.user_id) FROM ev e2 JOIN ulocs u2 ON u2.id=e2.user_id WHERE u2.city_id = cd.city_id) AS actives,
      coalesce(sum(cd.n) FILTER (WHERE cd.d = v_today),0)::int AS today,
      coalesce(sum(cd.n) FILTER (WHERE cd.d = v_today - 1),0)::int AS yesterday
    FROM city_daily cd
    LEFT JOIN city_reg cr ON cr.city_id = cd.city_id
    GROUP BY cd.city_id, cd.region_id, cr.registered
    ORDER BY actives DESC
    LIMIT 60
  )
  SELECT jsonb_build_object(
    'daily',   (SELECT coalesce(jsonb_agg(jsonb_build_object('d',d,'actives',actives,'opens',opens,'bookers',bookers,'bookings',bookings) ORDER BY d),'[]'::jsonb) FROM daily),
    'hours',   (SELECT coalesce(jsonb_agg(jsonb_build_object('hr',hr,'opens',opens,'actives',actives) ORDER BY hr),'[]'::jsonb) FROM hours),
    'regions', (SELECT coalesce(jsonb_agg(jsonb_build_object('region',region_id,'registered',registered,'buyers',buyers,'sellers',sellers,'actives',actives) ORDER BY registered DESC),'[]'::jsonb) FROM regions),
    'sources', (SELECT coalesce(jsonb_agg(jsonb_build_object('source',s.source,'users',s.users,'opens',s.opens,'bookings',coalesce(bs.bookings,0))),'[]'::jsonb)
                FROM srcs s LEFT JOIN bksrc bs ON bs.source = s.source),
    'cats',    (SELECT coalesce(jsonb_agg(jsonb_build_object('category',category,'views',views,'viewers',viewers) ORDER BY views DESC),'[]'::jsonb) FROM cats),
    'cities',  (SELECT coalesce(jsonb_agg(jsonb_build_object('city',city_id,'region',region_id,'registered',registered,'actives',actives,'today',today,'yesterday',yesterday) ORDER BY actives DESC),'[]'::jsonb) FROM cities),
    'totals',  jsonb_build_object(
        'actives',       (SELECT count(DISTINCT user_id) FROM ev),
        'opens',         (SELECT count(*) FROM ev WHERE kind='app_open'),
        'bookers',       (SELECT count(DISTINCT user_id) FROM bk),
        'bookings',      (SELECT count(*) FROM bk_all),
        'bk_completed',  (SELECT count(*) FROM bk_all WHERE status = 'completed'),
        'bk_active',     (SELECT count(*) FROM bk_all WHERE status NOT IN ('completed','cancelled')),
        'bk_cancelled',  (SELECT count(*) FROM bk_all WHERE status = 'cancelled'),
        'bk_c_buyer',    (SELECT count(*) FROM bk_all WHERE status = 'cancelled' AND cancelled_by = 'buyer'),
        'bk_c_seller',   (SELECT count(*) FROM bk_all WHERE status = 'cancelled' AND cancelled_by = 'seller'),
        'bk_c_system',   (SELECT count(*) FROM bk_all WHERE status = 'cancelled' AND cancelled_by = 'system'),
        'actives_today', (SELECT count(DISTINCT user_id) FROM ev WHERE d = v_today),
        'actives_yday',  (SELECT count(DISTINCT user_id) FROM ev WHERE d = v_today - 1),
        'located_users', (SELECT count(*) FROM ulocs WHERE lat IS NOT NULL),
        'total_users',   (SELECT count(*) FROM ulocs),
        'new_users',     (SELECT count(*) FROM ulocs WHERE joined_at >= v_from AND joined_at < v_to
                            AND (NOT v_has_area OR id IN (SELECT id FROM area_users)))
    )
  ) INTO v_out;

  RETURN v_out;
END;
$function$
;


-- ═══ FUNCTION admin_geographic_breakdown(p_days integer, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_geographic_breakdown(p_days integer DEFAULT 30, p_limit integer DEFAULT 20)
 RETURNS TABLE(city text, region text, bookings_count integer, completed_bookings integer, gmv numeric, unique_buyers integer, active_stores integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT
        COALESCE(d.city, 'غير محدّد')::TEXT,
        COALESCE(d.region, 'غير محدّد')::TEXT,
        COUNT(*)::INT,
        COUNT(*) FILTER (WHERE b.status = 'completed')::INT,
        COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)) FILTER (WHERE b.status IN ('completed', 'acknowledged')), 0)::NUMERIC,
        COUNT(DISTINCT b.user_id)::INT,
        COUNT(DISTINCT b.store_id)::INT
    FROM bookings b
    LEFT JOIN deals d ON d.id = b.deal_id
    WHERE b.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    GROUP BY 1, 2
    HAVING COUNT(*) > 0
    ORDER BY 5 DESC, 3 DESC
    LIMIT GREATEST(p_limit, 1);
END;
$function$
;


-- ═══ FUNCTION admin_get_thread_messages(p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_get_thread_messages(p_barcode text)
 RETURNS TABLE(id text, barcode text, sender_id text, sender_role text, sender_name text, body text, created_at timestamp with time zone, read_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_admin(auth.uid()::text) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    RETURN QUERY
    SELECT bm.id, bm.barcode, bm.sender_id, bm.sender_role,
           u.name, bm.body, bm.created_at, bm.read_at
    FROM public.booking_messages bm
    LEFT JOIN public.users u ON u.id = bm.sender_id
    WHERE bm.barcode = p_barcode
    ORDER BY bm.created_at ASC LIMIT 500;
END $function$
;


-- ═══ FUNCTION admin_gmv_monthly(p_months integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_gmv_monthly(p_months integer DEFAULT 12)
 RETURNS TABLE(month_key text, month_label text, gmv numeric, completed_gmv numeric, bookings_count integer, completed_count integer, avg_order_value numeric, savings_delivered numeric, unique_buyers integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH months AS (
        SELECT date_trunc('month', now()) - (n || ' months')::INTERVAL AS m
        FROM generate_series(0, GREATEST(p_months, 1) - 1) AS n
    ),
    bk AS (
        SELECT date_trunc('month', b.created_at) AS m,
               COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)), 0) AS gmv,
               COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)) FILTER (WHERE b.status = 'completed'), 0) AS done_gmv,
               COUNT(*) AS cnt,
               COUNT(*) FILTER (WHERE b.status = 'completed') AS done,
               COALESCE(SUM(b.booked_quantity * GREATEST(COALESCE(d.original_price, 0) - COALESCE(d.discounted_price, 0), 0)) FILTER (WHERE b.status = 'completed'), 0) AS save,
               COUNT(DISTINCT b.user_id) AS unique_b
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    )
    SELECT to_char(months.m, 'YYYY-MM')::TEXT,
           to_char(months.m, 'Mon YY')::TEXT,
           COALESCE(bk.gmv, 0)::NUMERIC,
           COALESCE(bk.done_gmv, 0)::NUMERIC,
           COALESCE(bk.cnt, 0)::INT,
           COALESCE(bk.done, 0)::INT,
           CASE WHEN COALESCE(bk.done, 0) = 0 THEN 0 ELSE ROUND(bk.done_gmv / bk.done, 2) END,
           COALESCE(bk.save, 0)::NUMERIC,
           COALESCE(bk.unique_b, 0)::INT
    FROM months
    LEFT JOIN bk ON bk.m = months.m
    ORDER BY months.m ASC;
END;
$function$
;


-- ═══ FUNCTION admin_health_check() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_health_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_result JSONB;
    v_table_counts JSONB;
    v_critical_triggers JSONB;
    v_indexes_present JSONB;
    v_rls_status JSONB;
    v_recent_errors INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    -- Row counts for core tables — quick sanity check
    SELECT jsonb_build_object(
        'users',                  (SELECT COUNT(*) FROM users),
        'sellers',                (SELECT COUNT(*) FROM users WHERE user_type='seller'),
        'buyers',                 (SELECT COUNT(*) FROM users WHERE user_type='buyer'),
        'admins',                 (SELECT COUNT(*) FROM users WHERE user_type='admin'),
        'deals',                  (SELECT COUNT(*) FROM deals),
        'deals_active',           (SELECT COUNT(*) FROM deals WHERE status='active'),
        'bookings',               (SELECT COUNT(*) FROM bookings),
        'bookings_today',         (SELECT COUNT(*) FROM bookings WHERE created_at >= now() - INTERVAL '1 day'),
        'activity_log',           (SELECT COUNT(*) FROM activity_log),
        'activity_today',         (SELECT COUNT(*) FROM activity_log WHERE created_at >= now() - INTERVAL '1 day'),
        'user_sessions',          (SELECT COUNT(*) FROM user_sessions),
        'sessions_recent',        (SELECT COUNT(*) FROM user_sessions WHERE last_seen_at >= now() - INTERVAL '5 minutes'),
        'merchant_subscriptions', (SELECT COUNT(*) FROM merchant_subscriptions),
        'subscription_payments',  (SELECT COUNT(*) FROM subscription_payments),
        'store_profiles',         (SELECT COUNT(*) FROM store_profiles),
        'store_analytics_events', (SELECT COUNT(*) FROM store_analytics_events),
        'notifications',          (SELECT COUNT(*) FROM notifications),
        'ratings',                (SELECT COUNT(*) FROM ratings)
    ) INTO v_table_counts;

    -- Critical triggers — confirm the safety-net triggers exist
    SELECT jsonb_object_agg(tgname, true)
      INTO v_critical_triggers
    FROM pg_trigger
    WHERE NOT tgisinternal
      AND tgname IN (
        'tr_guard_deal_publish',
        'tr_guard_report_insert',
        'tr_guard_complaint_insert',
        'tr_new_seller_trial'
      );

    -- Critical indexes — query plan health
    SELECT jsonb_object_agg(indexname, true)
      INTO v_indexes_present
    FROM pg_indexes
    WHERE schemaname='public'
      AND indexname IN (
        'bookings_user_id_idx',
        'bookings_store_id_idx',
        'deals_store_id_idx',
        'deals_status_idx',
        'activity_log_created_at_idx',
        'user_sessions_last_seen_idx'
      );

    -- RLS status on critical tables
    SELECT jsonb_object_agg(c.relname, c.relrowsecurity)
      INTO v_rls_status
    FROM pg_class c
    JOIN pg_namespace n ON c.relnamespace = n.oid
    WHERE n.nspname = 'public'
      AND c.relname IN ('users','deals','bookings','merchant_subscriptions','subscription_payments','store_profiles','notifications','activity_log');

    v_result := jsonb_build_object(
        'as_of',              now(),
        'admin_user_id',      auth.uid()::TEXT,
        'table_counts',       v_table_counts,
        'critical_triggers',  COALESCE(v_critical_triggers, '{}'::JSONB),
        'critical_indexes',   COALESCE(v_indexes_present, '{}'::JSONB),
        'rls_enabled',        COALESCE(v_rls_status, '{}'::JSONB),
        'db_size_bytes',      (SELECT pg_database_size(current_database()))
    );
    RETURN v_result;
END;
$function$
;


-- ═══ FUNCTION admin_hide_deal(p_deal_id text, p_hide boolean, p_reason text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_hide_deal(p_deal_id text, p_hide boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_d public.deals%ROWTYPE; v_msg text;
BEGIN
  IF NOT public.taki_admin_perm('action_delete_deals') THEN
    RAISE EXCEPTION 'ليست لديك صلاحية إخفاء العروض';
  END IF;
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF p_hide AND COALESCE(btrim(p_reason),'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'REASON_REQUIRED');
  END IF;

  -- 🪤 `tr_guard_deal_publish` يرفض أي `UPDATE OF status` من العميل، وهذه دالة
  -- مالكة فتتجاوزه. ولا نحذف: الإخفاء يُبقي الطلبات والفواتير المرتبطة سليمة.
  UPDATE public.deals SET status = CASE WHEN p_hide THEN 'paused' ELSE 'active' END
   WHERE id = p_deal_id;

  v_msg := CASE WHEN p_hide
    THEN '🚫 أخفت إدارة تاكي عرضك «' || COALESCE(v_d.item_name,'') || '» — ' || btrim(p_reason)
         || '. عدّله ثم راسل الإدارة لإعادته.'
    ELSE '✅ أُعيد عرضك «' || COALESCE(v_d.item_name,'') || '» للظهور.' END;

  IF p_hide THEN
    INSERT INTO public.user_warnings (user_id, user_role, reason, admin_id)
    VALUES (v_d.store_id, 'seller', v_msg, auth.uid()::text);
  END IF;
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (v_d.store_id, CASE WHEN p_hide THEN '🚫 إخفاء عرض' ELSE '✅ إعادة عرض' END,
          CASE WHEN p_hide THEN '🚫 Deal hidden' ELSE '✅ Deal restored' END,
          v_msg, v_msg, 'system',
          jsonb_build_object('audience','seller','dealId', p_deal_id,
                             'actionUrl','/deal/'||p_deal_id,'action_url','/deal/'||p_deal_id));
  RETURN jsonb_build_object('ok', true, 'hidden', p_hide);
END $function$
;


-- ═══ FUNCTION admin_investor_kpis(p_days integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_investor_kpis(p_days integer DEFAULT 30)
 RETURNS TABLE(period_days integer, gmv numeric, gmv_completed numeric, savings_delivered numeric, total_bookings integer, completed_bookings integer, cancelled_bookings integer, avg_order_value numeric, dau integer, wau integer, mau integer, stickiness_pct numeric, total_views integer, unique_viewers integer, conversion_pct numeric, repeat_customer_rate_pct numeric, mom_gmv_growth_pct numeric, mom_bookings_growth_pct numeric, mom_new_users_growth_pct numeric, new_buyers integer, new_sellers integer, net_active_merchants integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_end TIMESTAMPTZ := now();
    v_start TIMESTAMPTZ := now() - (GREATEST(p_days, 1) || ' days')::INTERVAL;
    v_prev_start TIMESTAMPTZ := v_start - (GREATEST(p_days, 1) || ' days')::INTERVAL;
    v_gmv NUMERIC; v_gmv_done NUMERIC; v_save NUMERIC;
    v_total_bk INT; v_done_bk INT; v_canc_bk INT;
    v_dau INT; v_wau INT; v_mau INT;
    v_views INT; v_viewers INT;
    v_buyers INT; v_sellers INT;
    v_repeat_bk INT; v_single_bk INT;
    v_prev_gmv NUMERIC; v_prev_total_bk INT; v_prev_new_users INT;
    v_active_merchants INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    -- Volume (current period)
    SELECT
        COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)), 0),
        COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)) FILTER (WHERE b.status = 'completed'), 0),
        COALESCE(SUM(b.booked_quantity * GREATEST(COALESCE(d.original_price, 0) - COALESCE(d.discounted_price, 0), 0)) FILTER (WHERE b.status = 'completed'), 0),
        COUNT(*),
        COUNT(*) FILTER (WHERE b.status = 'completed'),
        COUNT(*) FILTER (WHERE b.status = 'cancelled')
      INTO v_gmv, v_gmv_done, v_save, v_total_bk, v_done_bk, v_canc_bk
    FROM bookings b
    LEFT JOIN deals d ON d.id = b.deal_id
    WHERE b.created_at >= v_start AND b.created_at <= v_end;

    -- Active users — DAU last 1d, WAU last 7d, MAU last 30d (from activity_log)
    SELECT COUNT(DISTINCT user_id) INTO v_dau
    FROM activity_log
    WHERE created_at >= v_end - INTERVAL '1 day' AND user_id IS NOT NULL;

    SELECT COUNT(DISTINCT user_id) INTO v_wau
    FROM activity_log
    WHERE created_at >= v_end - INTERVAL '7 days' AND user_id IS NOT NULL;

    SELECT COUNT(DISTINCT user_id) INTO v_mau
    FROM activity_log
    WHERE created_at >= v_end - INTERVAL '30 days' AND user_id IS NOT NULL;

    -- Funnel
    SELECT COUNT(*), COUNT(DISTINCT user_id)
      INTO v_views, v_viewers
    FROM activity_log
    WHERE action = 'view_deal' AND created_at >= v_start AND created_at <= v_end;

    -- New buyers / sellers in current period
    SELECT COUNT(*) FILTER (WHERE user_type = 'buyer'),
           COUNT(*) FILTER (WHERE user_type = 'seller')
      INTO v_buyers, v_sellers
    FROM users
    WHERE created_at >= v_start AND created_at <= v_end;

    -- Repeat customer rate: bookers with 2+ bookings / bookers with any booking
    WITH bookers AS (
        SELECT user_id, COUNT(*) AS n
        FROM bookings
        WHERE created_at >= v_start AND created_at <= v_end
          AND status IN ('completed', 'acknowledged')
          AND user_id IS NOT NULL
        GROUP BY user_id
    )
    SELECT COUNT(*) FILTER (WHERE n >= 2), COUNT(*)
      INTO v_repeat_bk, v_single_bk
    FROM bookers;

    -- Previous period for MoM growth
    SELECT COALESCE(SUM(b.booked_quantity * COALESCE(d.discounted_price, 0)), 0),
           COUNT(*)
      INTO v_prev_gmv, v_prev_total_bk
    FROM bookings b
    LEFT JOIN deals d ON d.id = b.deal_id
    WHERE b.created_at >= v_prev_start AND b.created_at < v_start;

    SELECT COUNT(*) INTO v_prev_new_users
    FROM users
    WHERE created_at >= v_prev_start AND created_at < v_start AND user_type = 'buyer';

    -- Net active merchants — sellers who actually had bookings in the window
    SELECT COUNT(DISTINCT b.store_id) INTO v_active_merchants
    FROM bookings b
    WHERE b.created_at >= v_start AND b.created_at <= v_end;

    RETURN QUERY SELECT
        p_days,
        v_gmv, v_gmv_done, v_save,
        v_total_bk, v_done_bk, v_canc_bk,
        CASE WHEN v_done_bk = 0 THEN 0 ELSE ROUND(v_gmv_done / v_done_bk, 2) END,
        v_dau, v_wau, v_mau,
        CASE WHEN v_mau = 0 THEN 0 ELSE ROUND(100.0 * v_dau / v_mau, 1) END,
        v_views, v_viewers,
        CASE WHEN v_viewers = 0 THEN 0 ELSE ROUND(100.0 * v_single_bk / v_viewers, 1) END,
        CASE WHEN v_single_bk = 0 THEN 0 ELSE ROUND(100.0 * v_repeat_bk / v_single_bk, 1) END,
        CASE WHEN v_prev_gmv = 0 THEN
             CASE WHEN v_gmv = 0 THEN 0 ELSE 100 END
             ELSE ROUND(100.0 * (v_gmv - v_prev_gmv) / v_prev_gmv, 1) END,
        CASE WHEN v_prev_total_bk = 0 THEN
             CASE WHEN v_total_bk = 0 THEN 0 ELSE 100 END
             ELSE ROUND(100.0 * (v_total_bk - v_prev_total_bk) / v_prev_total_bk, 1) END,
        CASE WHEN v_prev_new_users = 0 THEN
             CASE WHEN v_buyers = 0 THEN 0 ELSE 100 END
             ELSE ROUND(100.0 * (v_buyers - v_prev_new_users) / v_prev_new_users, 1) END,
        v_buyers, v_sellers, v_active_merchants;
END;
$function$
;


-- ═══ FUNCTION admin_launch_audit() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_launch_audit()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_no_rls int; v_unguarded int; v_anon_write int; v_crons int;
  v_undeclared int; v_vat_rate text; v_gw int; v_gw_ok int;
  v_suspend_ok boolean; v_perm_policies int; v_bare_admin int;
BEGIN
  IF NOT public.taki_admin_perm('tab_launch') THEN RAISE EXCEPTION 'Not allowed'; END IF;

  SELECT count(*) INTO v_no_rls FROM pg_tables t
   WHERE t.schemaname = 'public'
     AND NOT (SELECT relrowsecurity FROM pg_class c
              JOIN pg_namespace n ON n.oid = c.relnamespace
              WHERE c.relname = t.tablename AND n.nspname = 'public');

  SELECT count(*) INTO v_unguarded FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
   WHERE n.nspname = 'public' AND p.proname LIKE 'admin\_%'
     AND pg_get_functiondef(p.oid) NOT LIKE '%is_admin%'
     AND pg_get_functiondef(p.oid) NOT LIKE '%_admin_require_ctx%'
     AND pg_get_functiondef(p.oid) NOT LIKE '%taki_admin_perm%'
     AND pg_get_functiondef(p.oid) NOT LIKE '%is_super_admin%'
     AND pg_get_functiondef(p.oid) NOT LIKE '%user_type%';

  SELECT count(*) INTO v_anon_write FROM information_schema.role_table_grants
   WHERE grantee = 'anon' AND table_schema = 'public'
     AND privilege_type IN ('INSERT','UPDATE','DELETE');

  SELECT count(*) INTO v_crons FROM cron.job WHERE active;

  SELECT count(*) INTO v_undeclared FROM public.users u
   WHERE u.user_type IN ('seller','admin') AND u.deleted_at IS NULL
     AND NOT COALESCE((public.store_can_sell(u.id)->>'ok')::boolean, false);

  SELECT (value #>> '{}') INTO v_vat_rate FROM public.platform_settings WHERE key = 'merchant_vat';
  SELECT count(*), count(*) FILTER (WHERE verified_at IS NOT NULL)
    INTO v_gw, v_gw_ok FROM public.merchant_gateways;

  v_suspend_ok := pg_get_functiondef(to_regprocedure('public.admin_suspend_account(text,boolean,text)'))
                  LIKE '%banned_until%';

  SELECT count(*) INTO v_perm_policies FROM pg_policies
   WHERE schemaname='public' AND (qual LIKE '%taki_admin_perm%' OR with_check LIKE '%taki_admin_perm%');
  SELECT count(*) INTO v_bare_admin FROM pg_policies
   WHERE schemaname='public' AND (qual LIKE '%is_admin%' OR with_check LIKE '%is_admin%')
     AND COALESCE(qual,'') NOT LIKE '%has_admin_permission%'
     AND COALESCE(qual,'') NOT LIKE '%taki_admin_perm%'
     AND COALESCE(with_check,'') NOT LIKE '%taki_admin_perm%';

  RETURN jsonb_build_object('measured_at', now(), 'checks', jsonb_build_array(
    jsonb_build_object('id','rls','ok', v_no_rls = 0,
      'detail', CASE WHEN v_no_rls = 0 THEN 'كل جداول public عليها RLS — قِيس الآن'
                     ELSE v_no_rls || ' جدولاً بلا RLS' END),
    jsonb_build_object('id','admin-rpc','ok', v_unguarded = 0,
      'detail', CASE WHEN v_unguarded = 0 THEN 'كل دوال admin_* عليها حارس — قِيس الآن'
                     ELSE v_unguarded || ' دالة بلا حارس' END),
    jsonb_build_object('id','subperms','ok', v_bare_admin <= 1,
      'detail', v_perm_policies || ' سياسة واعية بالصلاحية الفرعية · ' || v_bare_admin || ' بقيت على is_admin العارية'),
    jsonb_build_object('id','anon-write','ok', v_anon_write = 0,
      'detail', CASE WHEN v_anon_write = 0 THEN 'الزائر لا يملك كتابة على أي جدول'
                     ELSE v_anon_write || ' منح كتابة للزائر' END),
    jsonb_build_object('id','rate-limit','ok', to_regclass('public.rate_limit_counters') IS NOT NULL,
      'detail','مطبَّق في القاعدة منذ v13.15 — لا علاقة له بلوحة supabase.com'),
    jsonb_build_object('id','crons','ok', v_crons >= 15,
      'detail', v_crons || ' مهمة جدولة مفعّلة'),
    jsonb_build_object('id','suspension','ok', v_suspend_ok,
      'detail', CASE WHEN v_suspend_ok THEN 'الإيقاف يمنع الدخول ويُنهي الجلسات — قِيس'
                     ELSE 'الإيقاف يضبط عموداً فقط' END),
    jsonb_build_object('id','attestation','ok', v_undeclared = 0,
      'detail', CASE WHEN v_undeclared = 0 THEN 'كل المتاجر أقرّت بطريقة الحساب'
                     ELSE v_undeclared || ' متجراً لم يُقرّ — عروضه تبقى مسوّدة' END),
    jsonb_build_object('id','vat','ok', COALESCE(v_vat_rate,'0') <> '0',
      'detail','نسبة ضريبة التجار: ' || COALESCE(v_vat_rate,'غير مضبوطة')),
    jsonb_build_object('id','payment','ok', v_gw_ok > 0,
      'detail', v_gw || ' بوابة مسجّلة · ' || v_gw_ok || ' موثّقة'),
    jsonb_build_object('id','backup','ok', NULL,
      'detail','لا يُقاس من القاعدة عمداً: النسخ خارج الخادم. الحارس الحقيقي هو الفحص اليومي على GitHub')
  ));
END $function$
;


-- ═══ FUNCTION admin_list_complaints(p_query text, p_status text, p_limit integer, p_offset integer) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_complaints(p_query text DEFAULT ''::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, created_at timestamp with time zone, category text, subject text, message text, status text, admin_note text, user_id text, user_name text, user_phone text, user_type text, target_id text, target_name text, attachments text[], reply_count integer, last_reply_role text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role TEXT; v_q TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
  SELECT u.user_type INTO v_role FROM public.users u WHERE u.id = auth.uid()::text;
  IF v_role IS DISTINCT FROM 'admin' THEN RAISE EXCEPTION 'Admin only'; END IF;
  v_q := '%' || COALESCE(p_query, '') || '%';

  RETURN QUERY
  SELECT
      c.id, c.created_at, c.category, c.subject, c.message, c.status, c.admin_note,
      c.user_id,
      COALESCE(NULLIF(cu.name,''), cu.shop, '—'),
      cu.phone,
      COALESCE(cu.user_type, c.user_role),
      c.target_id,
      COALESCE(NULLIF(tu.name,''), tu.shop, NULL),
      c.attachments,
      COALESCE(r.cnt, 0)::int,
      r.last_role
  FROM public.complaints c
  LEFT JOIN public.users cu ON cu.id = c.user_id
  LEFT JOIN public.users tu ON tu.id = c.target_id
  LEFT JOIN LATERAL (
      SELECT count(*) AS cnt,
             (SELECT cr2.author_role FROM public.complaint_replies cr2
               WHERE cr2.complaint_id = c.id ORDER BY cr2.created_at DESC LIMIT 1) AS last_role
        FROM public.complaint_replies cr WHERE cr.complaint_id = c.id
  ) r ON true
  WHERE (p_status IS NULL OR c.status = p_status)
    AND (p_query = '' OR
         c.user_id ILIKE v_q OR cu.name ILIKE v_q OR cu.phone ILIKE v_q OR
         c.message ILIKE v_q OR COALESCE(c.subject,'') ILIKE v_q)
  ORDER BY c.created_at DESC
  LIMIT GREATEST(p_limit, 1) OFFSET GREATEST(p_offset, 0);
END;
$function$
;


-- ═══ FUNCTION admin_list_gateways() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_gateways()
 RETURNS TABLE(merchant_id text, store_name text, provider text, payment_modes text, is_enabled boolean, disabled_by_admin boolean, verified_at timestamp with time zone, fail_count integer, key_last4 text, agreement_accepted_at timestamp with time zone, created_at timestamp with time zone, secret_ok boolean, effective_mode text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  RETURN QUERY
  SELECT g.merchant_id, COALESCE(NULLIF(u.shop, ''), u.name) AS store_name, g.provider, g.payment_modes,
         g.is_enabled, g.disabled_by_admin, g.verified_at,
         g.fail_count, g.key_last4, g.agreement_accepted_at, g.created_at,
         public._gateway_secret_live(g.merchant_id) AS secret_ok,
         public.deal_payment_mode(g.merchant_id)    AS effective_mode
  FROM public.merchant_gateways g
  LEFT JOIN public.users u ON u.id = g.merchant_id
  ORDER BY g.created_at DESC;
END $function$
;


-- ═══ FUNCTION admin_list_message_threads(p_search text, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_message_threads(p_search text DEFAULT NULL::text, p_limit integer DEFAULT 100)
 RETURNS TABLE(barcode text, deal_id text, buyer_id text, buyer_name text, buyer_phone text, seller_id text, seller_name text, seller_shop text, booking_status text, message_count bigint, last_body text, last_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_admin(auth.uid()::text) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    RETURN QUERY
    WITH agg AS (
        SELECT bm.barcode,
               COUNT(*) AS message_count,
               MAX(bm.created_at) AS last_at,
               (ARRAY_AGG(bm.body ORDER BY bm.created_at DESC))[1] AS last_body
        FROM public.booking_messages bm
        GROUP BY bm.barcode
    )
    SELECT a.barcode, b.deal_id,
           b.user_id, COALESCE(bu.name, b.user_name), COALESCE(bu.phone, b.user_phone),
           b.store_id, su.name, su.shop,
           b.status, a.message_count, a.last_body, a.last_at
    FROM agg a
    JOIN public.bookings b ON b.barcode = a.barcode
    LEFT JOIN public.users bu ON bu.id = b.user_id
    LEFT JOIN public.users su ON su.id = b.store_id
    WHERE p_search IS NULL OR p_search = '' OR (
        a.barcode ILIKE '%'||p_search||'%'
        OR COALESCE(bu.name,'')  ILIKE '%'||p_search||'%'
        OR COALESCE(su.name,'')  ILIKE '%'||p_search||'%'
        OR COALESCE(su.shop,'')  ILIKE '%'||p_search||'%'
        OR COALESCE(bu.phone,'') ILIKE '%'||p_search||'%'
    )
    ORDER BY a.last_at DESC
    LIMIT GREATEST(1, LEAST(p_limit, 500));
END $function$
;


-- ═══ FUNCTION admin_list_payment_attempts(p_days integer, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_payment_attempts(p_days integer DEFAULT 30, p_limit integer DEFAULT 100)
 RETURNS TABLE(id text, merchant_id text, merchant_name text, merchant_shop text, gateway text, amount numeric, currency text, status text, gateway_reference text, error_message text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT pa.id::TEXT, pa.merchant_id::TEXT,
           u.name::TEXT, u.shop::TEXT,
           pa.gateway::TEXT, pa.amount, pa.currency::TEXT, pa.status::TEXT,
           pa.gateway_reference::TEXT, pa.error_message::TEXT, pa.created_at
    FROM payment_attempts pa
    LEFT JOIN users u ON u.id = pa.merchant_id
    WHERE pa.created_at >= now() - (GREATEST(p_days, 1) || ' days')::INTERVAL
    ORDER BY pa.created_at DESC
    LIMIT GREATEST(p_limit, 1);
END;
$function$
;


-- ═══ FUNCTION admin_list_platform_settings() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_platform_settings()
 RETURNS TABLE(key text, value jsonb, description text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT ps.key::TEXT, ps.value, ps.description::TEXT, ps.updated_at
    FROM platform_settings ps
    ORDER BY ps.key ASC;
END;
$function$
;


-- ═══ FUNCTION admin_list_reports(p_query text, p_reported_role text, p_type text, p_status text, p_days integer, p_limit integer, p_offset integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_reports(p_query text DEFAULT ''::text, p_reported_role text DEFAULT NULL::text, p_type text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_days integer DEFAULT 0, p_limit integer DEFAULT 100, p_offset integer DEFAULT 0)
 RETURNS TABLE(id uuid, created_at timestamp with time zone, report_type text, reason text, status text, admin_note text, reporter_id text, reporter_name text, reporter_phone text, reporter_role text, reporter_filed_count bigint, reported_id text, reported_name text, reported_phone text, reported_role text, reported_under_review boolean, reported_received_count bigint, reported_distinct_reporters bigint)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_role TEXT;
    v_q TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT u.user_type INTO v_role FROM public.users u WHERE u.id = auth.uid()::text;
    IF v_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    v_q := '%' || COALESCE(p_query, '') || '%';

    RETURN QUERY
    SELECT
        r.id, r.created_at, r.report_type, r.reason, r.status, r.admin_note,
        r.reporter_id,
        COALESCE(NULLIF(ru.name,''), ru.shop, '—'),
        ru.phone, r.reporter_role,
        (SELECT COUNT(*) FROM public.reports rf WHERE rf.reporter_id = r.reporter_id),
        r.reported_id,
        COALESCE(NULLIF(du.name,''), du.shop, '—'),
        du.phone, r.reported_role,
        COALESCE(du.under_review, FALSE),
        (SELECT COUNT(*) FROM public.reports rc
            WHERE rc.reported_id = r.reported_id AND rc.status <> 'dismissed'),
        (SELECT COUNT(DISTINCT rd.reporter_id) FROM public.reports rd
            WHERE rd.reported_id = r.reported_id AND rd.status <> 'dismissed'
              AND rd.created_at > NOW() - INTERVAL '14 days')
    FROM public.reports r
    LEFT JOIN public.users ru ON ru.id = r.reporter_id
    LEFT JOIN public.users du ON du.id = r.reported_id
    WHERE (p_reported_role IS NULL OR r.reported_role = p_reported_role)
      AND (p_type   IS NULL OR r.report_type = p_type)
      AND (p_status IS NULL OR r.status = p_status)
      AND (p_days  <= 0 OR r.created_at > NOW() - (p_days || ' days')::INTERVAL)
      AND (
          p_query = '' OR
          r.reporter_id ILIKE v_q OR r.reported_id ILIKE v_q OR
          ru.name ILIKE v_q OR du.name ILIKE v_q OR
          ru.shop ILIKE v_q OR du.shop ILIKE v_q OR
          ru.phone ILIKE v_q OR du.phone ILIKE v_q OR
          r.reason ILIKE v_q
      )
    ORDER BY r.created_at DESC
    LIMIT GREATEST(p_limit, 1) OFFSET GREATEST(p_offset, 0);
END $function$
;


-- ═══ FUNCTION admin_list_sponsors() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_sponsors()
 RETURNS TABLE(store_id text, store_name text, shop text, is_active boolean, target_category text, target_city text, target_region text, target_radius_km double precision, priority integer, starts_at timestamp with time zone, expires_at timestamp with time zone, notes text, label_type text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_admin(auth.uid()::text) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    RETURN QUERY
    SELECT s.store_id, u.name, u.shop, s.is_active, s.target_category,
           s.target_city, s.target_region, s.target_radius_km, s.priority,
           s.starts_at, s.expires_at, s.notes, s.label_type
    FROM public.sponsors s JOIN public.users u ON u.id = s.store_id
    ORDER BY s.priority DESC, s.created_at DESC;
END $function$
;


-- ═══ FUNCTION admin_list_staff() DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_staff()
 RETURNS TABLE(id text, name text, email text, phone text, user_type text, is_super_admin boolean, admin_permissions text[], created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  RETURN QUERY
    SELECT u.id, u.name, u.email, u.phone, u.user_type,
           u.is_super_admin, u.admin_permissions, u.created_at
    FROM public.users u
    WHERE u.user_type = 'admin'
    ORDER BY u.is_super_admin DESC, u.created_at NULLS LAST;
END;
$function$
;


-- ═══ FUNCTION admin_list_store_name_requests(p_status text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_store_name_requests(p_status text DEFAULT 'requested'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT COALESCE(jsonb_agg(to_jsonb(t) ORDER BY t.requested_at DESC), '[]'::jsonb) INTO v
  FROM (SELECT r.*, u.name AS owner_name, u.phone AS owner_phone
        FROM public.store_name_requests r JOIN public.users u ON u.id = r.store_id
        WHERE p_status IS NULL OR r.status = p_status) t;
  RETURN jsonb_build_object('ok', true, 'rows', v);
END $function$
;


-- ═══ FUNCTION admin_list_verifications(p_status text, p_limit integer, p_cursor timestamp with time zone) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_verifications(p_status text DEFAULT 'submitted'::text, p_limit integer DEFAULT 50, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_rows jsonb;
BEGIN
  IF NOT public.taki_admin_perm('tab_verification') THEN
    RAISE EXCEPTION 'غير مصرّح' USING ERRCODE = '42501'; END IF;
  SELECT jsonb_agg(x ORDER BY (x->>'submitted_at') DESC) INTO v_rows FROM (
    SELECT jsonb_build_object(
      'id', v.id, 'store_id', v.store_id, 'shop', u.shop, 'owner_name', u.name,
      'owner_phone', u.phone, 'owner_email', u.email,
      'doc_kind', v.doc_kind, 'doc_number', v.doc_number, 'claimed_name', v.claimed_name,
      'legal_name', v.legal_name, 'doc_expiry', v.doc_expiry, 'status', v.status,
      'reject_code', v.reject_code, 'admin_note', v.admin_note,
      'submitted_at', v.submitted_at, 'decided_at', v.decided_at,
      'dup_number', EXISTS (SELECT 1 FROM public.store_verifications d
                             WHERE d.id <> v.id AND d.status IN ('submitted','approved')
                               AND d.doc_kind = v.doc_kind
                               AND lower(btrim(d.doc_number)) = lower(btrim(v.doc_number))),
      'name_matches', (public.taki_norm(COALESCE(v.claimed_name,'')) = public.taki_norm(COALESCE(u.shop,'')))
    ) AS x
      FROM public.store_verifications v JOIN public.users u ON u.id = v.store_id
     WHERE (p_status IS NULL OR v.status = p_status)
       AND (p_cursor IS NULL OR v.submitted_at < p_cursor)
     ORDER BY v.submitted_at DESC LIMIT GREATEST(1, LEAST(200, p_limit))
  ) s;
  RETURN jsonb_build_object('ok', true, 'rows', COALESCE(v_rows, '[]'::jsonb));
END
$function$
;


-- ═══ FUNCTION admin_list_warned_users(p_role text, p_min_count integer, p_search text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_list_warned_users(p_role text DEFAULT NULL::text, p_min_count integer DEFAULT 1, p_search text DEFAULT ''::text)
 RETURNS TABLE(user_id text, name text, phone text, user_type text, is_suspended boolean, warn_count integer, last_warned_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  RETURN QUERY
    SELECT t.user_id, t.name, t.phone, t.user_type, t.is_suspended, t.warn_count, t.last_warned_at
    FROM (
      SELECT w.user_id,
        u.name, u.phone, u.user_type, COALESCE(u.is_suspended, false) AS is_suspended,
        count(*)::int AS warn_count,
        max(w.created_at) AS last_warned_at
      FROM user_warnings w
      LEFT JOIN users u ON u.id = w.user_id
      WHERE (p_role IS NULL OR u.user_type = p_role)
        AND (COALESCE(TRIM(p_search), '') = ''
             OR u.name ILIKE '%' || p_search || '%'
             OR u.phone ILIKE '%' || p_search || '%'
             OR w.user_id ILIKE '%' || p_search || '%')
      GROUP BY w.user_id, u.name, u.phone, u.user_type, u.is_suspended
    ) t
    WHERE t.warn_count >= GREATEST(1, COALESCE(p_min_count, 1))
    ORDER BY t.warn_count DESC, t.last_warned_at DESC;
END $function$
;


-- ═══ FUNCTION admin_lookup_by_date(p_date date) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_lookup_by_date(p_date date)
 RETURNS TABLE(target_date date, views_count integer, unique_viewers integer, bookings_count integer, unique_bookers integer, completed_bookings integer, cancelled_bookings integer, gmv numeric, savings_delivered numeric, new_buyers integer, new_sellers integer, active_users integer, total_events integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_start TIMESTAMPTZ;
    v_end TIMESTAMPTZ;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    v_start := p_date::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';
    v_end := (p_date + 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';

    RETURN QUERY
    WITH al AS (
        SELECT * FROM activity_log
        WHERE created_at >= v_start AND created_at < v_end
    ),
    bk AS (
        SELECT b.*, d.discounted_price, d.original_price
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= v_start AND b.created_at < v_end
    )
    SELECT p_date,
        (SELECT COUNT(*) FROM al WHERE action = 'view_deal')::INT,
        (SELECT COUNT(DISTINCT user_id) FROM al WHERE action = 'view_deal' AND user_id IS NOT NULL)::INT,
        (SELECT COUNT(*) FROM bk)::INT,
        (SELECT COUNT(DISTINCT user_id) FROM bk WHERE user_id IS NOT NULL)::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'completed')::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'cancelled')::INT,
        (SELECT COALESCE(SUM(booked_quantity * COALESCE(discounted_price, 0)), 0) FROM bk WHERE status IN ('completed', 'acknowledged'))::NUMERIC,
        (SELECT COALESCE(SUM(booked_quantity * GREATEST(COALESCE(original_price, 0) - COALESCE(discounted_price, 0), 0)), 0) FROM bk WHERE status = 'completed')::NUMERIC,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'buyer')::INT,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'seller')::INT,
        (SELECT COUNT(DISTINCT user_id) FROM al WHERE user_id IS NOT NULL)::INT,
        (SELECT COUNT(*) FROM al)::INT;
END;
$function$
;


-- ═══ FUNCTION admin_lookup_by_month(p_year integer, p_month integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_lookup_by_month(p_year integer, p_month integer)
 RETURNS TABLE(label text, views_count integer, bookings_count integer, completed_bookings integer, gmv numeric, savings_delivered numeric, new_buyers integer, active_users integer, daily_breakdown jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_start TIMESTAMPTZ;
    v_end TIMESTAMPTZ;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    v_start := make_date(p_year, p_month, 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';
    v_end := (make_date(p_year, p_month, 1) + INTERVAL '1 month')::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';

    RETURN QUERY
    WITH al AS (
        SELECT * FROM activity_log
        WHERE created_at >= v_start AND created_at < v_end
    ),
    bk AS (
        SELECT b.*, d.discounted_price, d.original_price
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= v_start AND b.created_at < v_end
    ),
    daily AS (
        SELECT (al.created_at AT TIME ZONE 'Asia/Riyadh')::DATE AS d,
               COUNT(*) FILTER (WHERE al.action = 'view_deal') AS views,
               COUNT(*) FILTER (WHERE al.action = 'book') AS books
        FROM al
        GROUP BY 1
        ORDER BY 1
    )
    SELECT to_char(v_start, 'Mon YYYY')::TEXT,
        (SELECT COUNT(*) FROM al WHERE action = 'view_deal')::INT,
        (SELECT COUNT(*) FROM bk)::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'completed')::INT,
        (SELECT COALESCE(SUM(booked_quantity * COALESCE(discounted_price, 0)), 0) FROM bk WHERE status IN ('completed', 'acknowledged'))::NUMERIC,
        (SELECT COALESCE(SUM(booked_quantity * GREATEST(COALESCE(original_price, 0) - COALESCE(discounted_price, 0), 0)), 0) FROM bk WHERE status = 'completed')::NUMERIC,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'buyer')::INT,
        (SELECT COUNT(DISTINCT user_id) FROM al WHERE user_id IS NOT NULL)::INT,
        COALESCE((SELECT jsonb_agg(jsonb_build_object('day', to_char(d, 'YYYY-MM-DD'), 'views', views, 'books', books) ORDER BY d) FROM daily), '[]'::jsonb);
END;
$function$
;


-- ═══ FUNCTION admin_lookup_by_year(p_year integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_lookup_by_year(p_year integer)
 RETURNS TABLE(label text, views_count integer, bookings_count integer, completed_bookings integer, gmv numeric, savings_delivered numeric, new_buyers integer, new_sellers integer, monthly_breakdown jsonb)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_start TIMESTAMPTZ;
    v_end TIMESTAMPTZ;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    v_start := make_date(p_year, 1, 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';
    v_end := make_date(p_year + 1, 1, 1)::TIMESTAMPTZ AT TIME ZONE 'Asia/Riyadh';

    RETURN QUERY
    WITH al AS (
        SELECT * FROM activity_log
        WHERE created_at >= v_start AND created_at < v_end
    ),
    bk AS (
        SELECT b.*, d.discounted_price, d.original_price
        FROM bookings b
        LEFT JOIN deals d ON d.id = b.deal_id
        WHERE b.created_at >= v_start AND b.created_at < v_end
    ),
    monthly AS (
        SELECT date_trunc('month', al.created_at AT TIME ZONE 'Asia/Riyadh') AS m,
               COUNT(*) FILTER (WHERE al.action = 'view_deal') AS views,
               COUNT(*) FILTER (WHERE al.action = 'book') AS books
        FROM al
        GROUP BY 1
    ),
    monthly_bk AS (
        SELECT date_trunc('month', bk.created_at AT TIME ZONE 'Asia/Riyadh') AS m,
               COALESCE(SUM(bk.booked_quantity * COALESCE(bk.discounted_price, 0)) FILTER (WHERE bk.status IN ('completed','acknowledged')), 0) AS gmv
        FROM bk
        GROUP BY 1
    )
    SELECT p_year::TEXT,
        (SELECT COUNT(*) FROM al WHERE action = 'view_deal')::INT,
        (SELECT COUNT(*) FROM bk)::INT,
        (SELECT COUNT(*) FROM bk WHERE status = 'completed')::INT,
        (SELECT COALESCE(SUM(booked_quantity * COALESCE(discounted_price, 0)), 0) FROM bk WHERE status IN ('completed', 'acknowledged'))::NUMERIC,
        (SELECT COALESCE(SUM(booked_quantity * GREATEST(COALESCE(original_price, 0) - COALESCE(discounted_price, 0), 0)), 0) FROM bk WHERE status = 'completed')::NUMERIC,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'buyer')::INT,
        (SELECT COUNT(*) FROM users WHERE created_at >= v_start AND created_at < v_end AND user_type = 'seller')::INT,
        COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'month', to_char(m, 'Mon YYYY'),
            'month_key', to_char(m, 'YYYY-MM'),
            'views', COALESCE(monthly.views, 0),
            'books', COALESCE(monthly.books, 0),
            'gmv', COALESCE(monthly_bk.gmv, 0)
        ) ORDER BY m)
        FROM (SELECT DISTINCT m FROM monthly UNION SELECT DISTINCT m FROM monthly_bk) all_months
        LEFT JOIN monthly USING (m)
        LEFT JOIN monthly_bk USING (m)
        ), '[]'::jsonb);
END;
$function$
;


-- ═══ FUNCTION admin_moderation_flags(p_store text, p_status text, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_moderation_flags(p_store text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_limit integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', t.id, 'kind', t.kind, 'source', t.source, 'ref_id', t.ref_id,
      'store_id', t.store_id, 'offender_id', t.offender_id, 'offender_name', t.offender_name,
      'content', t.content, 'matched', t.matched, 'status', t.status,
      'created_at', t.created_at) ORDER BY t.created_at DESC), '[]'::jsonb)
    INTO v
    FROM (
      SELECT mf.* FROM moderation_flags mf
       WHERE (p_store IS NULL OR mf.store_id = p_store OR mf.offender_id = p_store)
         AND (p_status IS NULL OR mf.status = p_status)
       ORDER BY mf.created_at DESC
       LIMIT greatest(1, least(coalesce(p_limit, 200), 2000))
    ) t;
  RETURN coalesce(v, '[]'::jsonb);
END $function$
;


-- ═══ FUNCTION admin_moderation_overview(p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_moderation_overview(p_limit integer DEFAULT 100)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  SELECT jsonb_build_object(
    'total_open', (SELECT count(*) FROM moderation_flags mf2 WHERE mf2.status = 'open'),
    'stores', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'store_id', t.store_id, 'shop', t.shop,
        'flags', t.flags, 'open', t.open_flags,
        'chat', t.chat, 'rating', t.rating, 'deal', t.deal, 'upload', t.upload,
        'last_at', t.last_at) ORDER BY t.open_flags DESC, t.flags DESC)
      FROM (
        SELECT mf.store_id,
               coalesce(max(mf.offender_name), mf.store_id) AS shop,
               count(*) AS flags,
               count(*) FILTER (WHERE mf.status = 'open') AS open_flags,
               count(*) FILTER (WHERE mf.source = 'chat') AS chat,
               count(*) FILTER (WHERE mf.source = 'rating') AS rating,
               count(*) FILTER (WHERE mf.source = 'deal') AS deal,
               count(*) FILTER (WHERE mf.source = 'upload') AS upload,
               max(mf.created_at) AS last_at
          FROM moderation_flags mf
         WHERE mf.store_id IS NOT NULL
         GROUP BY mf.store_id
         ORDER BY count(*) FILTER (WHERE mf.status = 'open') DESC, count(*) DESC
         LIMIT greatest(1, least(coalesce(p_limit, 100), 1000))
      ) t), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END $function$
;


-- ═══ FUNCTION admin_mrr_monthly(p_months integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_mrr_monthly(p_months integer DEFAULT 12)
 RETURNS TABLE(month_key text, month_label text, paid_amount numeric, paid_count integer, refunded_amount numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH months AS (
        SELECT date_trunc('month', now()) - (n || ' months')::INTERVAL AS m
        FROM generate_series(0, GREATEST(p_months, 1) - 1) AS n
    ),
    paid AS (
        SELECT date_trunc('month', paid_at) AS m,
               SUM(amount) FILTER (WHERE status = 'paid') AS amt,
               COUNT(*) FILTER (WHERE status = 'paid') AS cnt,
               SUM(amount) FILTER (WHERE status = 'refunded') AS refunded
        FROM subscription_payments
        WHERE paid_at IS NOT NULL
          AND paid_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    )
    SELECT to_char(months.m, 'YYYY-MM')::TEXT,
           to_char(months.m, 'Mon YY')::TEXT,
           COALESCE(paid.amt, 0)::NUMERIC,
           COALESCE(paid.cnt, 0)::INT,
           COALESCE(paid.refunded, 0)::NUMERIC
    FROM months
    LEFT JOIN paid ON paid.m = months.m
    ORDER BY months.m ASC;
END;
$function$
;


-- ═══ FUNCTION admin_my_permissions() DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_my_permissions()
 RETURNS TABLE(is_super_admin boolean, admin_permissions text[])
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN
    RAISE EXCEPTION 'forbidden: admin required';
  END IF;
  RETURN QUERY
    SELECT u.is_super_admin, u.admin_permissions
    FROM public.users u
    WHERE u.id = auth.uid()::text;
END;
$function$
;


-- ═══ FUNCTION admin_notify_user(p_user_id text, p_title_ar text, p_body_ar text, p_email boolean) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_notify_user(p_user_id text, p_title_ar text, p_body_ar text, p_email boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_emailed boolean := false;
BEGIN
    IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
    IF COALESCE(btrim(p_title_ar),'') = '' OR p_user_id IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'missing_fields');
    END IF;
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES (p_user_id, p_title_ar, p_title_ar, COALESCE(p_body_ar,''), COALESCE(p_body_ar,''),
            'system', jsonb_build_object('from_analyst', true), NOW());
    IF p_email THEN
        v_emailed := public.taki_queue_email(
          p_user_id, 'analyst_tip', p_title_ar,
          public.taki_email_wrap(p_title_ar,
            '<p style="font-size:15px;line-height:1.9;margin:0">'
            || replace(replace(replace(replace(COALESCE(p_body_ar,''),'&','&amp;'),'<','&lt;'),'>','&gt;'), E'\n', '<br>')
            || '</p>'));
    END IF;
    RETURN jsonb_build_object('success', true, 'emailed', v_emailed);
END $function$
;


-- ═══ FUNCTION admin_open_verification_grace(p_until timestamp with time zone) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_open_verification_grace(p_until timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n int;
BEGIN
  IF NOT public.taki_admin_perm('tab_verification') THEN
    RAISE EXCEPTION 'غير مصرّح' USING ERRCODE = '42501'; END IF;
  IF p_until IS NULL OR p_until <= now() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_DATE'); END IF;
  INSERT INTO public.store_verification_grace (store_id, until, opened_by)
  SELECT u.id, p_until, (SELECT auth.uid())::text
    FROM public.users u
   WHERE u.user_type = 'seller' AND u.deleted_at IS NULL
     AND EXISTS (SELECT 1 FROM public.store_profiles sp WHERE sp.store_id = u.id)
  ON CONFLICT (store_id) DO UPDATE SET until = EXCLUDED.until, opened_by = EXCLUDED.opened_by, opened_at = now();
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN jsonb_build_object('ok', true, 'stores', n, 'until', p_until);
END
$function$
;


-- ═══ FUNCTION admin_operations_log(p_limit integer, p_cursor timestamp with time zone, p_action text, p_q text, p_cursor_id bigint) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_operations_log(p_limit integer DEFAULT 30, p_cursor timestamp with time zone DEFAULT NULL::timestamp with time zone, p_action text DEFAULT NULL::text, p_q text DEFAULT NULL::text, p_cursor_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_lim   int  := GREATEST(1, LEAST(100, COALESCE(p_limit, 30)));
  v_code  text := NULLIF(regexp_replace(lower(COALESCE(p_q, '')), '\s', '', 'g'), '');
  v_name  text;
  v_rows  jsonb;
  v_n     int;
  v_last  timestamptz;
  v_lastid bigint;
  v_stats jsonb := NULL;
  v_day   timestamptz;
BEGIN
  IF NOT public.taki_admin_perm('tab_tools') THEN
    RAISE EXCEPTION 'غير مصرّح' USING ERRCODE = '42501';
  END IF;

  -- 🪤 العربية تُطبَّع على الطرفين معاً وإلا سقط «الراشد» أمام «راشد» (v13.25).
  v_name := NULLIF(public.taki_norm(COALESCE(p_q, '')), '');

  -- 🪤 كلُّ هذا في استعلامٍ واحد لا في جدولٍ مؤقّت: الدالّة `STABLE`، ودالّةٌ
  --    غير `VOLATILE` لا يُسمح لها بـ`CREATE`/`INSERT` إطلاقاً. وجعلُها
  --    `VOLATILE` لأجل جدولٍ مؤقّت ثمنٌ بلا مقابل.
  WITH page AS (
      SELECT a.*
        FROM public.activity_log a
       WHERE (p_action IS NULL OR a.action = p_action)
         AND (p_cursor IS NULL
              OR (p_cursor_id IS NULL     AND a.created_at < p_cursor)
              OR (p_cursor_id IS NOT NULL AND (a.created_at, a.id) < (p_cursor, p_cursor_id)))
         AND (
              v_code IS NULL
              OR position(v_code IN lower(COALESCE(a.entity_id, ''))) > 0
              OR (v_name IS NOT NULL AND EXISTS (
                   SELECT 1 FROM public.users u
                    WHERE u.id IN (a.user_id, a.metadata->>'store_id', a.metadata->>'buyer_id')
                      AND public.taki_norm(COALESCE(u.shop,'') || ' ' || COALESCE(u.name,''))
                          LIKE '%' || v_name || '%'))
             )
       ORDER BY a.created_at DESC, a.id DESC
       LIMIT v_lim
  ), shaped AS (
      SELECT p.id, p.created_at,
             jsonb_build_object(
               'id',          p.id,
               'at',          p.created_at,
               'action',      p.action,
               'entity_type', p.entity_type,
               'code',        p.entity_id,
               'actor_id',    p.user_id,
               'actor_type',  p.user_type,
               'actor_name',  COALESCE(NULLIF(ua.name,''), NULLIF(ua.shop,'')),
               'store_id',    p.metadata->>'store_id',
               'store_name',  COALESCE(NULLIF(us.shop,''), NULLIF(us.name,'')),
               'buyer_id',    p.metadata->>'buyer_id',
               'buyer_name',  COALESCE(NULLIF(ub.name,''), NULLIF(ub.shop,'')),
               'deal_id',     p.metadata->>'deal_id',
               'quantity',    CASE WHEN jsonb_typeof(p.metadata->'quantity') = 'number'
                                   THEN (p.metadata->>'quantity')::numeric END,
               'amount',      CASE WHEN jsonb_typeof(p.metadata->'amount') = 'number'
                                   THEN (p.metadata->>'amount')::numeric END,
               'event',       p.metadata->>'event',
               'meta',        COALESCE(p.metadata, '{}'::jsonb)
             ) AS x
        FROM page p
        LEFT JOIN public.users ua ON ua.id = p.user_id
        LEFT JOIN public.users us ON us.id = p.metadata->>'store_id'
        LEFT JOIN public.users ub ON ub.id = p.metadata->>'buyer_id'
  )
  SELECT jsonb_agg(s.x ORDER BY s.created_at DESC, s.id DESC),
         count(*)::int,
         (array_agg(s.created_at ORDER BY s.created_at ASC, s.id ASC))[1],
         (array_agg(s.id         ORDER BY s.created_at ASC, s.id ASC))[1]
    INTO v_rows, v_n, v_last, v_lastid
    FROM shaped s;

  -- الأرقام تُحسب للصفحة الأولى وحدها، وهي **عن السجلّ كلّه** لا عن المرشِّح.
  IF p_cursor IS NULL THEN
    v_day := date_trunc('day', now() AT TIME ZONE 'Asia/Riyadh') AT TIME ZONE 'Asia/Riyadh';
    SELECT jsonb_build_object(
      'today',   (SELECT count(*) FROM public.activity_log WHERE created_at >= v_day),
      'week',    (SELECT count(*) FROM public.activity_log WHERE created_at >= v_day - interval '6 days'),
      'total',   (SELECT count(*) FROM public.activity_log),
      'latest_code', (SELECT a.entity_id FROM public.activity_log a
                       WHERE a.entity_type = 'booking' AND a.entity_id IS NOT NULL
                       ORDER BY a.created_at DESC, a.id DESC LIMIT 1),
      'latest_at',   (SELECT a.created_at FROM public.activity_log a
                       WHERE a.entity_type = 'booking' AND a.entity_id IS NOT NULL
                       ORDER BY a.created_at DESC, a.id DESC LIMIT 1),
      'actions', COALESCE((
          SELECT jsonb_agg(jsonb_build_object('action', t.action, 'n', t.n) ORDER BY t.n DESC)
            FROM (SELECT a.action AS action, count(*) AS n
                    FROM public.activity_log a GROUP BY a.action) t), '[]'::jsonb)
    ) INTO v_stats;
  END IF;

  RETURN jsonb_build_object(
    'ok', true,
    'rows', COALESCE(v_rows, '[]'::jsonb),
    -- صفحةٌ ناقصة = لا مزيد. ولا يُعاد مؤشّرٌ لصفحةٍ فارغة.
    'next_cursor',    CASE WHEN v_n = v_lim THEN to_jsonb(v_last)   ELSE 'null'::jsonb END,
    'next_cursor_id', CASE WHEN v_n = v_lim THEN to_jsonb(v_lastid) ELSE 'null'::jsonb END,
    'stats', COALESCE(v_stats, 'null'::jsonb)
  );
END
$function$
;


-- ═══ FUNCTION admin_payment_gateway_status() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_payment_gateway_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_enabled BOOLEAN;
    v_provider TEXT;
    v_pub_key TEXT;
    v_webhook_url TEXT;
    v_has_secret BOOLEAN := FALSE; -- secret key is server-side only; we don't read it client-facing
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    SELECT (value)::BOOLEAN INTO v_enabled FROM platform_settings WHERE key='payment_gateway_enabled';
    SELECT (value #>> '{}')::TEXT INTO v_provider FROM platform_settings WHERE key='payment_gateway_provider';
    SELECT (value #>> '{}')::TEXT INTO v_pub_key FROM platform_settings WHERE key='payment_gateway_publishable_key';
    SELECT (value #>> '{}')::TEXT INTO v_webhook_url FROM platform_settings WHERE key='payment_gateway_webhook_url';

    RETURN jsonb_build_object(
        'enabled',              COALESCE(v_enabled, FALSE),
        'provider',             COALESCE(v_provider, ''),
        'has_publishable_key',  v_pub_key IS NOT NULL AND length(v_pub_key) > 8,
        'publishable_key_hint', CASE
                                  WHEN v_pub_key IS NULL OR length(v_pub_key) < 8 THEN NULL
                                  ELSE substring(v_pub_key from 1 for 8) || '…'
                                END,
        'webhook_url',          COALESCE(v_webhook_url, ''),
        'has_secret_configured', v_has_secret,
        'attempts_total',       (SELECT COUNT(*) FROM payment_attempts),
        'attempts_paid',        (SELECT COUNT(*) FROM payment_attempts WHERE status='paid'),
        'attempts_failed',      (SELECT COUNT(*) FROM payment_attempts WHERE status='failed')
    );
END;
$function$
;


-- ═══ FUNCTION admin_payment_log(p_from timestamp with time zone, p_to timestamp with time zone, p_merchant text, p_provider text, p_status text, p_before_id bigint, p_limit integer, p_search text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_payment_log(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_merchant text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_before_id bigint DEFAULT NULL::bigint, p_limit integer DEFAULT 50, p_search text DEFAULT NULL::text)
 RETURNS TABLE(id bigint, booking_barcode text, merchant_id text, merchant_name text, buyer_id text, buyer_name text, amount numeric, vat_amount numeric, provider text, payment_ref text, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_q text := NULLIF(btrim(COALESCE(p_search, '')), '');
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  RETURN QUERY
  SELECT l.id, l.booking_barcode, l.merchant_id,
         COALESCE(NULLIF(um.shop, ''), um.name) AS merchant_name,
         l.buyer_id, ub.name AS buyer_name,
         l.amount, l.vat_amount, l.provider, l.payment_ref, l.status, l.created_at
  FROM public.platform_payment_log l
  LEFT JOIN public.users um ON um.id = l.merchant_id
  LEFT JOIN public.users ub ON ub.id = l.buyer_id
  WHERE (p_from IS NULL OR l.created_at >= p_from)
    AND (p_to   IS NULL OR l.created_at <  p_to)
    AND (p_merchant IS NULL OR l.merchant_id = p_merchant)
    AND (p_provider IS NULL OR l.provider = p_provider)
    AND (p_status   IS NULL OR l.status = p_status)
    AND (p_before_id IS NULL OR l.id < p_before_id)
    AND (v_q IS NULL
         OR l.booking_barcode LIKE upper(v_q) || '%'
         OR l.payment_ref LIKE v_q || '%'
         OR (v_q ~ '^[0-9]+$' AND l.id = v_q::bigint))
  ORDER BY l.id DESC
  LIMIT LEAST(GREATEST(COALESCE(p_limit, 50), 1), 100);
END $function$
;


-- ═══ FUNCTION admin_payment_log_export(p_from timestamp with time zone, p_to timestamp with time zone, p_merchant text, p_provider text, p_status text, p_before_id bigint) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_payment_log_export(p_from timestamp with time zone, p_to timestamp with time zone, p_merchant text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_status text DEFAULT NULL::text, p_before_id bigint DEFAULT NULL::bigint)
 RETURNS TABLE(id bigint, booking_barcode text, merchant_id text, merchant_name text, buyer_id text, amount numeric, vat_amount numeric, provider text, payment_ref text, status text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  IF p_from IS NULL OR p_to IS NULL THEN RAISE EXCEPTION 'RANGE_REQUIRED'; END IF;
  IF p_to - p_from > interval '32 days' THEN RAISE EXCEPTION 'RANGE_TOO_WIDE'; END IF;
  RETURN QUERY
  SELECT l.id, l.booking_barcode, l.merchant_id,
         COALESCE(NULLIF(um.shop, ''), um.name) AS merchant_name,
         l.buyer_id, l.amount, l.vat_amount, l.provider, l.payment_ref, l.status, l.created_at
  FROM public.platform_payment_log l
  LEFT JOIN public.users um ON um.id = l.merchant_id
  WHERE l.created_at >= p_from AND l.created_at < p_to
    AND (p_merchant IS NULL OR l.merchant_id = p_merchant)
    AND (p_provider IS NULL OR l.provider = p_provider)
    AND (p_status   IS NULL OR l.status = p_status)
    AND (p_before_id IS NULL OR l.id < p_before_id)
  ORDER BY l.id DESC
  LIMIT 10000;
END $function$
;


-- ═══ FUNCTION admin_payment_log_stats(p_from timestamp with time zone, p_to timestamp with time zone, p_merchant text, p_provider text, p_status text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_payment_log_stats(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_merchant text DEFAULT NULL::text, p_provider text DEFAULT NULL::text, p_status text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_out jsonb;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  SELECT jsonb_build_object(
    'count',     COUNT(*),
    'total',     COALESCE(SUM(l.amount), 0),
    'vat_total', COALESCE(SUM(l.vat_amount), 0)
  ) INTO v_out
  FROM public.platform_payment_log l
  WHERE (p_from IS NULL OR l.created_at >= p_from)
    AND (p_to   IS NULL OR l.created_at <  p_to)
    AND (p_merchant IS NULL OR l.merchant_id = p_merchant)
    AND (p_provider IS NULL OR l.provider = p_provider)
    AND (p_status   IS NULL OR l.status = p_status);
  RETURN v_out;
END $function$
;


-- ═══ FUNCTION admin_promote_user(target_id text, perms text[]) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_promote_user(target_id text, perms text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  current_role TEXT;
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  IF target_id IS NULL OR target_id = '' THEN
    RAISE EXCEPTION 'target_id required';
  END IF;
  SELECT u.user_type INTO current_role FROM public.users u WHERE u.id = target_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'user not found';
  END IF;
  -- Refuse if already a super admin (would be a privilege downgrade attempt).
  IF EXISTS (SELECT 1 FROM public.users u WHERE u.id = target_id AND u.is_super_admin = TRUE) THEN
    RAISE EXCEPTION 'cannot modify super admin permissions via this RPC';
  END IF;
  UPDATE public.users u
  SET user_type = 'admin',
      is_super_admin = FALSE,
      admin_permissions = COALESCE(perms, '{}'::TEXT[])
  WHERE u.id = target_id;
END;
$function$
;


-- ═══ FUNCTION admin_range_summary(p_from timestamp with time zone, p_to timestamp with time zone) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_range_summary(p_from timestamp with time zone, p_to timestamp with time zone)
 RETURNS TABLE(new_buyers integer, new_sellers integer, new_users integer, bookings integer, completed_bookings integer, cancelled_bookings integer, gmv numeric, new_subscriptions integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  RETURN QUERY
    SELECT
      (SELECT count(*) FROM users u    WHERE u.user_type = 'buyer'  AND u.created_at >= p_from AND u.created_at < p_to)::int,
      (SELECT count(*) FROM users u    WHERE u.user_type = 'seller' AND u.created_at >= p_from AND u.created_at < p_to)::int,
      (SELECT count(*) FROM users u    WHERE u.created_at >= p_from AND u.created_at < p_to)::int,
      (SELECT count(*) FROM bookings b WHERE b.created_at >= p_from AND b.created_at < p_to)::int,
      (SELECT count(*) FROM bookings b WHERE b.status = 'completed' AND b.created_at >= p_from AND b.created_at < p_to)::int,
      (SELECT count(*) FROM bookings b WHERE b.status = 'cancelled' AND b.created_at >= p_from AND b.created_at < p_to)::int,
      COALESCE((SELECT sum(d.discounted_price * b.booked_quantity) FROM bookings b JOIN deals d ON d.id = b.deal_id WHERE b.created_at >= p_from AND b.created_at < p_to), 0),
      (SELECT count(*) FROM merchant_subscriptions ms WHERE ms.created_at >= p_from AND ms.created_at < p_to)::int;
END $function$
;


-- ═══ FUNCTION admin_referral_stats(p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer, p_region text, p_city text, p_location text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_referral_stats(p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 10, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_location text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 2000));
  v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  WITH ref_users AS (
    SELECT u.* FROM users u
     WHERE u.deleted_at IS NULL
       AND u.created_at >= v_from AND u.created_at < v_to
  ),
  src AS (
    SELECT coalesce(ru.referral_source, 'unknown') AS source, count(*) AS n
      FROM ref_users ru
     WHERE ru.referral_source IS NOT NULL OR ru.referred_by_store IS NOT NULL
     GROUP BY coalesce(ru.referral_source, 'unknown')
  ),
  store_geo_ok AS (
    SELECT s.id
      FROM users s
     WHERE s.deleted_at IS NULL
       AND (
            (p_region IS NULL AND p_city IS NULL AND p_location IS NULL)
         OR EXISTS (SELECT 1 FROM store_branches sb
                     WHERE sb.merchant_id = s.id AND sb.is_active IS NOT FALSE
                       AND (p_region   IS NULL OR sb.region_id   = p_region)
                       AND (p_city     IS NULL OR sb.city_id     = p_city)
                       AND (p_location IS NULL OR sb.location_id = p_location))
         OR EXISTS (SELECT 1 FROM deals d
                     WHERE d.store_id = s.id
                       AND (p_region   IS NULL OR d.region      = p_region)
                       AND (p_city     IS NULL OR d.city        = p_city)
                       AND (p_location IS NULL OR d.location_id = p_location))
       )
  ),
  board AS (
    SELECT s.id AS store_id,
           coalesce(s.shop, s.name) AS shop,
           s.referral_code,
           count(ru.id) AS refs,
           count(ru.id) FILTER (WHERE ru.user_type = 'seller') AS seller_refs
      FROM users s
      JOIN ref_users ru ON ru.referred_by_store = s.id
     WHERE s.id IN (SELECT sg.id FROM store_geo_ok sg)
     GROUP BY s.id, coalesce(s.shop, s.name), s.referral_code
     ORDER BY count(ru.id) DESC
     LIMIT v_limit
  )
  SELECT jsonb_build_object(
    'total_referred', (SELECT count(*) FROM ref_users ru2 WHERE ru2.referred_by_store IS NOT NULL),
    'sources', coalesce((SELECT jsonb_agg(jsonb_build_object('source', sr.source, 'count', sr.n) ORDER BY sr.n DESC) FROM src sr), '[]'::jsonb),
    'stores', coalesce((SELECT jsonb_agg(jsonb_build_object(
        'store_id', b.store_id, 'shop', b.shop, 'code', b.referral_code,
        'refs', b.refs, 'seller_refs', b.seller_refs) ORDER BY b.refs DESC) FROM board b), '[]'::jsonb)
  ) INTO v;
  RETURN v;
END $function$
;


-- ═══ FUNCTION admin_remove_sponsor(p_store_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_remove_sponsor(p_store_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id TEXT;
BEGIN
    v_caller_id := auth.uid()::text;
    IF NOT public.is_admin(v_caller_id) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    DELETE FROM public.sponsors WHERE store_id = p_store_id;
    UPDATE public.store_profiles sp SET is_pinned = FALSE, updated_at = NOW()
     WHERE sp.store_id = p_store_id;

    RETURN jsonb_build_object('success', TRUE, 'store_id', p_store_id);
END $function$
;


-- ═══ FUNCTION admin_reports_summary() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_reports_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT jsonb_build_object(
    'reports', jsonb_build_object(
      'open',     (SELECT count(*) FROM public.reports WHERE status = 'open'),
      'review',   (SELECT count(*) FROM public.reports WHERE status = 'under_review'),
      'resolved', (SELECT count(*) FROM public.reports WHERE status = 'resolved'),
      'total',    (SELECT count(*) FROM public.reports)),
    'complaints', jsonb_build_object(
      'open',     (SELECT count(*) FROM public.complaints WHERE status = 'open'),
      'review',   (SELECT count(*) FROM public.complaints WHERE status = 'reviewing'),
      'resolved', (SELECT count(*) FROM public.complaints WHERE status = 'resolved'),
      'total',    (SELECT count(*) FROM public.complaints))
  ) INTO v;
  RETURN v;
END $function$
;


-- ═══ FUNCTION admin_reset_contest_winners(p_contest_id uuid) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_reset_contest_winners(p_contest_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
begin
  if not public.is_admin() then raise exception 'forbidden: admin only'; end if;
  update contest_entries set is_winner = false where contest_id = p_contest_id;
  update contests set status = 'closed', updated_at = now()
    where id = p_contest_id and status = 'drawn';
  return jsonb_build_object('success', true);
end; $function$
;


-- ═══ FUNCTION admin_resolve_store_name(p_id text, p_approve boolean, p_note text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_resolve_store_name(p_id text, p_approve boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r public.store_name_requests%ROWTYPE; v_msg text;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT * INTO r FROM public.store_name_requests WHERE id = p_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF r.status <> 'requested' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_DECIDED', 'status', r.status);
  END IF;

  IF p_approve THEN
    -- المشغّل على `users.shop` ينشر الاسم على كل عروض المتجر تلقائياً.
    UPDATE public.users SET shop = r.wanted_name WHERE id = r.store_id;
    v_msg := '✅ اعتُمد اسم متجرك الجديد: ' || r.wanted_name;
  ELSE
    v_msg := '❌ لم يُعتمد تغيير اسم متجرك إلى «' || r.wanted_name || '»'
             || CASE WHEN COALESCE(btrim(p_note),'') <> '' THEN ' — ' || btrim(p_note) ELSE '' END || '.';
  END IF;

  UPDATE public.store_name_requests
     SET status = CASE WHEN p_approve THEN 'approved' ELSE 'rejected' END,
         admin_note = NULLIF(btrim(COALESCE(p_note,'')), ''),
         admin_id = auth.uid()::text, decided_at = now()
   WHERE id = p_id;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (r.store_id, CASE WHEN p_approve THEN '✅ اسم المتجر' ELSE '❌ اسم المتجر' END,
          CASE WHEN p_approve THEN '✅ Store name' ELSE '❌ Store name' END,
          v_msg, v_msg, 'system', jsonb_build_object('audience','seller'));

  RETURN jsonb_build_object('ok', true, 'approved', p_approve);
END $function$
;


-- ═══ FUNCTION admin_resolve_verification(p_id text, p_approve boolean, p_legal_name text, p_note text, p_reject_code text, p_expiry date, p_name_ack boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_resolve_verification(p_id text, p_approve boolean, p_legal_name text DEFAULT NULL::text, p_note text DEFAULT NULL::text, p_reject_code text DEFAULT NULL::text, p_expiry date DEFAULT NULL::date, p_name_ack boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE r record; v_uid text := (SELECT auth.uid())::text; v_shop text;
        v_name text := btrim(COALESCE(p_legal_name,'')); v_msg text;
BEGIN
  IF NOT public.taki_admin_perm('tab_verification') THEN
    RAISE EXCEPTION 'غير مصرّح' USING ERRCODE = '42501'; END IF;
  SELECT * INTO r FROM public.store_verifications WHERE id = p_id FOR UPDATE;
  IF r.id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF r.status <> 'submitted' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_DECIDED', 'status', r.status); END IF;

  IF p_approve THEN
    IF length(v_name) < 3 THEN RETURN jsonb_build_object('ok', false, 'error', 'LEGAL_NAME_REQUIRED'); END IF;
    -- إعادةُ فحص التفرّد **تحت القفل**: الفهرس وحده يعطي المراجع انتهاكَ قيدٍ خاماً.
    IF EXISTS (SELECT 1 FROM public.store_verifications d
                WHERE d.status = 'approved' AND d.store_id <> r.store_id
                  AND d.doc_kind = r.doc_kind
                  AND lower(btrim(d.doc_number)) = lower(btrim(r.doc_number))) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'NUMBER_TAKEN'); END IF;
    SELECT shop INTO v_shop FROM public.users WHERE id = r.store_id;
    IF public.taki_norm(v_name) <> public.taki_norm(COALESCE(v_shop,'')) AND NOT COALESCE(p_name_ack,false) THEN
      RETURN jsonb_build_object('ok', false, 'error', 'NAME_MISMATCH_UNACKED',
                                'legal_name', v_name, 'shop', v_shop); END IF;

    UPDATE public.store_verifications SET status = 'superseded', decided_at = now()
     WHERE store_id = r.store_id AND status = 'approved';
    UPDATE public.store_verifications
       SET status = 'approved', legal_name = v_name, doc_expiry = COALESCE(p_expiry, r.doc_expiry),
           assurance = CASE WHEN r.doc_kind = 'freelance' THEN 'declared' ELSE 'registry' END,
           name_ack = COALESCE(p_name_ack,false), admin_note = p_note, admin_id = v_uid,
           reject_code = NULL, decided_at = now()
     WHERE id = r.id;
    -- الفاتورة (v14.17) تقرأ `store_profiles.cr_number` — فالرقمُ المعتمد يُكتب
    -- هنا بدور الأدمن، والمشغّل يستثنيه. أي أن لا نسختين متباعدتين من هويّة.
    UPDATE public.store_profiles SET cr_number = btrim(r.doc_number) WHERE store_id = r.store_id;
    v_msg := '✅ تم توثيق متجرك. الاسم المسجَّل: «' || v_name || '». يمكنك نشر عروضك الآن.';
  ELSE
    UPDATE public.store_verifications
       SET status = 'rejected', reject_code = COALESCE(p_reject_code,'other'),
           admin_note = p_note, admin_id = v_uid, decided_at = now()
     WHERE id = r.id;
    v_msg := '❌ لم يُقبل طلب التوثيق: ' || CASE COALESCE(p_reject_code,'other')
      WHEN 'not_found'      THEN 'الرقم غير موجود في السجل الرسمي.'
      WHEN 'name_mismatch'  THEN 'الاسم في السجل لا يطابق اسم متجرك.'
      WHEN 'expired_doc'    THEN 'السجل/الوثيقة منتهية الصلاحية.'
      WHEN 'suspended_doc'  THEN 'السجل موقوف.'
      WHEN 'not_owner'      THEN 'الوثيقة ليست باسم صاحب الحساب.'
      WHEN 'duplicate_cr'   THEN 'هذا الرقم موثَّق لمتجرٍ آخر.'
      WHEN 'wrong_activity' THEN 'النشاط لا يشمل البيع الإلكتروني.'
      ELSE 'راجع الملاحظة أدناه.' END
      || COALESCE(E'\n' || p_note, '');
  END IF;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (r.store_id, CASE WHEN p_approve THEN '✅ متجرك موثّق' ELSE '❌ طلب التوثيق' END,
          CASE WHEN p_approve THEN '✅ Store verified' ELSE '❌ Verification request' END,
          v_msg, v_msg, 'system',
          jsonb_build_object('audience','seller','actionUrl','/seller','action_url','/seller'));
  RETURN jsonb_build_object('ok', true, 'approved', p_approve);
END
$function$
;


-- ═══ FUNCTION admin_retention_curve(p_months_back integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_retention_curve(p_months_back integer DEFAULT 6)
 RETURNS TABLE(cohort_month text, cohort_label text, cohort_size integer, d1_pct numeric, d7_pct numeric, d30_pct numeric, d60_pct numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH cohorts AS (
        SELECT u.id AS user_id,
               date_trunc('month', u.created_at) AS cohort_m,
               u.created_at
        FROM users u
        WHERE u.user_type = 'buyer'
          AND u.created_at >= date_trunc('month', now()) - ((p_months_back - 1) || ' months')::INTERVAL
          AND COALESCE(u.is_suspended, FALSE) = FALSE
          AND u.deleted_at IS NULL
    ),
    activity_after AS (
        SELECT c.user_id, c.cohort_m, c.created_at,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '1 day'  AND c.created_at + INTERVAL '2 days')  AS d1,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '7 days' AND c.created_at + INTERVAL '8 days')  AS d7,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '30 days' AND c.created_at + INTERVAL '31 days') AS d30,
               BOOL_OR(al.created_at BETWEEN c.created_at + INTERVAL '60 days' AND c.created_at + INTERVAL '61 days') AS d60
        FROM cohorts c
        LEFT JOIN activity_log al ON al.user_id = c.user_id
        GROUP BY c.user_id, c.cohort_m, c.created_at
    )
    SELECT to_char(cohort_m, 'YYYY-MM')::TEXT,
           to_char(cohort_m, 'Mon YY')::TEXT,
           COUNT(*)::INT,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d1) / COUNT(*), 1) END,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d7) / COUNT(*), 1) END,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d30) / COUNT(*), 1) END,
           CASE WHEN COUNT(*) = 0 THEN 0 ELSE ROUND(100.0 * COUNT(*) FILTER (WHERE d60) / COUNT(*), 1) END
    FROM activity_after
    GROUP BY cohort_m
    ORDER BY cohort_m ASC;
END;
$function$
;


-- ═══ FUNCTION admin_revenue_forecast() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_revenue_forecast()
 RETURNS TABLE(monthly_expected numeric, paying_sellers integer, free_sellers integer, trial_sellers integer, expires_7d integer, expires_30d integer, avg_arpu numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_monthly NUMERIC;
    v_paying INT;
    v_free INT;
    v_trial INT;
    v_exp7 INT;
    v_exp30 INT;
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;

    SELECT COALESCE(SUM(sp.subscription_amount * (1 - COALESCE(sp.discount_percentage, 0) / 100.0)), 0),
           COUNT(*)
      INTO v_monthly, v_paying
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE sp.subscription_plan = 'premium'
      AND COALESCE(sp.is_suspended, FALSE) = FALSE
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND u.user_type = 'seller';

    SELECT COUNT(*) INTO v_free
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE u.user_type = 'seller'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND (sp.subscription_plan IS NULL OR sp.subscription_plan = 'free');

    SELECT COUNT(*) INTO v_trial
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE u.user_type = 'seller'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
      AND sp.subscription_plan = 'trial';

    SELECT COUNT(*) INTO v_exp7
    FROM store_profiles
    WHERE subscription_plan = 'premium'
      AND subscription_expires_at IS NOT NULL
      AND subscription_expires_at BETWEEN now() AND now() + INTERVAL '7 days';

    SELECT COUNT(*) INTO v_exp30
    FROM store_profiles
    WHERE subscription_plan = 'premium'
      AND subscription_expires_at IS NOT NULL
      AND subscription_expires_at BETWEEN now() AND now() + INTERVAL '30 days';

    RETURN QUERY SELECT
        v_monthly,
        v_paying,
        v_free,
        v_trial,
        v_exp7,
        v_exp30,
        CASE WHEN v_paying = 0 THEN 0 ELSE ROUND(v_monthly / v_paying, 2) END;
END;
$function$
;


-- ═══ FUNCTION admin_revoke_verification(p_store_id text, p_reason text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_revoke_verification(p_store_id text, p_reason text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n int := 0; v_paused int := 0; v_msg text;
BEGIN
  IF NOT public.taki_admin_perm('tab_verification') THEN
    RAISE EXCEPTION 'غير مصرّح' USING ERRCODE = '42501'; END IF;
  UPDATE public.store_verifications
     SET status = 'revoked', admin_note = p_reason, admin_id = (SELECT auth.uid())::text, decided_at = now()
   WHERE store_id = p_store_id AND status = 'approved';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_VERIFIED'); END IF;
  UPDATE public.deals SET status = 'paused' WHERE store_id = p_store_id AND status = 'active';
  GET DIAGNOSTICS v_paused = ROW_COUNT;
  v_msg := '🚫 سُحب توثيق متجرك: ' || COALESCE(p_reason,'—') ||
           '. وأُوقفت عروضك مؤقتاً حتى تُعيد التوثيق. (طلباتك القائمة تكمل كما هي.)';
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (p_store_id, '🚫 سُحب التوثيق', '🚫 Verification revoked', v_msg, v_msg, 'system',
          jsonb_build_object('audience','seller','actionUrl','/seller','action_url','/seller'));
  RETURN jsonb_build_object('ok', true, 'paused_deals', v_paused);
END
$function$
;


-- ═══ FUNCTION admin_search_users(p_query text, p_user_type text, p_limit integer, p_offset integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_search_users(p_query text DEFAULT ''::text, p_user_type text DEFAULT NULL::text, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0)
 RETURNS TABLE(id text, name text, phone text, email text, user_type text, shop text, address text, is_suspended boolean, total_bookings integer, total_spent numeric, last_active_at timestamp with time zone, created_at timestamp with time zone, subscription_plan text, subscription_expires_at timestamp with time zone, subscription_amount numeric, discount_percentage numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
    v_q TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT u.user_type INTO v_caller_role FROM users u WHERE u.id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_q := '%' || COALESCE(p_query, '') || '%';

    RETURN QUERY
    SELECT u.id, u.name, u.phone, u.email, u.user_type, u.shop, u.address,
           COALESCE(u.is_suspended, FALSE),
           (SELECT COUNT(*)::int FROM bookings b WHERE b.user_id = u.id),
           -- v14.33 — `u.total_spent` عمودٌ ميّت: DEFAULT 0 ولا يكتبه أحد في
           -- المنصّة كلها (قِيس: صفر لكل الحسابات). فبطاقة المشتري كانت تقول
           -- «٠ ر.س مصروفة» مهما أنفق، ومرشّح «الأكثر إنفاقاً» يرتّب بقيمة
           -- ثابتة فلا يرتّب. المصدر الصحيح هو الإجمالي المُجمَّد على الحجز.
           public.taki_user_spend(u.id),
           u.last_active_at, u.created_at,
           sp.subscription_plan,
           sp.subscription_expires_at,
           sp.subscription_amount,
           sp.discount_percentage::numeric
    FROM users u
    LEFT JOIN store_profiles sp ON sp.store_id = u.id
    WHERE (u.deleted_at IS NULL)
      AND (
        p_user_type IS NULL
        OR u.user_type = p_user_type
        OR (p_user_type = 'buyer' AND u.user_type <> 'seller'
            AND EXISTS (SELECT 1 FROM bookings b WHERE b.user_id = u.id))
      )
      AND (
        p_query = '' OR
        u.name  ILIKE v_q OR
        u.phone ILIKE v_q OR
        u.email ILIKE v_q OR
        u.shop  ILIKE v_q OR
        u.address ILIKE v_q
      )
    ORDER BY u.created_at DESC
    LIMIT p_limit OFFSET p_offset;
END $function$
;


-- ═══ FUNCTION admin_set_booking_ban(p_user_id text, p_days integer, p_reason text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_booking_ban(p_user_id text, p_days integer, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_msg text;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  IF p_days IS NULL OR p_days <= 0 THEN
    UPDATE users SET booking_banned_until = NULL, booking_ban_reason = NULL WHERE id = p_user_id;
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (p_user_id, '✅ رفع تعليق الحجز', '✅ Booking ban lifted',
            'تم رفع تعليق الحجز عن حسابك — يمكنك الحجز الآن.', 'Your booking ban was lifted.', 'system',
            jsonb_build_object('audience', 'user'));
    RETURN jsonb_build_object('success', true, 'cleared', true);
  END IF;
  v_msg := format('⏸️ تم تعليق الحجز على حسابك لمدة %s أيام%s.', p_days,
                  CASE WHEN COALESCE(TRIM(p_reason), '') <> '' THEN ' — السبب: ' || TRIM(p_reason) ELSE '' END);
  UPDATE users SET booking_banned_until = now() + make_interval(days => p_days),
                   booking_ban_reason = COALESCE(NULLIF(TRIM(p_reason), ''), 'قرار إداري')
   WHERE id = p_user_id;
  INSERT INTO user_warnings (user_id, user_role, reason, admin_id)
  VALUES (p_user_id, (SELECT user_type FROM users WHERE id = p_user_id), v_msg, auth.uid()::text);
  INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (p_user_id, '⏸️ تعليق الحجز', '⏸️ Booking suspended', v_msg, v_msg, 'system',
          jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
  RETURN jsonb_build_object('success', true, 'until', now() + make_interval(days => p_days));
END $function$
;


-- ═══ FUNCTION admin_set_complaint_status(p_id uuid, p_status text, p_note text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_complaint_status(p_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_role TEXT;
    v_caller TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    v_caller := auth.uid()::text;
    SELECT u.user_type INTO v_role FROM public.users u WHERE u.id = v_caller;
    IF v_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    IF p_status NOT IN ('open','reviewing','resolved','dismissed') THEN
        RAISE EXCEPTION 'Bad status';
    END IF;
    UPDATE public.complaints
       SET status = p_status,
           admin_note = COALESCE(p_note, admin_note),
           resolved_by = CASE WHEN p_status IN ('resolved','dismissed') THEN v_caller ELSE resolved_by END,
           resolved_at = CASE WHEN p_status IN ('resolved','dismissed') THEN NOW() ELSE resolved_at END
     WHERE id = p_id;
    RETURN jsonb_build_object('success', TRUE);
END $function$
;


-- ═══ FUNCTION admin_set_delivery_global(p_enabled boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_delivery_global(p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.taki_admin_perm('tab_delivery') THEN RAISE EXCEPTION 'Not allowed'; END IF;
  INSERT INTO public.platform_settings (key, value) VALUES ('delivery_enabled', to_jsonb(p_enabled))
  ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value;
  RETURN jsonb_build_object('ok', true, 'enabled', p_enabled);
END $function$
;


-- ═══ FUNCTION admin_set_flag_status(p_id uuid, p_status text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_flag_status(p_id uuid, p_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_status NOT IN ('open','reviewed') THEN RAISE EXCEPTION 'bad status'; END IF;
  UPDATE moderation_flags SET status = p_status WHERE id = p_id;
END $function$
