-- ═══ FUNCTION admin_set_gateway_blocked(p_merchant_id text, p_blocked boolean) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_gateway_blocked(p_merchant_id text, p_blocked boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  UPDATE public.merchant_gateways
  SET disabled_by_admin = p_blocked, updated_at = now()
  WHERE merchant_id = p_merchant_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (auth.uid()::text, 'admin',
          CASE WHEN p_blocked THEN 'gateway_admin_blocked' ELSE 'gateway_admin_unblocked' END,
          'merchant_gateway', p_merchant_id, '{}'::jsonb);
  INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES ('ntf_gwadm_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
          p_merchant_id,
          CASE WHEN p_blocked THEN '⛔️ تم إيقاف بوابة الدفع لمتجرك' ELSE '✅ أُعيد تفعيل بوابة الدفع لمتجرك' END,
          CASE WHEN p_blocked THEN 'Your payment gateway was suspended' ELSE 'Your payment gateway was re-enabled' END,
          CASE WHEN p_blocked THEN 'أوقفت الإدارة خاصية الدفع الإلكتروني لمتجرك مؤقتاً — منتجاتك تعود تلقائياً للدفع عند الاستلام. تواصل مع الإدارة للتفاصيل.'
               ELSE 'أعادت الإدارة تفعيل الدفع الإلكتروني لمتجرك.' END,
          CASE WHEN p_blocked THEN 'The platform temporarily suspended online payment for your store — your products fall back to pay-on-pickup automatically.'
               ELSE 'Online payment for your store has been re-enabled.' END,
          'system', jsonb_build_object('audience', 'seller'));
END $function$
;


-- ═══ FUNCTION admin_set_launch_item(p_item_id text, p_done boolean, p_note text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_launch_item(p_item_id text, p_done boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.taki_admin_perm('tab_launch') THEN RAISE EXCEPTION 'Not allowed'; END IF;
  IF COALESCE(btrim(p_item_id),'') = '' THEN RETURN jsonb_build_object('ok', false); END IF;
  INSERT INTO public.launch_checklist_state (item_id, done, note, admin_id, updated_at)
  VALUES (btrim(p_item_id), p_done, NULLIF(btrim(COALESCE(p_note,'')),''), auth.uid()::text, now())
  ON CONFLICT (item_id) DO UPDATE
    SET done = EXCLUDED.done, note = EXCLUDED.note,
        admin_id = EXCLUDED.admin_id, updated_at = now();
  RETURN jsonb_build_object('ok', true, 'item', p_item_id, 'done', p_done);
END $function$
;


-- ═══ FUNCTION admin_set_permissions(target_id text, perms text[]) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_permissions(target_id text, perms text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_super_admin() THEN
    RAISE EXCEPTION 'forbidden: super admin required';
  END IF;
  IF target_id IS NULL OR target_id = '' THEN
    RAISE EXCEPTION 'target_id required';
  END IF;
  IF EXISTS (SELECT 1 FROM public.users u WHERE u.id = target_id AND u.is_super_admin = TRUE) THEN
    RAISE EXCEPTION 'cannot modify super admin permissions';
  END IF;
  UPDATE public.users u
  SET admin_permissions = COALESCE(perms, '{}'::TEXT[])
  WHERE u.id = target_id AND u.user_type = 'admin';
  IF NOT FOUND THEN
    RAISE EXCEPTION 'target is not a staff admin';
  END IF;
END;
$function$
;


-- ═══ FUNCTION admin_set_prize_delivered(p_entry_id uuid, p_delivered boolean, p_note text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_prize_delivered(p_entry_id uuid, p_delivered boolean, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_rows int;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  UPDATE contest_entries
     SET prize_delivered    = COALESCE(p_delivered, false),
         prize_delivered_at = CASE WHEN COALESCE(p_delivered, false) THEN now() ELSE NULL END,
         prize_note         = NULLIF(btrim(COALESCE(p_note, '')), '')
   WHERE id = p_entry_id AND is_winner = true;
  GET DIAGNOSTICS v_rows = ROW_COUNT;
  -- صفر صفوف = المعرّف خاطئ أو ليس فائزاً. لا يُقال «تمّ» بلا صفّ.
  RETURN jsonb_build_object('ok', v_rows = 1, 'updated', v_rows);
END $function$
;


-- ═══ FUNCTION admin_set_report_status(p_id uuid, p_status text, p_note text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_report_status(p_id uuid, p_status text, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_role TEXT;
    v_caller TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    v_caller := auth.uid()::text;
    SELECT u.user_type INTO v_role FROM public.users u WHERE u.id = v_caller;
    IF v_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    IF p_status NOT IN ('open','under_review','resolved','dismissed') THEN
        RAISE EXCEPTION 'Bad status';
    END IF;
    UPDATE public.reports
       SET status = p_status,
           admin_note = COALESCE(p_note, admin_note),
           resolved_by = CASE WHEN p_status IN ('resolved','dismissed') THEN v_caller ELSE resolved_by END,
           resolved_at = CASE WHEN p_status IN ('resolved','dismissed') THEN NOW() ELSE resolved_at END
     WHERE id = p_id;
    RETURN jsonb_build_object('success', TRUE);
END $function$
;


-- ═══ FUNCTION admin_set_sponsor(p_store_id text, p_is_active boolean, p_target_category text, p_target_city text, p_target_region text, p_target_lat double precision, p_target_lng double precision, p_target_radius_km double precision, p_priority integer, p_expires_at timestamp with time zone, p_notes text, p_label_type text, p_starts_at timestamp with time zone) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_sponsor(p_store_id text, p_is_active boolean DEFAULT true, p_target_category text DEFAULT NULL::text, p_target_city text DEFAULT NULL::text, p_target_region text DEFAULT NULL::text, p_target_lat double precision DEFAULT NULL::double precision, p_target_lng double precision DEFAULT NULL::double precision, p_target_radius_km double precision DEFAULT NULL::double precision, p_priority integer DEFAULT 0, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_notes text DEFAULT NULL::text, p_label_type text DEFAULT 'ad'::text, p_starts_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_id TEXT;
    v_store_name TEXT;
    v_was_active BOOLEAN;
    v_label TEXT;
    v_start TIMESTAMPTZ;
BEGIN
    v_caller_id := auth.uid()::text;
    IF NOT public.is_admin(v_caller_id) THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_label := lower(COALESCE(NULLIF(TRIM(p_label_type), ''), 'ad'));
    IF v_label NOT IN ('ad','sponsor','none','star') THEN v_label := 'ad'; END IF;
    v_start := COALESCE(p_starts_at, NOW());

    -- Validate the window: start must be before expiry (if expiry given).
    IF p_expires_at IS NOT NULL AND v_start >= p_expires_at THEN
        RAISE EXCEPTION 'Start date must be before expiry date';
    END IF;

    SELECT u.name INTO v_store_name FROM public.users u WHERE u.id = p_store_id;
    IF v_store_name IS NULL THEN
        RAISE EXCEPTION 'Store not found: %', p_store_id;
    END IF;

    SELECT s.is_active INTO v_was_active FROM public.sponsors s WHERE s.store_id = p_store_id;

    INSERT INTO public.sponsors (
        store_id, is_active, target_category, target_city, target_region,
        target_lat, target_lng, target_radius_km, priority, starts_at, expires_at,
        notes, label_type, created_by, updated_at
    ) VALUES (
        p_store_id, COALESCE(p_is_active, TRUE),
        NULLIF(TRIM(COALESCE(p_target_category, '')), ''),
        NULLIF(TRIM(COALESCE(p_target_city, '')), ''),
        NULLIF(TRIM(COALESCE(p_target_region, '')), ''),
        p_target_lat, p_target_lng, p_target_radius_km,
        COALESCE(p_priority, 0), v_start, p_expires_at, p_notes, v_label, v_caller_id, NOW()
    )
    ON CONFLICT (store_id) DO UPDATE SET
        is_active        = COALESCE(p_is_active, TRUE),
        target_category  = NULLIF(TRIM(COALESCE(p_target_category, '')), ''),
        target_city      = NULLIF(TRIM(COALESCE(p_target_city, '')), ''),
        target_region    = NULLIF(TRIM(COALESCE(p_target_region, '')), ''),
        target_lat       = p_target_lat,
        target_lng       = p_target_lng,
        target_radius_km = p_target_radius_km,
        priority         = COALESCE(p_priority, 0),
        starts_at        = v_start,
        expires_at       = p_expires_at,
        notes            = p_notes,
        label_type       = v_label,
        updated_at       = NOW();

    UPDATE public.store_profiles sp
       SET is_pinned = COALESCE(p_is_active, TRUE), updated_at = NOW()
     WHERE sp.store_id = p_store_id;
    IF NOT FOUND THEN
        INSERT INTO public.store_profiles (store_id, is_pinned, updated_at)
        VALUES (p_store_id, COALESCE(p_is_active, TRUE), NOW())
        ON CONFLICT (store_id) DO UPDATE SET is_pinned = EXCLUDED.is_pinned, updated_at = NOW();
    END IF;

    IF COALESCE(p_is_active, TRUE) AND COALESCE(v_was_active, FALSE) IS DISTINCT FROM TRUE THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (
            p_store_id,
            '🌟 أصبحت راعياً رسمياً في تاكي',
            '🌟 You are now an Official Sponsor on TAKI',
            'تهانينا! متجرك الآن راعٍ رسمي — تظهر منتجاتك كإعلانات مميزة بإطار ذهبي ضمن العروض' ||
                COALESCE(' حتى ' || to_char(p_expires_at, 'YYYY-MM-DD'), '') || '.',
            'Congratulations! Your store is now an official sponsor — your deals appear as featured gold ads' ||
                COALESCE(' until ' || to_char(p_expires_at, 'YYYY-MM-DD'), '') || '.',
            'system',
            jsonb_build_object('audience', 'user', 'sponsor', TRUE)
        );
    END IF;

    RETURN jsonb_build_object('success', TRUE, 'store_id', p_store_id, 'store_name', v_store_name, 'label_type', v_label);
END $function$
;


-- ═══ FUNCTION admin_set_store_delivery(p_store_id text, p_blocked boolean, p_reason text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_store_delivery(p_store_id text, p_blocked boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_msg text;
BEGIN
  IF NOT public.taki_admin_perm('tab_sellers') THEN RAISE EXCEPTION 'Not allowed'; END IF;
  UPDATE public.store_profiles
     SET delivery_blocked_by_admin = p_blocked,
         delivery_block_reason = CASE WHEN p_blocked THEN NULLIF(btrim(COALESCE(p_reason,'')),'') END,
         delivery_blocked_at = CASE WHEN p_blocked THEN now() END
   WHERE store_id = p_store_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'STORE_NOT_FOUND'); END IF;

  v_msg := CASE WHEN p_blocked
    THEN '🚚 أوقفت إدارة تاكي خدمة التوصيل على متجرك'
         || CASE WHEN COALESCE(btrim(p_reason),'')<>'' THEN ' — ' || btrim(p_reason) ELSE '' END
         || '. الاستلام من المتجر يبقى متاحاً.'
    ELSE '✅ أُعيدت خدمة التوصيل على متجرك.' END;
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (p_store_id, CASE WHEN p_blocked THEN '🚚 إيقاف التوصيل' ELSE '✅ إعادة التوصيل' END,
          CASE WHEN p_blocked THEN '🚚 Delivery paused' ELSE '✅ Delivery restored' END,
          v_msg, v_msg, 'system', jsonb_build_object('audience','seller'));
  RETURN jsonb_build_object('ok', true, 'blocked', p_blocked);
END $function$
;


-- ═══ FUNCTION admin_set_wathq_key(p_key text, p_env text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_wathq_key(p_key text, p_env text DEFAULT 'production'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_k text; v_back text;
BEGIN
  IF NOT public.taki_admin_perm('tab_tools') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;
  v_k := btrim(COALESCE(p_key, ''));
  IF length(v_k) < 16 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'KEY_TOO_SHORT');
  END IF;
  IF p_env NOT IN ('production', 'sandbox') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_ENV');
  END IF;

  -- 🪤 الاسمُ فريدٌ في الخزنة، فالإنشاءُ الأعمى باسمٍ موجودٍ يفشل.
  IF EXISTS (SELECT 1 FROM vault.secrets WHERE name = 'app_secret:wathq_api_key') THEN
    PERFORM vault.update_secret(
      (SELECT id FROM vault.secrets WHERE name = 'app_secret:wathq_api_key'),
      v_k, 'app_secret:wathq_api_key', 'مفتاحُ واثق (v15.30)');
  ELSE
    PERFORM vault.create_secret(v_k, 'app_secret:wathq_api_key', 'مفتاحُ واثق (v15.30)');
  END IF;

  -- 🔴 الإثباتُ بالقراءة: `vault.update_secret` على مؤشّرٍ ميت تكتب صفرَ
  --    صفوفٍ **بلا استثناء**، فالحفظُ يبدو ناجحاً وهو وهم (درس v14.44).
  v_back := public._taki_wathq_key();
  IF v_back IS DISTINCT FROM v_k THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SECRET_WRITE_FAILED');
  END IF;

  UPDATE public.wathq_config
     SET env = p_env, key_last4 = right(v_k, 4),
         key_set_at = now(), updated_at = now()
   WHERE id;

  RETURN jsonb_build_object('ok', true, 'env', p_env, 'last4', right(v_k, 4));
END
$function$
;


-- ═══ FUNCTION admin_set_wathq_options(p_check_owners boolean, p_convert_cr boolean, p_monthly_cap numeric) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_set_wathq_options(p_check_owners boolean DEFAULT NULL::boolean, p_convert_cr boolean DEFAULT NULL::boolean, p_monthly_cap numeric DEFAULT NULL::numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.taki_admin_perm('tab_tools') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;
  IF p_monthly_cap IS NOT NULL AND (p_monthly_cap < 0 OR p_monthly_cap > 100000) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_CAP');
  END IF;
  UPDATE public.wathq_config
     SET check_owners    = COALESCE(p_check_owners, check_owners),
         convert_cr      = COALESCE(p_convert_cr, convert_cr),
         monthly_cap_sar = COALESCE(p_monthly_cap, monthly_cap_sar),
         updated_at      = now()
   WHERE id;
  RETURN public.admin_wathq_state();
END
$function$
;


-- ═══ FUNCTION admin_site_traffic(p_days integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_site_traffic(p_days integer DEFAULT 30)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_days int := GREATEST(1, LEAST(COALESCE(p_days, 30), 365));
    v_from timestamptz := now() - (v_days || ' days')::interval;
    v jsonb;
BEGIN
    IF NOT public.taki_admin_perm('tab_analytics') THEN
        RAISE EXCEPTION 'forbidden: analytics permission required';
    END IF;

    SELECT jsonb_build_object(
      'days', v_days,
      'totals', (
        SELECT jsonb_build_object(
          'sessions',  count(*),
          'booked',    count(*) FILTER (WHERE booked),
          'bounced',   count(*) FILTER (WHERE page_count <= 1),
          'signed_in', count(*) FILTER (WHERE user_id IS NOT NULL),
          'pwa',       count(*) FILTER (WHERE is_pwa)
        ) FROM site_sessions WHERE started_at >= v_from
      ),
      'daily', COALESCE((
        SELECT jsonb_agg(x ORDER BY x->>'d')
          FROM (SELECT jsonb_build_object(
                        'd', to_char(date_trunc('day', started_at AT TIME ZONE 'Asia/Riyadh'), 'YYYY-MM-DD'),
                        'n', count(*),
                        'booked', count(*) FILTER (WHERE booked)) AS x
                  FROM site_sessions WHERE started_at >= v_from
                 -- 🪤 `GROUP BY 1` هنا يشير إلى `x` نفسه (وهو يحوي تجميعاً)
                 --    لا إلى التاريخ — فيُرفض. التجميع على التعبير صراحةً.
                 GROUP BY date_trunc('day', started_at AT TIME ZONE 'Asia/Riyadh')) t
      ), '[]'::jsonb),
      'channels', COALESCE((
        SELECT jsonb_agg(x ORDER BY (x->>'n')::int DESC)
          FROM (SELECT jsonb_build_object(
                        'channel', channel, 'n', count(*),
                        'booked', count(*) FILTER (WHERE booked)) AS x
                  FROM site_sessions WHERE started_at >= v_from
                 GROUP BY channel) t
      ), '[]'::jsonb),
      'referrers', COALESCE((
        SELECT jsonb_agg(x ORDER BY (x->>'n')::int DESC)
          FROM (SELECT jsonb_build_object('host', referrer_host, 'n', count(*)) AS x
                  FROM site_sessions
                 WHERE started_at >= v_from AND referrer_host IS NOT NULL
                 GROUP BY referrer_host ORDER BY count(*) DESC LIMIT 12) t
      ), '[]'::jsonb),
      'landing', COALESCE((
        SELECT jsonb_agg(x ORDER BY (x->>'n')::int DESC)
          FROM (SELECT jsonb_build_object('path', landing_path, 'n', count(*)) AS x
                  FROM site_sessions WHERE started_at >= v_from
                 GROUP BY landing_path ORDER BY count(*) DESC LIMIT 12) t
      ), '[]'::jsonb),
      -- «أي صفحة أوقفتهم»: آخر صفحة لجلسةٍ لم تحجز
      'exits', COALESCE((
        SELECT jsonb_agg(x ORDER BY (x->>'n')::int DESC)
          FROM (SELECT jsonb_build_object('path', last_path, 'n', count(*)) AS x
                  FROM site_sessions
                 WHERE started_at >= v_from AND NOT booked AND last_path IS NOT NULL
                 GROUP BY last_path ORDER BY count(*) DESC LIMIT 12) t
      ), '[]'::jsonb),
      'campaigns', COALESCE((
        SELECT jsonb_agg(x ORDER BY (x->>'n')::int DESC)
          FROM (SELECT jsonb_build_object(
                        'source', utm_source, 'medium', utm_medium, 'campaign', utm_campaign,
                        'n', count(*), 'booked', count(*) FILTER (WHERE booked)) AS x
                  FROM site_sessions
                 WHERE started_at >= v_from AND utm_source IS NOT NULL
                 GROUP BY utm_source, utm_medium, utm_campaign ORDER BY count(*) DESC LIMIT 12) t
      ), '[]'::jsonb),
      'devices', COALESCE((
        SELECT jsonb_agg(x ORDER BY (x->>'n')::int DESC)
          FROM (SELECT jsonb_build_object('device', COALESCE(device,'?'), 'n', count(*)) AS x
                  FROM site_sessions WHERE started_at >= v_from
                 GROUP BY COALESCE(device,'?')) t
      ), '[]'::jsonb)
    ) INTO v;
    RETURN v;
END $function$
;


-- ═══ FUNCTION admin_soft_delete_user(p_user_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_soft_delete_user(p_user_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
    v_caller_id TEXT;
BEGIN
  PERFORM public._admin_require_ctx();
    v_caller_id := auth.uid()::text;
    SELECT user_type INTO v_caller_role FROM users WHERE id = v_caller_id;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    UPDATE users SET is_suspended = TRUE, updated_at = NOW() WHERE id = p_user_id;
    UPDATE deals SET status = 'deleted' WHERE store_id = p_user_id;

    INSERT INTO activity_log (user_id, user_type, action, entity_type, entity_id)
    VALUES (v_caller_id, 'admin', 'admin_soft_delete_user', 'user', p_user_id);

    RETURN jsonb_build_object('success', true);
END $function$
;


-- ═══ FUNCTION admin_stock_bind_parked(p_parked bigint, p_integration uuid, p_note text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_stock_bind_parked(p_parked bigint, p_integration uuid, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := (SELECT auth.uid())::text;
        v_p record; v_tok jsonb; v_note text; r jsonb; v_store text;
BEGIN
  IF NOT public.taki_admin_perm('tab_sellers') THEN
    RAISE EXCEPTION 'forbidden: tab_sellers required';
  END IF;
  v_note := btrim(COALESCE(p_note, ''));
  -- 🪤 الحجّةُ إلزاميّةٌ لا تجميل: هذا القرارُ يُسلّم توكنَ متجرٍ إلى حسابٍ
  --    بعينه بناءً على ما رآه إنسانٌ خارج النظام. وبعد شهرٍ لن يتذكّر أحدٌ لماذا.
  IF length(v_note) < 10 THEN RAISE EXCEPTION 'NOTE_REQUIRED'; END IF;

  SELECT * INTO v_p FROM public.stock_oauth_parked WHERE id = p_parked FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_p.claimed_by IS NOT NULL THEN RAISE EXCEPTION 'ALREADY_CLAIMED'; END IF;

  SELECT store_id INTO v_store FROM public.stock_integrations
   WHERE id = p_integration AND lower(provider) = v_p.provider;
  IF v_store IS NULL THEN RAISE EXCEPTION 'NO_INTEGRATION'; END IF;

  SELECT decrypted_secret::jsonb INTO v_tok FROM vault.decrypted_secrets WHERE name = v_p.secret_name;
  IF v_tok IS NULL THEN RAISE EXCEPTION 'SECRET_GONE'; END IF;

  r := public.taki_stock_oauth_store(p_integration, v_tok, v_p.remote_id);
  IF NOT COALESCE((r->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'STORE_FAILED: %', COALESCE(r->>'error', '?');
  END IF;

  UPDATE public.stock_oauth_parked SET claimed_by = p_integration, claimed_at = now() WHERE id = v_p.id;
  DELETE FROM vault.secrets WHERE name = v_p.secret_name;

  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'admin', 'stock_parked_bound', 'stock_integration', p_integration::text,
          jsonb_build_object('parked', p_parked, 'provider', v_p.provider,
                             'remote_id', v_p.remote_id, 'store_id', v_store, 'note', v_note));

  RETURN jsonb_build_object('ok', true, 'expires_at', r->>'expires_at');
END
$function$
;


-- ═══ FUNCTION admin_stuck_refunds(p_limit integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_stuck_refunds(p_limit integer DEFAULT 50)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_rows jsonb;
BEGIN
  IF NOT (public.taki_admin_perm('action_view_finance') OR public.taki_admin_perm('tab_launch')) THEN
    RAISE EXCEPTION 'forbidden: action_view_finance required';
  END IF;

  SELECT COALESCE(jsonb_agg(x ORDER BY x->>'claimed_at'), '[]'::jsonb) INTO v_rows
  FROM (
    SELECT jsonb_build_object(
      'barcode',      b.barcode,
      'claimed_at',   b.refund_claimed_at,
      -- 🪤 العمر يُحسب على الخادم لا في المتصفّح: جهازُ ناصر قد يكون على
      --    توقيتٍ آخر، و«منذ كم» رقمٌ يُبنى عليه قرارٌ ماليّ.
      'age_minutes',  GREATEST(0, floor(extract(epoch FROM (now() - b.refund_claimed_at)) / 60))::int,
      'amount',       COALESCE(b.refund_amount, b.paid_amount, b.total_amount),
      'provider',     b.payment_provider,
      'payment_ref',  b.payment_ref,
      'reason',       b.refund_reason,
      'store_id',     b.store_id,
      'store_name',   COALESCE(NULLIF(btrim(u.shop), ''), NULLIF(btrim(u.name), ''), '—'),
      'buyer_name',   COALESCE(NULLIF(btrim(b.user_name), ''), '—'),
      'buyer_phone',  b.user_phone,
      'item',         COALESCE(d.item_name, '—')
    ) AS x
    FROM public.bookings b
    LEFT JOIN public.users u ON u.id = b.store_id
    LEFT JOIN public.deals d ON d.id = b.deal_id
    WHERE b.refund_state = 'claiming'
    ORDER BY b.refund_claimed_at
    LIMIT GREATEST(1, LEAST(200, COALESCE(p_limit, 50)))
  ) s;

  RETURN jsonb_build_object('ok', true, 'rows', v_rows,
                            'count', jsonb_array_length(v_rows));
END
$function$
;


-- ═══ FUNCTION admin_subscription_growth(p_months integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_subscription_growth(p_months integer DEFAULT 12)
 RETURNS TABLE(month_key text, month_label text, new_subs integer, churned_subs integer, net_change integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH months AS (
        SELECT date_trunc('month', now()) - (n || ' months')::INTERVAL AS m
        FROM generate_series(0, GREATEST(p_months, 1) - 1) AS n
    ),
    news AS (
        SELECT date_trunc('month', created_at) AS m, COUNT(*) AS cnt
        FROM merchant_subscriptions
        WHERE created_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    ),
    churns AS (
        SELECT date_trunc('month', updated_at) AS m, COUNT(*) AS cnt
        FROM merchant_subscriptions
        WHERE status = 'cancelled'
          AND updated_at >= date_trunc('month', now()) - ((p_months - 1) || ' months')::INTERVAL
        GROUP BY 1
    )
    SELECT to_char(months.m, 'YYYY-MM')::TEXT,
           to_char(months.m, 'Mon YY')::TEXT,
           COALESCE(news.cnt, 0)::INT,
           COALESCE(churns.cnt, 0)::INT,
           (COALESCE(news.cnt, 0) - COALESCE(churns.cnt, 0))::INT
    FROM months
    LEFT JOIN news   ON news.m   = months.m
    LEFT JOIN churns ON churns.m = months.m
    ORDER BY months.m ASC;
END;
$function$
;


-- ═══ FUNCTION admin_subscription_lifecycle() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_subscription_lifecycle()
 RETURNS TABLE(status text, cnt integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT ms.status::TEXT, COUNT(*)::INT
    FROM merchant_subscriptions ms
    GROUP BY ms.status
    ORDER BY COUNT(*) DESC;
END;
$function$
;


-- ═══ FUNCTION admin_subscription_timeline(p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_subscription_timeline(p_limit integer DEFAULT 200)
 RETURNS TABLE(store_id text, name text, shop text, phone text, plan text, started_at timestamp with time zone, expires_at timestamp with time zone, days_remaining integer, amount numeric, discount numeric, net_amount numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    SELECT u.id::TEXT,
           u.name::TEXT,
           u.shop::TEXT,
           u.phone::TEXT,
           COALESCE(sp.subscription_plan, 'free')::TEXT,
           sp.subscription_started_at,
           sp.subscription_expires_at,
           CASE
             WHEN sp.subscription_expires_at IS NULL THEN NULL
             ELSE EXTRACT(DAY FROM (sp.subscription_expires_at - now()))::INT
           END,
           COALESCE(sp.subscription_amount, 0)::NUMERIC,
           COALESCE(sp.discount_percentage, 0)::NUMERIC,
           (COALESCE(sp.subscription_amount, 0)
            * (1 - COALESCE(sp.discount_percentage, 0) / 100.0))::NUMERIC
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
    WHERE u.user_type = 'seller'
      AND COALESCE(u.is_suspended, FALSE) = FALSE
    ORDER BY sp.subscription_expires_at ASC NULLS LAST
    LIMIT GREATEST(p_limit, 1);
END;
$function$
;


-- ═══ FUNCTION admin_suspend_account(p_user_id text, p_suspend boolean, p_reason text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_suspend_account(p_user_id text, p_suspend boolean, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_msg text; v_type text; v_uuid uuid; v_sessions int := 0;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  SELECT user_type INTO v_type FROM users WHERE id = p_user_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'المستخدم غير موجود'; END IF;
  IF v_type = 'admin' THEN RAISE EXCEPTION 'لا يمكن إيقاف حساب إداري من هنا'; END IF;

  UPDATE users SET is_suspended = p_suspend WHERE id = p_user_id;
  BEGIN v_uuid := p_user_id::uuid; EXCEPTION WHEN others THEN v_uuid := NULL; END;

  IF p_suspend THEN
    -- (أ) منع الدخول. GoTrue يرفض إصدار أي رمز ما دام `banned_until` مستقبلاً.
    --     تاريخٌ بعيد لا «إلى الأبد»: العمود زمنيّ، وفكّ الإيقاف يُفرغه.
    IF v_uuid IS NOT NULL THEN
      UPDATE auth.users SET banned_until = now() + interval '100 years' WHERE id = v_uuid;
      -- (ب) إنهاء ما هو قائم. بلا هذا يبقى الموقوف يعمل من تبويبٍ مفتوح
      --     أسابيع: منعُ الدخول لا يلمس رمزاً صدر قبله.
      DELETE FROM auth.refresh_tokens WHERE user_id = p_user_id;
      WITH d AS (DELETE FROM auth.sessions WHERE user_id = v_uuid RETURNING 1)
      SELECT count(*) INTO v_sessions FROM d;
    END IF;

    v_msg := '⛔ تم إيقاف حسابك من إدارة تاكي' ||
             CASE WHEN COALESCE(TRIM(p_reason), '') <> '' THEN ' — السبب: ' || TRIM(p_reason) ELSE '' END || '.';
    INSERT INTO user_warnings (user_id, user_role, reason, admin_id)
    VALUES (p_user_id, v_type, v_msg, auth.uid()::text);
  ELSE
    IF v_uuid IS NOT NULL THEN
      UPDATE auth.users SET banned_until = NULL WHERE id = v_uuid;
    END IF;
    v_msg := '✅ تم إعادة تفعيل حسابك — أهلاً بعودتك.';
  END IF;

  INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (p_user_id, CASE WHEN p_suspend THEN '⛔ إيقاف الحساب' ELSE '✅ إعادة التفعيل' END,
          CASE WHEN p_suspend THEN '⛔ Account suspended' ELSE '✅ Account restored' END,
          v_msg, v_msg, 'system', jsonb_build_object('audience', 'user'));

  RETURN jsonb_build_object('success', true, 'suspended', p_suspend,
                            'sessions_killed', v_sessions);
END $function$
;


-- ═══ FUNCTION admin_suspended_accounts() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_suspended_accounts()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE WHEN NOT public.is_admin() THEN NULL ELSE COALESCE(jsonb_agg(row_data ORDER BY last_warned DESC NULLS LAST), '[]'::jsonb) END
  FROM (
    SELECT
      (SELECT max(w.created_at) FROM user_warnings w WHERE w.user_id = u.id) AS last_warned,
      jsonb_build_object(
        'user_id', u.id,
        'name', coalesce(u.shop, u.name),
        'user_type', u.user_type,
        'phone', u.phone,
        'warn_count', (SELECT count(*) FROM user_warnings w WHERE w.user_id = u.id),
        'flag_count', (SELECT count(*) FROM moderation_flags f WHERE f.offender_id = u.id),
        'report_count', (SELECT count(*) FROM reports r WHERE r.reported_id = u.id),
        'complaint_count', (SELECT count(*) FROM complaints c WHERE c.user_id = u.id),
        'warnings', (SELECT COALESCE(jsonb_agg(jsonb_build_object('reason', w.reason, 'at', w.created_at, 'auto', w.admin_id IS NULL) ORDER BY w.created_at DESC), '[]'::jsonb)
                     FROM (SELECT * FROM user_warnings w2 WHERE w2.user_id = u.id ORDER BY w2.created_at DESC LIMIT 5) w),
        'recent_flags', (SELECT COALESCE(jsonb_agg(jsonb_build_object('source', f.source, 'matched', f.matched, 'at', f.created_at) ORDER BY f.created_at DESC), '[]'::jsonb)
                         FROM (SELECT * FROM moderation_flags f2 WHERE f2.offender_id = u.id ORDER BY f2.created_at DESC LIMIT 5) f)
      ) AS row_data
    FROM users u
    WHERE u.is_suspended = true AND u.deleted_at IS NULL
  ) t;
$function$
;


-- ═══ FUNCTION admin_sweep_unverified_deals(p_dry_run boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_sweep_unverified_deals(p_dry_run boolean DEFAULT true)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n int := 0; r record; v_msg text;
BEGIN
  IF NOT public.taki_admin_perm('tab_verification') THEN
    RAISE EXCEPTION 'غير مصرّح' USING ERRCODE = '42501'; END IF;
  SELECT count(*) INTO n FROM public.deals d JOIN public.users u ON u.id = d.store_id
   WHERE d.status = 'active' AND u.user_type = 'seller' AND u.deleted_at IS NULL
     AND NOT public.taki_store_verified(u.id) AND NOT public.taki_store_grandfathered(u.id);
  IF p_dry_run THEN RETURN jsonb_build_object('ok', true, 'dry_run', true, 'would_pause', n); END IF;
  FOR r IN SELECT DISTINCT d.store_id FROM public.deals d JOIN public.users u ON u.id = d.store_id
            WHERE d.status = 'active' AND u.user_type = 'seller' AND u.deleted_at IS NULL
              AND NOT public.taki_store_verified(u.id) AND NOT public.taki_store_grandfathered(u.id)
  LOOP
    UPDATE public.deals SET status = 'paused' WHERE store_id = r.store_id AND status = 'active';
    v_msg := '📝 أُوقفت عروضك مؤقتاً: انتهت مهلة التوثيق ولم يصلنا سجلك. أرسله من «توثيق المتجر» وتعود عروضك بضغطة.';
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (r.store_id, '📝 عروضك متوقفة', '📝 Your deals are paused', v_msg, v_msg, 'system',
            jsonb_build_object('audience','seller','actionUrl','/seller','action_url','/seller'));
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'dry_run', false, 'paused', n);
END
$function$
;


-- ═══ FUNCTION admin_sync_package_limits() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_sync_package_limits()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_caller text; v_role text; v_updated int := 0; v_unbound int := 0; v_names jsonb;
BEGIN
  PERFORM public._admin_require_ctx();
  v_caller := auth.uid()::text;
  SELECT user_type INTO v_role FROM users WHERE id = v_caller;
  IF v_role IS DISTINCT FROM 'admin' THEN
    RAISE EXCEPTION 'Admin only' USING ERRCODE = '42501';
  END IF;

  WITH pkgs AS (
    SELECT (e->>'id')::int AS pid, GREATEST(1, (e->>'max')::int) AS pmax
      FROM jsonb_array_elements(
             (SELECT value FROM platform_settings WHERE key = 'location_packages')) e
     WHERE NULLIF(e->>'id','') IS NOT NULL AND NULLIF(e->>'max','') IS NOT NULL
  ), upd AS (
    UPDATE store_profiles sp
       SET max_branches = p.pmax, updated_at = NOW()
      FROM pkgs p
     WHERE sp.subscription_package_id = p.pid
       AND sp.max_branches IS DISTINCT FROM p.pmax
    RETURNING 1
  )
  SELECT count(*) INTO v_updated FROM upd;

  -- v14.76 — المتاجر التي لا باقة لها: سقفها رقمٌ حرّ لا يتبع اللوحة.
  SELECT count(*), COALESCE(jsonb_agg(jsonb_build_object(
           'store_id', sp.store_id,
           'name', COALESCE(NULLIF(btrim(u.shop),''), u.name),
           'max_branches', sp.max_branches)), '[]'::jsonb)
    INTO v_unbound, v_names
    FROM store_profiles sp
    JOIN users u ON u.id = sp.store_id
   WHERE sp.subscription_package_id IS NULL
     AND u.deleted_at IS NULL;

  RETURN jsonb_build_object('success', true,
                            'stores_updated', COALESCE(v_updated, 0),
                            'stores_unbound', COALESCE(v_unbound, 0),
                            'unbound', v_names);
END $function$
;


-- ═══ FUNCTION admin_system_health() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_system_health()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE h public.system_heartbeat%ROWTYPE;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'ADMIN_ONLY'; END IF;
  SELECT * INTO h FROM public.system_heartbeat WHERE id = 1;
  RETURN jsonb_build_object(
    'status', h.status, 'issues', h.issues, 'metrics', h.metrics, 'seen_at', h.seen_at,
    'age_seconds', GREATEST(0, floor(extract(epoch FROM (now() - h.seen_at)))::bigint),
    'cron', public.taki_cron_health(),
    'db_size', pg_size_pretty(pg_database_size(current_database()))
  );
END $function$
;


-- ═══ FUNCTION admin_test_message_event(p_event text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_test_message_event(p_event text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid text := auth.uid()::text;
  s jsonb; vars jsonb; v_title text; v_body text; v_emailed boolean := false;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'admins only'; END IF;
  IF p_event NOT IN ('sub_new','sub_warning','sub_renewed','sub_expired','sub_cancelled','booking_reminder') THEN
    RAISE EXCEPTION 'unknown event %', p_event;
  END IF;
  s := public.taki_msg_setting(p_event);
  vars := jsonb_build_object(
    'store',   'متجر تجريبي',
    'plan',    'باقة حتى 3 مواقع',
    'price',   '399.99',
    'expires', to_char(now() + interval '30 days', 'YYYY-MM-DD'),
    'days',    COALESCE(s->>'days_before','3'),
    'minutes', COALESCE(s->>'minutes_before','15'),
    'item',    'منتج تجريبي'
  );
  v_title := public.taki_render_template(s->>'title_ar', vars);
  v_body  := public.taki_render_template(s->>'body_ar',  vars);
  INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
  VALUES (v_uid, v_title || ' (تجربة)',
          public.taki_render_template(s->>'title_en', vars) || ' (test)',
          v_body, public.taki_render_template(s->>'body_en', vars),
          'system', jsonb_build_object('audience','admin','event','msg_test'), now());
  IF COALESCE((s->'channels'->>'email')::boolean, false) THEN
    v_emailed := public.taki_queue_email(v_uid, p_event,
        v_title || ' (تجربة)',
        public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
  END IF;
  RETURN jsonb_build_object('success', true, 'sent_inapp', true, 'queued_email', v_emailed);
END $function$
;


-- ═══ FUNCTION admin_top_activity(p_kind text, p_from timestamp with time zone, p_to timestamp with time zone, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_top_activity(p_kind text, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_from timestamptz := coalesce(p_from, 'epoch'::timestamptz);
  v_to   timestamptz := coalesce(p_to, now() + interval '1 day');
  v_limit integer := greatest(1, least(coalesce(p_limit, 10), 2000));
  v jsonb;
BEGIN
  IF NOT is_admin() THEN RAISE EXCEPTION 'admin only'; END IF;
  IF p_kind NOT IN ('stores', 'buyers') THEN RAISE EXCEPTION 'bad kind'; END IF;

  IF p_kind = 'stores' THEN
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'id', t.gid, 'label', t.label, 'phone', t.phone,
             'bookings', t.bookings, 'completed', t.completed,
             'qty', t.qty, 'revenue', t.revenue) ORDER BY t.completed DESC, t.bookings DESC), '[]'::jsonb)
      INTO v
      FROM (
        SELECT b.store_id AS gid,
               coalesce(max(coalesce(u.shop, u.name)), b.store_id) AS label,
               max(u.phone) AS phone,
               count(*) FILTER (WHERE b.status <> 'cancelled') AS bookings,
               count(*) FILTER (WHERE b.status = 'completed') AS completed,
               coalesce(sum(b.booked_quantity) FILTER (WHERE b.status = 'completed'), 0) AS qty,
               coalesce(sum(d.discounted_price * b.booked_quantity) FILTER (WHERE b.status = 'completed'), 0) AS revenue
          FROM bookings b
          LEFT JOIN users u ON u.id = b.store_id
          LEFT JOIN deals d ON d.id = b.deal_id
         WHERE b.created_at >= v_from AND b.created_at < v_to
         GROUP BY b.store_id
         ORDER BY completed DESC, bookings DESC
         LIMIT v_limit
      ) t;
  ELSE
    SELECT coalesce(jsonb_agg(jsonb_build_object(
             'id', t.gid, 'label', t.label, 'phone', t.phone,
             'bookings', t.bookings, 'completed', t.completed,
             'qty', t.qty, 'revenue', t.revenue) ORDER BY t.completed DESC, t.bookings DESC), '[]'::jsonb)
      INTO v
      FROM (
        SELECT b.user_id AS gid,
               coalesce(max(u.name), max(b.user_name), b.user_id) AS label,
               coalesce(max(u.phone), max(b.user_phone)) AS phone,
               count(*) FILTER (WHERE b.status <> 'cancelled') AS bookings,
               count(*) FILTER (WHERE b.status = 'completed') AS completed,
               coalesce(sum(b.booked_quantity) FILTER (WHERE b.status = 'completed'), 0) AS qty,
               coalesce(sum(d.discounted_price * b.booked_quantity) FILTER (WHERE b.status = 'completed'), 0) AS revenue
          FROM bookings b
          LEFT JOIN users u ON u.id = b.user_id
          LEFT JOIN deals d ON d.id = b.deal_id
         WHERE b.created_at >= v_from AND b.created_at < v_to
         GROUP BY b.user_id
         ORDER BY completed DESC, bookings DESC
         LIMIT v_limit
      ) t;
  END IF;

  RETURN coalesce(v, '[]'::jsonb);
END $function$
;


-- ═══ FUNCTION admin_top_buyers(p_limit integer, p_from timestamp with time zone, p_to timestamp with time zone) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_top_buyers(p_limit integer DEFAULT 20, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(id text, name text, phone text, bookings_count integer, total_spent numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  RETURN QUERY
    SELECT t.id, t.name, t.phone, t.bookings_count, t.total_spent
    FROM (
      SELECT u.id, u.name, u.phone,
        count(b.barcode) FILTER (
          WHERE b.barcode IS NOT NULL
            AND (p_from IS NULL OR b.created_at >= p_from)
            AND (p_to   IS NULL OR b.created_at <  p_to)
        )::int AS bookings_count,
        COALESCE(sum(d.discounted_price * b.booked_quantity) FILTER (
          WHERE (p_from IS NULL OR b.created_at >= p_from)
            AND (p_to   IS NULL OR b.created_at <  p_to)
        ), 0) AS total_spent
      FROM users u
      LEFT JOIN bookings b ON b.user_id = u.id
      LEFT JOIN deals d ON d.id = b.deal_id
      WHERE u.user_type = 'buyer'
      GROUP BY u.id, u.name, u.phone
    ) t
    ORDER BY t.bookings_count DESC, t.total_spent DESC NULLS LAST
    LIMIT GREATEST(1, COALESCE(p_limit, 20));
END $function$
;


-- ═══ FUNCTION admin_top_sellers(p_limit integer, p_from timestamp with time zone, p_to timestamp with time zone) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_top_sellers(p_limit integer DEFAULT 20, p_from timestamp with time zone DEFAULT NULL::timestamp with time zone, p_to timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS TABLE(id text, name text, shop text, phone text, deals_count integer, bookings_count integer, subscription_plan text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  RETURN QUERY
    SELECT t.id, t.name, t.shop, t.phone, t.deals_count, t.bookings_count, t.subscription_plan
    FROM (
      SELECT u.id, u.name, u.shop, u.phone,
        count(DISTINCT d.id) FILTER (WHERE d.status IS NULL OR d.status <> 'deleted')::int AS deals_count,
        count(DISTINCT b.barcode) FILTER (
          WHERE b.barcode IS NOT NULL
            AND (p_from IS NULL OR b.created_at >= p_from)
            AND (p_to   IS NULL OR b.created_at <  p_to)
        )::int AS bookings_count,
        sp.subscription_plan
      FROM users u
      LEFT JOIN deals d ON d.store_id = u.id
      LEFT JOIN bookings b ON b.store_id = u.id
      LEFT JOIN store_profiles sp ON sp.store_id = u.id
      WHERE u.user_type = 'seller'
      GROUP BY u.id, u.name, u.shop, u.phone, sp.subscription_plan
    ) t
    ORDER BY t.bookings_count DESC, t.deals_count DESC
    LIMIT GREATEST(1, COALESCE(p_limit, 20));
END $function$
;


-- ═══ FUNCTION admin_unstick_refund(p_barcode text, p_outcome text, p_note text, p_refund_ref text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_unstick_refund(p_barcode text, p_outcome text, p_note text, p_refund_ref text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_b public.bookings%ROWTYPE; v_note text; v_res jsonb; v_uid text;
BEGIN
  v_uid := (SELECT auth.uid())::text;
  IF NOT (public.taki_admin_perm('action_view_finance') OR public.taki_admin_perm('tab_launch')) THEN
    RAISE EXCEPTION 'forbidden: action_view_finance required';
  END IF;
  IF p_outcome NOT IN ('refunded', 'failed') THEN
    RAISE EXCEPTION 'BAD_OUTCOME';
  END IF;

  v_note := btrim(COALESCE(p_note, ''));
  -- 🪤 الحجّة إلزامية لا تجميل: هذا القرار يقول «المال خرج» أو «لم يخرج» بلا
  --    دليلٍ من النظام نفسه، فمصدرُه الوحيد ما رآه إنسانٌ في كشف البوّابة.
  --    وبعد شهرٍ لن يتذكّر أحدٌ لماذا — فتُكتب الآن أو لا يُتّخذ القرار.
  IF length(v_note) < 10 THEN
    RAISE EXCEPTION 'NOTE_REQUIRED';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = p_barcode FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  -- لا يُفكّ إلا العالق: طلبٌ اكتمل ردُّه أو لم يُطلب ردُّه أصلاً لا يُمسّ.
  IF COALESCE(v_b.refund_state, '') <> 'claiming' THEN
    RAISE EXCEPTION 'NOT_STUCK';
  END IF;

  -- التسويةُ تمرّ بنفس الدالّة التي يمرّ بها المسار الطبيعيّ — لا مسارَ ثانياً
  -- يكتب الحالة بيده، وإلا انحرف المساران (وردُّ الكمّية وإشعارُ المشتري
  -- وإشعارُ الدائن كلُّها هناك).
  v_res := public.taki_settle_booking_refund(
             p_barcode,
             (p_outcome = 'refunded'),
             p_refund_ref,
             'فُكَّ يدوياً من الإدارة: ' || v_note);

  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'admin', 'refund_unstuck', 'booking', p_barcode,
          jsonb_build_object('outcome', p_outcome, 'note', v_note,
                             'refund_ref', p_refund_ref,
                             'amount', COALESCE(v_b.refund_amount, v_b.paid_amount),
                             'provider', v_b.payment_provider,
                             'stuck_minutes',
                             GREATEST(0, floor(extract(epoch FROM (now() - v_b.refund_claimed_at)) / 60))::int));

  RETURN jsonb_build_object('ok', true, 'outcome', p_outcome, 'settle', v_res);
END
$function$
;


-- ═══ FUNCTION admin_update_user(p_user_id text, p_updates jsonb) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_update_user(p_user_id text, p_updates jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
    v_caller_id TEXT;
BEGIN
    v_caller_id := auth.uid()::text;
    SELECT user_type INTO v_caller_role FROM public.users WHERE id = v_caller_id;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;
    IF EXISTS (SELECT 1 FROM public.users WHERE id = p_user_id AND is_super_admin = TRUE) THEN
        RAISE EXCEPTION 'cannot modify the owner account';
    END IF;

    UPDATE public.users SET
        name         = COALESCE(p_updates->>'name', name),
        phone        = COALESCE(p_updates->>'phone', phone),
        email        = COALESCE(p_updates->>'email', email),
        shop         = COALESCE(p_updates->>'shop', shop),
        address      = COALESCE(p_updates->>'address', address),
        bio          = COALESCE(p_updates->>'bio', bio),
        avatar_url   = COALESCE(p_updates->>'avatar_url', avatar_url),
        is_suspended = COALESCE((p_updates->>'is_suspended')::BOOLEAN, is_suspended),
        admin_notes  = COALESCE(p_updates->>'admin_notes', admin_notes),
        updated_at   = NOW()
    WHERE id = p_user_id;
    -- user_type intentionally NOT updatable here (privilege-escalation guard).

    INSERT INTO activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
    VALUES (v_caller_id, 'admin', 'admin_update_user', 'user', p_user_id, p_updates);

    RETURN jsonb_build_object('success', true, 'user_id', p_user_id);
END $function$
;


-- ═══ FUNCTION admin_upsert_location(p_id text, p_name text, p_name_en text, p_type text, p_city_id text, p_lat double precision, p_lng double precision) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_upsert_location(p_id text, p_name text, p_name_en text, p_type text, p_city_id text, p_lat double precision, p_lng double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_id text;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;
  IF btrim(COALESCE(p_name,'')) = '' THEN RETURN jsonb_build_object('success', false, 'error', 'name_required'); END IF;
  IF p_type NOT IN ('mall','market') THEN RETURN jsonb_build_object('success', false, 'error', 'bad_type'); END IF;
  IF NOT EXISTS (SELECT 1 FROM cities WHERE id = p_city_id) THEN RETURN jsonb_build_object('success', false, 'error', 'bad_city'); END IF;
  IF p_lat IS NULL OR p_lng IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'coords_required'); END IF;

  v_id := COALESCE(NULLIF(btrim(COALESCE(p_id,'')), ''), 'loc_' || (EXTRACT(EPOCH FROM NOW())*1000)::bigint::text);

  INSERT INTO locations (id, name, name_en, type, city_id, lat, lng)
  VALUES (v_id, btrim(p_name), NULLIF(btrim(COALESCE(p_name_en,'')),''), p_type, p_city_id, p_lat, p_lng)
  ON CONFLICT (id) DO UPDATE SET
    name = EXCLUDED.name, name_en = EXCLUDED.name_en, type = EXCLUDED.type,
    city_id = EXCLUDED.city_id, lat = EXCLUDED.lat, lng = EXCLUDED.lng;

  RETURN jsonb_build_object('success', true, 'id', v_id);
END; $function$
;


-- ═══ FUNCTION admin_user_cohorts(p_months integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_user_cohorts(p_months integer DEFAULT 6)
 RETURNS TABLE(cohort_key text, cohort_label text, registered integer, active_now integer, booked_ever integer, retention_pct numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT is_admin() THEN
        RAISE EXCEPTION 'admin only';
    END IF;
    RETURN QUERY
    WITH months AS (
        SELECT date_trunc('month', now()) - (n || ' months')::INTERVAL AS m
        FROM generate_series(0, GREATEST(p_months, 1) - 1) AS n
    ),
    cohorts AS (
        SELECT date_trunc('month', u.created_at) AS m,
               COUNT(*) AS registered,
               COUNT(*) FILTER (WHERE u.last_active_at >= now() - INTERVAL '30 days') AS active_now,
               COUNT(*) FILTER (WHERE COALESCE(u.total_bookings, 0) > 0) AS booked
        FROM users u
        WHERE u.user_type = 'buyer'
          AND COALESCE(u.is_suspended, FALSE) = FALSE
          AND u.deleted_at IS NULL
        GROUP BY 1
    )
    SELECT to_char(months.m, 'YYYY-MM')::TEXT,
           to_char(months.m, 'Mon YY')::TEXT,
           COALESCE(c.registered, 0)::INT,
           COALESCE(c.active_now, 0)::INT,
           COALESCE(c.booked, 0)::INT,
           CASE WHEN COALESCE(c.registered, 0) = 0 THEN 0
                ELSE ROUND(100.0 * c.active_now / c.registered, 1) END
    FROM months
    LEFT JOIN cohorts c ON c.m = months.m
    ORDER BY months.m ASC;
END;
$function$
;


-- ═══ FUNCTION admin_user_warnings(p_user_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_user_warnings(p_user_id text)
 RETURNS TABLE(id uuid, reason text, context_barcode text, context_message text, admin_name text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'Admin only'; END IF;
  RETURN QUERY
    SELECT w.id, w.reason, w.context_barcode, w.context_message, a.name, w.created_at
    FROM user_warnings w LEFT JOIN users a ON a.id = w.admin_id
    WHERE w.user_id = p_user_id
    ORDER BY w.created_at DESC;
END $function$
;


-- ═══ FUNCTION admin_vat_status_summary() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_vat_status_summary()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_out jsonb;
begin
  if not public.is_admin() then raise exception 'Admin only'; end if;
  select jsonb_build_object(
    'registered',     count(*) filter (where sp.vat_status = 'registered'),
    'not_registered', count(*) filter (where sp.vat_status = 'not_registered'),
    'undeclared',     count(*) filter (where sp.vat_status is null),
    'total',          count(*),
    'merchants', coalesce((
      select jsonb_agg(jsonb_build_object(
               'name', coalesce(nullif(u2.shop,''), u2.name),
               'status', coalesce(sp2.vat_status, 'undeclared'),
               'vat', sp2.vat_number) order by u2.created_at desc)
      from users u2 left join store_profiles sp2 on sp2.store_id = u2.id
      where u2.user_type in ('seller','admin') and u2.deleted_at is null
      limit 200), '[]'::jsonb)
  ) into v_out
  from users u left join store_profiles sp on sp.store_id = u.id
  where u.user_type in ('seller','admin') and u.deleted_at is null;
  return v_out;
end $function$
;


-- ═══ FUNCTION admin_verification_registry(p_ver_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_verification_registry(p_ver_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_v record; v_checks jsonb; v_cfg jsonb; v_spent numeric;
BEGIN
  IF NOT public.taki_admin_perm('tab_verification') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;
  SELECT * INTO v_v FROM public.store_verifications WHERE id = p_ver_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;

  v_cfg := public._taki_wathq_cfg();
  SELECT COALESCE(sum(cost_sar), 0) INTO v_spent
    FROM public.store_verification_checks WHERE done_at >= date_trunc('month', now());

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'kind', c.kind, 'status', c.status, 'http', c.http_status,
           'cost', c.cost_sar, 'error', c.last_error, 'at', c.done_at,
           'asked', c.arg) ORDER BY c.id DESC), '[]'::jsonb)
    INTO v_checks
    FROM public.store_verification_checks c WHERE c.ver_id = p_ver_id;

  RETURN jsonb_build_object(
    'ok', true,
    'subscribed', public._taki_wathq_key() IS NOT NULL,
    'env', v_cfg->>'env',
    'check_owners', (v_cfg->>'check_owners')::boolean,
    'registry', v_v.registry_state,
    'registry_at', v_v.registry_at,
    'cr_national', v_v.cr_national,
    'confirmation_due', v_v.confirmation_due,
    'claimed_name', v_v.claimed_name,
    'legal_name', v_v.legal_name,
    'checks', v_checks,
    'spent_this_month_sar', v_spent,
    'monthly_cap_sar', (v_cfg->>'monthly_cap_sar')::numeric);
END
$function$
;


-- ═══ FUNCTION admin_verification_stats() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_verification_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.taki_admin_perm('tab_verification') THEN
    RAISE EXCEPTION 'غير مصرّح' USING ERRCODE = '42501'; END IF;
  RETURN jsonb_build_object(
    'mode', public.taki_verification_mode(),
    'policy', public.taki_verification_policy(),
    'pending',  (SELECT count(*) FROM public.store_verifications WHERE status='submitted'),
    'oldest_pending_hours', (SELECT ROUND(EXTRACT(EPOCH FROM (now() - MIN(submitted_at)))/3600)::int
                               FROM public.store_verifications WHERE status='submitted'),
    'approved', (SELECT count(*) FROM public.store_verifications WHERE status='approved'),
    'rejected_30d', (SELECT count(*) FROM public.store_verifications
                      WHERE status='rejected' AND decided_at > now() - interval '30 days'),
    'expiring_30d', (SELECT count(*) FROM public.store_verifications
                      WHERE status='approved' AND doc_expiry IS NOT NULL
                        AND doc_expiry <= (current_date + 30)),
    'merchants', (SELECT count(*) FROM public.users WHERE user_type='seller' AND deleted_at IS NULL),
    'would_block', (SELECT count(*) FROM public.users u
                     WHERE u.user_type='seller' AND u.deleted_at IS NULL
                       AND NOT public.taki_store_verified(u.id)
                       AND NOT public.taki_store_grandfathered(u.id)),
    'would_block_live_deals', (SELECT count(*) FROM public.deals d JOIN public.users u ON u.id=d.store_id
                     WHERE d.status='active' AND u.user_type='seller' AND u.deleted_at IS NULL
                       AND NOT public.taki_store_verified(u.id)
                       AND NOT public.taki_store_grandfathered(u.id)));
END
$function$
;


-- ═══ FUNCTION admin_warn_user(p_user_id text, p_message text, p_role text, p_barcode text, p_context_message text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_warn_user(p_user_id text, p_message text, p_role text DEFAULT NULL::text, p_barcode text DEFAULT NULL::text, p_context_message text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_caller text; v_role text; v_count int; v_delay int := 0; v_wid uuid;
BEGIN
  v_caller := auth.uid()::text;
  IF NOT public.is_admin(v_caller) THEN RAISE EXCEPTION 'Admin only'; END IF;
  IF COALESCE(TRIM(p_message), '') = '' THEN RAISE EXCEPTION 'Empty warning'; END IF;

  v_role := COALESCE(p_role, (SELECT user_type FROM users WHERE id = p_user_id));

  -- record the strike FIRST — يبقى مسجلاً حتى يحذفه المالك يدوياً
  INSERT INTO public.user_warnings (user_id, user_role, reason, context_barcode, context_message, admin_id)
  VALUES (p_user_id, v_role, p_message, NULLIF(TRIM(p_barcode), ''), NULLIF(TRIM(p_context_message), ''), v_caller)
  RETURNING id INTO v_wid;

  -- v12.53: تأخير وصول الإشعار للمخالف بدقائق يحددها المالك — يوحي بمراجعة بشرية
  v_delay := COALESCE((SELECT (value->>'warn_delay_minutes')::int FROM platform_settings WHERE key='moderation_settings'), 0);
  IF v_delay <= 0 THEN
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (p_user_id, '⚠️ تنبيه من إدارة تاكي', '⚠️ Warning from TAKI', p_message, p_message, 'system',
            jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
  ELSE
    INSERT INTO public.pending_warnings (warning_id, user_id, message, deliver_at)
    VALUES (v_wid, p_user_id, p_message, now() + make_interval(mins => v_delay));
  END IF;

  SELECT count(*) INTO v_count FROM public.user_warnings WHERE user_id = p_user_id;

  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_caller, 'admin', 'admin_warn_user', 'user', p_user_id, jsonb_build_object('message', p_message, 'count', v_count, 'delay_minutes', v_delay));

  RETURN jsonb_build_object('success', TRUE, 'count', v_count, 'delay_minutes', v_delay);
END $function$
;


-- ═══ FUNCTION admin_wathq_state() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.admin_wathq_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_c record; v_spent numeric; v_cnt jsonb;
BEGIN
  IF NOT (public.taki_admin_perm('tab_tools') OR public.taki_admin_perm('tab_verification')) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;
  SELECT * INTO v_c FROM public.wathq_config WHERE id;
  SELECT COALESCE(sum(cost_sar), 0) INTO v_spent
    FROM public.store_verification_checks WHERE done_at >= date_trunc('month', now());
  SELECT jsonb_object_agg(status, n) INTO v_cnt
    FROM (SELECT status, count(*) AS n FROM public.store_verification_checks GROUP BY status) t;
  RETURN jsonb_build_object(
    'ok', true,
    'subscribed', public._taki_wathq_key() IS NOT NULL,
    'env', v_c.env, 'last4', v_c.key_last4, 'set_at', v_c.key_set_at,
    'check_owners', v_c.check_owners, 'convert_cr', v_c.convert_cr,
    'monthly_cap_sar', v_c.monthly_cap_sar,
    'spent_this_month_sar', v_spent,
    'queue', COALESCE(v_cnt, '{}'::jsonb));
END
$function$
;


-- ═══ FUNCTION analyst_weekly_pulse() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.analyst_weekly_pulse()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    churned int; renewed int; new_this int; new_prev int;
    title text := NULL; body text := NULL;
BEGIN
    -- فترات انتهت الأسبوع الماضي: من جدّد ومن لم يجدّد
    SELECT count(*) FILTER (WHERE NOT EXISTS (
             SELECT 1 FROM subscription_payments p2
             WHERE p2.merchant_id=p.merchant_id AND p2.status='paid' AND p2.period_start > p.period_start)),
           count(*) FILTER (WHERE EXISTS (
             SELECT 1 FROM subscription_payments p2
             WHERE p2.merchant_id=p.merchant_id AND p2.status='paid' AND p2.period_start > p.period_start))
      INTO churned, renewed
      FROM subscription_payments p
     WHERE p.status='paid' AND p.period_end >= now() - interval '7 days' AND p.period_end < now();

    SELECT count(*) INTO new_this FROM users WHERE user_type='seller' AND deleted_at IS NULL
      AND created_at >= now() - interval '7 days';
    SELECT count(*) INTO new_prev FROM users WHERE user_type='seller' AND deleted_at IS NULL
      AND created_at >= now() - interval '14 days' AND created_at < now() - interval '7 days';

    IF churned >= 2 AND churned > renewed THEN
        title := '🚨 المحلل الذكي: بدأ عزوف التجار';
        body  := 'هذا الأسبوع: ' || churned || ' تاجراً انتهى اشتراكهم ولم يجدّدوا مقابل ' || renewed ||
                 ' جدّدوا. افتح تبويب «المحلل الذكي» لرؤية الأسباب المرجّحة لكل تاجر وإرسال توصيات لهم.';
    ELSIF new_this >= 3 AND new_this > new_prev * 2 THEN
        title := '📈 المحلل الذكي: قفزة في انضمام التجار';
        body  := 'انضم ' || new_this || ' تاجراً جديداً هذا الأسبوع (مقابل ' || new_prev ||
                 ' الأسبوع الماضي). افتح «المحلل الذكي» لمعرفة المدن والتصنيفات التي تقود النمو وتعزيزها.';
    END IF;

    IF title IS NOT NULL THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        SELECT u.id, title, title, body, body, 'system',
               jsonb_build_object('from_analyst', true, 'actionUrl', '/admin?tab=analyst'), NOW()
        FROM users u WHERE u.user_type='admin' AND u.deleted_at IS NULL;
    END IF;
END $function$
;


-- ═══ FUNCTION authenticity_counts(p_deal_ids text[]) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.authenticity_counts(p_deal_ids text[])
 RETURNS TABLE(deal_id text, real_count integer, fake_count integer, my_vote boolean)
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT v.deal_id,
           count(*) FILTER (WHERE v.is_real)::int        AS real_count,
           count(*) FILTER (WHERE NOT v.is_real)::int    AS fake_count,
           bool_or(v.is_real) FILTER (WHERE v.user_id = auth.uid()::text) AS my_vote
    FROM deal_authenticity_votes v
    WHERE v.deal_id = ANY(p_deal_ids)
    GROUP BY v.deal_id;
$function$
;


-- ═══ FUNCTION auto_start_seller_trial() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.auto_start_seller_trial()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.user_type = 'seller' THEN
        BEGIN
            PERFORM start_trial_for_merchant(NEW.id);
        EXCEPTION WHEN OTHERS THEN
            -- Don't block user creation if trial start fails.
            NULL;
        END;
    END IF;

    -- Also handle role-change buyer→seller: start trial then.
    IF TG_OP = 'UPDATE' AND OLD.user_type IS DISTINCT FROM NEW.user_type
       AND NEW.user_type = 'seller' THEN
        BEGIN
            PERFORM start_trial_for_merchant(NEW.id);
        EXCEPTION WHEN OTHERS THEN
            NULL;
        END;
    END IF;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION bot__loc_key(p_location_id text, p_lat double precision, p_lng double precision) INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot__loc_key(p_location_id text, p_lat double precision, p_lng double precision)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN p_location_id IS NOT NULL AND p_location_id <> 'other' AND p_location_id NOT LIKE 'custom~_%' ESCAPE '~'
      THEN 'loc:' || p_location_id
    ELSE 'geo:' || round(coalesce(p_lat,0)::numeric,3)::text || ',' || round(coalesce(p_lng,0)::numeric,3)::text
  END
$function$
;


-- ═══ FUNCTION bot_acknowledge_booking(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_acknowledge_booking(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_b bookings%ROWTYPE;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) AND store_id = v_sid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_b.status <> 'pending' THEN RETURN jsonb_build_object('success', false, 'error', 'wrong_status'); END IF;
  UPDATE bookings SET status = 'acknowledged' WHERE barcode = UPPER(p_barcode) AND store_id = v_sid;
  RETURN jsonb_build_object('success', true, 'user_name', COALESCE(v_b.user_name,'—'));
END; $function$
;


-- ═══ FUNCTION bot_active_banners() DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_active_banners()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', id,
    'title', coalesce(nullif(btrim(title_ar),''), nullif(btrim(title_en),''), 'عرض مميّز'),
    'image_url', image_url, 'target_url', target_url,
    'deal_id', deal_id, 'store_id', store_id
  ) ORDER BY display_order ASC NULLS LAST, created_at DESC), '[]'::jsonb)
  FROM banners
  WHERE is_active = true
    AND position = 'home_top'
    AND (expires_at IS NULL OR expires_at > now());
$function$
;


-- ═══ FUNCTION bot_active_season() DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_active_season()
 RETURNS text
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    (SELECT value#>>'{}' FROM platform_settings WHERE key = 'seasonal_theme'),
    ''
  );
$function$
;


-- ═══ FUNCTION bot_add_deal(p_telegram_id bigint, p_item_name text, p_original_price numeric, p_discounted_price numeric, p_quantity integer, p_description text, p_category text, p_images text[], p_location_id text, p_custom_location_name text, p_map_lat double precision, p_map_lng double precision, p_region text, p_city text, p_google_maps_link text, p_size text, p_gender text, p_expiry_type text, p_expiry_date text, p_expires_in_minutes integer, p_starts_at bigint, p_is_unlimited boolean, p_whatsapp_id text, p_max_per_booking integer, p_max_bookings_per_buyer integer, p_rebook_cooldown_minutes integer) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_add_deal(p_telegram_id bigint, p_item_name text, p_original_price numeric, p_discounted_price numeric, p_quantity integer, p_description text, p_category text DEFAULT 'other'::text, p_images text[] DEFAULT '{}'::text[], p_location_id text DEFAULT NULL::text, p_custom_location_name text DEFAULT NULL::text, p_map_lat double precision DEFAULT NULL::double precision, p_map_lng double precision DEFAULT NULL::double precision, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_google_maps_link text DEFAULT NULL::text, p_size text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_expiry_type text DEFAULT NULL::text, p_expiry_date text DEFAULT NULL::text, p_expires_in_minutes integer DEFAULT NULL::integer, p_starts_at bigint DEFAULT NULL::bigint, p_is_unlimited boolean DEFAULT NULL::boolean, p_whatsapp_id text DEFAULT NULL::text, p_max_per_booking integer DEFAULT NULL::integer, p_max_bookings_per_buyer integer DEFAULT NULL::integer, p_rebook_cooldown_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_shop text; v_new_id text; v_discount int; v_ref deals%ROWTYPE;
  v_unlimited boolean; v_qty integer; v_minutes integer; v_now bigint;
  v_loc text; v_cust text; v_lat double precision; v_lng double precision;
  v_region text; v_city text; v_gmap text; v_has_loc boolean; v_src text;
BEGIN
  SELECT id, shop INTO v_sid, v_shop FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  IF NOT public.ensure_active_subscription(v_sid) THEN RETURN jsonb_build_object('success',false,'error','no_subscription'); END IF;
  IF p_discounted_price >= p_original_price THEN RETURN jsonb_build_object('success',false,'error','invalid_price'); END IF;

  SELECT * INTO v_ref FROM deals WHERE store_id=v_sid ORDER BY created_at DESC LIMIT 1;
  v_has_loc := (p_location_id IS NOT NULL) OR (p_map_lat IS NOT NULL AND p_map_lng IS NOT NULL);
  IF v_has_loc THEN
    v_loc:=p_location_id; v_cust:=p_custom_location_name; v_lat:=p_map_lat; v_lng:=p_map_lng;
    v_region:=p_region; v_city:=p_city; v_gmap:=p_google_maps_link;
  ELSE
    v_loc:=v_ref.location_id; v_cust:=v_ref.custom_location_name; v_lat:=v_ref.map_lat; v_lng:=v_ref.map_lng;
    v_region:=v_ref.region; v_city:=v_ref.city; v_gmap:=v_ref.google_maps_link;
  END IF;

  v_unlimited := COALESCE(p_is_unlimited, (p_quantity IS NULL OR p_quantity = 0));
  v_qty       := CASE WHEN v_unlimited THEN NULL ELSE GREATEST(0, p_quantity) END;
  v_minutes   := COALESCE(p_expires_in_minutes, v_ref.expires_in_minutes, 525600);
  v_discount  := ROUND(((p_original_price - p_discounted_price)/p_original_price)*100);
  v_now       := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
  v_new_id    := v_now::text;
  v_src       := CASE WHEN p_whatsapp_id IS NOT NULL THEN 'whatsapp' ELSE 'telegram' END;

  BEGIN
    INSERT INTO deals (id, store_id, shop_name, item_name, original_price, discounted_price,
      discount_percentage, quantity, is_unlimited, initial_quantity, images, description, category, status,
      created_at, location_id, custom_location_name, map_lat, map_lng, region, city, google_maps_link,
      expires_in_minutes, prep_time, size, gender, expiry_type, expiry_date, starts_at, source,
      max_per_booking, max_bookings_per_buyer, rebook_cooldown_minutes)
    VALUES (v_new_id, v_sid, v_shop, p_item_name, p_original_price, p_discounted_price,
      v_discount, v_qty, v_unlimited, v_qty, COALESCE(p_images,'{}'), p_description,
      COALESCE(NULLIF(btrim(COALESCE(p_category,'')),''),'other'), 'active',
      v_now, v_loc, v_cust, v_lat, v_lng, v_region, v_city, v_gmap,
      v_minutes, v_ref.prep_time, NULLIF(btrim(COALESCE(p_size,'')),''),
      COALESCE(NULLIF(btrim(COALESCE(p_gender,'')),''),'all'),
      NULLIF(btrim(COALESCE(p_expiry_type,'')),''), NULLIF(btrim(COALESCE(p_expiry_date,'')),''),
      p_starts_at, v_src,
      NULLIF(COALESCE(p_max_per_booking,0), 0),
      NULLIF(COALESCE(p_max_bookings_per_buyer,0), 0),
      NULLIF(COALESCE(p_rebook_cooldown_minutes,0), 0));
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE '%LOCATION_LIMIT_EXCEEDED%' THEN
      RETURN jsonb_build_object('success', false, 'error', 'location_limit');
    END IF;
    RETURN jsonb_build_object('success', false, 'error', 'blocked', 'detail', SQLERRM);
  END;
  RETURN jsonb_build_object('success', true, 'deal_id', v_new_id, 'discount', v_discount);
END; $function$
;


-- ═══ FUNCTION bot_add_notif_keyword(p_telegram_id bigint, p_keyword text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_add_notif_keyword(p_telegram_id bigint, p_keyword text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_kw text; v_list text[];
BEGIN
  v_kw := btrim(COALESCE(p_keyword, ''));
  IF length(v_kw) < 2 OR length(v_kw) > 40 THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_length');
  END IF;
  SELECT id, COALESCE(notif_keywords, ARRAY[]::text[]) INTO v_uid, v_list
    FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF EXISTS (SELECT 1 FROM unnest(v_list) k WHERE lower(k) = lower(v_kw)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'exists', 'keywords', to_jsonb(v_list));
  END IF;
  IF COALESCE(array_length(v_list, 1), 0) >= 20 THEN
    RETURN jsonb_build_object('success', false, 'error', 'too_many', 'keywords', to_jsonb(v_list));
  END IF;
  v_list := array_append(v_list, v_kw::text);
  UPDATE users SET notif_keywords = v_list WHERE id = v_uid;
  RETURN jsonb_build_object('success', true, 'keywords', to_jsonb(v_list));
END; $function$
;


-- ═══ FUNCTION bot_add_smart_alert(p_telegram_id bigint, p_rule jsonb, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_add_smart_alert(p_telegram_id bigint, p_rule jsonb, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_arr jsonb; v_has boolean;
BEGIN
  SELECT id, smart_alerts INTO v_uid, v_arr FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF v_arr IS NULL OR jsonb_typeof(v_arr) <> 'array' THEN v_arr := '[]'::jsonb; END IF;
  IF jsonb_array_length(v_arr) >= 10 THEN RETURN jsonb_build_object('success',false,'error','too_many'); END IF;
  IF p_rule IS NULL OR jsonb_typeof(p_rule) <> 'object' THEN RETURN jsonb_build_object('success',false,'error','empty_rule'); END IF;

  v_has := (jsonb_typeof(p_rule->'regions')='array'    AND jsonb_array_length(p_rule->'regions')>0)
        OR (jsonb_typeof(p_rule->'cities')='array'     AND jsonb_array_length(p_rule->'cities')>0)
        OR (jsonb_typeof(p_rule->'malls')='array'      AND jsonb_array_length(p_rule->'malls')>0)
        OR (jsonb_typeof(p_rule->'categories')='array' AND jsonb_array_length(p_rule->'categories')>0)
        OR (jsonb_typeof(p_rule->'keywords')='array'   AND jsonb_array_length(p_rule->'keywords')>0)
        OR (jsonb_typeof(p_rule->'coords')='object'    AND (p_rule->>'radiusKm') IS NOT NULL);
  IF NOT v_has THEN RETURN jsonb_build_object('success',false,'error','empty_rule'); END IF;

  v_arr := v_arr || jsonb_build_array(p_rule);
  IF p_whatsapp_id IS NOT NULL THEN
    UPDATE users SET smart_alerts=v_arr, notify_via_whatsapp=true, updated_at=NOW() WHERE id=v_uid;
  ELSE
    UPDATE users SET smart_alerts=v_arr, notify_via_telegram=true, updated_at=NOW() WHERE id=v_uid;
  END IF;
  RETURN jsonb_build_object('success',true,'count',jsonb_array_length(v_arr));
END; $function$
;


-- ═══ FUNCTION bot_book_deal(p_telegram_id bigint, p_deal_id text, p_quantity integer, p_notes text, p_prep_time text, p_whatsapp_id text, p_location_id text, p_fulfillment text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_book_deal(p_telegram_id bigint, p_deal_id text, p_quantity integer DEFAULT 1, p_notes text DEFAULT NULL::text, p_prep_time text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_fulfillment text DEFAULT 'pickup'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user users%ROWTYPE; v_deal deals%ROWTYPE; v_barcode text; v_backup text; v_expiry bigint; v_now bigint; v_prep text; v_st jsonb; v_src text;
        v_cnt int; v_last timestamptz; v_wait int; v_loc_id text; v_loc_avail int; v_loc_name text; v_avail_now int;
        v_fulfil text; v_addr jsonb; v_q jsonb; v_pay text := 'cod'; v_fee numeric; v_sell jsonb;
BEGIN
  SELECT * INTO v_user FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF v_user.is_suspended THEN RETURN jsonb_build_object('success', false, 'error', 'suspended'); END IF;
  IF p_quantity < 1 THEN p_quantity := 1; END IF;

  SELECT * INTO v_deal FROM deals WHERE id = p_deal_id LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'deal_not_found'); END IF;
  IF v_deal.status <> 'active' THEN RETURN jsonb_build_object('success', false, 'error', 'deal_inactive'); END IF;

  -- v14.08 — لا بيع قبل إقرار التاجر بطريقة الحساب (نفس حارس الموقع).
  v_sell := public.store_can_sell(v_deal.store_id);
  IF NOT COALESCE((v_sell->>'ok')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'store_no_payment', 'reason', v_sell->>'reason');
  END IF;

  IF v_deal.options IS NOT NULL AND jsonb_typeof(v_deal.options) = 'array' AND EXISTS (
       SELECT 1 FROM jsonb_array_elements(v_deal.options) g
       WHERE COALESCE((g->>'required')::boolean, false))
  THEN RETURN jsonb_build_object('success', false, 'error', 'needs_options'); END IF;
  IF v_deal.variants IS NOT NULL AND jsonb_typeof(v_deal.variants) = 'array'
     AND jsonb_array_length(v_deal.variants) > 0
  THEN RETURN jsonb_build_object('success', false, 'error', 'needs_options'); END IF;

  v_st := public.store_is_open((SELECT working_hours FROM users WHERE id = v_deal.store_id));
  IF (v_st->>'open')::boolean = false THEN
    RETURN jsonb_build_object('success', false, 'error', 'shop_closed', 'opens_in_min', (v_st->>'opens_in_min')::int);
  END IF;

  v_loc_id := NULLIF(btrim(COALESCE(p_location_id, '')), '');
  IF v_deal.locations IS NOT NULL AND jsonb_typeof(v_deal.locations) = 'array'
     AND jsonb_array_length(v_deal.locations) > 0 THEN
    IF v_loc_id IS NULL AND jsonb_array_length(v_deal.locations) = 1 THEN
      v_loc_id := v_deal.locations->0->>'id';
    END IF;
    IF v_loc_id IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'needs_location',
        'locations', (SELECT jsonb_agg(jsonb_build_object(
            'id', e->>'id',
            'name', COALESCE(NULLIF(e->>'name',''), 'فرع'),
            'quantity', CASE WHEN v_deal.loc_qty_mode = 'per_location'
                             THEN NULLIF(e->>'quantity','')::int ELSE NULL END))
          FROM jsonb_array_elements(v_deal.locations) e));
    END IF;
    SELECT COALESCE(NULLIF(e->>'name',''),'فرع'), NULLIF(e->>'quantity','')::int
      INTO v_loc_name, v_loc_avail
      FROM jsonb_array_elements(v_deal.locations) e
     WHERE e->>'id' = v_loc_id LIMIT 1;
    IF v_loc_name IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'bad_location');
    END IF;
    IF v_deal.loc_qty_mode = 'per_location' AND v_loc_avail IS NOT NULL AND v_loc_avail < p_quantity THEN
      RETURN jsonb_build_object('success', false, 'error', 'no_quantity', 'available', GREATEST(v_loc_avail, 0));
    END IF;
  ELSE
    v_loc_id := NULL;
  END IF;

  IF NOT COALESCE(v_deal.is_unlimited, false)
     AND COALESCE(v_deal.initial_quantity, 0) > 0
     AND COALESCE(v_deal.quantity, 0) < p_quantity THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_quantity', 'available', GREATEST(COALESCE(v_deal.quantity, 0), 0));
  END IF;

  IF COALESCE(v_deal.max_per_booking, 0) > 0 AND p_quantity > v_deal.max_per_booking THEN
    RETURN jsonb_build_object('success', false, 'error', 'max_qty', 'limit', v_deal.max_per_booking);
  END IF;
  IF COALESCE(v_deal.max_bookings_per_buyer, 0) > 0 THEN
    SELECT count(*) INTO v_cnt FROM bookings
     WHERE deal_id = v_deal.id AND user_id = v_user.id
       AND status IN ('pending','acknowledged','completed');
    IF v_cnt >= v_deal.max_bookings_per_buyer THEN
      RETURN jsonb_build_object('success', false, 'error', 'rebook_limit', 'limit', v_deal.max_bookings_per_buyer);
    END IF;
  END IF;
  IF COALESCE(v_deal.rebook_cooldown_minutes, 0) > 0 THEN
    SELECT max(completed_at) INTO v_last FROM bookings
     WHERE deal_id = v_deal.id AND user_id = v_user.id AND status = 'completed';
    IF v_last IS NOT NULL AND v_last + (v_deal.rebook_cooldown_minutes || ' minutes')::interval > now() THEN
      v_wait := CEIL(EXTRACT(EPOCH FROM (v_last + (v_deal.rebook_cooldown_minutes || ' minutes')::interval - now())) / 60)::int;
      RETURN jsonb_build_object('success', false, 'error', 'rebook_wait', 'wait_minutes', GREATEST(v_wait,1));
    END IF;
  END IF;

  v_fulfil := CASE WHEN lower(COALESCE(p_fulfillment, 'pickup')) = 'delivery' THEN 'delivery' ELSE 'pickup' END;
  IF v_fulfil = 'delivery' THEN
    v_addr := v_user.delivery_address;
    IF v_addr IS NULL OR (v_addr->>'lat') IS NULL THEN
      RETURN jsonb_build_object('success', false, 'error', 'delivery_no_address');
    END IF;
    -- ⚠️ الفرع يُمرَّر: نفس ما يقيسه حارس الإدراج بالضبط.
    v_q := public.delivery_quote(v_deal.store_id, (v_addr->>'lat')::float8, (v_addr->>'lng')::float8, v_loc_id);
    IF NOT COALESCE((v_q->>'available')::boolean, false) THEN
      RETURN jsonb_build_object('success', false, 'error', 'delivery_unavailable', 'reason', v_q->>'reason');
    END IF;
    IF COALESCE((v_q->>'min_order')::numeric, 0) > v_deal.discounted_price * p_quantity THEN
      RETURN jsonb_build_object('success', false, 'error', 'delivery_min_order', 'min_order', (v_q->>'min_order')::numeric);
    END IF;
    v_pay := CASE WHEN v_q->>'payment' = 'card' THEN 'online' ELSE 'cod' END;
    v_fee := (v_q->>'fee')::numeric;
  ELSIF NOT COALESCE((v_sell->>'accepts_cod')::boolean, true) THEN
    -- متجر «بطاقة فقط» — الاستلام من المتجر يُدفع إلكترونياً كذلك.
    v_pay := 'online';
  END IF;

  v_prep := COALESCE(NULLIF(btrim(COALESCE(p_prep_time,'')), ''), v_deal.prep_time, 'arrival');
  v_now := (EXTRACT(EPOCH FROM NOW()) * 1000)::bigint;
  v_src := CASE WHEN p_whatsapp_id IS NOT NULL THEN 'whatsapp' ELSE 'telegram' END;
  LOOP
    v_barcode := _bot_gen_barcode();
    EXIT WHEN NOT EXISTS (SELECT 1 FROM bookings WHERE barcode = v_barcode);
  END LOOP;
  v_backup := _bot_gen_barcode();
  v_expiry := v_now + 7200000;

  BEGIN
    INSERT INTO bookings (barcode, backup_code, deal_id, user_id, store_id, user_name, user_phone,
      booked_quantity, prep_time, notes, status, booked_at, expiry_time, created_at, source,
      location_id, payment_method, fulfillment, delivery_address)
    VALUES (v_barcode, v_backup, p_deal_id, v_user.id, v_deal.store_id, v_user.name, v_user.phone,
      p_quantity, v_prep, NULLIF(btrim(COALESCE(p_notes,'')),''), 'pending', v_now, v_expiry, NOW(), v_src,
      v_loc_id, v_pay, v_fulfil, CASE WHEN v_fulfil = 'delivery' THEN v_addr ELSE NULL END);
  EXCEPTION
    WHEN SQLSTATE 'P0010' THEN
      SELECT COALESCE(quantity, 0) INTO v_avail_now FROM deals WHERE id = p_deal_id;
      RETURN jsonb_build_object('success', false, 'error', 'no_quantity', 'available', GREATEST(COALESCE(v_avail_now,0),0));
    WHEN SQLSTATE 'P0011' THEN
      RETURN jsonb_build_object('success', false, 'error', 'rate_limited', 'msg', SQLERRM);
    WHEN SQLSTATE 'P0013' THEN
      RETURN jsonb_build_object('success', false, 'error', 'delivery_unavailable', 'msg', SQLERRM);
  END;

  RETURN jsonb_build_object('success', true, 'barcode', v_barcode, 'deal_name', v_deal.item_name,
    'shop_name', v_deal.shop_name, 'store_id', v_deal.store_id, 'quantity', p_quantity, 'prep_time', v_prep,
    'location_id', v_loc_id, 'location_name', v_loc_name,
    'fulfillment', v_fulfil, 'delivery_fee', v_fee, 'delivery_label', v_addr->>'label',
    'payment_method', v_pay, 'unit_price', v_deal.discounted_price,
    'expiry_at', to_timestamp(v_expiry::double precision / 1000));
END; $function$
;


-- ═══ FUNCTION bot_booking_chat(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_booking_chat(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_b bookings%ROWTYPE; v_role text; v_msgs jsonb; v_my int; v_other int;
        v_other_name text; v_deal_name text;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_uid = v_b.user_id THEN v_role := 'buyer';
  ELSIF v_uid = v_b.store_id THEN v_role := 'seller';
  ELSE RETURN jsonb_build_object('success', false, 'error', 'not_authorized'); END IF;

  UPDATE booking_messages SET read_at = NOW()
    WHERE barcode = v_b.barcode AND sender_role <> v_role AND read_at IS NULL;

  -- `attachment` مسارٌ داخل مستودع خاصّ، لا عنوان يُفتح. البوت يبادله برابط
  -- موقّع قصير العمر عبر الدالة الطرفية، وهي تتحقّق من العضوية مرّة أخرى.
  SELECT jsonb_agg(jsonb_build_object('role', m.sender_role, 'body', m.body, 'at', m.created_at,
                                      'mine', (m.sender_role = v_role),
                                      'attachment', m.attachment_path) ORDER BY m.created_at)
    INTO v_msgs FROM (SELECT * FROM booking_messages WHERE barcode = v_b.barcode
                       ORDER BY created_at DESC
                       LIMIT (public.taki_chat_limits()->>'bot_page')::int) m;
  SELECT count(*) FILTER (WHERE sender_role = v_role), count(*) FILTER (WHERE sender_role <> v_role)
    INTO v_my, v_other FROM booking_messages WHERE barcode = v_b.barcode;

  IF v_role = 'buyer' THEN SELECT COALESCE(NULLIF(shop,''), NULLIF(name,''), 'التاجر') INTO v_other_name FROM users WHERE id = v_b.store_id;
  ELSE v_other_name := COALESCE(NULLIF(v_b.user_name,''), 'المشتري'); END IF;
  SELECT item_name INTO v_deal_name FROM deals WHERE id = v_b.deal_id;

  -- v14.93 — `cap` يُعاد للبوتين كي لا يُثبِّتا الرقم نصّاً في واجهتهما. 0 = بلا حدّ.
  RETURN jsonb_build_object('success', true, 'role', v_role, 'status', v_b.status, 'barcode', v_b.barcode,
    'uid', v_uid,
    'deal_name', COALESCE(v_deal_name,'العرض'), 'other_name', v_other_name,
    'cap', (public.taki_chat_limits()->>'per_booking')::int,
    'my_count', COALESCE(v_my,0), 'other_count', COALESCE(v_other,0), 'messages', COALESCE(v_msgs,'[]'::jsonb));
END $function$
;


-- ═══ FUNCTION bot_booking_contact(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_booking_contact(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_role text; v_b bookings%ROWTYPE; v_phone text; v_name text;
BEGIN
  SELECT id, user_type INTO v_uid, v_role FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode=UPPER(p_barcode) LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  IF v_uid = v_b.user_id THEN
    SELECT COALESCE(NULLIF(btrim(sp.phone),''), NULLIF(btrim(u.contact_phone),''), NULLIF(btrim(u.phone),'')),
           COALESCE(NULLIF(btrim(u.shop),''), NULLIF(btrim(u.name),''),'المتجر')
      INTO v_phone, v_name
      FROM users u LEFT JOIN store_profiles sp ON sp.store_id=u.id WHERE u.id=v_b.store_id;
    RETURN jsonb_build_object('success',true,'phone',v_phone,'name',v_name,'who','store');
  ELSIF v_uid = v_b.store_id THEN
    SELECT NULLIF(btrim(v_b.user_phone),''), COALESCE(NULLIF(btrim(v_b.user_name),''),'العميل') INTO v_phone, v_name;
    RETURN jsonb_build_object('success',true,'phone',v_phone,'name',v_name,'who','buyer');
  END IF;
  RETURN jsonb_build_object('success',false,'error','not_authorized');
END; $function$
;


-- ═══ FUNCTION bot_booking_countdown(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_booking_countdown(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_b bookings%ROWTYPE; v_deal text;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) LIMIT 1;
  IF NOT FOUND OR (v_b.user_id <> v_uid AND v_b.store_id <> v_uid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  SELECT item_name INTO v_deal FROM deals WHERE id = v_b.deal_id;
  RETURN jsonb_build_object(
    'success', true,
    'status', v_b.status,
    'expiry_time', v_b.expiry_time,
    'barcode', v_b.barcode,
    'deal_name', COALESCE(v_deal, ''),
    'role', CASE WHEN v_uid = v_b.user_id THEN 'buyer' ELSE 'seller' END
  );
END; $function$
;


-- ═══ FUNCTION bot_browse_deals(p_sort text, p_category text, p_lat double precision, p_lng double precision, p_radius_km double precision, p_limit integer, p_offset integer, p_region text, p_city text, p_location_id text, p_open_now boolean, p_upcoming boolean, p_season text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_browse_deals(p_sort text DEFAULT 'newest'::text, p_category text DEFAULT NULL::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_radius_km double precision DEFAULT NULL::double precision, p_limit integer DEFAULT 8, p_offset integer DEFAULT 0, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_open_now boolean DEFAULT false, p_upcoming boolean DEFAULT false, p_season text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now    bigint  := (extract(epoch from now())*1000)::bigint;
  v_lim    integer := least(greatest(coalesce(p_limit,8),1),12);
  v_off    integer := greatest(coalesce(p_offset,0),0);
  v_geo    boolean := (p_lat IS NOT NULL AND p_lng IS NOT NULL);
  -- ترتيب الطبقات من إعداد المالك؛ غيابه = الترتيب التقليدي.
  v_tiers  jsonb;
  v_result jsonb;
BEGIN
  SELECT COALESCE((SELECT value->'tier_order' FROM platform_settings WHERE key='sponsor_layout' LIMIT 1),
                  '["sponsor","ad","star","none"]'::jsonb)
    INTO v_tiers;
  IF jsonb_typeof(v_tiers) IS DISTINCT FROM 'array' OR jsonb_array_length(v_tiers) = 0 THEN
    v_tiers := '["sponsor","ad","star","none"]'::jsonb;
  END IF;

  WITH base AS (
    SELECT d.*,
      u.working_hours AS store_wh,
      coalesce(d.discount_percentage,
               round(((d.original_price - d.discounted_price)/nullif(d.original_price,0))*100)::int) AS disc_pct,
      CASE WHEN v_geo AND d.map_lat IS NOT NULL AND d.map_lng IS NOT NULL
           THEN 6371 * acos(least(1, greatest(-1,
                  sin(radians(p_lat))*sin(radians(d.map_lat)) +
                  cos(radians(p_lat))*cos(radians(d.map_lat))*cos(radians(d.map_lng - p_lng)))))
           ELSE NULL END AS dist_km,
      d.auth_real_count AS av_real,
      d.auth_fake_count AS av_fake,
      sp.label_type                AS sponsor_label,
      (sp.store_id IS NOT NULL)    AS is_sponsored,
      coalesce(sp.priority,0)      AS sponsor_priority
    FROM deals d
    LEFT JOIN users u ON u.id = d.store_id
    LEFT JOIN sponsors sp ON sp.store_id = d.store_id
         AND sp.is_active
         AND (sp.starts_at  IS NULL OR sp.starts_at  <= now())
         AND (sp.expires_at IS NULL OR sp.expires_at >  now())
    WHERE d.status = 'active'
      AND NOT COALESCE(d.sold_out,false)
      AND (d.is_unlimited OR COALESCE(d.quantity,0) > 0 OR COALESCE(d.initial_quantity,0) <= 0)
      AND ( (NOT p_upcoming AND (d.starts_at IS NULL OR d.starts_at <= v_now))
            OR (p_upcoming AND d.starts_at IS NOT NULL AND d.starts_at > v_now AND d.starts_at <= v_now + 604800000) )
      AND (p_season      IS NULL OR d.season_id = p_season)
      AND (p_category    IS NULL OR p_category = 'all' OR d.category = p_category)
      AND (p_region      IS NULL OR d.region = p_region)
      AND (p_city        IS NULL OR d.city = p_city)
      AND (p_location_id IS NULL OR d.location_id = p_location_id)
      AND (p_upcoming OR NOT p_open_now OR (public.store_is_open(u.working_hours)->>'open')::boolean)
  ),
  filtered AS (
    SELECT * FROM base
    WHERE ( (NOT (v_geo AND p_radius_km IS NOT NULL AND p_radius_km > 0))
         OR (dist_km IS NOT NULL AND dist_km <= p_radius_km) )
      AND (coalesce(p_sort,'') <> 'real' OR av_fake <= av_real)
  ),
  ranked AS (
    SELECT * FROM (
      SELECT f.*, row_number() OVER (PARTITION BY f.store_id ORDER BY f.created_at DESC) AS store_rn
      FROM filtered f
    ) t
    ORDER BY
      CASE WHEN NOT p_upcoming AND t.is_sponsored AND t.store_rn = 1
           THEN coalesce((SELECT (100 - o.ord)::int
                          FROM jsonb_array_elements_text(v_tiers) WITH ORDINALITY o(val, ord)
                          WHERE o.val = coalesce(t.sponsor_label,'ad') LIMIT 1), 0)
           ELSE 0 END DESC,
      CASE WHEN NOT p_upcoming AND t.is_sponsored AND t.store_rn = 1
           THEN t.sponsor_priority END DESC NULLS LAST,
      CASE WHEN p_upcoming   THEN t.starts_at END ASC  NULLS LAST,
      CASE WHEN p_sort='real'      THEN (t.av_real::numeric / nullif(t.av_real + t.av_fake, 0)) END DESC NULLS LAST,
      CASE WHEN p_sort='real'      THEN t.av_real END DESC,
      CASE WHEN p_sort='nearby'    THEN t.dist_km END ASC  NULLS LAST,
      CASE WHEN p_sort='popular'   THEN t.bookings_count END DESC NULLS LAST,
      CASE WHEN p_sort='popular'   THEN t.views END DESC NULLS LAST,
      CASE WHEN p_sort='discount'  THEN t.disc_pct END DESC NULLS LAST,
      CASE WHEN p_sort='sponsored' THEN (t.is_sponsored)::int END DESC NULLS LAST,
      CASE WHEN p_sort='sponsored' THEN t.sponsor_priority END DESC NULLS LAST,
      t.created_at DESC
    LIMIT v_lim OFFSET v_off
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id',id,'item_name',item_name,'shop_name',shop_name,'category',category,
    'original_price',original_price,'discounted_price',discounted_price,'discount_percentage',disc_pct,
    'quantity',quantity,'is_unlimited',is_unlimited,'initial_quantity',initial_quantity,
    'prep_time',prep_time,'expiry_type',expiry_type,'expiry_date',expiry_date,
    'expires_in_minutes',expires_in_minutes,'starts_at',starts_at,'created_at',created_at,
    'views',views,'clicks',clicks,'map_lat',map_lat,'map_lng',map_lng,
    'google_maps_link',google_maps_link,'city',city,'region',region,
    'image',(images)[1],'images_count',coalesce(array_length(images,1),0),
    'distance_km', CASE WHEN dist_km IS NULL THEN NULL ELSE round(dist_km::numeric,1) END,
    'bookings_count',bookings_count,'is_sponsored',is_sponsored,'sponsor_label',sponsor_label,
    'auth_real', av_real,
    'auth_fake', av_fake,
    'max_per_booking', max_per_booking,
    'working_hours',store_wh,'open_status',public.store_is_open(store_wh)
  )) INTO v_result FROM ranked;
  RETURN coalesce(v_result,'[]'::jsonb);
END; $function$
;


-- ═══ FUNCTION bot_buyer_confirm_receipt(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_buyer_confirm_receipt(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_b public.bookings%ROWTYPE; v_left integer; v_anchor bigint;
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('success', false, 'error', 'forbidden');
  END IF;

  SELECT id INTO v_uid FROM public.users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode)) AND user_id = v_uid;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  -- v15.41 — الزرُّ لكلّ طلبٍ حيّ، والتوصيلُ وحده يشترط انطلاقَ المندوب.
  IF v_b.status NOT IN ('pending','acknowledged') THEN
    RETURN jsonb_build_object('success',false,'error','closed'); END IF;

  -- 🔴 v15.49 — نفسُ حقيقة الانطلاق التي يقرؤها الموقع، لا نسخةٌ ثانية.
  IF COALESCE(v_b.fulfillment,'pickup') = 'delivery'
     AND NOT public.taki_delivery_dispatched(v_b.barcode) THEN
    RETURN jsonb_build_object('success',false,'error','not_dispatched'); END IF;

  -- 🔴 v15.42 — نفسُ المهلة، ونفسُ الساعة. والثواني تعود للبوت فيصوغها بـ
  -- `shared/arPlural.js` — فلا رقمَ مكتوبٌ نصّاً في سلسلةٍ ولا في SQL.
  -- 🔴 v15.44 (أمرُ ناصر) — الساعةُ تبدأ من **تأكيد التاجر**؛ وإن لم يؤكّد
  --    فتحةٌ احتياطيّة في آخر المهلة كي لا تبقى المشترية بلا مخرج.
  v_anchor := public.taki_self_close_opens_at(v_b);
  v_left := ceil((v_anchor - (EXTRACT(EPOCH FROM NOW())*1000)::bigint) / 1000.0);
  IF v_left > 0 AND v_b.acknowledged_at IS NULL AND v_b.status <> 'acknowledged' THEN
    RETURN jsonb_build_object('success',false,'error','not_acknowledged','wait_seconds',v_left); END IF;
  IF v_left > 0 THEN
    RETURN jsonb_build_object('success',false,'error','too_soon','wait_seconds',v_left); END IF;

  UPDATE public.bookings SET status='completed', completed_by='buyer'
   WHERE barcode = v_b.barcode AND status IN ('pending','acknowledged');

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
  VALUES (v_b.store_id, '✅ أكّد المشتري الاستلام', '✅ Buyer confirmed receipt',
          'أكّد المشتري استلام الطلب ' || v_b.barcode,
          'The buyer confirmed receiving order ' || v_b.barcode,
          'booking',
          jsonb_build_object('audience','seller','event','buyer_confirmed',
                             'barcode', v_b.barcode, 'dealId', v_b.deal_id),
          NOW());

  RETURN jsonb_build_object('success', true, 'barcode', v_b.barcode);
END;
$function$
;


-- ═══ FUNCTION bot_cancel_booking(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_cancel_booking(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_b bookings%ROWTYPE;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_b.user_id <> v_uid AND v_b.store_id <> v_uid THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  -- v14.18 — نفس حارس الموقع حرفياً: البوتان لا يفتحان باباً يُغلقه الموقع.
  IF v_b.paid_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'paid_needs_refund', 'barcode', v_b.barcode);
  END IF;
  IF v_b.status NOT IN ('pending','acknowledged') THEN
    RETURN jsonb_build_object('success', false, 'error', 'cannot_cancel', 'status', v_b.status);
  END IF;
  UPDATE bookings
     SET status = 'cancelled',
         cancelled_by = CASE WHEN v_uid = v_b.store_id THEN 'seller' ELSE 'buyer' END
   WHERE barcode = UPPER(p_barcode);
  RETURN jsonb_build_object('success', true);
END; $function$
;


-- ═══ FUNCTION bot_cast_authenticity_vote(p_deal_id text, p_is_real boolean, p_telegram_id bigint, p_whatsapp_id text, p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_cast_authenticity_vote(p_deal_id text, p_is_real boolean, p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text, p_barcode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_store text; v_deal text; v_existing boolean;
BEGIN
    v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
    IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
    IF p_barcode IS NOT NULL THEN
        SELECT deal_id INTO v_deal FROM bookings
          WHERE barcode = p_barcode AND user_id = v_uid AND status = 'completed' LIMIT 1;
        IF v_deal IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_completed'); END IF;
    ELSE
        v_deal := p_deal_id;
    END IF;
    SELECT store_id INTO v_store FROM deals WHERE id = v_deal;
    IF v_store IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'deal_not_found'); END IF;
    IF NOT EXISTS (SELECT 1 FROM bookings WHERE deal_id = v_deal AND user_id = v_uid AND status = 'completed') THEN
        RETURN jsonb_build_object('success', false, 'error', 'purchase_required');
    END IF;
    SELECT is_real INTO v_existing FROM deal_authenticity_votes WHERE deal_id = v_deal AND user_id = v_uid;
    -- v12.29: re-voting UPDATES the previous vote (no longer immutable)
    INSERT INTO deal_authenticity_votes (deal_id, store_id, user_id, is_real)
    VALUES (v_deal, v_store, v_uid, p_is_real)
    ON CONFLICT (deal_id, user_id) DO UPDATE SET is_real = EXCLUDED.is_real;
    RETURN jsonb_build_object(
        'success', true,
        'already', false,
        'changed', (v_existing IS NOT NULL AND v_existing IS DISTINCT FROM p_is_real),
        'is_real', p_is_real
    );
END; $function$
;


-- ═══ FUNCTION bot_complete_booking(p_telegram_id bigint, p_barcode text, p_message text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_complete_booking(p_telegram_id bigint, p_barcode text, p_message text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_b bookings%ROWTYPE; v_msg text; v_deal_name text;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode=UPPER(p_barcode) AND store_id=v_sid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  IF v_b.status='completed' THEN RETURN jsonb_build_object('success',false,'error','already_completed'); END IF;
  IF v_b.status='cancelled' THEN RETURN jsonb_build_object('success',false,'error','cancelled'); END IF;
  -- v14.42 — ملاحظة التاجر تُحفظ على الطلب لا في نصّ إشعارٍ عابر.
  -- 🪤 كانت `p_message` تُستعمل لصياغة الإشعار **فقط**: التاجر يكتب «تُرك عند
  -- الحارس» فتصل رسالةً تُقرأ مرّة وتضيع، ولا تظهر في بطاقة الطلب ولا في
  -- «💬 ملاحظة التاجر» التي يقرؤها المشتري في الموقع.
  UPDATE bookings
     SET status='completed', completed_at=NOW(),
         merchant_note = COALESCE(NULLIF(btrim(COALESCE(p_message,'')),''), merchant_note)
   WHERE barcode=UPPER(p_barcode) AND store_id=v_sid;

  v_msg := NULLIF(btrim(COALESCE(p_message,'')),'');
  IF v_msg IS NOT NULL THEN
    SELECT item_name INTO v_deal_name FROM deals WHERE id=v_b.deal_id;
    INSERT INTO notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, is_read, meta_data, created_at)
    VALUES (
      'ntf_'||(extract(epoch from now())*1000)::bigint::text||substr(md5(random()::text),1,6),
      v_b.user_id,
      '💬 رسالة من المتجر', '💬 Message from the store',
      v_msg, v_msg, 'booking', false,
      jsonb_build_object('audience','buyer','event','completed_note','barcode',v_b.barcode,
                         'dealId',v_b.deal_id,'bot_message_ar',v_msg,'bot_message_en',v_msg),
      now()
    );
  END IF;
  RETURN jsonb_build_object('success',true,'user_name',COALESCE(v_b.user_name,'—'),'quantity',v_b.booked_quantity);
END; $function$
;


-- ═══ FUNCTION bot_consume_link_token(p_token text, p_telegram_id bigint, p_chat_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_consume_link_token(p_token text, p_telegram_id bigint DEFAULT NULL::bigint, p_chat_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_user users%ROWTYPE;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_token'); END IF;
  SELECT user_id INTO v_uid FROM telegram_link_tokens WHERE token = p_token AND expires_at > now() LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_token'); END IF;
  IF p_whatsapp_id IS NOT NULL THEN
    UPDATE users SET whatsapp_chat_id = NULL, notify_via_whatsapp = false WHERE whatsapp_chat_id = p_whatsapp_id AND id <> v_uid;
    UPDATE users SET whatsapp_chat_id = p_whatsapp_id, notify_via_whatsapp = true WHERE id = v_uid RETURNING * INTO v_user;
  ELSE
    UPDATE users SET telegram_id = NULL, telegram_chat_id = NULL WHERE (telegram_id = p_telegram_id OR telegram_chat_id = p_chat_id) AND id <> v_uid;
    UPDATE users SET telegram_id = p_telegram_id, telegram_chat_id = p_chat_id, notify_via_telegram = true WHERE id = v_uid RETURNING * INTO v_user;
  END IF;
  DELETE FROM telegram_link_tokens WHERE token = p_token;
  IF v_user.id IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'user_gone'); END IF;
  RETURN jsonb_build_object('success', true) || _bot_profile(v_user);
END; $function$
;


-- ═══ FUNCTION bot_create_link_token() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.bot_create_link_token()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid   text := auth.uid()::text;
  v_token text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  DELETE FROM telegram_link_tokens WHERE user_id = v_uid OR expires_at < now();
  v_token := encode(gen_random_bytes(9), 'hex'); -- 18 hex chars, URL-safe
  INSERT INTO telegram_link_tokens (token, user_id, expires_at)
  VALUES (v_token, v_uid, now() + interval '15 minutes');
  RETURN v_token;
END;
$function$
;


-- ═══ FUNCTION bot_delete_deal(p_telegram_id bigint, p_deal_id text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_delete_deal(p_telegram_id bigint, p_deal_id text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_pending int;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  IF NOT EXISTS (SELECT 1 FROM deals WHERE id = p_deal_id AND store_id = v_sid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  SELECT COUNT(*) INTO v_pending FROM bookings WHERE deal_id = p_deal_id AND status IN ('pending','acknowledged');
  IF v_pending > 0 THEN RETURN jsonb_build_object('success', false, 'error', 'has_bookings', 'count', v_pending); END IF;
  DELETE FROM deals WHERE id = p_deal_id AND store_id = v_sid;
  RETURN jsonb_build_object('success', true);
END; $function$
;


-- ═══ FUNCTION bot_delivery_quote(p_telegram_id bigint, p_whatsapp_id text, p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_delivery_quote(p_telegram_id bigint, p_whatsapp_id text, p_store_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  RETURN public.bot_delivery_quote_at(p_telegram_id, p_whatsapp_id, p_store_id, NULL, NULL);
END $function$
;


-- ═══ FUNCTION bot_delivery_quote_at(p_telegram_id bigint, p_whatsapp_id text, p_store_id text, p_location_id text, p_address_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_delivery_quote_at(p_telegram_id bigint, p_whatsapp_id text, p_store_id text, p_location_id text DEFAULT NULL::text, p_address_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text; v_lat float8; v_lng float8; v_label text; v_details text; v_q jsonb;
BEGIN
  -- 🔒 الحارس. غيابُه كان يجعل هذه الدالة بوّابةً مفتوحة لعناوين الناس.
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;

  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_linked'); END IF;

  IF p_address_id IS NOT NULL THEN
    -- `user_id = v_uid` شرطٌ لا تجميل: بدونه يقرأ أيّ باحثٍ عنوان غيره بمعرّفه.
    SELECT a.lat, a.lng, a.label, a.details INTO v_lat, v_lng, v_label, v_details
    FROM public.user_addresses a WHERE a.id = p_address_id AND a.user_id = v_uid;
    IF v_lat IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'address_not_found'); END IF;
  ELSE
    -- الافتراضي: أوّل عنوان مُعلَّم افتراضياً، وإلا الحقل القديم على المستخدم.
    SELECT a.lat, a.lng, a.label, a.details INTO v_lat, v_lng, v_label, v_details
    FROM public.user_addresses a WHERE a.user_id = v_uid
    ORDER BY a.is_default DESC, a.created_at ASC LIMIT 1;
    IF v_lat IS NULL THEN
      SELECT nullif(u.delivery_address->>'lat','')::float8, nullif(u.delivery_address->>'lng','')::float8,
             u.delivery_address->>'label', u.delivery_address->>'details'
        INTO v_lat, v_lng, v_label, v_details
      FROM public.users u WHERE u.id = v_uid;
    END IF;
  END IF;

  v_q := public.delivery_quote(p_store_id, v_lat, v_lng, p_location_id);
  RETURN v_q || jsonb_build_object(
    'ok', true,
    'has_address', (v_lat IS NOT NULL),
    'label', v_label, 'details', v_details,
    'address_id', p_address_id, 'location_id', p_location_id);
END $function$
;


-- ═══ FUNCTION bot_delivery_track_get(p_telegram_id bigint, p_whatsapp_id text, p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_delivery_track_get(p_telegram_id bigint, p_whatsapp_id text, p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid text; v_b public.bookings%ROWTYPE; v_t public.delivery_tracks%ROWTYPE; v_fresh boolean; v_seller boolean;
BEGIN
  IF NOT public._bot_gate_ok() THEN RAISE EXCEPTION 'GATE'; END IF;
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_linked'); END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  v_seller := v_b.store_id IS NOT DISTINCT FROM v_uid;
  IF NOT (v_seller OR v_b.user_id IS NOT DISTINCT FROM v_uid) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_delivery');
  END IF;

  SELECT * INTO v_t FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', true, 'status', 'preparing', 'live', false,
    'dispatched', false, 'role', CASE WHEN v_seller THEN 'seller' ELSE 'buyer' END); END IF;

  v_fresh := v_t.lat IS NOT NULL AND v_t.updated_at > now() - interval '2 minutes'
             AND v_t.status IN ('on_the_way','arrived');
  RETURN jsonb_build_object(
    'ok', true,
    'role', CASE WHEN v_seller THEN 'seller' ELSE 'buyer' END,
    'status', v_t.status,
    'live', v_fresh,
    -- 🔴 v15.49 — نفسُ الحقيقة التي يقرؤها الموقع.
    'dispatched', (v_t.dispatched_at IS NOT NULL OR v_t.started_at IS NOT NULL
                   OR v_t.status IN ('on_the_way','arrived','delivered')),
    'remaining_km', CASE WHEN v_fresh THEN v_t.remaining_km ELSE NULL END,
    'eta_min', CASE WHEN v_fresh THEN v_t.eta_min ELSE NULL END,
    'age_sec', GREATEST(0, EXTRACT(EPOCH FROM (now() - v_t.updated_at)))::int,
    'lat', CASE WHEN v_fresh THEN v_t.lat ELSE NULL END,
    'lng', CASE WHEN v_fresh THEN v_t.lng ELSE NULL END,
    'label', v_b.delivery_address->>'label');
END
$function$
;


-- ═══ FUNCTION bot_delivery_track_ping(p_telegram_id bigint, p_whatsapp_id text, p_barcode text, p_lat double precision, p_lng double precision, p_heading double precision, p_speed_kmh double precision) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_delivery_track_ping(p_telegram_id bigint, p_whatsapp_id text, p_barcode text, p_lat double precision, p_lng double precision, p_heading double precision DEFAULT NULL::double precision, p_speed_kmh double precision DEFAULT NULL::double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid text; v_b public.bookings%ROWTYPE; v_prev public.delivery_tracks%ROWTYPE;
  v_dlat double precision; v_dlng double precision; v_km numeric; v_eta integer; v_speed double precision;
BEGIN
  IF NOT public._bot_gate_ok() THEN RAISE EXCEPTION 'GATE'; END IF;
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_linked'); END IF;
  IF p_lat IS NULL OR p_lng IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'bad_point'); END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND OR v_b.store_id IS DISTINCT FROM v_uid THEN
    RETURN jsonb_build_object('ok', false, 'error', 'forbidden');
  END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN RETURN jsonb_build_object('ok', false, 'error', 'not_delivery'); END IF;
  IF v_b.status IN ('completed','cancelled') THEN RETURN jsonb_build_object('ok', false, 'error', 'closed'); END IF;
  IF v_b.status = 'pending' THEN RETURN jsonb_build_object('ok', false, 'error', 'not_acknowledged'); END IF;

  SELECT * INTO v_prev FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  IF v_prev.barcode IS NULL THEN
    INSERT INTO public.delivery_tracks (barcode, store_id, user_id, status, started_at)
    VALUES (v_b.barcode, v_b.store_id, v_b.user_id, 'on_the_way', now());
    SELECT * INTO v_prev FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  ELSIF v_prev.status NOT IN ('on_the_way','arrived') THEN
    UPDATE public.delivery_tracks
       SET status = 'on_the_way', started_at = coalesce(started_at, now()), ended_at = NULL, updated_at = now()
     WHERE barcode = v_b.barcode;
    SELECT * INTO v_prev FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  ELSIF v_prev.lat IS NOT NULL AND v_prev.updated_at > now() - interval '4 seconds' THEN
    RETURN jsonb_build_object('ok', true, 'throttled', true);
  END IF;

  v_dlat := nullif(v_b.delivery_address->>'lat','')::double precision;
  v_dlng := nullif(v_b.delivery_address->>'lng','')::double precision;
  IF v_dlat IS NOT NULL AND v_dlng IS NOT NULL THEN
    v_km := round(public._taki_km(p_lat, p_lng, v_dlat, v_dlng)::numeric, 2);
    v_speed := CASE WHEN p_speed_kmh IS NOT NULL AND p_speed_kmh BETWEEN 1 AND 120 THEN p_speed_kmh ELSE 25 END;
    v_eta := GREATEST(1, CEIL((v_km * 1.3 / v_speed) * 60))::int;
  END IF;

  UPDATE public.delivery_tracks SET
    lat = p_lat, lng = p_lng, heading = p_heading, speed_kmh = p_speed_kmh,
    remaining_km = v_km, eta_min = v_eta, updated_at = now()
  WHERE barcode = v_b.barcode;

  RETURN jsonb_build_object('ok', true, 'remaining_km', v_km, 'eta_min', v_eta, 'status', v_prev.status);
END
$function$
;


-- ═══ FUNCTION bot_delivery_track_status(p_telegram_id bigint, p_barcode text, p_status text, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_delivery_track_status(p_telegram_id bigint, p_barcode text, p_status text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text; v_b public.bookings%ROWTYPE; v_msg text;
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;
  IF p_status NOT IN ('on_the_way','arrived','delivered','cancelled') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'bad_status');
  END IF;
  SELECT id INTO v_uid FROM public.users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_linked'); END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'not_found'); END IF;
  -- التاجر وحده يحرّك حالة التوصيل: هو من يوصّل.
  IF v_b.store_id IS DISTINCT FROM v_uid THEN RETURN jsonb_build_object('ok', false, 'error', 'forbidden'); END IF;
  IF COALESCE(v_b.fulfillment,'pickup') <> 'delivery' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_delivery');
  END IF;
  IF p_status IN ('on_the_way','arrived') AND v_b.status = 'pending' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_acknowledged');
  END IF;

  INSERT INTO public.delivery_tracks (barcode, store_id, user_id, status, updated_at)
  VALUES (upper(btrim(p_barcode)), v_b.store_id, v_b.user_id, p_status, now())
  ON CONFLICT (barcode) DO UPDATE
    SET status = EXCLUDED.status, updated_at = now();

  -- المشتري يُشعَر بما يعنيه فعلاً. «ألغي البثّ» ليس خبراً سيئاً فلا نُقلقه به.
  v_msg := CASE p_status
    WHEN 'arrived'   THEN '📍 وصل المندوب إلى عنوانك — طلبك عند الباب.'
    WHEN 'delivered' THEN '✅ سُلّم طلبك. إن لم تستلمه فراسل التاجر فوراً.'
    ELSE NULL END;
  IF v_msg IS NOT NULL THEN
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (v_b.user_id,
            CASE p_status WHEN 'arrived' THEN '📍 وصل المندوب' ELSE '✅ سُلّم طلبك' END,
            CASE p_status WHEN 'arrived' THEN '📍 Courier arrived' ELSE '✅ Delivered' END,
            v_msg, v_msg, 'booking',
            jsonb_build_object('audience','buyer','barcode', v_b.barcode,
                               'actionUrl','/bookings?barcode='||v_b.barcode,
                               'action_url','/bookings?barcode='||v_b.barcode));
  END IF;

  RETURN jsonb_build_object('ok', true, 'status', p_status, 'barcode', v_b.barcode);
END $function$
;


-- ═══ FUNCTION bot_geo_cities(p_region text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_geo_cities(p_region text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'name',name,'lat',lat,'lng',lng) ORDER BY name),'[]'::jsonb)
  FROM cities WHERE p_region IS NULL OR region_id = p_region
$function$
;


