-- ═══ FUNCTION bot_get_admin_stats(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_admin_stats(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_u users%ROWTYPE; v_today bigint;
  v_users int; v_sellers int; v_buyers int; v_active int; v_total int; v_today_n int; v_reports int;
BEGIN
  SELECT * INTO v_u FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;

  -- v13.50: must actually be an admin right now. No NULL-able arithmetic.
  IF v_u.user_type IS DISTINCT FROM 'admin' THEN
    RETURN jsonb_build_object('success', false, 'error', 'unauthorized');
  END IF;

  v_today := (EXTRACT(EPOCH FROM date_trunc('day', NOW() AT TIME ZONE 'Asia/Riyadh')) * 1000)::bigint;
  SELECT COUNT(*) INTO v_users   FROM users WHERE deleted_at IS NULL;
  SELECT COUNT(*) INTO v_sellers FROM users WHERE user_type = 'seller' AND deleted_at IS NULL;
  SELECT COUNT(*) INTO v_buyers  FROM users WHERE user_type = 'buyer'  AND deleted_at IS NULL;
  SELECT COUNT(*) INTO v_active  FROM deals WHERE status = 'active';
  SELECT COUNT(*) INTO v_total   FROM bookings;
  SELECT COUNT(*) INTO v_today_n FROM bookings WHERE booked_at >= v_today;
  SELECT COUNT(*) INTO v_reports FROM reports WHERE status = 'pending';
  RETURN jsonb_build_object('success', true, 'total_users', v_users, 'merchants', v_sellers, 'buyers', v_buyers,
    'active_deals', v_active, 'total_bookings', v_total, 'today_bookings', v_today_n, 'pending_reports', v_reports);
END; $function$
;


-- ═══ FUNCTION bot_get_alerts(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_alerts(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user users%ROWTYPE;
BEGIN
  SELECT * INTO v_user FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  RETURN jsonb_build_object(
    'success', true,
    'notify_via_telegram', COALESCE(v_user.notify_via_telegram, false),
    'notify_via_whatsapp', COALESCE(v_user.notify_via_whatsapp, false),
    'keywords', COALESCE(to_jsonb(v_user.notif_keywords), '[]'::jsonb),
    'smart_count', CASE WHEN jsonb_typeof(v_user.smart_alerts) = 'array' THEN jsonb_array_length(v_user.smart_alerts) ELSE 0 END,
    'has_location', (v_user.lat IS NOT NULL AND v_user.lng IS NOT NULL)
  );
END; $function$
;


-- ═══ FUNCTION bot_get_booking_invoice(p_uid text, p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_booking_invoice(p_uid text, p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_b       public.bookings%ROWTYPE;
  v_d       public.deals%ROWTYPE;
  v_is_buyer  boolean;
  v_is_seller boolean;
  v_vat     jsonb;
  v_vat_no  text;
  v_cr      text;
  v_total   numeric;
  v_rate    numeric;
  v_base    numeric;
  v_tax     numeric;
  v_items   jsonb := '[]'::jsonb;
  v_sel     jsonb;
  v_row     jsonb;
  v_grp     jsonb;
  v_choice  jsonb;
  v_label   text;
  v_has_variant boolean := false;
  v_loc_name text;
  v_shop    text;
  v_buyer_note text;
  v_inv     public.order_invoices%ROWTYPE;
  v_rf      public.booking_refunds%ROWTYPE;
BEGIN
  IF NOT public._bot_gate_ok() THEN RAISE EXCEPTION 'GATE'; END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_found');
  END IF;

  v_is_buyer  := v_b.user_id IS NOT DISTINCT FROM p_uid;
  v_is_seller := v_b.store_id IS NOT DISTINCT FROM p_uid;
  IF NOT (v_is_buyer OR v_is_seller) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  SELECT * INTO v_d FROM public.deals WHERE id = v_b.deal_id;
  SELECT coalesce(nullif(v_d.shop_name,''), nullif(u.shop,''), u.name) INTO v_shop FROM public.users u WHERE u.id = v_b.store_id;

  -- ── الإجمالي ──────────────────────────────────────────────────────────────
  -- v14.11 — الرقم من العمود الذي كتبه الخادم لحظة الحجز: هو نفسه الذي يُطالَب
  -- به الدفع الإلكتروني، فلا تفترق الفاتورة عن المقبوض. القراءة من الملاحظات
  -- بقيت للحجوزات القديمة وحدها (ما قبل الهجرة)، ثم إعادة حساب كملاذ أخير.
  SELECT * INTO v_inv FROM public.order_invoices WHERE barcode = v_b.barcode;
  -- v14.21 — بيانات الاسترداد في نفس النداء: الإشعار الدائن يجب أن يظهر على
  -- ورقة الفاتورة، وإلا بقيت تقول «مدفوع» عن مالٍ عاد لصاحبه.
  SELECT * INTO v_rf FROM public.booking_refunds WHERE barcode = v_b.barcode;

  v_total := COALESCE(
    NULLIF(v_inv.total, 0),
    NULLIF(v_b.paid_amount, 0),
    v_b.total_amount,
    NULLIF(substring(coalesce(v_b.notes, '') FROM 'الإجمالي:\s*([0-9]+(?:\.[0-9]+)?)'), '')::numeric,
    (public.taki_booking_amount(v_b.deal_id, v_b.booked_quantity, v_b.selected_options, v_b.delivery_fee)->>'total')::numeric);

  -- ── الضريبة: من **لقطة الفاتورة** لا من الإعدادات الحيّة (v14.17) ─────────
  -- كانت تُحسب هنا من دالّة وضع ضريبة **اشتراكات تاكي** ومن رقم التاجر
  -- الضريبي **الحالي**. فكان: (أ) تاجرٌ مسجَّل لا تظهر ضريبته حتى تسجّل تاكي،
  -- (ب) وتعديلُ رقمه لاحقاً يُعيد كتابة كل فاتورة قديمة بأثر رجعي،
  -- (ج) وفرع «تُضاف فوق السعر» كان يُخرج «أساس + ضريبة ≠ إجمالي».
  -- اليوم: الأرقام مجمّدة في `order_invoices` لحظة البيع، ومضمّنة دائماً.
  v_vat_no := NULLIF(btrim(COALESCE(v_inv.seller->>'vat_number', '')), '');
  v_cr     := NULLIF(btrim(COALESCE(v_inv.seller->>'cr_number', '')), '');
  v_rate   := v_inv.vat_rate;
  v_base   := v_inv.vat_base;
  v_tax    := v_inv.vat_amount;

  -- ── العناصر: الأنواع (بدل الصنف الأساسي) والإضافات — كل عنصر برمز كاشيره ─
  v_sel := CASE WHEN jsonb_typeof(coalesce(v_b.selected_options, 'null'::jsonb)) = 'array'
                THEN v_b.selected_options ELSE '[]'::jsonb END;

  FOR v_row IN SELECT * FROM jsonb_array_elements(v_sel) LOOP
    IF v_row->>'g' = '__variant__' THEN
      SELECT vv INTO v_choice
        FROM jsonb_array_elements(coalesce(v_d.variants, '[]'::jsonb)) vv
       WHERE vv->>'id' = v_row->>'c' LIMIT 1;
      v_label := coalesce(v_choice->>'label', v_row->>'c');
      v_has_variant := true;
      v_items := v_items || jsonb_build_object(
        'label', v_label,
        'qty',   coalesce((v_row->>'qty')::int, 1),
        'sku',   nullif(btrim(coalesce(v_choice->>'posSku','')),''),
        'kind',  'variant');
    ELSE
      SELECT gg INTO v_grp
        FROM jsonb_array_elements(coalesce(v_d.options, '[]'::jsonb)) gg
       WHERE gg->>'id' = v_row->>'g' LIMIT 1;
      SELECT cc INTO v_choice
        FROM jsonb_array_elements(coalesce(v_grp->'choices', '[]'::jsonb)) cc
       WHERE cc->>'id' = v_row->>'c' LIMIT 1;
      IF v_choice IS NULL THEN CONTINUE; END IF;
      v_label := CASE WHEN v_grp->>'title' IS NOT NULL
                      THEN (v_grp->>'title') || ': ' || coalesce(v_choice->>'label', '')
                      ELSE coalesce(v_choice->>'label', '') END;
      v_items := v_items || jsonb_build_object(
        'label', v_label,
        'qty',   coalesce((v_row->>'qty')::int, 1),
        'sku',   nullif(btrim(coalesce(v_choice->>'posSku','')),''),
        'kind',  'addon');
    END IF;
  END LOOP;

  -- الصنف الأساسي يُطبع كعنصر (برمز كاشيره) فقط حين لا أنواع — كالموقع تماماً
  IF NOT v_has_variant THEN
    v_items := jsonb_build_array(jsonb_build_object(
      'label', v_d.item_name, 'qty', coalesce(v_b.booked_quantity, 1),
      'sku', nullif(btrim(coalesce(v_d.pos_sku,'')),''), 'kind', 'main')) || v_items;
  END IF;

  -- اسم الفرع المختار (عرض متعدد المواقع)
  IF v_b.location_id IS NOT NULL AND jsonb_typeof(coalesce(v_d.locations,'null'::jsonb)) = 'array' THEN
    SELECT nullif(e->>'name','') INTO v_loc_name FROM jsonb_array_elements(v_d.locations) e
     WHERE e->>'id' = v_b.location_id LIMIT 1;
  END IF;

  -- ملاحظة المشتري الحرّة (بعد 📝 وقبل سطر 💰) — نفس منطق الموقع
  v_buyer_note := nullif(btrim(coalesce(substring(coalesce(v_b.notes,'') FROM '📝\s*([^\n]*(?:\n(?!💰)[^\n]*)*)'), '')), '');

  RETURN jsonb_build_object(
    'ok',            true,
    'role',          CASE WHEN v_is_seller THEN 'seller' ELSE 'buyer' END,
    'barcode',       v_b.barcode,
    'backup_code',   v_b.backup_code,
    'status',        v_b.status,
    'cancelled_by',  v_b.cancelled_by,
    'item_name',     v_d.item_name,
    'main_sku',      nullif(btrim(coalesce(v_d.pos_sku,'')),''),
    'shop_name',     v_shop,
    'store_id',      v_b.store_id,
    'quantity',      v_b.booked_quantity,
    'unit_price',    v_d.discounted_price,
    'original_price',v_d.original_price,
    'total',         v_total,
    'total_source',  CASE WHEN v_inv.total IS NOT NULL AND v_inv.total > 0 THEN 'invoice'
                          WHEN v_b.paid_amount > 0          THEN 'paid'
                          WHEN v_b.total_amount IS NOT NULL THEN 'order'
                          WHEN v_b.notes ~ 'الإجمالي:'    THEN 'order'
                          ELSE 'estimate' END,
    'refund_status',   v_rf.status,
    'credit_note_no',  v_rf.credit_note_no,
    'refund_amount',   v_rf.refund_amount,
    'refund_ref',      v_rf.refund_ref,
    'refunded_at',     v_rf.refunded_at,
    'invoice_no',    v_inv.invoice_no,
    'issued_at',     v_inv.issued_at,
    'seller_name',   COALESCE(v_inv.seller->>'name', v_shop),
    'seller_address',v_inv.seller->>'address',
    'vat_number',    v_vat_no,
    'cr_number',     v_cr,
    'vat_rate',      v_rate,
    'vat_base',      v_base,
    'vat_amount',    v_tax,
    -- v14.68 — رمز زاتكا يُرمَّز في القاعدة: كانت نسخة في الموقع ونسخة في البوت
    -- تختلفان لاسمٍ بائعٍ أطول من ٢٥٥ بايتاً، أي رمزان لمستندٍ ضريبيّ واحد.
    -- 🪤 الشرط `v_inv.total > 0` ليس زينة: `v_total` أعلاه يرتدّ إلى مصادر أخرى
    --    حين تكون اللقطة صفراً، فيصير المطبوع غير المرمَّز على نفس الورقة.
    'zatca_tlv',     CASE
                       WHEN v_tax IS NULL OR v_vat_no IS NULL
                         OR COALESCE(v_inv.total, 0) <= 0 THEN NULL
                       ELSE public.taki_zatca_tlv(
                              COALESCE(v_inv.seller->>'name', v_shop, ''),
                              v_vat_no,
                              to_char(COALESCE(v_inv.issued_at, v_inv.created_at, now())
                                        AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
                              to_char(v_inv.total,  'FM9999999990.00'),
                              to_char(v_tax,        'FM9999999990.00'))
                     END,
    'paid',          v_b.paid_at IS NOT NULL,
    'paid_amount',   v_b.paid_amount,
    'payment_method',v_b.payment_method,
    'items',         v_items,
    'buyer_name',    CASE WHEN v_is_seller THEN v_b.user_name ELSE NULL END,
    'buyer_phone',   CASE WHEN v_is_seller THEN v_b.user_phone ELSE NULL END,
    'prep_time',     v_b.prep_time,
    'notes',         v_b.notes,
    'buyer_note',    v_buyer_note,
    'merchant_note', v_b.merchant_note,
    'location_name', v_loc_name,
    'fulfillment',   coalesce(v_b.fulfillment, 'pickup'),
    'delivery_fee',  v_b.delivery_fee,
    'delivery',      v_b.delivery_address,
    'booked_at',     v_b.booked_at,
    'completed_at',  v_b.completed_at
  );
END;
$function$
;


-- ═══ FUNCTION bot_get_booking_refund(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_booking_refund(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_r public.booking_refunds%ROWTYPE;
BEGIN
  SELECT id INTO v_uid FROM public.users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_r FROM public.booking_refunds WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_uid <> v_r.buyer_id AND v_uid <> v_r.store_id THEN RETURN NULL; END IF;
  RETURN jsonb_build_object('status', v_r.status, 'amount', v_r.amount,
    'merchant_note', v_r.merchant_note, 'refund_amount', v_r.refund_amount,
    'refund_ref', v_r.refund_ref, 'credit_note_no', v_r.credit_note_no,
    'refunded_at', v_r.refunded_at, 'requested_at', v_r.requested_at);
END
$function$
;


-- ═══ FUNCTION bot_get_categories(p_lat double precision, p_lng double precision, p_radius_km double precision) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_categories(p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision, p_radius_km double precision DEFAULT NULL::double precision)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  WITH live AS (
    SELECT d.category,
      CASE WHEN p_lat IS NOT NULL AND p_lng IS NOT NULL AND d.map_lat IS NOT NULL AND d.map_lng IS NOT NULL
           THEN 6371*acos(least(1,greatest(-1,
                  sin(radians(p_lat))*sin(radians(d.map_lat))+
                  cos(radians(p_lat))*cos(radians(d.map_lat))*cos(radians(d.map_lng-p_lng)))))
           ELSE NULL END AS dist_km
    FROM deals d
    WHERE d.status='active'
      AND (d.starts_at IS NULL OR d.starts_at <= (extract(epoch from now())*1000)::bigint)
  )
  SELECT coalesce(jsonb_agg(jsonb_build_object('category',category,'n',n) ORDER BY n DESC),'[]'::jsonb)
  FROM (
    SELECT category, count(*) n FROM live
    WHERE (p_lat IS NULL OR p_lng IS NULL OR p_radius_km IS NULL OR p_radius_km<=0
           OR (dist_km IS NOT NULL AND dist_km<=p_radius_km))
    GROUP BY category
  ) g;
$function$
;


-- ═══ FUNCTION bot_get_contest(p_telegram_id bigint, p_contest_id uuid, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_contest(p_telegram_id bigint, p_contest_id uuid, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE c record; v_uid text; v_role text; v_phone text; v_entered boolean := false;
BEGIN
  SELECT id, user_type, nullif(btrim(phone),'')
    INTO v_uid, v_role, v_phone
  FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  SELECT * INTO c FROM contests WHERE id=p_contest_id;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_phone IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM contest_entries e WHERE e.contest_id=c.id AND e.phone=v_phone)
      INTO v_entered;
  END IF;
  RETURN jsonb_build_object(
    'id', c.id, 'title', c.title, 'description', c.description, 'prize', c.prize,
    'banner_image', c.banner_image, 'pass_mode', c.pass_mode, 'audience', c.audience,
    'status', c.status, 'starts_at', c.starts_at, 'ends_at', c.ends_at,
    'questions', coalesce(c.questions,'[]'::jsonb),
    'social_tasks', coalesce(c.social_tasks,'[]'::jsonb),
    'live', (c.status='active'
             AND (c.starts_at IS NULL OR c.starts_at<=now())
             AND (c.ends_at IS NULL OR c.ends_at>now())),
    'linked', (v_uid IS NOT NULL), 'has_phone', (v_phone IS NOT NULL),
    'role', v_role, 'entered', v_entered
  );
END; $function$
;


-- ═══ FUNCTION bot_get_deal(p_deal_id text, p_telegram_id bigint) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_deal(p_deal_id text, p_telegram_id bigint DEFAULT NULL::bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_d deals%ROWTYPE; v_bk integer; v_uid text; v_following boolean := false; v_blocked boolean := false; v_avg numeric; v_cnt integer; v_wh jsonb; v_areal int; v_afake int;
BEGIN
  SELECT * INTO v_d FROM deals WHERE id = p_deal_id AND status = 'active' LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT count(*) INTO v_bk FROM bookings WHERE deal_id = v_d.id AND status <> 'cancelled';
  SELECT round(avg(r.score)::numeric,1), count(*) INTO v_avg, v_cnt
    FROM ratings r JOIN deals d2 ON d2.id = r.deal_id
    WHERE d2.store_id = v_d.store_id AND r.deleted_at IS NULL;
  SELECT count(*) FILTER (WHERE is_real), count(*) FILTER (WHERE NOT is_real)
    INTO v_areal, v_afake FROM deal_authenticity_votes WHERE deal_id = v_d.id;
  SELECT working_hours INTO v_wh FROM users WHERE id = v_d.store_id;
  IF p_telegram_id IS NOT NULL AND public._bot_gate_ok() THEN
    SELECT id INTO v_uid FROM users WHERE telegram_id = p_telegram_id AND deleted_at IS NULL LIMIT 1;
    IF v_uid IS NOT NULL THEN
      SELECT (v_d.store_id = ANY(COALESCE(followed_merchants,'{}'))),
             (v_d.store_id = ANY(COALESCE(blocked_merchants,'{}')))
        INTO v_following, v_blocked FROM users WHERE id = v_uid;
    END IF;
  END IF;
  RETURN jsonb_build_object(
    'id',v_d.id,'store_id',v_d.store_id,'item_name',v_d.item_name,'shop_name',v_d.shop_name,'category',v_d.category,
    'original_price',v_d.original_price,'discounted_price',v_d.discounted_price,
    'discount_percentage', coalesce(v_d.discount_percentage,
        round(((v_d.original_price-v_d.discounted_price)/nullif(v_d.original_price,0))*100)::int),
    'quantity',v_d.quantity,'is_unlimited',v_d.is_unlimited,'initial_quantity',v_d.initial_quantity,
    'prep_time',v_d.prep_time,'description',v_d.description,
    'expiry_type',v_d.expiry_type,'expiry_date',v_d.expiry_date,'expires_in_minutes',v_d.expires_in_minutes,
    'starts_at',v_d.starts_at,'created_at',v_d.created_at,'views',v_d.views,'clicks',v_d.clicks,
    'city',v_d.city,'region',v_d.region,'map_lat',v_d.map_lat,'map_lng',v_d.map_lng,
    'google_maps_link',v_d.google_maps_link,
    'images', to_jsonb(coalesce(v_d.images, ARRAY[]::text[])),
    'images_count', coalesce(array_length(v_d.images,1),0),
    'image',(v_d.images)[1],'bookings_count',v_bk,
    'rating_avg', COALESCE(v_avg,0), 'rating_count', COALESCE(v_cnt,0),
    'auth_real', COALESCE(v_areal,0), 'auth_fake', COALESCE(v_afake,0),
    'following', COALESCE(v_following,false), 'blocked', COALESCE(v_blocked,false),
    'working_hours', v_wh, 'open_status', public.store_is_open(v_wh),
    'max_per_booking', v_d.max_per_booking,
    'max_bookings_per_buyer', v_d.max_bookings_per_buyer,
    'rebook_cooldown_minutes', v_d.rebook_cooldown_minutes,
    -- v13.14: المواقع المتعددة للبوت (اسم + كمية الفرع إن كانت per_location)
    'loc_qty_mode', v_d.loc_qty_mode,
    'locations', CASE WHEN v_d.locations IS NOT NULL AND jsonb_typeof(v_d.locations) = 'array'
      THEN (SELECT jsonb_agg(jsonb_build_object(
              'id', e->>'id',
              'name', COALESCE(NULLIF(e->>'name',''), 'فرع'),
              'lat', NULLIF(e->>'lat','')::numeric, 'lng', NULLIF(e->>'lng','')::numeric,
              'quantity', CASE WHEN v_d.loc_qty_mode = 'per_location'
                               THEN NULLIF(e->>'quantity','')::int ELSE NULL END))
            FROM jsonb_array_elements(v_d.locations) e)
      ELSE NULL END
  );
END; $function$
;


-- ═══ FUNCTION bot_get_delivery(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_delivery(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text := public._bot_uid(p_telegram_id, p_whatsapp_id);
  v_type text;
  v_shop text;
  sp     public.store_profiles%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_linked'); END IF;
  SELECT user_type, shop INTO v_type, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_type IS NULL OR (v_type NOT IN ('seller','admin')
      AND nullif(btrim(coalesce(v_shop,'')),'') IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_seller');
  END IF;

  SELECT * INTO sp FROM public.store_profiles WHERE store_id = v_uid;

  RETURN jsonb_build_object(
    'ok',            true,
    'enabled',       coalesce(sp.delivery_enabled, false),
    'payment',       coalesce(sp.delivery_payment, 'cod'),
    'fee',           coalesce(sp.delivery_fee, 0),
    'min_order',     coalesce(sp.delivery_min_order, 0),
    'eta_min',       sp.delivery_eta_min,
    'note',          sp.delivery_note,
    -- عدد النطاقات: «مفعّل بلا نطاق» يبدو سليماً وليس كذلك — لا أحد يستطيع الطلب.
    'zones',         (SELECT count(*) FROM public.store_delivery_zones z
                       WHERE z.store_id = v_uid AND z.is_active),
    -- نطاقاتٌ لها رسمها الخاص: تعديل الرسم العام لا يمسّها، فلا يُقال للتاجر
    -- «رفعتُ رسومك» وهو لم يرفعها على نصف خريطته.
    'zones_priced',  (SELECT count(*) FROM public.store_delivery_zones z
                       WHERE z.store_id = v_uid AND z.is_active AND z.fee IS NOT NULL),
    'admin_blocked', coalesce(sp.delivery_blocked_by_admin, false),
    'block_reason',  sp.delivery_block_reason,
    'platform_on',   public.taki_delivery_globally_on(),
    -- وضع الدفع: «بطاقة» تحتاج بوابةً عاملة، وبدونها تُرفض بـGATEWAY_REQUIRED.
    'gateway_mode',  public.deal_payment_mode(v_uid)
  );
END $function$
;


-- ═══ FUNCTION bot_get_my_bookings(p_telegram_id bigint, p_scope text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_my_bookings(p_telegram_id bigint, p_scope text DEFAULT 'all'::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_res jsonb;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT jsonb_agg(row ORDER BY (row->>'sort_at')::bigint DESC) INTO v_res FROM (
    SELECT jsonb_build_object(
      'barcode', b.barcode, 'deal_id', b.deal_id, 'deal_name', d.item_name, 'shop_name', d.shop_name,
      'store_id', d.store_id,
      'quantity', b.booked_quantity, 'status', b.status, 'image', (d.images)[1],
      'prep_time', b.prep_time, 'notes', b.notes, 'sort_at', b.booked_at,
      'expiry_time', b.expiry_time,
      'deal_expiry_type', d.expiry_type, 'deal_expiry_date', d.expiry_date,
      'unread', (SELECT count(*) FROM booking_messages m WHERE m.barcode = b.barcode AND m.sender_role='seller' AND m.read_at IS NULL),
      'msg_count', (SELECT count(*) FROM booking_messages m WHERE m.barcode = b.barcode),
      'booked_at', to_timestamp(b.booked_at::double precision / 1000),
      -- v15.44 — مرساةُ «الختم بلا كود» بالمللي (كـ`expiry_time`/`sort_at`).
      -- 🪤 ولا تُقرأ `booked_at` أعلاه لذلك: هي **نصُّ وقتٍ** لا رقم، و`Number()`
      --    عليها تُنتج NaN بصمت — وهو ما جعل بوّابةَ v15.42 ميّتةً في البوتين.
      'ack_at_ms', CASE WHEN b.acknowledged_at IS NULL THEN NULL
                        ELSE (EXTRACT(EPOCH FROM b.acknowledged_at)*1000)::bigint END,
      'booked_at_ms', b.booked_at,
      'fulfillment', coalesce(b.fulfillment, 'pickup'),
      'delivery_fee', b.delivery_fee,
      'delivery_label', b.delivery_address->>'label',
      'delivery_details', b.delivery_address->>'details',
      'delivery_lat', b.delivery_address->>'lat',
      'delivery_lng', b.delivery_address->>'lng',
      -- v14.10 — البوتان يحتاجانهما ليخفيا عدّاداً كاذباً ويُظهرا زرّ التأكيد
      'paid', b.paid_at IS NOT NULL,
      'dlv_status', (SELECT t.status FROM delivery_tracks t WHERE t.barcode = b.barcode),
      -- 🔴 v15.49 — وحقيقةُ الانطلاق صريحةً: `dlv_status` حالةٌ لحظيّة يكتبها
      --    المنظّفُ `cancelled` بعد ساعةٍ من صمت الهاتف، فمطابقتُها بقائمةٍ
      --    كانت تُخفي زرَّ التأكيد عن مشترٍ استلم بضاعته.
      'dlv_dispatched', public.taki_delivery_dispatched(b.barcode),
      -- v14.21 — حالة الاسترداد على بطاقة الطلب في البوتين، فلا ينتظر المشتري
      -- جواباً لا يراه. (كان السطر مكتوباً في البوت بلا حقلٍ يغذّيه.)
      'refund_status', (SELECT r.status FROM booking_refunds r WHERE r.barcode = b.barcode),
      'credit_note_no', (SELECT r.credit_note_no FROM booking_refunds r WHERE r.barcode = b.barcode),
      'hold_running', (
        b.status IN ('pending','acknowledged')
        AND b.paid_at IS NULL
        AND NOT public.taki_delivery_hold_stopped(b.barcode)
      )
    ) AS row
    FROM bookings b JOIN deals d ON d.id = b.deal_id
    WHERE b.user_id = v_uid
      AND ( p_scope = 'all'
         OR (p_scope = 'current'  AND b.status IN ('pending','acknowledged'))
         OR (p_scope = 'previous' AND b.status IN ('completed','cancelled','expired')) )
    ORDER BY b.booked_at DESC LIMIT 20
  ) t;
  RETURN COALESCE(v_res, '[]'::jsonb);
END; $function$
;


-- ═══ FUNCTION bot_get_pay_info(p_uid text, p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_pay_info(p_uid text, p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_b public.bookings%ROWTYPE; v_mode text;
BEGIN
  IF NOT public._bot_gate_ok() THEN RAISE EXCEPTION 'GATE'; END IF;
  SELECT * INTO v_b FROM public.bookings WHERE barcode = p_barcode;
  IF NOT FOUND OR v_b.user_id IS DISTINCT FROM p_uid THEN
    RETURN jsonb_build_object('payable', false);
  END IF;
  v_mode := public.deal_payment_mode(v_b.store_id);
  RETURN jsonb_build_object(
    'payable', (v_mode IN ('online','both'))
               AND v_b.paid_at IS NULL
               AND v_b.status IN ('pending','acknowledged'),
    'paid',    v_b.paid_at IS NOT NULL,
    'mode',    v_mode);
END $function$
;


-- ═══ FUNCTION bot_get_seller_bookings(p_telegram_id bigint, p_scope text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_seller_bookings(p_telegram_id bigint, p_scope text DEFAULT 'current'::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_res jsonb;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN NULL; END IF;
  SELECT jsonb_agg(row ORDER BY (row->>'sort_at')::bigint DESC) INTO v_res FROM (
    SELECT jsonb_build_object(
      'barcode', b.barcode, 'user_name', COALESCE(b.user_name,'—'), 'user_phone', COALESCE(b.user_phone,'—'),
      'deal_name', d.item_name, 'quantity', b.booked_quantity, 'status', b.status,
      'notes', COALESCE(b.notes,''), 'prep_time', b.prep_time, 'sort_at', b.booked_at,
      'expiry_time', b.expiry_time,
      'unread', (SELECT count(*) FROM booking_messages m WHERE m.barcode = b.barcode AND m.sender_role='buyer' AND m.read_at IS NULL),
      'booked_at', to_timestamp(b.booked_at::double precision / 1000),
      'fulfillment', coalesce(b.fulfillment, 'pickup'),
      'delivery_fee', b.delivery_fee,
      'delivery_label', b.delivery_address->>'label',
      'delivery_details', b.delivery_address->>'details',
      'delivery_phone', b.delivery_address->>'phone',
      'delivery_lat', b.delivery_address->>'lat',
      'delivery_lng', b.delivery_address->>'lng',
      -- v14.42 — حالة التوصيل من القاعدة: بلا هذا يقرأ البوت الحالةَ من ذاكرة
      -- المحادثة التي تُمسح مع كل إعادة تشغيل، فيعرض «ابدأ البثّ» وهو جارٍ.
      'dlv_status', (SELECT dt.status FROM delivery_tracks dt WHERE dt.barcode = b.barcode),
      'payment_method', b.payment_method,
      'paid', b.paid_at IS NOT NULL
    ) AS row
    FROM bookings b JOIN deals d ON d.id = b.deal_id
    WHERE b.store_id = v_sid
      AND ( p_scope = 'all'
         OR (p_scope = 'current'  AND b.status IN ('pending','acknowledged'))
         OR (p_scope = 'previous' AND b.status IN ('completed','cancelled','expired')) )
    ORDER BY b.booked_at DESC LIMIT 30
  ) t;
  RETURN COALESCE(v_res, '[]'::jsonb);
END; $function$
;


-- ═══ FUNCTION bot_get_seller_deal(p_telegram_id bigint, p_deal_id text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_seller_deal(p_telegram_id bigint, p_deal_id text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_d deals%ROWTYPE;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_d FROM deals WHERE id = p_deal_id AND store_id = v_sid LIMIT 1;
  IF NOT FOUND THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'id', v_d.id, 'item_name', v_d.item_name, 'original_price', v_d.original_price,
    'discounted_price', v_d.discounted_price, 'discount_percentage', v_d.discount_percentage,
    'quantity', v_d.quantity, 'on_hand', v_d.on_hand, 'variants', v_d.variants, 'locations', v_d.locations, 'loc_qty_mode', v_d.loc_qty_mode, 'is_unlimited', v_d.is_unlimited, 'initial_quantity', v_d.initial_quantity,
    'status', v_d.status, 'category', v_d.category, 'description', v_d.description,
    'size', v_d.size, 'gender', v_d.gender, 'images', COALESCE(v_d.images,'{}'),
    'expiry_type', v_d.expiry_type, 'expiry_date', v_d.expiry_date,
    'expires_in_minutes', v_d.expires_in_minutes, 'starts_at', v_d.starts_at,
    'created_at', v_d.created_at,
    'location_id', v_d.location_id, 'custom_location_name', v_d.custom_location_name,
    'map_lat', v_d.map_lat, 'map_lng', v_d.map_lng, 'region', v_d.region, 'city', v_d.city,
    'google_maps_link', v_d.google_maps_link,
    'max_per_booking', v_d.max_per_booking,
    'max_bookings_per_buyer', v_d.max_bookings_per_buyer,
    'rebook_cooldown_minutes', v_d.rebook_cooldown_minutes
  );
END; $function$
;


-- ═══ FUNCTION bot_get_seller_deals(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_seller_deals(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_res jsonb;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN NULL; END IF;
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'item_name', item_name, 'original_price', original_price,
    'discounted_price', discounted_price, 'discount_percentage', discount_percentage,
    'quantity', quantity, 'on_hand', on_hand, 'is_unlimited', is_unlimited, 'status', status,
    'category', category, 'description', description,
    'expiry_type', expiry_type, 'expiry_date', expiry_date,
    'expires_in_minutes', expires_in_minutes, 'starts_at', starts_at, 'created_at', created_at,
    'images_count', COALESCE(array_length(images,1),0),
    'bookings_count', (SELECT count(*) FROM bookings bk WHERE bk.deal_id = deals.id AND bk.status <> 'cancelled')
  ) ORDER BY created_at DESC) INTO v_res FROM deals WHERE store_id = v_sid LIMIT 30;
  RETURN COALESCE(v_res, '[]'::jsonb);
END; $function$
;


-- ═══ FUNCTION bot_get_seller_stats(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_seller_stats(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_shop text; v_today bigint;
  v_total int; v_today_n int; v_pending int; v_active int; v_rev numeric; v_sp store_profiles%ROWTYPE;
BEGIN
  SELECT id, shop INTO v_sid, v_shop FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN NULL; END IF;
  v_today := (EXTRACT(EPOCH FROM date_trunc('day', NOW() AT TIME ZONE 'Asia/Riyadh')) * 1000)::bigint;
  SELECT COUNT(*) INTO v_total   FROM bookings WHERE store_id = v_sid;
  SELECT COUNT(*) INTO v_today_n FROM bookings WHERE store_id = v_sid AND booked_at >= v_today;
  SELECT COUNT(*) INTO v_pending FROM bookings WHERE store_id = v_sid AND status IN ('pending','acknowledged');
  SELECT COUNT(*) INTO v_active  FROM deals WHERE store_id = v_sid AND status = 'active';
  SELECT COALESCE(SUM(d.discounted_price * b.booked_quantity),0) INTO v_rev
    FROM bookings b JOIN deals d ON d.id = b.deal_id WHERE b.store_id = v_sid AND b.status = 'completed';
  SELECT * INTO v_sp FROM store_profiles WHERE store_id = v_sid LIMIT 1;
  RETURN jsonb_build_object('shop', v_shop, 'total_bookings', v_total, 'today_bookings', v_today_n,
    'pending_bookings', v_pending, 'active_deals', v_active, 'total_revenue', v_rev,
    'subscription_plan', v_sp.subscription_plan, 'subscription_expires_at', v_sp.subscription_expires_at);
END; $function$
;


-- ═══ FUNCTION bot_get_smart_alerts(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_smart_alerts(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_arr jsonb; v_tg boolean; v_wa boolean;
BEGIN
  SELECT id, smart_alerts, COALESCE(notify_via_telegram,false), COALESCE(notify_via_whatsapp,false)
    INTO v_uid, v_arr, v_tg, v_wa
    FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF v_arr IS NULL OR jsonb_typeof(v_arr) <> 'array' THEN v_arr := '[]'::jsonb; END IF;
  RETURN jsonb_build_object('success',true,'alerts',v_arr,'notify_via_telegram',v_tg,'notify_via_whatsapp',v_wa);
END; $function$
;


-- ═══ FUNCTION bot_get_store(p_telegram_id bigint, p_store_id text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_store(p_telegram_id bigint, p_store_id text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now bigint := (extract(epoch from now())*1000)::bigint;
  v_name text; v_avatar text; v_bio text; v_city text; v_region text;
  v_avg numeric; v_cnt int; v_deals int; v_uid text;
  v_following boolean := false; v_blocked boolean := false; v_arr jsonb;
  v_wh jsonb; v_areal int; v_afake int;
BEGIN
  SELECT coalesce(nullif(btrim(u.shop),''), nullif(btrim(u.name),''), 'متجر'),
         coalesce(nullif(btrim(coalesce(u.avatar_url,'')),''), sp.avatar_url),
         coalesce(nullif(btrim(coalesce(u.bio,'')),''), sp.bio), u.working_hours
    INTO v_name, v_avatar, v_bio, v_wh
  FROM users u LEFT JOIN store_profiles sp ON sp.store_id=u.id
  WHERE u.id=p_store_id LIMIT 1;

  IF v_name IS NULL THEN
    SELECT max(shop_name) INTO v_name FROM deals WHERE store_id=p_store_id;
    IF v_name IS NULL THEN RETURN NULL; END IF;
  END IF;

  SELECT max(city), max(region) INTO v_city, v_region
    FROM deals WHERE store_id=p_store_id AND status='active';
  SELECT count(*) INTO v_deals
    FROM deals WHERE store_id=p_store_id AND status='active'
      AND (starts_at IS NULL OR starts_at<=v_now);
  SELECT round(avg(r.score)::numeric,1), count(*) INTO v_avg, v_cnt
    FROM ratings r JOIN deals d2 ON d2.id=r.deal_id
    WHERE d2.store_id=p_store_id AND r.deleted_at IS NULL;
  SELECT count(*) FILTER (WHERE is_real), count(*) FILTER (WHERE NOT is_real)
    INTO v_areal, v_afake FROM deal_authenticity_votes WHERE store_id=p_store_id;

  IF p_telegram_id IS NOT NULL OR p_whatsapp_id IS NOT NULL THEN
    v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
    IF v_uid IS NOT NULL THEN
      SELECT (p_store_id = ANY(coalesce(followed_merchants,'{}'))),
             (p_store_id = ANY(coalesce(blocked_merchants,'{}')))
        INTO v_following, v_blocked FROM users WHERE id=v_uid;
    END IF;
  END IF;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', x.id, 'item_name', x.item_name,
    'original_price', x.original_price, 'discounted_price', x.discounted_price,
    'discount_percentage', coalesce(x.discount_percentage,
        round(((x.original_price-x.discounted_price)/nullif(x.original_price,0))*100)::int)
  ) ORDER BY x.created_at DESC), '[]'::jsonb) INTO v_arr
  FROM (SELECT * FROM deals WHERE store_id=p_store_id AND status='active'
          AND (starts_at IS NULL OR starts_at<=v_now)
        ORDER BY created_at DESC LIMIT 8) x;

  RETURN jsonb_build_object(
    'store_id', p_store_id, 'name', v_name, 'avatar', v_avatar, 'bio', v_bio,
    'city', v_city, 'region', v_region,
    'rating_avg', coalesce(v_avg,0), 'rating_count', coalesce(v_cnt,0),
    'auth_real', coalesce(v_areal,0), 'auth_fake', coalesce(v_afake,0),
    'active_deals', coalesce(v_deals,0),
    'working_hours', v_wh, 'open_status', public.store_is_open(v_wh),
    'following', coalesce(v_following,false), 'blocked', coalesce(v_blocked,false),
    'deals', v_arr
  );
END; $function$
;


-- ═══ FUNCTION bot_get_store_hours(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_store_hours(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_wh jsonb;
BEGIN
  SELECT working_hours INTO v_wh FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  RETURN jsonb_build_object('success', true, 'working_hours', v_wh);
END; $function$
;


-- ═══ FUNCTION bot_get_store_reviews(p_store_id text, p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_store_reviews(p_store_id text, p_limit integer DEFAULT 8)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb; v_avg numeric; v_cnt int;
BEGIN
  SELECT round(avg(r.score)::numeric,1), count(*) INTO v_avg, v_cnt
    FROM ratings r JOIN deals d ON d.id=r.deal_id WHERE d.store_id=p_store_id AND r.deleted_at IS NULL;
  SELECT jsonb_agg(x ORDER BY (x->>'at') DESC) INTO v FROM (
    SELECT jsonb_build_object('score',r.score,'comment',r.comment,'user',COALESCE(r.user_name,'مشتري'),
                              'at',r.created_at,'reply',r.reply) AS x
    FROM ratings r JOIN deals d ON d.id=r.deal_id
    WHERE d.store_id=p_store_id AND r.deleted_at IS NULL
    ORDER BY r.created_at DESC LIMIT GREATEST(1, LEAST(p_limit, 20))
  ) t;
  RETURN jsonb_build_object('success',true,'avg',COALESCE(v_avg,0),'count',COALESCE(v_cnt,0),'reviews',COALESCE(v,'[]'::jsonb));
END; $function$
;


-- ═══ FUNCTION bot_get_subscription(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_get_subscription(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_sp store_profiles%ROWTYPE;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT * INTO v_sp FROM store_profiles WHERE store_id=v_sid LIMIT 1;
  RETURN jsonb_build_object('success',true,
    'plan',         COALESCE(v_sp.subscription_plan,'free'),
    'expires_at',   v_sp.subscription_expires_at,
    'max_branches', COALESCE(v_sp.max_branches,1),
    'auto_renew',   COALESCE(v_sp.auto_renew,true),
    'amount',       v_sp.subscription_amount,
    'active',       ensure_active_subscription(v_sid));
END; $function$
;


