-- ═══ FUNCTION bot_list_branches(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_list_branches(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_max int; v_used int; v_items jsonb;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT COALESCE(max_branches,3) INTO v_max FROM store_profiles WHERE store_id=v_sid;
  IF v_max IS NULL THEN v_max:=3; END IF;

  SELECT COUNT(DISTINCT bot__loc_key(location_id,map_lat,map_lng)) INTO v_used
    FROM deals WHERE store_id=v_sid AND status='active';

  WITH active_keys AS (
    SELECT DISTINCT bot__loc_key(location_id,map_lat,map_lng) AS k
    FROM deals WHERE store_id=v_sid AND status='active'
  ),
  branch_rows AS (
    SELECT
      jsonb_build_object(
        'id', b.id, 'kind','branch', 'name', b.name_ar,
        'address', nullif(btrim(coalesce(b.address, '')), ''),
        'region', b.region_id, 'city', b.city_id, 'location_id', b.location_id,
        'map_lat', b.map_lat, 'map_lng', b.map_lng, 'google_maps_link', b.google_maps_link,
        'is_primary', COALESCE(b.is_primary,false), 'is_active', COALESCE(b.is_active,true),
        'locked', bot__loc_key(b.location_id,b.map_lat,b.map_lng) IN (SELECT k FROM active_keys)
      ) AS item,
      (COALESCE(b.is_primary,false))::int AS isp, b.created_at::text AS crt
    FROM store_branches b WHERE b.merchant_id=v_sid AND COALESCE(b.is_active,true)=true
  ),
  deal_locs AS (
    SELECT DISTINCT ON (bot__loc_key(d.location_id,d.map_lat,d.map_lng))
      bot__loc_key(d.location_id,d.map_lat,d.map_lng) AS k,
      d.location_id, d.custom_location_name, d.map_lat, d.map_lng, d.region, d.city, d.google_maps_link, d.created_at
    FROM deals d WHERE d.store_id=v_sid AND d.status='active'
    ORDER BY bot__loc_key(d.location_id,d.map_lat,d.map_lng), d.created_at
  ),
  extra_rows AS (
    SELECT
      jsonb_build_object(
        'id', null, 'kind','deal',
        'name', COALESCE(NULLIF(btrim(COALESCE(dl.custom_location_name,'')),''),
                         (SELECT l.name FROM locations l WHERE l.id=dl.location_id),
                         (SELECT c.name FROM cities c WHERE c.id=dl.city),
                         'موقع عرض نشط'),
        'region', dl.region, 'city', dl.city, 'location_id', dl.location_id,
        'map_lat', dl.map_lat, 'map_lng', dl.map_lng, 'google_maps_link', dl.google_maps_link,
        'is_primary', false, 'is_active', true, 'locked', true
      ) AS item,
      0 AS isp, ('z'||dl.created_at::text) AS crt
    FROM deal_locs dl
    WHERE dl.k NOT IN (
      SELECT bot__loc_key(b.location_id,b.map_lat,b.map_lng) FROM store_branches b WHERE b.merchant_id=v_sid AND COALESCE(b.is_active,true)=true
    )
  )
  SELECT jsonb_agg(item ORDER BY isp DESC, crt) INTO v_items
  FROM (SELECT item,isp,crt FROM branch_rows UNION ALL SELECT item,isp,crt FROM extra_rows) all_rows;

  RETURN jsonb_build_object('success',true,'max',v_max,'used',v_used,'branches',COALESCE(v_items,'[]'::jsonb));
END; $function$
;


-- ═══ FUNCTION bot_list_contests(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_list_contests(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_role text; v_phone text; v_res jsonb;
BEGIN
  SELECT id, user_type, nullif(btrim(phone),'')
    INTO v_uid, v_role, v_phone
  FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;

  SELECT coalesce(jsonb_agg(jsonb_build_object(
    'id', c.id, 'title', c.title, 'description', c.description, 'prize', c.prize,
    'banner_image', c.banner_image, 'pass_mode', c.pass_mode,
    'questions_count', coalesce(jsonb_array_length(c.questions),0),
    'social_count', coalesce(jsonb_array_length(c.social_tasks),0),
    'ends_at', c.ends_at,
    'entered', (v_phone IS NOT NULL AND EXISTS(
        SELECT 1 FROM contest_entries e WHERE e.contest_id=c.id AND e.phone=v_phone))
  ) ORDER BY c.created_at DESC), '[]'::jsonb) INTO v_res
  FROM contests c
  WHERE c.status='active'
    AND (c.starts_at IS NULL OR c.starts_at <= now())
    AND (c.ends_at IS NULL OR c.ends_at > now())
    AND ( c.audience='all' OR v_role='admin'
          OR (c.audience='sellers' AND v_role='seller')
          OR (c.audience='buyers'  AND coalesce(v_role,'') <> 'seller') );
  RETURN v_res;
END; $function$
;


-- ═══ FUNCTION bot_list_followed(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_list_followed(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_now bigint := (extract(epoch from now())*1000)::bigint; v_ids text[]; v_arr jsonb;
BEGIN
  SELECT id, COALESCE(followed_merchants,'{}') INTO v_uid, v_ids
    FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF v_ids IS NULL OR array_length(v_ids,1) IS NULL THEN
    RETURN jsonb_build_object('success',true,'merchants','[]'::jsonb);
  END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'store_id', u.id,
    'name', COALESCE(NULLIF(btrim(u.shop),''), NULLIF(btrim(u.name),''), 'متجر'),
    'avatar', COALESCE(nullif(btrim(coalesce(u.avatar_url,'')),''), sp.avatar_url),
    'bio', COALESCE(nullif(btrim(coalesce(u.bio,'')),''), sp.bio),
    'rating_avg', COALESCE((SELECT round(avg(r.score)::numeric,1) FROM ratings r JOIN deals d2 ON d2.id=r.deal_id
                            WHERE d2.store_id=u.id AND r.deleted_at IS NULL),0),
    'rating_count', COALESCE((SELECT count(*) FROM ratings r JOIN deals d2 ON d2.id=r.deal_id
                            WHERE d2.store_id=u.id AND r.deleted_at IS NULL),0),
    'active_deals', COALESCE((SELECT count(*) FROM deals d WHERE d.store_id=u.id AND d.status='active'
                            AND (d.starts_at IS NULL OR d.starts_at<=v_now)),0)
  )), '[]'::jsonb) INTO v_arr
  FROM users u LEFT JOIN store_profiles sp ON sp.store_id=u.id
  WHERE u.id = ANY(v_ids);
  RETURN jsonb_build_object('success',true,'merchants',v_arr);
END; $function$
;


-- ═══ FUNCTION bot_list_packages() DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_list_packages()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public.bot_payments_enabled() THEN RETURN '[]'::jsonb; END IF;
  SELECT value INTO v FROM platform_settings WHERE key='location_packages' LIMIT 1;
  RETURN COALESCE(v, '[]'::jsonb);
END; $function$
