-- ═══ FUNCTION bot_lookup_booking(p_telegram_id bigint, p_code text, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_lookup_booking(p_telegram_id bigint, p_code text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text;
  v_code text := upper(btrim(translate(COALESCE(p_code, ''), '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', '01234567890123456789')));
  v_b    public.bookings%ROWTYPE;
  v_role text;
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  SELECT id INTO v_uid FROM public.users
  WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF v_code = '' OR length(v_code) > 32 THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;

  SELECT * INTO v_b FROM public.bookings
  WHERE upper(barcode) = v_code OR upper(backup_code) = v_code
  LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;

  IF    v_uid = v_b.store_id THEN v_role := 'seller';
  ELSIF v_uid = v_b.user_id  THEN v_role := 'buyer';
  ELSE  RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;

  RETURN jsonb_build_object('success', true, 'role', v_role,
                            'booking', public._booking_card(v_b.barcode, v_role));
END $function$
;


-- ═══ FUNCTION bot_mark_email(p_id uuid, p_ok boolean, p_error text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_mark_email(p_id uuid, p_ok boolean, p_error text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN; END IF;
  IF p_ok THEN
    UPDATE email_outbox SET status = 'sent', sent_at = now(), last_error = NULL WHERE id = p_id;
  ELSE
    UPDATE email_outbox
       SET status = CASE WHEN attempts >= 5 THEN 'failed' ELSE 'pending' END,
           last_error = LEFT(COALESCE(p_error,'unknown'), 500)
     WHERE id = p_id;
  END IF;
END $function$
;


-- ═══ FUNCTION bot_mark_stock_event(p_id bigint, p_ok boolean, p_error text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_mark_stock_event(p_id bigint, p_ok boolean, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN jsonb_build_object('ok', false, 'error', 'forbidden'); END IF;
  UPDATE public.stock_events
     SET status = CASE WHEN COALESCE(p_ok,false) THEN 'sent'
                       WHEN attempts >= 8 THEN 'failed' ELSE 'pending' END,
         sent_at = CASE WHEN COALESCE(p_ok,false) THEN now() ELSE sent_at END,
         last_error = left(COALESCE(p_error, ''), 500),
         picked_at = CASE WHEN COALESCE(p_ok,false) THEN picked_at ELSE NULL END
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION bot_my_addresses(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_my_addresses(p_telegram_id bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text; v_rows jsonb;
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'not_authorized');
  END IF;
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'not_linked'); END IF;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'id', a.id, 'label', COALESCE(NULLIF(a.label,''),'عنوان'),
           'details', COALESCE(a.details,''), 'city', a.city,
           'is_default', a.is_default)
         ORDER BY a.is_default DESC, a.created_at ASC), '[]'::jsonb)
    INTO v_rows
  FROM public.user_addresses a WHERE a.user_id = v_uid;

  RETURN jsonb_build_object('ok', true, 'rows', v_rows);
END $function$
;


