-- ═══ FUNCTION bot_publish_gate(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_publish_gate(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text; v_block text; v_sell jsonb;
BEGIN
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  v_block := public.taki_publish_block(v_uid);
  IF v_block IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'ok', false, 'reason', v_block,
      'sla_hours', (public.taki_verification_policy()->>'sla_hours')::int); END IF;
  v_sell := public.store_can_sell(v_uid);
  IF NOT COALESCE((v_sell->>'ok')::boolean, false) THEN
    RETURN jsonb_build_object('success', true, 'ok', false, 'reason', v_sell->>'reason'); END IF;
  RETURN jsonb_build_object('success', true, 'ok', true);
END
$function$
;


-- ═══ FUNCTION bot_pull_email_outbox(p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_pull_email_outbox(p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN '[]'::jsonb; END IF;
  -- a crashed sender must not strand rows in 'sending'
  UPDATE email_outbox SET status = 'pending'
   WHERE status = 'sending' AND picked_at < now() - interval '10 minutes';
  -- a backlog older than 48h is stale news — never flood on late SMTP setup
  UPDATE email_outbox SET status = 'expired'
   WHERE status = 'pending' AND created_at < now() - interval '48 hours';
  WITH picked AS (
    SELECT id FROM email_outbox
    WHERE status = 'pending' AND attempts < 5
    ORDER BY created_at ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit,10), 25))
    FOR UPDATE SKIP LOCKED
  ),
  upd AS (
    UPDATE email_outbox e
       SET status = 'sending', picked_at = now(), attempts = e.attempts + 1
      FROM picked WHERE e.id = picked.id
    RETURNING e.id, e.to_email, e.subject, e.html, e.event, e.created_at
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', id, 'to_email', to_email, 'subject', subject, 'html', html, 'event', event
  ) ORDER BY created_at ASC) INTO v FROM upd;
  RETURN COALESCE(v, '[]'::jsonb);
END $function$
;


-- ═══ FUNCTION bot_pull_outbox(p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_pull_outbox(p_limit integer DEFAULT 25)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v jsonb;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN '[]'::jsonb; END IF;
  WITH picked AS (
    SELECT n.id FROM public.notifications n
    WHERE n.bot_pushed_at IS NULL AND n.created_at > now() - interval '2 days'
    ORDER BY n.created_at ASC
    LIMIT GREATEST(1, LEAST(COALESCE(p_limit,25), 50))
    FOR UPDATE SKIP LOCKED
  ),
  upd AS (
    UPDATE public.notifications n SET bot_pushed_at = now()
    FROM picked WHERE n.id = picked.id
    RETURNING n.id, n.user_id, n.type, n.title_ar, n.title_en, n.body_ar, n.body_en, n.meta_data, n.created_at
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id', upd.id, 'user_id', upd.user_id, 'type', upd.type,
    'title_ar', upd.title_ar, 'title_en', upd.title_en,
    'body_ar', upd.body_ar, 'body_en', upd.body_en, 'meta_data', upd.meta_data,
    'telegram_chat_id', u.telegram_chat_id, 'notify_via_telegram', COALESCE(u.notify_via_telegram, true),
    'whatsapp_chat_id', u.whatsapp_chat_id, 'notify_via_whatsapp', COALESCE(u.notify_via_whatsapp, false),
    'preferred_lang', u.preferred_lang
  ) ORDER BY upd.created_at ASC)
  INTO v FROM upd JOIN public.users u ON u.id = upd.user_id;
  RETURN COALESCE(v, '[]'::jsonb);
END; $function$
;


-- ═══ FUNCTION bot_pull_stock_events(p_limit integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_pull_stock_events(p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_rows jsonb;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN jsonb_build_object('ok', false, 'error', 'forbidden'); END IF;
  -- 🪤 `SKIP LOCKED` فلا يلتقط عاملان نفسَ الصفّ، و`picked_at` يُعيد العالق
  --    بعد عشر دقائق — عاملٌ مات وهو ممسكٌ بصفٍّ لا يجوز أن يُجمّده أبداً.
  WITH claimed AS (
    SELECT e.id FROM public.stock_events e
     WHERE e.status = 'pending'
       AND (e.picked_at IS NULL OR e.picked_at < now() - interval '10 minutes')
       AND e.attempts < 8
     ORDER BY e.id
     LIMIT GREATEST(1, LEAST(COALESCE(p_limit, 20), 100))
     FOR UPDATE SKIP LOCKED
  ), upd AS (
    UPDATE public.stock_events e SET picked_at = now(), attempts = e.attempts + 1
      FROM claimed c WHERE e.id = c.id RETURNING e.*
  ), joined AS (
    SELECT u.*, i.webhook_url, i.webhook_secret, i.id AS integration_id,
           -- 🪤 ويُقيَّد البحثُ بالاتصال نفسه: بلا ذلك يُؤخذ كودُ منتجٍ من
           --    اتصالٍ آخر لنفس المتجر. (وقيدُ التفرّد في القسم ٦ يجعلها
           --    مستحيلةً عملياً — والقيدان معاً لا أحدُهما.)
           (SELECT l.external_id FROM public.stock_links l
             WHERE l.integration_id = i.id AND l.deal_id = u.deal_id
               AND l.variant_id IS NOT DISTINCT FROM u.variant_id
               AND l.location_id IS NOT DISTINCT FROM u.location_id LIMIT 1) AS external_id
      FROM upd u
      LEFT JOIN LATERAL (SELECT * FROM public.stock_integrations si
                          WHERE si.store_id = u.store_id AND si.is_enabled
                            AND si.direction IN ('out','both') AND si.webhook_url IS NOT NULL
                          ORDER BY si.created_at LIMIT 1) i ON true
  ), bodied AS (
    SELECT j.*, (jsonb_build_object(
      'event_id', j.id, 'reason', j.reason, 'deal_id', j.deal_id,
      'external_id', j.external_id, 'variant_id', j.variant_id,
      'location_id', j.location_id, 'delta', j.delta,
      'on_hand', j.on_hand_after, 'barcode', j.barcode,
      'occurred_at', j.occurred_at))::text AS body_raw
      FROM joined j
  )
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
    'id', b.id, 'store_id', b.store_id, 'webhook_url', b.webhook_url,
    'body_raw', b.body_raw,
    -- v15.20 sign — لا يخرج السرُّ من القاعدة أبداً.
    'signature', 'sha256=' || encode(
        extensions.hmac(b.body_raw, COALESCE(b.webhook_secret, ''), 'sha256'), 'hex')
  ) ORDER BY b.id), '[]'::jsonb) INTO v_rows FROM bodied b;
  RETURN jsonb_build_object('ok', true, 'events', v_rows);
END
$function$
;


-- ═══ FUNCTION bot_rate_store(p_telegram_id bigint, p_barcode text, p_score integer, p_comment text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_rate_store(p_telegram_id bigint, p_barcode text, p_score integer, p_comment text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_name text; v_b bookings%ROWTYPE; v_store text;
BEGIN
  SELECT id, COALESCE(name,'مشتري') INTO v_uid, v_name FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF p_score < 1 OR p_score > 5 THEN RETURN jsonb_build_object('success',false,'error','bad_score'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode=UPPER(p_barcode) AND user_id=v_uid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  IF v_b.status <> 'completed' THEN RETURN jsonb_build_object('success',false,'error','not_completed'); END IF;
  SELECT store_id INTO v_store FROM deals WHERE id = v_b.deal_id;

  IF EXISTS (SELECT 1 FROM ratings WHERE store_id=v_store AND user_id=v_uid AND deleted_at IS NULL) THEN
    UPDATE ratings SET score=p_score, comment=NULLIF(btrim(COALESCE(p_comment,'')),''), updated_at=NOW()
      WHERE store_id=v_store AND user_id=v_uid AND deleted_at IS NULL;
  ELSE
    INSERT INTO ratings (id, deal_id, user_id, user_name, score, comment)
      VALUES (gen_random_uuid()::text, v_b.deal_id, v_uid, v_name, p_score, NULLIF(btrim(COALESCE(p_comment,'')),''));
  END IF;
  RETURN jsonb_build_object('success',true,'score',p_score);
END; $function$
;


-- ═══ FUNCTION bot_rating_status(p_telegram_id bigint, p_whatsapp_id text, p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_rating_status(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text, p_barcode text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_b bookings%ROWTYPE; v_store text; v_shop text; v_rev ratings%ROWTYPE; v_voted boolean; v_my_vote boolean;
BEGIN
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok',false,'error','not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode=UPPER(p_barcode) AND user_id=v_uid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok',false,'error','not_found'); END IF;
  SELECT store_id, shop_name INTO v_store, v_shop FROM deals WHERE id = v_b.deal_id;
  SELECT * INTO v_rev FROM ratings WHERE store_id=v_store AND user_id=v_uid AND deleted_at IS NULL LIMIT 1;
  SELECT is_real INTO v_my_vote FROM deal_authenticity_votes WHERE deal_id=v_b.deal_id AND user_id=v_uid;
  v_voted := FOUND;
  RETURN jsonb_build_object(
    'ok', true,
    'completed', v_b.status='completed',
    'shop_name', v_shop,
    'deal_id', v_b.deal_id,
    'voted_auth', v_voted,
    'my_vote', v_my_vote,
    'prev_score', v_rev.score,
    'prev_comment', v_rev.comment
  );
END; $function$
;


-- ═══ FUNCTION bot_remove_branch(p_telegram_id bigint, p_branch_id text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_remove_branch(p_telegram_id bigint, p_branch_id text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_b store_branches%ROWTYPE; v_locked boolean;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT * INTO v_b FROM store_branches WHERE id=p_branch_id AND merchant_id=v_sid;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  SELECT EXISTS(SELECT 1 FROM deals d WHERE d.store_id=v_sid AND d.status='active' AND (
     CASE WHEN d.location_id IS NOT NULL AND d.location_id<>'other' AND d.location_id NOT LIKE 'custom~_%' ESCAPE '~'
          THEN 'loc:'||d.location_id ELSE 'geo:'||ROUND(COALESCE(d.map_lat,0)::numeric,3)::text||','||ROUND(COALESCE(d.map_lng,0)::numeric,3)::text END
     = CASE WHEN v_b.location_id IS NOT NULL AND v_b.location_id<>'other' AND v_b.location_id NOT LIKE 'custom~_%' ESCAPE '~'
          THEN 'loc:'||v_b.location_id ELSE 'geo:'||ROUND(COALESCE(v_b.map_lat,0)::numeric,3)::text||','||ROUND(COALESCE(v_b.map_lng,0)::numeric,3)::text END
  )) INTO v_locked;
  IF v_locked THEN RETURN jsonb_build_object('success',false,'error','locked'); END IF;
  UPDATE store_branches SET is_active=false, updated_at=now() WHERE id=p_branch_id AND merchant_id=v_sid;
  RETURN jsonb_build_object('success',true);
END; $function$
;


-- ═══ FUNCTION bot_remove_notif_keyword(p_telegram_id bigint, p_index integer, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_remove_notif_keyword(p_telegram_id bigint, p_index integer, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_list text[];
BEGIN
  SELECT id, COALESCE(notif_keywords, ARRAY[]::text[]) INTO v_uid, v_list
    FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF p_index < 0 OR p_index >= COALESCE(array_length(v_list, 1), 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_index', 'keywords', to_jsonb(v_list));
  END IF;
  v_list := v_list[1:p_index] || v_list[p_index+2:COALESCE(array_length(v_list,1),0)];
  UPDATE users SET notif_keywords = v_list WHERE id = v_uid;
  RETURN jsonb_build_object('success', true, 'keywords', to_jsonb(COALESCE(v_list, ARRAY[]::text[])));
END; $function$
;


-- ═══ FUNCTION bot_remove_smart_alert(p_telegram_id bigint, p_index integer, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_remove_smart_alert(p_telegram_id bigint, p_index integer, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_arr jsonb;
BEGIN
  SELECT id, smart_alerts INTO v_uid, v_arr FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF v_arr IS NULL OR jsonb_typeof(v_arr) <> 'array' THEN v_arr := '[]'::jsonb; END IF;
  IF p_index < 0 OR p_index >= jsonb_array_length(v_arr) THEN RETURN jsonb_build_object('success',false,'error','bad_index'); END IF;
  v_arr := v_arr - p_index;
  UPDATE users SET smart_alerts=v_arr, updated_at=NOW() WHERE id=v_uid;
  RETURN jsonb_build_object('success',true,'count',jsonb_array_length(v_arr));
END; $function$
;


-- ═══ FUNCTION bot_report(p_telegram_id bigint, p_store_id text, p_type text, p_reason text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_report(p_telegram_id bigint, p_store_id text, p_type text, p_reason text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_reason text;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  v_reason := btrim(coalesce(p_reason,''));
  IF length(v_reason) < 5 THEN RETURN jsonb_build_object('success',false,'error','short_reason'); END IF;
  IF p_store_id IS NULL OR NOT EXISTS(SELECT 1 FROM users WHERE id=p_store_id) THEN
    RETURN jsonb_build_object('success',false,'error','bad_target'); END IF;
  BEGIN
    INSERT INTO reports (reporter_id, reported_id, report_type, reason)
    VALUES (v_uid, p_store_id,
            COALESCE(NULLIF(btrim(p_type),''),'other'),
            left(v_reason,1000));
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE '%SELF_REPORT%'  THEN RETURN jsonb_build_object('success',false,'error','self');
    ELSIF SQLERRM LIKE '%SAME_ROLE%' THEN RETURN jsonb_build_object('success',false,'error','same_role');
    ELSE RETURN jsonb_build_object('success',false,'error','blocked','detail',SQLERRM); END IF;
  END;
  RETURN jsonb_build_object('success',true);
END; $function$
;


-- ═══ FUNCTION bot_report_email_status(p_configured boolean, p_from text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_report_email_status(p_configured boolean, p_from text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN; END IF;
  INSERT INTO platform_settings (key, value, description)
  VALUES ('email_sender_status',
          jsonb_build_object('configured', COALESCE(p_configured,false), 'from', COALESCE(p_from,''), 'updated_at', now()),
          'حالة مرسل الإيميل — يكتبها سيرفر البوت تلقائياً (v12.27)')
  ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value, updated_at = now();
END $function$
;


-- ═══ FUNCTION bot_report_gate(p_version text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_report_gate(p_version text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_hdr text; v_which text;
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;
  v_hdr := current_setting('request.headers', true)::json ->> 'x-bot-secret';
  SELECT CASE key WHEN 'bot_gateway_secret_next' THEN 'next' ELSE 'current' END
    INTO v_which
  FROM public.app_secrets
  WHERE key IN ('bot_gateway_secret', 'bot_gateway_secret_next') AND value = v_hdr
  LIMIT 1;

  INSERT INTO public.bot_gate_usage (id, which, seen_at, bot_version)
  VALUES (1, COALESCE(v_which, 'unknown'), now(), p_version)
  ON CONFLICT (id) DO UPDATE
    SET which = EXCLUDED.which, seen_at = EXCLUDED.seen_at, bot_version = EXCLUDED.bot_version;

  RETURN jsonb_build_object('success', true, 'using', COALESCE(v_which, 'unknown'));
END $function$
;


-- ═══ FUNCTION bot_request_booking_refund(p_telegram_id bigint, p_barcode text, p_reason text, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_request_booking_refund(p_telegram_id bigint, p_barcode text, p_reason text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid text; v_b public.bookings%ROWTYPE; v_amt numeric; v_shop text; v_cur public.booking_refunds%ROWTYPE;
BEGIN
  SELECT id INTO v_uid FROM public.users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND OR v_b.user_id <> v_uid THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_b.paid_at IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_paid'); END IF;

  SELECT * INTO v_cur FROM public.booking_refunds WHERE barcode = v_b.barcode;
  IF FOUND AND v_cur.status IN ('requested','approved','refunded') THEN
    RETURN jsonb_build_object('success', true, 'already', true, 'status', v_cur.status);
  END IF;

  v_amt := round(COALESCE(NULLIF(v_b.paid_amount, 0), v_b.total_amount, 0), 2);
  INSERT INTO public.booking_refunds (barcode, store_id, buyer_id, status, opened_by, amount, reason)
  VALUES (v_b.barcode, v_b.store_id, v_b.user_id, 'requested', 'buyer', v_amt,
          NULLIF(left(btrim(COALESCE(p_reason,'')), 600), ''))
  ON CONFLICT (barcode) DO UPDATE
    SET status='requested', opened_by='buyer', amount=EXCLUDED.amount, reason=EXCLUDED.reason,
        requested_at=now(), decided_at=NULL, decided_by=NULL, merchant_note=NULL, updated_at=now();

  SELECT COALESCE(NULLIF(u.shop,''), u.name) INTO v_shop FROM public.users u WHERE u.id = v_b.store_id;
  PERFORM public._refund_notify(v_b.store_id,
    '↩️ طلب إلغاء واسترداد', 'Refund request',
    'طلب المشتري إلغاء الطلب ' || v_b.barcode || ' واسترداد ' || trim(to_char(v_amt,'FM999999990.09')) || ' ر.س. القرار لك وفق سياستك المعلنة.',
    'The buyer asked to cancel order ' || v_b.barcode || ' and be refunded ' || trim(to_char(v_amt,'FM999999990.09')) || ' SAR.',
    v_b.barcode, 'seller', 'refund_requested');
  PERFORM public._refund_notify(v_b.user_id,
    '↩️ وصل طلبك للتاجر', 'Your request was sent',
    'أرسلنا طلبك للطلب ' || v_b.barcode || ' إلى «' || COALESCE(v_shop,'المتجر') || '». القرار والتنفيذ عليه — تاكي وسيط لا تحتفظ بالمال ولا تبتّ فيه.',
    'Your request for order ' || v_b.barcode || ' was sent to "' || COALESCE(v_shop,'the store') || '".',
    v_b.barcode, 'buyer', 'refund_requested');

  RETURN jsonb_build_object('success', true, 'status', 'requested', 'amount', v_amt);
END
$function$
;


-- ═══ FUNCTION bot_save_branch(p_telegram_id bigint, p_branch_id text, p_name text, p_region text, p_city text, p_location_id text, p_map_lat double precision, p_map_lng double precision, p_google_maps_link text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_save_branch(p_telegram_id bigint, p_branch_id text DEFAULT NULL::text, p_name text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_map_lat double precision DEFAULT NULL::double precision, p_map_lng double precision DEFAULT NULL::double precision, p_google_maps_link text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_id text; v_name text; v_clean text;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  v_clean := NULLIF(btrim(COALESCE(p_name,'')),'');
  BEGIN
    IF p_branch_id IS NOT NULL THEN
      UPDATE store_branches SET
        name_ar=COALESCE(v_clean, name_ar),
        region_id=COALESCE(p_region,region_id), city_id=COALESCE(p_city,city_id),
        location_id=COALESCE(p_location_id,location_id), map_lat=COALESCE(p_map_lat,map_lat),
        map_lng=COALESCE(p_map_lng,map_lng), google_maps_link=COALESCE(p_google_maps_link,google_maps_link),
        is_active=true, updated_at=now()
      WHERE id=p_branch_id AND merchant_id=v_sid
      RETURNING name_ar INTO v_name;
      IF v_name IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
      v_id := p_branch_id;
    ELSE
      v_name := COALESCE(v_clean, 'موقع');
      INSERT INTO store_branches (merchant_id, name_ar, region_id, city_id, location_id, map_lat, map_lng, google_maps_link, is_active)
      VALUES (v_sid, v_name, p_region, p_city, p_location_id, p_map_lat, p_map_lng, p_google_maps_link, true)
      RETURNING id INTO v_id;
    END IF;
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE '%LOCATION_LIMIT_EXCEEDED%' THEN
      RETURN jsonb_build_object('success', false, 'error', 'location_limit');
    END IF;
    RAISE;
  END;
  RETURN jsonb_build_object('success',true,'id',v_id,'name',v_name);
END; $function$
;


-- ═══ FUNCTION bot_search(p_query text, p_limit integer, p_categories text[]) DEFINER owner=postgres search_path=search_path=public, pg_catalog anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_search(p_query text, p_limit integer DEFAULT 8, p_categories text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_q     text    := btrim(coalesce(p_query,''));
  v_norm  text;
  v_now   bigint  := (extract(epoch from now())*1000)::bigint;
  v_lim   integer := least(greatest(coalesce(p_limit,8),1),12);
  v_pat   text;
  v_ts    tsquery;
  v_deals jsonb;
  v_stores jsonb;
BEGIN
  IF length(v_q) < 2 THEN
    RETURN jsonb_build_object('deals','[]'::jsonb,'stores','[]'::jsonb,'q',v_q);
  END IF;

  v_norm := public.taki_norm(v_q);
  IF v_norm IS NULL THEN
    RETURN jsonb_build_object('deals','[]'::jsonb,'stores','[]'::jsonb,'q',v_q);
  END IF;
  v_pat := '%'||v_norm||'%';
  SELECT to_tsquery('simple', string_agg(quote_literal(t)||':*',' & ')) INTO v_ts
    FROM unnest(string_to_array(v_norm,' ')) AS t WHERE t <> '';

  WITH geo_ids AS (
    SELECT id FROM regions   WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM cities    WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM locations WHERE public.taki_norm(name) LIKE v_pat
  ),
  cat_keys AS (
    SELECT key FROM (VALUES
      ('فساتين','Fashion_Women'),('نساء','Fashion_Women'),('رجالية','Fashion_Men'),('ملابس رجال','Fashion_Men'),
      ('رضع','Kids_Infants'),('حمل','Kids_Infants'),('اطفال','Kids_Girls'),
      ('الكترونيات','Electronics'),('جوال','Electronics'),('مطاعم','Food'),('مطعم','Food'),
      ('عطور','Beauty'),('تجميل','Beauty'),('صالون رجالي','MensSalon'),('صالون نسائي','WomensSalon'),
      ('رياضة','Sports'),('سوبرماركت','Supermarket'),('بقالة','Supermarket'),('ملحمة','Butcher'),('لحم','Butcher'),
      ('صحية','Sanitary'),('مقاهي','Cafe'),('مقهى','Cafe'),('كافيه','Cafe'),('قهوة','Cafe'),
      ('منزل','Home'),('ديكور','Home'),('فنادق','Hotels'),('فندق','Hotels'),('تأجير سيارات','CarRentals'),('سيارات','CarRentals'),
      ('مغسلة','Laundry'),('خياطة','MensTailor'),('مشغل','WomensTailor'),('غسيل','CarWash'),
      ('ورش','CarWorkshop'),('ملاهي','Amusements'),('نادي','Gym'),('جيم','Gym'),('مكتبة','Library'),
      ('مشاتل','Nursery'),('صيدلية','Pharmacy'),('عيادات','Clinics'),('عيادة','Clinics'),('اونلاين','Online')
    ) AS c(label,key)
    -- التطبيع أغنى عن ازدواج «اطفال/أطفال» و«الكترونيات/إلكترونيات» يدوياً
    WHERE v_norm LIKE '%'||public.taki_norm(label)||'%'
       OR public.taki_norm(label) LIKE v_pat
  ),
  m AS (
    SELECT d.*,
      coalesce(d.discount_percentage,
        round(((d.original_price-d.discounted_price)/nullif(d.original_price,0))*100)::int) AS disc_pct
    FROM deals d
    WHERE d.status='active' AND (d.starts_at IS NULL OR d.starts_at <= v_now)
      AND NOT COALESCE(d.sold_out,false)
      AND (d.is_unlimited OR COALESCE(d.quantity,0) > 0 OR COALESCE(d.initial_quantity,0) <= 0)
      AND ( d.name_norm LIKE v_pat                     -- مطابقة داخلية («راشد» في «الراشد»)
            OR d.search_vec @@ v_ts                    -- نصّ كامل موزون (يشمل الوصف)
            OR v_norm <% d.name_norm                   -- تسامح مع الأخطاء الإملائية
            OR (p_categories IS NOT NULL AND d.category = ANY(p_categories))
            OR d.region      IN (SELECT id FROM geo_ids)
            OR d.city        IN (SELECT id FROM geo_ids)
            OR d.location_id IN (SELECT id FROM geo_ids)
            OR d.category    IN (SELECT key FROM cat_keys) )
    ORDER BY bookings_count DESC, d.created_at DESC
    LIMIT v_lim
  )
  SELECT jsonb_agg(jsonb_build_object(
    'id',id,'item_name',item_name,'shop_name',shop_name,'category',category,
    'original_price',original_price,'discounted_price',discounted_price,'discount_percentage',disc_pct,
    'quantity',quantity,'is_unlimited',is_unlimited,'prep_time',prep_time,'expiry_type',expiry_type,
    'expiry_date',expiry_date,'expires_in_minutes',expires_in_minutes,'starts_at',starts_at,'created_at',created_at,
    'map_lat',map_lat,'map_lng',map_lng,'google_maps_link',google_maps_link,'city',city,'region',region,
    'image',(images)[1],'images_count',coalesce(array_length(images,1),0),
    'working_hours',(SELECT working_hours FROM users u WHERE u.id=m.store_id),
    'open_status',public.store_is_open((SELECT working_hours FROM users u WHERE u.id=m.store_id)),
    'bookings_count',bookings_count,'is_sponsored',false)) INTO v_deals FROM m;

  WITH geo_ids AS (
    SELECT id FROM regions   WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM cities    WHERE public.taki_norm(name) LIKE v_pat
    UNION SELECT id FROM locations WHERE public.taki_norm(name) LIKE v_pat
  ),
  s AS (
    SELECT d.store_id, max(d.shop_name) AS shop_name, max(d.city) AS city,
           max(d.region) AS region, count(*) AS deals_n
    FROM deals d
    WHERE d.status='active' AND (d.starts_at IS NULL OR d.starts_at <= v_now)
      AND NOT COALESCE(d.sold_out,false)
      AND (d.is_unlimited OR COALESCE(d.quantity,0) > 0 OR COALESCE(d.initial_quantity,0) <= 0)
      AND ( d.name_norm LIKE v_pat
            OR d.region      IN (SELECT id FROM geo_ids)
            OR d.city        IN (SELECT id FROM geo_ids)
            OR d.location_id IN (SELECT id FROM geo_ids) )
    GROUP BY d.store_id
    ORDER BY deals_n DESC
    LIMIT 6
  )
  SELECT jsonb_agg(jsonb_build_object('store_id',store_id,'shop_name',shop_name,
    'city',city,'region',region,'deals_n',deals_n)) INTO v_stores FROM s;

  RETURN jsonb_build_object('deals',coalesce(v_deals,'[]'::jsonb),
                            'stores',coalesce(v_stores,'[]'::jsonb),'q',v_q);
END
$function$
;


-- ═══ FUNCTION bot_season_campaign() DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_season_campaign()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((SELECT value FROM platform_settings WHERE key = 'season_campaign'), 'null'::jsonb);
$function$
;


-- ═══ FUNCTION bot_send_booking_message(p_telegram_id bigint, p_barcode text, p_body text, p_whatsapp_id text, p_attachment_path text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_send_booking_message(p_telegram_id bigint, p_barcode text, p_body text, p_whatsapp_id text DEFAULT NULL::text, p_attachment_path text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid text; v_b bookings%ROWTYPE; v_role text; v_cnt int; v_cap int;
  v_body text := btrim(COALESCE(p_body, ''));
  v_att  text := NULLIF(btrim(COALESCE(p_attachment_path, '')), '');
  v_other text; v_since timestamptz; v_allow int; v_sent int;
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authorized');
  END IF;

  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;

  -- صورةٌ بلا نصّ رسالةٌ كاملة، لكن الجدول يمنع النصّ الفارغ.
  IF v_body = '' AND v_att IS NOT NULL THEN v_body := '📎'; END IF;
  IF v_body = '' OR length(v_body) > 500 THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_body');
  END IF;

  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_uid = v_b.user_id THEN v_role := 'buyer';
  ELSIF v_uid = v_b.store_id THEN v_role := 'seller';
  ELSE RETURN jsonb_build_object('success', false, 'error', 'not_authorized'); END IF;

  IF v_b.status IN ('cancelled','completed','expired') THEN
    RETURN jsonb_build_object('success', false, 'error', 'chat_closed');
  END IF;

  -- المرفق تحت مجلّد هذا الحجز، وموجودٌ فعلاً. (المِلكية تحقّقت منها الدالة
  -- الطرفية قبل الرفع — البوت لا يحمل هوية قاعدة بيانات ليُقارَن بها.)
  IF v_att IS NOT NULL THEN
    IF split_part(v_att, '/', 1) <> v_b.barcode THEN
      RETURN jsonb_build_object('success', false, 'error', 'attachment_outside_booking');
    END IF;
    IF NOT EXISTS (SELECT 1 FROM storage.objects o WHERE o.bucket_id = 'chat' AND o.name = v_att) THEN
      RETURN jsonb_build_object('success', false, 'error', 'attachment_missing');
    END IF;
  END IF;

  -- v15.80 — الحجب. نفسُ دلالةِ مشغّلِ الجدول حرفياً (مصدرُ البحث واحد:
  -- `taki_block_since`)، لكن **رمزاً** لا استثناءً كي يبلغ القناتين.
  v_other := CASE WHEN v_role = 'buyer' THEN v_b.store_id ELSE v_b.user_id END;
  v_since := public.taki_block_since(v_uid, v_other);
  IF v_since IS NOT NULL THEN
    IF v_b.paid_at IS NULL AND COALESCE(v_b.fulfillment, '') <> 'delivery' THEN
      RETURN jsonb_build_object('success', false, 'error', 'blocked');
    END IF;
    v_allow := (public.taki_chat_limits()->>'blocked_inflight')::int;
    SELECT count(*) INTO v_sent FROM booking_messages
     WHERE barcode = v_b.barcode AND sender_role = v_role AND created_at >= v_since;
    IF v_allow <= 0 OR v_sent >= v_allow THEN
      RETURN jsonb_build_object('success', false, 'error', 'blocked_cap');
    END IF;
  END IF;

  SELECT count(*) INTO v_cnt FROM booking_messages WHERE barcode = v_b.barcode AND sender_role = v_role;
  -- v14.93 — الحدّ من الإعداد، و0 = بلا حدّ.
  v_cap := (public.taki_chat_limits()->>'per_booking')::int;
  IF v_cap > 0 AND v_cnt >= v_cap THEN
    RETURN jsonb_build_object('success', false, 'error', 'limit_reached', 'cap', v_cap);
  END IF;

  INSERT INTO booking_messages (barcode, sender_id, sender_role, body, attachment_path)
  VALUES (v_b.barcode, v_uid, v_role, v_body, v_att);

  RETURN jsonb_build_object('success', true, 'my_count', v_cnt + 1, 'cap', v_cap);
END $function$
;


-- ═══ FUNCTION bot_set_deal_location(p_telegram_id bigint, p_deal_id text, p_location_id text, p_custom_location_name text, p_map_lat double precision, p_map_lng double precision, p_region text, p_city text, p_google_maps_link text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_deal_location(p_telegram_id bigint, p_deal_id text, p_location_id text DEFAULT NULL::text, p_custom_location_name text DEFAULT NULL::text, p_map_lat double precision DEFAULT NULL::double precision, p_map_lng double precision DEFAULT NULL::double precision, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_google_maps_link text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  IF NOT EXISTS(SELECT 1 FROM deals WHERE id=p_deal_id AND store_id=v_sid) THEN
    RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  BEGIN
    UPDATE deals SET
      location_id=p_location_id, custom_location_name=p_custom_location_name,
      map_lat=p_map_lat, map_lng=p_map_lng, region=COALESCE(p_region,region), city=COALESCE(p_city,city),
      google_maps_link=p_google_maps_link
    WHERE id=p_deal_id AND store_id=v_sid;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('success',false,'error','blocked','detail',SQLERRM);
  END;
  RETURN jsonb_build_object('success',true);
END; $function$
;


-- ═══ FUNCTION bot_set_deal_season(p_deal_id text, p_on boolean, p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_deal_season(p_deal_id text, p_on boolean DEFAULT true, p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid    text;
    v_camp   jsonb;
    v_season text;
BEGIN
    IF NOT public._bot_gate_ok() THEN
        RETURN jsonb_build_object('success', false, 'error', 'forbidden');
    END IF;
    v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
    IF v_uid IS NULL THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_linked');
    END IF;

    IF p_on THEN
        SELECT value INTO v_camp FROM platform_settings WHERE key = 'season_campaign';
        v_season := v_camp->>'season_id';
        IF v_season IS NULL OR v_season = '' THEN
            RETURN jsonb_build_object('success', false, 'error', 'no_campaign');
        END IF;
    END IF;

    BEGIN
        UPDATE deals SET season_id = CASE WHEN p_on THEN v_season ELSE NULL END
         WHERE id = p_deal_id AND store_id = v_uid;
    EXCEPTION WHEN OTHERS THEN
        -- الحارس tr_deal_season رفض (نافذة مغلقة…) — نعيد رسالته العربية كما هي
        RETURN jsonb_build_object('success', false, 'error', 'window_closed', 'detail', SQLERRM);
    END;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('success', false, 'error', 'not_found');
    END IF;
    RETURN jsonb_build_object('success', true, 'season_id', CASE WHEN p_on THEN v_season ELSE NULL END);
END; $function$
;


-- ═══ FUNCTION bot_set_delivery(p_telegram_id bigint, p_whatsapp_id text, p_enabled boolean, p_payment text, p_fee numeric, p_min_order numeric, p_eta_min integer, p_note text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_delivery(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text, p_enabled boolean DEFAULT NULL::boolean, p_payment text DEFAULT NULL::text, p_fee numeric DEFAULT NULL::numeric, p_min_order numeric DEFAULT NULL::numeric, p_eta_min integer DEFAULT NULL::integer, p_note text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid   text;
  v_type  text;
  v_shop  text;
  sp      public.store_profiles%ROWTYPE;
  v_en    boolean;
  v_pay   text;
  v_fee   numeric;
  v_min   numeric;
  v_eta   integer;
  v_note  text;
  v_mode  text;
BEGIN
  IF NOT public._bot_gate_ok() THEN RAISE EXCEPTION 'GATE'; END IF;
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_linked'); END IF;
  SELECT user_type, shop INTO v_type, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_type IS NULL OR (v_type NOT IN ('seller','admin')
      AND nullif(btrim(coalesce(v_shop,'')),'') IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_seller');
  END IF;

  SELECT * INTO sp FROM public.store_profiles WHERE store_id = v_uid;

  -- الدمج: `NULL` = لا تغيّر. والملاحظة وحدها يمسحها نصٌّ فارغ صراحةً.
  v_en   := coalesce(p_enabled,   sp.delivery_enabled,   false);
  v_pay  := coalesce(p_payment,   sp.delivery_payment,   'cod');
  v_fee  := coalesce(p_fee,       sp.delivery_fee,       0);
  v_min  := coalesce(p_min_order, sp.delivery_min_order, 0);
  v_eta  := coalesce(p_eta_min,   sp.delivery_eta_min);
  v_note := CASE WHEN p_note IS NULL THEN sp.delivery_note
                 ELSE nullif(left(btrim(p_note), 300), '') END;

  -- نفس حدود `merchant_set_delivery` ونفس رموزها — لا تُخفَّف ولا تُشدَّد.
  IF v_pay NOT IN ('cod','card','both')                 THEN RETURN jsonb_build_object('ok', false, 'reason', 'BAD_MODE'); END IF;
  IF v_fee < 0  OR v_fee > 1000                          THEN RETURN jsonb_build_object('ok', false, 'reason', 'BAD_FEE');  END IF;
  IF v_min < 0  OR v_min > 100000                        THEN RETURN jsonb_build_object('ok', false, 'reason', 'BAD_MIN');  END IF;
  IF v_eta IS NOT NULL AND v_eta NOT BETWEEN 0 AND 1440  THEN RETURN jsonb_build_object('ok', false, 'reason', 'BAD_ETA');  END IF;
  -- 🪤 فحص البوابة يجري حين **يُطلب** تغييرٌ يمسّ الدفع أو التفعيل، لا في كل
  --    كتابة. الموقع يرسل الحقول الستّة دفعةً واحدة فيُعيد الفحص دائماً؛ أما
  --    البوت فيعدّل حقلاً واحداً. قِيس على جدة: متجرٌ حالته محفوظة
  --    «مفعّل + بطاقة» وبوّابته معطوبة اليوم — فكان تعديل **الرسم وحده** يُرفض
  --    بـGATEWAY_REQUIRED، أي يُحبس التاجر عن إعدادٍ لا علاقة له بالبوابة.
  --    ولا ثغرة: أي طلبٍ يرفع التفعيل أو يحوّل الوضع إلى بطاقة يُفحص كاملاً.
  IF (p_enabled IS NOT NULL OR p_payment IS NOT NULL)
     AND v_en AND v_pay IN ('card','both') THEN
    v_mode := public.deal_payment_mode(v_uid);
    IF v_mode NOT IN ('online','both') THEN
      RETURN jsonb_build_object('ok', false, 'reason', 'GATEWAY_REQUIRED');
    END IF;
  END IF;

  INSERT INTO public.store_profiles
      (store_id, delivery_enabled, delivery_payment, delivery_fee, delivery_min_order, delivery_eta_min, delivery_note)
  VALUES (v_uid, v_en, v_pay, round(v_fee, 2), round(v_min, 2), v_eta, v_note)
  ON CONFLICT (store_id) DO UPDATE SET
    delivery_enabled   = EXCLUDED.delivery_enabled,
    delivery_payment   = EXCLUDED.delivery_payment,
    delivery_fee       = EXCLUDED.delivery_fee,
    delivery_min_order = EXCLUDED.delivery_min_order,
    delivery_eta_min   = EXCLUDED.delivery_eta_min,
    delivery_note      = EXCLUDED.delivery_note,
    updated_at         = now();

  -- الردّ = الحالة الجديدة كاملةً (نفس شكل القراءة) فتُعاد رسم البطاقة بلا نداءٍ ثانٍ.
  RETURN public.bot_get_delivery(p_telegram_id, p_whatsapp_id);
END $function$
;


-- ═══ FUNCTION bot_set_lang(p_telegram_id bigint, p_lang text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_lang(p_telegram_id bigint, p_lang text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_lang text := lower(COALESCE(p_lang,'ar'));
BEGIN
  IF v_lang NOT IN ('ar','en') THEN v_lang := 'ar'; END IF;
  UPDATE public.users SET bot_lang = v_lang
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  RETURN jsonb_build_object('success', true, 'lang', v_lang);
END;
$function$
;


-- ═══ FUNCTION bot_set_location(p_telegram_id bigint, p_lat double precision, p_lng double precision, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_location(p_telegram_id bigint, p_lat double precision, p_lng double precision, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text; v_type text; v_shop text;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL OR p_lat < -90 OR p_lat > 90
     OR p_lng < -180 OR p_lng > 180 THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_coords');
  END IF;

  SELECT id, user_type, shop INTO v_uid, v_type, v_shop
    FROM public.users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;

  -- نفس شرط الموقع حرفاً بحرف: مشترٍ صِرف فقط.
  IF v_type IS DISTINCT FROM 'buyer'
     OR nullif(btrim(coalesce(v_shop, '')), '') IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'store_pin_protected');
  END IF;

  UPDATE public.users SET lat = p_lat, lng = p_lng WHERE id = v_uid;
  RETURN jsonb_build_object('success', true);
END $function$
;


-- ═══ FUNCTION bot_set_sold_out(p_telegram_id bigint, p_deal_id text, p_on boolean, p_variant_id text, p_location_id text, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_sold_out(p_telegram_id bigint, p_deal_id text, p_on boolean, p_variant_id text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sid text;
BEGIN
  SELECT id INTO v_sid FROM users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id)
     AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  IF NOT EXISTS (SELECT 1 FROM deals WHERE id = p_deal_id AND store_id = v_sid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  PERFORM public._taki_set_off(p_deal_id, p_on, p_variant_id, p_location_id);
  RETURN jsonb_build_object('success', true, 'off', COALESCE(p_on, false));
END
$function$
;


-- ═══ FUNCTION bot_set_stock(p_telegram_id bigint, p_deal_id text, p_on_hand integer, p_variants jsonb, p_locations jsonb, p_whatsapp_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_stock(p_telegram_id bigint, p_deal_id text, p_on_hand integer DEFAULT NULL::integer, p_variants jsonb DEFAULT NULL::jsonb, p_locations jsonb DEFAULT NULL::jsonb, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sid text; v_res jsonb;
BEGIN
  SELECT id INTO v_sid FROM users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id)
     AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  IF NOT EXISTS (SELECT 1 FROM deals WHERE id = p_deal_id AND store_id = v_sid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  -- 🪤 المرورُ من الكاتب المُعلَن: قفلُ الصفّ وإعادةُ اشتقاق كلّ مرآةٍ متاحة.
  --    ولا يُمرّ من `bot_update_deal.p_quantity`: كان صفرُها يجعل العرض بلا حدّ
  --    (أُصلح في v15.05) وهي تكتب أعمدةً أخرى لا تخصّ المخزون.
  v_res := public.taki_set_on_hand(p_deal_id, p_on_hand, p_variants, p_locations, now(), 'merchant');
  RETURN jsonb_build_object('success', COALESCE((v_res->>'ok')::boolean, false), 'stock', v_res);
END
$function$
;


-- ═══ FUNCTION bot_set_store_hours(p_telegram_id bigint, p_hours jsonb, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_store_hours(p_telegram_id bigint, p_hours jsonb, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user users%ROWTYPE;
BEGIN
  SELECT * INTO v_user FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF v_user.user_type NOT IN ('seller','admin') THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  UPDATE users SET working_hours = p_hours WHERE id = v_user.id;
  RETURN jsonb_build_object('success', true, 'working_hours', p_hours);
END; $function$
;


-- ═══ FUNCTION bot_set_telegram_notif(p_telegram_id bigint, p_enabled boolean, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_set_telegram_notif(p_telegram_id bigint, p_enabled boolean, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text;
BEGIN
  v_uid := public._bot_uid(p_telegram_id, p_whatsapp_id);
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF p_whatsapp_id IS NOT NULL THEN
    UPDATE users SET notify_via_whatsapp = COALESCE(p_enabled, true) WHERE id = v_uid AND deleted_at IS NULL;
  ELSE
    UPDATE users SET notify_via_telegram = COALESCE(p_enabled, true) WHERE id = v_uid AND deleted_at IS NULL;
  END IF;
  RETURN jsonb_build_object('success', true, 'enabled', COALESCE(p_enabled, true));
END; $function$
;


-- ═══ FUNCTION bot_store_contact(p_telegram_id bigint, p_store_id text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_store_contact(p_telegram_id bigint, p_store_id text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_phone text; v_name text;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  SELECT COALESCE(NULLIF(btrim(sp.phone),''), NULLIF(btrim(u.contact_phone),''), NULLIF(btrim(u.phone),'')),
         COALESCE(NULLIF(btrim(u.shop),''), NULLIF(btrim(u.name),''),'المتجر')
    INTO v_phone, v_name
    FROM users u LEFT JOIN store_profiles sp ON sp.store_id=u.id
    WHERE u.id=p_store_id AND u.user_type='seller' LIMIT 1;
  IF v_name IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  RETURN jsonb_build_object('success',true,'phone',v_phone,'name',v_name);
END; $function$
;


-- ═══ FUNCTION bot_submit_contest_entry(p_telegram_id bigint, p_contest_id uuid, p_answers jsonb, p_social jsonb, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_submit_contest_entry(p_telegram_id bigint, p_contest_id uuid, p_answers jsonb, p_social jsonb DEFAULT '{}'::jsonb, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  c record; q jsonb; v_score int := 0; v_max int := 0; v_qual boolean;
  ans text; pts int;
  correct_set jsonb; n_correct int;
  v_uid text; v_name text; v_phone text; v_role text;
BEGIN
  SELECT id, coalesce(nullif(btrim(name),''),'مشارك'), nullif(btrim(phone),''), user_type
    INTO v_uid, v_name, v_phone, v_role
  FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL  THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF v_phone IS NULL THEN RETURN jsonb_build_object('success',false,'error','no_phone'); END IF;

  SELECT * INTO c FROM contests WHERE id=p_contest_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;
  IF c.status<>'active' THEN RETURN jsonb_build_object('success',false,'error','not_active'); END IF;
  IF c.starts_at IS NOT NULL AND now()<c.starts_at THEN RETURN jsonb_build_object('success',false,'error','not_started'); END IF;
  IF c.ends_at   IS NOT NULL AND now()>c.ends_at   THEN RETURN jsonb_build_object('success',false,'error','ended'); END IF;

  IF v_role IS DISTINCT FROM 'admin' THEN
    IF c.audience='sellers' AND v_role IS DISTINCT FROM 'seller' THEN
      RETURN jsonb_build_object('success',false,'error','sellers_only'); END IF;
    IF c.audience='buyers'  AND v_role='seller' THEN
      RETURN jsonb_build_object('success',false,'error','buyers_only'); END IF;
  END IF;

  IF EXISTS(SELECT 1 FROM contest_entries e WHERE e.contest_id=p_contest_id AND e.phone=v_phone) THEN
    RETURN jsonb_build_object('success',false,'error','already_entered');
  END IF;

  FOR q IN SELECT * FROM jsonb_array_elements(coalesce(c.questions,'[]'::jsonb)) LOOP
    -- v12.37: multi-correct — correctAnswers[] first, legacy correctAnswer fallback
    correct_set := q->'correctAnswers';
    IF correct_set IS NULL OR jsonb_typeof(correct_set) <> 'array' THEN
      correct_set := '[]'::jsonb;
    END IF;
    IF jsonb_array_length(correct_set) = 0
       AND coalesce(btrim(q->>'correctAnswer'), '') <> '' THEN
      correct_set := jsonb_build_array(q->>'correctAnswer');
    END IF;
    SELECT count(*) INTO n_correct
      FROM jsonb_array_elements_text(correct_set) v WHERE btrim(v) <> '';
    IF n_correct > 0 THEN
      pts := coalesce(nullif(q->>'points','')::int,1);
      v_max := v_max + pts;
      ans := p_answers->>(q->>'id');
      IF ans IS NOT NULL AND EXISTS (
        SELECT 1 FROM jsonb_array_elements_text(correct_set) ca
        WHERE btrim(ca) <> '' AND lower(btrim(ca)) = lower(btrim(ans))
      ) THEN v_score := v_score + pts; END IF;
    END IF;
  END LOOP;

  v_qual := CASE c.pass_mode
    WHEN 'collect' THEN true
    WHEN 'any'     THEN (v_score>0 OR v_max=0)
    ELSE (v_score>=v_max) END;

  INSERT INTO contest_entries(contest_id,name,phone,answers,social_answers,score,max_score,qualified)
  VALUES (p_contest_id,v_name,v_phone,coalesce(p_answers,'{}'::jsonb),coalesce(p_social,'{}'::jsonb),v_score,v_max,v_qual);

  RETURN jsonb_build_object('success',true,'qualified',v_qual,'score',v_score,'max_score',v_max,'name',v_name);
END; $function$
;


-- ═══ FUNCTION bot_subscribe_plan(p_telegram_id bigint, p_package_id integer, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_subscribe_plan(p_telegram_id bigint, p_package_id integer, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_dry jsonb; v_res jsonb; v_pkg jsonb; v_vat numeric;
BEGIN
  IF NOT public.bot_payments_enabled() THEN
    RETURN jsonb_build_object('success', false, 'error', 'free_mode');
  END IF;
  SELECT id INTO v_sid FROM users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id)
     AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_seller');
  END IF;
  v_dry := public._taki_apply_package_dry(p_package_id);
  IF NOT COALESCE((v_dry->>'success')::boolean, false) THEN
    RETURN jsonb_build_object('success', false, 'error',
      CASE v_dry->>'error' WHEN 'unknown_package' THEN 'bad_package'
                           WHEN 'package_inactive' THEN 'bad_package'
                           ELSE COALESCE(v_dry->>'error','bad_package') END);
  END IF;
  IF NOT public._taki_sub_payment_ok(v_sid, p_package_id, (v_dry->>'net')::numeric) THEN
    RETURN jsonb_build_object('success', false, 'error', 'payment_not_confirmed');
  END IF;
  v_res := public._taki_apply_package(v_sid, p_package_id, NULL, true);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN RETURN v_res; END IF;
  SELECT pkg INTO v_pkg FROM public.platform_settings ps,
         LATERAL jsonb_array_elements(ps.value) AS pkg
   WHERE ps.key = 'location_packages' AND (pkg->>'id')::int = p_package_id LIMIT 1;
  SELECT CASE WHEN COALESCE((s.value->>'vat_enabled')::boolean, false)
               AND COALESCE((s.value->>'prices_include_vat')::boolean, true) = false
              THEN round((v_res->>'net')::numeric
                         * COALESCE(NULLIF(s.value->>'vat_rate','')::numeric, 15) / 100, 2)
              ELSE 0 END
    INTO v_vat
    FROM (SELECT value FROM public.platform_settings WHERE key = 'tax_settings'
          UNION ALL SELECT '{}'::jsonb LIMIT 1) s;
  RETURN jsonb_build_object('success', true, 'plan_ar', v_pkg->>'ar',
    'max_branches', (v_res->>'max_branches')::int, 'price', (v_res->>'net')::numeric,
    'expires_at', v_res->>'expires_at', 'days', (v_res->>'days')::int,
    'vat', v_vat, 'total', round((v_res->>'net')::numeric + v_vat, 2));
END $function$
;


-- ═══ FUNCTION bot_toggle_block(p_telegram_id bigint, p_store_id text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_toggle_block(p_telegram_id bigint, p_store_id text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_blocked boolean; v_n int;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;

  -- 🪤 ويُفحص الهدفُ هنا لا يُترك للمفتاح الأجنبيّ: استثناءٌ مرفوعٌ يبتلعه
  --    غلافُ `rpc()` إلى `null` فيصمت البوت.
  IF v_uid = p_store_id THEN RETURN jsonb_build_object('success', false, 'error', 'self'); END IF;
  IF NOT EXISTS (SELECT 1 FROM users WHERE id = p_store_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;

  DELETE FROM public.user_blocks WHERE blocker_id = v_uid AND blocked_id = p_store_id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  IF v_n > 0 THEN
    v_blocked := false;
  ELSE
    INSERT INTO public.user_blocks (blocker_id, blocked_id) VALUES (v_uid, p_store_id)
      ON CONFLICT DO NOTHING;
    v_blocked := true;
  END IF;

  RETURN jsonb_build_object('success', true, 'blocked', v_blocked);
END $function$
;


-- ═══ FUNCTION bot_toggle_deal(p_telegram_id bigint, p_deal_id text, p_status text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_toggle_deal(p_telegram_id bigint, p_deal_id text, p_status text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_max int;
BEGIN
  IF p_status NOT IN ('active','paused') THEN RETURN jsonb_build_object('success', false, 'error', 'invalid'); END IF;
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  IF NOT EXISTS (SELECT 1 FROM deals WHERE id = p_deal_id AND store_id = v_sid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_found');
  END IF;
  IF p_status = 'active' AND NOT public.ensure_active_subscription(v_sid) THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_subscription');
  END IF;
  BEGIN
    UPDATE deals SET status = p_status WHERE id = p_deal_id AND store_id = v_sid;
  EXCEPTION WHEN OTHERS THEN
    IF SQLERRM LIKE 'LOCATION_LIMIT_EXCEEDED%' THEN
      SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = v_sid;
      RETURN jsonb_build_object('success', false, 'error', 'location_cap', 'max', COALESCE(v_max, 3));
    END IF;
    RETURN jsonb_build_object('success', false, 'error', 'blocked', 'detail', SQLERRM);
  END;
  RETURN jsonb_build_object('success', true);
END $function$
;


-- ═══ FUNCTION bot_toggle_follow(p_telegram_id bigint, p_store_id text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_toggle_follow(p_telegram_id bigint, p_store_id text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_arr text[]; v_following boolean;
BEGIN
  SELECT id, COALESCE(followed_merchants,'{}') INTO v_uid, v_arr FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_linked'); END IF;
  IF p_store_id = ANY(v_arr) THEN
    UPDATE users SET followed_merchants = array_remove(v_arr, p_store_id) WHERE id=v_uid; v_following := false;
  ELSE
    UPDATE users SET followed_merchants = array_append(v_arr, p_store_id) WHERE id=v_uid; v_following := true;
  END IF;
  RETURN jsonb_build_object('success',true,'following',v_following);
END; $function$
;


-- ═══ FUNCTION bot_touch_chat(p_telegram_id bigint, p_chat_id bigint) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_touch_chat(p_telegram_id bigint, p_chat_id bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public._bot_gate_ok() THEN
    RAISE EXCEPTION 'forbidden' USING ERRCODE = '42501';
  END IF;
  UPDATE users SET telegram_chat_id = p_chat_id, notify_via_telegram = true
    WHERE telegram_id = p_telegram_id AND telegram_chat_id IS DISTINCT FROM p_chat_id;
END;
$function$
;


-- ═══ FUNCTION bot_track_open(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_track_open(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := public._bot_uid(p_telegram_id, p_whatsapp_id);
        v_src text := CASE WHEN p_telegram_id IS NOT NULL THEN 'telegram' ELSE 'whatsapp' END;
        v_lat double precision; v_lng double precision;
BEGIN
    -- v15.79 — الموافقةُ على الخادم.
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.users WHERE id = v_uid AND COALESCE(analytics_opt_out, false)
    ) THEN RETURN; END IF;

    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind='app_open' AND user_id=v_uid AND source=v_src
          AND created_at > now() - interval '30 minutes'
    ) THEN RETURN; END IF;
    -- آخر موقع معروف للمستخدم المربوط (المشترك يشارك موقعه في التطبيق).
    IF v_uid IS NOT NULL THEN
        SELECT round(u.lat::numeric, 2)::double precision,
               round(u.lng::numeric, 2)::double precision
          INTO v_lat, v_lng
          FROM users u WHERE u.id = v_uid;
    END IF;
    INSERT INTO analytics_events (kind, user_id, source, lat, lng)
    VALUES ('app_open', v_uid, v_src, v_lat, v_lng);
END;
$function$
;


-- ═══ FUNCTION bot_unlink(p_telegram_id bigint, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_unlink(p_telegram_id bigint DEFAULT NULL::bigint, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_name text;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  IF p_whatsapp_id IS NOT NULL THEN
    UPDATE users SET whatsapp_chat_id = NULL, notify_via_whatsapp = false
      WHERE whatsapp_chat_id = p_whatsapp_id RETURNING name INTO v_name;
  ELSE
    UPDATE users SET telegram_id = NULL, telegram_chat_id = NULL, notify_via_telegram = false
      WHERE telegram_id = p_telegram_id RETURNING name INTO v_name;
  END IF;
  IF v_name IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  RETURN jsonb_build_object('success', true, 'name', v_name);
END; $function$
;


-- ═══ FUNCTION bot_update_booking(p_telegram_id bigint, p_barcode text, p_quantity integer, p_prep_time text, p_notes text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_update_booking(p_telegram_id bigint, p_barcode text, p_quantity integer DEFAULT NULL::integer, p_prep_time text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_b bookings%ROWTYPE; v_deal deals%ROWTYPE; v_newqty int; v_delta int;
BEGIN
  SELECT id INTO v_uid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND deleted_at IS NULL LIMIT 1;
  IF v_uid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_linked'); END IF;
  SELECT * INTO v_b FROM bookings WHERE barcode = UPPER(p_barcode) AND user_id = v_uid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  IF v_b.status <> 'pending' THEN RETURN jsonb_build_object('success', false, 'error', 'not_editable', 'status', v_b.status); END IF;
  SELECT * INTO v_deal FROM deals WHERE id = v_b.deal_id LIMIT 1;

  v_newqty := COALESCE(p_quantity, v_b.booked_quantity);
  IF v_newqty < 1 THEN v_newqty := 1; END IF;
  -- v12.28: respect the merchant's per-booking cap on edits as well
  IF COALESCE(v_deal.max_per_booking, 0) > 0 AND v_newqty > v_deal.max_per_booking THEN
    RETURN jsonb_build_object('success', false, 'error', 'max_qty', 'limit', v_deal.max_per_booking);
  END IF;
  v_delta := v_newqty - v_b.booked_quantity;
  IF NOT COALESCE(v_deal.is_unlimited,false) AND v_delta > 0 AND COALESCE(v_deal.quantity,0) < v_delta THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_quantity', 'available', v_b.booked_quantity + COALESCE(v_deal.quantity,0));
  END IF;
  IF NOT COALESCE(v_deal.is_unlimited,false) AND v_delta <> 0 THEN
    UPDATE deals SET quantity = GREATEST(0, quantity - v_delta) WHERE id = v_b.deal_id;
  END IF;

  UPDATE bookings SET
    booked_quantity = v_newqty,
    prep_time = COALESCE(NULLIF(btrim(COALESCE(p_prep_time,'')),''), prep_time),
    notes = CASE WHEN p_notes IS NULL THEN notes ELSE NULLIF(btrim(p_notes),'') END
  WHERE barcode = v_b.barcode AND user_id = v_uid;

  RETURN jsonb_build_object('success', true, 'quantity', v_newqty);
END; $function$
;


-- ═══ FUNCTION bot_update_deal(p_telegram_id bigint, p_deal_id text, p_item_name text, p_original_price numeric, p_discounted_price numeric, p_quantity integer, p_description text, p_category text, p_size text, p_gender text, p_expiry_type text, p_expiry_date text, p_expires_in_minutes integer, p_starts_at bigint, p_clear_schedule boolean, p_is_unlimited boolean, p_images text[], p_status text, p_whatsapp_id text, p_max_per_booking integer, p_max_bookings_per_buyer integer, p_rebook_cooldown_minutes integer) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_update_deal(p_telegram_id bigint, p_deal_id text, p_item_name text DEFAULT NULL::text, p_original_price numeric DEFAULT NULL::numeric, p_discounted_price numeric DEFAULT NULL::numeric, p_quantity integer DEFAULT NULL::integer, p_description text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_size text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_expiry_type text DEFAULT NULL::text, p_expiry_date text DEFAULT NULL::text, p_expires_in_minutes integer DEFAULT NULL::integer, p_starts_at bigint DEFAULT NULL::bigint, p_clear_schedule boolean DEFAULT false, p_is_unlimited boolean DEFAULT NULL::boolean, p_images text[] DEFAULT NULL::text[], p_status text DEFAULT NULL::text, p_whatsapp_id text DEFAULT NULL::text, p_max_per_booking integer DEFAULT NULL::integer, p_max_bookings_per_buyer integer DEFAULT NULL::integer, p_rebook_cooldown_minutes integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_d deals%ROWTYPE; v_orig numeric; v_disc numeric; v_pct int; v_now bigint;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success',false,'error','not_seller'); END IF;
  SELECT * INTO v_d FROM deals WHERE id=p_deal_id AND store_id=v_sid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success',false,'error','not_found'); END IF;

  v_orig := COALESCE(p_original_price, v_d.original_price);
  v_disc := COALESCE(p_discounted_price, v_d.discounted_price);
  IF v_disc >= v_orig THEN RETURN jsonb_build_object('success',false,'error','invalid_price'); END IF;
  v_pct := CASE WHEN v_orig > 0 THEN round(((v_orig - v_disc)/v_orig)*100) ELSE 0 END;

  UPDATE deals SET
    item_name           = COALESCE(NULLIF(btrim(COALESCE(p_item_name,'')),''), item_name),
    original_price      = v_orig,
    discounted_price    = v_disc,
    discount_percentage = v_pct,
    quantity            = CASE WHEN p_is_unlimited IS TRUE THEN NULL
                               WHEN p_quantity IS NOT NULL THEN GREATEST(0,p_quantity)
                               ELSE quantity END,
    is_unlimited        = CASE WHEN p_is_unlimited IS NOT NULL THEN p_is_unlimited
                               WHEN p_quantity IS NOT NULL THEN false  -- v15.05: صفرٌ يعني «نفد» لا «بلا حدّ»
                               ELSE is_unlimited END,
    description         = CASE WHEN p_description IS NULL THEN description ELSE NULLIF(btrim(p_description),'') END,
    category            = COALESCE(NULLIF(btrim(COALESCE(p_category,'')),''), category),
    size                = CASE WHEN p_size IS NULL THEN size ELSE NULLIF(btrim(p_size),'') END,
    gender              = COALESCE(NULLIF(btrim(COALESCE(p_gender,'')),''), gender),
    expiry_type         = COALESCE(NULLIF(btrim(COALESCE(p_expiry_type,'')),''), expiry_type),
    expiry_date         = CASE WHEN p_expiry_type IS NOT NULL THEN NULLIF(btrim(COALESCE(p_expiry_date,'')),'') ELSE expiry_date END,
    expires_in_minutes  = COALESCE(p_expires_in_minutes, expires_in_minutes),
    starts_at           = CASE WHEN p_clear_schedule IS TRUE THEN NULL
                               WHEN p_starts_at IS NOT NULL THEN p_starts_at
                               ELSE starts_at END,
    images              = CASE WHEN p_images IS NULL THEN images ELSE p_images END,
    -- v12.29: booking limits (NULL=keep, 0=clear, >0=set)
    max_per_booking         = CASE WHEN p_max_per_booking IS NULL THEN max_per_booking ELSE NULLIF(p_max_per_booking, 0) END,
    max_bookings_per_buyer  = CASE WHEN p_max_bookings_per_buyer IS NULL THEN max_bookings_per_buyer ELSE NULLIF(p_max_bookings_per_buyer, 0) END,
    rebook_cooldown_minutes = CASE WHEN p_rebook_cooldown_minutes IS NULL THEN rebook_cooldown_minutes ELSE NULLIF(p_rebook_cooldown_minutes, 0) END
  WHERE id=p_deal_id AND store_id=v_sid;

  IF p_status IS NOT NULL AND p_status <> v_d.status THEN
    IF p_status = 'active' AND NOT public.ensure_active_subscription(v_sid) THEN
      RETURN jsonb_build_object('success', false, 'error', 'no_subscription');
    END IF;
    v_now := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
    BEGIN
      IF p_status = 'active' THEN
        UPDATE deals SET
          status     = 'active',
          created_at = v_now
        WHERE id=p_deal_id AND store_id=v_sid;
      ELSE
        UPDATE deals SET status = p_status WHERE id=p_deal_id AND store_id=v_sid;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('success',false,'error','blocked','detail',SQLERRM);
    END;
  END IF;

  RETURN jsonb_build_object('success',true,'discount',v_pct,
    'reactivated', (p_status='active' AND v_d.status<>'active'));
END; $function$
;


-- ═══ FUNCTION bot_update_store_bio(p_telegram_id bigint, p_bio text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_update_store_bio(p_telegram_id bigint, p_bio text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sid text; v_res jsonb;
BEGIN
  SELECT id INTO v_sid FROM public.users
   WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id)
     AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  -- نصٌّ فارغ = محوٌ صريح (نفس ما كانت تفعله النسخة السابقة عبر NULLIF).
  v_res := public.taki_set_store_card(v_sid, coalesce(p_bio, ''), NULL);
  RETURN jsonb_build_object('success', true, 'bio', v_res->>'bio');
END $function$
;


-- ═══ FUNCTION bot_vat_mode() DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_vat_mode()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  select case when public._bot_gate_ok() then
    (select jsonb_build_object(
       'enabled', coalesce((value->>'vat_enabled')::boolean, false),
       'add_on_top', coalesce((value->>'prices_include_vat')::boolean, true) = false,
       'rate', coalesce(nullif(value->>'vat_rate','')::numeric, 15))
     from platform_settings where key = 'tax_settings')
  else null end;
$function$
;


-- ═══ FUNCTION bot_verify_booking(p_telegram_id bigint, p_barcode text, p_whatsapp_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_verify_booking(p_telegram_id bigint, p_barcode text, p_whatsapp_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_sid text; v_b bookings%ROWTYPE; v_d deals%ROWTYPE;
BEGIN
  SELECT id INTO v_sid FROM users WHERE id = public._bot_uid(p_telegram_id, p_whatsapp_id) AND user_type IN ('seller','admin') AND deleted_at IS NULL LIMIT 1;
  IF v_sid IS NULL THEN RETURN jsonb_build_object('success', false, 'error', 'not_seller'); END IF;
  SELECT * INTO v_b FROM bookings WHERE (barcode = UPPER(p_barcode) OR backup_code = UPPER(p_barcode)) AND store_id = v_sid LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'not_found'); END IF;
  SELECT * INTO v_d FROM deals WHERE id = v_b.deal_id LIMIT 1;
  RETURN jsonb_build_object('success', true, 'barcode', v_b.barcode, 'user_name', COALESCE(v_b.user_name,'—'),
    'user_phone', COALESCE(v_b.user_phone,'—'), 'deal_name', v_d.item_name, 'quantity', v_b.booked_quantity,
    'status', v_b.status, 'notes', COALESCE(v_b.notes,''), 'booked_at', to_timestamp(v_b.booked_at::double precision / 1000));
END; $function$
;


-- ═══ FUNCTION bot_verify_link_code(p_code text, p_chat_id bigint) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.bot_verify_link_code(p_code text, p_chat_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_user users%ROWTYPE;
BEGIN
  IF NOT public._bot_gate_ok() THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired'); END IF;
  SELECT * INTO v_user FROM users
  WHERE upper(telegram_link_otp) = upper(trim(p_code))
    AND telegram_link_otp_expires_at > NOW() AND deleted_at IS NULL LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'invalid_or_expired'); END IF;
  IF COALESCE(v_user.is_suspended, false) THEN RETURN jsonb_build_object('success', false, 'error', 'suspended'); END IF;
  UPDATE users SET telegram_chat_id = p_chat_id, notify_via_telegram = true,
    telegram_link_otp = NULL, telegram_link_otp_expires_at = NULL WHERE id = v_user.id;
  RETURN jsonb_build_object('success', true, 'id', v_user.id, 'name', v_user.name,
    'user_type', v_user.user_type, 'shop', v_user.shop,
    'is_super_admin', COALESCE(v_user.is_super_admin, false),
    'admin_permissions', COALESCE(v_user.admin_permissions, ARRAY[]::text[]));
END; $function$
;


-- ═══ FUNCTION broadcast_campaign(p_campaign_id text, p_force boolean) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.broadcast_campaign(p_campaign_id text, p_force boolean DEFAULT false)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.is_admin() THEN
        RAISE EXCEPTION 'Only admins can broadcast campaigns';
    END IF;
    RETURN public._broadcast_campaign_core(p_campaign_id, COALESCE(p_force, false));
END;
$function$
;


-- ═══ FUNCTION browse_bookings(p_scope text, p_state text, p_query text, p_cursor_ts text, p_cursor_id text, p_limit integer) INVOKER owner=postgres search_path=search_path=public, pg_catalog anon=YES ═══
CREATE OR REPLACE FUNCTION public.browse_bookings(p_scope text DEFAULT 'buyer'::text, p_state text DEFAULT 'all'::text, p_query text DEFAULT NULL::text, p_cursor_ts text DEFAULT NULL::text, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_me    text    := auth.uid()::text;
  v_lim   integer := LEAST(GREATEST(COALESCE(p_limit, 20), 1), 50);
  v_q     text    := public.taki_norm(p_query);
  v_where text;
  v_page  text;
  v_out   jsonb;
  v_total bigint;
  c_cap   constant integer := 5000;
BEGIN
  IF v_me IS NULL THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'has_more',false,'total',0,'total_capped',false);
  END IF;

  -- RLS على bookings يحصر الرؤية أصلاً؛ هذا يفصل دور المشتري عن دور التاجر.
  IF lower(COALESCE(p_scope,'buyer')) = 'seller' THEN
    v_where := format('b.store_id = %L', v_me);
  ELSE
    v_where := format('b.user_id = %L', v_me);
  END IF;

  IF lower(COALESCE(p_state,'all')) = 'active' THEN
    v_where := v_where || ' AND b.status NOT IN (''completed'',''cancelled'')';
  ELSIF lower(COALESCE(p_state,'all')) = 'past' THEN
    v_where := v_where || ' AND b.status IN (''completed'',''cancelled'')';
  END IF;

  -- بحث مُطبَّع عربياً (نفس محرك v13.24): الباركود/اسم المنتج/المتجر/المشتري
  IF v_q IS NOT NULL THEN
    v_where := v_where || format(
      ' AND (b.search_norm LIKE %1$L'
      '      OR EXISTS (SELECT 1 FROM public.deals dd WHERE dd.id = b.deal_id'
      '                 AND dd.store_id = b.store_id AND dd.name_norm LIKE %1$L))' /* v13.31 */,
      '%' || v_q || '%');
  END IF;

  EXECUTE format(
    'SELECT count(*)::bigint FROM (SELECT 1 FROM public.bookings b WHERE %s LIMIT %s) z',
    v_where, c_cap + 1) INTO v_total;

  v_page := v_where;
  IF p_cursor_ts IS NOT NULL AND p_cursor_id IS NOT NULL THEN
    v_page := v_page || format(
      ' AND (b.created_at < (%1$L)::timestamptz'
      '   OR (b.created_at = (%1$L)::timestamptz AND b.barcode < %2$L))',
      p_cursor_ts, p_cursor_id);
  END IF;

  EXECUTE format($q$
    WITH page AS (
      SELECT b.* FROM public.bookings b
      WHERE %1$s
      ORDER BY b.created_at DESC, b.barcode DESC
      LIMIT %2$s
    ), ranked AS (
      SELECT p.*, row_number() OVER (ORDER BY p.created_at DESC, p.barcode DESC) AS _rn
      FROM page p
    )
    SELECT jsonb_build_object(
      'rows', COALESCE((
        SELECT jsonb_agg(
          to_jsonb(r) - '_rn'
          || jsonb_build_object('deal', COALESCE(
               (SELECT to_jsonb(d) - 'search_vec' - 'name_norm' - 'loc_keys'
                  FROM public.deals d WHERE d.id = r.deal_id), 'null'::jsonb))
          -- v14.24 — حالة الاسترداد داخل الصفّ. بدونها تُطلق كل بطاقة طلبٍ
          -- مدفوع نداءً مستقلّاً عند الظهور: عشرون طلباً = عشرون نداءً،
          -- وثلاث صفحات = ستّون — أغلبها يعود فارغاً.
          || jsonb_build_object('refund', (
               SELECT jsonb_build_object(
                 'barcode', rf.barcode, 'status', rf.status, 'amount', rf.amount,
                 'opened_by', rf.opened_by, 'reason', rf.reason,
                 'requested_at', rf.requested_at, 'merchant_note', rf.merchant_note,
                 'decided_at', rf.decided_at, 'refunded_at', rf.refunded_at,
                 'refund_amount', rf.refund_amount, 'refund_ref', rf.refund_ref,
                 'refund_method', rf.refund_method, 'credit_note_no', rf.credit_note_no)
                 FROM public.booking_refunds rf WHERE rf.barcode = r.barcode))
          ORDER BY r._rn)
        FROM ranked r WHERE r._rn <= %3$s), '[]'::jsonb),
      'has_more', (SELECT count(*) FROM page) > %3$s,
      'next_ts',  (SELECT r.created_at FROM ranked r WHERE r._rn = %3$s),
      'next_id',  (SELECT r.barcode    FROM ranked r WHERE r._rn = %3$s))
  $q$, v_page, v_lim + 1, v_lim) INTO v_out;

  RETURN COALESCE(v_out, jsonb_build_object('rows','[]'::jsonb,'has_more',false))
       || jsonb_build_object('total', LEAST(v_total, c_cap), 'total_capped', v_total > c_cap);
END $function$
;


-- ═══ FUNCTION browse_deal_ratings(p_deal_id text, p_cursor_at timestamp with time zone, p_cursor_id text, p_limit integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.browse_deal_ratings(p_deal_id text, p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_lim  int := GREATEST(1, LEAST(50, COALESCE(p_limit, 20)));
  v_me   text := (SELECT auth.uid())::text;
  v_rows jsonb;
  v_more boolean := false;
BEGIN
  IF p_deal_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'DEAL_REQUIRED');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC, r.id DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT rt.id, rt.deal_id, rt.store_id, rt.user_name, rt.score, rt.comment,
           rt.created_at, rt.reply, rt.replied_at, rt.like_count,
           (v_me IS NOT NULL AND rt.user_id = v_me)                            AS is_mine,
           (v_me IS NOT NULL AND v_me = ANY(COALESCE(rt.liked_by, '{}'::text[]))) AS liked_by_me
    FROM public.ratings rt
    WHERE rt.deal_id = p_deal_id
      AND rt.deleted_at IS NULL
      AND (
        p_cursor_at IS NULL
        OR rt.created_at < p_cursor_at
        OR (rt.created_at = p_cursor_at AND rt.id < p_cursor_id)
      )
    ORDER BY rt.created_at DESC, rt.id DESC
    LIMIT v_lim + 1
  ) r;

  IF jsonb_array_length(v_rows) > v_lim THEN
    v_more := true;
    v_rows := (SELECT jsonb_agg(e) FROM (
                 SELECT e FROM jsonb_array_elements(v_rows) e LIMIT v_lim) s);
  END IF;

  RETURN jsonb_build_object('ok', true, 'rows', COALESCE(v_rows, '[]'::jsonb), 'has_more', v_more);
END
$function$
;


-- ═══ FUNCTION browse_deals(p_query text, p_category text, p_gender text, p_region text, p_city text, p_mall text, p_store_id text, p_season_id text, p_sort text, p_mode text, p_open_now boolean, p_verified boolean, p_cursor_key double precision, p_cursor_id text, p_limit integer, p_blocked text[], p_exclude_ids text[]) INVOKER owner=postgres search_path=search_path=public, pg_catalog anon=YES ═══
CREATE OR REPLACE FUNCTION public.browse_deals(p_query text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_gender text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_mall text DEFAULT NULL::text, p_store_id text DEFAULT NULL::text, p_season_id text DEFAULT NULL::text, p_sort text DEFAULT 'new'::text, p_mode text DEFAULT 'live'::text, p_open_now boolean DEFAULT false, p_verified boolean DEFAULT false, p_cursor_key double precision DEFAULT NULL::double precision, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 30, p_blocked text[] DEFAULT NULL::text[], p_exclude_ids text[] DEFAULT NULL::text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_now bigint := (EXTRACT(epoch FROM now()) * 1000)::bigint;
  v_lim integer := LEAST(GREATEST(COALESCE(p_limit, 30), 1), 60);
  v_q text := public.taki_norm(p_query);
  v_ts tsquery; v_long boolean := false;
  v_sort text := lower(COALESCE(p_sort, 'new'));
  v_expr text; v_cast text; v_desc boolean; v_dir text; v_cmp text;
  v_where text; v_page_w text; v_closed text[]; v_out jsonb; v_total bigint;
  c_cap constant integer := 5000;
BEGIN
  IF v_q IS NOT NULL THEN
    SELECT to_tsquery('simple', string_agg(quote_literal(t) || ':*', ' & ')) INTO v_ts
      FROM unnest(string_to_array(v_q, ' ')) AS t WHERE t <> '';
    v_long := length(v_q) >= 3;
  END IF;

  IF v_ts IS NOT NULL AND v_sort IN ('best', 'relevance') THEN
    v_expr := format('(ts_rank_cd(d.search_vec, %L::tsquery) * 8 + word_similarity(%L, d.name_norm) * 4'
                     ' + CASE WHEN d.name_norm LIKE %L THEN 3 ELSE 0 END'
                     ' + CASE WHEN d.name_norm LIKE %L THEN 2 ELSE 0 END)',
                     v_ts::text, v_q, v_q || '%', '%' || v_q || '%');
    v_cast := 'double precision'; v_desc := true;
  ELSIF v_sort = 'price' THEN
    v_expr := 'd.discounted_price'; v_cast := 'numeric'; v_desc := false;
  ELSIF v_sort = 'discount' THEN
    v_expr := 'd.discount_percentage'; v_cast := 'integer'; v_desc := true;
  ELSIF v_sort = 'reliability' THEN
    v_expr := 'd.reliability_score'; v_cast := 'integer'; v_desc := true;
  ELSIF v_sort = 'soon' THEN
    v_expr := 'COALESCE(d.starts_at, 0)'; v_cast := 'bigint'; v_desc := false;
  ELSE
    v_expr := 'd.created_at'; v_cast := 'bigint'; v_desc := true;
  END IF;
  v_dir := CASE WHEN v_desc THEN 'DESC' ELSE 'ASC' END;
  v_cmp := CASE WHEN v_desc THEN '<' ELSE '>' END;

  v_where := 'd.status = ''active'''
          || ' AND NOT COALESCE(d.sold_out,false) AND (d.is_unlimited OR COALESCE(d.quantity,0) > 0 OR COALESCE(d.initial_quantity,0) <= 0)';
  -- v14.32 — عروض متجرٍ موقوف لا تُعرض. كان الإيقاف يُخفي صفحة المتجر من
  -- الدليل وحدها، بينما عروضه تبقى في الرئيسية وفي «القريب مني» ويفتحها
  -- المشترون ويحجزون — أي أن «إيقاف التاجر» لم يكن يوقف بيعه.
  -- الفلترة هنا لا في صفوف العروض: فكّ الإيقاف يُعيدها كما كانت بلا أي إصلاح.
  v_where := v_where || ' AND NOT EXISTS (SELECT 1 FROM public.users su'
                     || ' WHERE su.id = d.store_id AND (su.is_suspended OR su.deleted_at IS NOT NULL))';


  IF lower(COALESCE(p_mode,'live')) = 'coming_soon' THEN
    v_where := v_where || format(' AND d.starts_at IS NOT NULL AND d.starts_at > %s AND d.starts_at <= %s', v_now, v_now + 604800000);
  ELSE
    v_where := v_where || format(' AND COALESCE(d.starts_at, 0) <= %s'
      ' AND %s <= (GREATEST(COALESCE(d.starts_at,0), d.created_at)::bigint'
      '            + (CASE WHEN COALESCE(d.expires_in_minutes,0) = 0 THEN 120 ELSE d.expires_in_minutes END)::bigint * 60000)', v_now, v_now);
  END IF;

  IF NULLIF(p_category,'') IS NOT NULL AND p_category <> 'all' THEN
    v_where := v_where || format(' AND (d.category = %L OR d.category = ''all'')', p_category); END IF;
  IF NULLIF(p_gender,'') IS NOT NULL AND p_gender <> 'all' THEN
    v_where := v_where || format(' AND (d.gender = %L OR d.gender = ''all'')', p_gender); END IF;
  IF NULLIF(p_store_id,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.store_id = %L', p_store_id); END IF;
  IF NULLIF(p_season_id,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.season_id = %L', p_season_id); END IF;

  IF NULLIF(p_mall,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.loc_keys @> ARRAY[%L]::text[]', 'm:' || p_mall);
  ELSIF NULLIF(p_city,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.loc_keys @> ARRAY[%L]::text[]', 'c:' || p_city);
  ELSIF NULLIF(p_region,'') IS NOT NULL THEN
    v_where := v_where || format(' AND d.loc_keys @> ARRAY[%L]::text[]', 'r:' || p_region);
  END IF;

  -- v13.25 — الحظر والاستثناء (كانا ترشيحاً محلياً على النافذة المُحمّلة)
  IF p_blocked IS NOT NULL AND COALESCE(array_length(p_blocked,1),0) > 0 THEN
    v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', p_blocked);
  END IF;
  IF p_exclude_ids IS NOT NULL AND COALESCE(array_length(p_exclude_ids,1),0) > 0 THEN
    v_where := v_where || format(' AND NOT (d.id = ANY(%L::text[]))', p_exclude_ids);
  END IF;

  IF COALESCE(p_open_now,false) THEN
    v_closed := taki_internal.closed_store_ids();
    IF COALESCE(array_length(v_closed,1),0) > 0 THEN
      v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', v_closed);
    END IF;
  END IF;

  IF COALESCE(p_verified,false) THEN
    v_where := v_where || ' AND (d.auth_real_count + d.auth_fake_count) > 0 AND d.auth_real_count >= d.auth_fake_count';
  END IF;

  IF v_ts IS NOT NULL THEN
    IF v_long THEN
      v_where := v_where || format(' AND (d.search_vec @@ %L::tsquery OR d.name_norm LIKE %L OR %L <%% d.name_norm)', v_ts::text, '%' || v_q || '%', v_q);
    ELSE
      v_where := v_where || format(' AND d.search_vec @@ %L::tsquery', v_ts::text);
    END IF;
  END IF;

  EXECUTE format('SELECT count(*)::bigint FROM (SELECT 1 FROM public.deals d WHERE %s LIMIT %s) z', v_where, c_cap + 1) INTO v_total;

  v_page_w := v_where;
  IF p_cursor_id IS NOT NULL AND p_cursor_key IS NOT NULL THEN
    v_page_w := v_page_w || format(' AND ((%1$s) %2$s (%3$L)::%4$s OR ((%1$s) = (%3$L)::%4$s AND d.id %2$s %5$L))',
                                   v_expr, v_cmp, p_cursor_key::text, v_cast, p_cursor_id);
  END IF;

  EXECUTE format($q$
    WITH page AS (
      SELECT d.*, (%1$s)::double precision AS _k FROM public.deals d
      WHERE %2$s ORDER BY %1$s %3$s, d.id %3$s LIMIT %4$s
    ), ranked AS (
      SELECT p.*, row_number() OVER (ORDER BY p._k %3$s, p.id %3$s) AS _rn FROM page p
    )
    SELECT jsonb_build_object(
      'rows', COALESCE((SELECT jsonb_agg(to_jsonb(r) - '_k' - '_rn' - 'search_vec' - 'name_norm' - 'loc_keys' ORDER BY r._rn)
                        FROM ranked r WHERE r._rn <= %5$s), '[]'::jsonb),
      'has_more', (SELECT count(*) FROM page) > %5$s,
      'next_key', (SELECT r._k FROM ranked r WHERE r._rn = %5$s),
      'next_id',  (SELECT r.id FROM ranked r WHERE r._rn = %5$s))
  $q$, v_expr, v_page_w, v_dir, v_lim + 1, v_lim) INTO v_out;

  RETURN COALESCE(v_out, jsonb_build_object('rows','[]'::jsonb,'has_more',false))
       || jsonb_build_object('total', LEAST(v_total, c_cap), 'total_capped', v_total > c_cap,
                             'limit', v_lim, 'sort', v_sort);
END $function$
;


-- ═══ FUNCTION browse_nearby(p_lat double precision, p_lng double precision, p_radius_km double precision, p_query text, p_category text, p_region text, p_city text, p_location_id text, p_loc_type text, p_open_now boolean, p_blocked text[], p_limit integer, p_cursor_dist double precision, p_cursor_key text) INVOKER owner=postgres search_path=search_path=public, pg_catalog anon=YES ═══
CREATE OR REPLACE FUNCTION public.browse_nearby(p_lat double precision, p_lng double precision, p_radius_km double precision DEFAULT 0, p_query text DEFAULT NULL::text, p_category text DEFAULT NULL::text, p_region text DEFAULT NULL::text, p_city text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_loc_type text DEFAULT NULL::text, p_open_now boolean DEFAULT false, p_blocked text[] DEFAULT NULL::text[], p_limit integer DEFAULT 30, p_cursor_dist double precision DEFAULT NULL::double precision, p_cursor_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_now   bigint  := (EXTRACT(epoch FROM now()) * 1000)::bigint;
  v_lim   integer := LEAST(GREATEST(COALESCE(p_limit, 30), 1), 60);
  v_q     text    := public.taki_norm(p_query);
  v_ts    tsquery;
  v_long  boolean := false;
  v_where text;
  v_page  text;
  v_dlat  double precision;
  v_dlng  double precision;
  v_closed text[];
  v_out   jsonb;
  v_total bigint;
  c_cap   constant integer := 5000;
BEGIN
  IF p_lat IS NULL OR p_lng IS NULL THEN
    RETURN jsonb_build_object('rows','[]'::jsonb,'has_more',false,'total',0,'total_capped',false);
  END IF;

  IF v_q IS NOT NULL THEN
    SELECT to_tsquery('simple', string_agg(quote_literal(t) || ':*', ' & ')) INTO v_ts
      FROM unnest(string_to_array(v_q, ' ')) AS t WHERE t <> '';
    v_long := length(v_q) >= 3;
  END IF;

  -- دورة حياة العرض — نفس قواعد بقية المنصة
  v_where := 'd.status = ''active'''
          || ' AND NOT COALESCE(d.sold_out,false) AND (d.is_unlimited OR COALESCE(b.quantity, d.quantity, 0) > 0 OR COALESCE(d.initial_quantity,0) <= 0)'
          || format(' AND COALESCE(d.starts_at, 0) <= %s', v_now)
          || format(' AND %s <= (GREATEST(COALESCE(d.starts_at,0), d.created_at)::bigint'
                    ' + (CASE WHEN COALESCE(d.expires_in_minutes,0) = 0 THEN 120'
                    '         ELSE d.expires_in_minutes END)::bigint * 60000)', v_now)
          || ' AND b.lat IS NOT NULL AND b.lng IS NOT NULL';
  -- v14.32 — عروض متجرٍ موقوف لا تُعرض. كان الإيقاف يُخفي صفحة المتجر من
  -- الدليل وحدها، بينما عروضه تبقى في الرئيسية وفي «القريب مني» ويفتحها
  -- المشترون ويحجزون — أي أن «إيقاف التاجر» لم يكن يوقف بيعه.
  -- الفلترة هنا لا في صفوف العروض: فكّ الإيقاف يُعيدها كما كانت بلا أي إصلاح.
  v_where := v_where || ' AND NOT EXISTS (SELECT 1 FROM public.users su'
                     || ' WHERE su.id = d.store_id AND (su.is_suspended OR su.deleted_at IS NOT NULL))';


  -- المرشّح الصندوقي: ضربة فهرس قبل أي حساب مثلثات
  IF COALESCE(p_radius_km, 0) > 0 THEN
    v_dlat := p_radius_km / 111.045;
    v_dlng := p_radius_km / (111.045 * GREATEST(cos(radians(p_lat)), 0.01));
    v_where := v_where || format(
      ' AND b.lat BETWEEN %s AND %s AND b.lng BETWEEN %s AND %s',
      p_lat - v_dlat, p_lat + v_dlat, p_lng - v_dlng, p_lng + v_dlng);
    v_where := v_where || format(
      ' AND public.taki_haversine_km(%s, %s, b.lat, b.lng) <= %s', p_lat, p_lng, p_radius_km);
  END IF;

  IF NULLIF(p_category,'') IS NOT NULL AND p_category <> 'all' THEN
    v_where := v_where || format(' AND (d.category = %L OR d.category = ''all'')', p_category); END IF;
  IF NULLIF(p_region,'') IS NOT NULL THEN
    v_where := v_where || format(' AND b.region = %L', p_region); END IF;
  IF NULLIF(p_city,'') IS NOT NULL THEN
    v_where := v_where || format(' AND b.city = %L', p_city); END IF;
  IF NULLIF(p_location_id,'') IS NOT NULL THEN
    v_where := v_where || format(' AND b.location_id = %L', p_location_id); END IF;
  IF NULLIF(p_loc_type,'') IS NOT NULL THEN
    v_where := v_where || format(
      ' AND EXISTS (SELECT 1 FROM public.locations lt WHERE lt.id = b.location_id AND lt.type = %L)', p_loc_type); END IF;
  IF p_blocked IS NOT NULL AND COALESCE(array_length(p_blocked,1),0) > 0 THEN
    v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', p_blocked); END IF;

  IF COALESCE(p_open_now,false) THEN
    v_closed := taki_internal.closed_store_ids();
    IF COALESCE(array_length(v_closed,1),0) > 0 THEN
      v_where := v_where || format(' AND NOT (d.store_id = ANY(%L::text[]))', v_closed);
    END IF;
  END IF;

  -- البحث: نفس الطبقات الثلاث + اسم الفرع (يبحث المستخدم باسم المول أيضاً)
  IF v_ts IS NOT NULL THEN
    IF v_long THEN
      v_where := v_where || format(
        ' AND (d.search_vec @@ %L::tsquery OR d.name_norm LIKE %L OR %L <%% d.name_norm'
        '      OR public.taki_norm(b.branch_name) LIKE %L)',
        v_ts::text, '%' || v_q || '%', v_q, '%' || v_q || '%');
    ELSE
      v_where := v_where || format(
        ' AND (d.search_vec @@ %L::tsquery OR public.taki_norm(b.branch_name) LIKE %L)',
        v_ts::text, '%' || v_q || '%');
    END IF;
  END IF;

  EXECUTE format(
    'SELECT count(*)::bigint FROM (SELECT 1 FROM public.deal_branches b'
    ' JOIN public.deals d ON d.id = b.deal_id WHERE %s LIMIT %s) z', v_where, c_cap + 1) INTO v_total;

  v_page := v_where;
  IF p_cursor_dist IS NOT NULL AND p_cursor_key IS NOT NULL THEN
    v_page := v_page || format(
      ' AND ((public.taki_haversine_km(%1$s, %2$s, b.lat, b.lng) > (%3$L)::double precision)'
      '   OR (public.taki_haversine_km(%1$s, %2$s, b.lat, b.lng) = (%3$L)::double precision'
      '       AND (b.deal_id || ''__'' || b.branch_id) > %4$L))',
      p_lat, p_lng, p_cursor_dist::text, p_cursor_key);
  END IF;

  EXECUTE format($q$
    WITH page AS (
      SELECT d, b, public.taki_haversine_km(%1$s, %2$s, b.lat, b.lng) AS _dist,
             (b.deal_id || '__' || b.branch_id) AS _key
      FROM public.deal_branches b
      JOIN public.deals d ON d.id = b.deal_id
      WHERE %3$s
      ORDER BY _dist ASC, _key ASC
      LIMIT %4$s
    ), ranked AS (
      SELECT p.*, row_number() OVER (ORDER BY p._dist ASC, p._key ASC) AS _rn FROM page p
    )
    SELECT jsonb_build_object(
      'rows', COALESCE((
        SELECT jsonb_agg(
          (to_jsonb(r.d) - 'search_vec' - 'name_norm' - 'loc_keys')
          || jsonb_build_object(
               'distance', r._dist,
               'lat',      (r.b).lat,
               'lng',      (r.b).lng,
               '_key',     r._key,
               '_bId',     (r.b).branch_id,
               '_bLocId',  (r.b).location_id,
               '_bName',   (r.b).branch_name,
               '_bRegion', (r.b).region,
               '_bCity',   (r.b).city)
          || CASE WHEN (r.b).quantity IS NOT NULL
                  THEN jsonb_build_object('quantity', (r.b).quantity)
                  ELSE '{}'::jsonb END
          ORDER BY r._rn)
        FROM ranked r WHERE r._rn <= %5$s), '[]'::jsonb),
      'has_more',  (SELECT count(*) FROM page) > %5$s,
      'next_dist', (SELECT r._dist FROM ranked r WHERE r._rn = %5$s),
      'next_key',  (SELECT r._key  FROM ranked r WHERE r._rn = %5$s))
  $q$, p_lat, p_lng, v_page, v_lim + 1, v_lim) INTO v_out;

  RETURN COALESCE(v_out, jsonb_build_object('rows','[]'::jsonb,'has_more',false))
       || jsonb_build_object('total', LEAST(v_total, c_cap), 'total_capped', v_total > c_cap);
END $function$
;


-- ═══ FUNCTION browse_notifications(p_cursor_at timestamp with time zone, p_cursor_id text, p_limit integer, p_q text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.browse_notifications(p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 40, p_q text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_lim  int  := GREATEST(1, LEAST(100, COALESCE(p_limit, 40)));
  v_q    text := NULLIF(btrim(COALESCE(p_q, '')), '');
  v_pat  text;
  v_rows jsonb;
  v_more boolean := false;
  v_unread int;
  v_total  int;
  v_match  int;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED');
  END IF;

  -- النمط يُبنى مرّة واحدة بعد التطبيع، والحروف الخاصّة تُهرَّب فلا تُفسّر.
  IF v_q IS NOT NULL THEN
    v_pat := '%' || replace(replace(replace(public.taki_norm(v_q), '\', '\\'), '%', '\%'), '_', '\_') || '%';
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC, r.id DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    SELECT n.*
    FROM public.notifications n
    WHERE n.user_id = v_uid
      AND (
        p_cursor_at IS NULL
        OR n.created_at < p_cursor_at
        OR (n.created_at = p_cursor_at AND n.id < p_cursor_id)
      )
      AND (
        v_pat IS NULL
        OR public.taki_norm(n.title_ar) LIKE v_pat
        OR public.taki_norm(n.title_en) LIKE v_pat
        OR public.taki_norm(n.body_ar)  LIKE v_pat
        OR public.taki_norm(n.body_en)  LIKE v_pat
      )
    ORDER BY n.created_at DESC, n.id DESC
    LIMIT v_lim + 1               -- صفٌّ زائد: به نعرف «هل بعدها المزيد» بلا عدٍّ ثانٍ
  ) r;

  IF jsonb_array_length(v_rows) > v_lim THEN
    v_more := true;
    v_rows := (SELECT jsonb_agg(e) FROM (
                 SELECT e FROM jsonb_array_elements(v_rows) e LIMIT v_lim) s);
  END IF;

  -- العدّان من الجدول كلّه لا من الصفحة — وهذا بيت القصيد.
  SELECT count(*) FILTER (WHERE NOT is_read), count(*)
    INTO v_unread, v_total
  FROM public.notifications WHERE user_id = v_uid;

  -- وعند البحث: عددُ المطابق كلِّه (لا المعروض) حتى لا يكذب العدّاد ثانية.
  IF v_pat IS NULL THEN
    v_match := v_total;
  ELSE
    SELECT count(*) INTO v_match
    FROM public.notifications n
    WHERE n.user_id = v_uid
      AND ( public.taki_norm(n.title_ar) LIKE v_pat
         OR public.taki_norm(n.title_en) LIKE v_pat
         OR public.taki_norm(n.body_ar)  LIKE v_pat
         OR public.taki_norm(n.body_en)  LIKE v_pat );
  END IF;

  RETURN jsonb_build_object(
    'ok', true, 'rows', COALESCE(v_rows, '[]'::jsonb), 'has_more', v_more,
    'unread_total', v_unread, 'total', v_total, 'matched', v_match);
END $function$
;


-- ═══ FUNCTION browse_store_ratings(p_store_id text, p_cursor_at timestamp with time zone, p_cursor_id text, p_limit integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.browse_store_ratings(p_store_id text, p_cursor_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_cursor_id text DEFAULT NULL::text, p_limit integer DEFAULT 10)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_lim int := GREATEST(1, LEAST(50, COALESCE(p_limit, 10)));
  v_me  text := (SELECT auth.uid())::text;
  v_rows jsonb; v_more boolean := false; v_total int;
BEGIN
  IF p_store_id IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'STORE_REQUIRED');
  END IF;

  SELECT COALESCE(jsonb_agg(to_jsonb(r) ORDER BY r.created_at DESC, r.id DESC), '[]'::jsonb)
    INTO v_rows
  FROM (
    -- v15.79 — أعمدةٌ مُسمّاةٌ لا `rt.*`: أيُّ عمودٍ جديدٍ على `ratings`
    -- لا يُنشر من تلقاء نفسه بعد اليوم.
    SELECT rt.id, rt.deal_id, rt.store_id, rt.user_name, rt.score, rt.comment,
           rt.created_at, rt.reply, rt.replied_at, rt.like_count,
           (v_me IS NOT NULL AND rt.user_id = v_me)                            AS is_mine,
           (v_me IS NOT NULL AND v_me = ANY(COALESCE(rt.liked_by, '{}'::text[]))) AS liked_by_me,
           d.item_name
    FROM public.ratings rt
    JOIN public.deals d ON d.id = rt.deal_id
    WHERE d.store_id = p_store_id
      AND rt.deleted_at IS NULL
      AND (p_cursor_at IS NULL
           OR rt.created_at < p_cursor_at
           OR (rt.created_at = p_cursor_at AND rt.id < p_cursor_id))
    ORDER BY rt.created_at DESC, rt.id DESC
    LIMIT v_lim + 1
  ) r;

  IF jsonb_array_length(v_rows) > v_lim THEN
    v_more := true;
    v_rows := (SELECT jsonb_agg(e) FROM (SELECT e FROM jsonb_array_elements(v_rows) e LIMIT v_lim) s);
  END IF;

  SELECT count(*) INTO v_total
  FROM public.ratings rt JOIN public.deals d ON d.id = rt.deal_id
  WHERE d.store_id = p_store_id AND rt.deleted_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'rows', COALESCE(v_rows,'[]'::jsonb),
                            'has_more', v_more, 'total', v_total);
END
$function$
;


-- ═══ FUNCTION buyer_confirm_receipt(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.buyer_confirm_receipt(p_barcode text)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_b    public.bookings%ROWTYPE;
  v_left integer;
  v_anchor bigint;
  v_out  public.bookings;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND OR v_b.user_id IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'لم يتم العثور على الطلب' USING ERRCODE = 'P0001', HINT = 'P0002';
  END IF;
  -- v15.41 — الزرُّ لكلّ طلبٍ حيّ، والتوصيلُ وحده يشترط انطلاقَ المندوب.
  IF v_b.status NOT IN ('pending','acknowledged') THEN
    RAISE EXCEPTION 'الطلب مغلق بالفعل' USING ERRCODE = 'P0001';
  END IF;

  -- 🔴 v15.49 — «انطلق» لا «أين هو الآن». كانت تقرأ `status` فكان المنظّفُ
  --    يسحب الزرَّ من يد مشترٍ استلم بضاعته فعلاً بعد ساعةٍ من صمت الهاتف.
  IF COALESCE(v_b.fulfillment,'pickup') = 'delivery'
     AND NOT public.taki_delivery_dispatched(v_b.barcode) THEN
    RAISE EXCEPTION 'لم يبدأ التاجر التوصيل بعد' USING ERRCODE = 'P0001';
  END IF;

  -- 🔴 v15.42 — المهلةُ قبل أن يُسمح بالختم الذاتيّ.
  -- 🪤 ولا تُصاغ الدقائقُ نصّاً هنا: العربيّةُ تحتاج خمسَ صيغٍ للمعدود، ومحرّكُها
  --    في ثلاثة مواضع مقيسة (`arPlural`) — ورابعٌ في SQL يعني انحرافاً. فالرسالةُ
  --    تخلو من المعدود، والثواني المتبقّية في `DETAIL` تصوغها الواجهة.
  -- 🔴 v15.44 (أمرُ ناصر) — الساعةُ تبدأ من **تأكيد التاجر**؛ وإن لم يؤكّد
  --    فتحةٌ احتياطيّة في آخر المهلة كي لا تبقى المشترية بلا مخرج (١٤٪ من
  --    الطلبات المكتملة لم تُؤكَّد قطّ — قِيس). والرمزُ يفرّق **سببَ** الانتظار
  --    فتقول الشاشةُ الصدق: أتنتظرُ شخصاً أم وقتاً.
  v_anchor := public.taki_self_close_opens_at(v_b);
  v_left := ceil((v_anchor - (EXTRACT(EPOCH FROM NOW())*1000)::bigint) / 1000.0);
  IF v_left > 0 AND v_b.acknowledged_at IS NULL AND v_b.status <> 'acknowledged' THEN
    RAISE EXCEPTION 'لم يؤكّد التاجر استلام طلبك بعد'
      USING ERRCODE = 'P0001', HINT = 'P0029', DETAIL = v_left::text;
  END IF;
  IF v_left > 0 THEN
    RAISE EXCEPTION 'لم تمضِ المهلة بعد استلام المتجر للطلب'
      USING ERRCODE = 'P0001', HINT = 'P0028', DETAIL = v_left::text;
  END IF;

  UPDATE public.bookings
     SET status = 'completed', completed_by = 'buyer'
   WHERE barcode = v_b.barcode
     AND status IN ('pending','acknowledged')
  RETURNING * INTO v_out;

  IF v_out.barcode IS NULL THEN
    RAISE EXCEPTION 'الطلب مغلق بالفعل' USING ERRCODE = 'P0001';
  END IF;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
  VALUES (v_out.store_id,
          '✅ أكّد المشتري الاستلام', '✅ Buyer confirmed receipt',
          'أكّد المشتري استلام الطلب ' || v_out.barcode,
          'The buyer confirmed receiving order ' || v_out.barcode,
          'booking',
          jsonb_build_object('audience','seller','event','buyer_confirmed',
                             'barcode', v_out.barcode, 'dealId', v_out.deal_id),
          NOW());

  RETURN v_out;
END;
$function$
;


-- ═══ FUNCTION cancel_booking(p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.cancel_booking(p_barcode text)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    caller  text := (SELECT auth.uid()::text);
    updated public.bookings;
    v_b     public.bookings%ROWTYPE;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
    END IF;

    -- v14.18 — الطلب المدفوع إلكترونياً لا يُلغى بضغطة واحدة. مالٌ خرج من حساب
    -- المشتري ووصل حساب التاجر مباشرة (تاكي لا تمرّ بها الأموال أصلاً)، فإلغاءٌ
    -- صامت يُعيد الكمّية للتاجر ويترك المشتري بلا بضاعة ولا مال ولا أثر مكتوب.
    -- المسار الصحيح: طلب إلغاء واسترداد يُسجَّل ويُبلَّغ ويُثبَّت بمرجع ومبلغ.
    SELECT * INTO v_b FROM public.bookings WHERE barcode = p_barcode;
    IF FOUND AND v_b.paid_at IS NOT NULL
       AND (caller = v_b.store_id OR caller = v_b.user_id) THEN
        RAISE EXCEPTION 'TAKI_PAID_NEEDS_REFUND' USING ERRCODE = 'P0001', HINT = 'P0014';
    END IF;

    UPDATE public.bookings
    SET status = 'cancelled',
        cancelled_by = CASE WHEN caller = store_id THEN 'seller' ELSE 'buyer' END
    WHERE barcode = p_barcode
      AND status IN ('pending', 'acknowledged')
      AND (caller = store_id OR caller = user_id)
    RETURNING * INTO updated;

    IF updated.barcode IS NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.bookings
            WHERE barcode = p_barcode
              AND (caller = store_id OR caller = user_id)
        ) THEN
            RAISE EXCEPTION 'الحجز مغلق ولا يمكن إلغاؤه' USING ERRCODE = 'P0001';
        ELSE
            RAISE EXCEPTION 'لم يتم العثور على الحجز' USING ERRCODE = 'P0001', HINT = 'P0002';
        END IF;
    END IF;

    RETURN updated;
END;
$function$
;


-- ═══ FUNCTION cancel_subscription(p_immediate boolean) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.cancel_subscription(p_immediate boolean DEFAULT false)
 RETURNS merchant_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller TEXT := auth.uid()::text;
    v_row merchant_subscriptions;
BEGIN
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    SELECT * INTO v_row
    FROM merchant_subscriptions
    WHERE merchant_id = v_caller
    FOR UPDATE;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No subscription found for merchant %', v_caller;
    END IF;

    IF v_row.status = 'cancelled' THEN
        RETURN v_row; -- idempotent
    END IF;

    IF p_immediate THEN
        UPDATE merchant_subscriptions
        SET status = 'cancelled',
            cancel_at_period_end = FALSE,
            current_period_end = NOW(),
            updated_at = NOW()
        WHERE merchant_id = v_caller
        RETURNING * INTO v_row;
    ELSE
        UPDATE merchant_subscriptions
        SET cancel_at_period_end = TRUE,
            updated_at = NOW()
        WHERE merchant_id = v_caller
        RETURNING * INTO v_row;
    END IF;

    RETURN v_row;
END;
$function$
;


-- ═══ FUNCTION cancel_unverified_signup(target_email text, target_id uuid) DEFINER owner=postgres search_path=search_path=public, auth anon=YES ═══
CREATE OR REPLACE FUNCTION public.cancel_unverified_signup(target_email text, target_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
  v_ip text;
BEGIN
  IF target_id IS NULL OR target_email IS NULL OR btrim(target_email) = '' THEN
    RAISE EXCEPTION 'target_email and target_id are both required';
  END IF;

  v_ip := public._taki_client_ip();
  IF v_ip IS NOT NULL THEN
    PERFORM public.taki_rate_check('cus1h:' || v_ip, 20, 3600,
      '⏳ محاولات كثيرة — أعد المحاولة بعد قليل.');
  END IF;

  DELETE FROM auth.users
   WHERE id = target_id
     AND email = target_email
     AND email_confirmed_at IS NULL
     AND created_at < NOW() - INTERVAL '10 minutes';
END;
$function$
;


-- ═══ FUNCTION cast_authenticity_vote(p_deal_id text, p_is_real boolean) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.cast_authenticity_vote(p_deal_id text, p_is_real boolean)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_store text;
BEGIN
    v_uid := auth.uid()::text;
    IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
    SELECT store_id INTO v_store FROM deals WHERE id = p_deal_id;
    IF v_store IS NULL THEN RAISE EXCEPTION 'deal not found'; END IF;
    IF NOT EXISTS (SELECT 1 FROM bookings WHERE deal_id = p_deal_id AND user_id = v_uid AND status = 'completed') THEN
        RAISE EXCEPTION 'purchase required';
    END IF;
    -- v12.29: the vote is editable — a re-vote UPDATES the previous one
    -- (merchants can no longer rely on a buyer's first vote being frozen).
    INSERT INTO deal_authenticity_votes (deal_id, store_id, user_id, is_real)
    VALUES (p_deal_id, v_store, v_uid, p_is_real)
    ON CONFLICT (deal_id, user_id) DO UPDATE SET is_real = EXCLUDED.is_real;
END;
$function$
;


-- ═══ FUNCTION cleanup_old_activity() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.cleanup_old_activity()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    DELETE FROM activity_log WHERE created_at < NOW() - INTERVAL '90 days';
    -- v14.23 — كانت ٧ أيام والخصوصية تقول ٣٠ تحت «المدد المطبَّقة فعلياً».
    DELETE FROM user_sessions WHERE last_seen_at < NOW() - INTERVAL '30 days';
    -- وجلسات المصادقة نفسها لم يكن يحذفها شيء إطلاقاً.
    BEGIN
      DELETE FROM auth.sessions       WHERE COALESCE(updated_at, created_at) < NOW() - INTERVAL '30 days';
      DELETE FROM auth.refresh_tokens WHERE COALESCE(updated_at, created_at) < NOW() - INTERVAL '30 days';
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'auth session prune skipped: %', SQLERRM;
    END;
END
$function$
;


-- ═══ FUNCTION complaint_reply(p_id uuid, p_body text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.complaint_reply(p_id uuid, p_body text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_owner text; v_body text; v_recent int;
BEGIN
  v_uid := auth.uid()::text;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sign in required'; END IF;

  v_body := btrim(COALESCE(p_body, ''));
  IF v_body = '' THEN RAISE EXCEPTION 'empty reply'; END IF;

  SELECT c.user_id INTO v_owner FROM public.complaints c WHERE c.id = p_id;
  IF v_owner IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'forbidden'; END IF;

  -- حدُّ معدّل بسيط: عشرة ردودٍ في الساعة لكل مستخدم عبر كل شكاواه.
  SELECT count(*) INTO v_recent
    FROM public.complaint_replies cr
   WHERE cr.author_id = v_uid
     AND cr.author_role = 'user'
     AND cr.created_at > now() - interval '1 hour';
  IF v_recent >= 10 THEN
    RAISE EXCEPTION 'أرسلت ردوداً كثيرة في وقتٍ قصير — انتظر قليلاً ثم أعد المحاولة.'
      USING ERRCODE = 'P0001', HINT = 'P0011';
  END IF;

  INSERT INTO public.complaint_replies (complaint_id, author_id, author_role, body)
  VALUES (p_id, v_uid, 'user', v_body);

  -- شكوى ردَّ عليها صاحبها تعود «مفتوحة» — فلا تُدفن تحت «تم الحل».
  UPDATE public.complaints SET status = 'open'
   WHERE id = p_id AND status IN ('resolved','dismissed');

  RETURN jsonb_build_object('ok', true);
END;
$function$
;


-- ═══ FUNCTION complaint_set_attachments(p_id uuid, p_paths text[]) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.complaint_set_attachments(p_id uuid, p_paths text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_owner text; v_path text;
BEGIN
  v_uid := auth.uid()::text;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sign in required'; END IF;

  SELECT c.user_id INTO v_owner FROM public.complaints c WHERE c.id = p_id;
  IF v_owner IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'forbidden'; END IF;

  IF COALESCE(array_length(p_paths, 1), 0) > 5 THEN
    RAISE EXCEPTION 'أكثر من خمسة مرفقات لشكوى واحدة.';
  END IF;

  -- 🪤 كل مسارٍ يجب أن يبدأ بمعرّف صاحبه: بلا هذا يستطيع مستخدمٌ ربطَ ملفٍّ
  --    في مجلّد غيره بشكواه، فيقرؤه من خلالها.
  FOREACH v_path IN ARRAY COALESCE(p_paths, ARRAY[]::text[]) LOOP
    IF split_part(v_path, '/', 1) <> v_uid THEN
      RAISE EXCEPTION 'مسار مرفقٍ خارج مجلّدك.';
    END IF;
  END LOOP;

  UPDATE public.complaints SET attachments = COALESCE(p_paths, '{}')
   WHERE id = p_id;

  RETURN jsonb_build_object('ok', true, 'count', COALESCE(array_length(p_paths, 1), 0));
END;
$function$
;


-- ═══ FUNCTION complaint_thread(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.complaint_thread(p_id uuid)
 RETURNS TABLE(id uuid, author_role text, author_name text, body text, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text; v_owner text;
BEGIN
  v_uid := auth.uid()::text;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sign in required'; END IF;

  SELECT c.user_id INTO v_owner FROM public.complaints c WHERE c.id = p_id;
  IF v_owner IS NULL THEN RAISE EXCEPTION 'complaint not found'; END IF;
  IF v_owner <> v_uid AND NOT public.taki_admin_perm('tab_reports') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  RETURN QUERY
  SELECT cr.id, cr.author_role,
         -- اسمُ الإدارة لا يُكشف: «فريق تاكي» (لا تسمية أدمن في نصٍّ ظاهر)
         CASE WHEN cr.author_role = 'admin' THEN 'فريق تاكي'
              ELSE COALESCE(u.name, 'أنت') END,
         cr.body, cr.created_at
    FROM public.complaint_replies cr
    LEFT JOIN public.users u ON u.id = cr.author_id
   WHERE cr.complaint_id = p_id
   ORDER BY cr.created_at ASC;
END;
$function$
;


-- ═══ FUNCTION complete_booking(p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.complete_booking(p_barcode text)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    caller text := auth.uid()::text;
    updated public.bookings;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول لإتمام الحجز' USING ERRCODE = '28000';
    END IF;

    -- v15.42 — التاجرُ وحده. والمشتري مسارُه `buyer_confirm_receipt`، وفيه
    -- حارسُ انطلاقِ المندوب ومهلةُ العشر دقائق — وكان هذا الفرعُ يلتفّ عليهما.
    UPDATE public.bookings
    SET status = 'completed'
    WHERE barcode = p_barcode
      AND status IN ('pending', 'acknowledged')
      AND caller = store_id
    RETURNING * INTO updated;

    IF updated.barcode IS NULL THEN
        IF EXISTS (
            SELECT 1 FROM public.bookings
            WHERE barcode = p_barcode
              AND caller = store_id
        ) THEN
            RAISE EXCEPTION 'الحجز مغلق بالفعل أو ملغى' USING ERRCODE = 'P0001';
        ELSE
            RAISE EXCEPTION 'لم يتم العثور على الحجز أو ليست لديك صلاحية' USING ERRCODE = 'P0001', HINT = 'P0002';
        END IF;
    END IF;

    RETURN updated;
END;
$function$
;


-- ═══ FUNCTION compute_subscription_price(p_plan_id text, p_branches integer, p_discount_percent numeric) INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.compute_subscription_price(p_plan_id text, p_branches integer, p_discount_percent numeric DEFAULT 0)
 RETURNS numeric
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    v_plan RECORD;
    v_extra_branches INTEGER;
    v_total NUMERIC;
BEGIN
    SELECT * INTO v_plan FROM subscription_plans WHERE id = p_plan_id LIMIT 1;
    IF v_plan IS NULL THEN
        RETURN 0;
    END IF;

    v_extra_branches := GREATEST(0, COALESCE(p_branches, 1) - COALESCE(v_plan.included_branches, 3));
    v_total := COALESCE(v_plan.price_monthly, 0) + (v_extra_branches * COALESCE(v_plan.extra_branch_fee, 0));

    IF p_discount_percent IS NOT NULL AND p_discount_percent > 0 THEN
        v_total := v_total * (1 - p_discount_percent / 100.0);
    END IF;

    RETURN ROUND(v_total::numeric, 2);
END;
$function$
;


-- ═══ FUNCTION confirm_subscription_payment(p_payment_id text, p_gateway_reference text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.confirm_subscription_payment(p_payment_id text, p_gateway_reference text)
 RETURNS merchant_subscriptions
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_payment subscription_payments;
    v_sub merchant_subscriptions;
BEGIN
    -- v15.80 ⑦ — كان `SELECT user_type … IS DISTINCT FROM 'admin'`: أيُّ أدمنٍ
    --   فرعيٍّ يَختم دفعةً ويُفعّل اشتراكاً. ونصُّ الرسالة يبقى كما هو.
    IF NOT public.taki_admin_finance() THEN
        RAISE EXCEPTION 'Only admins can confirm payments';
    END IF;

    SELECT * INTO v_payment FROM subscription_payments WHERE id = p_payment_id;
    IF v_payment IS NULL THEN
        RAISE EXCEPTION 'Payment not found';
    END IF;

    -- v15.45 — ويُختم **من** ضمِن الدفعة: الصفُّ كان يصير «مدفوعاً» بلا أيّ
    -- أثرٍ لمن أقرّ بوصولها ولا كيف. و`tr_guard_fake_sub_payment` صار يرى
    -- التعديلَ أيضاً (كان `BEFORE INSERT` وحده)، فمزوّدٌ فارغٌ يُرفض بحقّ.
    UPDATE subscription_payments
    SET status = 'paid',
        gateway_provider = COALESCE(NULLIF(gateway_provider, ''), 'admin_confirmed'),
        gateway_reference = p_gateway_reference,
        paid_at = NOW()
    WHERE id = p_payment_id;

    UPDATE merchant_subscriptions
    SET status = 'active',
        current_period_start = COALESCE(v_payment.period_start, NOW()),
        current_period_end = COALESCE(v_payment.period_end, NOW() + interval '30 days'),
        last_renewed_at = NOW(),
        updated_at = NOW()
    WHERE id = v_payment.subscription_id
    RETURNING * INTO v_sub;

    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type)
    VALUES (v_payment.merchant_id,
        '✅ تم تجديد اشتراكك', '✅ Subscription renewed',
        'استلمنا دفعتك بنجاح. اشتراكك ساري حتى ' ||
            to_char(COALESCE(v_payment.period_end, NOW() + interval '30 days'), 'YYYY-MM-DD'),
        'We received your payment. Your subscription is active until ' ||
            to_char(COALESCE(v_payment.period_end, NOW() + interval '30 days'), 'YYYY-MM-DD'),
        'system');

    RETURN v_sub;
END;
$function$
;


-- ═══ FUNCTION contest_counts(p_contest_id uuid) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.contest_counts(p_contest_id uuid)
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  select jsonb_build_object(
    'total',     count(*),
    'qualified', count(*) filter (where qualified)
  ) from contest_entries where contest_id = p_contest_id;
$function$
;


-- ═══ FUNCTION contest_public_results(p_contest_id uuid) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.contest_public_results(p_contest_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare c record; v jsonb;
begin
  select * into c from contests where id = p_contest_id;
  if not found or c.status <> 'drawn' then return '[]'::jsonb; end if;
  select jsonb_agg(jsonb_build_object(
    'name',  case when c.reveal_name then name else 'فائز' end,
    'phone', case c.reveal_phone
               when 'full'   then phone
               when 'hidden' then null
               else '*** ' || right(regexp_replace(phone, '\D', '', 'g'), 4)
             end
  )) into v from contest_entries where contest_id = p_contest_id and is_winner = true;
  return coalesce(v, '[]'::jsonb);
end; $function$
;


-- ═══ FUNCTION deal_payment_mode(p_store_id text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.deal_payment_mode(p_store_id text)
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN NOT public.direct_pay_on() THEN 'cod'
    WHEN g.merchant_id IS NULL THEN 'cod'
    WHEN NOT public.pay_provider_on(g.provider) THEN 'cod'
    WHEN NOT g.is_enabled OR g.disabled_by_admin OR g.verified_at IS NULL OR g.fail_count >= 5 THEN 'cod'
    -- v14.44 — الحارس الأخير: مفتاحٌ لا يَحُلّ في الخزنة = بوّابةٌ لا تعمل.
    -- كان غيابه يُظهر «ادفع الآن» على عرضين ثم يردّ GATEWAY_UNAVAILABLE.
    WHEN NOT public._gateway_secret_live(g.merchant_id) THEN 'cod'
    ELSE g.payment_modes
  END
  FROM (SELECT 1) x
  LEFT JOIN public.merchant_gateways g ON g.merchant_id = p_store_id;
$function$
;


-- ═══ FUNCTION default_maps_link_from_location() INVOKER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.default_maps_link_from_location()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF (NEW.google_maps_link IS NULL OR NEW.google_maps_link = '') AND NEW.location_id IS NOT NULL THEN
    SELECT google_maps_link INTO NEW.google_maps_link FROM public.locations WHERE id = NEW.location_id;
  END IF;
  RETURN NEW;
END; $function$
;


-- ═══ FUNCTION delete_rating(p_rating_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.delete_rating(p_rating_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid text := (auth.uid())::text;
    v_owner text;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    SELECT user_id INTO v_owner FROM public.ratings WHERE id = p_rating_id;
    IF v_owner IS NULL THEN
        RAISE EXCEPTION 'rating not found';
    END IF;
    IF v_owner <> v_uid AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = v_uid AND u.user_type='admin') THEN
        RAISE EXCEPTION 'forbidden';
    END IF;
    UPDATE public.ratings SET deleted_at = now(), updated_at = now() WHERE id = p_rating_id;
END $function$
;


-- ═══ FUNCTION delete_user_account() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.delete_user_account()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := (auth.uid())::text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'Not authenticated'; END IF;
  -- v14.20 — كانت تمسح صفّ المصادقة فيتسلسل الحذف إلى الطلبات والفواتير.
  -- اليوم تُحوّل إلى المسار المعتمد: تعطيلٌ فوري ثم تجهيلٌ بعد ثلاثين يوماً
  -- مع إمكانية التراجع — وهو ما تَعِد به الشروط حرفياً.
  UPDATE public.users
     SET deleted_at = now(), purge_after = now() + interval '30 days'
   WHERE id = v_uid;
  UPDATE public.deals SET status = 'paused' WHERE store_id = v_uid AND status = 'active';
END
$function$
;


-- ═══ FUNCTION delivery_quote(p_store_id text, p_lat double precision, p_lng double precision, p_location_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.delivery_quote(p_store_id text, p_lat double precision, p_lng double precision, p_location_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  sp   public.store_profiles%ROWTYPE;
  z    public.store_delivery_zones%ROWTYPE;
  -- عرضٌ بلا فرع محدّد = الموقع الأساسي للمتجر. بدون هذه المساواة يسقط كل عرضٍ
  -- ذي موقع واحد (location_id فارغ) خارج نطاقاته المرسومة على 'primary' فلا
  -- يظهر له توصيل أبداً — وهي الحالة الأشيع: متجرٌ بفروع، وعرضٌ في المحل الرئيس.
  v_loc text := coalesce(nullif(btrim(coalesce(p_location_id, '')), ''), 'primary');
  v_zone_count int;
  v_pay text;
BEGIN
  -- v14.39 — مفتاح الإيقاف العام. هذه الدالة هي المختنق الذي تمرّ به كل
  -- المسارات (الموقع والبوتان وحارس الحجز)، فالفحص هنا يُغطّيها جميعاً.
  IF NOT public.taki_delivery_globally_on() THEN
    RETURN jsonb_build_object('enabled', false, 'available', false, 'reason', 'platform_off');
  END IF;

  SELECT * INTO sp FROM public.store_profiles WHERE store_id = p_store_id;
  IF NOT FOUND OR NOT coalesce(sp.delivery_enabled, false) THEN
    RETURN jsonb_build_object('enabled', false, 'available', false, 'reason', 'disabled');
  END IF;
  -- إيقافٌ إداريّ على هذا المتجر بعينه — عمودٌ لا يملكه التاجر فلا يرفعه بضغطة.
  IF coalesce(sp.delivery_blocked_by_admin, false) THEN
    RETURN jsonb_build_object('enabled', false, 'available', false, 'reason', 'admin_blocked');
  END IF;

  -- ── v15.33 · الإقرارُ يحكم ────────────────────────────────────────────
  -- `accepts_cod` إقرارُ المتجر كلِّه (بوّابةُ كلّ حجز)، وعمودُ التوصيل
  -- إعدادُ التوصيل وحده — عمودان في جدولٍ واحد لا يسأل أحدُهما الآخر.
  -- 🔴 وافتراضُ الثاني «نقداً»، فمتجرٌ أقرّ «بطاقة فقط» ثمّ فعّل التوصيل
  --    كان يُعلن نقداً عند الباب. والمشغّل `tr_guard_booking_delivery`
  --    يرفض ذلك النقدَ بـTAKI_STORE_CARD_ONLY، و`DealDetails` تفرض
  --    `paymentIntent='cod'` من هذا الحقل ثمّ تقول «اختر الدفع الإلكتروني»
  --    — **والمشتري لا يملك اختياره**. طريقٌ مسدود، لا تسريبُ نقد.
  -- ⇒ مصدرُ الحقيقة واحد: الإقرارُ يَجُبّ إعدادَ التوصيل عند التعارض.
  v_pay := CASE WHEN NOT coalesce(sp.accepts_cod, true) THEN 'card' ELSE sp.delivery_payment END;

  -- النطاقات التي تحكم هذا الحجز: نطاقات الفرع المختار + النطاقات العامة
  -- (branch_id IS NULL) التي رُسمت قبل ربط النطاق بالفرع أو لمتجر بموقع واحد.
  SELECT count(*) INTO v_zone_count
    FROM public.store_delivery_zones dz
   WHERE dz.store_id = p_store_id AND dz.is_active
     AND (dz.branch_id IS NULL OR (v_loc IS NOT NULL AND dz.branch_id = v_loc));

  IF v_zone_count = 0 THEN
    RETURN jsonb_build_object('enabled', true, 'available', false, 'reason', 'no_zones',
      'payment', v_pay, 'min_order', sp.delivery_min_order,
      'eta_min', sp.delivery_eta_min, 'note', sp.delivery_note);
  END IF;
  IF p_lat IS NULL OR p_lng IS NULL THEN
    RETURN jsonb_build_object('enabled', true, 'available', false, 'reason', 'no_location',
      'payment', v_pay, 'min_order', sp.delivery_min_order,
      'eta_min', sp.delivery_eta_min, 'note', sp.delivery_note);
  END IF;

  SELECT * INTO z FROM public.store_delivery_zones dz
   WHERE dz.store_id = p_store_id AND dz.is_active
     AND (dz.branch_id IS NULL OR (v_loc IS NOT NULL AND dz.branch_id = v_loc))
     AND public._taki_zone_contains(dz, p_lat, p_lng)
   ORDER BY coalesce(dz.fee, sp.delivery_fee) ASC, dz.created_at ASC
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('enabled', true, 'available', false, 'reason', 'out_of_zone',
      'payment', v_pay, 'min_order', sp.delivery_min_order,
      'eta_min', sp.delivery_eta_min, 'note', sp.delivery_note);
  END IF;

  RETURN jsonb_build_object(
    'enabled',   true,
    'available', true,
    'zone_id',   z.id,
    'zone_name', z.name,
    'branch_id', z.branch_id,
    'fee',       round(coalesce(z.fee, sp.delivery_fee), 2),
    'min_order', sp.delivery_min_order,
    'payment',   v_pay,
    'eta_min',   sp.delivery_eta_min,
    'note',      sp.delivery_note);
END
$function$
;


-- ═══ FUNCTION delivery_track_get(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.delivery_track_get(p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_b    public.bookings%ROWTYPE;
  v_t    public.delivery_tracks%ROWTYPE;
  v_is_seller boolean;
  v_is_buyer  boolean;
  v_fresh boolean;
  v_store_lat double precision;
  v_store_lng double precision;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'auth'); END IF;
  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;

  v_is_seller := v_b.store_id IS NOT DISTINCT FROM v_uid;
  v_is_buyer  := v_b.user_id  IS NOT DISTINCT FROM v_uid;
  IF NOT (v_is_seller OR v_is_buyer OR public.is_admin()) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'not_delivery');
  END IF;

  SELECT * INTO v_t FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('ok', true, 'status', 'preparing', 'live', false,
      'dispatched', false, 'hold_stopped', false,
      'destination', jsonb_build_object('lat', nullif(v_b.delivery_address->>'lat','')::double precision,
                                        'lng', nullif(v_b.delivery_address->>'lng','')::double precision));
  END IF;

  -- «حيّ» = نبضة خلال دقيقتين. أقدم من ذلك يُعرَض كآخر موقع معروف بوقته، ولا
  -- يُقدَّم كأنه الآن — إشارة متجمّدة تُعرض كحيّة تُفقد الثقة بالميزة كلها.
  v_fresh := v_t.lat IS NOT NULL AND v_t.updated_at > now() - interval '2 minutes'
             AND v_t.status IN ('on_the_way','arrived');

  SELECT u.lat, u.lng INTO v_store_lat, v_store_lng FROM public.users u WHERE u.id = v_b.store_id;

  RETURN jsonb_build_object(
    'ok', true,
    'role', CASE WHEN v_is_seller THEN 'seller' ELSE 'buyer' END,
    'status', v_t.status,
    'live', v_fresh,
    -- 🔴 v15.49 — حقيقتان صريحتان: «غادرت البضاعة» و«توقّف العدّاد». و`status`
    --    يبقى للعرض وحده — المنظّفُ يكتبه `cancelled` فلا يُستدلّ منه.
    'dispatched', (v_t.dispatched_at IS NOT NULL OR v_t.started_at IS NOT NULL
                   OR v_t.status IN ('on_the_way','arrived','delivered')),
    'hold_stopped', (v_t.dispatched_at IS NOT NULL OR v_t.started_at IS NOT NULL
                   OR v_t.status IN ('preparing','on_the_way','arrived','delivered')),
    'dispatched_at', v_t.dispatched_at,
    -- الإحداثيات لا تخرج إلا وهي حيّة وأثناء التوصيل: صفٌّ منتهٍ لا موقع فيه أصلاً.
    'lat', CASE WHEN v_fresh THEN v_t.lat ELSE NULL END,
    'lng', CASE WHEN v_fresh THEN v_t.lng ELSE NULL END,
    'heading', CASE WHEN v_fresh THEN v_t.heading ELSE NULL END,
    'accuracy_m', CASE WHEN v_fresh THEN v_t.accuracy_m ELSE NULL END,
    'remaining_km', CASE WHEN v_fresh THEN v_t.remaining_km ELSE NULL END,
    'eta_min', CASE WHEN v_fresh THEN v_t.eta_min ELSE NULL END,
    'updated_at', v_t.updated_at,
    'started_at', v_t.started_at,
    'ended_at', v_t.ended_at,
    'age_sec', GREATEST(0, EXTRACT(EPOCH FROM (now() - v_t.updated_at)))::int,
    'destination', jsonb_build_object(
        'lat', nullif(v_b.delivery_address->>'lat','')::double precision,
        'lng', nullif(v_b.delivery_address->>'lng','')::double precision,
        'label', v_b.delivery_address->>'label',
        -- تفاصيل العنوان للتاجر (هو من يصل)، والمشتري يعرف عنوانه أصلاً.
        'details', CASE WHEN v_is_seller THEN v_b.delivery_address->>'details' ELSE NULL END,
        'phone',   CASE WHEN v_is_seller THEN v_b.delivery_address->>'phone'   ELSE NULL END),
    'store', jsonb_build_object('lat', v_store_lat, 'lng', v_store_lng,
                                'name', (SELECT coalesce(nullif(u.shop,''), u.name) FROM public.users u WHERE u.id = v_b.store_id)),
    'booking_status', v_b.status
  );
END
$function$
;


-- ═══ FUNCTION delivery_track_ping(p_barcode text, p_lat double precision, p_lng double precision, p_accuracy double precision, p_heading double precision, p_speed_kmh double precision) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.delivery_track_ping(p_barcode text, p_lat double precision, p_lng double precision, p_accuracy double precision DEFAULT NULL::double precision, p_heading double precision DEFAULT NULL::double precision, p_speed_kmh double precision DEFAULT NULL::double precision)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid   text := auth.uid()::text;
  v_b     public.bookings%ROWTYPE;
  v_prev  public.delivery_tracks%ROWTYPE;
  v_dlat  double precision;
  v_dlng  double precision;
  v_km    numeric;
  v_eta   integer;
  v_speed double precision;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_lat IS NULL OR p_lng IS NULL
     OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 THEN
    RAISE EXCEPTION 'BAD_POINT';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_b.store_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN RAISE EXCEPTION 'NOT_DELIVERY'; END IF;
  IF v_b.status IN ('completed','cancelled') THEN RAISE EXCEPTION 'BOOKING_CLOSED'; END IF;

  SELECT * INTO v_prev FROM public.delivery_tracks WHERE barcode = v_b.barcode;
  -- لا بثّ قبل ضغطة «بدء التوصيل»: نبضةٌ بلا حالة سائرة تُرفض، فلا يتسرّب موقع
  -- تاجرٍ لم يبدأ توصيلاً بعد.
  IF v_prev.barcode IS NULL OR v_prev.status NOT IN ('on_the_way','arrived') THEN
    RAISE EXCEPTION 'NOT_STARTED';
  END IF;
  -- حدّ النبض: نبضة كل ٤ ثوانٍ على الأكثر (الواجهة ترسل كل ~١٠). يمنع إغراق
  -- الجدول وإرهاق الريل‑تايم من عميل معطوب أو خبيث.
  -- ⚠️ **إلا النبضة الأولى**: `delivery_track_set_status` تضع `updated_at = now()`،
  -- فكان الحدّ يبتلع أوّل موقع بعد ضغطة «بدء التوصيل» مباشرة — وهي أهمّ نبضة
  -- («خرج الآن من المتجر»)، فيبقى المشتري يرى «غير متصل» بلا سبب. الشرط الآن
  -- على وجود موقعٍ سابق فعلاً لا على وقت آخر تعديل. (كشفه اختبار T5/T6/T7.)
  IF v_prev.lat IS NOT NULL AND v_prev.updated_at > now() - interval '4 seconds' THEN
    RETURN jsonb_build_object('ok', true, 'throttled', true);
  END IF;

  v_dlat := nullif(v_b.delivery_address->>'lat','')::double precision;
  v_dlng := nullif(v_b.delivery_address->>'lng','')::double precision;
  IF v_dlat IS NOT NULL AND v_dlng IS NOT NULL THEN
    v_km := round(public._taki_km(p_lat, p_lng, v_dlat, v_dlng)::numeric, 2);
    -- السرعة الفعلية إن أرسلها الجهاز ومعقولة (١–١٢٠)، وإلا ٢٥ كم/س داخل المدينة.
    v_speed := CASE WHEN p_speed_kmh IS NOT NULL AND p_speed_kmh BETWEEN 1 AND 120
                    THEN p_speed_kmh ELSE 25 END;
    -- +١.٣ معامل التواء الطرق عن الخطّ المستقيم، ودقيقة واحدة حدّ أدنى.
    v_eta := GREATEST(1, CEIL((v_km * 1.3 / v_speed) * 60))::int;
  END IF;

  UPDATE public.delivery_tracks SET
    lat = p_lat, lng = p_lng,
    accuracy_m = p_accuracy, heading = p_heading, speed_kmh = p_speed_kmh,
    remaining_km = v_km, eta_min = v_eta,
    updated_at = now()
  WHERE barcode = v_b.barcode;

  RETURN jsonb_build_object('ok', true, 'remaining_km', v_km, 'eta_min', v_eta, 'status', v_prev.status);
END
$function$
;


-- ═══ FUNCTION delivery_track_set_status(p_barcode text, p_status text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.delivery_track_set_status(p_barcode text, p_status text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid text := auth.uid()::text;
  v_b   public.bookings%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_status IS NULL OR p_status NOT IN ('preparing','on_the_way','arrived','delivered','cancelled') THEN
    RAISE EXCEPTION 'BAD_STATUS';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RAISE EXCEPTION 'NOT_FOUND'; END IF;
  IF v_b.store_id IS DISTINCT FROM v_uid THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF coalesce(v_b.fulfillment,'pickup') <> 'delivery' THEN RAISE EXCEPTION 'NOT_DELIVERY'; END IF;
  IF v_b.status IN ('cancelled') THEN RAISE EXCEPTION 'BOOKING_CLOSED'; END IF;
  -- الانطلاق يستلزم تأكيد الاستلام أولاً. الإيقاف والإنهاء لا يستلزمانه
  -- (لا يُحبس تاجرٌ عن إيقاف بثٍّ بدأه).
  IF p_status IN ('on_the_way','arrived') AND v_b.status = 'pending' THEN
    RAISE EXCEPTION 'NOT_ACKNOWLEDGED';
  END IF;

  INSERT INTO public.delivery_tracks (barcode, store_id, user_id, status, started_at)
  VALUES (v_b.barcode, v_b.store_id, v_b.user_id, p_status,
          CASE WHEN p_status = 'on_the_way' THEN now() ELSE NULL END)
  ON CONFLICT (barcode) DO UPDATE SET
    status     = EXCLUDED.status,
    started_at = CASE WHEN EXCLUDED.status = 'on_the_way'
                      THEN coalesce(public.delivery_tracks.started_at, now())
                      ELSE public.delivery_tracks.started_at END,
    ended_at   = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN now() ELSE NULL END,
    lat        = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.lat END,
    lng        = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.lng END,
    accuracy_m = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.accuracy_m END,
    heading    = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.heading END,
    speed_kmh  = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.speed_kmh END,
    remaining_km = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.remaining_km END,
    eta_min    = CASE WHEN EXCLUDED.status IN ('delivered','cancelled') THEN NULL ELSE public.delivery_tracks.eta_min END,
    updated_at = now();

  RETURN jsonb_build_object('ok', true, 'status', p_status, 'barcode', v_b.barcode);
END
$function$
;


-- ═══ FUNCTION direct_pay_on() DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.direct_pay_on()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((SELECT value = 'true'::jsonb FROM public.platform_settings WHERE key = 'direct_pay_enabled'), false);
$function$
;


-- ═══ FUNCTION draw_contest_winners(p_contest_id uuid, p_count integer) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.draw_contest_winners(p_contest_id uuid, p_count integer DEFAULT 1)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v        jsonb;
  v_title  text;
  v_prize  text;
  v_sent   int := 0;
BEGIN
  IF NOT public.is_admin() THEN RAISE EXCEPTION 'forbidden: admin only'; END IF;

  SELECT title, COALESCE(NULLIF(btrim(prize), ''), '') INTO v_title, v_prize
    FROM contests WHERE id = p_contest_id;

  -- Never reset existing winners; draw only from not-yet-winners.
  WITH picked AS (
    SELECT id FROM contest_entries
    WHERE contest_id = p_contest_id AND qualified = true AND is_winner = false
    ORDER BY random() LIMIT GREATEST(1, COALESCE(p_count, 1))
  ), upd AS (
    UPDATE contest_entries e SET is_winner = true
    FROM picked WHERE e.id = picked.id
    RETURNING e.name, e.phone, e.created_at
  )
  SELECT jsonb_agg(jsonb_build_object('name', name, 'phone', phone) ORDER BY created_at) INTO v FROM upd;

  UPDATE contests SET status = 'drawn', updated_at = now() WHERE id = p_contest_id;

  -- v14.65 — إشعارٌ لكل فائزٍ له حساب. الإدراج لا يُسقط السحب إن تعذّر.
  -- v14.77 — الربط بالحساب (`user_id`) لا بنصّ الجوال، فمن غيّر جوّاله بعد
  -- المشاركة يصله إشعارُه. والجوال يبقى مساراً احتياطياً للصفوف الأقدم.
  BEGIN
    WITH winners AS (
      SELECT DISTINCT COALESCE(e.user_id, u.id) AS user_id
      FROM contest_entries e
      LEFT JOIN users u
             ON e.user_id IS NULL
            AND nullif(btrim(u.phone), '') = btrim(e.phone)
      WHERE e.contest_id = p_contest_id
        AND e.is_winner = true
        AND COALESCE(e.user_id, u.id) IS NOT NULL
    ), ins AS (
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      SELECT w.user_id,
             '🎉 مبروك! فزت في المسابقة',
             '🎉 Congratulations! You won',
             'فزت في «' || COALESCE(v_title, 'المسابقة') || '»'
               || CASE WHEN v_prize <> '' THEN ' — الجائزة: ' || v_prize ELSE '' END
               || '. سنتواصل معك لتسليم الجائزة.',
             'You won “' || COALESCE(v_title, 'the contest') || '”'
               || CASE WHEN v_prize <> '' THEN ' — prize: ' || v_prize ELSE '' END
               || '. We will contact you to hand it over.',
             'system',
             jsonb_build_object('audience', 'buyer', 'actionUrl', '/contests', 'contestId', p_contest_id)
      FROM winners w
      -- لا يُكرَّر الإشعار على سحبةٍ ثانية لنفس المسابقة
      WHERE NOT EXISTS (
        SELECT 1 FROM notifications n
        WHERE n.user_id = w.user_id
          AND n.type = 'system'
          AND n.meta_data->>'contestId' = p_contest_id::text
      )
      RETURNING 1
    )
    SELECT count(*) INTO v_sent FROM ins;
  EXCEPTION WHEN OTHERS THEN
    v_sent := -1;   -- تعذّر الإبلاغ: السحب صحيح والجدول يقول ذلك
  END;

  RETURN jsonb_build_object('winners', COALESCE(v, '[]'::jsonb), 'notified', v_sent);
END $function$
;


-- ═══ FUNCTION enforce_branch_location_cap() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.enforce_branch_location_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role TEXT; v_max INT; v_new_key TEXT; v_old_key TEXT; v_distinct INT; v_exists BOOLEAN;
BEGIN
    IF NEW.is_active IS DISTINCT FROM true THEN RETURN NEW; END IF;
    SELECT user_type INTO v_role FROM users WHERE id = NEW.merchant_id;
    SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = NEW.merchant_id;
    IF v_role = 'admin' AND v_max IS NULL THEN RETURN NEW; END IF;
    v_max := COALESCE(v_max, 3);

    IF NEW.location_id IS NOT NULL AND NEW.location_id <> 'other' AND NEW.location_id NOT LIKE 'custom\_%' ESCAPE '\'
    THEN v_new_key := 'loc:' || NEW.location_id;
    ELSE v_new_key := 'geo:' || ROUND(COALESCE(NEW.map_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(NEW.map_lng,0)::numeric,3)::text;
    END IF;

    -- Editing a branch without moving its location → always allowed (rename, etc.)
    IF TG_OP = 'UPDATE' THEN
        IF OLD.location_id IS NOT NULL AND OLD.location_id <> 'other' AND OLD.location_id NOT LIKE 'custom\_%' ESCAPE '\'
        THEN v_old_key := 'loc:' || OLD.location_id;
        ELSE v_old_key := 'geo:' || ROUND(COALESCE(OLD.map_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(OLD.map_lng,0)::numeric,3)::text;
        END IF;
        IF v_old_key = v_new_key THEN RETURN NEW; END IF;
    END IF;

    SELECT
        COUNT(*) FILTER (WHERE k <> v_new_key),
        bool_or(k = v_new_key)
      INTO v_distinct, v_exists
    FROM (
        SELECT DISTINCT k FROM (
            -- v13.16: مفاتيح العروض النشطة تشمل فروع النشر المتعدد
            SELECT k FROM deals d
              CROSS JOIN LATERAL public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k
             WHERE d.store_id = NEW.merchant_id AND d.status='active'
            UNION ALL
            SELECT CASE WHEN b.location_id IS NOT NULL AND b.location_id <> 'other' AND b.location_id NOT LIKE 'custom\_%' ESCAPE '\'
                THEN 'loc:' || b.location_id
                ELSE 'geo:' || ROUND(COALESCE(b.map_lat,0)::numeric,3)::text || ',' || ROUND(COALESCE(b.map_lng,0)::numeric,3)::text END
            FROM store_branches b WHERE b.merchant_id = NEW.merchant_id AND b.is_active = true AND b.id <> NEW.id
        ) t
    ) keys;

    IF COALESCE(v_exists,false) THEN RETURN NEW; END IF;   -- location already used → not new
    IF COALESCE(v_distinct,0) >= v_max THEN
        RAISE EXCEPTION 'LOCATION_LIMIT_EXCEEDED: Plan allows % locations.', v_max USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END; $function$
;


-- ═══ FUNCTION enforce_seller_location_cap() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.enforce_seller_location_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_role TEXT; v_max INT; v_new_keys TEXT[]; v_other_keys TEXT[]; v_union INT; v_self INT;
BEGIN
    IF NEW.status IS DISTINCT FROM 'active' THEN RETURN NEW; END IF;
    SELECT user_type INTO v_role FROM users WHERE id = NEW.store_id;
    SELECT max_branches INTO v_max FROM store_profiles WHERE store_id = NEW.store_id;
    IF v_role = 'admin' AND v_max IS NULL THEN RETURN NEW; END IF;
    v_max := COALESCE(v_max, 3);

    -- v13.16: كل مفاتيح هذا العرض (الأساسي + فروع «انشر في عدة مواقع»)
    SELECT COALESCE(array_agg(DISTINCT k), ARRAY[]::text[]) INTO v_new_keys
      FROM public._taki_deal_loc_keys(NEW.location_id, NEW.map_lat, NEW.map_lng, NEW.locations) k;
    v_self := array_length(v_new_keys, 1);

    -- العرض وحده يتجاوز الباقة (الحالة التي أبلغ عنها ناصر: باقة ١ وعرض بـ٣ فروع)
    IF COALESCE(v_self,0) > v_max THEN
        RAISE EXCEPTION
          'LOCATION_LIMIT_EXCEEDED: Plan allows % distinct locations; this deal needs %.',
          v_max, v_self USING ERRCODE = 'P0001';
    END IF;

    SELECT COALESCE(array_agg(DISTINCT k), ARRAY[]::text[]) INTO v_other_keys
      FROM deals d
      CROSS JOIN LATERAL public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k
     WHERE d.store_id = NEW.store_id AND d.status = 'active' AND d.id <> NEW.id;

    SELECT count(DISTINCT k) INTO v_union FROM unnest(v_new_keys || v_other_keys) k;

    IF v_union > v_max THEN
        RAISE EXCEPTION
          'LOCATION_LIMIT_EXCEEDED: Plan allows % distinct locations; this deal needs %.',
          v_max, v_union USING ERRCODE = 'P0001';
    END IF;
    RETURN NEW;
END; $function$
;


-- ═══ FUNCTION enqueue_rating_reminders() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.enqueue_rating_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int := 0;
BEGIN
  WITH due AS (
    SELECT b.barcode, b.user_id, b.deal_id, b.store_id,
           COALESCE(d.shop_name, NULLIF(u.shop, ''), u.name, 'المتجر') AS shop_name
      FROM public.bookings b
      LEFT JOIN public.deals d ON d.id = b.deal_id
      LEFT JOIN public.users u ON u.id = b.store_id
     WHERE b.status = 'completed'
       -- نافذةٌ يومٌ إلى ثلاثة: لا نزاحم إشعار الإتمام نفسه، ولا نُذكّر بعد
       -- أن يبرد الطلب فيصير التذكير إزعاجاً.
       AND b.completed_at >= now() - interval '3 days'
       AND b.completed_at <= now() - interval '1 day'
       AND b.user_id IS NOT NULL
       -- لم يقيّم هذا المتجر بعد
       AND NOT EXISTS (
         SELECT 1 FROM public.ratings r
          WHERE r.user_id = b.user_id AND r.store_id = b.store_id AND r.deleted_at IS NULL
       )
       -- ولم يُذكَّر بهذا الطلب من قبل (البصمة = الباركود)
       AND NOT EXISTS (
         SELECT 1 FROM public.notifications n
          WHERE n.user_id = b.user_id
            AND n.meta_data->>'ratingReminder' = b.barcode
       )
     LIMIT 200          -- سقفٌ لكل تشغيلة فلا تتضخّم دفعةٌ واحدة
  ), ins AS (
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    SELECT due.user_id,
           '⭐ كيف كانت تجربتك؟',
           '⭐ How was your experience?',
           'قيّم ' || due.shop_name || ' في دقيقة — تقييمك يساعد غيرك على الاختيار.',
           'Rate ' || due.shop_name || ' in under a minute — your rating helps other buyers choose.',
           'rating',
           jsonb_build_object(
             'audience', 'buyer',
             'barcode', due.barcode,
             'dealId', due.deal_id,
             'storeId', due.store_id,
             'ratingReminder', due.barcode,
             'actionUrl', '/bookings?barcode=' || due.barcode
           )
      FROM due
    RETURNING 1
  )
  SELECT count(*) INTO v_n FROM ins;
  RETURN v_n;
END $function$
;


-- ═══ FUNCTION ensure_active_subscription(p_merchant_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.ensure_active_subscription(p_merchant_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_enabled  boolean;
    v_role     text;
    v_status   text;
    v_pe       timestamptz;
    v_te       timestamptz;
    v_plan     text;
    v_exp      timestamptz;
BEGIN
    -- Free mode: gateway disabled or unset -> everyone is "active".
    SELECT (value = 'true'::jsonb) INTO v_enabled
      FROM platform_settings WHERE key = 'payment_gateway_enabled';
    IF v_enabled IS NOT TRUE THEN
        RETURN TRUE;
    END IF;

    -- Admins always pass.
    SELECT user_type INTO v_role FROM users WHERE id = p_merchant_id;
    IF v_role = 'admin' THEN
        RETURN TRUE;
    END IF;

    -- Source A: the billing lifecycle table.
    SELECT status, current_period_end, trial_ends_at
      INTO v_status, v_pe, v_te
      FROM merchant_subscriptions WHERE merchant_id = p_merchant_id;
    IF v_status = 'trial' AND v_te IS NOT NULL AND v_te > NOW() THEN
        RETURN TRUE;
    END IF;
    IF v_status IN ('active','gifted') AND (v_pe IS NULL OR v_pe > NOW()) THEN
        RETURN TRUE;
    END IF;

    -- Source B: the store_profiles mirror (admin RPC + self-serve write here).
    SELECT subscription_plan, subscription_expires_at
      INTO v_plan, v_exp
      FROM store_profiles WHERE store_id = p_merchant_id;
    IF v_plan IS NOT NULL AND lower(v_plan) <> 'free'
       AND (v_exp IS NULL OR v_exp > NOW()) THEN
        RETURN TRUE;
    END IF;

    RETURN FALSE;
END;
$function$
;


-- ═══ FUNCTION expire_due_bookings() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.expire_due_bookings()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now     bigint  := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
  v_count   int;
BEGIN
  WITH upd AS (
    UPDATE public.bookings b
       SET status = 'cancelled', cancelled_by = 'system'
     WHERE b.status IN ('pending','acknowledged')
       AND b.expiry_time IS NOT NULL
       AND b.expiry_time < v_now
       -- حقيقةٌ واحدة: الدفعُ بالبطاقة وشبكةُ أمان المنطلق كلاهما داخلها.
       AND NOT public.taki_autocancel_blocked(b.barcode, b.booked_at, b.expiry_time, b.paid_at IS NOT NULL)
    RETURNING 1
  ) SELECT count(*) INTO v_count FROM upd;
  RETURN COALESCE(v_count,0);
END;
$function$
;


-- ═══ FUNCTION expire_trials() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.expire_trials()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_count INTEGER;
BEGIN
    WITH expired AS (
        UPDATE merchant_subscriptions
        SET status = 'frozen', updated_at = NOW()
        WHERE status = 'trial' AND trial_ends_at < NOW()
        RETURNING merchant_id
    )
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type)
    SELECT merchant_id,
        '⏰ انتهت فترتك التجريبية', '⏰ Your free trial ended',
        'انتهت الـ 14 يوماً المجانية. اشترك الآن لاستئناف نشر العروض الجديدة. عروضك الحالية تبقى مرئية للزبائن.',
        'Your 14-day free trial ended. Subscribe now to resume publishing new deals. Your existing deals remain visible.',
        'system'
    FROM expired
    RETURNING 1
    INTO v_count;
    RETURN COALESCE(v_count, 0);
END;
$function$
;


-- ═══ FUNCTION find_email_by_phone(input_phone text) DEFINER owner=postgres search_path=search_path=public, auth anon=YES ═══
CREATE OR REPLACE FUNCTION public.find_email_by_phone(input_phone text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth'
AS $function$
DECLARE
    digits_only TEXT;
    bare        TEXT;
    intl        TEXT;
    country     TEXT;
    found_email TEXT;
    v_ip        TEXT;
BEGIN
    v_ip := public._taki_client_ip();
    -- v15.79 — بلا شرطٍ: عنوانٌ مجهولٌ يسقط في دلوٍ مشترك، لا في فراغ.
    PERFORM public.taki_rate_check('fep1m:' || COALESCE(v_ip, 'noip'), 3, 60,
      '⏳ محاولات كثيرة خلال وقت قصير — انتظر دقيقة ثم أعد المحاولة.');
    PERFORM public.taki_rate_check('fep1h:' || COALESCE(v_ip, 'noip'), 15, 3600,
      '⏳ محاولات كثيرة — أعد المحاولة بعد قليل.');

    digits_only := regexp_replace(COALESCE(input_phone, ''), '\D', '', 'g');

    IF length(digits_only) >= 13 AND left(digits_only, 5) = '00966' THEN
        digits_only := '0' || substring(digits_only from 6);
    ELSIF length(digits_only) >= 12 AND left(digits_only, 3) = '966' THEN
        digits_only := '0' || substring(digits_only from 4);
    END IF;

    IF length(digits_only) < 9 THEN
        RETURN NULL;
    END IF;

    -- v15.79 — دلوٌ لكلّ رقم: **بعد** التطبيع و**بعد** الخروج المبكّر، فلا
    -- يُنشئ نصٌّ مختلَقٌ صفَّ عدٍّ. وترتيبُه بعد دلوَي العنوان مقصود: نموُّ
    -- الصفوف يبقى محصوراً بسقف العنوان (١٥/ساعة) لا بخيال المهاجم.
    -- وموضعُه قبل أيّ بحثٍ في الجدول مقصودٌ أيضاً: فالخنقُ يقع سواءٌ كان
    -- الرقمُ مسجَّلاً أم لا، فلا يصير العدّادُ بنفسه عرّافاً عن وجود حساب.
    --
    -- 🔴 والسقفُ سخيٌّ عن قصدٍ مقيس: هذه الدالّة تُنادى في **كلّ** محاولة
    --    دخولٍ بالجوّال حتى الخاطئة — `src/services/authService.ts:293`
    --    قبل `signInWithPassword` في :298 — بنداءٍ واحدٍ لكلّ محاولة. وسقفُ
    --    العنوان (١٥/ساعة) يَبتُّ قبل هذا السقف لمن على اتّصالٍ واحد، فهذا
    --    الدلوُ لا يَعضُّ إلا هجمةً **موزَّعةً على عناوين كثيرة** — وهي
    --    الحالةُ التي يُفلتها سقفُ العنوان وحده. وشبكاتُ المشغّلين
    --    السعوديّة مشتركةُ العنوان (NAT)، فالمفتاحُ على **الرقم** لا على
    --    العنوان حتى لا يُعاقَب جارٌ بفعل جار.
    PERFORM public.taki_rate_check('fepph:' || digits_only, 20, 3600,
      '⏳ محاولات كثيرة على هذا الرقم — أعد المحاولة بعد قليل، أو ادخل ببريدك الإلكتروني.');

    IF left(digits_only, 1) = '0' THEN
        bare := substring(digits_only from 2);
    ELSE
        bare := digits_only;
    END IF;
    intl    := '+966' || bare;
    country := '966'  || bare;

    -- v12.39: admin accounts are excluded — their emails must never be
    -- resolvable from a phone number (admins log in with email).
    SELECT email INTO found_email
      FROM public.users
     WHERE (phone         IN (digits_only, '0' || bare, bare, intl, country)
        OR contact_phone IN (digits_only, '0' || bare, bare, intl, country))
       AND user_type IS DISTINCT FROM 'admin'
     LIMIT 1;

    IF found_email IS NOT NULL THEN
        RETURN found_email;
    END IF;

    SELECT COALESCE(au.email, au.raw_user_meta_data->>'email') INTO found_email
      FROM auth.users au
     WHERE (au.phone                          IN (digits_only, '0' || bare, bare, intl, country)
        OR au.raw_user_meta_data->>'phone'         IN (digits_only, '0' || bare, bare, intl, country)
        OR au.raw_user_meta_data->>'contact_phone' IN (digits_only, '0' || bare, bare, intl, country))
       AND NOT EXISTS (
         SELECT 1 FROM public.users pu
         WHERE pu.id = au.id::text AND pu.user_type = 'admin'
       )
     LIMIT 1;

    IF found_email IS NOT NULL THEN
      BEGIN
        INSERT INTO public.activity_log (action, entity_type, entity_id, metadata)
        VALUES ('phone_email_lookup', 'auth', left(digits_only, 4) || '****',
                jsonb_build_object('ip', v_ip));
      EXCEPTION WHEN OTHERS THEN NULL;
      END;
    END IF;
    RETURN found_email;
END;
$function$
;


-- ═══ FUNCTION find_nearest_sa_city(p_lat double precision, p_lng double precision) INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.find_nearest_sa_city(p_lat double precision, p_lng double precision)
 RETURNS sa_cities_geo
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
    SELECT g.*
    FROM public.sa_cities_geo g
    ORDER BY (
        2 * 6371 * asin(sqrt(
            sin(radians((g.lat - p_lat) / 2))^2
            + cos(radians(p_lat)) * cos(radians(g.lat))
              * sin(radians((g.lng - p_lng) / 2))^2
        ))
    ) ASC
    LIMIT 1
$function$
;


-- ═══ FUNCTION freeze_deals_on_downgrade() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.freeze_deals_on_downgrade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_max INT;
  r RECORD;
  v_keys TEXT[] := ARRAY[]::TEXT[];
  v_deal_keys TEXT[];
BEGIN
  BEGIN
    IF NEW.max_branches IS NULL OR OLD.max_branches IS NULL
       OR NEW.max_branches >= OLD.max_branches THEN
      RETURN NEW;   -- ترقية أو بلا تغيير → لا شيء
    END IF;
    v_max := GREATEST(1, NEW.max_branches);

    -- (١) العروض التي تتجاوز السقف بذاتها
    UPDATE deals d
       SET status = 'paused', subscription_frozen = TRUE
     WHERE d.store_id = NEW.store_id
       AND d.status = 'active'
       AND (SELECT count(DISTINCT k)
              FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) > v_max;

    -- (٢) اتحاد الباقي: نُبقي الأقدم ونوقف ما يدفع الاتحاد فوق السقف
    FOR r IN
      SELECT d.id,
             ARRAY(SELECT DISTINCT k
                     FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) AS keys
        FROM deals d
       WHERE d.store_id = NEW.store_id AND d.status = 'active'
       ORDER BY d.created_at ASC NULLS FIRST, d.id ASC
    LOOP
      v_deal_keys := (SELECT array_agg(DISTINCT k) FROM unnest(v_keys || r.keys) k);
      IF COALESCE(array_length(v_deal_keys, 1), 0) > v_max THEN
        UPDATE deals SET status = 'paused', subscription_frozen = TRUE WHERE id = r.id;
      ELSE
        v_keys := v_deal_keys;   -- هذا العرض يسع داخل الباقة
      END IF;
    END LOOP;
  EXCEPTION WHEN OTHERS THEN
    NULL;  -- الحماية لا تُفشل عملية الاشتراك نفسها أبداً
  END;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION generate_telegram_link_code() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.generate_telegram_link_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_otp text;
BEGIN
  v_otp := upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 8));
  UPDATE users
  SET telegram_link_otp = v_otp,
      telegram_link_otp_expires_at = NOW() + INTERVAL '15 minutes'
  WHERE id = auth.uid()::text;
  RETURN v_otp;
END;
$function$
;


-- ═══ FUNCTION get_analytics_opt_out() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.get_analytics_opt_out()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_off boolean;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;   -- زائر: لا رأي للحساب
  SELECT COALESCE(analytics_opt_out, false) INTO v_off FROM users WHERE id = v_uid;
  RETURN v_off;   -- NULL إن لم يوجد صفّ ⇒ العميل يُبقي حالته المحلية
END $function$
;


-- ═══ FUNCTION get_booking_card(p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_booking_card(p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_b          bookings%ROWTYPE;
  v_d          deals%ROWTYPE;
  v_uid        text := auth.uid()::text;
  v_is_admin   boolean := false;
  v_seller     text;
  v_buyer      text;
  v_deal_found boolean := false;
BEGIN
  IF p_barcode IS NULL OR length(btrim(p_barcode)) = 0 THEN
    RETURN jsonb_build_object('error','bad_request');
  END IF;

  SELECT * INTO v_b FROM bookings WHERE barcode = upper(btrim(p_barcode)) LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error','not_found');
  END IF;

  -- v15.80 ⑦ — كان `SELECT (user_type='admin')` خاماً: أيُّ أدمنٍ فرعيٍّ يقرأ
  --   جوّالَ أيِّ مشترٍ وعنوانَه والمدفوع. صار صلاحيةً صريحة.
  IF v_uid IS NOT NULL THEN
    v_is_admin := public.taki_admin_finance();
  END IF;
  v_is_admin := coalesce(v_is_admin,false);

  IF v_uid IS NULL
     OR (v_uid <> coalesce(v_b.user_id,'~') AND v_uid <> coalesce(v_b.store_id,'~') AND NOT v_is_admin) THEN
    RETURN jsonb_build_object('error','forbidden');
  END IF;

  SELECT * INTO v_d FROM deals WHERE id = v_b.deal_id LIMIT 1;
  v_deal_found := FOUND;

  SELECT coalesce(nullif(shop,''), name) INTO v_seller FROM users WHERE id = v_b.store_id;
  v_buyer := coalesce(nullif(v_b.user_name,''), (SELECT name FROM users WHERE id = v_b.user_id));

  RETURN jsonb_build_object(
    'barcode',             v_b.barcode,
    'backup_code',         v_b.backup_code,
    'status',              v_b.status,
    'booked_quantity',     v_b.booked_quantity,
    'booked_at',           v_b.booked_at,
    'expiry_time',         v_b.expiry_time,
    'completed_at',        v_b.completed_at,
    'prep_time',           coalesce(v_b.prep_time, v_d.prep_time),
    'notes',               v_b.notes,
    'merchant_note',       v_b.merchant_note,
    'deal_id',             v_b.deal_id,
    'deal_exists',         v_deal_found,
    'item_name',           v_d.item_name,
    'shop_name',           coalesce(v_d.shop_name, v_seller),
    'category',            v_d.category,
    'image',               (v_d.images)[1],
    'original_price',      v_d.original_price,
    'discounted_price',    v_d.discounted_price,
    'discount_percentage', v_d.discount_percentage,
    'city',                v_d.city,
    'region',              v_d.region,
    'buyer_name',          v_buyer,
    'buyer_phone',         v_b.user_phone,
    'store_id',            v_b.store_id,
    'user_id',             v_b.user_id,
    'payment_method',      v_b.payment_method,
    'paid_at',             v_b.paid_at,
    'paid_amount',         v_b.paid_amount,
    'fulfillment',         coalesce(v_b.fulfillment, 'pickup'),
    'delivery_address',    v_b.delivery_address,
    'delivery_fee',        v_b.delivery_fee,
    'viewer_is_buyer',     (v_uid = v_b.user_id),
    'viewer_is_seller',    (v_uid = v_b.store_id),
    'viewer_is_admin',     v_is_admin
  );
END;
$function$
;


-- ═══ FUNCTION get_booking_refund(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_booking_refund(p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_me text := (SELECT auth.uid()::text); v_r public.booking_refunds%ROWTYPE;
BEGIN
  IF v_me IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_r FROM public.booking_refunds WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN NULL; END IF;
  -- v15.80 ⑦
  IF v_me <> v_r.buyer_id AND v_me <> v_r.store_id
     AND NOT public.taki_admin_finance() THEN RETURN NULL; END IF;
  RETURN jsonb_build_object(
    'barcode', v_r.barcode, 'status', v_r.status, 'amount', v_r.amount,
    'opened_by', v_r.opened_by, 'reason', v_r.reason, 'requested_at', v_r.requested_at,
    'merchant_note', v_r.merchant_note, 'decided_at', v_r.decided_at,
    'refunded_at', v_r.refunded_at, 'refund_amount', v_r.refund_amount,
    'refund_ref', v_r.refund_ref, 'refund_method', v_r.refund_method,
    'credit_note_no', v_r.credit_note_no);
END
$function$
;


-- ═══ FUNCTION get_bookings_timeline(p_from timestamp with time zone, p_to timestamp with time zone, p_bucket text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_bookings_timeline(p_from timestamp with time zone DEFAULT (now() - '24:00:00'::interval), p_to timestamp with time zone DEFAULT now(), p_bucket text DEFAULT 'hour'::text)
 RETURNS TABLE(bucket timestamp with time zone, count integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
    v_interval TEXT;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_interval := CASE p_bucket
        WHEN 'minute' THEN 'minute'
        WHEN 'day'    THEN 'day'
        ELSE 'hour'
    END;

    RETURN QUERY EXECUTE format($f$
        SELECT date_trunc(%L, created_at) AS bucket, COUNT(*)::INT
        FROM bookings
        WHERE created_at BETWEEN $1 AND $2
        GROUP BY 1 ORDER BY 1
    $f$, v_interval) USING p_from, p_to;
END $function$
;


-- ═══ FUNCTION get_deal_funnel(p_deal_id text, p_start timestamp with time zone, p_end timestamp with time zone) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_deal_funnel(p_deal_id text, p_start timestamp with time zone DEFAULT (now() - '30 days'::interval), p_end timestamp with time zone DEFAULT now())
 RETURNS TABLE(views bigint, clicks bigint, booking_started bigint, booking_abandoned bigint, booking_completed bigint, favorites bigint, shares bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_store_id TEXT;
    v_caller_role TEXT;
BEGIN
    SELECT store_id INTO v_store_id FROM deals WHERE id = p_deal_id;
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF auth.uid()::text <> v_store_id AND v_caller_role <> 'admin' THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    RETURN QUERY
    WITH ev AS (
        SELECT * FROM store_analytics_events
         WHERE deal_id = p_deal_id
           AND created_at BETWEEN p_start AND p_end
    )
    SELECT
        (SELECT COUNT(*) FROM ev WHERE event_type = 'deal_view')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'deal_click')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'booking_started')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'booking_abandoned')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'booking_completed')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'click_favorite')::bigint,
        (SELECT COUNT(*) FROM ev WHERE event_type = 'click_share')::bigint;
END;
$function$
;


-- ═══ FUNCTION get_live_stats(p_minutes integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_live_stats(p_minutes integer DEFAULT 5)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
    v_threshold TIMESTAMPTZ;
    result JSONB;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    v_threshold := NOW() - (p_minutes || ' minutes')::INTERVAL;

    SELECT jsonb_build_object(
        'active_users',   (SELECT COUNT(DISTINCT user_id)::INT FROM user_sessions WHERE last_seen_at > v_threshold),
        'active_buyers',  (SELECT COUNT(DISTINCT user_id)::INT FROM user_sessions WHERE user_type = 'buyer'  AND last_seen_at > v_threshold),
        'active_sellers', (SELECT COUNT(DISTINCT user_id)::INT FROM user_sessions WHERE user_type = 'seller' AND last_seen_at > v_threshold),
        'bookings_today', (SELECT COUNT(*)::INT FROM bookings WHERE created_at >= NOW()::DATE),
        'bookings_hour',  (SELECT COUNT(*)::INT FROM bookings WHERE created_at > NOW() - INTERVAL '1 hour'),
        'bookings_5min',  (SELECT COUNT(*)::INT FROM bookings WHERE created_at > NOW() - INTERVAL '5 minutes'),
        'new_users_today',(SELECT COUNT(*)::INT FROM users    WHERE created_at >= NOW()::DATE),
        -- v14.33 — كانت تعدّ المحذوفين، بينما «إدارة المشترين» تستبعدهم.
        -- فالزرّ في الرئيسية يقول عدداً والقائمة التي يفتحها تعرض أقلّ منه.
        'total_users',    (SELECT COUNT(*)::INT FROM users WHERE deleted_at IS NULL),
        'total_buyers',   (SELECT COUNT(*)::INT FROM users WHERE user_type = 'buyer'  AND deleted_at IS NULL),
        'total_sellers',  (SELECT COUNT(*)::INT FROM users WHERE user_type = 'seller' AND deleted_at IS NULL),
        -- «النشطة» كانت تشمل `paused` لأن الشرط نفيٌ لحالتين فقط، ومجال
        -- الحالات أربع. الإثبات أوضح من النفي.
        'active_deals',   (SELECT COUNT(*)::INT FROM deals  WHERE status = 'active'),
        'paying_sellers', (SELECT COUNT(*)::INT FROM store_profiles WHERE subscription_plan = 'premium' AND (subscription_expires_at IS NULL OR subscription_expires_at > NOW())),
        'mrr',            (SELECT COALESCE(SUM(subscription_amount), 0)::NUMERIC FROM store_profiles WHERE subscription_plan = 'premium' AND (subscription_expires_at IS NULL OR subscription_expires_at > NOW())),
        'as_of',          NOW()
    ) INTO result;

    RETURN result;
END $function$
;


-- ═══ FUNCTION get_my_account_status() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_my_account_status()
 RETURNS TABLE(deleted_at timestamp with time zone, purge_after timestamp with time zone, days_left integer)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid text := (auth.uid())::text;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    RETURN QUERY
        SELECT u.deleted_at,
               u.purge_after,
               GREATEST(0, EXTRACT(day FROM (u.purge_after - now()))::integer) AS days_left
        FROM public.users u
        WHERE u.id = v_uid;
END $function$
;


-- ═══ FUNCTION get_my_gateway() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_my_gateway()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT public._gateway_masked(auth.uid()::text);
$function$
;


-- ═══ FUNCTION get_my_referral_code() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_my_referral_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid text := auth.uid()::text;
  v_code text;
  v_type text;
  v_try text;
  i integer := 0;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  SELECT u.referral_code, u.user_type INTO v_code, v_type
    FROM users u WHERE u.id = v_uid AND u.deleted_at IS NULL;
  IF NOT FOUND OR v_type NOT IN ('seller', 'admin') THEN RAISE EXCEPTION 'sellers only'; END IF;
  IF v_code IS NOT NULL THEN RETURN v_code; END IF;
  LOOP
    i := i + 1;
    v_try := upper(substr(md5(v_uid || clock_timestamp()::text || i::text), 1, 6));
    BEGIN
      UPDATE users SET referral_code = v_try, updated_at = now()
       WHERE id = v_uid AND referral_code IS NULL;
      EXIT;
    EXCEPTION WHEN unique_violation THEN
      IF i > 25 THEN RAISE; END IF;
    END;
  END LOOP;
  SELECT u.referral_code INTO v_code FROM users u WHERE u.id = v_uid;
  RETURN v_code;
END $function$
;


-- ═══ FUNCTION get_order_invoice(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_order_invoice(p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me  text := (SELECT auth.uid()::text);
  v_row public.order_invoices%ROWTYPE;
  v_vat text;
BEGIN
  IF v_me IS NULL THEN RETURN NULL; END IF;
  SELECT * INTO v_row FROM public.order_invoices WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN NULL; END IF;
  -- v15.80 ⑦ — والمشتري والتاجرُ لا يتأثّران: الفرعُ المُضيَّقُ هو فرعُ الأدمن
  --   وحده. و`enforcedAt` لـ`action_view_finance` يُسمّي `RLS order_invoices`.
  IF v_me <> COALESCE(v_row.buyer_id, '') AND v_me <> v_row.store_id
     AND NOT public.taki_admin_finance() THEN
    RETURN NULL;
  END IF;
  v_vat := NULLIF(btrim(COALESCE(v_row.seller->>'vat_number', '')), '');
  RETURN jsonb_build_object(
    'barcode',    v_row.barcode,
    'invoice_no', v_row.invoice_no,
    'issued_at',  v_row.issued_at,
    'currency',   v_row.currency,
    'total',      v_row.total,
    'vat_rate',   v_row.vat_rate,
    'vat_base',   v_row.vat_base,
    'vat_amount', v_row.vat_amount,
    'seller',     v_row.seller,
    'zatca_tlv',  CASE
                    WHEN v_row.vat_amount IS NULL OR v_vat IS NULL
                      OR COALESCE(v_row.total, 0) <= 0 THEN NULL
                    ELSE public.taki_zatca_tlv(
                           COALESCE(v_row.seller->>'name', ''),
                           v_vat,
                           to_char(COALESCE(v_row.issued_at, v_row.created_at, now())
                                     AT TIME ZONE 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS.MS"Z"'),
                           to_char(v_row.total,      'FM9999999990.00'),
                           to_char(v_row.vat_amount, 'FM9999999990.00'))
                  END);
END
$function$
;


-- ═══ FUNCTION get_pinned_store_ids(p_city text, p_mall text) INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.get_pinned_store_ids(p_city text DEFAULT NULL::text, p_mall text DEFAULT NULL::text)
 RETURNS text[]
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE(ARRAY_AGG(store_id ORDER BY rank ASC), ARRAY[]::TEXT[])
      FROM pinned_stores
     WHERE is_active = TRUE
       AND (target_city IS NULL OR target_city = p_city OR p_city IS NULL)
       AND (target_mall IS NULL OR target_mall = p_mall OR p_mall IS NULL)
       AND (ends_at IS NULL OR ends_at > NOW());
$function$
;


-- ═══ FUNCTION get_recent_activity(p_limit integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_recent_activity(p_limit integer DEFAULT 20)
 RETURNS TABLE(id bigint, user_id text, user_name text, user_type text, action text, entity_type text, entity_id text, metadata jsonb, created_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
BEGIN
    -- 🪤 `u.user_type` مؤهَّلاً: بلا التأهيل يلتبس بعمود الإخراج فتفشل الدالة
    --    كلّها — وهو ما كان يحدث.
    SELECT u.user_type INTO v_caller_role
      FROM public.users u
     WHERE u.id = auth.uid()::text;

    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Admin only';
    END IF;

    RETURN QUERY
    SELECT a.id, a.user_id, u.name, a.user_type, a.action,
           a.entity_type, a.entity_id, a.metadata, a.created_at
      FROM public.activity_log a
      LEFT JOIN public.users u ON u.id = a.user_id
     ORDER BY a.created_at DESC
     LIMIT p_limit;
END
$function$
;


-- ═══ FUNCTION get_setting(p_key text, p_default jsonb) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_setting(p_key text, p_default jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
    SELECT COALESCE((SELECT value FROM platform_settings WHERE key = p_key), p_default);
$function$
;


-- ═══ FUNCTION get_store_daily(p_store_id text, p_days integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_store_daily(p_store_id text, p_days integer DEFAULT 14)
 RETURNS TABLE(day date, views bigint, clicks bigint, bookings bigint)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
BEGIN
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF auth.uid()::text <> p_store_id AND v_caller_role <> 'admin' THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    RETURN QUERY
    SELECT (created_at AT TIME ZONE 'Asia/Riyadh')::date AS day,
           SUM(CASE WHEN event_type IN ('deal_view','page_view') THEN 1 ELSE 0 END)::bigint,
           SUM(CASE WHEN event_type = 'deal_click' THEN 1 ELSE 0 END)::bigint,
           SUM(CASE WHEN event_type = 'booking_completed' THEN 1 ELSE 0 END)::bigint
      FROM store_analytics_events
     WHERE store_id = p_store_id
       AND created_at >= NOW() - (p_days || ' days')::interval
     GROUP BY 1
     ORDER BY 1 DESC;
END;
$function$
;


-- ═══ FUNCTION get_store_funnel(p_store_id text, p_start timestamp with time zone, p_end timestamp with time zone) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.get_store_funnel(p_store_id text, p_start timestamp with time zone DEFAULT (now() - '30 days'::interval), p_end timestamp with time zone DEFAULT now())
 RETURNS TABLE(views bigint, clicks bigint, booking_started bigint, booking_abandoned bigint, booking_completed bigint, abandoned_rate numeric, conversion_rate numeric, unique_sessions bigint, avg_time_ms numeric)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
BEGIN
    -- The owning seller and admins can run this.
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF auth.uid()::text <> p_store_id AND v_caller_role <> 'admin' THEN
        RAISE EXCEPTION 'Forbidden';
    END IF;

    RETURN QUERY
    WITH ev AS (
        SELECT * FROM store_analytics_events
         WHERE store_id = p_store_id
           AND created_at BETWEEN p_start AND p_end
    ),
    cnt_v   AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type IN ('deal_view','page_view')),
    cnt_c   AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'deal_click'),
    cnt_bs  AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'booking_started'),
    cnt_ba  AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'booking_abandoned'),
    cnt_bc  AS (SELECT COUNT(*)::bigint AS n FROM ev WHERE event_type = 'booking_completed'),
    cnt_s   AS (SELECT COUNT(DISTINCT session_id)::bigint AS n FROM ev WHERE session_id IS NOT NULL),
    cnt_t   AS (SELECT COALESCE(AVG(duration_ms)::numeric,0) AS n FROM ev WHERE event_type = 'time_on_page')
    SELECT
        cnt_v.n, cnt_c.n, cnt_bs.n, cnt_ba.n, cnt_bc.n,
        CASE WHEN cnt_bs.n = 0 THEN 0 ELSE ROUND((cnt_ba.n::numeric / cnt_bs.n::numeric) * 100, 1) END,
        CASE WHEN cnt_c.n  = 0 THEN 0 ELSE ROUND((cnt_bc.n::numeric / cnt_c.n::numeric) * 100, 1) END,
        cnt_s.n, cnt_t.n
    FROM cnt_v, cnt_c, cnt_bs, cnt_ba, cnt_bc, cnt_s, cnt_t;
END;
$function$
;


-- ═══ FUNCTION grant_subscription_bulk(p_merchant_ids text[], p_grant_type text, p_duration_days integer, p_discount_percent numeric, p_reason text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.grant_subscription_bulk(p_merchant_ids text[], p_grant_type text, p_duration_days integer, p_discount_percent numeric DEFAULT 0, p_reason text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller_role TEXT;
    v_basic_plan_id TEXT;
    v_count INTEGER := 0;
    v_merchant TEXT;
    v_status TEXT;
    v_now TIMESTAMPTZ := NOW();
    v_period_end TIMESTAMPTZ;
BEGIN
  PERFORM public._admin_require_ctx();
    SELECT user_type INTO v_caller_role FROM users WHERE id = auth.uid()::text;
    IF v_caller_role IS DISTINCT FROM 'admin' THEN
        RAISE EXCEPTION 'Only admins can grant subscriptions';
    END IF;

    IF p_grant_type NOT IN ('free','discount') THEN
        RAISE EXCEPTION 'Invalid grant type: %', p_grant_type;
    END IF;

    IF p_duration_days IS NULL OR p_duration_days <= 0 THEN
        RAISE EXCEPTION 'Duration must be > 0 days';
    END IF;

    SELECT id INTO v_basic_plan_id FROM subscription_plans WHERE code = 'basic' LIMIT 1;
    v_period_end := v_now + (p_duration_days || ' days')::interval;
    v_status := CASE WHEN p_grant_type = 'free' THEN 'gifted' ELSE 'active' END;

    FOREACH v_merchant IN ARRAY p_merchant_ids LOOP
        -- Ensure a row exists, then update it.
        INSERT INTO merchant_subscriptions (merchant_id, plan_id, status, branches_count)
        VALUES (v_merchant, v_basic_plan_id, v_status, 1)
        ON CONFLICT (merchant_id) DO NOTHING;

        UPDATE merchant_subscriptions
        SET status = v_status,
            plan_id = COALESCE(plan_id, v_basic_plan_id),
            current_period_start = v_now,
            current_period_end = v_period_end,
            grant_expires_at = v_period_end,
            granted_by_admin = auth.uid()::text,
            grant_reason = p_reason,
            discount_percent = CASE WHEN p_grant_type = 'discount' THEN p_discount_percent ELSE 0 END,
            last_renewed_at = v_now,
            updated_at = v_now
        WHERE merchant_id = v_merchant;

        -- Ledger entry: 0 SAR for free, discounted price for discount.
        INSERT INTO subscription_payments (
            subscription_id, merchant_id, plan_id, amount, currency,
            status, payment_method, gateway_provider,
            period_start, period_end, branches_count, discount_percent, metadata
        )
        SELECT s.id, v_merchant, s.plan_id,
               CASE WHEN p_grant_type = 'free' THEN 0
                    ELSE compute_subscription_price(s.plan_id, s.branches_count, p_discount_percent) END,
               'SAR',
               CASE WHEN p_grant_type = 'free' THEN 'gifted' ELSE 'paid' END,
               'admin_grant', 'admin_grant',
               v_now, v_period_end, s.branches_count,
               COALESCE(p_discount_percent, 0),
               jsonb_build_object('reason', p_reason, 'granted_by', auth.uid()::text)
          FROM merchant_subscriptions s WHERE s.merchant_id = v_merchant;

        -- Notification to the merchant.
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (v_merchant,
            CASE WHEN p_grant_type = 'free' THEN '🎁 تم تفعيل اشتراك مجاني!'
                 ELSE '🎉 تم تفعيل خصم خاص على اشتراكك!' END,
            CASE WHEN p_grant_type = 'free' THEN '🎁 Free subscription activated!'
                 ELSE '🎉 Special discount activated on your subscription!' END,
            CASE WHEN p_grant_type = 'free'
                 THEN 'منحتك إدارة TAKI اشتراكاً مجانياً لمدة ' || p_duration_days || ' يوماً. ابدأ بنشر عروضك الآن! 💚'
                 ELSE 'حصلت على خصم ' || p_discount_percent || '% على الاشتراك لمدة ' || p_duration_days || ' يوماً.' END,
            CASE WHEN p_grant_type = 'free'
                 THEN 'TAKI granted you a free subscription for ' || p_duration_days || ' days. Start posting your deals now! 💚'
                 ELSE 'You received a ' || p_discount_percent || '% discount on the subscription for ' || p_duration_days || ' days.' END,
            'system',
            jsonb_build_object('grant_type', p_grant_type, 'duration_days', p_duration_days,
                               'discount_percent', p_discount_percent, 'reason', p_reason));

        v_count := v_count + 1;
    END LOOP;

    RETURN v_count;
END;
$function$
;


-- ═══ FUNCTION guard_booking_status() INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.guard_booking_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    old_rank INT;
    new_rank INT;
BEGIN
    old_rank := CASE OLD.status
        WHEN 'pending' THEN 0
        WHEN 'acknowledged' THEN 1
        WHEN 'completed' THEN 2
        WHEN 'cancelled' THEN 2
        ELSE 0
    END;
    new_rank := CASE NEW.status
        WHEN 'pending' THEN 0
        WHEN 'acknowledged' THEN 1
        WHEN 'completed' THEN 2
        WHEN 'cancelled' THEN 2
        ELSE 0
    END;

    -- Block any backward transition. Cancelled is terminal in the
    -- same rank as completed but they are NOT interchangeable.
    IF new_rank < old_rank THEN
        NEW.status := OLD.status;
    ELSIF OLD.status IN ('completed', 'cancelled') AND NEW.status <> OLD.status THEN
        NEW.status := OLD.status;
    END IF;

    -- Stamp completed_at the first time we transition INTO completed
    IF NEW.status = 'completed' AND OLD.status <> 'completed' THEN
        NEW.completed_at := NOW();
    END IF;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION guard_deal_publish() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.guard_deal_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller TEXT;
    v_role TEXT;
    v_active BOOLEAN;
BEGIN
    v_caller := auth.uid()::text;
    SELECT user_type INTO v_role FROM users WHERE id = v_caller;

    -- Admins bypass for support purposes.
    IF v_role = 'admin' THEN
        RETURN NEW;
    END IF;

    -- Existing rows being updated to a *non-active* status are always allowed.
    -- (Pause / expire / delete must work even after trial expiry.)
    IF TG_OP = 'UPDATE' AND NEW.status IN ('expired','deleted','paused') THEN
        RETURN NEW;
    END IF;

    -- Only block INSERTs and re-activations from frozen sellers.
    IF TG_OP = 'INSERT' OR (TG_OP = 'UPDATE' AND OLD.status <> 'active' AND NEW.status = 'active') THEN
        v_active := ensure_active_subscription(NEW.store_id);
        IF NOT v_active THEN
            RAISE EXCEPTION 'SUBSCRIPTION_REQUIRED: Merchant subscription is not active. Renew to publish new deals.'
                USING ERRCODE = 'P0001';
        END IF;
    END IF;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION guard_report_insert() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.guard_report_insert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_reporter_type TEXT;
    v_reported_type TEXT;
BEGIN
    IF NEW.reporter_id = NEW.reported_id THEN
        RAISE EXCEPTION 'SELF_REPORT_NOT_ALLOWED' USING ERRCODE = 'P0001';
    END IF;

    SELECT user_type INTO v_reporter_type FROM public.users WHERE id = NEW.reporter_id;
    SELECT user_type INTO v_reported_type FROM public.users WHERE id = NEW.reported_id;

    IF v_reporter_type IS NULL OR v_reported_type IS NULL THEN
        RAISE EXCEPTION 'INVALID_REPORT_PARTIES' USING ERRCODE = 'P0001';
    END IF;
    IF v_reporter_type NOT IN ('buyer','seller')
       OR v_reported_type NOT IN ('buyer','seller') THEN
        RAISE EXCEPTION 'REPORT_ROLE_NOT_ALLOWED' USING ERRCODE = 'P0001';
    END IF;
    IF v_reporter_type = v_reported_type THEN
        RAISE EXCEPTION 'SAME_ROLE_REPORT_BLOCKED' USING ERRCODE = 'P0001';
    END IF;

    -- Trust the DB, not the client: stamp the real roles.
    NEW.reporter_role := v_reporter_type;
    NEW.reported_role := v_reported_type;
    IF NEW.status IS NULL THEN NEW.status := 'open'; END IF;
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_auth_user_updated() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.handle_auth_user_updated()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.email IS DISTINCT FROM OLD.email
       AND NEW.email IS NOT NULL
       AND NEW.email_confirmed_at IS NOT NULL THEN
        UPDATE public.users SET email = NEW.email WHERE id = NEW.id::text;
    END IF;

    IF NEW.phone IS DISTINCT FROM OLD.phone
       AND NEW.phone IS NOT NULL
       AND NEW.phone_confirmed_at IS NOT NULL THEN
        BEGIN
            UPDATE public.users SET phone = NEW.phone WHERE id = NEW.id::text;
        EXCEPTION WHEN unique_violation THEN NULL;
        END;
    END IF;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_booking_message_notification() INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.handle_booking_message_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
    booking_row public.bookings;
    recipient text;
    item_name text;
    sender_name text;
    preview text;
BEGIN
    SELECT * INTO booking_row FROM public.bookings WHERE barcode = NEW.barcode;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;

    IF NEW.sender_role = 'buyer' THEN
        recipient := booking_row.store_id;
    ELSE
        recipient := booking_row.user_id;
    END IF;

    SELECT d.item_name INTO item_name FROM public.deals d WHERE d.id = booking_row.deal_id;
    item_name := COALESCE(item_name, 'العرض');

    SELECT COALESCE(NULLIF(u.name, ''), NULLIF(u.shop, ''), CASE NEW.sender_role WHEN 'buyer' THEN 'المشتري' ELSE 'التاجر' END)
    INTO sender_name FROM public.users u WHERE u.id = NEW.sender_id;

    preview := CASE WHEN length(NEW.body) > 80 THEN substring(NEW.body, 1, 77) || '…' ELSE NEW.body END;

    INSERT INTO public.notifications
        (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES
        (recipient,
         CASE WHEN NEW.sender_role = 'buyer'
              THEN '💬 رسالة جديدة من المشتري'
              ELSE '💬 رسالة جديدة من التاجر' END,
         CASE WHEN NEW.sender_role = 'buyer'
              THEN '💬 New message from buyer'
              ELSE '💬 New message from seller' END,
         sender_name || ' — ' || item_name || ': ' || preview,
         sender_name || ' — ' || item_name || ': ' || preview,
         'booking',
         jsonb_build_object(
             'audience',  CASE WHEN NEW.sender_role = 'buyer' THEN 'seller' ELSE 'buyer' END,
             'barcode',   NEW.barcode,
             'dealId',    booking_row.deal_id,
             'messageId', NEW.id,
             'isMessage', true
         ),
         NOW());

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_booking_notification() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_booking_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    item_name   TEXT;
    buyer_name  TEXT;
    seller_name TEXT;
    v_expired   boolean;
    v_now       bigint := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
BEGIN
    SELECT d.item_name INTO item_name FROM public.deals d WHERE d.id = NEW.deal_id;
    item_name := COALESCE(item_name, 'العرض');
    SELECT COALESCE(u.name, u.shop, '') INTO buyer_name FROM public.users u WHERE u.id = NEW.user_id;
    buyer_name := COALESCE(NULLIF(buyer_name, ''), 'مشتري');
    SELECT COALESCE(u.shop, u.name, '') INTO seller_name FROM public.users u WHERE u.id = NEW.store_id;
    seller_name := COALESCE(NULLIF(seller_name, ''), 'التاجر');

    IF TG_OP = 'INSERT' THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.store_id, '📦 طلب حجز جديد!', '📦 New Booking Request!',
            'طلب جديد من ' || buyer_name || ' لـ ' || item_name || ' (' || NEW.booked_quantity || ' قطعة).'
                || CASE WHEN NEW.prep_time IS NOT NULL AND NEW.prep_time <> '' THEN
                       ' 🕒 الوقت: ' || CASE WHEN NEW.prep_time = 'arrival' THEN 'عند الوصول' ELSE replace(NEW.prep_time,'min','') || ' دقيقة' END ELSE '' END
                || CASE WHEN NEW.notes IS NOT NULL AND NEW.notes <> '' THEN ' 📝 ' || NEW.notes ELSE '' END,
            'New order from ' || buyer_name || ' for ' || item_name || ' (' || NEW.booked_quantity || ' pcs).'
                || CASE WHEN NEW.prep_time IS NOT NULL AND NEW.prep_time <> '' THEN
                       ' 🕒 ETA: ' || CASE WHEN NEW.prep_time = 'arrival' THEN 'On arrival' ELSE replace(NEW.prep_time,'min','') || ' min' END ELSE '' END
                || CASE WHEN NEW.notes IS NOT NULL AND NEW.notes <> '' THEN ' 📝 ' || NEW.notes ELSE '' END,
            'booking',
            jsonb_build_object('audience','seller','event','new','barcode',NEW.barcode,'dealId',NEW.deal_id,'quantity',NEW.booked_quantity,'prepTime',NEW.prep_time,'notes',NEW.notes), NOW());

        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.user_id, '✅ تم الحجز بنجاح!', '✅ Booking Confirmed!',
            'تم حجز ' || item_name || ' — الرمز: ' || NEW.barcode || '. سيستلم التاجر طلبك قريباً.',
            item_name || ' booked — Code: ' || NEW.barcode || '. The seller will receive your order shortly.',
            'booking', jsonb_build_object('audience','buyer','event','new','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());

        -- v14.99 — بدل حلقةٍ تُدخل إشعاراً لكل أدمن: سطرٌ واحد في سجلّ العمليات.
        INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
        VALUES ((SELECT u.id FROM public.users u WHERE u.id = NEW.user_id), 'buyer',
                'booking_created', 'booking', NEW.barcode,
                jsonb_strip_nulls(jsonb_build_object(
                    'store_id', NEW.store_id, 'buyer_id', NEW.user_id, 'deal_id', NEW.deal_id,
                    'quantity', NEW.booked_quantity, 'amount', NEW.total_amount,
                    'event', 'new', 'source', NEW.source, 'fulfillment', NEW.fulfillment)));
        RETURN NEW;
    END IF;

    IF TG_OP = 'UPDATE' AND NEW.status IS DISTINCT FROM OLD.status THEN
        IF NEW.status = 'acknowledged' THEN
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.user_id, '📦 التاجر استلم طلبك!', '📦 Seller received your order!',
                'استلم ' || seller_name || ' طلبك لـ ' || item_name || ' وهو قيد التجهيز الآن.',
                seller_name || ' received your order for ' || item_name || ' and is preparing it now.',
                'booking', jsonb_build_object('audience','buyer','event','acknowledged','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());

        ELSIF NEW.status = 'completed' THEN
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.user_id, '🎉 تم تسليم طلبك!', '🎉 Order Delivered!',
                'تم تأكيد استلام ' || item_name || ' من ' || seller_name || '. شكراً لاستخدامك تاكي 💚',
                item_name || ' delivery confirmed by ' || seller_name || '. Thanks for using Taki 💚',
                'booking', jsonb_build_object('audience','buyer','event','completed','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.store_id, '🎉 تم الاستلام بنجاح!', '🎉 Order Delivered!',
                'استلم ' || buyer_name || ' طلب ' || item_name || ' — تم إغلاق الحجز.',
                buyer_name || ' received the order for ' || item_name || ' — booking closed.',
                'booking', jsonb_build_object('audience','seller','event','completed','barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());

            INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
            VALUES ((SELECT u.id FROM public.users u WHERE u.id = NEW.store_id), 'seller',
                    'booking_completed', 'booking', NEW.barcode,
                    jsonb_strip_nulls(jsonb_build_object(
                        'store_id', NEW.store_id, 'buyer_id', NEW.user_id, 'deal_id', NEW.deal_id,
                        'quantity', NEW.booked_quantity, 'amount', NEW.total_amount,
                        'event', 'completed', 'paid', (NEW.paid_at IS NOT NULL))));

        ELSIF NEW.status = 'cancelled' THEN
            -- v14.21 — إلغاءُ استردادٍ له رسائله الخاصّة من `resolve_booking_refund`
            -- (المبلغ والمرجع والإشعار الدائن). وهذا الفرع يحسب «انتهت المهلة» من
            -- `expiry_time`، والدفع لا يمسحه — فكان المشتري الذي رُدّ ماله يتلقّى
            -- فوق إشعار الردّ «⏰ انتهت مدة حجزك فأُلغي تلقائياً»، وهي كذبة، ويتلقّى
            -- التاجر «أُلغي دون استلام»، والإدارة «انتهاء حجز تلقائي».
            IF COALESCE(NEW.cancelled_by, '') = 'refund' THEN
                RETURN NEW;
            END IF;
            v_expired := (NEW.expiry_time IS NOT NULL AND NEW.expiry_time < v_now);
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.user_id,
                CASE WHEN v_expired THEN '⏰ انتهت مدة الحجز' ELSE '⚠️ تم إلغاء الحجز' END,
                CASE WHEN v_expired THEN '⏰ Booking expired' ELSE '⚠️ Booking Cancelled' END,
                CASE WHEN v_expired THEN 'انتهت مدة حجز ' || item_name || ' (ساعتان) فأُلغي تلقائياً وأُتيح العرض للآخرين.'
                     ELSE 'تم إلغاء حجز ' || item_name || '.' END,
                CASE WHEN v_expired THEN 'Your booking for ' || item_name || ' expired (2h window) and was auto-cancelled.'
                     ELSE 'Booking for ' || item_name || ' has been cancelled.' END,
                'booking', jsonb_build_object('audience','buyer','event', CASE WHEN v_expired THEN 'expired' ELSE 'cancelled' END,'barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());
            INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (NEW.store_id,
                CASE WHEN v_expired THEN '⏰ انتهى حجز دون استلام' ELSE '⚠️ تم إلغاء حجز' END,
                CASE WHEN v_expired THEN '⏰ Booking expired' ELSE '⚠️ Booking Cancelled' END,
                CASE WHEN v_expired THEN 'انتهت مدة حجز ' || item_name || ' من ' || buyer_name || ' دون استلام، وأُلغي تلقائياً.'
                     ELSE 'تم إلغاء حجز ' || item_name || ' من قِبل ' || buyer_name || '.' END,
                CASE WHEN v_expired THEN 'Booking for ' || item_name || ' by ' || buyer_name || ' expired without pickup and was auto-cancelled.'
                     ELSE buyer_name || ' cancelled the booking for ' || item_name || '.' END,
                'booking', jsonb_build_object('audience','seller','event', CASE WHEN v_expired THEN 'expired' ELSE 'cancelled' END,'barcode',NEW.barcode,'dealId',NEW.deal_id), NOW());

            INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
            VALUES (
                (SELECT u.id FROM public.users u WHERE u.id = CASE
                    WHEN v_expired THEN NULL
                    WHEN COALESCE(NEW.cancelled_by,'') = 'seller' THEN NEW.store_id
                    ELSE NEW.user_id END),
                CASE WHEN v_expired THEN 'system'
                     WHEN COALESCE(NEW.cancelled_by,'') = 'seller' THEN 'seller'
                     ELSE 'buyer' END,
                CASE WHEN v_expired THEN 'booking_expired' ELSE 'booking_cancelled' END,
                'booking', NEW.barcode,
                jsonb_strip_nulls(jsonb_build_object(
                    'store_id', NEW.store_id, 'buyer_id', NEW.user_id, 'deal_id', NEW.deal_id,
                    'quantity', NEW.booked_quantity, 'amount', NEW.total_amount,
                    'event', CASE WHEN v_expired THEN 'expired' ELSE 'cancelled' END,
                    'cancelled_by', NEW.cancelled_by)));
        END IF;
    END IF;
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_deal_smart_notifications() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_deal_smart_notifications()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    deal_region_id  TEXT;
    deal_city_id    TEXT;
    deal_lat        DOUBLE PRECISION;
    deal_lng        DOUBLE PRECISION;
    nearest_row     public.sa_cities_geo;
    rec             RECORD;
    now_ms          BIGINT;
    window_cutoff   BIGINT;
    blk_out         TEXT[];   -- v15.80 — من حجبهم هذا المتجر
    blk_in          TEXT[];   -- v15.80 — من حجبوا هذا المتجر
BEGIN
    IF NEW.status <> 'active' THEN
        RETURN NEW;
    END IF;

    now_ms        := (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT;
    window_cutoff := now_ms + (7 * 24 * 60 * 60 * 1000);  -- 7 days

    -- v11.21 — Hidden phase: deal scheduled further than 7 days out. Only
    -- the merchant who owns it knows about it; no buyer-side fan-out yet.
    -- The pg_cron job `taki_dispatch_coming_soon_window` will pick the
    -- row up as soon as starts_at crosses into the visibility window.
    IF NEW.starts_at IS NOT NULL AND NEW.starts_at > window_cutoff THEN
        RETURN NEW;
    END IF;

    deal_region_id := NEW.region;
    deal_city_id   := NEW.city;
    deal_lat       := NEW.map_lat;
    deal_lng       := NEW.map_lng;

    IF deal_region_id IS NULL OR deal_city_id IS NULL THEN
        SELECT l.city_id, c.region_id,
               COALESCE(deal_lat, l.lat),
               COALESCE(deal_lng, l.lng)
        INTO deal_city_id, deal_region_id, deal_lat, deal_lng
        FROM public.locations l
        LEFT JOIN public.cities c ON c.id = l.city_id
        WHERE l.id = NEW.location_id;
    END IF;

    IF (deal_region_id IS NULL OR deal_city_id IS NULL)
       AND deal_lat IS NOT NULL AND deal_lng IS NOT NULL
    THEN
        SELECT * INTO nearest_row FROM public.find_nearest_sa_city(deal_lat, deal_lng);
        IF nearest_row.city_id IS NOT NULL THEN
            deal_region_id := COALESCE(deal_region_id, nearest_row.region_id);
            deal_city_id   := COALESCE(deal_city_id,   nearest_row.city_id);
        END IF;
    END IF;

    -- v15.80 — الحجبُ في الاتجاهين، ومسحٌ واحدٌ لا واحدٌ لكلّ مستخدم.
    blk_out := ARRAY(SELECT ub.blocked_id FROM public.user_blocks ub WHERE ub.blocker_id = NEW.store_id);
    blk_in  := ARRAY(SELECT ub.blocker_id FROM public.user_blocks ub WHERE ub.blocked_id = NEW.store_id);

    FOR rec IN
        SELECT id, smart_alerts, followed_merchants
        FROM public.users
        WHERE id <> NEW.store_id
          AND deleted_at IS NULL
          -- v13.31 — لا تمرّ على كل مستخدمي المنصة: من لا تنبيهات لديه ولا
          -- يتابع هذا المتجر يخرج من taki_dispatch_smart_alert بـRETURN FALSE
          -- حتماً، فتمريره كان يُنفّذ taki_norm على نص العرض مرة لكل مستخدم
          -- (قِيس: ١٠.٦ ثانية عند ١٠٠ ألف مستخدم — التاجر ينتظرها عند كل إضافة).
          AND ( COALESCE(jsonb_array_length(smart_alerts), 0) > 0
             OR NEW.store_id = ANY(COALESCE(followed_merchants, ARRAY[]::text[])) )
          -- v15.80 — ووعدُ شاشةِ المتجر: «لن تصلك أي تنبيهات منه — حتى لو
          -- طابقت تنبيهك الذكي». كان نصّاً بلا شرط.
          AND NOT (id = ANY(blk_out))
          AND NOT (id = ANY(blk_in))
    LOOP
        PERFORM public.taki_dispatch_smart_alert(
            rec.id,
            rec.followed_merchants,
            rec.smart_alerts,
            NEW,
            deal_region_id, deal_city_id,
            deal_lat, deal_lng,
            FALSE
        );
    END LOOP;

    -- Mark notified so the cron dispatcher never re-fires on this row.
    -- We update directly via UPDATE (not by editing NEW) because AFTER
    -- INSERT triggers can't mutate NEW back to the row.
    UPDATE public.deals SET coming_soon_notified_at = now_ms WHERE id = NEW.id;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_deleted_user() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_deleted_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  DELETE FROM public.users WHERE id = OLD.id::text;
  RETURN OLD;
END;
$function$
;


-- ═══ FUNCTION handle_follow_notification() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_follow_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    added_merchant_id TEXT;
    buyer_name TEXT;
BEGIN
    SELECT elem INTO added_merchant_id
    FROM unnest(NEW.followed_merchants) AS elem
    WHERE elem NOT IN (SELECT unnest(COALESCE(OLD.followed_merchants, ARRAY[]::TEXT[])));

    IF added_merchant_id IS NOT NULL THEN
        -- Idempotency guard: one follow notification per
        -- (merchant, follower) per hour — kills the double-write race
        -- and quick unfollow/refollow spam without suppressing a
        -- genuine re-follow much later.
        IF EXISTS (
            SELECT 1 FROM public.notifications
            WHERE user_id = added_merchant_id
              AND type = 'follow'
              AND meta_data->>'followerId' = NEW.id
              AND created_at > NOW() - INTERVAL '1 hour'
        ) THEN
            RETURN NEW;
        END IF;

        buyer_name := COALESCE(NEW.name, 'مستخدم جديد');

        INSERT INTO public.notifications (
            user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at
        ) VALUES (
            added_merchant_id,
            '👥 متابع جديد!',
            '👥 New Follower!',
            'بدأ ' || buyer_name || ' بمتابعة محلك لمشاهدة أحدث عروضك.',
            buyer_name || ' started following your shop to see your latest deals.',
            'follow',
            jsonb_build_object('followerId', NEW.id),
            NOW()
        );
    END IF;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_new_complaint() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.handle_new_complaint()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE a RECORD; v_from text; v_body text;
BEGIN
  SELECT COALESCE(NULLIF(name,''), NULLIF(email,''), 'مستخدم') INTO v_from
  FROM public.users WHERE id = NEW.user_id;
  v_body := COALESCE(v_from, 'مستخدم') || ': ' || left(COALESCE(NEW.message, NEW.subject, ''), 160);

  FOR a IN SELECT id FROM public.users
           WHERE user_type = 'admin' AND deleted_at IS NULL
  LOOP
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (a.id, '📮 شكوى جديدة', '📮 New complaint', v_body, v_body, 'system',
            jsonb_build_object('audience','admin', 'complaintId', NEW.id,
                               'actionUrl', '/admin?tab=reports',
                               'action_url', '/admin?tab=reports'));
    -- البريد هو القناة الوحيدة التي تصل ناصر وهو خارج التطبيق وبلا إشعارات مثبَّتة.
    BEGIN
      PERFORM public.taki_queue_email(a.id, 'admin_complaint',
        '📮 شكوى جديدة على تاكي',
        '<div dir="rtl" style="font-family:system-ui"><h2>📮 شكوى جديدة</h2><p>'
        || coalesce(v_body,'') || '</p><p><a href="https://www.takisa.net/admin?tab=reports">فتح لوحة البلاغات</a></p></div>');
    EXCEPTION WHEN others THEN NULL;  -- تعذّر البريد لا يمنع الشكوى من الوصول
    END;
  END LOOP;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION handle_new_seller_trial() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_new_seller_trial()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_trial_days INT;
    v_amount NUMERIC;
    v_max INT := NULL;
    v_pkg jsonb := NULL;
    v_existing_plan TEXT;
BEGIN
    IF NEW.user_type IS DISTINCT FROM 'seller' THEN
        RETURN NEW;
    END IF;

    BEGIN
        SELECT (value::text)::int INTO v_trial_days
        FROM platform_settings WHERE key = 'trial_days';
    EXCEPTION WHEN OTHERS THEN v_trial_days := NULL;
    END;
    v_trial_days := COALESCE(NULLIF(v_trial_days, 0), 14);

    -- Unified source (v12.35): the default package in the الباقات catalogue.
    BEGIN
        SELECT p INTO v_pkg
        FROM platform_settings ps, jsonb_array_elements(ps.value) p
        WHERE ps.key = 'location_packages'
          AND (p->>'id')::int = (SELECT (value::text)::int FROM platform_settings WHERE key = 'default_package_id')
          AND COALESCE((p->>'active')::boolean, true)
        LIMIT 1;
    EXCEPTION WHEN OTHERS THEN v_pkg := NULL;
    END;

    IF v_pkg IS NOT NULL THEN
        v_amount := round(COALESCE((v_pkg->>'price')::numeric, 0)
                          * (1 - COALESCE((v_pkg->>'discount')::numeric, 0) / 100), 2);
        v_max := (v_pkg->>'max')::int;
    ELSE
        -- Legacy fallback if the catalogue/setting is missing.
        BEGIN
            SELECT (value::text)::numeric INTO v_amount
            FROM platform_settings WHERE key = 'basic_plan_price_sar';
        EXCEPTION WHEN OTHERS THEN v_amount := NULL;
        END;
        v_amount := COALESCE(v_amount, 199);
    END IF;

    SELECT subscription_plan INTO v_existing_plan
    FROM store_profiles WHERE store_id = NEW.id;

    IF v_existing_plan IN ('premium', 'trial') THEN
        RETURN NEW;
    END IF;

    INSERT INTO store_profiles (
        store_id,
        subscription_plan,
        subscription_amount,
        subscription_started_at,
        subscription_expires_at,
        discount_percentage,
        max_branches
    )
    VALUES (
        NEW.id,
        'trial',
        v_amount,
        NOW(),
        NOW() + (v_trial_days || ' days')::INTERVAL,
        0,
        COALESCE(v_max, 3)
    )
    ON CONFLICT (store_id) DO UPDATE SET
        subscription_plan = 'trial',
        subscription_amount = EXCLUDED.subscription_amount,
        subscription_started_at = EXCLUDED.subscription_started_at,
        subscription_expires_at = EXCLUDED.subscription_expires_at,
        discount_percentage = 0,
        max_branches = COALESCE(v_max, store_profiles.max_branches);

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_new_user() DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_new_user()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_src text;
  v_detail text;
  v_code text;
  v_ref_store text;
  v_requested text;
  v_type text;
  v_lang text;
BEGIN
  v_src    := NULLIF(btrim(coalesce(new.raw_user_meta_data->>'referral_source', '')), '');
  v_detail := NULLIF(btrim(coalesce(new.raw_user_meta_data->>'referral_source_detail', '')), '');
  v_code   := NULLIF(btrim(coalesce(new.raw_user_meta_data->>'referred_by_code', '')), '');
  IF v_code IS NOT NULL THEN
    SELECT u.id INTO v_ref_store FROM public.users u
     WHERE u.referral_code IS NOT NULL AND upper(u.referral_code) = upper(v_code)
     LIMIT 1;
    IF v_ref_store IS NOT NULL THEN v_src := 'store'; END IF;
  END IF;

  -- v13.42: whitelist. Never let signup metadata name a privileged role.
  v_requested := lower(btrim(coalesce(new.raw_user_meta_data->>'user_type', '')));
  v_type := CASE WHEN v_requested IN ('buyer', 'seller') THEN v_requested ELSE 'buyer' END;

  -- v13.92: لغة الواجهة وقت التسجيل. أي قيمة غير 'en' تُعامَل عربية.
  v_lang := CASE WHEN lower(btrim(coalesce(new.raw_user_meta_data->>'lang', ''))) = 'en'
                 THEN 'en' ELSE 'ar' END;

  INSERT INTO public.users (id, email, phone, name, user_type, shop,
                            referral_source, referral_source_detail, referred_by_store,
                            preferred_lang)
  VALUES (
    new.id::text,
    new.email,
    new.raw_user_meta_data->>'phone',
    COALESCE(new.raw_user_meta_data->>'name', 'مستخدم'),
    v_type,
    new.raw_user_meta_data->>'shop',
    v_src, v_detail, v_ref_store,
    v_lang
  )
  ON CONFLICT (id) DO NOTHING;
  RETURN new;
END;
$function$
;


-- ═══ FUNCTION handle_new_user_admin_alert() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_new_user_admin_alert()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    admin_id    TEXT;
    label_ar    TEXT;
    label_en    TEXT;
    display     TEXT;
BEGIN
    label_ar := CASE NEW.user_type
        WHEN 'seller' THEN 'بائع جديد انضم'
        WHEN 'admin'  THEN 'مدير جديد أُضيف'
        ELSE 'مشترٍ جديد سجّل'
    END;
    label_en := CASE NEW.user_type
        WHEN 'seller' THEN 'New seller joined'
        WHEN 'admin'  THEN 'New admin added'
        ELSE 'New buyer signed up'
    END;
    display := COALESCE(NULLIF(NEW.shop, ''), NULLIF(NEW.name, ''), NULLIF(NEW.phone, ''), 'مستخدم');

    FOR admin_id IN SELECT id FROM public.users WHERE user_type = 'admin' AND id <> NEW.id LOOP
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (
            admin_id,
            '👤 ' || label_ar,
            '👤 ' || label_en,
            display || ' انضم للمنصة الآن.',
            display || ' just joined the platform.',
            'system',
            jsonb_build_object('userId', NEW.id, 'userType', NEW.user_type, 'admin', true),
            NOW()
        );
    END LOOP;
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_notification_push() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_notification_push()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_url    text;
  v_secret text;
BEGIN

  -- لا مشترك = لا نداء. يوفّر نداءً لكل إشعار لمستخدم بلا جهاز مسجَّل،
  -- وهي الحالة الغالبة اليوم (١١٧٧ إشعاراً مقابل صفر اشتراك).
  -- 🔴 v15.81 — **ويُسأل الجدولان**: تطبيقُ المتجر لا يستلم Web Push
  --    إطلاقاً، فرمزُ الجهاز هو قناتُه الوحيدة. وبسؤال جدولٍ واحدٍ كان
  --    مستخدمُ التطبيق يُستبعَد عند الباب.
  IF NOT EXISTS (SELECT 1 FROM public.push_subscriptions  WHERE user_id = NEW.user_id)
 AND NOT EXISTS (SELECT 1 FROM public.device_push_tokens WHERE user_id = NEW.user_id) THEN
    RETURN NEW;
  END IF;

  -- 🔴 v15.51 — الخزنةُ تُقرأ **بعد** الفحص لا قبله: بثٌّ لمليون مستخدمٍ
  --    كان يقرأ سرّين لكلّ صفّ (مليونا قراءة) قبل أن يسأل إن كان لصاحبه
  --    جهازٌ مسجَّل أصلاً. والفحصُ فهرسٌ على user_id، والقراءةُ أغلى منه.
  BEGIN
    SELECT value INTO v_url    FROM public.app_secrets WHERE key = 'push_url';
    SELECT value INTO v_secret FROM public.app_secrets WHERE key = 'push_shared_secret';
  EXCEPTION WHEN OTHERS THEN
    RETURN NEW;   -- الخزنة غير متاحة: لا نُسقط الإشعار نفسه أبداً
  END;
  IF coalesce(v_url, '') = '' OR coalesce(v_secret, '') = '' THEN
    RETURN NEW;
  END IF;

  BEGIN
    PERFORM net.http_post(
      url := v_url,
      body := jsonb_build_object(
        'userId',  NEW.user_id,
        'titleAr', NEW.title_ar,
        'titleEn', NEW.title_en,
        'bodyAr',  NEW.body_ar,
        'bodyEn',  NEW.body_en,
        'type',    NEW.type,
        'data',    NEW.meta_data,
        'notifId', NEW.id
      ),
      headers := jsonb_build_object(
        'Content-Type',  'application/json',
        'x-push-secret', v_secret
      ),
      timeout_milliseconds := 5000
    );
  EXCEPTION WHEN OTHERS THEN
    -- إشعارٌ في القاعدة أهمّ من دفعةٍ فشلت: لا تُجهض الإدراج أبداً.
    NULL;
  END;
  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_rating_notification() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_rating_notification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_store_id  TEXT;
    v_item_name TEXT;
    v_buyer     TEXT;
BEGIN
    SELECT d.store_id, d.item_name INTO v_store_id, v_item_name
    FROM public.deals d WHERE d.id = NEW.deal_id;

    v_item_name := COALESCE(NULLIF(v_item_name, ''), 'منتجك');
    v_buyer     := COALESCE(NULLIF(NEW.user_name, ''), 'عميل');

    IF v_store_id IS NOT NULL THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (
            v_store_id,
            '⭐ تقييم جديد لمتجرك!',
            '⭐ New rating for your store!',
            'قام ' || v_buyer || ' بتقييم ' || v_item_name || ' بـ ' || NEW.score || ' من 5'
                || CASE WHEN NEW.comment IS NOT NULL AND NEW.comment <> '' THEN ' — «' || NEW.comment || '»' ELSE '' END,
            v_buyer || ' rated ' || v_item_name || ' ' || NEW.score || '/5'
                || CASE WHEN NEW.comment IS NOT NULL AND NEW.comment <> '' THEN ' — "' || NEW.comment || '"' ELSE '' END,
            'rating',
            jsonb_build_object('audience', 'seller', 'dealId', NEW.deal_id, 'ratingId', NEW.id, 'score', NEW.score),
            NOW()
        );
    END IF;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_report_threshold() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_report_threshold()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_distinct      INT;
    v_under_review  BOOLEAN;
    v_admin_id      TEXT;
    v_reported_name TEXT;
BEGIN
    SELECT COUNT(DISTINCT reporter_id) INTO v_distinct
    FROM public.reports
    WHERE reported_id = NEW.reported_id
      AND status <> 'dismissed'
      AND created_at > NOW() - INTERVAL '14 days';

    SELECT COALESCE(under_review, false) INTO v_under_review
    FROM public.users WHERE id = NEW.reported_id;

    IF v_distinct >= 3 AND COALESCE(v_under_review, false) = false THEN
        UPDATE public.users
        SET under_review = true, under_review_at = NOW()
        WHERE id = NEW.reported_id;

        SELECT COALESCE(NULLIF(name,''), shop, 'حساب') INTO v_reported_name
        FROM public.users WHERE id = NEW.reported_id;

        FOR v_admin_id IN
            SELECT id FROM public.users
            WHERE user_type = 'admin' AND COALESCE(deleted_at::text,'') = ''
        LOOP
            INSERT INTO public.notifications
                (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
            VALUES (
                v_admin_id,
                '🚩 حساب تحت المراجعة — بلاغات متعددة',
                '🚩 Account under review — multiple reports',
                'تلقّى «' || COALESCE(v_reported_name,'حساب') || '» ' || v_distinct
                    || ' بلاغات من أشخاص مختلفين خلال 14 يوماً. راجِع مركز البلاغات في لوحة الأدمن.',
                'Account "' || COALESCE(v_reported_name,'account') || '" received ' || v_distinct
                    || ' reports from distinct users within 14 days. Review the admin Reports center.',
                'report',
                jsonb_build_object(
                    'audience','admin','admin',true,
                    'reportedId',NEW.reported_id,'reportedRole',NEW.reported_role,
                    'distinctReporters',v_distinct
                ),
                NOW()
            );
        END LOOP;
    END IF;
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION handle_smart_alerts_backfill() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.handle_smart_alerts_backfill()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    deal_rec        public.deals;
    deal_region_id  TEXT;
    deal_city_id    TEXT;
    deal_lat        DOUBLE PRECISION;
    deal_lng        DOUBLE PRECISION;
    nearest_row     public.sa_cities_geo;
    has_new_rules   BOOLEAN;
    cutoff_ms       BIGINT;
BEGIN
    IF NEW.smart_alerts IS NULL
       OR jsonb_typeof(NEW.smart_alerts) <> 'array'
       OR jsonb_array_length(NEW.smart_alerts) = 0
    THEN
        RETURN NEW;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM jsonb_array_elements(NEW.smart_alerts) AS new_rule
        WHERE NOT EXISTS (
            SELECT 1 FROM jsonb_array_elements(COALESCE(OLD.smart_alerts, '[]'::jsonb)) AS old_rule
            WHERE old_rule = new_rule
        )
    ) INTO has_new_rules;
    IF NOT has_new_rules THEN
        RETURN NEW;
    END IF;

    cutoff_ms := (EXTRACT(EPOCH FROM (NOW() - INTERVAL '7 days')) * 1000)::BIGINT;

    FOR deal_rec IN
        SELECT * FROM public.deals
        WHERE status = 'active'
          AND created_at > cutoff_ms
          AND store_id <> NEW.id
          AND NOT (store_id = ANY(COALESCE(NEW.blocked_merchants, ARRAY[]::TEXT[])))
        ORDER BY created_at DESC
        LIMIT 200
    LOOP
        deal_region_id := deal_rec.region;
        deal_city_id   := deal_rec.city;
        deal_lat       := deal_rec.map_lat;
        deal_lng       := deal_rec.map_lng;

        IF deal_region_id IS NULL OR deal_city_id IS NULL THEN
            SELECT l.city_id, c.region_id,
                   COALESCE(deal_lat, l.lat),
                   COALESCE(deal_lng, l.lng)
            INTO deal_city_id, deal_region_id, deal_lat, deal_lng
            FROM public.locations l
            LEFT JOIN public.cities c ON c.id = l.city_id
            WHERE l.id = deal_rec.location_id;
        END IF;
        IF (deal_region_id IS NULL OR deal_city_id IS NULL)
           AND deal_lat IS NOT NULL AND deal_lng IS NOT NULL
        THEN
            SELECT * INTO nearest_row FROM public.find_nearest_sa_city(deal_lat, deal_lng);
            IF nearest_row.city_id IS NOT NULL THEN
                deal_region_id := COALESCE(deal_region_id, nearest_row.region_id);
                deal_city_id   := COALESCE(deal_city_id,   nearest_row.city_id);
            END IF;
        END IF;

        PERFORM public.taki_dispatch_smart_alert(
            NEW.id,
            NEW.followed_merchants,
            NEW.smart_alerts,
            deal_rec,
            deal_region_id, deal_city_id,
            deal_lat, deal_lng,
            TRUE
        );
    END LOOP;

    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION has_admin_permission(perm text, uid text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.has_admin_permission(perm text, uid text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  target_uid TEXT;
  is_super BOOLEAN;
  perms TEXT[];
BEGIN
  target_uid := COALESCE(uid, auth.uid()::text);
  IF target_uid IS NULL OR perm IS NULL OR perm = '' THEN RETURN FALSE; END IF;
  SELECT u.is_super_admin, u.admin_permissions
    INTO is_super, perms
  FROM public.users u
  WHERE u.id = target_uid
    AND u.user_type = 'admin'
    AND u.deleted_at IS NULL;          -- v15.79
  IF NOT FOUND THEN RETURN FALSE; END IF;
  IF COALESCE(is_super, FALSE) THEN RETURN TRUE; END IF;
  RETURN perm = ANY(COALESCE(perms, '{}'::TEXT[]));
END;
$function$
;


-- ═══ FUNCTION increment_deal_click(target_deal_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.increment_deal_click(target_deal_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_store text;
BEGIN
    UPDATE public.deals
       SET clicks = COALESCE(clicks, 0) + 1
     WHERE id = target_deal_id
    RETURNING store_id INTO v_store;
    IF v_store IS NOT NULL THEN
        INSERT INTO public.analytics_events (kind, user_id, store_id, deal_id)
        VALUES ('deal_click', auth.uid()::text, v_store, target_deal_id);
    END IF;
END;
$function$
;


-- ═══ FUNCTION increment_deal_view(target_deal_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.increment_deal_view(target_deal_id text)
