-- ═══ FUNCTION increment_sponsorship_metric(p_id text, p_metric text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.increment_sponsorship_metric(p_id text, p_metric text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF p_metric = 'impression' THEN
        UPDATE sponsorships SET impressions = impressions + 1 WHERE id = p_id;
    ELSIF p_metric = 'click' THEN
        UPDATE sponsorships SET clicks = clicks + 1 WHERE id = p_id;
    ELSE
        RAISE EXCEPTION 'Invalid metric: %', p_metric;
    END IF;
END;
$function$
;


-- ═══ FUNCTION invoice_customer_details(p_merchant_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.invoice_customer_details(p_merchant_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_me text := auth.uid()::text; v_out jsonb;
begin
  if v_me is null then return null; end if;
  -- v15.80 ⑦ — ومنادي الأدمن هو `src/pages/admin/AdminTax.tsx:84` لأيّ تاجر،
  --   و`tab_launch` هو ما يفتح «الزكاة والضريبة» بنصّ الكتالوج.
  if v_me <> p_merchant_id and not public.taki_admin_finance() then return null; end if;

  select jsonb_build_object(
    'name',    coalesce(nullif(u.shop,''), u.name),
    'vat',     nullif(sp.vat_number,''),
    'cr',      nullif(sp.cr_number,''),
    'address', coalesce(nullif(sp.address,''), nullif(u.address,'')),
    'email',   coalesce(nullif(sp.email,''), nullif(u.email,'')),
    'phone',   coalesce(nullif(sp.phone,''), nullif(u.contact_phone,''), nullif(u.phone,''))
  ) into v_out
  from users u left join store_profiles sp on sp.store_id = u.id
  where u.id = p_merchant_id;

  return v_out;
end
$function$
;


-- ═══ FUNCTION is_admin(uid text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.is_admin(uid text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    target_uid TEXT;
    found      BOOLEAN;
    v_ctx      TEXT;
    v_perm     TEXT;
    v_super    BOOLEAN;
    v_perms    TEXT[];
BEGIN
    target_uid := COALESCE(uid, auth.uid()::text);
    IF target_uid IS NULL THEN
        RETURN FALSE;
    END IF;

    SELECT EXISTS (
        SELECT 1 FROM public.users
        WHERE id = target_uid AND user_type = 'admin'
    ) INTO found;
    IF NOT found THEN
        RETURN FALSE;
    END IF;

    -- v13.46: which admin_* RPC are we gating for, if any?
    GET DIAGNOSTICS v_ctx = PG_CONTEXT;

    SELECT r.required_perm INTO v_perm
      FROM public.admin_rpc_permissions r
     WHERE v_ctx ~ ('function ' || r.rpc_name || '\(')
     LIMIT 1;

    -- No admin_* frame on the stack (an RLS policy, a trigger, a plain call):
    -- behave exactly as before.
    IF v_perm IS NULL THEN
        RETURN TRUE;
    END IF;

    SELECT u.is_super_admin, u.admin_permissions
      INTO v_super, v_perms
      FROM public.users u
     WHERE u.id = target_uid;

    IF COALESCE(v_super, FALSE) THEN
        RETURN TRUE;
    END IF;

    RETURN v_perm = ANY(COALESCE(v_perms, '{}'::TEXT[]));
END;
$function$
;


-- ═══ FUNCTION is_super_admin(uid text) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.is_super_admin(uid text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  target_uid TEXT;
  found BOOLEAN;
BEGIN
  target_uid := COALESCE(uid, auth.uid()::text);
  IF target_uid IS NULL THEN RETURN FALSE; END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = target_uid
      AND u.user_type = 'admin'
      AND u.is_super_admin = TRUE
      AND u.deleted_at IS NULL         -- v15.79
  ) INTO found;
  RETURN found;
END;
$function$
;


-- ═══ FUNCTION log_activity(p_action text, p_entity_type text, p_entity_id text, p_metadata jsonb) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.log_activity(p_action text, p_entity_type text DEFAULT NULL::text, p_entity_id text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_user_id TEXT;
    v_user_type TEXT;
BEGIN
    v_user_id := auth.uid()::text;
    SELECT user_type INTO v_user_type FROM users WHERE id = v_user_id;

    INSERT INTO activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
    VALUES (v_user_id, v_user_type, p_action, p_entity_type, p_entity_id, p_metadata);
END $function$
;


-- ═══ FUNCTION log_moderation_flag(p_source text, p_content text, p_matched text[]) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.log_moderation_flag(p_source text, p_content text, p_matched text[] DEFAULT NULL::text[])
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid text := auth.uid()::text;
  v_type text; v_shop text; v_name text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  IF p_source NOT IN ('upload','chat','rating','deal') THEN RAISE EXCEPTION 'bad source'; END IF;
  SELECT u.user_type, u.shop, u.name INTO v_type, v_shop, v_name FROM users u WHERE u.id = v_uid;
  INSERT INTO moderation_flags (kind, source, store_id, offender_id, offender_name, content, matched)
  VALUES ('image', p_source,
          CASE WHEN v_type IN ('seller','admin') AND v_shop IS NOT NULL THEN v_uid ELSE NULL END,
          v_uid, coalesce(v_shop, v_name), left(coalesce(p_content,''), 500), p_matched);
END $function$
;


-- ═══ FUNCTION lookup_booking_by_code(p_code text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.lookup_booking_by_code(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_code text := upper(btrim(translate(COALESCE(p_code, ''), '٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹', '01234567890123456789')));
  v_b    public.bookings%ROWTYPE;
  v_role text;
BEGIN
  -- جوابٌ واحد لكل حالات الفشل: لا يفرّق المستمع بين «غير موجود» و«ليس لك».
  IF v_uid IS NULL OR v_code = '' OR length(v_code) > 32 THEN
    RETURN jsonb_build_object('found', false);
  END IF;

  SELECT * INTO v_b FROM public.bookings
  WHERE upper(barcode) = v_code OR upper(backup_code) = v_code
  LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('found', false); END IF;

  IF    v_uid = v_b.store_id THEN v_role := 'seller';
  ELSIF v_uid = v_b.user_id  THEN v_role := 'buyer';
  ELSIF public.is_admin()    THEN v_role := 'admin';
  ELSE  RETURN jsonb_build_object('found', false);
  END IF;

  RETURN jsonb_build_object('found', true,
                            'booking', public._booking_card(v_b.barcode, v_role));
END $function$
;


-- ═══ FUNCTION mark_booking_messages_read(p_barcode text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.mark_booking_messages_read(p_barcode text)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    caller text := auth.uid()::text;
    booking_row public.bookings;
    role text;
    updated_count int;
BEGIN
    IF caller IS NULL THEN
        RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
    END IF;
    SELECT * INTO booking_row FROM public.bookings WHERE barcode = p_barcode;
    IF NOT FOUND THEN
        RETURN 0;
    END IF;

    IF caller = booking_row.user_id THEN
        role := 'buyer';
    ELSIF caller = booking_row.store_id THEN
        role := 'seller';
    ELSE
        RETURN 0;
    END IF;

    UPDATE public.booking_messages
    SET read_at = NOW()
    WHERE barcode = p_barcode
      AND sender_role <> role
      AND read_at IS NULL;
    GET DIAGNOSTICS updated_count = ROW_COUNT;
    RETURN updated_count;
END;
$function$
;


-- ═══ FUNCTION merchant_accept_gateway_agreement() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_accept_gateway_agreement()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := auth.uid()::text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  UPDATE public.merchant_gateways
  SET agreement_accepted_at = COALESCE(agreement_accepted_at, now()), updated_at = now()
  WHERE merchant_id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'seller', 'gateway_agreement_accepted', 'merchant_gateway', v_uid, '{}'::jsonb);
  RETURN public.get_my_gateway();
END $function$
;


-- ═══ FUNCTION merchant_clear_field_map(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_clear_field_map(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  -- 🪤 ويُعاد الوسمُ إلى `UNMAPPED` إن كانت هناك حمولةٌ محفوظة، فيظهر المحرّرُ
  --    مرّةً أخرى بالرسالة الحقيقية أمام التاجر. وإلّا فلا وسم.
  UPDATE public.stock_integrations
     SET field_map = NULL,
         last_note = CASE WHEN last_payload IS NOT NULL THEN 'UNMAPPED' ELSE NULL END
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION merchant_create_integration(p_provider text, p_segment text, p_label text, p_webhook_url text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_create_integration(p_provider text, p_segment text DEFAULT NULL::text, p_label text DEFAULT NULL::text, p_webhook_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_key text; v_sec text; v_id uuid;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  -- v15.20 seller — كان مفتوحاً لأيّ مستخدمٍ موثَّق بما فيهم المشترون.
  --   و`<> 'buyer'` لا `= 'seller'`: متجرُ تاكي مملوكٌ لحساب أدمن.
  IF NOT EXISTS (SELECT 1 FROM public.users u
                  WHERE u.id = v_me AND COALESCE(u.user_type,'buyer') <> 'buyer'
                    AND u.deleted_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SELLERS_ONLY');
  END IF;
  IF EXISTS (SELECT 1 FROM public.stock_integrations s WHERE s.store_id = v_me) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_LINKED',
      'hint', 'delete or rotate the existing link instead of creating a second one');
  END IF;
  IF p_webhook_url IS NOT NULL AND p_webhook_url !~ '^https://' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'HTTPS_REQUIRED');
  END IF;
  -- v15.80 ③ — وشكلُ المضيف فوق ذلك: `https` وحده يسمح بـ`https://127.0.0.1/`
  IF p_webhook_url IS NOT NULL AND NOT public._taki_hook_url_ok(p_webhook_url) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'WEBHOOK_URL_REJECTED',
      'hint', 'use a public DNS host over https on port 443 — no IP address, no port, no credentials in the URL');
  END IF;
  -- 🪤 يُولَّد على الخادم: مفتاحٌ يمرّ عبر متصفّحٍ أو محادثةٍ صار معروفاً.
  v_key := 'taki_' || encode(extensions.gen_random_bytes(24), 'hex');
  v_sec := encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO public.stock_integrations
    -- v15.23 readonly — الاتجاهُ يُحسم عند الإنشاء: مزوّدٌ نقرأ منه يُنشأ
  --   بـ`in` فقط (قرارُ المالك)، وغيرُه يبقى `both` كما كان.
  (store_id, provider, segment, label, api_key_hash, api_key_last4, webhook_url, webhook_secret, webhook_slug, direction)
  VALUES (v_me, COALESCE(NULLIF(btrim(p_provider),''),'custom'), NULLIF(btrim(p_segment),''),
          NULLIF(btrim(p_label),''),
          encode(extensions.digest(v_key,'sha256'),'hex'), right(v_key, 4),
          NULLIF(btrim(p_webhook_url),''), v_sec,
          encode(extensions.gen_random_bytes(18), 'hex'),
          CASE WHEN public._taki_provider_read(COALESCE(NULLIF(btrim(p_provider),''),'custom')) IS NOT NULL
               THEN 'in' ELSE 'both' END)
  RETURNING id INTO v_id;
  -- 🔴 المفتاحُ يُعاد **مرّةً واحدة فقط** ولا يمكن استرجاعُه بعدها.
  RETURN jsonb_build_object('ok', true, 'id', v_id, 'api_key', v_key,
    'webhook_secret', v_sec, 'shown_once', true,
    'endpoint', 'https://api.takisa.net/rest/v1/rpc/taki_stock_push',
    'hook_url', 'https://api.takisa.net/functions/v1/stock-webhook/h/'
               || (SELECT webhook_slug FROM public.stock_integrations WHERE id = v_id));
END
$function$
;


-- ═══ FUNCTION merchant_delete_integration(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_delete_integration(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text; v_n int;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  SELECT count(*) INTO v_n FROM public.stock_links WHERE integration_id = p_id;
  -- الروابطُ وصندوقُ الوارد يُحذفان بالتتالي (ON DELETE CASCADE)، والأحداثُ
  -- الصادرة **تبقى** لأنها سجلٌّ لما جرى لا ملكٌ للاتصال.
  DELETE FROM public.stock_integrations WHERE id = p_id;
  RETURN jsonb_build_object('ok', true, 'unlinked', v_n);
END
$function$
;


-- ═══ FUNCTION merchant_handover_booking(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_handover_booking(p_barcode text)
 RETURNS bookings
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_b    public.bookings%ROWTYPE;
  v_left integer;
  v_anchor bigint;
  v_out  public.bookings;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'يجب تسجيل الدخول' USING ERRCODE = '28000';
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND OR v_b.store_id IS DISTINCT FROM v_uid THEN
    RAISE EXCEPTION 'لم يتم العثور على الطلب أو ليست لديك صلاحية' USING ERRCODE = 'P0001', HINT = 'P0002';
  END IF;

  IF v_b.status NOT IN ('pending','acknowledged') THEN
    RAISE EXCEPTION 'الطلب مغلق بالفعل' USING ERRCODE = 'P0001';
  END IF;

  -- 🔴 v15.44 (أمرُ ناصر) — الساعةُ تبدأ من **تأكيد التاجر**؛ وإن لم يؤكّد
  --    فتحةٌ احتياطيّة في آخر المهلة كي لا تبقى المشترية بلا مخرج (١٤٪ من
  --    الطلبات المكتملة لم تُؤكَّد قطّ — قِيس). والرمزُ يفرّق **سببَ** الانتظار
  --    فتقول الشاشةُ الصدق: أتنتظرُ شخصاً أم وقتاً.
  v_anchor := public.taki_self_close_opens_at(v_b);
  v_left := ceil((v_anchor - (EXTRACT(EPOCH FROM NOW())*1000)::bigint) / 1000.0);
  IF v_left > 0 AND v_b.acknowledged_at IS NULL AND v_b.status <> 'acknowledged' THEN
    RAISE EXCEPTION 'اضغط «تأكيد استلام الطلب» أوّلاً — ومن تلك اللحظة تبدأ المهلة'
      USING ERRCODE = 'P0001', HINT = 'P0029', DETAIL = v_left::text;
  END IF;
  IF v_left > 0 THEN
    RAISE EXCEPTION 'لم تمضِ المهلة بعد — واستلامُ الكود يعمل الآن بلا انتظار'
      USING ERRCODE = 'P0001', HINT = 'P0028', DETAIL = v_left::text;
  END IF;

  UPDATE public.bookings
     SET status = 'completed', completed_by = 'seller'
   WHERE barcode = v_b.barcode
     AND status IN ('pending','acknowledged')
  RETURNING * INTO v_out;

  IF v_out.barcode IS NULL THEN
    RAISE EXCEPTION 'الطلب مغلق بالفعل' USING ERRCODE = 'P0001';
  END IF;

  RETURN v_out;
END;
$function$
;


-- ═══ FUNCTION merchant_link_product(p_integration_id uuid, p_deal_id text, p_external_id text, p_variant_id text, p_location_id text, p_external_url text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_link_product(p_integration_id uuid, p_deal_id text, p_external_id text, p_variant_id text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text, p_external_url text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_store text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_store FROM public.stock_integrations WHERE id = p_integration_id;
  IF v_store IS NULL OR v_store <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOUR_INTEGRATION');
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.deals WHERE id = p_deal_id AND store_id = v_me) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOUR_DEAL');
  END IF;
  IF p_external_id IS NULL OR btrim(p_external_id) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'EXTERNAL_ID_REQUIRED');
  END IF;
  INSERT INTO public.stock_links
    (integration_id, store_id, deal_id, variant_id, location_id, external_id, external_url)
  VALUES (p_integration_id, v_me, p_deal_id, NULLIF(btrim(p_variant_id),''),
          NULLIF(btrim(p_location_id),''), btrim(p_external_id), NULLIF(btrim(p_external_url),''))
  ON CONFLICT (integration_id, external_id) DO UPDATE
    SET deal_id = EXCLUDED.deal_id, variant_id = EXCLUDED.variant_id,
        location_id = EXCLUDED.location_id, external_url = EXCLUDED.external_url;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION merchant_reissue_webhook_path(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_reissue_webhook_path(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text;
        v_slug text; v_rev int;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  v_slug := encode(extensions.gen_random_bytes(18), 'hex');
  UPDATE public.stock_integrations
     SET webhook_slug = v_slug,
         webhook_rev  = webhook_rev + 1,
         -- 🪤 ويُطفأ وسمُ الحالة: العنوانُ الجديد لم يُجرَّب بعد، وإبقاءُ
         --    «يعمل ✅» عليه كذبٌ حتى تصل أوّلُ رسالةٍ إليه.
         last_note    = 'NEW_URL_NOT_TRIED'
   WHERE id = p_id
   RETURNING webhook_rev INTO v_rev;
  RETURN jsonb_build_object('ok', true, 'slug', v_slug, 'rev', v_rev);
END
$function$
;


-- ═══ FUNCTION merchant_request_store_name(p_name text, p_reason text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_request_store_name(p_name text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_name text := btrim(COALESCE(p_name, ''));
  v_cur  text; v_type text; v_id text; v_bad text[];
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT COALESCE(shop, name), user_type INTO v_cur, v_type FROM public.users WHERE id = v_uid;
  IF v_type NOT IN ('seller','admin') THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_A_MERCHANT'); END IF;
  IF length(v_name) < 2 OR length(v_name) > 60 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_NAME');
  END IF;
  IF v_name = COALESCE(v_cur, '') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SAME_NAME');
  END IF;
  v_bad := public.taki_match_terms(v_name);
  IF array_length(v_bad, 1) IS NOT NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_WORDS');
  END IF;
  IF EXISTS (SELECT 1 FROM public.users u
             WHERE u.id <> v_uid AND u.deleted_at IS NULL
               AND public.taki_norm(COALESCE(u.shop,'')) = public.taki_norm(v_name)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NAME_TAKEN');
  END IF;
  IF EXISTS (SELECT 1 FROM public.store_name_requests
             WHERE store_id = v_uid AND status = 'requested') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_PENDING');
  END IF;

  INSERT INTO public.store_name_requests (store_id, current_name, wanted_name, reason)
  VALUES (v_uid, v_cur, v_name, NULLIF(btrim(COALESCE(p_reason,'')), ''))
  RETURNING id INTO v_id;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  SELECT a.id, '🏷 طلب تغيير اسم متجر', '🏷 Store rename request',
         COALESCE(v_cur,'—') || ' ← ' || v_name, COALESCE(v_cur,'—') || ' → ' || v_name,
         'system', jsonb_build_object('audience','admin','actionUrl','/admin?tab=sellers',
                                      'action_url','/admin?tab=sellers','nameRequestId', v_id)
  FROM public.users a WHERE a.user_type = 'admin' AND a.deleted_at IS NULL;

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'status', 'requested');
END $function$
;


-- ═══ FUNCTION merchant_rotate_integration_key(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_rotate_integration_key(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text; v_key text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  -- 🪤 يُولَّد على الخادم: مفتاحٌ يمرّ عبر متصفّحٍ أو محادثةٍ صار معروفاً.
  v_key := 'taki_' || encode(extensions.gen_random_bytes(24), 'hex');
  UPDATE public.stock_integrations
     SET api_key_hash = encode(extensions.digest(v_key, 'sha256'), 'hex'),
         api_key_last4 = right(v_key, 4)
   WHERE id = p_id;
  -- 🔴 يُعاد مرّةً واحدة. ولا يُخزَّن، فلا يُسترجع — يُدوَّر.
  RETURN jsonb_build_object('ok', true, 'api_key', v_key, 'shown_once', true);
END
$function$
;


-- ═══ FUNCTION merchant_set_booking_holds(p_pickup numeric, p_delivery numeric) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_booking_holds(p_pickup numeric, p_delivery numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me  text := (SELECT auth.uid()::text);
  v_max numeric := public.taki_booking_hold_max();
  v_min numeric := public.taki_booking_hold_min();
  v_p   numeric;
  v_d   numeric;
  v_rp  numeric;
  v_rd  numeric;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users u
                  WHERE u.id = v_me AND u.user_type <> 'buyer' AND u.deleted_at IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_A_MERCHANT');
  END IF;

  -- العدمُ يعني «اتبع المنصّة»؛ وما دون الأرضيّة أو فوق السقف يُرفض صريحاً
  -- لا يُقصّ بصمت: التاجرُ كتب رقماً، فتغييرُه تحت يده دون أن يُقال كذبٌ هادئ.
  -- 🔴 v15.50 — والأرضيّةُ تُقرأ (`taki_booking_hold_min`) فتُعيدها الرسالةُ
  --    صادقةً: كانت تقول `min: 0.25` نصّاً، فبدّلَها ناصرٌ إلى ساعةٍ وكذبت.
  v_p := p_pickup; v_d := p_delivery;
  IF v_p IS NOT NULL AND (v_p < v_min OR v_p > v_max) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'PICKUP_OUT_OF_RANGE', 'min', v_min, 'max', v_max);
  END IF;
  IF v_d IS NOT NULL AND (v_d < v_min OR v_d > v_max) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'DELIVERY_OUT_OF_RANGE', 'min', v_min, 'max', v_max);
  END IF;

  INSERT INTO public.store_profiles (store_id, hold_pickup_hours, hold_delivery_hours)
  VALUES (v_me, v_p, v_d)
  ON CONFLICT (store_id) DO UPDATE
    SET hold_pickup_hours   = EXCLUDED.hold_pickup_hours,
        hold_delivery_hours = EXCLUDED.hold_delivery_hours,
        updated_at          = now();

  SELECT sp.hold_pickup_hours, sp.hold_delivery_hours INTO v_rp, v_rd
    FROM public.store_profiles sp WHERE sp.store_id = v_me;
  IF v_rp IS DISTINCT FROM v_p OR v_rd IS DISTINCT FROM v_d THEN
    RETURN jsonb_build_object('ok', false, 'error', 'WRITE_NOT_CONFIRMED');
  END IF;

  RETURN jsonb_build_object('ok', true,
    'hold_pickup_custom',   v_rp,
    'hold_delivery_custom', v_rd,
    'hold_pickup_hours',    public.taki_booking_hold_hours('pickup',   v_me),
    'hold_delivery_hours',  public.taki_booking_hold_hours('delivery', v_me),
    'hold_min_hours',       v_min,
    'hold_max_hours',       v_max);
END
$function$
;


-- ═══ FUNCTION merchant_set_delivery(p_enabled boolean, p_payment text, p_fee numeric, p_min_order numeric, p_eta_min integer, p_note text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_delivery(p_enabled boolean, p_payment text, p_fee numeric, p_min_order numeric, p_eta_min integer, p_note text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_type text; v_shop text; v_mode text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT user_type, shop INTO v_type, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_type IS NULL OR (v_type NOT IN ('seller','admin') AND nullif(btrim(coalesce(v_shop,'')),'') IS NULL) THEN
    RAISE EXCEPTION 'SELLER_ONLY';
  END IF;
  IF p_payment IS NULL OR p_payment NOT IN ('cod','card','both') THEN RAISE EXCEPTION 'BAD_MODE'; END IF;
  -- v15.33 — ولا يُحفظ التعارضُ أصلاً: متجرٌ أقرّ «بطاقة فقط» لا يختار نقداً
  -- للتوصيل. والرفضُ هنا أصدقُ من قبولٍ تُبطله القراءة بصمت.
  IF p_payment IN ('cod','both')
     AND NOT coalesce((SELECT sp2.accepts_cod FROM public.store_profiles sp2 WHERE sp2.store_id = v_uid), true) THEN
    RAISE EXCEPTION 'COD_VS_CARD_ONLY';
  END IF;
  IF coalesce(p_fee, 0) < 0 OR coalesce(p_fee, 0) > 1000 THEN RAISE EXCEPTION 'BAD_FEE'; END IF;
  IF coalesce(p_min_order, 0) < 0 OR coalesce(p_min_order, 0) > 100000 THEN RAISE EXCEPTION 'BAD_MIN'; END IF;
  IF p_eta_min IS NOT NULL AND p_eta_min NOT BETWEEN 0 AND 1440 THEN RAISE EXCEPTION 'BAD_ETA'; END IF;
  IF coalesce(p_enabled, false) AND p_payment IN ('card','both') THEN
    v_mode := public.deal_payment_mode(v_uid);
    IF v_mode NOT IN ('online','both') THEN RAISE EXCEPTION 'GATEWAY_REQUIRED'; END IF;
  END IF;

  INSERT INTO public.store_profiles (store_id, delivery_enabled, delivery_payment, delivery_fee, delivery_min_order, delivery_eta_min, delivery_note)
  VALUES (v_uid, coalesce(p_enabled,false), p_payment, round(coalesce(p_fee,0),2), round(coalesce(p_min_order,0),2), p_eta_min, nullif(left(btrim(coalesce(p_note,'')),300),''))
  ON CONFLICT (store_id) DO UPDATE SET
    delivery_enabled   = EXCLUDED.delivery_enabled,
    delivery_payment   = EXCLUDED.delivery_payment,
    delivery_fee       = EXCLUDED.delivery_fee,
    delivery_min_order = EXCLUDED.delivery_min_order,
    delivery_eta_min   = EXCLUDED.delivery_eta_min,
    delivery_note      = EXCLUDED.delivery_note,
    updated_at         = now();

  RETURN (SELECT jsonb_build_object(
    'delivery_enabled', sp.delivery_enabled, 'delivery_payment', sp.delivery_payment,
    'delivery_fee', sp.delivery_fee, 'delivery_min_order', sp.delivery_min_order,
    'delivery_eta_min', sp.delivery_eta_min, 'delivery_note', sp.delivery_note,
    'zones', (SELECT count(*) FROM public.store_delivery_zones z WHERE z.store_id = v_uid AND z.is_active))
    FROM public.store_profiles sp WHERE sp.store_id = v_uid);
END
$function$
;


-- ═══ FUNCTION merchant_set_field_map(p_id uuid, p_id_path text, p_qty_path text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_field_map(p_id uuid, p_id_path text, p_qty_path text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_i public.stock_integrations%ROWTYPE;
        v_id text; v_qty text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT * INTO v_i FROM public.stock_integrations WHERE id = p_id;
  IF v_i.store_id IS NULL OR v_i.store_id <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  -- 🔴 ولا تُقبل خريطةٌ لا تعمل على الرسالة الحقيقية: خريطةٌ خاطئة تُسكت
  --    الربطَ بصمت، والتاجر يظنّه يعمل.
  IF v_i.last_payload IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NO_MESSAGE_YET');
  END IF;
  v_id  := public._taki_jpath(v_i.last_payload, p_id_path);
  v_qty := public._taki_jpath(v_i.last_payload, p_qty_path);
  IF v_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'ID_PATH_EMPTY'); END IF;
  IF v_qty IS NULL OR v_qty !~ '^[0-9]+$' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'QTY_PATH_NOT_A_NUMBER', 'got', v_qty);
  END IF;
  UPDATE public.stock_integrations
     SET field_map = jsonb_build_object('id', btrim(p_id_path), 'qty', btrim(p_qty_path), 'learned', false),
         last_note = 'MAPPED'
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true, 'sample_id', v_id, 'sample_qty', v_qty::int);
END
$function$
;


-- ═══ FUNCTION merchant_set_gateway(p_provider text, p_publishable_key text, p_secret_key text, p_webhook_secret text, p_extra jsonb) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_gateway(p_provider text, p_publishable_key text DEFAULT NULL::text, p_secret_key text DEFAULT NULL::text, p_webhook_secret text DEFAULT NULL::text, p_extra jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_utype text;
BEGIN
  -- 🔴 v15.31: `sim` تختم الطلبَ «مدفوعاً» بلا مال — فلا تُربط
  --    من لوحة التاجر إطلاقاً. ولناصر مسارُه الإداريّ إن أراد اختباراً.
  IF lower(COALESCE(p_provider, '')) = 'sim' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SIM_NOT_ALLOWED');
  END IF;

  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT u.user_type INTO v_utype FROM public.users u WHERE u.id = v_uid;
  IF v_utype IS NULL OR v_utype NOT IN ('seller','admin') THEN RAISE EXCEPTION 'SELLER_ONLY'; END IF;
  RETURN public._gateway_write(v_uid, p_provider, p_publishable_key, p_secret_key, p_webhook_secret, p_extra, v_uid, v_utype);
END $function$
;


-- ═══ FUNCTION merchant_set_instant_refund(p_on boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_instant_refund(p_on boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := (SELECT auth.uid())::text; v_type text; n int;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT user_type INTO v_type FROM public.users WHERE id = v_me AND deleted_at IS NULL;
  IF v_type IS NULL OR v_type NOT IN ('seller', 'admin') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_A_MERCHANT');
  END IF;

  INSERT INTO public.store_profiles (store_id, instant_refund)
  VALUES (v_me, COALESCE(p_on, true))
  ON CONFLICT (store_id) DO UPDATE
    SET instant_refund = EXCLUDED.instant_refund, updated_at = now();
  GET DIAGNOSTICS n = ROW_COUNT;
  -- 🪤 صفرُ صفوفٍ بلا خطأ هو شكلُ الرفض الصامت الذي تعيده RLS — يُثبَت العدد.
  IF n = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_SAVED'); END IF;

  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_me, v_type, 'instant_refund_toggled', 'store', v_me,
          jsonb_build_object('on', COALESCE(p_on, true)));

  RETURN jsonb_build_object('ok', true, 'instant_refund', COALESCE(p_on, true));
END
$function$
;


-- ═══ FUNCTION merchant_set_payment_declaration(p_accepts_cod boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_payment_declaration(p_accepts_cod boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_type text; v_shop text; v_mode text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT user_type, shop INTO v_type, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_type IS NULL OR (v_type NOT IN ('seller','admin') AND nullif(btrim(coalesce(v_shop,'')),'') IS NULL) THEN
    RAISE EXCEPTION 'SELLER_ONLY';
  END IF;
  v_mode := public.deal_payment_mode(v_uid);
  -- رفض النقد بلا بوابة يعني متجراً لا يستطيع تحصيل ريال واحد — نمنعه بدل أن
  -- نتركه يكتشف ذلك من مشترٍ لا يستطيع الحجز.
  IF NOT coalesce(p_accepts_cod, true) AND v_mode NOT IN ('online','both') THEN
    RAISE EXCEPTION 'NEED_GATEWAY_OR_COD';
  END IF;

  INSERT INTO public.store_profiles (store_id, accepts_cod, payment_declared_at)
  VALUES (v_uid, coalesce(p_accepts_cod, true), now())
  ON CONFLICT (store_id) DO UPDATE SET
    accepts_cod = EXCLUDED.accepts_cod,
    payment_declared_at = now(),
    updated_at = now();

  -- v15.33 — إقرارُ «بطاقة فقط» يسحب التوصيلَ النقديّ معه في النداء نفسه،
  -- فلا يبقى في الجدول صفٌّ متناقض يحتاج من يتذكّره.
  IF NOT coalesce(p_accepts_cod, true) THEN
    UPDATE public.store_profiles SET delivery_payment = 'card', updated_at = now()
     WHERE store_id = v_uid AND delivery_payment IS DISTINCT FROM 'card';
  END IF;

  RETURN public.store_can_sell(v_uid);
END
$function$
;


-- ═══ FUNCTION merchant_set_payment_modes(p_mode text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_payment_modes(p_mode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := auth.uid()::text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  IF p_mode IS NULL OR p_mode NOT IN ('cod','online','both') THEN RAISE EXCEPTION 'BAD_MODE'; END IF;
  UPDATE public.merchant_gateways SET payment_modes = p_mode, updated_at = now() WHERE merchant_id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  RETURN public.get_my_gateway();
END $function$
;


-- ═══ FUNCTION merchant_set_policies(p_refund_policy text, p_store_terms text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_policies(p_refund_policy text, p_store_terms text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_me text := (SELECT auth.uid()::text);
  v_r  text;
  v_t  text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  v_r := NULLIF(left(btrim(COALESCE(p_refund_policy, '')), 1500), '');
  v_t := NULLIF(left(btrim(COALESCE(p_store_terms,   '')), 1500), '');

  INSERT INTO public.store_profiles (store_id, refund_policy, store_terms)
  VALUES (v_me, v_r, v_t)
  ON CONFLICT (store_id) DO UPDATE
    SET refund_policy = EXCLUDED.refund_policy,
        store_terms   = EXCLUDED.store_terms,
        updated_at    = now();

  RETURN jsonb_build_object('ok', true, 'refund_policy', v_r, 'store_terms', v_t);
END
$function$
;


-- ═══ FUNCTION merchant_set_primary_branch(p_branch_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_primary_branch(p_branch_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_mid text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT merchant_id INTO v_mid FROM public.store_branches WHERE id = p_branch_id;
  IF v_mid IS NULL THEN RETURN jsonb_build_object('ok', false, 'reason', 'not_found'); END IF;
  IF v_mid <> v_uid AND NOT COALESCE(public.taki_admin_perm('tab_sellers'), false) THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'forbidden');
  END IF;

  UPDATE public.store_branches SET is_primary = false, updated_at = now()
   WHERE merchant_id = v_mid AND COALESCE(is_primary, false) AND id <> p_branch_id;
  UPDATE public.store_branches SET is_primary = true, updated_at = now()
   WHERE id = p_branch_id;

  RETURN jsonb_build_object('ok', true, 'branch_id', p_branch_id);
END $function$
;


-- ═══ FUNCTION merchant_set_sold_out(p_deal_id text, p_on boolean, p_variant_id text, p_location_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_sold_out(p_deal_id text, p_on boolean, p_variant_id text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.deals WHERE id = p_deal_id;
  IF v_owner IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF v_owner IS DISTINCT FROM v_me AND NOT public.taki_admin_perm('action_delete_deals') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOUR_DEAL');
  END IF;
  RETURN public._taki_set_off(p_deal_id, p_on, p_variant_id, p_location_id);
END
$function$
;


-- ═══ FUNCTION merchant_set_stock(p_deal_id text, p_on_hand integer, p_variants jsonb, p_locations jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_stock(p_deal_id text, p_on_hand integer DEFAULT NULL::integer, p_variants jsonb DEFAULT NULL::jsonb, p_locations jsonb DEFAULT NULL::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text; v_admin boolean;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.deals WHERE id = p_deal_id;
  IF v_owner IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;

  -- تاجرٌ يعدّل مخزون عرضٍ ليس له = تخريب. والإدارةُ مستثناةٌ بصلاحيتها وحدها.
  v_admin := (v_owner IS DISTINCT FROM v_me) AND public.taki_admin_perm('action_delete_deals');
  IF v_owner IS DISTINCT FROM v_me AND NOT v_admin THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOUR_DEAL');
  END IF;

  RETURN public.taki_set_on_hand(p_deal_id, p_on_hand, p_variants, p_locations, now(),
                                 CASE WHEN v_admin THEN 'admin' ELSE 'merchant' END);
END
$function$
;


-- ═══ FUNCTION merchant_set_store_card(p_bio text, p_avatar_url text, p_address text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_store_card(p_bio text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_type text;
  v_shop text;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT user_type, shop INTO v_type, v_shop
    FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_type IS NULL OR (v_type NOT IN ('seller','admin')
      AND nullif(btrim(coalesce(v_shop,'')),'') IS NULL) THEN
    RAISE EXCEPTION 'SELLER_ONLY';
  END IF;
  -- 🪤 حدّ المضيف بالنقطة لا بـ`[^/]*` (فخّ `evil-google.com`)، و`supabase.co`
  --    مقصورٌ على مشروع المعاينة لا كل مشاريع العالم.
  IF p_avatar_url IS NOT NULL AND btrim(p_avatar_url) <> ''
     AND p_avatar_url !~ '^https?://([A-Za-z0-9-]+\.)*(takisa\.net|sslip\.io|kbmqzxcjdankdgiovctm\.supabase\.co)(:[0-9]+)?/' THEN
    RAISE EXCEPTION 'BAD_AVATAR_HOST';
  END IF;
  RETURN public.taki_set_store_card(v_uid, p_bio, p_avatar_url, p_address);
END $function$
;


-- ═══ FUNCTION merchant_set_subscription_renew(p_on boolean) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_set_subscription_renew(p_on boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_caller text := auth.uid()::text;
    v_row    store_profiles;
BEGIN
    IF v_caller IS NULL THEN
        RAISE EXCEPTION 'Not authenticated';
    END IF;

    UPDATE store_profiles
    SET auto_renew = p_on,
        subscription_canceled_at = CASE WHEN p_on THEN NULL ELSE NOW() END,
        updated_at = NOW()
    WHERE store_id = v_caller
    RETURNING * INTO v_row;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'No store profile for %', v_caller;
    END IF;

    -- v12.32: لا استعادة تلقائية للعروض المجمّدة — التاجر يفعّلها بنفسه.

    RETURN jsonb_build_object(
        'success', true,
        'auto_renew', v_row.auto_renew,
        'canceled_at', v_row.subscription_canceled_at,
        'expires_at', v_row.subscription_expires_at
    );
END;
$function$
;


-- ═══ FUNCTION merchant_setup_gaps(p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_setup_gaps(p_store_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'store_id',              u.id,
    'refund_policy_missing', (NULLIF(btrim(COALESCE(sp.refund_policy, '')), '') IS NULL
                              AND EXISTS (SELECT 1 FROM public.deals d WHERE d.store_id = u.id)),
    'payment_undeclared',    (sp.payment_declared_at IS NULL),
    'deals_total',           (SELECT count(*) FROM public.deals d WHERE d.store_id = u.id),
    'deals_live',            (SELECT count(*) FROM public.deals d WHERE d.store_id = u.id AND d.status = 'active'),
    'pay_declared',          (sp.payment_declared_at IS NOT NULL),
    'hours_set',             (u.working_hours IS NOT NULL),
    'refund_set',            (NULLIF(btrim(COALESCE(sp.refund_policy, '')), '') IS NOT NULL),
    'vat_answered',          (sp.vat_status IS NOT NULL),
    'has_live_deal',         (EXISTS (SELECT 1 FROM public.deals d
                                       WHERE d.store_id = u.id AND d.status = 'active')),
    'profile_set',           (NULLIF(btrim(COALESCE(u.bio, sp.bio, '')), '') IS NOT NULL
                          AND NULLIF(btrim(COALESCE(u.avatar_url, sp.avatar_url, '')), '') IS NOT NULL),
    -- v14.72d — النصفان، ليقول السطرُ على الشاشة أيّهما الناقص بالضبط.
    'bio_set',               (NULLIF(btrim(COALESCE(u.bio, sp.bio, '')), '') IS NOT NULL),
    'avatar_set',            (NULLIF(btrim(COALESCE(u.avatar_url, sp.avatar_url, '')), '') IS NOT NULL)
  )
  FROM public.users u
  LEFT JOIN public.store_profiles sp ON sp.store_id = u.id
  WHERE u.id = p_store_id AND u.deleted_at IS NULL;
$function$
;


-- ═══ FUNCTION merchant_stock_claim_parked(p_id uuid, p_remote_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_stock_claim_parked(p_id uuid, p_remote_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, '');
        v_owner text; v_prov text; v_p record; v_tok jsonb; r jsonb;
        v_n int; v_mine boolean;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id, lower(provider) INTO v_owner, v_prov
    FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  IF COALESCE(btrim(p_remote_id), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'REMOTE_ID_REQUIRED');
  END IF;
  SELECT * INTO v_p FROM public.stock_oauth_parked
   WHERE provider = v_prov AND claimed_by IS NULL
     AND remote_id = btrim(p_remote_id)
   ORDER BY created_at DESC LIMIT 1;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;

  -- 🔴 v15.80 ④ — الرقمُ وحده ادّعاء. فيُشترط معه أنّ نافذةً كانت مفتوحةً
  --    لحظةَ وصولِ التوكن، وأنّها **نافذةُ المُطالب**، وأنّها **الوحيدة**.
  SELECT count(*), COALESCE(bool_or(si.id = p_id), false)
    INTO v_n, v_mine
    FROM public.stock_integrations si
   WHERE lower(si.provider) = v_prov
     AND si.connect_nonce IS NOT NULL
     AND si.oauth_attempt_at IS NOT NULL
     AND si.oauth_attempt_at <= v_p.created_at
     AND si.oauth_attempt_at >  v_p.created_at - interval '30 minutes';
  IF v_n = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NO_WINDOW',
      'hint', 'press Connect in TAKI first, then install from your store — the token must arrive while your window is open');
  END IF;
  IF NOT v_mine THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOUR_WINDOW');
  END IF;
  IF v_n > 1 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'AMBIGUOUS_WINDOW', 'open_claims', v_n,
      'hint', 'another store had a connect window open at the same moment — retry, or ask TAKI support to bind it');
  END IF;

  SELECT decrypted_secret::jsonb INTO v_tok FROM vault.decrypted_secrets WHERE name = v_p.secret_name;
  IF v_tok IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'SECRET_GONE'); END IF;

  r := public.taki_stock_oauth_store(p_id, v_tok, btrim(p_remote_id));
  IF NOT COALESCE((r->>'ok')::boolean, false) THEN RETURN r; END IF;

  UPDATE public.stock_oauth_parked SET claimed_by = p_id, claimed_at = now() WHERE id = v_p.id;
  DELETE FROM vault.secrets WHERE name = v_p.secret_name;
  RETURN jsonb_build_object('ok', true, 'expires_at', r->>'expires_at');
END
$function$
;


-- ═══ FUNCTION merchant_stock_connect_url(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_stock_connect_url(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, '');
        v_i public.stock_integrations%ROWTYPE; v_app jsonb; v_nonce text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT * INTO v_i FROM public.stock_integrations WHERE id = p_id;
  IF v_i.store_id IS NULL OR v_i.store_id <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  v_app := public._taki_stock_app(v_i.provider);
  -- 🔴 يُقال صريحاً ولا يُعرض زرٌّ لا يعمل: تطبيقُ تاكي غيرُ مسجَّلٍ بعد.
  IF v_app IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'APP_NOT_REGISTERED',
      'provider', v_i.provider);
  END IF;

  -- v15.80 ④ — نافذةٌ قائمةٌ تُعاد كما هي، ولا يُفتح غيرُها إلا بحصّة.
  IF v_i.connect_nonce IS NOT NULL
     AND v_i.oauth_attempt_at IS NOT NULL
     AND v_i.oauth_attempt_at > now() - interval '30 minutes' THEN
    v_nonce := v_i.connect_nonce;
  ELSE
    -- 🪤 ويُردّ شكلاً ثابتاً: `taki_rate_check` ترفع استثناءً، وهذه الدالّةُ
    --    عقدُها jsonb. فيُلفّ النداءُ ولا يُغيَّر شكلُ الردّ على الواجهة.
    BEGIN
      PERFORM public.taki_rate_check('stockconnect:' || p_id::text, 5, 3600,
                                     'too many connect attempts — wait and retry');
    EXCEPTION WHEN OTHERS THEN
      RETURN jsonb_build_object('ok', false, 'error', 'RATE_LIMITED');
    END;
    v_nonce := encode(extensions.gen_random_bytes(16), 'hex');
    UPDATE public.stock_integrations
       SET connect_nonce = v_nonce, oauth_attempt_at = now(),
           last_note = 'CONNECT_STARTED'
     WHERE id = p_id;
  END IF;

  IF lower(v_i.provider) = 'zid' THEN
    -- مقيسٌ من https://docs.zid.sa/authorization.md — و`state` تُعاد كما هي
    IF COALESCE(v_app->>'client_id','') = '' OR COALESCE(v_app->>'redirect_uri','') = '' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'APP_INCOMPLETE');
    END IF;
    RETURN jsonb_build_object('ok', true, 'mode', 'redirect',
      'url', 'https://oauth.zid.sa/oauth/authorize'
          || '?client_id='    || public._taki_urlenc(v_app->>'client_id')
          || '&redirect_uri=' || public._taki_urlenc(v_app->>'redirect_uri')
          || '&response_type=code'
          || '&state='        || public._taki_urlenc(p_id::text || ':' || v_nonce),
      'window_minutes', 30);
  END IF;

  IF lower(v_i.provider) = 'salla' THEN
    -- 🪤 ولا `state` هنا: «الوضعُ السهل» يبدأ برابط تثبيت، والتوكن يصل إلى
    --    عنوان التطبيق العامّ بـ`merchant` وحده. فالنسبةُ بنافذةِ ٣٠ دقيقة،
    --    وإن التبست **لا تُخمَّن** (القسم ٥).
    IF COALESCE(v_app->>'app_id','') = '' THEN
      RETURN jsonb_build_object('ok', false, 'error', 'APP_INCOMPLETE');
    END IF;
    RETURN jsonb_build_object('ok', true, 'mode', 'install',
      'url', 'https://s.salla.sa/apps/install/' || public._taki_urlenc(v_app->>'app_id'),
      'window_minutes', 30);
  END IF;

  RETURN jsonb_build_object('ok', false, 'error', 'PROVIDER_HAS_NO_OAUTH');
END
$function$
;


-- ═══ FUNCTION merchant_stock_disconnect(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_stock_disconnect(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  DELETE FROM vault.secrets WHERE name = 'stock_tok:' || p_id::text;
  UPDATE public.stock_integrations
     SET oauth_state = NULL, oauth_expires_at = NULL, oauth_scope = NULL,
         connect_nonce = NULL, last_note = 'DISCONNECTED'
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION merchant_stock_parked_count(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_stock_parked_count(p_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text; v_prov text;
BEGIN
  IF v_me IS NULL THEN RETURN 0; END IF;
  SELECT store_id, lower(provider) INTO v_owner, v_prov
    FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN RETURN 0; END IF;
  RETURN (SELECT count(*) FROM public.stock_oauth_parked p
           WHERE p.provider = v_prov AND p.claimed_by IS NULL
             AND p.created_at > now() - interval '7 days'
             AND EXISTS (SELECT 1 FROM public.stock_integrations si
                          WHERE si.id = p_id
                            AND si.connect_nonce IS NOT NULL
                            AND si.oauth_attempt_at IS NOT NULL
                            AND si.oauth_attempt_at <= p.created_at
                            AND si.oauth_attempt_at >  p.created_at - interval '30 minutes'));
END
$function$
;


-- ═══ FUNCTION merchant_stock_verify_state(p_id uuid) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_stock_verify_state(p_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_i public.stock_integrations%ROWTYPE;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT * INTO v_i FROM public.stock_integrations WHERE id = p_id;
  IF v_i.store_id IS NULL OR v_i.store_id <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  RETURN jsonb_build_object('ok', true,
    'signed', COALESCE(btrim(COALESCE(v_i.inbound_secret,'')), '') <> '',
    'method', CASE lower(v_i.provider) WHEN 'salla' THEN 'hmac-sha256-raw'
                                       WHEN 'zid'   THEN 'basic-auth'
                                       ELSE 'none' END);
END
$function$
;


-- ═══ FUNCTION merchant_submit_verification(p_kind text, p_number text, p_legal_name text, p_expiry date) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_submit_verification(p_kind text, p_number text, p_legal_name text, p_expiry date DEFAULT NULL::date)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := (SELECT auth.uid())::text; v_t text; v_shop text;
        v_num text := btrim(COALESCE(p_number,'')); v_name text := btrim(COALESCE(p_legal_name,''));
        v_id text;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT user_type, shop INTO v_t, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_t IS NULL OR (v_t NOT IN ('seller','admin') AND NULLIF(btrim(COALESCE(v_shop,'')),'') IS NULL) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_A_MERCHANT');
  END IF;
  IF p_kind NOT IN ('business_sa','cr','freelance') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_KIND'); END IF;
  -- 🪤 فحصُ الشكل **مرشّحُ أخطاءٍ مطبعية لا إثبات**: لا خانة تدقيق منشورة لأي
  --    سجلٍّ سعودي، و`^7[0-9]{9}$` كانت سترفض سجلات `1010…/4030…` السارية.
  IF p_kind = 'cr'        AND v_num !~ '^[0-9]{10}$'   THEN RETURN jsonb_build_object('ok', false, 'error', 'BAD_NUMBER'); END IF;
  IF p_kind = 'business_sa' AND v_num !~ '^[0-9]{5,14}$' THEN RETURN jsonb_build_object('ok', false, 'error', 'BAD_NUMBER'); END IF;
  IF p_kind = 'freelance' AND length(v_num) < 4        THEN RETURN jsonb_build_object('ok', false, 'error', 'BAD_NUMBER'); END IF;
  IF length(v_name) < 3 THEN RETURN jsonb_build_object('ok', false, 'error', 'BAD_NAME'); END IF;

  IF EXISTS (SELECT 1 FROM public.store_verifications WHERE store_id = v_uid AND status = 'submitted') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_PENDING'); END IF;
  IF EXISTS (SELECT 1 FROM public.store_verifications
              WHERE status = 'approved' AND store_id <> v_uid
                AND doc_kind = p_kind AND lower(btrim(doc_number)) = lower(v_num)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NUMBER_TAKEN'); END IF;

  -- ٣ محاولات في اليوم: طابورٌ يُغرق أسرعَ ممّا يُفرَّغ يجعل مهلةَ المراجعة كذبة.
  BEGIN
    PERFORM public.taki_rate_check('ver:' || v_uid, 3, 86400, 'RATE_LIMIT');
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'TOO_MANY');
  END;

  INSERT INTO public.store_verifications (store_id, doc_kind, doc_number, claimed_name, doc_expiry)
  VALUES (v_uid, p_kind, v_num, v_name, p_expiry)
  RETURNING id INTO v_id;

  -- إشعارٌ واحد، ولحاملي الصلاحية وحدهم — لا فيضانٌ لكل أدمن (قاعدة المشروع).
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  SELECT u.id, '🪪 طلب توثيق جديد', '🪪 New verification request',
         'طلب توثيق من متجر «' || COALESCE(NULLIF(v_shop,''),'متجر') || '» — بانتظار مراجعتك.',
         'A merchant submitted a verification request.', 'system',
         jsonb_build_object('audience','admin','verificationId', v_id,
                            'actionUrl','/admin?tab=verification','action_url','/admin?tab=verification')
    FROM public.users u
   WHERE u.user_type = 'admin' AND u.deleted_at IS NULL
     AND (COALESCE(u.is_super_admin,false) OR 'tab_verification' = ANY(COALESCE(u.admin_permissions,'{}'::text[])));

  RETURN jsonb_build_object('ok', true, 'id', v_id, 'status', 'submitted');
END
$function$
;


-- ═══ FUNCTION merchant_toggle_gateway(p_enabled boolean) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_toggle_gateway(p_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_row public.merchant_gateways%ROWTYPE;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
  SELECT * INTO v_row FROM public.merchant_gateways WHERE merchant_id = v_uid;
  IF NOT FOUND THEN RAISE EXCEPTION 'NO_GATEWAY'; END IF;
  IF p_enabled THEN
    -- v15.33 — قبل كلّ شرطٍ آخر: المحاكاةُ لا تُفعَّل من لوحة التاجر.
    IF lower(coalesce(v_row.provider,'')) = 'sim' THEN RAISE EXCEPTION 'SIM_NOT_ALLOWED'; END IF;
    IF v_row.agreement_accepted_at IS NULL THEN RAISE EXCEPTION 'AGREEMENT_REQUIRED'; END IF;
    IF NOT public._gateway_secret_live(v_uid) THEN RAISE EXCEPTION 'KEYS_REQUIRED'; END IF;
    IF v_row.verified_at IS NULL THEN RAISE EXCEPTION 'VERIFY_REQUIRED'; END IF;
  END IF;
  UPDATE public.merchant_gateways
  SET is_enabled = p_enabled, fail_count = CASE WHEN p_enabled THEN 0 ELSE fail_count END, updated_at = now()
  WHERE merchant_id = v_uid;
  INSERT INTO public.activity_log (user_id, user_type, action, entity_type, entity_id, metadata)
  VALUES (v_uid, 'seller', CASE WHEN p_enabled THEN 'gateway_enabled' ELSE 'gateway_disabled' END,
          'merchant_gateway', v_uid, '{}'::jsonb);
  RETURN public.get_my_gateway();
END $function$
;


-- ═══ FUNCTION merchant_unlink_product(p_link_id bigint) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_unlink_product(p_link_id bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.stock_links WHERE id = p_link_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  DELETE FROM public.stock_links WHERE id = p_link_id;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION merchant_update_integration(p_id uuid, p_enabled boolean, p_webhook_url text, p_label text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_update_integration(p_id uuid, p_enabled boolean DEFAULT NULL::boolean, p_webhook_url text DEFAULT NULL::text, p_label text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_me text := NULLIF((SELECT auth.uid())::text, ''); v_owner text;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT store_id INTO v_owner FROM public.stock_integrations WHERE id = p_id;
  IF v_owner IS NULL OR v_owner <> v_me THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_YOURS');
  END IF;
  -- 🪤 خطّافٌ بلا https يُرسل أحداثَ مخزونٍ موقَّعةً على قناةٍ مكشوفة.
  IF p_webhook_url IS NOT NULL AND btrim(p_webhook_url) <> '' AND p_webhook_url !~ '^https://' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'HTTPS_REQUIRED');
  END IF;
  -- v15.80 ③ — ونفسُ الحارس في الكاتب الثاني. ونصٌّ واحدٌ يُستدعى من الموضعين
  --   لا نسختان تنحرفان (درسُ «مفرداتُ الأخطاء في مكانٍ واحد»، v14.96).
  IF p_webhook_url IS NOT NULL AND btrim(p_webhook_url) <> ''
     AND NOT public._taki_hook_url_ok(btrim(p_webhook_url)) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'WEBHOOK_URL_REJECTED',
      'hint', 'use a public DNS host over https on port 443 — no IP address, no port, no credentials in the URL');
  END IF;
  UPDATE public.stock_integrations
     SET is_enabled  = COALESCE(p_enabled, is_enabled),
         webhook_url = CASE WHEN p_webhook_url IS NULL THEN webhook_url
                            ELSE NULLIF(btrim(p_webhook_url), '') END,
         label       = CASE WHEN p_label IS NULL THEN label ELSE NULLIF(btrim(p_label), '') END
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION merchant_withdraw_verification() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.merchant_withdraw_verification()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := (SELECT auth.uid())::text; n int;
BEGIN
  IF v_uid IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  UPDATE public.store_verifications SET status = 'withdrawn', decided_at = now()
   WHERE store_id = v_uid AND status = 'submitted';
  GET DIAGNOSTICS n = ROW_COUNT;
  IF n = 0 THEN RETURN jsonb_build_object('ok', false, 'error', 'NO_OPEN_REQUEST'); END IF;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION my_complaints(p_limit integer) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.my_complaints(p_limit integer DEFAULT 50)
 RETURNS TABLE(id uuid, category text, subject text, message text, status text, attachments text[], created_at timestamp with time zone, reply_count integer, last_reply_at timestamp with time zone, unread_admin boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text;
BEGIN
  v_uid := auth.uid()::text;
  IF v_uid IS NULL THEN RAISE EXCEPTION 'sign in required'; END IF;

  RETURN QUERY
  SELECT c.id, c.category, c.subject, c.message, c.status, c.attachments, c.created_at,
         COALESCE(r.cnt, 0)::int,
         r.last_at,
         -- «جديد»: آخر ردٍّ من الإدارة بعد آخر ردٍّ منك (أو لم تردّ أصلاً)
         COALESCE(r.last_admin_at > COALESCE(r.last_user_at, c.created_at), false)
    FROM public.complaints c
    LEFT JOIN LATERAL (
      SELECT count(*) AS cnt,
             max(cr.created_at) AS last_at,
             max(cr.created_at) FILTER (WHERE cr.author_role = 'admin') AS last_admin_at,
             max(cr.created_at) FILTER (WHERE cr.author_role = 'user')  AS last_user_at
        FROM public.complaint_replies cr
       WHERE cr.complaint_id = c.id
    ) r ON true
   WHERE c.user_id = v_uid
   ORDER BY COALESCE(r.last_at, c.created_at) DESC
   LIMIT GREATEST(1, LEAST(p_limit, 200));
END;
$function$
;


-- ═══ FUNCTION my_contest_entry(p_contest_id uuid) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.my_contest_entry(p_contest_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare v_uid text := auth.uid()::text; v_phone text; r record;
begin
  if v_uid is null then return jsonb_build_object('entered', false); end if;
  select nullif(btrim(phone), '') into v_phone from users where id = v_uid;
  -- v14.77 — الحساب هو الرابط؛ الجوال احتياطيّ للصفوف التي سبقت العمود.
  -- (ولم يعد غيابُ الجوال يعني «لم يشارك»: من شارك ثم مسح جوّاله كان يُقال له
  --  إنه لم يشارك، فيحاول ويُردّ بخطأ «شاركتَ من قبل».)
  select score, max_score, qualified into r
    from contest_entries
   where contest_id = p_contest_id
     and (user_id = v_uid or (user_id is null and v_phone is not null and btrim(phone) = v_phone));
  if not found then return jsonb_build_object('entered', false); end if;
  return jsonb_build_object('entered', true, 'qualified', r.qualified, 'score', r.score, 'max_score', r.max_score);
end; $function$
;


-- ═══ FUNCTION my_referral_stats() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.my_referral_stats()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid text := auth.uid()::text;
  v_total integer; v_last30 integer;
BEGIN
  IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
  SELECT count(*),
         count(*) FILTER (WHERE u.created_at >= now() - interval '30 days')
    INTO v_total, v_last30
    FROM users u
   WHERE u.referred_by_store = v_uid AND u.deleted_at IS NULL;
  RETURN jsonb_build_object('total', coalesce(v_total, 0), 'last30', coalesce(v_last30, 0));
END $function$
;


-- ═══ FUNCTION my_setup_gaps() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.my_setup_gaps()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_type text; v_shop text;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT u.user_type, u.shop INTO v_type, v_shop FROM public.users u WHERE u.id = v_uid AND u.deleted_at IS NULL;
  IF v_type IS NULL THEN RETURN NULL; END IF;
