-- ═══ FUNCTION my_verification_state() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.my_verification_state()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_uid text := (SELECT auth.uid())::text; v_t text; v_shop text; r record; g timestamptz;
BEGIN
  IF v_uid IS NULL THEN RETURN NULL; END IF;
  SELECT user_type, shop INTO v_t, v_shop FROM public.users WHERE id = v_uid AND deleted_at IS NULL;
  IF v_t IS NULL OR (v_t NOT IN ('seller','admin') AND NULLIF(btrim(COALESCE(v_shop,'')),'') IS NULL) THEN RETURN NULL; END IF;
  SELECT * INTO r FROM public.store_verifications
   WHERE store_id = v_uid AND status IN ('submitted','approved')
   ORDER BY CASE status WHEN 'submitted' THEN 0 ELSE 1 END, submitted_at DESC LIMIT 1;
  IF r.id IS NULL THEN
    SELECT * INTO r FROM public.store_verifications WHERE store_id = v_uid
     ORDER BY submitted_at DESC LIMIT 1;
  END IF;
  SELECT until INTO g FROM public.store_verification_grace WHERE store_id = v_uid;
  RETURN jsonb_build_object(
    'mode', public.taki_verification_mode(),
    'sla_hours', (public.taki_verification_policy()->>'sla_hours')::int,
    'verified', public.taki_store_verified(v_uid),
    'grace_until', g,
    'status', COALESCE(r.status,'none'), 'doc_kind', r.doc_kind, 'doc_number', r.doc_number,
    'legal_name', r.legal_name, 'claimed_name', r.claimed_name, 'doc_expiry', r.doc_expiry,
    'reject_code', r.reject_code, 'admin_note', r.admin_note,
    'submitted_at', r.submitted_at, 'decided_at', r.decided_at,
    'has_open', EXISTS (SELECT 1 FROM public.store_verifications WHERE store_id = v_uid AND status = 'submitted'));
END
$function$
;


-- ═══ FUNCTION notify_shops_closing_soon() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.notify_shops_closing_soon()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now  bigint := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
  v_count int := 0; r record; v_wh jsonb; v_os jsonb; v_mins int; v_item text; v_shop text;
BEGIN
  FOR r IN SELECT b.* FROM public.bookings b
           WHERE b.status IN ('pending','acknowledged')
             AND COALESCE(b.closing_warned,false) = false
             AND b.expiry_time > v_now
  LOOP
    SELECT working_hours INTO v_wh FROM public.users WHERE id = r.store_id;
    IF v_wh IS NULL THEN CONTINUE; END IF;
    v_os := public.store_is_open(v_wh);
    IF COALESCE((v_os->>'configured')::boolean,false)
       AND COALESCE((v_os->>'open')::boolean,false)
       AND (v_os->>'closes_in_min') IS NOT NULL THEN
      v_mins := (v_os->>'closes_in_min')::int;
      IF v_mins > 0 AND v_mins <= 60 THEN
        SELECT item_name, shop_name INTO v_item, v_shop FROM public.deals WHERE id = r.deal_id;
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (r.user_id,
          '🔔 محل ' || COALESCE(v_shop,'التاجر') || ' على وشك الإغلاق',
          '🔔 ' || COALESCE(v_shop,'The shop') || ' is about to close',
          'محل ' || COALESCE(v_shop,'التاجر') || ' سيغلق بعد ' || public.taki_ar_minutes(v_mins) || ' — يُرجى استلام طلب ' || COALESCE(v_item,'حجزك') || ' قبل الإغلاق.',
          COALESCE(v_shop,'The shop') || ' closes in ' || v_mins || ' minutes — please collect your order for ' || COALESCE(v_item,'your booking') || ' before it closes.',
          'booking', jsonb_build_object('audience','buyer','event','closing_soon','barcode',r.barcode,'dealId',r.deal_id), NOW());
        UPDATE public.bookings SET closing_warned = true WHERE barcode = r.barcode;
        v_count := v_count + 1;
      END IF;
    END IF;
  END LOOP;
  RETURN v_count;
END; $function$
;


-- ═══ FUNCTION notify_subscription_invoice() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.notify_subscription_invoice()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s jsonb; v_tax jsonb; v_name text;
  v_vat_on boolean; v_rate numeric; v_incl boolean;
  v_gross numeric; v_vat numeric; v_net numeric; v_total numeric;
  v_entity text; v_period text; v_title text; v_body text; v_html text;
  vars jsonb;
BEGIN
  IF NEW.merchant_id IS NOT NULL AND (
       (TG_OP = 'INSERT' AND NEW.status = 'paid')
    OR (TG_OP = 'UPDATE' AND NEW.status = 'paid' AND OLD.status IS DISTINCT FROM 'paid')
  ) THEN
    s := public.taki_msg_setting('sub_new');
    IF NOT COALESCE((s->>'enabled')::boolean, true)
       OR NOT COALESCE((s->'channels'->>'email')::boolean, false) THEN
      RETURN NEW;   -- in-app activation notice comes from the store_profiles trigger
    END IF;

    SELECT u.name INTO v_name FROM users u WHERE u.id = NEW.merchant_id;
    vars := jsonb_build_object(
      'store',   COALESCE(v_name,''),
      'plan',    COALESCE(NEW.plan_id, CASE WHEN COALESCE(NEW.branches_count,0) > 0
                       THEN 'باقة حتى ' || NEW.branches_count || ' مواقع' ELSE 'اشتراك تاكي' END),
      'price',   trim(to_char(COALESCE(NEW.amount,0), 'FM999999990.00')),
      'expires', COALESCE(to_char(NEW.period_end, 'YYYY-MM-DD'), '—'));
    v_title := public.taki_render_template(s->>'title_ar', vars);
    v_body  := public.taki_render_template(s->>'body_ar',  vars);

    IF COALESCE((s->>'email_invoice')::boolean, true) THEN
      v_tax    := COALESCE((SELECT value FROM platform_settings WHERE key = 'tax_settings'), '{}'::jsonb);
      v_vat_on := COALESCE((v_tax->>'vat_enabled')::boolean, false);
      v_rate   := COALESCE(NULLIF(v_tax->>'vat_rate','')::numeric, 15);
      v_incl   := COALESCE((v_tax->>'prices_include_vat')::boolean, true);
      v_entity := COALESCE(NULLIF(v_tax->>'entity_name',''), 'TAKI — تاكي');
      v_gross  := COALESCE(NEW.amount, 0);
      v_vat    := CASE WHEN v_vat_on THEN
                    CASE WHEN v_incl THEN round(v_gross * v_rate / (100 + v_rate), 2)
                         ELSE round(v_gross * v_rate / 100, 2) END
                  ELSE 0 END;
      v_net    := CASE WHEN v_incl THEN v_gross - v_vat ELSE v_gross END;
      v_total  := CASE WHEN v_incl THEN v_gross ELSE v_gross + v_vat END;
      v_period := CASE WHEN NEW.period_start IS NOT NULL AND NEW.period_end IS NOT NULL
                    THEN to_char(NEW.period_start,'YYYY-MM-DD') || ' ← ' || to_char(NEW.period_end,'YYYY-MM-DD')
                    ELSE '—' END;
      v_html := '<p>' || replace(v_body, E'\n', '<br>') || '</p>'
        || '<div style="border:1px solid #e5e7eb;border-radius:12px;padding:16px;margin-top:14px;background:#fafafa;">'
        || '<div style="font-weight:800;font-size:15px;margin-bottom:8px;">🧾 '
        || CASE WHEN v_vat_on AND COALESCE(v_tax->>'vat_number','') <> '' THEN 'فاتورة ضريبية' ELSE 'فاتورة' END /* v13.37 */
        || '</div>'
        || '<div style="font-size:12px;color:#6b7280;margin-bottom:10px;">' || v_entity
        || CASE WHEN COALESCE(v_tax->>'cr_number','') <> '' THEN ' — سجل/وثيقة: ' || (v_tax->>'cr_number') ELSE '' END
        || CASE WHEN v_vat_on AND COALESCE(v_tax->>'vat_number','') <> '' THEN ' — الرقم الضريبي: ' || (v_tax->>'vat_number') ELSE '' END
        || '</div>'
        || '<table style="width:100%;border-collapse:collapse;font-size:13px;">'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">رقم الفاتورة</td><td style="border:1px solid #e5e5e5;padding:7px 10px;font-weight:700;">INV-' || CASE WHEN NEW.invoice_no IS NOT NULL
                     THEN lpad(NEW.invoice_no::text, 6, '0')
                     ELSE NEW.id::text END || '</td></tr>'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">التاريخ</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || to_char(COALESCE(NEW.paid_at, NEW.created_at) AT TIME ZONE 'Asia/Riyadh', 'YYYY-MM-DD HH24:MI') || '</td></tr>'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">العميل (التاجر)</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || COALESCE(v_name,'—') || '</td></tr>'
        || CASE WHEN COALESCE((SELECT vat_number FROM store_profiles WHERE store_id = NEW.merchant_id), '') <> ''
             THEN '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">الرقم الضريبي للعميل</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || (SELECT vat_number FROM store_profiles WHERE store_id = NEW.merchant_id) || '</td></tr>'
             ELSE '' END
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">البيان</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">اشتراك باقة مواقع'
        || CASE WHEN COALESCE(NEW.branches_count,0) > 0 THEN ' (' || NEW.branches_count || ' مواقع)' ELSE '' END
        || ' — الفترة: ' || v_period || '</td></tr>'
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">الصافي</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || trim(to_char(v_net,'FM999999990.00')) || ' ر.س</td></tr>'
        || CASE WHEN v_vat_on THEN '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;">ضريبة القيمة المضافة (' || trim(to_char(v_rate,'FM990.00')) || '%)</td><td style="border:1px solid #e5e5e5;padding:7px 10px;">' || trim(to_char(v_vat,'FM999999990.00')) || ' ر.س</td></tr>' ELSE '' END
        || '<tr><td style="border:1px solid #e5e5e5;padding:7px 10px;background:#fffbe6;font-weight:800;">الإجمالي</td><td style="border:1px solid #e5e5e5;padding:7px 10px;background:#fffbe6;font-weight:800;">' || trim(to_char(v_total,'FM999999990.00')) || ' ر.س</td></tr>'
        || '</table>'
        || '<div style="font-size:11px;color:#9ca3af;margin-top:8px;">للنسخة الرسمية القابلة للطباعة (مع رمز QR): صفحة الاشتراك ← «🧾 فواتيري».</div>'
        || '</div>';
      PERFORM public.taki_queue_email(NEW.merchant_id, 'sub_new', v_title, public.taki_email_wrap(v_title, v_html));
    ELSE
      PERFORM public.taki_queue_email(NEW.merchant_id, 'sub_new', v_title,
          public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
    END IF;
  END IF;
  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  RAISE WARNING 'notify_subscription_invoice: %', SQLERRM;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION pay_provider_on(p_provider text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.pay_provider_on(p_provider text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT CASE
    WHEN lower(COALESCE(p_provider, '')) IN ('sim', 'simulated') AND NOT public.taki_is_lab()
      THEN false
    ELSE COALESCE(
      (SELECT (value ->> p_provider)::boolean FROM public.platform_settings
        WHERE key = 'enabled_pay_providers'), false)
  END;
$function$
;


-- ═══ FUNCTION pending_rating_prompts() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.pending_rating_prompts()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT coalesce(jsonb_agg(jsonb_build_object(
           'barcode',      t.barcode,
           'deal_id',      t.deal_id,
           'store_id',     t.store_id,
           'shop_name',    t.shop_name,
           'completed_at', t.completed_at,
           -- 🪤 مصدرٌ واحد: الوسمان يُشتقّان من الحمولة نفسها فلا ينحرفان عنها.
           'has_rating',   (t.prev_rating IS NOT NULL),
           'has_vote',     (t.my_vote IS NOT NULL),
           'my_vote',      t.my_vote,
           'prev_rating',  t.prev_rating)
           ORDER BY t.completed_at DESC), '[]'::jsonb)
    FROM (
      SELECT b.barcode, b.deal_id, b.store_id, b.completed_at,
             coalesce(d.shop_name, nullif(u.shop, ''), u.name) AS shop_name,
             (SELECT v.is_real FROM public.deal_authenticity_votes v
               WHERE v.user_id = b.user_id AND v.deal_id = b.deal_id
               LIMIT 1) AS my_vote,
             (SELECT jsonb_build_object('id', r.id, 'deal_id', r.deal_id,
                                        'score', r.score,
                                        'comment', coalesce(r.comment, ''))
                FROM public.ratings r
               WHERE r.user_id = b.user_id AND r.store_id = b.store_id
                 AND r.deleted_at IS NULL
               LIMIT 1) AS prev_rating
        FROM public.bookings b
        LEFT JOIN public.deals d ON d.id = b.deal_id
        LEFT JOIN public.users u ON u.id = b.store_id
       WHERE b.user_id = auth.uid()::text
         AND b.status = 'completed'
         AND b.completed_at >= now() - interval '7 days'
         AND b.rating_prompt_at IS NULL
         -- العرضُ لا بدّ أن يبقى: التصويتُ والتقييمُ كلاهما مرتبطٌ بـ`deal_id`
         -- بمفتاحٍ أجنبيّ، فطلبٌ بعرضٍ محذوفٍ حذفاً صلباً لا يُمكن تقييمه.
         AND d.id IS NOT NULL
       ORDER BY b.completed_at DESC
       LIMIT 20
    ) t;
$function$
;


-- ═══ FUNCTION prune_analytics_events(p_keep_days integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.prune_analytics_events(p_keep_days integer DEFAULT 180)
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_count BIGINT;
BEGIN
    DELETE FROM store_analytics_events
     WHERE created_at < NOW() - (p_keep_days || ' days')::interval;
    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$function$
;


-- ═══ FUNCTION prune_device_push_tokens() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.prune_device_push_tokens()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n integer;
BEGIN
  DELETE FROM public.device_push_tokens
   WHERE coalesce(last_used_at, created_at) < now() - interval '90 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$function$
;


-- ═══ FUNCTION prune_push_subscriptions() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.prune_push_subscriptions()
 RETURNS integer
