-- ═══ FUNCTION store_policies(p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.store_policies(p_store_id text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT jsonb_strip_nulls(jsonb_build_object(
    'refund_policy', NULLIF(btrim(COALESCE(sp.refund_policy, '')), ''),
    'store_terms',   NULLIF(btrim(COALESCE(sp.store_terms,   '')), '')))
    || jsonb_build_object(
    'hold_pickup_hours',    public.taki_booking_hold_hours('pickup',   p_store_id),
    'hold_delivery_hours',  public.taki_booking_hold_hours('delivery', p_store_id),
    'hold_pickup_custom',   sp.hold_pickup_hours,
    'hold_delivery_custom', sp.hold_delivery_hours,
    -- v15.50 — الأرضيّةُ تصل الواجهةَ كما يصل السقف، فلا رقمَ مكتوبٌ فيها.
    'hold_min_hours',       public.taki_booking_hold_min(),
    'hold_max_hours',       public.taki_booking_hold_max())
    FROM (SELECT 1) z
    LEFT JOIN public.store_profiles sp ON sp.store_id = p_store_id;
$function$
;


-- ═══ FUNCTION submit_contest_entry(p_contest_id uuid, p_name text, p_phone text, p_answers jsonb, p_social jsonb) DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.submit_contest_entry(p_contest_id uuid, p_name text, p_phone text, p_answers jsonb, p_social jsonb DEFAULT '{}'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
declare
  c record; q jsonb; v_score int := 0; v_max int := 0; v_qual boolean;
  ans text; pts int;
  correct_set jsonb; n_correct int;
  v_uid text := auth.uid()::text;
  v_name text; v_phone text; v_role text;
begin
  if v_uid is null then
    raise exception 'يجب تسجيل الدخول للمشاركة في المسابقة';
  end if;
  -- identity (+ role) from THEIR account; client values are ignored
  select coalesce(nullif(btrim(name), ''), 'مشارك'), nullif(btrim(phone), ''), user_type
    into v_name, v_phone, v_role
  from users where id = v_uid;
  if v_phone is null then
    raise exception 'أكمل رقم جوالك في حسابك أولاً ثم شارك';
  end if;

  select * into c from contests where id = p_contest_id;
  if not found then raise exception 'المسابقة غير موجودة'; end if;
  if c.status <> 'active' then raise exception 'المسابقة غير مفعّلة حالياً'; end if;
  if c.starts_at is not null and now() < c.starts_at then raise exception 'المسابقة لم تبدأ بعد'; end if;
  if c.ends_at  is not null and now() > c.ends_at  then raise exception 'انتهت مدة المسابقة'; end if;

  -- audience gate (admins bypass so the owner can test any audience)
  if v_role is distinct from 'admin' then
    if c.audience = 'sellers' and v_role is distinct from 'seller' then
      raise exception 'هذه المسابقة مخصّصة للتجار فقط';
    end if;
    if c.audience = 'buyers' and v_role = 'seller' then
      raise exception 'هذه المسابقة مخصّصة للمشترين فقط';
    end if;
  end if;

  -- ONE entry per user — v14.77: بالحساب أوّلاً، وبالجوال للصفوف التي سبقت
  -- العمود. الاكتفاء بالجوال كان يسمح بمشاركةٍ ثانية بعد تغييره.
  if exists (
    select 1 from contest_entries e
     where e.contest_id = p_contest_id
       and (e.user_id = v_uid or (e.user_id is null and btrim(e.phone) = v_phone))
  ) then
    raise exception 'لقد شاركت في هذه المسابقة من قبل — لكل مشارك محاولة واحدة فقط';
  end if;

  for q in select * from jsonb_array_elements(c.questions) loop
    -- v12.37: multi-correct — correctAnswers[] first, legacy correctAnswer fallback
    correct_set := q->'correctAnswers';
    if correct_set is null or jsonb_typeof(correct_set) <> 'array' then
      correct_set := '[]'::jsonb;
    end if;
    if jsonb_array_length(correct_set) = 0
       and coalesce(btrim(q->>'correctAnswer'), '') <> '' then
      correct_set := jsonb_build_array(q->>'correctAnswer');
    end if;
    select count(*) into n_correct
      from jsonb_array_elements_text(correct_set) v where btrim(v) <> '';
    if n_correct > 0 then
      pts := coalesce(nullif(q->>'points','')::int, 1);
      v_max := v_max + pts;
      ans := btrim(coalesce(p_answers ->> (q->>'id'), ''));
      if ans <> '' and exists (
        select 1 from jsonb_array_elements_text(correct_set) v
         where btrim(v) <> '' and lower(btrim(v)) = lower(ans)
      ) then
        v_score := v_score + pts;
      end if;
    end if;
  end loop;

  v_qual := case
              when c.pass_mode = 'collect'     then true
              when c.pass_mode = 'any'         then v_score > 0
              when v_max = 0                   then true
              else v_score >= v_max
            end;

  -- 🪤 القيد الفريد يمسك السباق الذي يفلت من `if exists` أعلاه (نداءان
  --    متزامنان يمرّان معاً). ولولا هذا الالتقاط لرأى المشارك خطأ قاعدةٍ خاماً
  --    بالإنجليزية بدل الرسالة التي كُتبت له.
  begin
    insert into contest_entries (contest_id, user_id, name, phone, answers, social_answers, score, max_score, qualified)
    values (p_contest_id, v_uid, v_name, v_phone, coalesce(p_answers,'{}'::jsonb), coalesce(p_social,'{}'::jsonb), v_score, v_max, v_qual);
  exception when unique_violation then
    raise exception 'لقد شاركت في هذه المسابقة من قبل — لكل مشارك محاولة واحدة فقط';
  end;

  return jsonb_build_object('success', true, 'qualified', v_qual, 'score', v_score, 'max_score', v_max);
end; $function$
;


-- ═══ FUNCTION subscribe_self_to_package(p_package_id integer) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.subscribe_self_to_package(p_package_id integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := auth.uid()::text; v_role text; v_res jsonb;
BEGIN
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_authenticated');
  END IF;
  SELECT user_type INTO v_role FROM public.users WHERE id = v_uid;
  IF v_role NOT IN ('seller', 'admin') THEN
    RETURN jsonb_build_object('success', false, 'error', 'not_a_merchant');
  END IF;
  v_res := public._taki_apply_package_dry(p_package_id);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN RETURN v_res; END IF;
  IF NOT public._taki_sub_payment_ok(v_uid, p_package_id, (v_res->>'net')::numeric) THEN
    RETURN jsonb_build_object('success', false, 'error', 'payment_not_confirmed');
  END IF;
  -- مسارُ البوّابة: لا تاريخَ من متجرٍ ⇒ مدّةُ الكتالوج، والتجديدُ يُفعَّل.
  RETURN public._taki_apply_package(v_uid, p_package_id, NULL, true);
END $function$
;


-- ═══ FUNCTION sync_auth_lang() DEFINER owner=supabase_admin search_path=search_path=public, auth, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.sync_auth_lang()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'auth', 'pg_temp'
AS $function$
DECLARE
  v_lang text;
BEGIN
  v_lang := CASE WHEN lower(btrim(coalesce(new.preferred_lang, ''))) = 'en'
                 THEN 'en' ELSE 'ar' END;

  UPDATE auth.users au
     SET raw_user_meta_data =
           jsonb_set(coalesce(au.raw_user_meta_data, '{}'::jsonb),
                     '{lang}', to_jsonb(v_lang), true)
   WHERE au.id::text = new.id
     AND coalesce(au.raw_user_meta_data->>'lang', '') IS DISTINCT FROM v_lang;

  RETURN new;
END;
$function$
;


-- ═══ FUNCTION sync_branch_count() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.sync_branch_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_merchant TEXT;
    v_count INTEGER;
BEGIN
    v_merchant := COALESCE(NEW.merchant_id, OLD.merchant_id);
    SELECT COUNT(*) INTO v_count FROM store_branches
     WHERE merchant_id = v_merchant AND is_active = TRUE;
    UPDATE merchant_subscriptions
       SET branches_count = GREATEST(1, v_count), updated_at = NOW()
     WHERE merchant_id = v_merchant;
    RETURN COALESCE(NEW, OLD);
END;
$function$
;


-- ═══ FUNCTION system_health_public() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.system_health_public()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'status',      h.status,
    'issues',      h.issues,
    'seen_at',     h.seen_at,
    'age_seconds', GREATEST(0, floor(extract(epoch FROM (now() - h.seen_at)))::bigint)
  )
  FROM public.system_heartbeat h WHERE h.id = 1;
$function$
;


-- ═══ FUNCTION taki_admin_finance() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_admin_finance()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.taki_admin_perm('action_view_finance')
      OR public.taki_admin_perm('tab_launch');
$function$
;


-- ═══ FUNCTION taki_admin_perm(p_perm text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_admin_perm(p_perm text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = (SELECT auth.uid())::text
      AND u.user_type = 'admin'
      AND u.deleted_at IS NULL
      AND ( COALESCE(u.is_super_admin, false)
         OR p_perm = ANY(COALESCE(u.admin_permissions, '{}'::text[])) )
  );
$function$
;


-- ═══ FUNCTION taki_alert_dispatch(p_title text, p_body text, p_level text, p_key text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_alert_dispatch(p_title text, p_body text, p_level text DEFAULT 'crit'::text, p_key text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_chan   jsonb;
  v_to     text;
  v_key    text;
  v_fp     text;
  v_floor  int;
  v_req    bigint;
  v_html   text;
BEGIN
  -- البصمةُ: مفتاحُ المنادي + محتوى الرسالة. فمحتوًى مختلفٌ يمرّ، ومكرَّرٌ
  -- حرفيٌّ يُكتم — وهي أرضيّةٌ **أضعفُ** من تهدئة المنادي عمداً، فلا تُلغيها.
  v_fp := COALESCE(p_key, 'alert') || ':' || md5(COALESCE(p_title,'') || '|' || COALESCE(p_body,''));

  SELECT value INTO v_chan FROM public.platform_settings WHERE key = 'alert_channels';
  IF COALESCE((v_chan->>'email')::boolean, false) IS NOT TRUE THEN
    INSERT INTO public.taki_alert_log (fingerprint, level, channel, ok, reason, title)
    VALUES (v_fp, p_level, 'email', false, 'channel_off', left(COALESCE(p_title,''), 200));
    RETURN jsonb_build_object('sent', false, 'reason', 'channel_off');
  END IF;

  -- 🪤 وقيمةٌ غيرُ رقميّةٍ في الإعداد لا تُجهض التنبيه: `::int` على نصٍّ
  --    فاسدٍ يرفع استثناءً، ومسارٌ مُجهَضٌ هنا يعني تنبيهاً **ضائعاً** بسبب
  --    خطأِ ضبطٍ — فالارتدادُ إلى الافتراضيّ أصحُّ من السقوط.
  BEGIN
    v_floor := GREATEST(COALESCE((v_chan->>'min_minutes')::int, 30), 0);
  EXCEPTION WHEN OTHERS THEN
    v_floor := 30;
  END;
  IF EXISTS (SELECT 1 FROM public.taki_alert_log
              WHERE fingerprint = v_fp AND ok
                AND sent_at > now() - make_interval(mins => v_floor)) THEN
    RETURN jsonb_build_object('sent', false, 'reason', 'deduped');
  END IF;

  SELECT value #>> '{}' INTO v_to FROM public.platform_settings WHERE key = 'alert_email';
  -- 🪤 عنوانٌ مشوَّهٌ يُنتج نداءً يفشل بصمت، فيُفحص بالصيغة قبل الإرسال
  --    (نفسُ حارسِ `contact_emails` في الواجهة — درسُ الرابط المعطوب v14.77).
  IF COALESCE(v_to,'') !~ '^[^[:space:]@]+@([A-Za-z0-9-]+\.)+[A-Za-z]{2,}$' THEN
    INSERT INTO public.taki_alert_log (fingerprint, level, channel, ok, reason, title)
    VALUES (v_fp, p_level, 'email', false, 'no_address', left(COALESCE(p_title,''), 200));
    RETURN jsonb_build_object('sent', false, 'reason', 'no_address');
  END IF;

  -- 🪤 الخزنةُ تُقرأ **بعد** الفحوص — نفسُ ترتيب v15.51 في
  --    `handle_notification_push`: لا قراءةَ سرٍّ لنداءٍ لن يحدث.
  BEGIN
    SELECT value INTO v_key FROM public.app_secrets WHERE key = 'resend_api_key';
  EXCEPTION WHEN OTHERS THEN
    v_key := NULL;
  END;
  IF COALESCE(v_key,'') = '' THEN
    INSERT INTO public.taki_alert_log (fingerprint, level, channel, ok, reason, title)
    VALUES (v_fp, p_level, 'email', false, 'no_secret', left(COALESCE(p_title,''), 200));
    RETURN jsonb_build_object('sent', false, 'reason', 'no_secret');
  END IF;

  -- الجسمُ عربيٌّ وإنجليزيٌّ معاً: المنصّةُ ثنائيّةُ اللغة، والتنبيهُ يُقرأ
  -- على جوّالٍ قد يكون بأيّ منهما.
  -- 🪤 ولا تهريبَ HTML هنا عن قصدٍ مقيس: المنادِيان الوحيدان يبنيان النصَّ
  --    من ثوابتَ ومن `format()` على أرقامِ خادمٍ وأسماءِ وظائفَ — صفرُ مدخلٍ
  --    من مستخدم. وأيُّ منادٍ **قادمٍ** يحمل نصَّ مستخدمٍ يجب أن يهرّبه قبل
  --    النداء، وإلّا صار البريدُ سطحَ حقنٍ في صندوقِ ناصر.
  v_html :=
      '<div dir="rtl" style="font:16px/1.7 -apple-system,system-ui,sans-serif">'
   || '<h3 style="margin:0 0 8px">' || p_title || '</h3>'
   || '<pre style="white-space:pre-wrap;font:inherit;margin:0">' || COALESCE(p_body,'') || '</pre>'
   || '<p style="color:#666;font-size:13px">المستوى / level: ' || COALESCE(p_level,'') || '</p>'
   || '</div>'
   || '<hr><div dir="ltr" style="font:14px/1.6 -apple-system,system-ui,sans-serif;color:#444">'
   || 'TAKI server alert. This message is sent straight from the database, '
   || 'independently of the bots and of web push.'
   || '</div>';

  BEGIN
    SELECT net.http_post(
      url     := 'https://api.resend.com/emails',
      body    := jsonb_build_object(
                   'from',    'TAKI <no-reply@takisa.net>',
                   'to',      jsonb_build_array(v_to),
                   'subject', p_title,
                   'html',    v_html),
      headers := jsonb_build_object(
                   'Content-Type',  'application/json',
                   'Authorization', 'Bearer ' || v_key),
      timeout_milliseconds := 5000
    ) INTO v_req;
  EXCEPTION WHEN OTHERS THEN
    -- 🔴 و«ابتلاعُ الاستثناء» هنا لا يُخفي العيب: السببُ يُكتب في السجلّ،
    --    فالإدراجُ في معالِج الاستثناء ينجو من تراجعِ الكتلة الداخليّة.
    INSERT INTO public.taki_alert_log (fingerprint, level, channel, ok, reason, title)
    VALUES (v_fp, p_level, 'email', false, 'http_error:' || left(SQLERRM, 120), left(COALESCE(p_title,''), 200));
    RETURN jsonb_build_object('sent', false, 'reason', 'http_error');
  END;

  INSERT INTO public.taki_alert_log (fingerprint, level, channel, ok, reason, request_id, title)
  VALUES (v_fp, p_level, 'email', true, 'queued', v_req, left(COALESCE(p_title,''), 200));

  -- تنظيفٌ ذاتيٌّ بلا كرونٍ جديد: الحجمُ قِيس ٣٣ تنبيهاً في أحد عشر أسبوعاً.
  DELETE FROM public.taki_alert_log WHERE sent_at < now() - interval '180 days';

  RETURN jsonb_build_object('sent', true, 'reason', 'queued', 'request_id', v_req);
END $function$
;


-- ═══ FUNCTION taki_ar_days(p_n integer) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_ar_days(p_n integer)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN p_n = 1 THEN 'يوم واحد'
    WHEN p_n = 2 THEN 'يومان'
    WHEN p_n BETWEEN 3 AND 10 THEN p_n::text || ' أيام'
    ELSE p_n::text || ' يوماً'
  END;
$function$
;


