-- ═══ FUNCTION taki_audit_notification_types() INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_audit_notification_types()
 RETURNS TABLE(fn text, bad_type text)
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  WITH f AS (
    SELECT p.proname::text AS fn, pg_get_functiondef(p.oid) AS def
      FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
     WHERE n.nspname = 'public' AND p.prokind IN ('f','p')
  ), ins AS (
    SELECT fn, def FROM f WHERE def ~* 'INSERT INTO (public\.)?notifications'
  ), lit AS (
    SELECT fn,
           (regexp_matches(def,
             $re$'([a-z_]+)'\s*,\s*(?:jsonb_build_object|'\{|COALESCE\s*\(\s*p_meta|p_meta|v_meta)$re$,
             'g'))[1] AS t
      FROM ins
  ), allowed AS (
    SELECT unnest(ARRAY['booking','deal','system','rating','follow','marketing',
                        'report','subscription','contest']) AS t
  )
  SELECT DISTINCT l.fn, l.t
    FROM lit l
   WHERE l.t NOT IN (SELECT t FROM allowed)
     -- مفاتيح jsonb معروفة ليست أنواعاً (سببُ أوّل إنذارٍ كاذب)
     AND l.t NOT IN ('dates','notified','audience','event','barcode','channels')
   ORDER BY 1, 2;
$function$
;


-- ═══ FUNCTION taki_audit_payment_drift() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_audit_payment_drift()
 RETURNS TABLE(store_id text, accepts_cod boolean, payment_modes text, effective_mode text)
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT sp.store_id, sp.accepts_cod, mg.payment_modes,
         public.deal_payment_mode(sp.store_id)
    FROM public.store_profiles sp
    JOIN public.merchant_gateways mg ON mg.merchant_id = sp.store_id
   WHERE sp.accepts_cod IS DISTINCT FROM (mg.payment_modes <> 'online');
$function$
;


-- ═══ FUNCTION taki_autocancel_blocked(p_barcode text, p_booked_at bigint, p_expiry_time bigint, p_paid boolean) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_autocancel_blocked(p_barcode text, p_booked_at bigint, p_expiry_time bigint, p_paid boolean)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- (أ) طلبٌ دفع صاحبه بالبطاقة لا يُلغى تلقائياً أبداً. إلغاؤه يخلق مطالبة
  --     استرداد كاذبة، ولا أحد يراجعها.
  SELECT COALESCE(p_paid, false)
      -- (ب) وطلبُ توصيلٍ توقّف عدّاده: محميٌّ حتى تنتهي شبكةُ الأمان.
      -- 🔴 v15.49 — تُقرأ حقيقةُ الانطلاق لا `status`: كان المنظّفُ يكتب
      --    `cancelled` بعد ساعةٍ من صمت الهاتف فتسقط الحمايةُ ويُلغى طلبٌ
      --    وصل صاحبَه فعلاً وتعود بضاعتُه للبيع.
      -- 🔴 وشبكةُ الأمان كانت تساوي صفراً عند الحدّ (مهلةٌ ٧٢ وشبكةٌ ٧٢):
      --    فكلُّ طلبٍ يُحمى حتى **ساعةٍ بعد انتهاء مهلته هو** على الأقلّ،
      --    فلا تُنقص مهلةُ تاجرٍ ولا تبقى الحمايةُ معدومةً عند أيّ ضبط.
      OR ( public.taki_delivery_hold_stopped(p_barcode)
           AND GREATEST(
                 COALESCE(p_booked_at, 0) + (public.taki_booking_grace_hours() * 3600000)::bigint,
                 COALESCE(p_expiry_time, 0) + 3600000)
               > (EXTRACT(EPOCH FROM NOW())*1000)::bigint );
$function$
;


-- ═══ FUNCTION taki_block_since(p_a text, p_b text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_block_since(p_a text, p_b text)
 RETURNS timestamp with time zone
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT min(created_at) FROM public.user_blocks
   WHERE (blocker_id = p_a AND blocked_id = p_b)
      OR (blocker_id = p_b AND blocked_id = p_a);
$function$
;


-- ═══ FUNCTION taki_booking_amount(p_deal_id text, p_quantity integer, p_selected jsonb, p_delivery_fee numeric) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_booking_amount(p_deal_id text, p_quantity integer, p_selected jsonb, p_delivery_fee numeric)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_price   numeric;
  v_opts    jsonb;
  v_vars    jsonb;
  v_sel     jsonb := CASE WHEN jsonb_typeof(COALESCE(p_selected, 'null'::jsonb)) = 'array'
                          THEN p_selected ELSE '[]'::jsonb END;
  v_row     jsonb;
  v_node    jsonb;
  v_base    numeric := 0;
  v_addons  numeric := 0;
  v_variant boolean := false;
  v_dlv     numeric := round(GREATEST(COALESCE(p_delivery_fee, 0), 0), 2);
BEGIN
  SELECT d.discounted_price, d.options, d.variants
    INTO v_price, v_opts, v_vars
    FROM public.deals d WHERE d.id = p_deal_id;

  -- الأساس: مجموع النسخ المختارة (لكلٍّ سعرها)، وإلا سعر العرض × الكمية.
  IF jsonb_typeof(COALESCE(v_vars, 'null'::jsonb)) = 'array' THEN
    FOR v_row IN SELECT * FROM jsonb_array_elements(v_sel) LOOP
      CONTINUE WHEN v_row->>'g' IS DISTINCT FROM '__variant__';
      SELECT e INTO v_node FROM jsonb_array_elements(v_vars) e
        WHERE e->>'id' = v_row->>'c' LIMIT 1;
      CONTINUE WHEN v_node IS NULL;
      v_variant := true;
      v_base := v_base + COALESCE(NULLIF(v_node->>'price','')::numeric, 0)
                       * GREATEST(COALESCE(NULLIF(v_row->>'qty','')::int, 1), 1);
    END LOOP;
  END IF;
  IF NOT v_variant THEN
    v_base := COALESCE(v_price, 0) * GREATEST(COALESCE(p_quantity, 1), 1);
  END IF;

  -- الإضافات: سعر كل خيار × عدد القطع التي اختارته (جبنة +٣ على برغرين = +٦).
  IF jsonb_typeof(COALESCE(v_opts, 'null'::jsonb)) = 'array' THEN
    FOR v_row IN SELECT * FROM jsonb_array_elements(v_sel) LOOP
      CONTINUE WHEN v_row->>'g' = '__variant__';
      SELECT c INTO v_node
        FROM jsonb_array_elements(v_opts) g,
             jsonb_array_elements(CASE WHEN jsonb_typeof(COALESCE(g->'choices','null'::jsonb)) = 'array'
                                       THEN g->'choices' ELSE '[]'::jsonb END) c
       WHERE g->>'id' = v_row->>'g' AND c->>'id' = v_row->>'c' LIMIT 1;
      CONTINUE WHEN v_node IS NULL;
      v_addons := v_addons + COALESCE(NULLIF(v_node->>'price','')::numeric, 0)
                           * GREATEST(COALESCE(NULLIF(v_row->>'qty','')::int, 1), 1);
    END LOOP;
  END IF;

  RETURN jsonb_build_object(
    'base',     round(v_base, 2),
    'addons',   round(v_addons, 2),
    'goods',    round(v_base + v_addons, 2),
    'delivery', v_dlv,
    'total',    round(v_base + v_addons + v_dlv, 2));
END
$function$
;


-- ═══ FUNCTION taki_booking_grace_hours() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_booking_grace_hours()
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT GREATEST(1, LEAST(8760, COALESCE(
    (SELECT (value->>'in_progress_hours')::numeric
       FROM public.platform_settings WHERE key = 'booking_holds' LIMIT 1), 72)));
$function$
;


-- ═══ FUNCTION taki_booking_hold_hours(p_fulfillment text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_booking_hold_hours(p_fulfillment text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT GREATEST(
    public.taki_booking_hold_min(),         -- v15.50: الأرضيّة إعدادٌ لا ثابت
    LEAST(
      8760,                                 -- ولا أطول من سنة
      COALESCE(
        (SELECT CASE WHEN COALESCE(p_fulfillment,'pickup') = 'delivery'
                     THEN (value->>'delivery_hours')::numeric
                     ELSE (value->>'pickup_hours')::numeric END
           FROM public.platform_settings WHERE key = 'booking_holds' LIMIT 1),
        CASE WHEN COALESCE(p_fulfillment,'pickup') = 'delivery' THEN 6 ELSE 2 END
      )
    )
  );
$function$
;


-- ═══ FUNCTION taki_booking_hold_hours(p_fulfillment text, p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_booking_hold_hours(p_fulfillment text, p_store_id text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE(
    -- استثناءُ التاجر، مقصوصاً بين الأرضيّة وسقف المنصّة
    (SELECT GREATEST(public.taki_booking_hold_min(), LEAST(public.taki_booking_hold_max(),
              CASE WHEN COALESCE(p_fulfillment,'pickup') = 'delivery'
                   THEN sp.hold_delivery_hours ELSE sp.hold_pickup_hours END))
       FROM public.store_profiles sp
      WHERE sp.store_id = p_store_id
        AND (CASE WHEN COALESCE(p_fulfillment,'pickup') = 'delivery'
                  THEN sp.hold_delivery_hours ELSE sp.hold_pickup_hours END) IS NOT NULL
      LIMIT 1),
    -- وإلّا افتراضُ المنصّة كما كان حرفاً بحرف
    public.taki_booking_hold_hours(p_fulfillment)
  );
$function$
;


-- ═══ FUNCTION taki_booking_hold_max() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_booking_hold_max()
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- 🪤 ولا تنادي هذه `taki_booking_hold_min()`: الأخيرةُ تناديها، فالعكسُ دور.
  SELECT GREATEST(0.25, LEAST(8760, COALESCE(
    (SELECT NULLIF(value->>'max_hold_hours','')::numeric
       FROM public.platform_settings WHERE key = 'booking_holds' LIMIT 1), 72)));
$function$
;


-- ═══ FUNCTION taki_booking_hold_min() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_booking_hold_min()
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- أرضيّةُ مهلة الحجز. يضبطها ناصر، ولا تتجاوز السقفَ أبداً (وإلّا صار
  -- المدى مقلوباً فيُرفض كلُّ رقم)، ولا تنزل عن ربع ساعة تقنيّاً.
  SELECT GREATEST(0.25, LEAST(public.taki_booking_hold_max(), COALESCE(
    (SELECT NULLIF(value->>'min_hold_hours','')::numeric
       FROM public.platform_settings WHERE key = 'booking_holds' LIMIT 1), 1)));
$function$
;


-- ═══ FUNCTION taki_booking_options_fault(p_deal_id text, p_selected jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_booking_options_fault(p_deal_id text, p_selected jsonb)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_opts jsonb; v_vars jsonb; v_grp jsonb; v_sel jsonb; v_var jsonb;
  v_arr  jsonb := CASE WHEN jsonb_typeof(COALESCE(p_selected, 'null'::jsonb)) = 'array'
                       THEN p_selected ELSE '[]'::jsonb END;
BEGIN
  SELECT CASE WHEN jsonb_typeof(d.options)  = 'array' THEN d.options  ELSE '[]'::jsonb END,
         CASE WHEN jsonb_typeof(d.variants) = 'array' THEN d.variants ELSE '[]'::jsonb END
    INTO v_opts, v_vars
    FROM public.deals d WHERE d.id = p_deal_id;
  -- عرضٌ غير موجود: لا قاعدةَ تُطبَّق هنا (المفتاحُ الأجنبيُّ على `deal_id` هو
  -- موضعُ ذلك)، وسلوكُ النصّ السابق نفسُه.
  IF v_opts IS NULL THEN RETURN NULL; END IF;

  -- (١) 🔴 كلُّ مدخلٍ يُشير إلى شيءٍ **موجودٍ فعلاً**. وبلا هذا الشرط يكون
  --     الشرطان (٢) و(٣) قابلَين للتجاوز بمعرّفٍ مخترَع: `taki_booking_amount`
  --     تتجاوز المجهول (`CONTINUE WHEN v_node IS NULL`) فتُسقط ثمنَه، ومدخلٌ
  --     بمعرّفِ نسخةٍ وهميّ يُرضي (٢) ثم يُسقط الأساسَ إلى سعرِ العرض.
  FOR v_sel IN SELECT * FROM jsonb_array_elements(v_arr) LOOP
    IF v_sel->>'g' = '__variant__' THEN
      IF NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_vars) e WHERE e->>'id' = v_sel->>'c') THEN
        RETURN 'NEEDS_OPTIONS';
      END IF;
    ELSE
      IF NOT EXISTS (
        SELECT 1 FROM jsonb_array_elements(v_opts) g,
             jsonb_array_elements(CASE WHEN jsonb_typeof(g->'choices') = 'array'
                                       THEN g->'choices' ELSE '[]'::jsonb END) c
         WHERE g->>'id' = v_sel->>'g' AND c->>'id' = v_sel->>'c')
      THEN
        RETURN 'NEEDS_OPTIONS';
      END IF;
    END IF;
  END LOOP;

  -- (٢) 🔴 عرضٌ له نسخ ⇒ لا بدّ من اختيار نسخة — **لكلّ المصادر**. كان هذا
  --     الشرطُ داخل `IF COALESCE(NEW.source,'web') <> 'web'`، فالويبُ معفى.
  IF jsonb_array_length(v_vars) > 0
     AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_arr) s WHERE s->>'g' = '__variant__')
  THEN
    RETURN 'NEEDS_OPTIONS';
  END IF;

  -- (٣) كلُّ مجموعةٍ إلزاميّةٍ مختارة — لكلّ المصادر كذلك
  FOR v_grp IN SELECT * FROM jsonb_array_elements(v_opts) LOOP
    IF COALESCE((v_grp->>'required')::boolean, false)
       AND NOT EXISTS (SELECT 1 FROM jsonb_array_elements(v_arr) s WHERE s->>'g' = v_grp->>'id')
    THEN
      RETURN 'NEEDS_OPTIONS';
    END IF;
  END LOOP;

  -- (٤) كمّيةُ النسخة المتبقّية تكفي المطلوب (كما كان، بلا تغييرٍ في النصّ)
  FOR v_sel IN SELECT * FROM jsonb_array_elements(v_arr) LOOP
    CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
    SELECT e INTO v_var FROM jsonb_array_elements(v_vars) e WHERE e->>'id' = v_sel->>'c' LIMIT 1;
    CONTINUE WHEN v_var IS NULL OR NOT (v_var ? 'qty') OR NULLIF(v_var->>'qty','') IS NULL;
    IF (v_var->>'qty')::numeric < GREATEST(COALESCE((v_sel->>'qty')::int,1),1) THEN
      RETURN 'VARIANT_STOCK:' || COALESCE(v_var->>'label','?') || ':'
             || GREATEST((v_var->>'qty')::int, 0)::text;
    END IF;
  END LOOP;

  RETURN NULL;
END
$function$
;


-- ═══ FUNCTION taki_can_upload_deal_image() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_can_upload_deal_image()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.users u
    WHERE u.id = (SELECT auth.uid())::text
      AND u.deleted_at IS NULL
      AND COALESCE(u.is_suspended, false) = false
      AND (u.user_type IN ('seller','admin') OR NULLIF(btrim(COALESCE(u.shop,'')), '') IS NOT NULL)
  );
$function$
;


-- ═══ FUNCTION taki_cancel_abuse_scan() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_cancel_abuse_scan()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s jsonb; v_cats text[]; v_window int; v_thresh int;
  v_cb boolean; v_ct boolean; v_gap int; v_before int; v_action text; v_ban_days int;
  r record; v_warn_count int; v_last timestamptz; v_wid uuid; v_msg text; v_delay int;
BEGIN
  SELECT value INTO s FROM platform_settings WHERE key = 'cancel_abuse_settings';
  IF s IS NULL OR COALESCE((s->>'enabled')::boolean, false) IS NOT TRUE THEN RETURN; END IF;
  v_cats     := COALESCE(ARRAY(SELECT jsonb_array_elements_text(s->'categories')), '{}');
  v_window   := GREATEST(COALESCE((s->>'window_days')::int, 30), 1);
  v_thresh   := GREATEST(COALESCE((s->>'cancel_threshold')::int, 3), 1);
  v_cb       := COALESCE((s->>'count_buyer_cancel')::boolean, true);
  v_ct       := COALESCE((s->>'count_timeout')::boolean, true);
  v_gap      := GREATEST(COALESCE((s->>'warn_gap_hours')::int, 72), 1);
  v_before   := GREATEST(COALESCE((s->>'warnings_before_action')::int, 3), 1);
  v_action   := COALESCE(s->>'action', 'booking_ban');
  v_ban_days := GREATEST(COALESCE((s->>'ban_days')::int, 7), 1);
  v_delay    := COALESCE((SELECT (value->>'warn_delay_minutes')::int FROM platform_settings WHERE key = 'moderation_settings'), 0);

  FOR r IN
    SELECT b.user_id, u.name, count(*) AS n
    FROM bookings b
    JOIN deals d ON d.id = b.deal_id
    JOIN users u ON u.id = b.user_id
    WHERE b.status = 'cancelled'
      AND ((v_cb AND b.cancelled_by = 'buyer') OR (v_ct AND b.cancelled_by = 'timeout'))
      AND b.created_at >= now() - make_interval(days => v_window)
      AND (cardinality(v_cats) = 0 OR d.category = ANY(v_cats))
      AND u.user_type <> 'admin'
      AND COALESCE(u.is_suspended, false) = false
      AND (u.booking_banned_until IS NULL OR u.booking_banned_until < now())
      -- 🔴 v14.32 — العقوبة كانت تُجدّد نفسها إلى ما لا نهاية.
      -- السبب: فحص المهلة وعدّاد الإنذارات يبحثان عن صفوفٍ نصّها يبدأ بـ
      -- «⚠️ إلغاءات متكررة»، بينما صفّ **العقوبة** نصّه يبدأ بـ«⏸️ تم تعليق
      -- الحجز» أو «⛔ تم إيقاف حسابك». فالماسح لا يرى عقوبته السابقة إطلاقاً.
      -- والنتيجة: مشترٍ عوقب ٧ أيام على ثلاثة إلغاءات، يُعاقَب ٧ أيام أخرى
      -- فور انقضائها على **نفس** الإلغاءات، ويتكرّر حتى تخرج من نافذة الثلاثين
      -- يوماً — أي حظرٌ شبه دائم على مخالفةٍ واحدة.
      -- العلاج: لا يُحسب إلا ما وقع **بعد** آخر إجراء. فالعقوبة مرّة لكل مجموعة.
      AND b.created_at > COALESCE((
            SELECT max(w.created_at) FROM user_warnings w
             WHERE w.user_id = b.user_id
               AND (w.reason LIKE '⏸️ تم تعليق الحجز%'
                 OR w.reason LIKE '⛔ تم إيقاف حسابك بسبب تكرار%')
          ), '-infinity'::timestamptz)
    GROUP BY b.user_id, u.name
    HAVING count(*) >= v_thresh
  LOOP
    -- المهلة بين إنذار وإنذار — يحددها المالك
    -- المهلة تُقاس من آخر **أي** إجراء (إنذاراً كان أو عقوبة) لا من آخر إنذار
    -- وحده — وإلا أنذر الماسحُ من عاقبه قبل ساعة.
    SELECT max(created_at) INTO v_last FROM user_warnings
     WHERE user_id = r.user_id
       AND (reason LIKE '⚠️ إلغاءات متكررة%'
         OR reason LIKE '⏸️ تم تعليق الحجز%'
         OR reason LIKE '⛔ تم إيقاف حسابك بسبب تكرار%');
    IF v_last IS NOT NULL AND v_last > now() - make_interval(hours => v_gap) THEN CONTINUE; END IF;

    SELECT count(*) INTO v_warn_count FROM user_warnings
     WHERE user_id = r.user_id AND reason LIKE '⚠️ إلغاءات متكررة%';

    IF v_warn_count < v_before THEN
      v_msg := format('⚠️ إلغاءات متكررة: رصدنا %s حجوزات ملغاة أو غير مستلمة خلال آخر %s يوماً. تكرار ذلك سيؤدي لتعليق الحجز أو إيقاف الحساب. (إنذار %s من %s)', r.n, v_window, v_warn_count + 1, v_before);
      INSERT INTO user_warnings (user_id, user_role, reason, admin_id)
      VALUES (r.user_id, 'buyer', v_msg, NULL) RETURNING id INTO v_wid;
      IF v_delay <= 0 THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (r.user_id, '⚠️ تنبيه من إدارة تاكي', '⚠️ Warning from TAKI', v_msg, v_msg, 'system',
                jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
      ELSE
        INSERT INTO pending_warnings (warning_id, user_id, message, deliver_at)
        VALUES (v_wid, r.user_id, v_msg, now() + make_interval(mins => v_delay));
      END IF;
    ELSE
      IF v_action = 'suspend' THEN
        UPDATE users SET is_suspended = true WHERE id = r.user_id;
        v_msg := '⛔ تم إيقاف حسابك بسبب تكرار إلغاء الحجوزات بعد عدة إنذارات — تواصل مع إدارة تاكي.';
      ELSE
        UPDATE users SET booking_banned_until = now() + make_interval(days => v_ban_days),
                         booking_ban_reason = 'إلغاءات متكررة (آلي)'
         WHERE id = r.user_id;
        v_msg := format('⏸️ تم تعليق الحجز على حسابك لمدة %s أيام بسبب تكرار الإلغاء/عدم الاستلام بعد عدة إنذارات.', v_ban_days);
      END IF;
      INSERT INTO user_warnings (user_id, user_role, reason, admin_id)
      VALUES (r.user_id, 'buyer', v_msg, NULL);
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES (r.user_id, '⛔ إجراء من إدارة تاكي', '⛔ TAKI enforcement', v_msg, v_msg, 'system',
              jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      SELECT id, '🚫 عقوبة إلغاءات متكررة', '🚫 Cancel-abuse action',
             format('طُبقت عقوبة تلقائية على «%s»: %s', COALESCE(r.name, r.user_id), v_msg),
             'Automatic cancel-abuse action applied', 'system',
             jsonb_build_object('audience', 'admin')
      FROM users WHERE user_type = 'admin';
    END IF;
  END LOOP;
END $function$
;


-- ═══ FUNCTION taki_capacity_check() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_capacity_check()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r jsonb := public.taki_capacity_report();
  lim jsonb := r->'limits';
  v_cool interval := make_interval(hours => COALESCE((lim->>'cooldown_hours')::int, 6));
  v_raised int := 0;
  m record;
BEGIN
  FOR m IN
    SELECT * FROM (VALUES
      ('db_connections', 'اتصالاتُ القاعدة',      (r->'db_connections'->>'pct')::numeric,
         COALESCE((lim->>'db_connections_warn_pct')::numeric, 70), COALESCE((lim->>'db_connections_crit_pct')::numeric, 85), '٪'),
      ('db_size',        'حجمُ القاعدة',          (r->>'db_size_mb')::numeric,
         COALESCE((lim->>'db_size_warn_mb')::numeric, 4096),       COALESCE((lim->>'db_size_crit_mb')::numeric, 8192), ' م.ب'),
      ('storage',        'حجمُ الصور والملفّات',   (r->>'storage_mb')::numeric,
         COALESCE((lim->>'storage_warn_mb')::numeric, 20480),      COALESCE((lim->>'storage_crit_mb')::numeric, 40960), ' م.ب'),
      ('email_daily',    'بريدُ اليوم (سقفُ المزوّد)', (r->>'email_24h')::numeric,
         COALESCE((lim->>'email_daily_warn')::numeric, 80),        COALESCE((lim->>'email_daily_crit')::numeric, 95), ' رسالة'),
      ('cron_fail',      'وظائفُ الخادم الفاشلة',  (r->>'cron_fail_24h')::numeric,
         COALESCE((lim->>'cron_fail_warn')::numeric, 3),           COALESCE((lim->>'cron_fail_crit')::numeric, 10), '')
    ) AS t(metric, label, val, warn, crit, unit)
  LOOP
    IF m.val >= m.crit OR m.val >= m.warn THEN
      DECLARE
        v_level text := CASE WHEN m.val >= m.crit THEN 'crit' ELSE 'warn' END;
        v_prev  public.capacity_alerts%ROWTYPE;
      BEGIN
        SELECT * INTO v_prev FROM public.capacity_alerts WHERE metric = m.metric;
        -- لا يتكرّر الإنذارُ قبل التهدئة، إلا إن تصاعد من تحذيرٍ إلى حرج.
        -- 🪤 والمقارنةُ برتبةٍ صريحة لا أبجديّة: `GREATEST('crit','warn')='warn'`.
        IF v_prev.metric IS NOT NULL
           AND v_prev.cleared_at IS NULL
           AND v_prev.raised_at > now() - v_cool
           AND NOT (v_level = 'crit' AND v_prev.level = 'warn') THEN
          CONTINUE;
        END IF;

        INSERT INTO public.capacity_alerts (metric, level, value_num, limit_num, raised_at, cleared_at)
        VALUES (m.metric, v_level, m.val, CASE WHEN v_level='crit' THEN m.crit ELSE m.warn END, now(), NULL)
        ON CONFLICT (metric) DO UPDATE
          SET level = EXCLUDED.level, value_num = EXCLUDED.value_num,
              limit_num = EXCLUDED.limit_num, raised_at = now(), cleared_at = NULL;

        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        SELECT u.id,
          CASE WHEN v_level='crit' THEN '🔴 بلغت الطاقة القصوى: ' ELSE '🟠 اقتربت الطاقة القصوى: ' END || m.label,
          CASE WHEN v_level='crit' THEN '🔴 Capacity reached: '   ELSE '🟠 Capacity near: '        END || m.metric,
          m.label || ' الآن ' || trim(to_char(m.val, 'FM999999999990.9')) || m.unit
            || ' والحدُّ ' || trim(to_char(CASE WHEN v_level='crit' THEN m.crit ELSE m.warn END, 'FM999999999990.9')) || m.unit
            || '. تُضبط الحدودُ من «الأدوات ← حدود السعة».',
          m.metric || ' is ' || trim(to_char(m.val, 'FM999999999990.9')) || ' (limit '
            || trim(to_char(CASE WHEN v_level='crit' THEN m.crit ELSE m.warn END, 'FM999999999990.9')) || ').',
          'system',
          jsonb_build_object('audience','admin','event','capacity','metric', m.metric,
                             'level', v_level, 'value', m.val),
          now()
        FROM public.users u
        WHERE u.user_type = 'admin' AND u.deleted_at IS NULL;

        -- v15.80 ⟵ ساقٌ ثانية، **إضافيّةٌ** وداخلَ نفس التهدئة أعلاه.
        -- والنصُّ ثنائيُّ اللغة، وبصمةُ الكتم لكلّ مقياسٍ على حِدة فلا يكتم
        -- مقياسٌ غيرَه.
        BEGIN
          PERFORM public.taki_alert_dispatch(
            (CASE WHEN v_level='crit' THEN '🔴 بلغت الطاقة القصوى: ' ELSE '🟠 اقتربت الطاقة القصوى: ' END)
              || m.label || ' · '
              || (CASE WHEN v_level='crit' THEN 'Capacity reached: ' ELSE 'Capacity near: ' END) || m.metric,
            m.label || ' الآن ' || trim(to_char(m.val, 'FM999999999990.9')) || m.unit
              || ' والحدُّ ' || trim(to_char(CASE WHEN v_level='crit' THEN m.crit ELSE m.warn END, 'FM999999999990.9')) || m.unit
              || '. تُضبط الحدودُ من «الأدوات ← حدود السعة».' || E'\n'
              || m.metric || ' is ' || trim(to_char(m.val, 'FM999999999990.9')) || ' (limit '
              || trim(to_char(CASE WHEN v_level='crit' THEN m.crit ELSE m.warn END, 'FM999999999990.9')) || ').',
            v_level, 'capacity:' || m.metric);
        EXCEPTION WHEN OTHERS THEN
          NULL;
        END;

        v_raised := v_raised + 1;
      END;
    ELSE
      -- نزل تحت العتبة ⇒ يُطوى بلا ضجيج، فيُنذر من جديدٍ إن عاد.
      UPDATE public.capacity_alerts SET cleared_at = now()
       WHERE metric = m.metric AND cleared_at IS NULL;
    END IF;
  END LOOP;
  RETURN v_raised;
END $function$
;


-- ═══ FUNCTION taki_capacity_report() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_capacity_report()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_lim jsonb;
  v_conn_used int; v_conn_max int;
  v_db_mb numeric; v_store_mb numeric; v_mail int; v_cronfail int; v_users bigint;
BEGIN
  SELECT COALESCE(value,'{}'::jsonb) INTO v_lim FROM public.platform_settings WHERE key='capacity_limits';
  SELECT count(*) INTO v_conn_used FROM pg_stat_activity;
  v_conn_max := current_setting('max_connections')::int;
  v_db_mb := round(pg_database_size(current_database()) / 1048576.0, 1);
  SELECT round(COALESCE(sum((metadata->>'size')::bigint),0) / 1048576.0, 1) INTO v_store_mb
    FROM storage.objects;
  SELECT count(*) INTO v_mail FROM public.email_outbox
   WHERE created_at > now() - interval '24 hours' AND status <> 'failed';
  SELECT count(*) INTO v_cronfail FROM cron.job_run_details
   WHERE status <> 'succeeded' AND end_time > now() - interval '24 hours';
  SELECT count(*) INTO v_users FROM public.users WHERE deleted_at IS NULL;

  RETURN jsonb_build_object(
    'limits', v_lim,
    'db_connections', jsonb_build_object('used', v_conn_used, 'max', v_conn_max,
                        'pct', round(100.0 * v_conn_used / GREATEST(v_conn_max,1), 1)),
    'db_size_mb',   v_db_mb,
    'storage_mb',   v_store_mb,
    'email_24h',    v_mail,
    'cron_fail_24h', v_cronfail,
    'users',        v_users,
    'at', now());
END $function$
;


-- ═══ FUNCTION taki_category_label_ar(p_id text) INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_category_label_ar(p_id text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
    SELECT CASE p_id
        WHEN 'Fashion_Women' THEN '👗 فساتين ونساء'
        WHEN 'Fashion_Men'   THEN '👔 ملابس رجالية'
        WHEN 'Kids_Infants'  THEN '👶 رضع وملابس حمل'
        WHEN 'Kids_Girls'    THEN '👧 ملابس أطفال'
        WHEN 'Electronics'   THEN '📱 إلكترونيات'
        WHEN 'Food'          THEN '🍔 مطاعم'
        WHEN 'Beauty'        THEN '💄 عطور وتجميل'
        WHEN 'MensSalon'     THEN '💈 صالون رجالي'
        WHEN 'WomensSalon'   THEN '💇‍♀️ صالون نسائي'
        WHEN 'Sports'        THEN '⚽ رياضة'
        WHEN 'Supermarket'   THEN '🛒 سوبرماركت'
        WHEN 'Butcher'       THEN '🥩 ملحمة'
        WHEN 'Sanitary'      THEN '🚿 أدوات صحية'
        WHEN 'Cafe'          THEN '☕ مقاهي'
        WHEN 'Home'          THEN '🏠 منزل وديكور'
        WHEN 'Hotels'        THEN '🏨 فنادق'
        WHEN 'CarRentals'    THEN '🚗 تأجير سيارات'
        WHEN 'Laundry'       THEN '🧺 مغسلة ملابس'
        WHEN 'MensTailor'    THEN '🧵 خياطة رجالية'
        WHEN 'WomensTailor'  THEN '🪡 مشغل نسائي'
        WHEN 'CarWash'       THEN '🧽 مغسلة سيارات'
        WHEN 'CarWorkshop'   THEN '🔧 ورش سيارات'
        WHEN 'Amusements'    THEN '🎡 ملاهي ألعاب'
        WHEN 'Gym'           THEN '🏋️ نادي رياضي'
        WHEN 'Library'       THEN '📚 مكتبة'
        WHEN 'Nursery'       THEN '🌱 مشاتل زراعية'
        WHEN 'Pharmacy'      THEN '💊 صيدلية'
        WHEN 'Clinics'       THEN '🩺 عيادات'
        WHEN 'Online'        THEN '🌐 أونلاين'
        WHEN 'Other'         THEN '✨ أخرى'
        ELSE COALESCE(p_id, '')
    END;
$function$
;


