-- ═══ FUNCTION taki_chat_limits() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_chat_limits()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'per_booking', GREATEST(0, LEAST(1000, COALESCE((
        SELECT floor((value->>'per_booking')::numeric)::int FROM public.platform_settings
         WHERE key='chat_limits' AND jsonb_typeof(value->'per_booking')='number'), 0))),
    'per_hour',    GREATEST(1, LEAST(10000, COALESCE((
        SELECT floor((value->>'per_hour')::numeric)::int FROM public.platform_settings
         WHERE key='chat_limits' AND jsonb_typeof(value->'per_hour')='number'), 120))),
    'bot_page',    GREATEST(5, LEAST(100, COALESCE((
        SELECT floor((value->>'bot_page')::numeric)::int FROM public.platform_settings
         WHERE key='chat_limits' AND jsonb_typeof(value->'bot_page')='number'), 30))),
    -- v15.80 — رسائلُ طرفٍ محجوبٍ على طلبٍ جارٍ (مدفوعٍ أو توصيل)، تُحسب من
    -- لحظة الحجب. صفرٌ = حجبٌ قاطعٌ حتى على الطلب الجاري (قرارُ تشغيلٍ متاح).
    'blocked_inflight', GREATEST(0, LEAST(50, COALESCE((
        SELECT floor((value->>'blocked_inflight')::numeric)::int FROM public.platform_settings
         WHERE key='chat_limits' AND jsonb_typeof(value->'blocked_inflight')='number'), 3)))
  );
$function$
;


-- ═══ FUNCTION taki_chat_member(p_object_name text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_chat_member(p_object_name text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid text := auth.uid()::text;
  v_bc  text;
BEGIN
  IF v_uid IS NULL OR p_object_name IS NULL THEN RETURN false; END IF;
  v_bc := split_part(p_object_name, '/', 1);
  IF v_bc = '' OR v_bc = p_object_name THEN RETURN false; END IF;   -- لا مجلّد ⇒ مرفوض
  RETURN EXISTS (
    SELECT 1 FROM public.bookings b
    WHERE b.barcode = v_bc AND (b.user_id = v_uid OR b.store_id = v_uid)
  );
END $function$
;


-- ═══ FUNCTION taki_claim_booking_refund(p_barcode text, p_reason text, p_restock boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_claim_booking_refund(p_barcode text, p_reason text DEFAULT NULL::text, p_restock boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_me     text := (SELECT auth.uid()::text);
  v_system boolean := public.taki_is_system_caller();
  v_b      public.bookings%ROWTYPE;
  v_amt    numeric;
  v_actor  text;
BEGIN
  IF p_barcode IS NULL OR btrim(p_barcode) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BARCODE_REQUIRED');
  END IF;
  -- 🔴 `current_user` هنا هو **مالكُ الدالّة** لا المنادي (درس v14.96: أربعة
  --    حرّاس كانت عاطلةً تماماً بسببه). التمييزُ الوحيد الصحيح للنظام هو
  --    `taki_is_system_caller()`.
  IF v_me IS NULL AND NOT v_system THEN
    RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED');
  END IF;

  SELECT * INTO v_b FROM public.bookings
   WHERE barcode = upper(btrim(p_barcode))
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;

  -- الصلاحية: صاحبُ المتجر، أو النظام (دالّة الحافة تنادي بـservice_role حين
  -- تُتمّ مساراً بدأه التاجر)، أو أدمنٌ يملك تبويب المدفوعات صراحةً.
  -- 🪤 ولا تُستعمل `is_admin()`: تُرجع TRUE لأيّ أدمن عند النداء المباشر (v14.38).
  IF v_system THEN
    v_actor := 'system';
  ELSIF v_me = v_b.store_id THEN
    v_actor := 'merchant';
  ELSIF public.taki_admin_perm('tab_launch') THEN
    v_actor := 'admin';
  ELSE
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_MERCHANT');
  END IF;

  IF NOT COALESCE((SELECT sp.instant_refund FROM public.store_profiles sp WHERE sp.store_id = v_b.store_id), true) AND NOT v_system THEN
    -- v15.01 — التاجر أطفأ الردّ الفوريّ من لوحته. خيارُه، والمنصّة
    --          لا تتدخّل. (ويبقى المسارُ اليدويّ `booking_refunds` قائماً،
    --          وتبقى الإدارةُ قادرةً على الفكّ عند الحاجة — `v_system`.)
    RETURN jsonb_build_object('ok', false, 'error', 'MERCHANT_REFUND_OFF');
  END IF;
  IF v_b.paid_at IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_PAID');
  END IF;
  IF v_b.refund_state = 'refunded' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_REFUNDED',
                              'refunded_at', v_b.refunded_at, 'ref', v_b.refund_ref);
  END IF;
  IF v_b.refund_state = 'claiming' THEN
    -- 🔴 النصّ محلُّ عقدٍ: تُفحص هذه القيمةُ حرفياً في القسم ٧ وفي دالّة الحافة.
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_CLAIMING',
                              'claimed_at', v_b.refund_claimed_at);
  END IF;

  -- 🔴 وهذا الفحصُ يسدّ ثقباً **بين مسارين**، لا داخل مسارٍ واحد: مسارُ v14.18
  --    اليدويّ (`resolve_booking_refund`) يختم «رُدّ» في `booking_refunds` ولا
  --    يمسّ `refund_state` — فتاجرٌ سجّل ردّه يدوياً أمسِ يجد اليوم زرَّ الردّ
  --    الفوريّ مفتوحاً، فيُخرج المبلغ **مرّتين** من حسابه ويُصدر إشعاراً دائناً
  --    ثانياً. حالتان في جدولين لا تحرس إحداهما الأخرى ما لم تُسأل صراحةً.
  -- 🪤 وترتيبُ القفل هنا (الحجز ثمّ الاسترداد) هو نفسه في
  --    `resolve_booking_refund` — عكسُه يصنع جمود قفلٍ بين المسارين.
  PERFORM 1 FROM public.booking_refunds WHERE barcode = v_b.barcode FOR UPDATE;
  IF EXISTS (SELECT 1 FROM public.booking_refunds
              WHERE barcode = v_b.barcode AND status = 'refunded') THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ALREADY_REFUNDED',
                              'source', 'manual');
  END IF;
  -- يمرّ من هنا: NULL (لم يُطلب قطّ) و 'failed' (رفضَه المزوّد ⇒ إعادةُ محاولة).
  -- ولا يُطلَق سراحُ 'claiming' بمرور الوقت أبداً: نداءٌ ظنّناه ميتاً قد يكون
  -- نجح عند المزوّد، وإطلاقُه بالتخمين = ردٌّ مزدوج من حساب التاجر.

  v_amt := round(COALESCE(NULLIF(v_b.paid_amount, 0), v_b.total_amount, 0), 2);
  IF NOT (v_amt > 0) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'ZERO_AMOUNT');
  END IF;
  IF v_b.payment_provider IS NULL OR btrim(COALESCE(v_b.payment_ref, '')) = '' THEN
    -- بلا مرجع المزوّد لا يوجد ما يُردّ عليه. يُقال صراحةً بدل نداءٍ يفشل عنده.
    RETURN jsonb_build_object('ok', false, 'error', 'NO_PAYMENT_REF');
  END IF;

  UPDATE public.bookings
     SET refund_state      = 'claiming',
         refund_claimed_at = now(),
         refund_amount     = v_amt,
         refund_reason     = NULLIF(left(btrim(COALESCE(p_reason, '')), 600), ''),
         refund_by         = v_actor,
         refund_ref        = NULL,         -- محاولةٌ جديدة ⇒ مرجعٌ جديد
         -- v15.09 — جوابُ التاجر لهذا الردّ، يُحفظ لحظةَ الضغط ليصمد
         --          عبر رحلة البوّابة وفكِّ الإدارة لردٍّ عالق بعد ساعة.
         refund_restock    = p_restock
   WHERE barcode = v_b.barcode;

  RETURN jsonb_build_object(
    'ok', true, 'barcode', v_b.barcode, 'amount', v_amt,
    'provider', v_b.payment_provider, 'ref', v_b.payment_ref, 'by', v_actor);
END
$function$
;


-- ═══ FUNCTION taki_complaint_party(p_name text) DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_complaint_party(p_name text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT split_part(p_name, '/', 1) = auth.uid()::text
      OR public.taki_admin_perm('tab_reports');
$function$
;


-- ═══ FUNCTION taki_cron_health() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_cron_health()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
WITH alive AS (
  -- قيمةٌ محفوظة؛ وإن غاب الصفُّ (قاعدةٌ لم تُهيَّأ) فأقدمُ تشغيلٍ معروف.
  SELECT COALESCE((SELECT u.alive_since FROM public.taki_cron_uptime u WHERE u.id = 1),
                  (SELECT min(d.start_time) FROM cron.job_run_details d),
                  now()) AS alive_since
), j AS (
  SELECT c.jobid, c.jobname, c.schedule, c.active,
         CASE
           WHEN split_part(c.schedule,' ',1) = '*'      THEN 1
           WHEN split_part(c.schedule,' ',1) LIKE '*/%' THEN NULLIF(regexp_replace(split_part(c.schedule,' ',1),'\D','','g'),'')::int
           WHEN split_part(c.schedule,' ',2) = '*'      THEN 60
           WHEN split_part(c.schedule,' ',5) = '*'      THEN 1440
           ELSE 10080
         END AS every_min
  FROM cron.job c WHERE c.active
), last_run AS (
  -- 🪤 `DISTINCT ON` بدل `GROUP BY`: يقفز في الفهرس `(jobid, start_time DESC)`
  --    إلى أوّل صفٍّ لكلّ وظيفة، بدل تجميعِ الجدول كلِّه.
  SELECT DISTINCT ON (d.jobid) d.jobid, d.start_time AS last_run
    FROM cron.job_run_details d
   ORDER BY d.jobid, d.start_time DESC
), fails AS (
  -- ومرشّحٌ زمنيٌّ صريح يخدمه فهرس `start_time` — بدل مسحِ كلِّ التاريخ.
  SELECT d.jobid, count(*) AS failed_24h
    FROM cron.job_run_details d
   WHERE d.status = 'failed' AND d.start_time > now() - interval '24 hours'
   GROUP BY d.jobid
), x AS (
  SELECT j.jobname, j.every_min, lr.last_run, COALESCE(f.failed_24h,0) AS failed_24h,
         public._taki_job_stalled(lr.last_run, j.every_min, a.alive_since, s.first_seen_at) AS stalled,
         (lr.last_run IS NULL) AS never_ran_raw
  FROM j
  LEFT JOIN last_run lr ON lr.jobid = j.jobid
  LEFT JOIN fails f     ON f.jobid  = j.jobid
  LEFT JOIN public.taki_cron_seen s ON s.jobname = j.jobname
  CROSS JOIN alive a
)
SELECT jsonb_build_object(
  'jobs',         (SELECT count(*) FROM x),
  'alive_since',  (SELECT alive_since FROM alive),
  'failed_24h',   (SELECT COALESCE(sum(failed_24h),0) FROM x),
  'failed_names', (SELECT COALESCE(jsonb_agg(jobname), '[]'::jsonb) FROM x WHERE failed_24h > 0),
  -- 🔴 «متوقّفة» تعني: الخادمُ كان حيّاً والوظيفةُ لم تعمل.
  -- 🪤 و«لم تعمل قطّ» تُفصل عنها: الحالتان مختلفتان في المعنى وفي العلاج.
  'stalled',      (SELECT count(*) FROM x WHERE stalled AND NOT never_ran_raw),
  'stalled_names',(SELECT COALESCE(jsonb_agg(jobname), '[]'::jsonb) FROM x WHERE stalled AND NOT never_ran_raw),
  'never_ran',    (SELECT COALESCE(jsonb_agg(jobname), '[]'::jsonb) FROM x WHERE never_ran_raw),
  'never_ran_overdue',
                  (SELECT count(*) FROM x WHERE never_ran_raw AND stalled),
  'never_ran_overdue_names',
                  (SELECT COALESCE(jsonb_agg(jobname), '[]'::jsonb) FROM x WHERE never_ran_raw AND stalled)
);
$function$
;


-- ═══ FUNCTION taki_cron_seen_sync() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_cron_seen_sync()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int; v_boundary timestamptz;
BEGIN
  INSERT INTO public.taki_cron_seen (jobname)
  SELECT c.jobname FROM cron.job c ON CONFLICT (jobname) DO NOTHING;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  -- 🪤 وتُحذف أسماءُ وظائفَ لم تعد موجودة، وإلّا نما الجدولُ بلا حدّ
  DELETE FROM public.taki_cron_seen s
   WHERE NOT EXISTS (SELECT 1 FROM cron.job c WHERE c.jobname = s.jobname);

  -- 🔴 الاحتفاظُ ٩٠ يوماً — **أوسعُ** من نافذة كشف التوقّف، وإلّا حُذف الدليل
  --    الذي يقوم عليه الكشف (درسٌ مدفوعُ الثمن في v15.25 وv15.56).
  DELETE FROM cron.job_run_details WHERE start_time < now() - interval '90 days';

  -- ── تحديثُ «منذ متى والخادمُ حيّ» بفحصِ ساعتين لا ستّين يوماً ────────────
  -- 🪤 النافذةُ ساعتان **لأن** المزامنةَ ساعية: أيُّ عودةٍ من انقطاعٍ يقع
  --    حدُّها داخل نافذة الفحص التالي يقيناً. وفي الجدولة وظيفةٌ كلَّ دقيقة،
  --    فالفجوةُ التي تتجاوز ساعةً دليلُ توقّفٍ لا ظنّ.
  SELECT g.start_time INTO v_boundary
    FROM (
      SELECT d.start_time,
             d.start_time - lag(d.start_time) OVER (ORDER BY d.start_time) AS gap
        FROM cron.job_run_details d
       WHERE d.start_time > now() - interval '2 hours'
    ) g
   WHERE g.gap > interval '1 hour'
   ORDER BY g.start_time DESC
   LIMIT 1;

  UPDATE public.taki_cron_uptime
     SET alive_since  = COALESCE(v_boundary, alive_since),
         last_sync_at = now()
   WHERE id = 1;

  BEGIN
    EXECUTE 'ANALYZE cron.job_run_details';
  EXCEPTION WHEN OTHERS THEN NULL;   -- إحصاءٌ فاشل لا يُسقط مزامنةَ الأسماء
  END;
  RETURN v_n;
END $function$
;


-- ═══ FUNCTION taki_deliver_warnings() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_deliver_warnings()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE r RECORD;
BEGIN
  FOR r IN SELECT * FROM pending_warnings WHERE sent_at IS NULL AND deliver_at <= now() ORDER BY deliver_at LIMIT 50
  LOOP
    INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (r.user_id, '⚠️ تنبيه من إدارة تاكي', '⚠️ Warning from TAKI', r.message, r.message, 'system',
            jsonb_build_object('audience', 'user', 'admin_warning', TRUE));
    UPDATE pending_warnings SET sent_at = now() WHERE id = r.id;
  END LOOP;
END $function$
;


-- ═══ FUNCTION taki_delivery_dispatched(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_delivery_dispatched(p_barcode text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT EXISTS (
    SELECT 1 FROM public.delivery_tracks t
     WHERE t.barcode = upper(btrim(p_barcode))
       AND (t.dispatched_at IS NOT NULL
            OR t.started_at IS NOT NULL
            OR t.status IN ('on_the_way','arrived','delivered')));
$function$
;


-- ═══ FUNCTION taki_delivery_globally_on() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_delivery_globally_on()
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(
    (SELECT (value #>> '{}') FROM public.platform_settings WHERE key = 'delivery_enabled'),
    'true') <> 'false';
$function$
;


-- ═══ FUNCTION taki_delivery_hold_stopped(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_delivery_hold_stopped(p_barcode text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  -- «توقّف العدّاد» أوسعُ من «انطلق»: التجهيزُ وحده يوقفه (v14.10).
  SELECT EXISTS (
    SELECT 1 FROM public.delivery_tracks t
     WHERE t.barcode = upper(btrim(p_barcode))
       AND (t.dispatched_at IS NOT NULL
            OR t.started_at IS NOT NULL
            OR t.status IN ('preparing','on_the_way','arrived','delivered')));
$function$
;


-- ═══ FUNCTION taki_dispatch_coming_soon_window() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_dispatch_coming_soon_window()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    deal_rec        public.deals;
    deal_region_id  TEXT;
    deal_city_id    TEXT;
    deal_lat        DOUBLE PRECISION;
    deal_lng        DOUBLE PRECISION;
    nearest_row     public.sa_cities_geo;
    rec             RECORD;
    now_ms          BIGINT;
    window_cutoff   BIGINT;
    processed       INTEGER := 0;
    blk_out         TEXT[];   -- v15.80
    blk_in          TEXT[];   -- v15.80
BEGIN
    now_ms        := (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT;
    window_cutoff := now_ms + (7 * 24 * 60 * 60 * 1000);

    -- Cap at 50 per tick. With a 5-minute interval that's 600 deals/hour —
    -- well above any realistic burst. Cap exists so a sudden spike (e.g.
    -- a backfill migration that resets coming_soon_notified_at on
    -- hundreds of rows) can't fan out into thousands of notifications in
    -- a single tick and choke the trigger budget.
    FOR deal_rec IN
        SELECT * FROM public.deals
        WHERE status = 'active'
          AND starts_at IS NOT NULL
          AND coming_soon_notified_at IS NULL
          AND starts_at > now_ms                  -- still in the future
          AND starts_at <= window_cutoff          -- inside the 7-day window
        ORDER BY starts_at ASC
        LIMIT 50
    LOOP
        deal_region_id := deal_rec.region;
        deal_city_id   := deal_rec.city;
        deal_lat       := deal_rec.map_lat;
        deal_lng       := deal_rec.map_lng;

        IF deal_region_id IS NULL OR deal_city_id IS NULL THEN
            SELECT l.city_id, c.region_id,
                   COALESCE(deal_lat, l.lat),
                   COALESCE(deal_lng, l.lng)
            INTO deal_city_id, deal_region_id, deal_lat, deal_lng
            FROM public.locations l
            LEFT JOIN public.cities c ON c.id = l.city_id
            WHERE l.id = deal_rec.location_id;
        END IF;

        IF (deal_region_id IS NULL OR deal_city_id IS NULL)
           AND deal_lat IS NOT NULL AND deal_lng IS NOT NULL
        THEN
            SELECT * INTO nearest_row FROM public.find_nearest_sa_city(deal_lat, deal_lng);
            IF nearest_row.city_id IS NOT NULL THEN
                deal_region_id := COALESCE(deal_region_id, nearest_row.region_id);
                deal_city_id   := COALESCE(deal_city_id,   nearest_row.city_id);
            END IF;
        END IF;

        -- v15.80 — نفسُ شرط مشغّلِ النشر: الحجبُ في الاتجاهين، ومسحٌ واحد.
        blk_out := ARRAY(SELECT ub.blocked_id FROM public.user_blocks ub WHERE ub.blocker_id = deal_rec.store_id);
        blk_in  := ARRAY(SELECT ub.blocker_id FROM public.user_blocks ub WHERE ub.blocked_id = deal_rec.store_id);

        FOR rec IN
            SELECT id, smart_alerts, followed_merchants
            FROM public.users
            WHERE id <> deal_rec.store_id
              AND deleted_at IS NULL
              -- v13.31 — نفس إصلاح ترغر الإضافة: المعنيّون فقط
              AND ( COALESCE(jsonb_array_length(smart_alerts), 0) > 0
                 OR deal_rec.store_id = ANY(COALESCE(followed_merchants, ARRAY[]::text[])) )
              AND NOT (id = ANY(blk_out))
              AND NOT (id = ANY(blk_in))
        LOOP
            PERFORM public.taki_dispatch_smart_alert(
                rec.id,
                rec.followed_merchants,
                rec.smart_alerts,
                deal_rec,
                deal_region_id, deal_city_id,
                deal_lat, deal_lng,
                TRUE  -- dedupe: skip if a notification for this (user, deal) already exists
            );
        END LOOP;

        UPDATE public.deals
        SET coming_soon_notified_at = now_ms
        WHERE id = deal_rec.id;

        processed := processed + 1;
    END LOOP;

    RETURN processed;
END;
$function$
;


-- ═══ FUNCTION taki_dispatch_smart_alert(p_user_id text, p_followed_merchants text[], p_smart_alerts jsonb, p_deal deals, p_deal_region text, p_deal_city text, p_deal_lat double precision, p_deal_lng double precision, p_skip_existing boolean) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_dispatch_smart_alert(p_user_id text, p_followed_merchants text[], p_smart_alerts jsonb, p_deal deals, p_deal_region text, p_deal_city text, p_deal_lat double precision, p_deal_lng double precision, p_skip_existing boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    is_follower         BOOLEAN;
    rule_matched        BOOLEAN := FALSE;
    deal_text           TEXT;
    rule                JSONB;
    rule_idx            INT;
    ok                  BOOLEAN;
    has_any_condition   BOOLEAN;
    this_range          DOUBLE PRECISION;
    this_kw             TEXT;
    kw_ok               BOOLEAN;
    i                   INT;
    kw                  TEXT;
    has_range           BOOLEAN := FALSE;
    range_km_min        DOUBLE PRECISION;
    has_mall            BOOLEAN := FALSE;
    has_city            BOOLEAN := FALSE;
    has_category        BOOLEAN := FALSE;
    cat_first           TEXT;
    has_keyword         BOOLEAN := FALSE;
    kw_first            TEXT;
    has_region          BOOLEAN := FALSE;
    chips_ar            TEXT[] := ARRAY[]::TEXT[];
    chips_en            TEXT[] := ARRAY[]::TEXT[];
    title_ar            TEXT;
    title_en            TEXT;
    body_ar             TEXT;
    body_en             TEXT;
    nkind               TEXT;
    city_name           TEXT;
    mall_name           TEXT;
    chip_count          INT;
    shown_ar            TEXT[];
    shown_en            TEXT[];
    more_n              INT;
    line1_ar            TEXT;
    line1_en            TEXT;
    line2_ar            TEXT;
    line2_en            TEXT;
    line3_ar            TEXT;
    line3_en            TEXT;
    range_num_text      TEXT;
    range_chip_ar       TEXT;
    range_chip_en       TEXT;
    range_title_ar      TEXT;
    range_title_en      TEXT;
    is_coming_soon      BOOLEAN := FALSE;
    now_ms              BIGINT;
    starts_in_days      INT;
    starts_eta_ar       TEXT;
    starts_eta_en       TEXT;
BEGIN
    is_follower := p_followed_merchants IS NOT NULL
                   AND p_deal.store_id = ANY(p_followed_merchants);

    now_ms := (EXTRACT(EPOCH FROM NOW()) * 1000)::BIGINT;
    IF p_deal.starts_at IS NOT NULL AND p_deal.starts_at > now_ms THEN
        is_coming_soon := TRUE;
        starts_in_days := GREATEST(1, CEIL((p_deal.starts_at - now_ms)::numeric / 86400000.0)::INT);
        IF starts_in_days = 1 THEN
            starts_eta_ar := 'خلال يوم';
            starts_eta_en := 'in 1 day';
        ELSIF starts_in_days = 2 THEN
            starts_eta_ar := 'بعد يومين';
            starts_eta_en := 'in 2 days';
        ELSE
            starts_eta_ar := 'خلال ' || starts_in_days::TEXT || ' أيام';
            starts_eta_en := 'in ' || starts_in_days::TEXT || ' days';
        END IF;
    END IF;

    deal_text := COALESCE(public.taki_norm(
        COALESCE(p_deal.item_name, '')   || ' ' ||
        COALESCE(p_deal.shop_name, '')   || ' ' ||
        COALESCE(p_deal.category, '')    || ' ' ||
        COALESCE(p_deal.description, '')
    ), '');

    IF p_smart_alerts IS NOT NULL
       AND jsonb_typeof(p_smart_alerts) = 'array'
       AND jsonb_array_length(p_smart_alerts) > 0
    THEN
        FOR rule_idx IN 0 .. (jsonb_array_length(p_smart_alerts) - 1) LOOP
            rule              := p_smart_alerts -> rule_idx;
            ok                := TRUE;
            this_range        := NULL;
            this_kw           := NULL;
            has_any_condition := FALSE;

            IF rule ? 'regions' AND jsonb_array_length(rule->'regions') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal_region IS NULL OR NOT (rule->'regions' ? p_deal_region) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'cities' AND jsonb_array_length(rule->'cities') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal_city IS NULL OR NOT (rule->'cities' ? p_deal_city) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'malls' AND jsonb_array_length(rule->'malls') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal.location_id IS NULL OR NOT (rule->'malls' ? p_deal.location_id) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'categories' AND jsonb_array_length(rule->'categories') > 0 THEN
                has_any_condition := TRUE;
                IF p_deal.category IS NULL OR NOT (rule->'categories' ? p_deal.category) THEN
                    ok := FALSE;
                END IF;
            END IF;
            IF ok AND rule ? 'keywords' AND jsonb_array_length(rule->'keywords') > 0 THEN
                has_any_condition := TRUE;
                kw_ok := FALSE;
                FOR i IN 0 .. (jsonb_array_length(rule->'keywords') - 1) LOOP
                    kw := public.taki_norm(rule->'keywords'->>i);
                    IF kw IS NOT NULL AND deal_text LIKE '%' || kw || '%' THEN
                        kw_ok := TRUE;
                        this_kw := rule->'keywords'->>i;
                        EXIT;
                    END IF;
                END LOOP;
                IF NOT kw_ok THEN ok := FALSE; END IF;
            END IF;
            IF ok
               AND rule ? 'coords'
               AND rule->'coords' ? 'lat'
               AND rule->'coords' ? 'lng'
               AND rule ? 'radiusKm'
            THEN
                has_any_condition := TRUE;
                this_range := public.taki_haversine_km(
                    (rule->'coords'->>'lat')::DOUBLE PRECISION,
                    (rule->'coords'->>'lng')::DOUBLE PRECISION,
                    p_deal_lat, p_deal_lng
                );
                IF this_range IS NULL
                   OR this_range > (rule->>'radiusKm')::DOUBLE PRECISION
                THEN
                    ok := FALSE;
                END IF;
            END IF;

            IF NOT has_any_condition THEN
                ok := FALSE;
            END IF;

            IF ok THEN
                rule_matched := TRUE;
                IF rule ? 'regions' AND jsonb_array_length(rule->'regions') > 0 THEN
                    has_region := TRUE;
                END IF;
                IF rule ? 'cities' AND jsonb_array_length(rule->'cities') > 0 THEN
                    has_city := TRUE;
                END IF;
                IF rule ? 'malls' AND jsonb_array_length(rule->'malls') > 0 THEN
                    has_mall := TRUE;
                END IF;
                IF rule ? 'categories' AND jsonb_array_length(rule->'categories') > 0 THEN
                    has_category := TRUE;
                    IF cat_first IS NULL THEN cat_first := p_deal.category; END IF;
                END IF;
                IF rule ? 'keywords' AND jsonb_array_length(rule->'keywords') > 0 THEN
                    has_keyword := TRUE;
                    IF kw_first IS NULL THEN kw_first := this_kw; END IF;
                END IF;
                IF rule ? 'coords' AND rule ? 'radiusKm' THEN
                    has_range := TRUE;
                    IF this_range IS NOT NULL
                       AND (range_km_min IS NULL OR this_range < range_km_min)
                    THEN
                        range_km_min := this_range;
                    END IF;
                END IF;
            END IF;
        END LOOP;
    END IF;

    IF NOT is_follower AND NOT rule_matched THEN
        RETURN FALSE;
    END IF;

    IF p_skip_existing THEN
        IF EXISTS (
            SELECT 1 FROM public.notifications
            WHERE user_id = p_user_id
              AND (meta_data->>'dealId') = p_deal.id::TEXT
              AND type IN ('deal','marketing')
        ) THEN
            RETURN FALSE;
        END IF;
    END IF;

    IF has_city AND p_deal_city IS NOT NULL THEN
        SELECT name INTO city_name FROM public.cities WHERE id = p_deal_city LIMIT 1;
    END IF;
    IF has_mall AND p_deal.location_id IS NOT NULL THEN
        SELECT name INTO mall_name FROM public.locations WHERE id = p_deal.location_id LIMIT 1;
    END IF;

    IF has_range AND range_km_min IS NOT NULL THEN
        IF range_km_min < 0.1 THEN
            range_chip_ar  := '📍 بجانبك تماماً';
            range_chip_en  := '📍 Right next to you';
            range_title_ar := '📍 عرض بجانبك تماماً';
            range_title_en := '📍 A deal right next to you';
        ELSIF range_km_min < 1 THEN
            range_chip_ar  := '📍 أقل من 1 كم منك';
            range_chip_en  := '📍 Under 1 km away';
            range_title_ar := '📍 عرض على بُعد أقل من 1 كم منك';
            range_title_en := '📍 Deal under 1 km from you';
        ELSE
            range_num_text := TRIM(TRAILING '.' FROM
                                   TRIM(TRAILING '0' FROM ROUND(range_km_min::numeric, 1)::TEXT));
            IF range_num_text = '' OR range_num_text IS NULL THEN
                range_num_text := '1';
            END IF;
            range_chip_ar  := '📍 ' || range_num_text || ' كم منك';
            range_chip_en  := '📍 ' || range_num_text || ' km away';
            range_title_ar := '📍 عرض على بُعد ' || range_num_text || ' كم منك';
            range_title_en := '📍 Deal ' || range_num_text || ' km from you';
        END IF;
    END IF;

    IF is_follower THEN
        chips_ar := chips_ar || '🔥 متجر تتابعه'::TEXT;
        chips_en := chips_en || '🔥 Followed store'::TEXT;
    END IF;
    IF has_range THEN
        chips_ar := chips_ar || range_chip_ar;
        chips_en := chips_en || range_chip_en;
    END IF;
    IF has_mall THEN
        chips_ar := chips_ar || ('🏬 ' || COALESCE(mall_name, 'مولك'))::TEXT;
        chips_en := chips_en || ('🏬 ' || COALESCE(mall_name, 'Your mall'))::TEXT;
    END IF;
    IF has_city THEN
        chips_ar := chips_ar || ('🌆 ' || COALESCE(city_name, 'مدينتك'))::TEXT;
        chips_en := chips_en || ('🌆 ' || COALESCE(city_name, 'Your city'))::TEXT;
    END IF;
    IF has_category THEN
        chips_ar := chips_ar || public.taki_category_label_ar(cat_first);
        chips_en := chips_en || public.taki_category_label_en(cat_first);
    END IF;
    IF has_keyword THEN
        chips_ar := chips_ar || ('🔍 «' || kw_first || '»')::TEXT;
        chips_en := chips_en || ('🔍 "' || kw_first || '"')::TEXT;
    END IF;
    IF has_region THEN
        chips_ar := chips_ar || '🌍 منطقتك'::TEXT;
        chips_en := chips_en || '🌍 Your region'::TEXT;
    END IF;
    IF is_coming_soon THEN
        chips_ar := chips_ar || ('⏳ يبدأ ' || starts_eta_ar)::TEXT;
        chips_en := chips_en || ('⏳ Starts ' || starts_eta_en)::TEXT;
    END IF;

    IF is_coming_soon THEN
        title_ar := '⏳ عرض قادم — ' || COALESCE(p_deal.shop_name, 'متجر') || ' يبدأ ' || starts_eta_ar;
        title_en := '⏳ Coming soon — ' || COALESCE(p_deal.shop_name, 'a store') || ' starts ' || starts_eta_en;
    ELSIF is_follower AND rule_matched THEN
        title_ar := '🔥 ' || COALESCE(p_deal.shop_name, 'متجر تتابعه') || ' نزّل عرضاً يطابق تنبيهك';
        title_en := '🔥 ' || COALESCE(p_deal.shop_name, 'A store you follow') || ' posted a matching deal';
    ELSIF is_follower THEN
        title_ar := '🔥 ' || COALESCE(p_deal.shop_name, 'متجرك المفضل') || ' نزّل عرضاً جديداً';
        title_en := '🔥 New deal from ' || COALESCE(p_deal.shop_name, 'your favorite store');
    ELSIF has_range THEN
        title_ar := range_title_ar;
        title_en := range_title_en;
    ELSIF has_mall THEN
        title_ar := '🏬 عرض جديد في ' || COALESCE(mall_name, 'مولك');
        title_en := '🏬 New deal at ' || COALESCE(mall_name, 'your mall');
    ELSIF has_city THEN
        title_ar := '🌆 عرض جديد في ' || COALESCE(city_name, 'مدينتك');
        title_en := '🌆 New deal in ' || COALESCE(city_name, 'your city');
    ELSIF has_keyword THEN
        title_ar := '🔍 عرض يطابق كلمتك «' || kw_first || '»';
        title_en := '🔍 Deal matching "' || kw_first || '"';
    ELSIF has_category THEN
        title_ar := '🎯 ' || public.taki_category_label_ar(cat_first) || ' — عرض جديد';
        title_en := '🎯 ' || public.taki_category_label_en(cat_first) || ' — new deal';
    ELSIF has_region THEN
        title_ar := '🌍 عرض جديد في منطقتك';
        title_en := '🌍 New deal in your region';
    ELSE
        title_ar := '🎯 يطابق تنبيهك الذكي';
        title_en := '🎯 Matches your smart alert';
    END IF;

    line1_ar := COALESCE(p_deal.item_name, 'عرض جديد')
                || '  —  خصم ' || COALESCE(p_deal.discount_percentage::TEXT, '؟') || '٪';
    line1_en := COALESCE(p_deal.item_name, 'New deal')
                || '  —  ' || COALESCE(p_deal.discount_percentage::TEXT, '?') || '% off';
    line2_ar := '🏪 ' || COALESCE(p_deal.shop_name, 'متجر');
    line2_en := '🏪 ' || COALESCE(p_deal.shop_name, 'Store');

    chip_count := COALESCE(array_length(chips_ar, 1), 0);
    IF chip_count <= 3 THEN
        shown_ar := chips_ar;
        shown_en := chips_en;
        more_n   := 0;
    ELSE
        shown_ar := chips_ar[1:3];
        shown_en := chips_en[1:3];
        more_n   := chip_count - 3;
    END IF;

    IF chip_count > 0 THEN
        line3_ar := array_to_string(shown_ar, '  •  ');
        line3_en := array_to_string(shown_en, '  •  ');
        IF more_n > 0 THEN
            line3_ar := line3_ar || '  •  +' || more_n::TEXT;
            line3_en := line3_en || '  •  +' || more_n::TEXT;
        END IF;
        body_ar := line1_ar || E'\n' || line2_ar || E'\n' || line3_ar;
        body_en := line1_en || E'\n' || line2_en || E'\n' || line3_en;
    ELSE
        body_ar := line1_ar || E'\n' || line2_ar;
        body_en := line1_en || E'\n' || line2_en;
    END IF;

    IF is_coming_soon THEN
        nkind := 'coming_soon';
    ELSIF is_follower THEN
        nkind := 'follow';
    ELSIF has_range THEN
        nkind := 'range';
    ELSIF has_mall THEN
        nkind := 'mall';
    ELSIF has_city THEN
        nkind := 'city';
    ELSIF has_keyword THEN
        nkind := 'keyword';
    ELSIF has_category THEN
        nkind := 'category';
    ELSIF has_region THEN
        nkind := 'region';
    ELSE
        nkind := 'other';
    END IF;

    INSERT INTO public.notifications
        (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES (
        p_user_id, title_ar, title_en, body_ar, body_en,
        CASE WHEN is_follower THEN 'deal' ELSE 'marketing' END,
        jsonb_build_object(
            'dealId',         p_deal.id::TEXT,
            'reasons_ar',     to_jsonb(chips_ar),
            'reasons_en',     to_jsonb(chips_en),
            'follower',       is_follower,
            'primary_kind',   nkind,
            'audience',       CASE WHEN is_follower THEN 'follower' ELSE 'alert' END,
            'coming_soon',    is_coming_soon,
            'starts_at',      p_deal.starts_at,
            'bot_message_ar', title_ar || E'\n\n' || body_ar,
            'bot_message_en', title_en || E'\n\n' || body_en
        ),
        NOW()
    );

    RETURN TRUE;
END;
$function$
;


-- ═══ FUNCTION taki_email_wrap(p_title text, p_body_html text) INVOKER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_email_wrap(p_title text, p_body_html text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
SELECT '<!DOCTYPE html><html dir="rtl" lang="ar"><head><meta charset="utf-8"></head>'
    || '<body style="margin:0;padding:0;background:#f4f7f6;font-family:-apple-system,''Segoe UI'',Tahoma,Arial,sans-serif;">'
    || '<div style="max-width:600px;margin:0 auto;padding:24px 16px;">'
    || '<div style="background:linear-gradient(135deg,#10b981,#0d9488);border-radius:16px 16px 0 0;padding:22px 24px;text-align:center;">'
    || '<div style="font-size:26px;font-weight:900;color:#ffffff;letter-spacing:1px;">TAKI — تاكي</div>'
    || '<div style="font-size:12px;color:#d1fae5;margin-top:4px;">منصة حجز التخفيضات في السعودية</div></div>'
    || '<div style="background:#ffffff;border:1px solid #e5e7eb;border-top:none;border-radius:0 0 16px 16px;padding:26px 24px;">'
    || '<h1 style="font-size:19px;margin:0 0 14px;color:#111827;text-align:right;">' || COALESCE(p_title,'') || '</h1>'
    || '<div style="font-size:14px;line-height:2;color:#374151;text-align:right;">' || COALESCE(p_body_html,'') || '</div>'
    || '<div style="margin-top:22px;text-align:center;">'
    || '<a href="https://www.takisa.net" style="display:inline-block;background:#10b981;color:#ffffff;text-decoration:none;font-weight:700;font-size:14px;padding:11px 28px;border-radius:12px;">فتح تاكي</a></div></div>'
    || '<div style="text-align:center;font-size:11px;color:#9ca3af;padding:14px 6px;">وصلتك هذه الرسالة لأنك مشترك في منصة تاكي. يمكنك التحكم بالإشعارات من صفحة حسابك.</div>'
    || '</div></body></html>';
$function$
;


-- ═══ FUNCTION taki_enforce_booking_ban() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_enforce_booking_ban()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_until timestamptz; v_susp boolean;
BEGIN
  SELECT booking_banned_until, COALESCE(is_suspended, false) INTO v_until, v_susp
    FROM users WHERE id = NEW.user_id;
  IF v_susp THEN
    RAISE EXCEPTION 'حسابك موقوف — تواصل مع إدارة تاكي';
  END IF;
  IF v_until IS NOT NULL AND v_until > now() THEN
    RAISE EXCEPTION 'تم تعليق الحجز على حسابك حتى % بسبب إلغاءات متكررة', to_char(v_until AT TIME ZONE 'Asia/Riyadh', 'YYYY-MM-DD HH24:MI');
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_enforce_booking_rules() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_enforce_booking_rules()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deal deals%ROWTYPE; v_cnt int; v_last timestamptz; v_wait int;
BEGIN
  SELECT * INTO v_deal FROM deals WHERE id = NEW.deal_id;
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- (a) units per single booking
  IF COALESCE(v_deal.max_per_booking, 0) > 0
     AND COALESCE(NEW.booked_quantity, 1) > v_deal.max_per_booking THEN
    RAISE EXCEPTION 'TAKI_MAX_QTY:%', v_deal.max_per_booking;
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- (b) bookings per buyer (active + completed count; cancelled/expired don't)
    IF COALESCE(v_deal.max_bookings_per_buyer, 0) > 0 THEN
      SELECT count(*) INTO v_cnt FROM bookings
       WHERE deal_id = NEW.deal_id AND user_id = NEW.user_id
         AND status IN ('pending','acknowledged','completed');
      IF v_cnt >= v_deal.max_bookings_per_buyer THEN
        RAISE EXCEPTION 'TAKI_REBOOK_LIMIT:%', v_deal.max_bookings_per_buyer;
      END IF;
    END IF;
    -- (c) cooldown after the buyer's last COMPLETED pickup
    IF COALESCE(v_deal.rebook_cooldown_minutes, 0) > 0 THEN
      SELECT max(completed_at) INTO v_last FROM bookings
       WHERE deal_id = NEW.deal_id AND user_id = NEW.user_id AND status = 'completed';
      IF v_last IS NOT NULL
         AND v_last + (v_deal.rebook_cooldown_minutes || ' minutes')::interval > now() THEN
        v_wait := CEIL(EXTRACT(EPOCH FROM (v_last + (v_deal.rebook_cooldown_minutes || ' minutes')::interval - now())) / 60)::int;
        RAISE EXCEPTION 'TAKI_REBOOK_WAIT:%', GREATEST(v_wait, 1);
      END IF;
    END IF;
  END IF;

  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_enforce_branch_display_cap() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_enforce_branch_display_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare v_cap integer; v_shown integer;
begin
  if coalesce(new.show_on_store_page, false) = false then return new; end if;
  if tg_op = 'UPDATE' and coalesce(old.show_on_store_page, false) = true then return new; end if;

  select coalesce(sp.max_branches, 1) into v_cap
    from public.store_profiles sp where sp.store_id = new.merchant_id;
  v_cap := coalesce(v_cap, 1);

  select count(*) into v_shown
    from public.store_branches b
   where b.merchant_id = new.merchant_id
     and b.show_on_store_page = true
     and b.id is distinct from new.id;

  if v_shown + 1 > v_cap then
    raise exception 'BRANCH_DISPLAY_CAP:%', v_cap
      using hint = 'باقتك تسمح بعرض ' || v_cap || ' موقع فقط على صفحتك. أخفِ موقعاً أو رقِّ باقتك.';
  end if;
  return new;
end $function$
;


-- ═══ FUNCTION taki_expire_delivery_tracks() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_expire_delivery_tracks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_wiped integer; v_deleted integer;
BEGIN
  -- (أ) بثٌّ توقّف ساعةً: يُغلق المسار ويُمحى الموقع.
  UPDATE public.delivery_tracks
     SET status = 'cancelled', lat = NULL, lng = NULL, accuracy_m = NULL,
         heading = NULL, speed_kmh = NULL, remaining_km = NULL, eta_min = NULL,
         ended_at = now(), updated_at = now()
   WHERE status IN ('on_the_way','arrived')
     AND updated_at < now() - interval '1 hour';
  GET DIAGNOSTICS v_wiped = ROW_COUNT;

  -- (ب) ثم يُحذف الصفّ بعد ساعة من إغلاق **الطلب** لا من إغلاق المسار.
  -- 🪤 v14.19 كانت تحذفه بعد ساعة من `ended_at` بلا شرطٍ على الطلب. والتاجر
  -- يضغط «تم التسليم» فيُغلق المسار **والطلب يبقى مفتوحاً** بانتظار تأكيد
  -- المشتري — فكان الحذف يُخفي زرّ «✅ استلمت طلبي»، ويُسقط الحمايةَ التي
  -- تمنع الإلغاء التلقائي لطلبٍ انطلق مندوبه، فيُلغى طلبٌ وصل صاحبه فعلاً.
  DELETE FROM public.delivery_tracks t
   WHERE COALESCE(t.ended_at, t.updated_at) < now() - interval '1 hour'
     AND t.status IN ('delivered','cancelled')
     AND EXISTS (SELECT 1 FROM public.bookings b
                  WHERE b.barcode = t.barcode
                    AND b.status IN ('completed','cancelled')
                    AND COALESCE(b.completed_at, b.created_at) < now() - interval '1 hour');
  GET DIAGNOSTICS v_deleted = ROW_COUNT;

  RETURN v_wiped + v_deleted;
END
$function$
;


-- ═══ FUNCTION taki_expire_verifications() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_expire_verifications()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  n int := 0;
  r record;
  v_msg text;
  v_left int;
  v_stage smallint;
BEGIN
  -- ① التنبيه: عتبتان، بالمدى لا بالمساواة، ومرّةً واحدةً لكلّ عتبة.
  --    🪤 `ORDER BY doc_expiry` ليس تجميلاً: لو حُدّ العددُ يوماً ما فالأقربُ
  --       انتهاءً أولى بالتنبيه.
  FOR r IN
    SELECT id, store_id, (doc_expiry - current_date)::int AS days_left, warn_stage
      FROM public.store_verifications
     WHERE status = 'approved'
       AND doc_expiry IS NOT NULL
       AND doc_expiry >= current_date          -- المنتهي يُعالَج في ②
       AND (doc_expiry - current_date) <= 30
       AND warn_stage < 2
     ORDER BY doc_expiry
  LOOP
    -- العتبةُ المستحقّة: ٧ تعلو ٣٠، ولا يُنبَّه بعتبةٍ سبق تجاوزُها.
    v_stage := CASE WHEN r.days_left <= 7 THEN 2 ELSE 1 END;
    CONTINUE WHEN v_stage <= r.warn_stage;

    v_left := GREATEST(r.days_left, 0);
    v_msg := '⚠️ ينتهي توثيق متجرك خلال ' || public.taki_ar_days(v_left)
          || '. جدّده من «توثيق المتجر» — عروضك الحالية تبقى تعمل، لكن لن تستطيع نشر عرضٍ جديد بعد الانتهاء.';

    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (r.store_id, '⚠️ توثيقك يقترب من الانتهاء', '⚠️ Verification expiring',
            v_msg, v_msg, 'system',
            jsonb_build_object('audience', 'seller', 'actionUrl', '/seller',
                               'action_url', '/seller', 'days_left', v_left));

    UPDATE public.store_verifications SET warn_stage = v_stage WHERE id = r.id;
  END LOOP;

  -- ② الانتهاء — كما كان: يمنع النشر الجديد ولا يُسقط عرضاً حيّاً.
  FOR r IN SELECT id, store_id FROM public.store_verifications
            WHERE status = 'approved' AND doc_expiry IS NOT NULL AND doc_expiry < current_date LOOP
    UPDATE public.store_verifications SET status = 'expired', decided_at = now() WHERE id = r.id;
    v_msg := '⚠️ انتهت صلاحية توثيق متجرك. عروضك الحالية تعمل، ولا يمكنك نشر عرضٍ جديد حتى تجدّد.';
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (r.store_id, '⚠️ انتهى توثيق متجرك', '⚠️ Verification expired',
            v_msg, v_msg, 'system',
            jsonb_build_object('audience', 'seller', 'actionUrl', '/seller', 'action_url', '/seller'));
    n := n + 1;
  END LOOP;

  RETURN n;
END
$function$
;


-- ═══ FUNCTION taki_guard_banned_signup() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_banned_signup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_hit text;
BEGIN
  SELECT id INTO v_hit FROM public.users
  WHERE is_suspended = true
    AND id <> NEW.id
    AND (   (NULLIF(btrim(lower(NEW.email)), '') IS NOT NULL
             AND lower(email) = btrim(lower(NEW.email)))
         OR (NULLIF(btrim(NEW.phone), '') IS NOT NULL
             AND regexp_replace(COALESCE(phone,''), '[^0-9]', '', 'g')
               = regexp_replace(NEW.phone, '[^0-9]', '', 'g')) )
  LIMIT 1;
  IF v_hit IS NOT NULL THEN
    RAISE EXCEPTION 'هذا البريد أو الجوال مرتبط بحساب موقوف. تواصل مع إدارة تاكي.'
      USING ERRCODE = 'P0001', HINT = 'P0019';
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_guard_branch_name_dup() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_branch_name_dup()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n text;
BEGIN
  IF NEW.is_active IS DISTINCT FROM true THEN RETURN NEW; END IF;
  v_n := public.taki_norm(COALESCE(NEW.name_ar, ''));
  IF v_n IS NULL OR btrim(v_n) = '' THEN RETURN NEW; END IF;
  IF EXISTS (
    SELECT 1 FROM public.store_branches b
     WHERE b.merchant_id = NEW.merchant_id
       AND b.id <> NEW.id
       AND COALESCE(b.is_active, true)
       AND public.taki_norm(COALESCE(b.name_ar, '')) = v_n
  ) THEN
    RAISE EXCEPTION 'BRANCH_NAME_DUP:%', NEW.name_ar
      USING hint = 'لديك موقعٌ نشطٌ بهذا الاسم. سمِّ الموقعين باسمين مختلفين (واكتب عنوان كلٍّ منهما) ليفرّق المشتري بينهما.';
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_guard_deal_merchant() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_deal_merchant()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_t text;
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  IF public.taki_is_system_caller() THEN RETURN NEW; END IF;
  IF public.taki_admin_perm('action_delete_deals') OR public.taki_admin_perm('tab_verification')
     OR public.taki_admin_perm('tab_sellers') THEN RETURN NEW; END IF;
  SELECT user_type INTO v_t FROM public.users WHERE id = NEW.store_id AND deleted_at IS NULL;
  IF v_t IS NULL OR v_t NOT IN ('seller','admin') THEN
    RAISE EXCEPTION 'هذا الحساب ليس حساب تاجر — لا يُنشر منه عرض.' USING ERRCODE = 'P0001', HINT = 'P0022';
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION taki_guard_delivery_block() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_delivery_block()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.delivery_blocked_by_admin IS DISTINCT FROM OLD.delivery_blocked_by_admin
     AND NOT COALESCE(public.taki_admin_perm('tab_delivery'), false)
     AND auth.uid()::text = NEW.store_id THEN
    RAISE EXCEPTION 'إيقاف التوصيل على هذا المتجر قرارٌ إداري — تواصل مع إدارة تاكي.' USING ERRCODE = 'P0001', HINT = 'P0021';
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_guard_publish_needs_declaration() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_publish_needs_declaration()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sell jsonb; v_msg text;
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  -- لا نُزعج عرضاً نشطاً يُحدَّث لسببٍ آخر وهو مقرٌّ أصلاً.
  IF TG_OP = 'UPDATE' AND OLD.status = 'active' THEN RETURN NEW; END IF;

  v_sell := public.store_can_sell(NEW.store_id);
  IF COALESCE((v_sell->>'ok')::boolean, false) THEN RETURN NEW; END IF;

  NEW.status := 'paused';

  v_msg := CASE v_sell->>'reason'
    WHEN 'no_method' THEN
      '📝 عرضك «' || COALESCE(NEW.item_name,'') || '» حُفظ مسوّدة. أقررتَ ألّا تقبل الدفع عند الاستلام ولا الدفع الإلكتروني — فلا وسيلة لتحصيل ثمنه. عدّل إقرار طريقة الحساب في لوحة التاجر ثم انشره.'
    ELSE
      '📝 عرضك «' || COALESCE(NEW.item_name,'') || '» حُفظ مسوّدة ولم يُنشر: لم تُقرّ بعد بطريقة حساب متجرك. أكمل «إقرار طريقة الحساب» في لوحة التاجر ثم انشره بضغطة.'
  END;

  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (NEW.store_id, '📝 عرضك محفوظ مسوّدة', '📝 Your deal is saved as a draft',
          v_msg, v_msg, 'system',
          jsonb_build_object('audience','seller','dealId', NEW.id,
                             'actionUrl','/seller','action_url','/seller'));
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_guard_publish_needs_verification() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_publish_needs_verification()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_same boolean;
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  IF public.taki_is_system_caller() THEN RETURN NEW; END IF;
  IF public.taki_admin_perm('action_delete_deals') OR public.taki_admin_perm('tab_verification')
     OR public.taki_admin_perm('tab_sellers') THEN RETURN NEW; END IF;

  -- 🪤 الامتياز ليس أبدياً ولا يصلح خانةَ نشرٍ دائمة: عرضٌ حيٌّ يُعدَّل **محتواه**
  --    يمرّ بالبوّابة. `dealRepository.save` تُرسل الصفّ كاملاً فتُطلق هذا
  --    الفرع، وبلا فحص المحتوى كان عرضٌ واحد مُعفى يصير منفذاً دائماً:
  --    يُعاد تسميته وتُبدَّل صوره ويُعاد تسعيره بلا حدّ.
  IF TG_OP = 'UPDATE' AND OLD.status = 'active' THEN
    v_same := (NEW.item_name        IS NOT DISTINCT FROM OLD.item_name)
          AND (NEW.description      IS NOT DISTINCT FROM OLD.description)
          AND (NEW.images           IS NOT DISTINCT FROM OLD.images)
          AND (NEW.original_price   IS NOT DISTINCT FROM OLD.original_price)
          AND (NEW.discounted_price IS NOT DISTINCT FROM OLD.discounted_price)
          AND (NEW.category         IS NOT DISTINCT FROM OLD.category);
    IF v_same THEN RETURN NEW; END IF;
  END IF;

  IF public.taki_publish_block(NEW.store_id) = 'not_verified' THEN
    RAISE EXCEPTION 'عرضك لم يُنشر: متجرك غير موثّق بعد. أرسل رقم سجلك من «توثيق المتجر» في لوحة التاجر.'
      USING ERRCODE = 'P0001', HINT = 'P0024';
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION taki_guard_store_cr() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_store_cr()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.cr_number IS NOT DISTINCT FROM OLD.cr_number THEN RETURN NEW; END IF;
  IF public.taki_is_system_caller() THEN RETURN NEW; END IF;
  IF public.taki_admin_perm('tab_verification') THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'رقم السجل يُحدَّد من طلب التوثيق وحده.' USING ERRCODE = 'P0001', HINT = 'P0023';
END
$function$
;


-- ═══ FUNCTION taki_guard_store_rename() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_store_rename()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.shop IS DISTINCT FROM OLD.shop
     AND NOT COALESCE(public.is_admin(), false)
     -- الدوال المالكة (طابور الموافقة) تعمل بلا `auth.uid()` أو بهوية الأدمن،
     -- وهذا الشرط يسمح لها ويمنع التاجر من الكتابة المباشرة من المتصفّح.
     AND auth.uid()::text = NEW.id THEN
    RAISE EXCEPTION 'تغيير اسم المتجر يمرّ بموافقة إدارة تاكي — أرسل طلباً من لوحة التاجر.'
      USING ERRCODE = 'P0001', HINT = 'P0020';
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_guard_suspended_publish() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_suspended_publish()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_blocked boolean;
BEGIN
  SELECT (is_suspended OR deleted_at IS NOT NULL) INTO v_blocked
  FROM public.users WHERE id = NEW.store_id;
  IF COALESCE(v_blocked, false) THEN
    RAISE EXCEPTION 'حسابك موقوف — لا يمكنك نشر عروض. تواصل مع إدارة تاكي.'
      USING ERRCODE = 'P0001', HINT = 'P0018';
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_guard_user_consent() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_user_consent()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- الأعمدةُ العشرة لم تُمسّ ⇒ لا شأنَ لنا (فلا يُعطَّل `saveProfile`
  -- الجزئيّ ولا بطاقةُ المتجر ولا مزامنةُ اللغة ولا أيٌّ من ١٤ مشغّلاً).
  IF  NEW.consent_terms_at          IS NOT DISTINCT FROM OLD.consent_terms_at
  AND NEW.consent_terms_version     IS NOT DISTINCT FROM OLD.consent_terms_version
  AND NEW.consent_privacy_at        IS NOT DISTINCT FROM OLD.consent_privacy_at
  AND NEW.consent_refund_at         IS NOT DISTINCT FROM OLD.consent_refund_at
  AND NEW.consent_ip                IS NOT DISTINCT FROM OLD.consent_ip
  AND NEW.consent_user_agent        IS NOT DISTINCT FROM OLD.consent_user_agent
  AND NEW.consent_age_confirmed     IS NOT DISTINCT FROM OLD.consent_age_confirmed
  AND NEW.consent_min_age           IS NOT DISTINCT FROM OLD.consent_min_age
  AND NEW.gateway_agreement_version IS NOT DISTINCT FROM OLD.gateway_agreement_version
  AND NEW.gateway_agreement_at      IS NOT DISTINCT FROM OLD.gateway_agreement_at
  THEN RETURN NEW;
  END IF;

  -- كتابةٌ صادرةٌ من `record_user_consent` في نفس المعاملة
  IF current_setting('taki.consent_write', true) = '1' THEN RETURN NEW; END IF;

  -- وعملُ الخادم (كرونُ التجهيل · هجرةٌ · خدمةٌ بمفتاح service_role)
  IF public.taki_is_system_caller() THEN RETURN NEW; END IF;

  RAISE EXCEPTION 'سجلُّ الموافقة لا يُعدَّل إلّا من خلال تسجيل الموافقة. / The consent record can only be written by recording consent.'
    USING ERRCODE = 'P0001', HINT = 'P0032';
END
$function$
;


-- ═══ FUNCTION taki_guard_user_created_at() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_guard_user_created_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.created_at IS NOT DISTINCT FROM OLD.created_at THEN RETURN NEW; END IF;
  IF public.taki_is_system_caller() THEN RETURN NEW; END IF;
  RAISE EXCEPTION 'تاريخ إنشاء الحساب لا يُعدَّل.' USING ERRCODE = 'P0001', HINT = 'P0025';
END
$function$
;


-- ═══ FUNCTION taki_haversine_km(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_haversine_km(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision)
 RETURNS double precision
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public'
AS $function$
DECLARE
    p CONSTANT DOUBLE PRECISION := 0.017453292519943295;
    a DOUBLE PRECISION;
BEGIN
    IF lat1 IS NULL OR lng1 IS NULL OR lat2 IS NULL OR lng2 IS NULL THEN
        RETURN NULL;
    END IF;
    a := 0.5
       - cos((lat2 - lat1) * p) / 2
       + cos(lat1 * p) * cos(lat2 * p) * (1 - cos((lng2 - lng1) * p)) / 2;
    RETURN 2 * 6371.0 * asin(sqrt(a));
END;
$function$
;


-- ═══ FUNCTION taki_iap_apply(p_store_id text, p_platform text, p_product_id text, p_purchase_key text, p_latest_txn text, p_expires_at timestamp with time zone, p_environment text, p_auto_renew boolean, p_event text, p_raw jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_iap_apply(p_store_id text, p_platform text, p_product_id text, p_purchase_key text, p_latest_txn text, p_expires_at timestamp with time zone, p_environment text, p_auto_renew boolean, p_event text, p_raw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_pkg_id  integer;
  v_owner   text;
  v_res     jsonb;
  v_net     numeric;
  v_pay_id  text;
  v_plan_id text;
  v_env     text := COALESCE(p_environment, 'Production');
BEGIN
  IF NOT public.taki_is_system_caller() THEN
    RAISE EXCEPTION 'IAP_SERVER_ONLY' USING HINT = 'IAP_SERVER_ONLY';
  END IF;
  IF p_platform NOT IN ('apple', 'google') THEN
    RAISE EXCEPTION 'IAP_BAD_PLATFORM' USING HINT = 'IAP_BAD_PLATFORM';
  END IF;
  IF COALESCE(p_purchase_key, '') = '' THEN
    RAISE EXCEPTION 'IAP_NO_KEY' USING HINT = 'IAP_NO_KEY';
  END IF;

  -- 🔴 بيئةُ الاختبار لا تُفعّل اشتراكاً حقيقياً ولا تكتب دفعةً «مدفوعة».
  --    و`appleLookup` تسقط إلى خادم الاختبار عند ٤٠٤ وهو **المسارُ الطبيعيّ**
  --    لشراء اختبار — فبلا هذا الفحص كان شراءُ سَندبوكس يمنح باقةً مجّاناً
  --    ويُدرج إيراداً وهمياً في التقارير والإقرار الضريبيّ.
  IF v_env = 'Sandbox'
     AND COALESCE((SELECT value::text FROM public.platform_settings
                    WHERE key = 'iap_allow_sandbox'), 'false') <> 'true' THEN
    RETURN jsonb_build_object('success', false, 'error', 'sandbox_not_allowed',
      'hint', 'يُفعَّل عمداً بمفتاح iap_allow_sandbox للاختبار وحده');
  END IF;

  SELECT (kv.value->>'package_id')::int INTO v_pkg_id
    FROM public.platform_settings ps, LATERAL jsonb_each(ps.value) AS kv
   WHERE ps.key = 'iap_products' AND kv.key = p_product_id
   LIMIT 1;
  IF v_pkg_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unmapped_product',
      'product_id', p_product_id,
      'hint', 'يُضاف المعرّف بـ scripts/iap-wire-products.js');
  END IF;

  SELECT store_id INTO v_owner FROM public.store_iap_subscriptions
   WHERE platform = p_platform AND purchase_key = p_purchase_key;

  -- 🔴 والمالكُ لا يُستبدل صامتاً. الحمايةُ صحيحة (لا يُسند شراءُ تاجرٍ
  --    لآخر)، لكنّ ردَّ «نجاح» لمن لم يُفعَّل له شيء **كذب**: تُعرض له
  --    «✅ تم تفعيل اشتراكك» ويبقى بلا اشتراك. يُقال له الحقيقةُ برمزٍ صريح.
  --    🪤 و`p_store_id IS NULL` مسارُ الإشعار (لا هويّةَ فيه) فيُقرأ المالك.
  IF p_store_id IS NOT NULL AND v_owner IS NOT NULL AND v_owner <> p_store_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'owned_by_another_account',
      'hint', 'هذا الشراءُ مسجَّلٌ لحسابٍ آخر — سجّل الدخول بذلك الحساب');
  END IF;

  INSERT INTO public.store_iap_subscriptions (
    store_id, platform, product_id, package_id, purchase_key, latest_txn_id,
    environment, status, expires_at, auto_renew, last_event, last_event_at, raw)
  VALUES (p_store_id, p_platform, p_product_id, v_pkg_id, p_purchase_key, p_latest_txn,
          v_env, 'active', p_expires_at, COALESCE(p_auto_renew, true),
          p_event, now(), COALESCE(p_raw, '{}'::jsonb))
  ON CONFLICT (platform, purchase_key) DO UPDATE SET
    store_id      = COALESCE(public.store_iap_subscriptions.store_id, EXCLUDED.store_id),
    product_id    = EXCLUDED.product_id,
    package_id    = EXCLUDED.package_id,
    latest_txn_id = EXCLUDED.latest_txn_id,
    environment   = EXCLUDED.environment,
    status        = 'active',
    expires_at    = EXCLUDED.expires_at,
    auto_renew    = EXCLUDED.auto_renew,
    last_event    = EXCLUDED.last_event,
    last_event_at = now(),
    raw           = EXCLUDED.raw,
    updated_at    = now();

  SELECT store_id INTO v_owner FROM public.store_iap_subscriptions
   WHERE platform = p_platform AND purchase_key = p_purchase_key;
  IF v_owner IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'no_owner',
      'hint', 'الشراءُ مسجَّلٌ بلا مالك — يربطه التاجر من التطبيق');
  END IF;

  v_res := public._taki_apply_package_dry(v_pkg_id);
  IF NOT COALESCE((v_res->>'success')::boolean, false) THEN RETURN v_res; END IF;
  v_net := (v_res->>'net')::numeric;

  -- 🔴 والفاتورةُ تُفحص **قبل** الإدراج لا بـ`ON CONFLICT DO NOTHING`: مشغّلُ
  --    `tr_invoice_no` يُسند `nextval` قبل كشف التعارض، و`nextval` لا يتراجع
  --    — فكلُّ إعادةِ إشعارٍ تحرق رقماً من تسلسلٍ ضريبيٍّ لا يُفترض أن فيه
  --    فجوة. وأبل تُعيد الإرسال أيّاماً، فالفجواتُ كانت ستتراكم.
  v_pay_id := p_platform || ':' || COALESCE(p_latest_txn, p_purchase_key);
  IF NOT EXISTS (SELECT 1 FROM public.subscription_payments WHERE id = v_pay_id) THEN
    SELECT id INTO v_plan_id FROM public.subscription_plans
     WHERE code = 'premium' OR id = 'premium' LIMIT 1;
    INSERT INTO public.subscription_payments (
      id, merchant_id, plan_id, amount, currency, status, payment_method,
      gateway_provider, gateway_reference, branches_count, period_start, period_end,
      metadata, paid_at, created_at)
    VALUES (
      v_pay_id, v_owner, v_plan_id, v_net, 'SAR', 'paid',
      CASE p_platform WHEN 'apple' THEN 'apple_iap' ELSE 'google_play' END,
      CASE p_platform WHEN 'apple' THEN 'App Store' ELSE 'Google Play' END,
      COALESCE(p_latest_txn, p_purchase_key),
      (v_res->>'max_branches')::int,
      now(), p_expires_at,
      jsonb_build_object('platform', p_platform, 'product_id', p_product_id,
                         'environment', v_env, 'event', p_event,
                         'package_id', v_pkg_id,
                         'source', CASE p_platform WHEN 'apple' THEN 'app_store' ELSE 'play_store' END),
      now(), now());
  END IF;

  -- 🔴 ويُمرَّر تاريخُ المتجر وحالةُ تجديده — وهما ما كان يُرمى.
  RETURN public._taki_apply_package(v_owner, v_pkg_id, p_expires_at, p_auto_renew)
         || jsonb_build_object('payment_id', v_pay_id, 'package_id', v_pkg_id,
                               'environment', v_env);
END $function$
;


-- ═══ FUNCTION taki_iap_claim(p_store_id text, p_platform text, p_product_id text, p_purchase_key text, p_latest_txn text, p_environment text, p_raw jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_iap_claim(p_store_id text, p_platform text, p_product_id text, p_purchase_key text, p_latest_txn text, p_environment text, p_raw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_pkg_id integer; v_owner text;
BEGIN
  IF NOT public.taki_is_system_caller() THEN
    RAISE EXCEPTION 'IAP_SERVER_ONLY' USING HINT = 'IAP_SERVER_ONLY';
  END IF;
  IF p_platform NOT IN ('apple','google') OR COALESCE(p_purchase_key,'') = ''
     OR COALESCE(p_store_id,'') = '' THEN
    RETURN jsonb_build_object('success', false, 'error', 'bad_input');
  END IF;

  SELECT (kv.value->>'package_id')::int INTO v_pkg_id
    FROM public.platform_settings ps, LATERAL jsonb_each(ps.value) AS kv
   WHERE ps.key = 'iap_products' AND kv.key = p_product_id LIMIT 1;
  IF v_pkg_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'unmapped_product');
  END IF;

  SELECT store_id INTO v_owner FROM public.store_iap_subscriptions
   WHERE platform = p_platform AND purchase_key = p_purchase_key;
  IF v_owner IS NOT NULL AND v_owner <> p_store_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'owned_by_another_account');
  END IF;

  INSERT INTO public.store_iap_subscriptions (
    store_id, platform, product_id, package_id, purchase_key, latest_txn_id,
    environment, status, expires_at, auto_renew, last_event, last_event_at, raw)
  VALUES (p_store_id, p_platform, p_product_id, v_pkg_id, p_purchase_key, p_latest_txn,
          COALESCE(p_environment,'Production'), 'on_hold', NULL, true,
          'CLAIM_PENDING', now(), COALESCE(p_raw,'{}'::jsonb))
  ON CONFLICT (platform, purchase_key) DO UPDATE SET
    store_id      = COALESCE(public.store_iap_subscriptions.store_id, EXCLUDED.store_id),
    latest_txn_id = COALESCE(EXCLUDED.latest_txn_id, public.store_iap_subscriptions.latest_txn_id),
    last_event    = 'CLAIM_PENDING',
    last_event_at = now(),
    updated_at    = now();
  -- 🪤 ولا تُمسّ حالةٌ قائمة: شراءٌ سارٍ لا يُنزَل إلى «معلَّق» بنداءِ ربط.
  RETURN jsonb_build_object('success', true, 'claimed', true, 'package_id', v_pkg_id);
END $function$
;


-- ═══ FUNCTION taki_iap_sync(p_platform text, p_purchase_key text, p_status text, p_expires_at timestamp with time zone, p_auto_renew boolean, p_event text, p_raw jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_iap_sync(p_platform text, p_purchase_key text, p_status text, p_expires_at timestamp with time zone, p_auto_renew boolean, p_event text, p_raw jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_row public.store_iap_subscriptions;
BEGIN
  IF NOT public.taki_is_system_caller() THEN
    RAISE EXCEPTION 'IAP_SERVER_ONLY' USING HINT = 'IAP_SERVER_ONLY';
  END IF;

  UPDATE public.store_iap_subscriptions SET
    status        = p_status,
    expires_at    = COALESCE(p_expires_at, expires_at),
    auto_renew    = COALESCE(p_auto_renew, auto_renew),
    last_event    = p_event,
    last_event_at = now(),
    raw           = COALESCE(p_raw, raw),
    updated_at    = now()
   WHERE platform = p_platform AND purchase_key = p_purchase_key
  RETURNING * INTO v_row;

  IF v_row.id IS NULL THEN
    -- 🪤 إشعارٌ عن شراءٍ لا نعرفه **ليس خطأً يُعاد**: أبل تُرسل إشعاراتَ
    --    بيئة الاختبار وإشعاراتِ مشترياتٍ سبقت الربط. يُجاب بنجاحٍ وإلّا
    --    أعادت المحاولةَ أيّاماً. (ونفسُ منطق ٤٢٩ مع زد في v15.22.)
    RETURN jsonb_build_object('success', true, 'unknown_purchase', true);
  END IF;

  -- وانقطاعُ الاشتراك يُقصّر صلاحيّتَه فوراً، ولا يُحذف سجلٌّ.
  IF p_status IN ('expired', 'revoked') AND v_row.store_id IS NOT NULL THEN
    UPDATE public.store_profiles
       SET subscription_expires_at = LEAST(subscription_expires_at, now()),
           auto_renew = false, updated_at = now()
     WHERE store_id = v_row.store_id;
  ELSIF p_status = 'canceled' AND v_row.store_id IS NOT NULL THEN
    -- إلغاءُ التجديد التلقائيّ لا يُنهي المدّةَ المدفوعة — تكتمل.
    UPDATE public.store_profiles
       SET auto_renew = false, subscription_canceled_at = now(), updated_at = now()
     WHERE store_id = v_row.store_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'status', p_status,
                            'store_id', v_row.store_id);
END $function$
;


-- ═══ FUNCTION taki_is_blocked_pair(p_a text, p_b text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_is_blocked_pair(p_a text, p_b text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT public.taki_block_since(p_a, p_b) IS NOT NULL;
$function$
;


