-- ═══ FUNCTION taki_is_system_caller() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_is_system_caller()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_role text;
BEGIN
  -- `session_user` هو الدور الذي **اتّصلت** به الجلسة، ولا يغيّره
  -- `SET ROLE` ولا `SECURITY DEFINER`. وهو وحده ما يفرّق بين كرونٍ يعمل
  -- على الخادم وبين متصفّحٍ على الإنترنت.
  IF session_user IN ('postgres', 'supabase_admin') THEN RETURN true; END IF;

  -- خدمةٌ تحمل مفتاح `service_role` تصل بنفس اتصال PostgREST
  -- (`authenticator`)، فتُميَّز بمطالبة الدور في الطلب لا بدور الاتصال.
  BEGIN
    v_role := current_setting('request.jwt.claims', true)::jsonb ->> 'role';
  EXCEPTION WHEN OTHERS THEN
    v_role := NULL;   -- مطالباتٌ مشوّهة تُعامَل معاملة «ليس نظاماً»
  END;
  RETURN COALESCE(v_role, '') = 'service_role';
END;
$function$
;


-- ═══ FUNCTION taki_issue_order_invoice(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_issue_order_invoice(p_barcode text)
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_store text;
  v_no    text;
  v_seq   integer;
BEGIN
  SELECT store_id, invoice_no INTO v_store, v_no
    FROM public.order_invoices WHERE barcode = p_barcode FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  IF v_no IS NOT NULL THEN RETURN v_no; END IF;   -- أُصدرت من قبل: لا تُصدر مرّتين

  -- عدّاد التاجر. `ON CONFLICT DO UPDATE` يقفل الصفّ فيتسلسل تاجران معاً بلا
  -- تصادم، وتراجُع المعاملة يُعيد الرقم فلا تنشأ فجوة.
  INSERT INTO public.store_invoice_counters (store_id, last_seq)
  VALUES (v_store, 1)
  ON CONFLICT (store_id) DO UPDATE
    SET last_seq = public.store_invoice_counters.last_seq + 1,
        updated_at = now()
  RETURNING last_seq INTO v_seq;

  v_no := 'TK-' || lpad(v_seq::text, 6, '0');

  UPDATE public.order_invoices
     SET seq = v_seq, invoice_no = v_no, issued_at = now()
   WHERE barcode = p_barcode;

  RETURN v_no;
END
$function$
;


-- ═══ FUNCTION taki_loc_keys(p_region text, p_city text, p_location_id text, p_locations jsonb) INVOKER owner=postgres search_path=search_path=pg_catalog anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_loc_keys(p_region text, p_city text, p_location_id text, p_locations jsonb)
 RETURNS text[]
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT COALESCE(
    CASE
      -- عرض متعدد المواقع: مفاتيح كل فرع (نفس قاعدة dealResolvedLocations)
      WHEN jsonb_typeof(p_locations) = 'array' AND jsonb_array_length(p_locations) > 1 THEN
        ARRAY(
          SELECT DISTINCT k
          FROM jsonb_array_elements(p_locations) e
          CROSS JOIN LATERAL (VALUES
            ('r:' || COALESCE(NULLIF(e->>'region',''), '~')),
            ('c:' || COALESCE(NULLIF(e->>'city',''), '~')),
            ('m:' || COALESCE(NULLIF(e->>'locationId',''), '~'))
          ) v(k)
          WHERE k NOT LIKE '%:~'
        )
      ELSE
        ARRAY(
          SELECT DISTINCT k
          FROM (VALUES
            ('r:' || COALESCE(NULLIF(p_region,''), '~')),
            ('c:' || COALESCE(NULLIF(p_city,''), '~')),
            ('m:' || COALESCE(NULLIF(p_location_id,''), '~'))
          ) v(k)
          WHERE k NOT LIKE '%:~'
        )
    END, ARRAY[]::text[]);
$function$
;


-- ═══ FUNCTION taki_map_gate() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_map_gate()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_uid  text := auth.uid()::text;
  v_type text;
  v_shop text;
BEGIN
  -- ١) لا هويّة ⇒ لا خدمة. هذا وحده يُخرج الإنترنت كلّه من الباب.
  IF v_uid IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED');
  END IF;

  -- ٢) والخدمة للتجّار وحدهم: المشتري لا يرسم موقع محلّ.
  SELECT u.user_type, u.shop INTO v_type, v_shop
  FROM public.users u WHERE u.id = v_uid AND u.deleted_at IS NULL
    AND COALESCE(u.is_suspended, false) = false;
  IF v_type IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED');
  END IF;
  IF v_type NOT IN ('seller','admin') AND NULLIF(btrim(COALESCE(v_shop,'')), '') IS NULL THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SELLER_ONLY');
  END IF;

  -- ٣) حدّ المعدّل: ٢٠ نداءً في الساعة لكل تاجر. التاجر يضبط موقع محلّه مرّات
  --    معدودة في عمر المتجر، فعشرون سقفٌ سخيّ لاستعمالٍ حقيقي وضيّقٌ على إساءة.
  --    (`taki_rate_check` ترفع P0011 عند التجاوز — نلتقطها ونردّ ردّاً مفهوماً
  --    بدل أن يصل خطأ قاعدة بيانات إلى المتصفّح.)
  BEGIN
    PERFORM public.taki_rate_check('mapgate:' || v_uid, 20, 3600, 'RATE_LIMIT');
  EXCEPTION WHEN SQLSTATE 'P0011' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'RATE_LIMIT');
  END;

  RETURN jsonb_build_object('ok', true);
END $function$
;


-- ═══ FUNCTION taki_mark_campaign_seen(p_campaign_id text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_mark_campaign_seen(p_campaign_id text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := (SELECT auth.uid()::text); v_new boolean := false;
BEGIN
  IF v_uid IS NULL OR COALESCE(btrim(p_campaign_id),'') = '' THEN RETURN false; END IF;
  IF NOT EXISTS (SELECT 1 FROM public.promotional_campaigns WHERE id = p_campaign_id) THEN
    RETURN false;
  END IF;
  INSERT INTO public.promo_impressions (campaign_id, user_id, seen_at)
  VALUES (p_campaign_id, v_uid, NOW())
  ON CONFLICT (campaign_id, user_id) DO UPDATE SET seen_at = COALESCE(public.promo_impressions.seen_at, NOW());
  -- العدّادُ يُحسب من الحقيقة لا يُراكَم: مجموعُ من رآها فعلاً.
  UPDATE public.promotional_campaigns c
     SET current_impressions = (SELECT count(*) FROM public.promo_impressions p WHERE p.campaign_id = c.id)
   WHERE c.id = p_campaign_id;
  RETURN true;
END $function$
;


-- ═══ FUNCTION taki_mark_session_booked(p_session text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_mark_session_booked(p_session text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_sid text := left(btrim(COALESCE(p_session,'')), 64);
  v_me  text := (SELECT auth.uid())::text;
BEGIN
  IF v_sid = '' THEN RETURN; END IF;

  -- حدٌّ خشنٌ يمنع تمشيطَ معرّفاتِ الجلسات. ولا يُرفع استثناءً: القياسُ لا
  -- يُعطّل حجزاً، والمنادي يبتلع الخطأ أصلاً (siteVisit.ts:125 `.catch`).
  BEGIN
    PERFORM public.taki_rate_check('mkbk:' || COALESCE(public._taki_client_ip(), 'noip'),
                                   30, 60, 'too many conversion marks');
  EXCEPTION WHEN OTHERS THEN RETURN;
  END;

  UPDATE public.site_sessions
     SET booked = true, last_seen_at = now()
   WHERE session_id = v_sid
     AND COALESCE(booked, false) = false
     AND last_seen_at > now() - interval '30 minutes'
     AND (user_id IS NULL OR user_id = v_me);
END
$function$
;


-- ═══ FUNCTION taki_match_terms(p_text text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_match_terms(p_text text)
 RETURNS text[]
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT coalesce(array_agg(mt.term), '{}'::text[])
    FROM moderation_terms mt
   WHERE p_text IS NOT NULL AND btrim(p_text) <> ''
     AND (
          (mt.match_mode = 'substr' AND p_text ILIKE '%' || mt.term || '%')
       OR (mt.match_mode = 'word'   AND p_text ~* ('\m' || mt.term || '\M'))
     );
$function$
;


-- ═══ FUNCTION taki_merchant_setup_reminders() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_merchant_setup_reminders()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  r          record;
  v_gaps     jsonb;
  v_refund   boolean;
  v_paydecl  boolean;
  v_done     int;
  v_ar       text;
  v_en       text;
  v_sent     integer := 0;
BEGIN
  FOR r IN
    SELECT u.id
    FROM public.users u
    WHERE u.deleted_at IS NULL
      AND COALESCE(u.is_suspended, false) = false
      AND (u.user_type IN ('seller','admin') OR NULLIF(btrim(COALESCE(u.shop,'')), '') IS NOT NULL)
  LOOP
    v_gaps    := public.merchant_setup_gaps(r.id);
    v_refund  := COALESCE((v_gaps->>'refund_policy_missing')::boolean, false);
    v_paydecl := COALESCE((v_gaps->>'payment_undeclared')::boolean, false);
    -- شرط الإطلاق: النقصان المكلفان وحدهما (بلا تغيير عن v14.45).
    CONTINUE WHEN NOT (v_refund OR v_paydecl);

    -- فترة التهدئة: أسبوع كامل بين تذكيرين لنفس المتجر
    CONTINUE WHEN EXISTS (
      SELECT 1 FROM public.notifications n
      WHERE n.user_id = r.id
        AND n.meta_data->>'kind' = 'setup_gap'
        AND n.created_at > now() - interval '7 days'
    );

    -- عدّادٌ يطابق الشريط على الشاشة حرفاً بحرف (الخطوات الستّ نفسها).
    v_done :=   COALESCE((v_gaps->>'pay_declared')::boolean, false)::int
              + COALESCE((v_gaps->>'profile_set')::boolean,  false)::int
              + COALESCE((v_gaps->>'hours_set')::boolean,    false)::int
              + COALESCE((v_gaps->>'refund_set')::boolean,   false)::int
              + COALESCE((v_gaps->>'vat_answered')::boolean, false)::int
              + COALESCE((v_gaps->>'has_live_deal')::boolean,false)::int;

    v_ar := 'أنجزتَ ' || v_done || ' من ٦ خطوات:' || E'\n';
    v_en := 'You have completed ' || v_done || ' of 6 steps:' || E'\n';

    IF NOT COALESCE((v_gaps->>'pay_declared')::boolean, false) THEN
      v_ar := v_ar || '• لم تُقرّ طريقة الحساب — وعروضك تبقى مسوّدات لا يراها أحد حتى تُقرّها.' || E'\n';
      v_en := v_en || '• You have not declared how you get paid — your deals stay drafts until you do.' || E'\n';
    END IF;
    IF NOT COALESCE((v_gaps->>'profile_set')::boolean, false) THEN
      v_ar := v_ar || '• بطاقة متجرك ناقصة (الشعار أو النبذة) — وهي أوّل ما يراه المشتري. تُكمَل من صفحة «صفحتي» ← «تعديل البروفايل».' || E'\n';
      v_en := v_en || '• Your store card is incomplete (logo or blurb) — it is the first thing buyers see. Finish it in “My store” → “Edit profile”.' || E'\n';
    END IF;
    IF NOT COALESCE((v_gaps->>'hours_set')::boolean, false) THEN
      v_ar := v_ar || '• لم تحدّد ساعات العمل — فلا يعرف المشتري متى يستلم.' || E'\n';
      v_en := v_en || '• No opening hours set — buyers cannot tell when to collect.' || E'\n';
    END IF;
    IF NOT COALESCE((v_gaps->>'refund_set')::boolean, false) THEN
      v_ar := v_ar || '• لم تكتب سياسة الاسترداد — وصفحة كل عرضٍ لك تقول للمشتري: «لم يُعلن هذا المتجر سياسة استرداد».' || E'\n';
      v_en := v_en || '• No refund policy — every deal page of yours tells buyers: “this store has not published a refund policy”.' || E'\n';
    END IF;
    IF NOT COALESCE((v_gaps->>'vat_answered')::boolean, false) THEN
      v_ar := v_ar || '• لم تحدّد وضعك الضريبي — وهو ما يحدّد شكل فاتورة كل طلب. وإجابة «غير مسجّل» كافية.' || E'\n';
      v_en := v_en || '• VAT status not stated — it decides the shape of every order invoice. “Not registered” is a complete answer.' || E'\n';
    END IF;
    IF NOT COALESCE((v_gaps->>'has_live_deal')::boolean, false) THEN
      v_ar := v_ar || '• لا عرض حيّ لديك — فمتجرك لا يظهر في الرئيسية ولا في «حولي».' || E'\n';
      v_en := v_en || '• No live deal — your store appears neither on the home feed nor in “Nearby”.' || E'\n';
    END IF;

    v_ar := v_ar || E'\nافتح لوحة التاجر وستجد المسار كاملاً في أعلى الصفحة، وزرّاً لكل خطوة.';
    v_en := v_en || E'\nOpen your seller dashboard — the full path is at the top of the page, with a button per step.';

    INSERT INTO public.notifications (id, user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES ('ntf_gap_' || (extract(epoch from clock_timestamp())*1000)::bigint || '_' || substr(md5(random()::text), 1, 6),
            r.id,
            '🧭 جهّز متجرك للبيع', 'Get your store ready to sell',
            v_ar, v_en, 'system',
            jsonb_build_object('audience', 'seller', 'kind', 'setup_gap',
                               -- وجهةٌ حقيقية: البوتان يبثّان الإشعار حرفياً،
                               -- وبلا هذا الحقل يصل التاجرَ إرشادٌ بلا زرّ.
                               'actionUrl', '/seller',
                               'steps_done', v_done,
                               'refund_policy_missing', v_refund,
                               'payment_undeclared', v_paydecl));
    v_sent := v_sent + 1;
  END LOOP;
  RETURN v_sent;
END $function$
;


-- ═══ FUNCTION taki_merchant_vat_rate() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_merchant_vat_rate()
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT GREATEST(0, LEAST(100, COALESCE(
    (SELECT NULLIF(value->>'rate','')::numeric FROM public.platform_settings WHERE key = 'merchant_vat'),
    15)));
$function$
;


-- ═══ FUNCTION taki_moderation_escalate() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_moderation_escalate()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_cnt int; v_susp boolean; v_role text; v_name text;
  v_delay int; v_wid uuid; v_msg text;
BEGIN
  BEGIN
    IF NEW.offender_id IS NULL THEN RETURN NEW; END IF;
    SELECT count(*) INTO v_cnt FROM moderation_flags WHERE offender_id = NEW.offender_id;
    SELECT is_suspended, user_type, coalesce(shop, name) INTO v_susp, v_role, v_name
      FROM users WHERE id = NEW.offender_id;

    IF v_cnt = 2 THEN
      -- إنذار آلي (مرة واحدة عند المخالفة الثانية) — السجل فوري، والإشعار
      -- يحترم moderation_settings.warn_delay_minutes (إيحاء المراجعة البشرية)
      v_msg := 'رصدت إدارة تاكي محتوى مخالفاً متكرراً من حسابك (ألفاظ أو محتوى محظور). هذا إنذار رسمي — تكرار المخالفة مرة أخرى يؤدي إلى تعليق حسابك.';
      INSERT INTO user_warnings (user_id, user_role, reason, context_message, admin_id)
      VALUES (NEW.offender_id, v_role, '⚠️ إنذار آلي: مخالفة محتوى متكررة (المخالفة الثانية)', left(coalesce(NEW.content,''), 300), NULL)
      RETURNING id INTO v_wid;
      v_delay := COALESCE((SELECT (value->>'warn_delay_minutes')::int FROM platform_settings WHERE key='moderation_settings'), 0);
      IF v_delay <= 0 THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        VALUES (NEW.offender_id, '⚠️ تنبيه من إدارة تاكي', '⚠️ Warning from TAKI', v_msg, v_msg, 'system',
                jsonb_build_object('audience','user','admin_warning', TRUE));
      ELSE
        INSERT INTO pending_warnings (warning_id, user_id, message, deliver_at)
        VALUES (v_wid, NEW.offender_id, v_msg, now() + make_interval(mins => v_delay));
      END IF;
      -- «تحت المجهر» — إبلاغ الأدمن
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      SELECT u.id, '🔎 حساب تحت المجهر', '🔎 Account under watch',
             'المستخدم «' || coalesce(v_name,'?') || '» سجّل مخالفتي محتوى — أُرسل له إنذار آلي. المخالفة الثالثة تعلق حسابه تلقائياً.',
             'Two content violations — auto-warning sent.', 'system',
             jsonb_build_object('audience','admin')
      FROM users u WHERE u.deleted_at IS NULL AND u.user_type = 'admin';

    ELSIF v_cnt >= 3 AND NOT COALESCE(v_susp, false) THEN
      UPDATE users SET is_suspended = true WHERE id = NEW.offender_id;
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      VALUES (NEW.offender_id, '⛔ تم تعليق حسابك', '⛔ Account suspended',
              'عُلّق حسابك لتكرار مخالفات المحتوى بعد إنذار رسمي. للاعتراض تواصل مع الإدارة من «الشكاوى / تواصل الإدارة».',
              'Your account was suspended for repeated content violations.', 'system',
              jsonb_build_object('audience','user'));
      INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
      SELECT u.id, '⛔ تعليق تلقائي لحساب', '⛔ Auto-suspension',
             'عُلّق حساب «' || coalesce(v_name,'?') || '» تلقائياً بعد ٣ مخالفات محتوى. راجعه من «الحسابات المعلقة» في البلاغات.',
             'Account auto-suspended after 3 violations.', 'system',
             jsonb_build_object('audience','admin')
      FROM users u WHERE u.deleted_at IS NULL AND u.user_type = 'admin';
    END IF;
  EXCEPTION WHEN OTHERS THEN
    NULL; -- التصعيد لا يكسر تسجيل المخالفة أبداً
  END;
  RETURN NEW;
END $function$
;


