    'body_en',  'Your subscription expired and your deals were paused. Renew now to restore them instantly.'),
 'sub_cancelled', jsonb_build_object(
    'enabled', true,
    'channels', jsonb_build_object('inapp', true, 'email', false),
    'title_ar', '👋 تم إلغاء التجديد التلقائي',
    'title_en', '👋 Auto-renew cancelled',
    'body_ar',  'تم إلغاء التجديد التلقائي لاشتراكك بناءً على طلبك. يبقى اشتراكك فعالاً حتى {expires} ولن يُجدَّد تلقائياً.',
    'body_en',  'Auto-renew was cancelled as requested. Your subscription stays active until {expires} and will not renew automatically.'),
 'booking_reminder', jsonb_build_object(
    'enabled', true,
    'minutes_before', 15,
    'channels', jsonb_build_object('inapp', true, 'email', false),
    'title_ar', '⏰ باقٍ {minutes} دقيقة على حجزك',
    'title_en', '⏰ {minutes} minutes left on your booking',
    'body_ar',  'باقي أقل من {minutes} دقيقة على انتهاء حجز {item}. توجّه للاستلام قبل الإلغاء التلقائي.',
    'body_en',  'Less than {minutes} minutes left on your booking for {item}. Head to the store before it auto-cancels.')
);
$function$
;


-- ═══ FUNCTION taki_msg_setting(p_event text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_msg_setting(p_event text)
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
SELECT COALESCE(public.taki_msg_defaults()->p_event, '{}'::jsonb)
       || COALESCE((SELECT value->p_event FROM public.platform_settings WHERE key = 'message_settings'), '{}'::jsonb);
$function$
;


-- ═══ FUNCTION taki_new_order_code() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_new_order_code()
 RETURNS text
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_len   CONSTANT int := 10;   -- ← يطابق TAKI_ORDER_CODE_LEN أعلاه وORDER_CODE_LEN في الموقع
  v_pool  text;
  v_code  text;
  v_tries int := 0;
BEGIN
  LOOP
    v_tries := v_tries + 1;

    -- 🪤 مصدرُ العشوائية `gen_random_uuid()` لا `random()`: الأخيرة تُبذَر
    --    لكلّ جلسةٍ على حدة، وأسوأُ لحظةٍ لتشابه بذرتين هي أشدُّ لحظات الضغط
    --    (موجةُ حجزٍ تفتح اتصالاتٍ متزامنة). والـuuid هنا مصدرٌ قويّ مدمج،
    --    فيوازي `crypto.getRandomValues` في الموقع.
    -- وخاناتُ الـuuid الستّ عشرية موزَّعة بانتظام، فترشيحُ ما كان منها ٠–٩
    -- يُخرج أرقاماً **منتظمة** لا منحازة.
    v_pool := '';
    WHILE length(v_pool) < v_len LOOP
      -- و`ltrim` تضمن ألّا يبدأ الرمز بصفر: صفرٌ بادئ يضيع في أوّل لحظة
      -- يُكتب فيها الرقم في جدول بيانات أو حقلٍ رقميّ، فيعود العميل برمزٍ
      -- أقصرَ بخانة ولا يجده أحد.
      v_pool := ltrim(v_pool || regexp_replace(gen_random_uuid()::text, '[^0-9]', '', 'g'), '0');
    END LOOP;
    v_code := substr(v_pool, 1, v_len);

    -- الرمزُ يجب أن يكون حرّاً في العمودين معاً: الماسحُ يقبل أيّهما
    -- (`upper(barcode) = v_code OR upper(backup_code) = v_code`)، فرمزٌ
    -- يصادم رمزاً احتياطياً قديماً يجعل المسحَ يفتح الطلب الخطأ.
    EXIT WHEN NOT EXISTS (
      SELECT 1 FROM public.bookings b
       WHERE b.barcode = v_code OR b.backup_code = v_code
    );

    IF v_tries >= 50 THEN
      -- عند ٩×١٠⁹ احتمالاً هذا مستحيلٌ عملياً — فوقوعُه يعني عطلاً في مصدر
      -- العشوائية لا سوءَ حظّ. نرفع بدل أن ندور إلى الأبد داخل معاملة حجز.
      RAISE EXCEPTION 'تعذّر توليد رقم طلبٍ حرّ بعد % محاولة — افحص مصدر العشوائية.', v_tries;
    END IF;
  END LOOP;

  RETURN v_code;
END
$function$
;


-- ═══ FUNCTION taki_norm(txt text) INVOKER owner=postgres search_path=search_path=pg_catalog anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_norm(txt text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE PARALLEL SAFE
 SET search_path TO 'pg_catalog'
AS $function$
  SELECT NULLIF(btrim(
    regexp_replace(
      translate(
        translate(
          lower(
            -- ١) حذف التشكيل والتطويل: U+0610..061A, U+064B..065F, U+0640, U+0670, U+06D6..06ED
            regexp_replace(
              COALESCE(txt, ''),
              '[' || chr(1552) || '-' || chr(1562)
                  || chr(1611) || '-' || chr(1631)
                  || chr(1600) || chr(1648)
                  || chr(1750) || '-' || chr(1773) || ']',
              '', 'g'
            )
          ),
          -- ٢) توحيد الحروف: أ إ آ ٱ → ا | ى ئ → ي | ؤ → و | ة → ه
          chr(1571)||chr(1573)||chr(1570)||chr(1649)||chr(1609)||chr(1574)||chr(1572)||chr(1577),
          chr(1575)||chr(1575)||chr(1575)||chr(1575)||chr(1610)||chr(1610)||chr(1608)||chr(1607)
        ),
        -- ٣) الأرقام العربية والفارسية → لاتينية
        chr(1632)||chr(1633)||chr(1634)||chr(1635)||chr(1636)||chr(1637)||chr(1638)||chr(1639)||chr(1640)||chr(1641)||
        chr(1776)||chr(1777)||chr(1778)||chr(1779)||chr(1780)||chr(1781)||chr(1782)||chr(1783)||chr(1784)||chr(1785),
        '01234567890123456789'
      ),
      -- ٤) كل ما عدا الحروف/الأرقام يصير مسافة واحدة (يوحّد الترقيم والرموز)
      '[^0-9a-z' || chr(224) || '-' || chr(255) || chr(1569) || '-' || chr(1610) || ']+',
      ' ', 'g'
    )
  ), '');
$function$
;


-- ═══ FUNCTION taki_notification_type_guard(p_type text) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_notification_type_guard(p_type text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v text := COALESCE(NULLIF(btrim(p_type), ''), 'system');
BEGIN
  IF v NOT IN ('booking','deal','system','rating','follow','marketing',
               'report','subscription','contest') THEN
    RAISE EXCEPTION
      'نوع إشعار غير معروف: «%». المقبول: booking · deal · system · rating · follow · marketing · report · subscription · contest',
      v USING ERRCODE = '22023';
  END IF;
  RETURN v;
END $function$
;


-- ═══ FUNCTION taki_notify_deal_published() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_notify_deal_published()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_msg text;
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  IF TG_OP = 'UPDATE' AND OLD.status = 'active' THEN RETURN NEW; END IF;
  v_msg := '✅ نُشر عرضك «' || COALESCE(NEW.item_name,'') || '» وصار ظاهراً للمشترين في الرئيسية والبحث وفي البوتين.';
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  VALUES (NEW.store_id, '✅ نُشر عرضك', '✅ Your deal is live', v_msg, v_msg, 'deal',
          jsonb_build_object('audience','seller','dealId', NEW.id,
                             'actionUrl','/deal/' || NEW.id, 'action_url','/deal/' || NEW.id));
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_open_holds(p_deal_id text, p_variant_id text, p_location_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_open_holds(p_deal_id text, p_variant_id text DEFAULT NULL::text, p_location_id text DEFAULT NULL::text)
 RETURNS integer
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(CASE WHEN p_variant_id IS NULL THEN (
      SELECT sum(GREATEST(COALESCE(b.booked_quantity, 1), 1))
        FROM public.bookings b
       WHERE b.deal_id = p_deal_id
         AND b.status IN ('pending', 'acknowledged')
         AND (p_location_id IS NULL OR b.location_id = p_location_id)
    ) ELSE (
      -- 🔴 الوسم `__variant__` لا مطابقة `c` وحدها: الخياراتُ الإضافية
      --    تتشارك نفس المفتاح (٢٤ منها في الإنتاج) وليست مخزوناً.
      SELECT sum(GREATEST(COALESCE((s->>'qty')::int, 1), 1))
        FROM public.bookings b,
             jsonb_array_elements(COALESCE(b.selected_options, '[]'::jsonb)) s
       WHERE b.deal_id = p_deal_id
         AND b.status IN ('pending', 'acknowledged')
         AND (p_location_id IS NULL OR b.location_id = p_location_id)
         AND s->>'g' = '__variant__'
         AND s->>'c' = p_variant_id
    ) END, 0)::int;
$function$
;


-- ═══ FUNCTION taki_process_booking_expiry() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_process_booking_expiry()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  PERFORM public.warn_expiring_bookings();
  PERFORM public.notify_shops_closing_soon();
  PERFORM public.expire_due_bookings();
END; $function$
;


-- ═══ FUNCTION taki_propagate_store_name() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_propagate_store_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.shop IS DISTINCT FROM OLD.shop THEN
    UPDATE public.deals
       SET shop_name = COALESCE(NULLIF(btrim(NEW.shop), ''), NULLIF(btrim(NEW.name), ''), 'متجر')
     WHERE store_id = NEW.id;
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_prune_analytics() DEFINER owner=postgres search_path=search_path=public, pg_catalog anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_prune_analytics()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_catalog'
AS $function$
BEGIN
  -- أحداث القِمع التفصيلية — ٩٠ يوماً تكفي كل لوحات التاجر والاتجاهات
  DELETE FROM public.store_analytics_events WHERE created_at < now() - interval '90 days';
  -- أحداث فتح التطبيق (جمهور المدن) — ١٨٠ يوماً لمقارنات الموسم بالموسم
  DELETE FROM public.analytics_events       WHERE created_at < now() - interval '180 days';
  -- سجل الحضور اللحظي — لا معنى له بعد ٣٠ يوماً
  DELETE FROM public.user_sessions          WHERE last_seen_at < now() - interval '30 days';
END
$function$
;


-- ═══ FUNCTION taki_prune_auth_audit() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_prune_auth_audit()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int;
BEGIN
  -- 🪤 ٩٠ يوماً: نفسُ نافذةِ `activity_log` المعلَنةِ في سياسة الخصوصية.
  --    ولا قارئَ لهذا الجدول في القاعدة إطلاقاً (قِيس: صفرُ دالّة تذكره)،
  --    فالنافذةُ ليست رهينةَ كشفٍ كما هي في سجلّ الكرون (درس v15.25).
  DELETE FROM auth.audit_log_entries WHERE created_at < now() - interval '90 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$
;


-- ═══ FUNCTION taki_prune_notifications(p_batch integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_prune_notifications(p_batch integer DEFAULT 2000)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int;
BEGIN
  -- 🔴 السقفُ ليس تجميلاً: الجدولُ في نشرِ البثّ الحيّ، فكلُّ صفٍّ محذوفٍ حدثٌ
  --    يُرسَل ويُقيَّم أمام كلّ متّصل. وبالسقف يُصرَّف الركامُ على أيامٍ بلا أثر.
  -- 🪤 والمقروءُ وحده يُحذف عند ٩٠ يوماً؛ وغيرُ المقروء يُمهَل ١٨٠ — فإشعارٌ
  --    لم يره صاحبُه ليس قمامةً، وحذفُه يُخفي عنه ما لم يعلمه قطّ.
  WITH victims AS (
    SELECT id FROM public.notifications
     WHERE (is_read IS TRUE     AND created_at < now() - interval '90 days')
        OR (is_read IS NOT TRUE AND created_at < now() - interval '180 days')
     ORDER BY created_at
     LIMIT GREATEST(1, LEAST(p_batch, 20000))
  )
  DELETE FROM public.notifications n USING victims v WHERE n.id = v.id;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END $function$
;


-- ═══ FUNCTION taki_prune_stock_inbox() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_prune_stock_inbox()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int;
BEGIN
  -- 🪤 سبعةُ أيام تكفي بفارقٍ كبير: أطولُ إعادةٍ موثَّقة عند زد ١٥ دقيقة،
  --    ونافذةُ البصمة خمسُ دقائق. والإبقاءُ أبداً كان يُفقد كمّياتٍ (القسم ٤).
  DELETE FROM public.stock_inbox WHERE received_at < now() - interval '7 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$function$
;


-- ═══ FUNCTION taki_prune_stock_parked() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_prune_stock_parked()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int := 0; v_row record;
BEGIN
  FOR v_row IN
    SELECT id, secret_name FROM public.stock_oauth_parked
     WHERE created_at < now() - interval '30 days'
  LOOP
    -- السرُّ أوّلاً: صفٌّ يُحذف وسرُّه باقٍ يُخلّف توكناً بلا أيّ أثرٍ يقود إليه.
    DELETE FROM vault.secrets WHERE name = v_row.secret_name;
    DELETE FROM public.stock_oauth_parked WHERE id = v_row.id;
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END
$function$
;


-- ═══ FUNCTION taki_prune_stock_queue() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_prune_stock_queue()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int;
BEGIN
  DELETE FROM public.stock_refresh_queue
   WHERE status IN ('done','failed') AND COALESCE(done_at, created_at) < now() - interval '7 days';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$function$
;


-- ═══ FUNCTION taki_prune_wathq_checks() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_prune_wathq_checks()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE n int;
BEGIN
  -- 🪤 تُحفظ سنةً كاملة: الكلفةُ دليلٌ ماليّ، ونافذةُ التأكيد السنويّ سنة.
  DELETE FROM public.store_verification_checks
   WHERE done_at IS NOT NULL AND done_at < now() - interval '400 days';
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$function$
;


-- ═══ FUNCTION taki_publish_block(p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_publish_block(p_store_id text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_t text;
BEGIN
  SELECT user_type INTO v_t FROM public.users WHERE id = p_store_id AND deleted_at IS NULL;
  IF v_t IS NULL OR v_t NOT IN ('seller','admin') THEN RETURN 'not_merchant'; END IF;
  IF v_t = 'admin' THEN RETURN NULL; END IF;                 -- متجر المنصّة
  IF public.taki_verification_mode() <> 'required' THEN RETURN NULL; END IF;
  IF public.taki_store_verified(p_store_id) THEN RETURN NULL; END IF;
  IF public.taki_store_grandfathered(p_store_id) THEN RETURN NULL; END IF;
  RETURN 'not_verified';
END
$function$
;


-- ═══ FUNCTION taki_queue_email(p_user_id text, p_event text, p_subject text, p_html text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_queue_email(p_user_id text, p_event text, p_subject text, p_html text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_email text;
BEGIN
  SELECT email INTO v_email FROM users WHERE id = p_user_id;
  IF v_email IS NULL
     OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+\.[^@[:space:]]+$'
     OR v_email ILIKE '%telegram%' OR v_email ILIKE '%whatsapp%' OR v_email ILIKE '%.local'
  THEN
    RETURN false;
  END IF;
  INSERT INTO email_outbox (user_id, to_email, subject, html, event)
  VALUES (p_user_id, v_email, COALESCE(p_subject,'TAKI'), COALESCE(p_html,''), p_event);
  RETURN true;
END $function$
;


-- ═══ FUNCTION taki_rate_check(p_key text, p_max integer, p_window_secs integer, p_msg text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_rate_check(p_key text, p_max integer, p_window_secs integer, p_msg text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_win  timestamptz;
  v_hits int;
BEGIN
  v_win := to_timestamp(floor(extract(epoch FROM now()) / p_window_secs) * p_window_secs);
  INSERT INTO rate_limit_counters (bucket_key, window_start, hits)
  VALUES (p_key, v_win, 1)
  ON CONFLICT (bucket_key, window_start)
  DO UPDATE SET hits = rate_limit_counters.hits + 1
  RETURNING hits INTO v_hits;
  IF v_hits > p_max THEN
    RAISE EXCEPTION '%', p_msg USING ERRCODE = 'P0001', HINT = 'P0011';
  END IF;
END;
$function$
;


-- ═══ FUNCTION taki_reconcile_all_branch_display() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_reconcile_all_branch_display()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare r record; n integer := 0;
begin
  for r in select distinct merchant_id from public.store_branches loop
    perform public.taki_reconcile_branch_display(r.merchant_id);
    n := n + 1;
  end loop;
  return n;
end $function$
;


-- ═══ FUNCTION taki_reconcile_branch_display(p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_reconcile_branch_display(p_store_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cap integer;
BEGIN
    SELECT max_branches INTO v_cap FROM public.store_profiles WHERE store_id = p_store_id;
    IF v_cap IS NULL OR v_cap <= 0 THEN RETURN; END IF;

    UPDATE public.store_branches b
       SET show_on_store_page = false, updated_at = NOW()
     WHERE b.merchant_id = p_store_id
       AND b.show_on_store_page
       AND b.id NOT IN (
            SELECT x.id FROM public.store_branches x
             WHERE x.merchant_id = p_store_id
               AND x.show_on_store_page
               AND COALESCE(x.is_active, true)
             ORDER BY x.is_primary DESC NULLS LAST, x.created_at ASC
             LIMIT v_cap);
END;
$function$
;


-- ═══ FUNCTION taki_reconcile_location_caps() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_reconcile_location_caps()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s RECORD; r RECORD;
  v_max INT; v_keys TEXT[]; v_union TEXT[];
  v_paused INT := 0; v_n INT;
BEGIN
  FOR s IN
    SELECT sp.store_id, GREATEST(1, sp.max_branches) AS max_b
      FROM store_profiles sp
      JOIN users u ON u.id = sp.store_id
     WHERE sp.max_branches IS NOT NULL
  LOOP
    v_max := s.max_b;

    -- (١) العروض المتجاوزة بذاتها
    UPDATE deals d
       SET status = 'paused', subscription_frozen = TRUE
     WHERE d.store_id = s.store_id
       AND d.status = 'active'
       AND (SELECT count(DISTINCT k)
              FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) > v_max;
    GET DIAGNOSTICS v_n = ROW_COUNT;
    v_paused := v_paused + COALESCE(v_n, 0);

    -- (٢) اتحاد الباقي — نُبقي الأقدم فالأقدم
    v_keys := ARRAY[]::TEXT[];
    FOR r IN
      SELECT d.id,
             ARRAY(SELECT DISTINCT k
                     FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) AS keys
        FROM deals d
       WHERE d.store_id = s.store_id AND d.status = 'active'
       ORDER BY d.created_at ASC NULLS FIRST, d.id ASC
    LOOP
      v_union := (SELECT array_agg(DISTINCT k) FROM unnest(v_keys || r.keys) k);
      IF COALESCE(array_length(v_union, 1), 0) > v_max THEN
        UPDATE deals SET status = 'paused', subscription_frozen = TRUE WHERE id = r.id;
        v_paused := v_paused + 1;
      ELSE
        v_keys := v_union;
      END IF;
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'deals_paused', v_paused);
END $function$
;


-- ═══ FUNCTION taki_recur_campaigns() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_recur_campaigns()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_riyadh timestamp := (NOW() AT TIME ZONE 'Asia/Riyadh');
  v_today  date := v_riyadh::date;
  c record; v_last date; v_due boolean; v_sent int := 0; v_reached int := 0;
BEGIN
  FOR c IN SELECT * FROM promotional_campaigns
           WHERE is_active = true
             AND recurrence <> 'none'
             AND starts_at <= NOW()
             AND (ends_at IS NULL OR ends_at > NOW())
  LOOP
    IF extract(hour FROM v_riyadh)::int <> COALESCE(c.recurrence_hour, 10) THEN CONTINUE; END IF;
    v_last := (c.last_broadcast_at AT TIME ZONE 'Asia/Riyadh')::date;
    v_due := CASE c.recurrence
      WHEN 'daily'        THEN v_last IS NULL OR v_last < v_today
      WHEN 'every_3_days' THEN v_last IS NULL OR (v_today - v_last) >= 3
      WHEN 'weekend'      THEN extract(isodow FROM v_today)::int = 5 AND (v_last IS NULL OR v_last < v_today)
      WHEN 'weekly'       THEN v_last IS NULL OR (v_today - v_last) >= 7
      WHEN 'monthly'      THEN v_last IS NULL OR (v_today - v_last) >= 30
      ELSE false END;
    IF v_due THEN
      v_reached := v_reached + public._broadcast_campaign_core(c.id, true);
      v_sent := v_sent + 1;
    END IF;
  END LOOP;
  RETURN jsonb_build_object('campaigns', v_sent, 'notifications', v_reached);
END;
$function$
;


-- ═══ FUNCTION taki_refund_cap(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_refund_cap(p_barcode text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT round(LEAST(
           COALESCE(NULLIF(b.paid_amount, 0), b.total_amount, 0),
           (SELECT oi.total FROM public.order_invoices oi
             WHERE oi.barcode = b.barcode AND oi.total > 0 LIMIT 1)
         ), 2)
    FROM public.bookings b
   WHERE b.barcode = upper(btrim(p_barcode));
$function$
;


-- ═══ FUNCTION taki_refund_policy() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_refund_policy()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    -- ٠ ساعة = لا نافذة ضمان معلنة (الزرّ يبقى عاملاً). و٧٢٠ = ٣٠ يوماً سقفاً.
    -- 🪤 `jsonb_typeof = 'number'` لا `::numeric` على نصّ: `Number(null)` صفرٌ
    --    صالح في الواجهة، ونظيرُه هنا كان يُحوّل قيمةً تالفة إلى ٠ ساعة بصمت
    --    بدل الارتداد إلى الافتراضي (درس v14.92 في قارئ نسبة الضريبة).
    'hours', GREATEST(0, LEAST(720, COALESCE((
        SELECT floor((value->>'hours')::numeric)::int FROM public.platform_settings
         WHERE key = 'refund_window' AND jsonb_typeof(value->'hours') = 'number'), 2))),
    -- بولياني حقيقيّ وحده يُحسب؛ أيّ شيءٍ آخر يرتدّ إلى الافتراضي (مفتوح).
    'merchant_button', COALESCE((
        SELECT CASE WHEN jsonb_typeof(value->'merchant_button') = 'boolean'
                    THEN (value->>'merchant_button')::boolean END
          FROM public.platform_settings WHERE key = 'refund_window'), true)
  );
$function$
;


-- ═══ FUNCTION taki_refund_remaining(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_refund_remaining(p_barcode text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT GREATEST(
           COALESCE(public.taki_refund_cap(p_barcode), 0)
           - COALESCE((SELECT sum(r.refund_amount) FROM public.booking_refunds r
                        WHERE r.barcode = upper(btrim(p_barcode))
                          AND r.status = 'refunded'), 0),
           0);
$function$
;


-- ═══ FUNCTION taki_render_template(p_tpl text, p_vars jsonb) INVOKER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_render_template(p_tpl text, p_vars jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_out text := COALESCE(p_tpl, ''); v_k text; v_v text;
BEGIN
  FOR v_k, v_v IN SELECT key, value FROM jsonb_each_text(COALESCE(p_vars, '{}'::jsonb)) LOOP
    v_out := replace(v_out, '{' || v_k || '}', COALESCE(v_v, ''));
  END LOOP;
  RETURN v_out;
END $function$
;


-- ═══ FUNCTION taki_restock_booking(p_barcode text, p_qty integer, p_reason text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_restock_booking(p_barcode text, p_qty integer DEFAULT NULL::integer, p_reason text DEFAULT 'refund'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_b        public.bookings%ROWTYPE;
  v_d        public.deals%ROWTYPE;
  v_left     int;
  v_n        int;
  v_variants jsonb;
  v_locs     jsonb;
  v_res      jsonb;
BEGIN
  IF NOT public.taki_is_system_caller() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_b FROM public.bookings WHERE barcode = p_barcode FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;

  -- 🪤 الطلبُ غيرُ المكتمل يعود بمسارِ الإلغاء (`adjust_deal_quantity`) — وهو
  --    مقيسٌ وصحيح على المحاور الأربعة. إرجاعُه هنا **أيضاً** يُضاعف البضاعة.
  IF v_b.status IS DISTINCT FROM 'completed' THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'NOT_COMPLETED', 'status', v_b.status);
  END IF;

  v_left := GREATEST(0, GREATEST(COALESCE(v_b.booked_quantity, 1), 1) - COALESCE(v_b.restocked_qty, 0));
  v_n := LEAST(GREATEST(COALESCE(p_qty, v_left), 0), v_left);
  IF v_n <= 0 THEN
    RETURN jsonb_build_object('ok', true, 'already', true, 'restocked_qty', v_b.restocked_qty);
  END IF;

  -- 🪤 القفلُ على العرض قبل قراءة أرقامه: الإرجاعُ يُحسب من الرقم الحيّ لا من
  --    رقمٍ قُرئ قبل القفل — وإلا دهس نداءان أحدُهما الآخر.
  SELECT * INTO v_d FROM public.deals WHERE id = v_b.deal_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'DEAL_GONE'); END IF;
  IF COALESCE(v_d.is_unlimited, false) OR v_d.on_hand IS NULL THEN
    -- عرضٌ بلا حدّ لا مخزونَ له يُعاد؛ ويُسجَّل الإرجاع كي لا يُعاد النداء.
    UPDATE public.bookings SET restocked_qty = COALESCE(restocked_qty, 0) + v_n WHERE barcode = p_barcode;
    RETURN jsonb_build_object('ok', true, 'skipped', 'UNLIMITED', 'restocked_qty', v_n);
  END IF;

  -- الأصناف المختارة: كلُّ صنفٍ يعود بكمّيته هو (وليس بكمّية الطلب).
  IF v_d.variants IS NOT NULL AND jsonb_typeof(v_d.variants) = 'array'
     AND v_b.selected_options IS NOT NULL AND jsonb_typeof(v_b.selected_options) = 'array' THEN
    SELECT jsonb_agg(jsonb_build_object('id', e->>'id', 'onHand',
             GREATEST(0, COALESCE(NULLIF(e->>'onHand','')::int, 0) + COALESCE(pick.q, 0))))
      INTO v_variants
      FROM jsonb_array_elements(v_d.variants) e
      JOIN LATERAL (
        SELECT sum(GREATEST(COALESCE((s->>'qty')::int, 1), 1))::int AS q
          FROM jsonb_array_elements(v_b.selected_options) s
         WHERE s->>'g' = '__variant__' AND s->>'c' = e->>'id') pick ON pick.q IS NOT NULL
     WHERE (e ? 'onHand');
  END IF;

  -- الفرع: كمّيةُ الطلب، وأصنافُه داخله بكمّياتها.
  IF v_b.location_id IS NOT NULL AND v_d.loc_qty_mode = 'per_location'
     AND v_d.locations IS NOT NULL AND jsonb_typeof(v_d.locations) = 'array' THEN
    SELECT jsonb_agg(jsonb_build_object(
             'id', e->>'id',
             'onHand', GREATEST(0, COALESCE(NULLIF(e->>'onHand','')::int, 0) + v_n),
             'variantOnHand', COALESCE((
                SELECT jsonb_object_agg(vo.key,
                         GREATEST(0, COALESCE(NULLIF(vo.value #>> '{}','')::int, 0)
                                   + COALESCE((SELECT sum(GREATEST(COALESCE((s->>'qty')::int,1),1))::int
                                                 FROM jsonb_array_elements(v_b.selected_options) s
                                                WHERE s->>'g' = '__variant__' AND s->>'c' = vo.key), 0)))
                  FROM jsonb_each(e->'variantOnHand') vo), '{}'::jsonb)))
      INTO v_locs
      FROM jsonb_array_elements(v_d.locations) e
     WHERE e->>'id' = v_b.location_id AND (e ? 'onHand');
  END IF;

  v_res := public.taki_set_on_hand(v_b.deal_id, v_d.on_hand + v_n, v_variants, v_locs, NULL, p_reason);
  -- v15.16 restock — كان يزيد `restocked_qty` بعد تجاوُزٍ صامت، فتضيع
  --   وحداتُ الاسترداد إلى الأبد: المحاولةُ التالية تردّ `already:true`.
  IF COALESCE(v_res->>'skipped', '') <> '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'RESTOCK_NOT_APPLIED',
                              'skipped', v_res->>'skipped', 'detail', v_res);
  END IF;
  IF NOT COALESCE((v_res->>'ok')::boolean, false) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SET_FAILED', 'detail', v_res);
  END IF;

  UPDATE public.bookings SET restocked_qty = COALESCE(restocked_qty, 0) + v_n WHERE barcode = p_barcode;

  RETURN jsonb_build_object('ok', true, 'restocked', v_n,
                            'restocked_qty', COALESCE(v_b.restocked_qty, 0) + v_n,
                            'on_hand', v_res->'on_hand', 'available', v_res->'available');
END
$function$
;


-- ═══ FUNCTION taki_saturation() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_saturation()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'max_conn',   (SELECT setting::int FROM pg_settings WHERE name = 'max_connections'),
    'conn',       (SELECT count(*)::int FROM pg_stat_activity),
    'conn_pct',   (SELECT round(100.0 * count(*) /
                     NULLIF((SELECT setting::numeric FROM pg_settings WHERE name='max_connections'),0))::int
                   FROM pg_stat_activity),
    'active',     (SELECT count(*)::int FROM pg_stat_activity WHERE state = 'active'),
    -- أطول استعلامٍ **يعمل الآن**: استعلامٌ عالق يخنق المسبح قبل أن يمتلئ.
    -- تُستثنى عمليات الصيانة الطويلة المشروعة (autovacuum) وإلا صرخ كل ليلة.
    'longest_ms', COALESCE((SELECT round(EXTRACT(epoch FROM (now() - query_start)) * 1000)::int
                              FROM pg_stat_activity
                             WHERE state = 'active'
                               AND backend_type = 'client backend'
                               AND query NOT ILIKE '%pg_stat_activity%'
                             ORDER BY query_start ASC LIMIT 1), 0),
    'cache_hit',  (SELECT round(100.0 * sum(heap_blks_hit) /
                     NULLIF(sum(heap_blks_hit) + sum(heap_blks_read), 0), 2)
                   FROM pg_statio_user_tables)
  );
$function$
;


-- ═══ FUNCTION taki_scan_text_tr() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_scan_text_tr()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_content text;
  v_source text;
  v_store text;
  v_offender text;
  v_matched text[];
  v_ref text;
BEGIN
  BEGIN
    IF TG_TABLE_NAME = 'booking_messages' THEN
      v_content := NEW.body;
      v_source := 'chat';
      v_offender := NEW.sender_id;
      v_ref := NEW.barcode;
      SELECT b.store_id INTO v_store FROM bookings b WHERE b.barcode = NEW.barcode LIMIT 1;
    ELSIF TG_TABLE_NAME = 'ratings' THEN
      IF TG_OP = 'UPDATE' AND NEW.comment IS NOT DISTINCT FROM OLD.comment THEN RETURN NEW; END IF;
      v_content := NEW.comment;
      v_source := 'rating';
      v_offender := NEW.user_id;
      v_store := NEW.store_id;
      v_ref := NEW.id::text;
    ELSE -- deals
      IF TG_OP = 'UPDATE'
         AND NEW.item_name IS NOT DISTINCT FROM OLD.item_name
         AND NEW.description IS NOT DISTINCT FROM OLD.description THEN RETURN NEW; END IF;
      v_content := coalesce(NEW.item_name,'') || ' — ' || coalesce(NEW.description,'');
      v_source := 'deal';
      v_offender := NEW.store_id;
      v_store := NEW.store_id;
      v_ref := NEW.id::text;
    END IF;

    v_matched := public.taki_match_terms(v_content);
    IF array_length(v_matched, 1) IS NULL THEN RETURN NEW; END IF;

    -- v14.40 — `ref_id`: بلا مرجعٍ للصفّ المخالف لا يستطيع الأدمن فتح المحتوى
    -- ولا إخفاءه — يقرأ النصّ ويبحث عنه يدوياً في المتاجر.
    INSERT INTO moderation_flags (kind, source, ref_id, store_id, offender_id, offender_name, content, matched)
    VALUES ('text', v_source, v_ref, v_store, v_offender,
            (SELECT coalesce(u.shop, u.name) FROM users u WHERE u.id = v_offender),
            left(v_content, 500), v_matched);
  EXCEPTION WHEN OTHERS THEN
    NULL;   -- moderation must never break chat/rating/deal writes
  END;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_season_reminders() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_season_reminders()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_cfg      jsonb;
    v_dates    jsonb;
    v_notified jsonb;
    v_today    date := (now() AT TIME ZONE 'Asia/Riyadh')::date;
    r          RECORD;
    v_days     int;
    v_marker   text;
    v_name     text;
BEGIN
    SELECT value INTO v_cfg FROM platform_settings WHERE key = 'season_event_dates';
    IF v_cfg IS NULL THEN RETURN; END IF;
    v_dates    := COALESCE(v_cfg->'dates', '{}'::jsonb);
    v_notified := COALESCE(v_cfg->'notified', '[]'::jsonb);

    FOR r IN SELECT key AS season_id, value #>> '{}' AS event_date FROM jsonb_each(v_dates)
    LOOP
        CONTINUE WHEN r.event_date IS NULL OR r.event_date = '';
        v_days := (r.event_date::date - v_today);
        -- نافذتا تذكير: شهر قبلها وأسبوع قبلها (تلتقط اليوم التالي لو تعطّل الكرون يوماً)
        IF v_days BETWEEN 28 AND 30 THEN v_marker := r.season_id || ':' || r.event_date || ':30';
        ELSIF v_days BETWEEN 5 AND 7 THEN v_marker := r.season_id || ':' || r.event_date || ':7';
        ELSE CONTINUE;
        END IF;
        CONTINUE WHEN v_notified ? v_marker;

        v_name := CASE r.season_id
            WHEN 'ramadan' THEN 'رمضان' WHEN 'eid' THEN 'العيد'
            WHEN 'founding' THEN 'يوم التأسيس' WHEN 'national' THEN 'اليوم الوطني'
            WHEN 'school' THEN 'العودة للمدارس' WHEN 'white_friday' THEN 'الجمعة البيضاء'
            WHEN 'summer' THEN 'إجازة الصيف' ELSE r.season_id END;

        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        SELECT u.id,
               '⏰ باقي ' || v_days || ' يوماً على ' || v_name,
               '⏰ ' || v_days || ' days until ' || v_name,
               'جهّز حملة الموسم من أدوات الإدارة → هوية المواسم: افتح باب التجار لإضافة منتجاتهم، وحدّد فترة ظهور صفحة العروض للعامة.',
               'Set up the season campaign from Admin Tools → Seasonal identity.',
               'system',
               jsonb_build_object('audience', 'admin', 'season_id', r.season_id, 'event_date', r.event_date),
               NOW()
        FROM users u
        WHERE u.deleted_at IS NULL AND u.user_type = 'admin';

        v_notified := v_notified || to_jsonb(v_marker);
    END LOOP;

    UPDATE platform_settings
       SET value = jsonb_build_object('dates', v_dates, 'notified', v_notified),
           updated_at = NOW()
     WHERE key = 'season_event_dates';
END $function$
;


-- ═══ FUNCTION taki_season_sync_theme() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_season_sync_theme()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  eff text;
  cur text;
BEGIN
  eff := public.taki_season_theme_effective();
  SELECT COALESCE(value #>> '{}', '') INTO cur
    FROM platform_settings WHERE key = 'seasonal_theme';
  IF cur IS DISTINCT FROM eff THEN
    INSERT INTO platform_settings (key, value, description, updated_at)
    VALUES ('seasonal_theme', to_jsonb(eff),
            'Auto-derived from season_campaign public window (v12.57)', now())
    ON CONFLICT (key) DO UPDATE
      SET value = EXCLUDED.value,
          description = EXCLUDED.description,
          updated_at = EXCLUDED.updated_at;
  END IF;
END;
$function$
;


-- ═══ FUNCTION taki_season_theme_effective() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_season_theme_effective()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT COALESCE((
    SELECT CASE
      WHEN COALESCE(value->>'season_id','') <> ''
       AND COALESCE(value->>'public_from','') <> ''
       AND COALESCE(value->>'public_to','') <> ''
       AND (now() AT TIME ZONE 'Asia/Riyadh')::date
           BETWEEN (value->>'public_from')::date AND (value->>'public_to')::date
      THEN value->>'season_id'
      ELSE ''
    END
    FROM platform_settings WHERE key = 'season_campaign'
  ), '');
$function$
;


-- ═══ FUNCTION taki_self_close_minutes() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_self_close_minutes()
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
  SELECT GREATEST(0, LEAST(1440, COALESCE(
    (SELECT NULLIF(value->>'self_close_minutes','')::numeric
       FROM public.platform_settings WHERE key = 'booking_holds' LIMIT 1),
    10)));
$function$
;


-- ═══ FUNCTION taki_self_close_opens_at(p_booking bookings) INVOKER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_self_close_opens_at(p_booking bookings)
 RETURNS bigint
 LANGUAGE sql
 STABLE
 SET search_path TO 'public'
AS $function$
  -- 🔴 والسقفُ الخارجيّ ليس تجميلاً: بلا `LEAST` كان فرعُ «أُكِّد» ينفجر.
  --    مهلةُ ١٥ دقيقة (أرضيّةُ v15.43) + تأكيدٌ بعد ٦ ⇒ فتحةٌ عند +١٦ ومهلةٌ
  --    تنتهي عند +١٥ ⇒ **نافذةٌ خالية**، ثمّ يُلغى الطلب. وقِيس أن ٩٫١٪ من
  --    التأكيدات تقع بعد خمس دقائق — فليست حالةً نادرة. ومثلُه أدمنيّاً:
  --    `self_close_minutes` يقبل حتى ١٤٤٠ دقيقة، فرقمٌ كبير كان يُقفل الميزةَ
  --    على المنصّة كلّها بلا أن يقول أحدٌ شيئاً.
  -- ⇒ الزرُّ يُفتح دائماً قبل انتهاء المهلة بدقيقةٍ على الأقلّ، ولا يُفتح
  --   أبداً قبل مهلةِ الختم من لحظة الحجز.
  -- 🔴 v15.46 — صفرٌ يعني «بلا مهلة» لا «بلا إزاحة».
  --    بدون هذا السطر كان `ms = 0` يجعل الفرعَ الاحتياطيّ
  --    `GREATEST(booked+0, expiry-0)` = `expiry`، ثمّ يقصّه السقفُ إلى
  --    `expiry − دقيقة` — أي أن **ضبطَ المهلة على صفر يُنتج أطولَ انتظارٍ
  --    ممكن**، عكسَ ما يقرؤه المدير تماماً. وتوأماه في الموقع والبوت يُرجعان
  --    «مفتوح» عند الصفر، فكانت الشاشةُ تعرض الزرَّ والخادمُ يرفضه.
  SELECT CASE WHEN public.taki_self_close_minutes() <= 0
              THEN COALESCE(p_booking.booked_at, 0)
  ELSE LEAST(
    -- 🔴 v15.46 — واللحظةُ **لا ترجع إلى الوراء أبداً**: كانت الصيغةُ تختار
    --    مرساةَ التأكيد إن وُجدت، فتاجرٌ يؤكّد متأخّراً (بعد أن فتحت الفتحةُ
    --    الاحتياطيّة) كان **يسحب من المشتري زرّاً صار في يده**: يراه عند
    --    ١:٥٠ ثم يختفي عند ١:٥٥ لأن التاجر ضغط «تأكيد الاستلام». ⇒ تُؤخذ
    --    **الأسبقُ** من المرساتين، فالتأكيدُ يُعجّل الفتحَ ولا يؤجّله أبداً.
    LEAST(
      CASE
        WHEN p_booking.acknowledged_at IS NOT NULL
          THEN GREATEST(COALESCE(p_booking.booked_at, 0) + v.ms,
                        (EXTRACT(EPOCH FROM p_booking.acknowledged_at)*1000)::bigint + v.ms)
        WHEN p_booking.status = 'acknowledged'      -- صفٌّ أُكِّد قبل v15.44
          THEN COALESCE(p_booking.booked_at, 0) + v.ms
        ELSE 9223372036854775807
      END,
      GREATEST(COALESCE(p_booking.booked_at, 0) + v.ms,
               COALESCE(NULLIF(p_booking.expiry_time, 0), 9223372036854775807) - v.ms)
    ),
    COALESCE(NULLIF(p_booking.expiry_time, 0), 9223372036854775807) - 60000) END
  FROM (SELECT (public.taki_self_close_minutes() * 60000)::bigint AS ms) v;
$function$
;


-- ═══ FUNCTION taki_set_on_hand(p_deal_id text, p_on_hand integer, p_variants jsonb, p_locations jsonb, p_observed_at timestamp with time zone, p_source text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_set_on_hand(p_deal_id text, p_on_hand integer DEFAULT NULL::integer, p_variants jsonb DEFAULT NULL::jsonb, p_locations jsonb DEFAULT NULL::jsonb, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_source text DEFAULT 'merchant'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_d  public.deals%ROWTYPE;
  -- v15.16 clamp2 — ساعةُ نظام التاجر لا تُصدَّق بلا سقف: فرقُ ٣ ساعات
  --                (توقيت الرياض كأنّه UTC) كان يُجمّد كلّ كتابةٍ بعدها.
  v_at timestamptz := LEAST(COALESCE(p_observed_at, now()), now());
  v_h  int;
  v_new jsonb;
  v_out jsonb;
BEGIN
  -- ── كلُّ المخارج المبكّرة قبل رفع الراية ────────────────────────────────
  IF p_deal_id IS NULL OR btrim(p_deal_id) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'DEAL_REQUIRED');
  END IF;
  IF p_on_hand IS NOT NULL AND p_on_hand < 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NEGATIVE');
  END IF;

  -- 🪤 القفل قبل أيّ قراءة: بلا `FOR UPDATE` يقرأ نداءان نفسَ المحجوز فيكتب
  --    أحدهما فوق الآخر، ويصير المتاح أكبر ممّا يجب — أي بيعٌ لِما لا يوجد.
  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;

  -- عرضٌ بلا حدّ لا كاملَ له — وصفرٌ فيه يعني «نفد».
  IF COALESCE(v_d.is_unlimited, false) THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'UNLIMITED');
  END IF;

  -- الملاحظةُ الأقدم تُهمَل — وليست خطأً: الشبكةُ تُعيد الترتيب أحياناً،
  -- فالأحدثُ **ملاحظةً** يفوز لا الأحدثُ وصولاً.
  IF v_d.stock_observed_at IS NOT NULL AND v_at < v_d.stock_observed_at THEN
    RETURN jsonb_build_object('ok', true, 'skipped', 'STALE_OBSERVATION',
                              'stored_at', v_d.stock_observed_at, 'incoming', v_at);
  END IF;

  -- ── من هنا نكتب: تُرفع الراية، وتُطفأ عند المخرج الوحيد ────────────────
  PERFORM set_config('taki.stock_derived', '1', true);

  IF p_on_hand IS NOT NULL THEN
    v_h := public.taki_open_holds(p_deal_id, NULL, NULL);
    -- 🪤 ولا يُنقص المحجوز أبداً: لو قال التاجر «عندي ٢» وعنده ٥ محجوزة،
    --    فالمتاح صفرٌ والحجوزاتُ الخمس تبقى — فبضاعةٌ وُعد بها مشترٍ لا
    --    تُسحب منه برقمٍ كُتب بعده.
    UPDATE public.deals
       SET on_hand = p_on_hand, quantity = GREATEST(0, p_on_hand - v_h)
     WHERE id = p_deal_id;
  END IF;

  IF p_variants IS NOT NULL AND jsonb_typeof(p_variants) = 'array'
     AND v_d.variants IS NOT NULL AND jsonb_typeof(v_d.variants) = 'array' THEN
    SELECT jsonb_agg(
             CASE WHEN inc.oh IS NULL THEN t.e
                  ELSE jsonb_set(jsonb_set(t.e, '{onHand}', to_jsonb(GREATEST(0, inc.oh))),
                                 '{qty}', to_jsonb(GREATEST(0,
                                   inc.oh - public.taki_open_holds(p_deal_id, t.e->>'id', NULL))))
             END ORDER BY t.ord)
      INTO v_new
      FROM jsonb_array_elements(v_d.variants) WITH ORDINALITY AS t(e, ord)
      LEFT JOIN LATERAL (
        SELECT NULLIF(x->>'onHand','')::int AS oh
          FROM jsonb_array_elements(p_variants) x
         WHERE x->>'id' = t.e->>'id' LIMIT 1) inc ON true;
    IF v_new IS NOT NULL THEN
      UPDATE public.deals SET variants = v_new WHERE id = p_deal_id;
    END IF;
  END IF;

  IF p_locations IS NOT NULL AND jsonb_typeof(p_locations) = 'array'
     AND v_d.locations IS NOT NULL AND jsonb_typeof(v_d.locations) = 'array' THEN
    SELECT jsonb_agg(public._taki_loc_on_hand(p_deal_id, t.e, inc.x) ORDER BY t.ord)
      INTO v_new
      FROM jsonb_array_elements(v_d.locations) WITH ORDINALITY AS t(e, ord)
      LEFT JOIN LATERAL (
        SELECT y AS x FROM jsonb_array_elements(p_locations) y
         WHERE y->>'id' = t.e->>'id' LIMIT 1) inc ON true;
    IF v_new IS NOT NULL THEN
      UPDATE public.deals SET locations = v_new WHERE id = p_deal_id;
    END IF;
  END IF;

  UPDATE public.deals SET stock_observed_at = CASE WHEN p_observed_at IS NULL THEN stock_observed_at ELSE v_at END, stock_source = p_source
   WHERE id = p_deal_id;

  SELECT * INTO v_d FROM public.deals WHERE id = p_deal_id;
  v_out := jsonb_build_object('ok', true, 'on_hand', v_d.on_hand,
                              'holds', public.taki_open_holds(p_deal_id, NULL, NULL),
                              'available', v_d.quantity,
                              'variants', v_d.variants, 'locations', v_d.locations);

  -- 🔴 المخرجُ الوحيد بعد أيّ كتابة — وإطفاءُ الراية شرطُ صحّة لا تنظيف.
  -- v15.08: كلُّ إعلانٍ أو مزامنةٍ أو إرجاعٍ يصير حدثاً لنظام التاجر
  PERFORM public._taki_stock_event(p_deal_id, NULL, NULL, p_source, NULL, v_d.on_hand, NULL);
  PERFORM set_config('taki.stock_derived', '0', true);
  RETURN v_out;
END
$function$
;


-- ═══ FUNCTION taki_set_store_card(p_uid text, p_bio text, p_avatar_url text, p_address text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_set_store_card(p_uid text, p_bio text DEFAULT NULL::text, p_avatar_url text DEFAULT NULL::text, p_address text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_bio    text;
  v_avatar text;
  v_addr   text;
BEGIN
  IF p_uid IS NULL THEN RETURN NULL; END IF;

  v_bio    := CASE WHEN p_bio        IS NULL THEN NULL ELSE nullif(left(btrim(p_bio), 500), '') END;
  v_avatar := CASE WHEN p_avatar_url IS NULL THEN NULL ELSE nullif(btrim(p_avatar_url), '') END;
  v_addr   := CASE WHEN p_address    IS NULL THEN NULL ELSE nullif(left(btrim(p_address), 300), '') END;

  INSERT INTO public.store_profiles (store_id, bio, avatar_url, address, updated_at)
  VALUES (p_uid,
          CASE WHEN p_bio        IS NULL THEN NULL ELSE v_bio    END,
          CASE WHEN p_avatar_url IS NULL THEN NULL ELSE v_avatar END,
          CASE WHEN p_address    IS NULL THEN NULL ELSE v_addr   END,
          now())
  ON CONFLICT (store_id) DO UPDATE SET
    bio        = CASE WHEN p_bio        IS NULL THEN public.store_profiles.bio        ELSE v_bio    END,
    avatar_url = CASE WHEN p_avatar_url IS NULL THEN public.store_profiles.avatar_url ELSE v_avatar END,
    address    = CASE WHEN p_address    IS NULL THEN public.store_profiles.address    ELSE v_addr   END,
    updated_at = now();

  UPDATE public.users SET
    bio        = CASE WHEN p_bio        IS NULL THEN bio        ELSE v_bio    END,
    avatar_url = CASE WHEN p_avatar_url IS NULL THEN avatar_url ELSE v_avatar END,
    address    = CASE WHEN p_address    IS NULL THEN address    ELSE v_addr   END,
    updated_at = now()
  WHERE id = p_uid;

  RETURN (SELECT jsonb_build_object('bio', u.bio, 'avatar_url', u.avatar_url, 'address', u.address)
            FROM public.users u WHERE u.id = p_uid);
END $function$
;


-- ═══ FUNCTION taki_setting_is_protected(p_key text) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_setting_is_protected(p_key text)
 RETURNS boolean
 LANGUAGE sql
 STABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT p_key = ANY (ARRAY[
    -- الدفع والبوّابات
    'payment_gateway_enabled', 'payment_gateway_provider',
    'payment_gateway_publishable_key', 'payment_gateway_webhook_url',
    'payment_publishable_key', 'enabled_pay_providers', 'direct_pay_enabled',
    -- الضريبة
    'tax_settings', 'merchant_vat',
    -- التسعير والباقات
    'basic_plan_price_sar', 'extra_branch_fee_sar', 'trial_days',
    'trial_warning_days_before', 'included_branches', 'default_package_id',
    'location_packages',
    -- الشراء داخل التطبيق
    'iap_products', 'iap_allow_sandbox',
    -- مفتاحُ دفعِ الإشعارات العامّ (تبديلُه يُسكت كلَّ الإشعارات)
    'consent_gate_enabled', 'vapid_public_key'
  ]::text[]);
$function$
;


-- ═══ FUNCTION taki_settle_booking_refund(p_barcode text, p_ok boolean, p_refund_ref text, p_reason text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_settle_booking_refund(p_barcode text, p_ok boolean, p_refund_ref text DEFAULT NULL::text, p_reason text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_restocked boolean := false;
  v_b         public.bookings%ROWTYPE;
  v_amt       numeric;
  v_seq       integer;
  v_cn        text;
  v_shop      text;
  v_money     text;
  v_cancelled boolean := false;
  v_rows      integer;
  v_ref       text := NULLIF(left(btrim(COALESCE(p_refund_ref, '')), 120), '');
  v_reason    text := NULLIF(left(btrim(COALESCE(p_reason, '')), 600), '');
BEGIN
  -- خدمةٌ وحدها. لا تاجر ولا أدمن: من يختم يجب أن يكون قد رأى ردّ المزوّد.
  IF NOT public.taki_is_system_caller() THEN
    RETURN jsonb_build_object('ok', false, 'error', 'FORBIDDEN');
  END IF;
  IF p_barcode IS NULL OR btrim(p_barcode) = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BARCODE_REQUIRED');
  END IF;

  SELECT * INTO v_b FROM public.bookings
   WHERE barcode = upper(btrim(p_barcode))
   FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;

  -- خاملةُ التكرار: إعادةُ إرسالٍ من الشبكة بعد ختمٍ ناجح لا تُصدر إشعاراً
  -- دائناً ثانياً ولا تحرق رقماً من سلسلة التاجر (درس v14.21).
  IF v_b.refund_state = 'refunded' THEN
    RETURN jsonb_build_object('ok', true, 'already', true, 'state', 'refunded',
                              'ref', v_b.refund_ref, 'refunded_at', v_b.refunded_at);
  END IF;
  IF v_b.refund_state IS DISTINCT FROM 'claiming' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_CLAIMING',
                              'state', v_b.refund_state);
  END IF;

  -- ── فشلٌ عند المزوّد: يُطلَق سراحُ القفل ويبقى سببُه ظاهراً للتاجر ───────
  IF NOT COALESCE(p_ok, false) THEN
    UPDATE public.bookings
       SET refund_state  = 'failed',
           refund_reason = COALESCE(v_reason, refund_reason)
     WHERE barcode = v_b.barcode;
    RETURN jsonb_build_object('ok', true, 'state', 'failed', 'reason', v_reason);
  END IF;

  -- ── نجاح: المال خرج فعلاً من حساب التاجر ────────────────────────────────
  v_amt := round(COALESCE(NULLIF(v_b.refund_amount, 0),
                          NULLIF(v_b.paid_amount, 0), v_b.total_amount, 0), 2);
  IF NOT (v_amt > 0) THEN RETURN jsonb_build_object('ok', false, 'error', 'ZERO_AMOUNT'); END IF;

  SELECT COALESCE(NULLIF(u.shop, ''), u.name) INTO v_shop
    FROM public.users u WHERE u.id = v_b.store_id;

  -- إشعارٌ دائن بسلسلةٍ مستقلّة لكلّ تاجر — ذرّيّ وبلا فجوات (v14.17).
  -- 🪤 ولا يُسحب رقمٌ جديد إن كان للطلب إشعارٌ دائن من قبل: السلسلة الضريبية
  --    لا تحتمل فجوة، وسحبُ رقمٍ ثمّ إهمالُه فجوةٌ دائمة (درس v14.21).
  SELECT credit_note_no INTO v_cn
    FROM public.booking_refunds WHERE barcode = v_b.barcode FOR UPDATE;
  IF v_cn IS NULL THEN
    INSERT INTO public.store_invoice_counters (store_id, last_credit_seq)
    VALUES (v_b.store_id, 1)
    ON CONFLICT (store_id) DO UPDATE
      SET last_credit_seq = public.store_invoice_counters.last_credit_seq + 1,
          updated_at = now()
    RETURNING last_credit_seq INTO v_seq;
    v_cn := 'CN-' || lpad(v_seq::text, 6, '0');
  END IF;

  -- صفّ `booking_refunds` هو ما تقرؤه الفاتورةُ والبوتان، فيُكتب هنا أيضاً —
  -- سواءٌ فُتح بطلبٍ من المشتري أو لم يُفتح قطّ (ردٌّ بمبادرة التاجر).
  INSERT INTO public.booking_refunds
    (barcode, store_id, buyer_id, status, opened_by, amount, merchant_note,
     decided_at, decided_by, refunded_at, refund_amount, refund_ref, refund_method,
     credit_note_no, updated_at)
  VALUES
    (v_b.barcode, v_b.store_id, v_b.user_id, 'refunded', 'seller', v_amt, v_reason,
     now(), v_b.store_id, now(), v_amt, v_ref, 'gateway', v_cn, now())
  ON CONFLICT (barcode) DO UPDATE
    SET status         = 'refunded',
        decided_at     = COALESCE(public.booking_refunds.decided_at, now()),
        merchant_note  = COALESCE(EXCLUDED.merchant_note, public.booking_refunds.merchant_note),
        refunded_at    = now(),
        refund_amount  = EXCLUDED.refund_amount,
        refund_ref     = EXCLUDED.refund_ref,
        refund_method  = 'gateway',
        credit_note_no = COALESCE(public.booking_refunds.credit_note_no, EXCLUDED.credit_note_no),
        updated_at     = now()
  RETURNING credit_note_no INTO v_cn;

  UPDATE public.bookings
     SET refund_state = 'refunded',
         refunded_at  = now(),
         refund_ref   = v_ref,
         refund_amount = v_amt
   WHERE barcode = v_b.barcode;

  -- v15.06 (طلب ناصر) بدّلت قاعدة v14.21: المفتوحُ يُلغى وتعود كمّيته،
  -- والمكتملُ تعود بضاعته بـtaki_restock_booking ما لم يُطفئه التاجر.
  IF v_b.status IN ('pending', 'acknowledged') THEN
    UPDATE public.bookings SET status = 'cancelled', cancelled_by = 'refund'
     WHERE barcode = v_b.barcode;
  -- v15.06 (طلب ناصر): والمكتملُ تعود بضاعته كذلك — ما لم يُطفئه التاجر.
  -- 🪤 ولا يُنقل إلى «ملغى»: guard_booking_status يُعيد الحالة صامتاً،
  --    والفاتورة الضريبية المجمّدة تتّكئ على نهائيّتها. الإرجاعُ حدثٌ مستقلّ.
  -- v15.09 — جوابُ التاجر لهذا الردّ أوّلاً، ثمّ المقترَح من ملفّ متجره.
  --           لأن الجواب واقعةُ طلبٍ لا سياسةُ متجر: نفسُ التاجر يستعيد
  --           قطعةً اليوم ويهدي معيبةً غداً ويردّ المال في الحالتين.
  ELSIF v_b.status = 'completed'
        AND COALESCE(v_b.refund_restock, true) THEN
    -- 🔴 ولا تُقرأ نتيجتُه بـGET DIAGNOSTICS: بعد `PERFORM func()` تُرجع
    --    ١ دائماً، فكانت الرسالةُ تقول «أُلغي الطلب» لطلبٍ مكتملٍ لم يُلغَ.
    v_restocked := COALESCE((public.taki_restock_booking(v_b.barcode, NULL, 'refund')->>'ok')::boolean, false);
  END IF;

  v_money := trim(to_char(v_amt, 'FM999999990.09'));

  PERFORM public._refund_notify(v_b.user_id,
    '✅ رُدّ المبلغ إلى بطاقتك', 'Your refund has been issued',
    'ردّ «' || COALESCE(v_shop, 'المتجر') || '» ' || v_money || ' ر.س عن الطلب ' || v_b.barcode
      || COALESCE(' — المرجع: ' || v_ref, '')
      || '. إشعار دائن رقم ' || v_cn || ' على فاتورتك. '
      || 'المبلغ غادر حساب التاجر الآن، ومدّة وصوله إلى بطاقتك تحدّدها جهة الدفع لا تاكي.',
    '"' || COALESCE(v_shop, 'The store') || '" refunded ' || v_money || ' SAR for order ' || v_b.barcode
      || COALESCE(' — reference: ' || v_ref, '')
      || '. Credit note ' || v_cn || ' is on your invoice. '
      || 'The time it takes to reach your card is set by the payment provider, not TAKI.',
    v_b.barcode, 'buyer', 'refund_done');

  PERFORM public._refund_notify(v_b.store_id,
    '✅ نُفِّذ ردّ المبلغ', 'Refund executed',
    'نُفِّذ ردّ ' || v_money || ' ر.س عن الطلب ' || v_b.barcode || ' عبر بوّابتك، بإشعار دائن ' || v_cn || '. '
      || CASE WHEN v_cancelled THEN 'وأُلغي الطلب وعادت الكمّية للبيع.'
              WHEN v_restocked THEN 'والطلب مكتملٌ، وعادت كمّيته إلى مخزونك كما اخترت.'
              ELSE 'والطلب مكتملٌ، ولم تعُد كمّيته إلى المخزون كما اخترت.' END,
    'A refund of ' || v_money || ' SAR for order ' || v_b.barcode
      || ' was executed through your gateway as credit note ' || v_cn || '. '
      || CASE WHEN v_cancelled THEN 'The order was cancelled and the stock returned.'
              ELSE 'The order was already closed, so the stock did not return.' END,
    v_b.barcode, 'seller', 'refund_done');

  RETURN jsonb_build_object('ok', true, 'state', 'refunded', 'amount', v_amt,
                            'credit_note_no', v_cn, 'ref', v_ref,
                            'order_cancelled', v_cancelled);
END
$function$
;


-- ═══ FUNCTION taki_stock_inbound_guard(p_key text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_inbound_guard(p_key text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_i public.stock_integrations%ROWTYPE; v_hash text;
BEGIN
  IF p_key IS NULL OR length(btrim(p_key)) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_KEY');
  END IF;
  v_hash := encode(extensions.digest(btrim(p_key), 'sha256'), 'hex');
  SELECT * INTO v_i FROM public.stock_integrations
   WHERE (api_key_hash = v_hash OR webhook_slug = btrim(p_key))
     AND is_enabled AND direction IN ('in','both');
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'UNKNOWN_KEY'); END IF;
  RETURN jsonb_build_object('ok', true, 'provider', lower(v_i.provider),
    'secret', NULLIF(btrim(COALESCE(v_i.inbound_secret, '')), ''));
END
$function$
;


-- ═══ FUNCTION taki_stock_oauth_bind_salla(p_remote_id text, p_tok jsonb) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_oauth_bind_salla(p_remote_id text, p_tok jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid; v_n int; v_park bigint; v_name text;
BEGIN
  IF p_tok IS NULL OR COALESCE(btrim(p_tok->>'access_token'),'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NO_ACCESS_TOKEN');
  END IF;

  -- (أ) المطابقةُ الوحيدةُ المقبولة: متجرٌ ربط قبلاً بنفس الرقم (إعادةُ تفويضٍ
  --     أو تجديد). وهي **إثباتٌ** لأنّ الرقمَ كُتب في ربطٍ سابقٍ تمّ فعلاً.
  SELECT id INTO v_id FROM public.stock_integrations
   WHERE lower(provider) = 'salla'
     AND COALESCE(oauth_remote_id,'') = COALESCE(btrim(p_remote_id),'~')
   LIMIT 1;

  IF v_id IS NOT NULL THEN
    RETURN public.taki_stock_oauth_store(v_id, p_tok, p_remote_id)
           || jsonb_build_object('matched_by', 'remote_id');
  END IF;

  -- 🔴 v15.80 ④ — وحُذف فرعُ «نافذةٌ مفتوحةٌ واحدة». كان يَربط توكناً مجهولَ
  --    النسبة بمن له نافذة، فيُبقي مهاجمٌ نافذتَه مفتوحةً ويحصد تثبيتَ الضحيّة.
  --    و«واحدةٌ فقط» ليست إثباتاً: المهاجمُ يملك أن يكون الوحيد.
  --    (ويبقى العددُ محسوباً لأنه يُقال للمُطالب في `open_claims`.)
  SELECT count(*) INTO v_n FROM public.stock_integrations
   WHERE lower(provider) = 'salla' AND connect_nonce IS NOT NULL
     AND oauth_attempt_at > now() - interval '30 minutes';

  -- (ب) تُحفظ جانباً. وتخمينُ متجرٍ يعني تسليمَ توكنِ تاجرٍ لتاجرٍ آخر — وهو
  --     أسوأُ ما يمكن أن يحدث في هذا الملفّ كلِّه.
  v_name := 'stock_park:' || encode(extensions.gen_random_bytes(12), 'hex');
  PERFORM vault.create_secret(p_tok::text, v_name, 'TAKI parked stock OAuth token (v15.18)');
  INSERT INTO public.stock_oauth_parked (provider, remote_id, secret_name)
  VALUES ('salla', NULLIF(btrim(COALESCE(p_remote_id,'')),''), v_name)
  RETURNING id INTO v_park;
  RETURN jsonb_build_object('ok', false, 'error', 'PARKED_AWAITING_CLAIM',
    'parked', v_park, 'open_claims', COALESCE(v_n, 0));
END
$function$
;


-- ═══ FUNCTION taki_stock_oauth_job_secret() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_oauth_job_secret()
 RETURNS jsonb
 LANGUAGE sql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object('secret',
    (SELECT value FROM public.app_secrets WHERE key = 'stock_oauth_secret'));
$function$
;


-- ═══ FUNCTION taki_stock_oauth_resolve_state(p_state text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_oauth_resolve_state(p_state text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid; v_nonce text; v_i public.stock_integrations%ROWTYPE; v_app jsonb;
BEGIN
  IF p_state IS NULL OR position(':' IN p_state) = 0 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_STATE');
  END IF;
  BEGIN
    v_id := split_part(p_state, ':', 1)::uuid;
  EXCEPTION WHEN OTHERS THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_STATE');
  END;
  v_nonce := split_part(p_state, ':', 2);
  SELECT * INTO v_i FROM public.stock_integrations WHERE id = v_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NO_INTEGRATION'); END IF;
  -- 🪤 ويُقارن النونس بطولٍ ثابت لا بـ`=` على نصٍّ فارغ: اتصالٌ بلا نونس
  --    (لم يُطلب ربطُه) كان سيُطابق `state` بنونسٍ فارغ.
  IF COALESCE(v_i.connect_nonce, '') = '' OR length(v_nonce) <> 32
     OR v_i.connect_nonce <> v_nonce THEN
    RETURN jsonb_build_object('ok', false, 'error', 'STATE_MISMATCH');
  END IF;
  IF v_i.oauth_attempt_at IS NULL OR v_i.oauth_attempt_at < now() - interval '30 minutes' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'WINDOW_EXPIRED');
  END IF;
  v_app := public._taki_stock_app(v_i.provider);
  IF v_app IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'APP_NOT_REGISTERED'); END IF;
  RETURN jsonb_build_object('ok', true, 'integration_id', v_i.id, 'provider', v_i.provider,
    'client_id', v_app->>'client_id', 'client_secret', v_app->>'client_secret',
    'redirect_uri', v_app->>'redirect_uri');
END
$function$
;


-- ═══ FUNCTION taki_stock_oauth_revoke(p_provider text, p_remote_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_oauth_revoke(p_provider text, p_remote_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id uuid;
BEGIN
  SELECT id INTO v_id FROM public.stock_integrations
   WHERE lower(provider) = lower(COALESCE(p_provider,''))
     AND COALESCE(oauth_remote_id,'') = COALESCE(btrim(p_remote_id),'~');
  IF v_id IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  DELETE FROM vault.secrets WHERE name = 'stock_tok:' || v_id::text;
  UPDATE public.stock_integrations
     SET oauth_state = NULL, oauth_expires_at = NULL, connect_nonce = NULL,
         last_note = 'UNINSTALLED_AT_PROVIDER'
   WHERE id = v_id;
  -- 🪤 ولا يُطفأ الاتصالُ نفسه: التاجر قد يُعيد التثبيت، وإطفاءُ الاتصال
  --    يمحو روابطَ منتجاته التي ربطها بيده.
  RETURN jsonb_build_object('ok', true, 'integration_id', v_id);
END
$function$
;


-- ═══ FUNCTION taki_stock_oauth_store(p_id uuid, p_tok jsonb, p_remote_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_oauth_store(p_id uuid, p_tok jsonb, p_remote_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_i public.stock_integrations%ROWTYPE; v_exp timestamptz;
BEGIN
  SELECT * INTO v_i FROM public.stock_integrations WHERE id = p_id;
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NO_INTEGRATION'); END IF;
  IF p_tok IS NULL OR COALESCE(btrim(p_tok->>'access_token'), '') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'NO_ACCESS_TOKEN');
  END IF;
  -- 🔴 الكتابةُ تُثبَت بقراءة: `vault.update_secret` على مؤشّرٍ ميت تكتب صفرَ
  --    صفوفٍ **بلا استثناء** — فحفظٌ بلا قراءةٍ بعده وهمٌ (درسُ v14.44).
  IF NOT public._taki_stock_token_set(p_id, p_tok) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SECRET_WRITE_FAILED');
  END IF;
  v_exp := public._taki_stock_token_expiry(p_tok);
  UPDATE public.stock_integrations
     SET oauth_expires_at = v_exp,
         -- v15.19 renew — على ساعة **رمز التحديث** لا ساعة التوكن.
         oauth_renew_at   = public._taki_stock_renew_at(v_i.provider, p_tok),
         oauth_scope      = NULLIF(btrim(COALESCE(p_tok->>'scope','')), ''),
         oauth_remote_id  = COALESCE(NULLIF(btrim(COALESCE(p_remote_id,'')), ''), oauth_remote_id),
         oauth_state      = 'idle',
         oauth_req_id     = NULL,
         connect_nonce    = NULL,
         last_note        = 'CONNECTED'
   WHERE id = p_id;
  -- وأوّلُ مزامنةٍ فوراً: ربطٌ لا يُظهر رقماً صحيحاً بعده يبدو معطوباً.
  PERFORM public._taki_stock_enqueue(p_id, NULL, 'connect', NULL, 0);
  RETURN jsonb_build_object('ok', true, 'expires_at', v_exp);
END
$function$
;


-- ═══ FUNCTION taki_stock_push(p_key text, p_items jsonb, p_observed_at timestamp with time zone, p_event_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_stock_push(p_key text, p_items jsonb, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_event_id text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_hash text; v_id uuid;
BEGIN
  IF p_key IS NULL OR length(btrim(p_key)) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_KEY');
  END IF;
  v_hash := encode(extensions.digest(btrim(p_key), 'sha256'), 'hex');

  -- v15.79 — التعرّفُ أوّلاً، كما في `taki_stock_webhook`.
  SELECT id INTO v_id FROM public.stock_integrations
   WHERE api_key_hash = v_hash AND is_enabled AND direction IN ('in','both');

  IF v_id IS NULL THEN
    -- 🔴 دلوٌ **واحدٌ مشتركٌ** لكلّ المفاتيح المجهولة: عددُ الصفوف لا ينمو
    --    بمدخلات المهاجم أبداً، صفٌّ واحدٌ لكلّ نافذة.
    -- 🪤 ولا يُرفع استثناءٌ هنا مهما تجاوز: `taki_stock_webhook` تنادي هذه
    --    الدالّةَ **بلا معالج**، وخطأٌ منها يصير ٥٠٢ عند الحافة — و٥٠٢
    --    تُحسب فشلاً عند زد (٣٠ في ساعةٍ ⇒ تعطيلُ الخطّاف وإلغاءُ أحداثه
    --    المعلّقة). فالردُّ يبقى `UNKNOWN_KEY` حرفياً كما كان، والدلوُ
    --    للرصد وتثبيتِ عدد الصفوف لا للرفض.
    BEGIN
      PERFORM public.taki_rate_check('stockpush:unknown', 600, 60, 'unknown stock key flood');
    EXCEPTION WHEN OTHERS THEN NULL;
    END;
    RETURN jsonb_build_object('ok', false, 'error', 'UNKNOWN_KEY');
  END IF;

  -- والمفتاحُ صار **معرّفَ الاتصال** لا بصمةَ السرّ: فسببُ v15.20 («لا
  -- يُسجَّل سرٌّ في `rate_limit_counters`») متحقّقٌ بالبناء لا بالتعمية.
  PERFORM public.taki_rate_check('stockpush:' || v_id::text, 120, 60,
                                 'too many stock pushes — slow down');
  RETURN public._taki_stock_apply(v_id, p_items, p_observed_at, p_event_id);
END
$function$
;


-- ═══ FUNCTION taki_stock_refresh_collect(p_cap integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_refresh_collect(p_cap integer DEFAULT 300)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row record; v_resp record; v_body jsonb; v_p jsonb; v_ap jsonb;
  v_ok int := 0; v_none int := 0; v_retry int := 0; v_dead int := 0; v_wait int := 0;
  MAX_TRIES constant int := 8;
BEGIN
  FOR v_row IN
    SELECT q.*, i.provider, l.location_id
      FROM public.stock_refresh_queue q
      JOIN public.stock_integrations i ON i.id = q.integration_id
      LEFT JOIN public.stock_links l
             ON l.integration_id = q.integration_id AND l.external_id = q.external_id
     WHERE q.status = 'awaiting'
     ORDER BY q.sent_at NULLS FIRST, q.id
     LIMIT GREATEST(COALESCE(p_cap, 300), 1)
  LOOP
    -- (أ) حُجز ولم يُرسل: مات الإرسالُ بين الخطوتين ⇒ يُعاد
    IF v_row.request_id IS NULL THEN
      IF v_row.sent_at < now() - interval '2 minutes' THEN
        UPDATE public.stock_refresh_queue
           SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
               last_error = 'CLAIMED_NOT_SENT',
               done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
               due_at = now() + make_interval(secs => (30 * power(2, LEAST(attempts, 5)))::int)
         WHERE id = v_row.id;
        v_retry := v_retry + 1;
      ELSE
        v_wait := v_wait + 1;
      END IF;
      CONTINUE;
    END IF;

    SELECT * INTO v_resp FROM net._http_response WHERE id = v_row.request_id;

    -- (ب) لم يهبط الردُّ بعد — أو ضاع
    IF NOT FOUND THEN
      IF v_row.sent_at < now() - interval '3 minutes' THEN
        -- 🪤 ثلاثُ دقائق تفوق مهلةَ الطلب (٨ ثوانٍ) بكثير، فالغيابُ بعدها
        --    يعني ضياعَ الردّ (إعادةُ تشغيل عامل pg_net مثلاً) لا بطأً.
        UPDATE public.stock_refresh_queue
           SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
               last_error = 'RESPONSE_LOST',
               done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
               due_at = now() + make_interval(secs => (30 * power(2, LEAST(attempts, 5)))::int)
         WHERE id = v_row.id;
        v_retry := v_retry + 1;
      ELSE
        v_wait := v_wait + 1;
      END IF;
      CONTINUE;
    END IF;

    -- (ج) شبكةٌ أو مهلة
    IF COALESCE(v_resp.timed_out, false) OR v_resp.error_msg IS NOT NULL THEN
      UPDATE public.stock_refresh_queue
         SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
             last_error = 'NET:' || left(COALESCE(v_resp.error_msg, 'TIMEOUT'), 120),
             http_status = v_resp.status_code,
             done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
             due_at = now() + make_interval(secs => (30 * power(2, LEAST(attempts, 5)))::int)
       WHERE id = v_row.id;
      v_retry := v_retry + 1; CONTINUE;
    END IF;

    -- (د) ٤٢٩ — وعند زد **لا يُحسب فشلاً** (وثيقتهم صريحة)، فلا يُستهلك
    --     رصيدُ المحاولات، ويُؤجَّل تأجيلاً أطول. ووثيقتاهما توصيان بتراجعٍ أُسّي.
    IF v_resp.status_code = 429 THEN
      UPDATE public.stock_refresh_queue
         SET status = 'pending', http_status = 429, last_error = 'RATE_LIMITED',
             attempts = GREATEST(attempts - 1, 0),
             due_at = now() + interval '90 seconds'
       WHERE id = v_row.id;
      v_retry := v_retry + 1; CONTINUE;
    END IF;

    -- (هـ) توكنٌ مرفوض — لا يُعاد بغبائه: يُوسم الاتصالُ ويُطلب تحديثٌ واحد
    IF v_resp.status_code IN (401, 403) THEN
      UPDATE public.stock_refresh_queue
         SET status = 'failed', http_status = v_resp.status_code,
             last_error = 'TOKEN_REJECTED', done_at = now()
       WHERE id = v_row.id;
      UPDATE public.stock_integrations
         SET last_note = 'TOKEN_REJECTED',
             -- 🔴 ولا يُقفز إلى «needs_reconnect» فوراً: التحديثُ الدوريّ
             --    قد ينجح. لكنّ تاريخَ الانتهاء يُقدَّم ليُحاول الآن.
             oauth_expires_at = LEAST(COALESCE(oauth_expires_at, now()), now())
       WHERE id = v_row.integration_id;
      v_dead := v_dead + 1; CONTINUE;
    END IF;

    IF v_resp.status_code < 200 OR v_resp.status_code > 299 THEN
      UPDATE public.stock_refresh_queue
         SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
             http_status = v_resp.status_code, last_error = 'HTTP_' || v_resp.status_code,
             done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
             due_at = now() + make_interval(secs => (30 * power(2, LEAST(attempts, 5)))::int)
       WHERE id = v_row.id;
      v_retry := v_retry + 1; CONTINUE;
    END IF;

    -- (و) ٢xx — يُقرأ الرقمُ ويُكتب
    BEGIN
      v_body := v_resp.content::jsonb;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.stock_refresh_queue
         SET status = 'failed', http_status = v_resp.status_code,
             last_error = 'BODY_NOT_JSON', done_at = now() WHERE id = v_row.id;
      v_dead := v_dead + 1; CONTINUE;
    END;

    v_p := public._taki_stock_parse_read(v_row.provider, v_body, v_row.external_id, v_row.location_id);
    IF NOT COALESCE((v_p->>'ok')::boolean, false) THEN
      -- 🪤 «لا شيءَ يُكتب» ليس فشلاً: منتجٌ بلا حدّ أو فرعٌ غير موجودٍ عندهم
      --    حالةٌ مشروعة. تُسجَّل بسببها ويُغلق الصفّ — ولا تُعاد إلى الأبد.
      UPDATE public.stock_refresh_queue
         SET status = 'done', http_status = v_resp.status_code,
             last_error = COALESCE(v_p->>'reason', 'NOT_USABLE'), done_at = now()
       WHERE id = v_row.id;
      v_none := v_none + 1; CONTINUE;
    END IF;

    -- 🪤 `observed_at = now()` صحيحٌ هنا بالضبط: الرقمُ قُرئ الآن من مصدره،
    --    لا من رسالةٍ قد تكون قديمة. ومفتاحُ التكرار صفُّ الطابور نفسه.
    v_ap := public._taki_stock_apply(
              v_row.integration_id,
              jsonb_build_array(jsonb_build_object('external_id', v_row.external_id,
                                                   'on_hand', (v_p->>'on_hand')::int)),
              now(), 'rd:' || v_row.id::text);

    UPDATE public.stock_refresh_queue
       SET status = 'done', http_status = v_resp.status_code, done_at = now(),
           last_error = CASE WHEN COALESCE((v_ap->>'applied')::int, 0) > 0 THEN NULL
                             WHEN jsonb_array_length(COALESCE(v_ap->'unmatched','[]'::jsonb)) > 0
                               THEN 'NOT_LINKED'
                             ELSE COALESCE(v_ap->'skip_reasons'->>0, 'NO_EFFECT') END
     WHERE id = v_row.id;

    IF COALESCE((v_ap->>'applied')::int, 0) > 0 THEN
      UPDATE public.stock_integrations
         SET last_sync_at = now(), last_note = 'SYNCED' WHERE id = v_row.integration_id;
      v_ok := v_ok + 1;
    ELSE
      v_none := v_none + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('applied', v_ok, 'no_write', v_none,
                            'retried', v_retry, 'dead', v_dead, 'in_flight', v_wait);
END
$function$
;


-- ═══ FUNCTION taki_stock_refresh_dispatch(p_global_cap integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_refresh_dispatch(p_global_cap integer DEFAULT 150)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row   record; v_d jsonb; v_tok jsonb; v_url text; v_req bigint;
  v_sent  int := 0; v_fail int := 0; v_exp int := 0;
BEGIN
  -- ── (أ) توسيعُ «أعِد قراءة كلّ المربوط» إلى صفٍّ لكلّ منتج ────────────
  -- 🔴 كلا المزوّدين يقرأ **منتجاً واحداً** في النداء، فالصفُّ العامّ لا
  --    يُرسل بذاته. والتوسيعُ هنا لا في الخطّاف: الخطّافُ يجب أن يردّ فوراً.
  FOR v_row IN
    SELECT q.id, q.integration_id, q.store_id, q.reason, q.signal_event
      FROM public.stock_refresh_queue q
      JOIN public.stock_integrations i ON i.id = q.integration_id
     WHERE q.status = 'pending' AND q.external_id IS NULL AND q.due_at <= now()
       AND i.is_enabled AND public._taki_provider_read(i.provider) IS NOT NULL
     ORDER BY q.due_at, q.id LIMIT 50
  LOOP
    INSERT INTO public.stock_refresh_queue
      (integration_id, store_id, external_id, reason, signal_event, due_at)
    SELECT v_row.integration_id, v_row.store_id, l.external_id, v_row.reason,
           v_row.signal_event, now()
      FROM public.stock_links l
     WHERE l.integration_id = v_row.integration_id
    ON CONFLICT (integration_id, COALESCE(external_id, '*')) WHERE status = 'pending'
    DO UPDATE SET due_at = LEAST(stock_refresh_queue.due_at, EXCLUDED.due_at);
    GET DIAGNOSTICS v_exp = ROW_COUNT;
    UPDATE public.stock_refresh_queue
       SET status = 'done', done_at = now(),
           last_error = CASE WHEN v_exp = 0 THEN 'NO_LINKS' ELSE NULL END
     WHERE id = v_row.id;
  END LOOP;

  -- ── (ب) الحجزُ في خطوتين، ولسببٍ لغويّ لا تفضيليّ ─────────────────────
  -- 🪤 بوستجرس يرفض `FOR UPDATE` مع دالّةِ نافذة (`row_number`)، وسقفُ كلّ
  --    اتصالٍ يحتاجها. فالحجزُ `UPDATE … WHERE id IN (…)` وهو ذرّيٌّ بنفسه.
  -- 🪤 والصفُّ المحجوز يحمل `request_id IS NULL` حتى يُرسل فعلاً — وهي علامةُ
  --    «حُجز ولم يُرسل» التي يحرسها الجامعُ فيُعيدها إن مات الإرسال.
  CREATE TEMP TABLE IF NOT EXISTS _taki_disp(id bigint PRIMARY KEY) ON COMMIT DROP;
  DELETE FROM _taki_disp;
  INSERT INTO _taki_disp(id)
  WITH cand AS (
    SELECT q.id, i.provider,
           row_number() OVER (PARTITION BY q.integration_id ORDER BY q.due_at, q.id) AS rn
      FROM public.stock_refresh_queue q
      JOIN public.stock_integrations i ON i.id = q.integration_id
     WHERE q.status = 'pending' AND q.external_id IS NOT NULL AND q.due_at <= now()
       AND i.is_enabled
     ORDER BY q.due_at, q.id
     LIMIT GREATEST(COALESCE(p_global_cap, 150), 1)
  )
  SELECT c.id FROM cand c
   -- 🔴 سقفُ النبضة مشتقٌّ من سقف مزوّده لا مخترَع: ٤٠٪ منه، فسحةً لنداءات
   --    التحديث والتسجيل. (زد ٦٠/دقيقة للتطبيق في المتجر ⇒ ٢٤؛ وسلّة يُفترض
   --    أدنى باقاتها ١٢٠ ⇒ ٤٨.)
   WHERE c.rn <= GREATEST(
           (COALESCE((public._taki_provider_read(c.provider)->>'rpm')::int, 60) * 4) / 10, 1);

  UPDATE public.stock_refresh_queue q
     SET status = 'awaiting', request_id = NULL, sent_at = now(), attempts = attempts + 1
   WHERE q.id IN (SELECT id FROM _taki_disp) AND q.status = 'pending';

  FOR v_row IN
    SELECT q.id, q.integration_id, q.external_id, i.provider
      FROM public.stock_refresh_queue q
      JOIN public.stock_integrations i ON i.id = q.integration_id
     WHERE q.id IN (SELECT id FROM _taki_disp) AND q.status = 'awaiting' AND q.request_id IS NULL
  LOOP
    v_d := public._taki_provider_read(v_row.provider);
    IF v_d IS NULL THEN
      UPDATE public.stock_refresh_queue
         SET status = 'failed', last_error = 'NO_READ_DESCRIPTOR', done_at = now() WHERE id = v_row.id;
      v_fail := v_fail + 1; CONTINUE;
    END IF;

    v_tok := public._taki_stock_token(v_row.integration_id);
    IF v_tok IS NULL THEN
      -- 🪤 لا إعادةَ بلا نهاية: اتصالٌ بلا توكن ينتظر ضغطةَ التاجر «اربط
      --    متجرك»، وتلك الضغطةُ تُدرج صفوفاً جديدة. فالإعادةُ دَينٌ صامت.
      UPDATE public.stock_refresh_queue
         SET status = 'failed', last_error = 'NOT_CONNECTED', done_at = now() WHERE id = v_row.id;
      UPDATE public.stock_integrations SET last_note = 'NOT_CONNECTED' WHERE id = v_row.integration_id;
      v_fail := v_fail + 1; CONTINUE;
    END IF;

    v_url := (v_d->>'base')
          || replace(v_d->>'path', '{id}', public._taki_urlenc(v_row.external_id));

    BEGIN
      v_req := net.http_get(url := v_url,
                            headers := public._taki_provider_headers(v_row.provider, v_tok),
                            timeout_milliseconds := 8000);
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.stock_refresh_queue
         SET status = 'pending', last_error = 'DISPATCH:' || left(SQLERRM, 120),
             due_at = now() + make_interval(secs => (30 * power(2, LEAST(attempts, 5)))::int)
       WHERE id = v_row.id;
      v_fail := v_fail + 1; CONTINUE;
    END;

    UPDATE public.stock_refresh_queue SET request_id = v_req WHERE id = v_row.id;
    v_sent := v_sent + 1;
  END LOOP;

  RETURN jsonb_build_object('sent', v_sent, 'failed', v_fail);
END
$function$
;


-- ═══ FUNCTION taki_stock_refresh_periodic() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_refresh_periodic()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int := 0; v_row record;
BEGIN
  FOR v_row IN
    SELECT i.id FROM public.stock_integrations i
     WHERE i.is_enabled AND i.direction IN ('in','both')
       AND public._taki_provider_read(i.provider) IS NOT NULL
       AND public._taki_stock_token(i.id) IS NOT NULL
       AND EXISTS (SELECT 1 FROM public.stock_links l WHERE l.integration_id = i.id)
  LOOP
    PERFORM public._taki_stock_enqueue(v_row.id, NULL, 'periodic', NULL, 0);
    v_n := v_n + 1;
  END LOOP;
  RETURN v_n;
END
$function$
;


-- ═══ FUNCTION taki_stock_set_inbound_secret(p_id uuid, p_secret text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_set_inbound_secret(p_id uuid, p_secret text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_back text;
BEGIN
  IF COALESCE(btrim(COALESCE(p_secret,'')),'') = '' THEN
    RETURN jsonb_build_object('ok', false, 'error', 'SECRET_REQUIRED');
  END IF;
  UPDATE public.stock_integrations SET inbound_secret = btrim(p_secret) WHERE id = p_id;
  -- 🪤 تُثبَت بقراءة: `UPDATE` على معرّفٍ غيرِ موجودٍ يكتب صفرَ صفوفٍ بلا خطأ.
  SELECT inbound_secret INTO v_back FROM public.stock_integrations WHERE id = p_id;
  IF COALESCE(v_back,'') <> btrim(p_secret) THEN
    RETURN jsonb_build_object('ok', false, 'error', 'WRITE_FAILED');
  END IF;
  RETURN jsonb_build_object('ok', true);
END
$function$
;


-- ═══ FUNCTION taki_stock_sync_info() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_stock_sync_info()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'periodic_minutes', (
      SELECT CASE WHEN schedule ~ '^\*/[0-9]+ \* \* \* \*$'
                  THEN (regexp_replace(schedule, '^\*/([0-9]+).*$', '\1'))::int
                  WHEN schedule = '* * * * *' THEN 1 ELSE NULL END
        FROM cron.job WHERE jobname = 'taki-stock-refresh-periodic' AND active LIMIT 1),
    'debounce_seconds', 10,
    'instant', false);
$function$
;


-- ═══ FUNCTION taki_stock_token_reap() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_token_reap()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_n int;
BEGIN
  UPDATE public.stock_integrations
     SET oauth_state = 'needs_reconnect', last_note = 'REFRESH_STUCK'
   WHERE oauth_state = 'inflight' AND oauth_attempt_at < now() - interval '10 minutes';
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RETURN v_n;
END
$function$
;


-- ═══ FUNCTION taki_stock_token_refresh_claim(p_limit integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_token_refresh_claim(p_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_out jsonb := '[]'::jsonb; v_row record; v_app jsonb; v_tok jsonb;
BEGIN
  FOR v_row IN
    UPDATE public.stock_integrations i
       SET oauth_state = 'inflight', oauth_attempt_at = now()
     WHERE i.id IN (
       SELECT x.id FROM public.stock_integrations x
        WHERE x.is_enabled
          AND COALESCE(x.oauth_state, 'idle') = 'idle'
          -- 🔴 v15.19: الشرطُ على موعد التجديد وحده. وv15.18 كانت تقيس انتهاءَ
          --    التوكن، فربطُ زد (توكنٌ ٣ سنوات · رمزٌ سنة) كان سيُجدَّد بعد
          --    سنتين و١١ شهراً برمزٍ ميتٍ منذ سنتين ⇒ موتٌ صامت.
          AND x.oauth_renew_at IS NOT NULL
          AND x.oauth_renew_at < now()
        ORDER BY x.oauth_renew_at
        LIMIT GREATEST(COALESCE(p_limit, 20), 1))
       AND COALESCE(i.oauth_state, 'idle') = 'idle'
    RETURNING i.id, i.provider
  LOOP
    v_app := public._taki_stock_app(v_row.provider);
    v_tok := public._taki_stock_token(v_row.id);
    IF v_app IS NULL OR v_tok IS NULL
       OR COALESCE(btrim(v_tok->>'refresh_token'), '') = '' THEN
      UPDATE public.stock_integrations
         SET oauth_state = 'needs_reconnect', last_note = 'NO_REFRESH_TOKEN'
       WHERE id = v_row.id;
      CONTINUE;
    END IF;
    v_out := v_out || jsonb_build_object(
      'integration_id', v_row.id, 'provider', lower(v_row.provider),
      'client_id', v_app->>'client_id', 'client_secret', v_app->>'client_secret',
      'refresh_token', v_tok->>'refresh_token');
  END LOOP;
  RETURN jsonb_build_object('ok', true, 'jobs', v_out);
END
$function$
;


-- ═══ FUNCTION taki_stock_token_refresh_done(p_id uuid, p_outcome text, p_tok jsonb, p_error text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_token_refresh_done(p_id uuid, p_outcome text, p_tok jsonb DEFAULT NULL::jsonb, p_error text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_state text; r jsonb;
BEGIN
  SELECT oauth_state INTO v_state FROM public.stock_integrations WHERE id = p_id;
  IF v_state IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'NO_INTEGRATION'); END IF;
  IF v_state <> 'inflight' THEN
    -- 🪤 ردٌّ على قفلٍ غير قائم: إمّا نتيجةٌ متأخّرةٌ جداً وإمّا نداءٌ مكرّر.
    --    لا يُطبَّق — فتطبيقُه قد يدهس توكناً أحدثَ منه.
    RETURN jsonb_build_object('ok', false, 'error', 'NOT_INFLIGHT', 'state', v_state);
  END IF;

  IF p_outcome = 'ok' THEN
    r := public.taki_stock_oauth_store(p_id, p_tok, NULL);
    IF NOT COALESCE((r->>'ok')::boolean, false) THEN
      -- فشلُ الحفظ بعد نجاح التحديث = التوكنُ الجديد ضاع ⇒ لا يُعاد الرمزُ
      --    القديمُ أبداً (استُهلك). المخرجُ إعادةُ ربطٍ بضغطة.
      UPDATE public.stock_integrations
         SET oauth_state = 'needs_reconnect', last_note = 'REFRESH_SAVE_FAILED'
       WHERE id = p_id;
      RETURN r;
    END IF;
    RETURN jsonb_build_object('ok', true);
  END IF;

  -- 🔴 كلُّ ما ليس نجاحاً صريحاً ⇒ `needs_reconnect`. وهذا **ليس تشاؤماً**:
  --    رمزُ التحديث استُهلك أو قد يكون استُهلك، ومحاولةٌ ثانيةٌ به تُبيد
  --    التفويضَ نهائياً. وكلفةُ الخطأ هنا غيرُ متناظرة: ضغطةٌ من التاجر
  --    مقابل إعادةِ تثبيتٍ من متجر سلّة.
  UPDATE public.stock_integrations
     SET oauth_state = 'needs_reconnect',
         last_note = CASE WHEN p_outcome = 'auth_failed' THEN 'REFRESH_REJECTED'
                          ELSE 'REFRESH_UNKNOWN' END
   WHERE id = p_id;
  RETURN jsonb_build_object('ok', true, 'parked', true, 'outcome', p_outcome,
                            'detail', left(COALESCE(p_error, ''), 200));
END
$function$
;


-- ═══ FUNCTION taki_stock_token_refresh_kick() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_token_refresh_kick()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_sec text; v_req bigint;
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM public.stock_integrations
     WHERE is_enabled AND COALESCE(oauth_state,'idle') = 'idle'
       AND oauth_renew_at IS NOT NULL AND oauth_renew_at < now()) THEN
    RETURN NULL;   -- لا عملَ ⇒ لا نداء
  END IF;
  SELECT value INTO v_sec FROM public.app_secrets WHERE key = 'stock_oauth_secret';
  IF COALESCE(v_sec,'') = '' THEN RAISE WARNING 'stock_oauth_secret مفقود — لا تحديث.'; RETURN NULL; END IF;
  -- 🪤 العنوانُ العامّ لا `SUPABASE_URL` (ذاك `http://kong:8000` داخل الحاوية).
  v_req := net.http_post(
    url := 'https://api.takisa.net/functions/v1/stock-oauth/refresh',
    body := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json',
                                  'x-stock-oauth-secret', v_sec),
    timeout_milliseconds := 20000);
  RETURN v_req;
END
$function$
;


-- ═══ FUNCTION taki_stock_webhook(p_key text, p_body jsonb, p_event_id text, p_observed_at timestamp with time zone) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_stock_webhook(p_key text, p_body jsonb, p_event_id text DEFAULT NULL::text, p_observed_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_i      public.stock_integrations%ROWTYPE;
  v_hash   text;
  v_map    jsonb;
  v_id     text; v_qty text;
  v_cand   text[][];
  v_pair   text[];
  v_ev     text;
  v_res    jsonb;
  v_obs    timestamptz := COALESCE(p_observed_at, now());
BEGIN
  IF p_key IS NULL OR length(btrim(p_key)) < 20 THEN
    RETURN jsonb_build_object('ok', false, 'error', 'BAD_KEY');
  END IF;
  v_hash := encode(extensions.digest(btrim(p_key), 'sha256'), 'hex');

  SELECT * INTO v_i FROM public.stock_integrations
   -- v15.17 signal — العنوانُ صار مساراً لكلّ متجر (`/h/<slug>`) لأن
   --   دائرةَ زد القاطعة ترفض إعادةَ استخدام رابطٍ عُطّل («You cannot
   --   recover a webhook by re-using the same target_url»). فيُفصل
   --   العنوانُ عن السرّ: المسارُ يُعاد إصدارُه والمفتاحُ يبقى.
   WHERE (api_key_hash = v_hash OR webhook_slug = btrim(p_key))
     AND is_enabled AND direction IN ('in','both');
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'UNKNOWN_KEY'); END IF;

  -- v15.20 throttle2 — **بعد** التعرّف: مفتاحٌ مجهولٌ لا يمسّ العدّاد،
  --   والمخنوقُ يُوسَم مرّةً لكلّ دفقة. ويُردّ خنقاً لا خطأً: ٥٠٢ تُحسب
  --   فشلاً عند زد (٣٠ في ساعةٍ ⇒ تعطيلُ الخطّاف وإلغاءُ أحداثه)،
  --   و٤٢٩ **لا تُحسب فشلاً** بنصّ وثيقتهم.
  BEGIN
    PERFORM public.taki_rate_check('stockhook:' || left(v_hash, 16), 300, 60,
                                   'too many webhooks — slow down');
  EXCEPTION WHEN OTHERS THEN
    UPDATE public.stock_integrations SET last_note = 'THROTTLED'
     WHERE id = v_i.id AND COALESCE(last_note, '') <> 'THROTTLED';
    RETURN jsonb_build_object('ok', true, 'throttled', true, 'retry_after', 60);
  END;

  -- 🔴 تُحفظ الرسالةُ **دائماً** قبل أيّ محاولة فهم: هي الدليلُ الوحيد على
  --    شكلها الحقيقي، وبدونها لا يستطيع أحدٌ ربطَ الحقول إلا بالتخمين.
  UPDATE public.stock_integrations
     SET last_payload = p_body, last_payload_at = now(), last_seen_at = now()
   WHERE id = v_i.id;

  -- v15.17 signal — تُدرَج إشارةٌ ويُعاد القراءةُ لاحقاً. ولا يُنادى
  --   المزوّدُ من هنا إطلاقاً: وثيقةُ زد تحسب الردَّ البطيء فشلاً
  --   (٣٠ فشلاً في ساعةٍ ⇒ `broken` وتُلغى الأحداثُ المعلّقة).
  IF public._taki_provider_read(v_i.provider) IS NOT NULL THEN
    PERFORM public._taki_stock_enqueue(v_i.id, NULL, 'signal',
              public._taki_jpath(p_body, 'event'), 10);
  END IF;

  IF p_body IS NULL OR jsonb_typeof(p_body) <> 'object' THEN
    UPDATE public.stock_integrations SET last_note = 'BODY_NOT_OBJECT' WHERE id = v_i.id;
    RETURN jsonb_build_object('ok', true, 'stored', true, 'unmapped', true, 'reason', 'BODY_NOT_OBJECT');
  END IF;

  -- خريطةُ التاجر أوّلاً؛ وإلّا تُجرَّب مرشّحاتٌ شائعة على الرسالة نفسها.
  -- v15.16 merge — دمجٌ لا إحلال: ما يكتبه التاجر يعلو في id/qty،
  --   و`skip_when` من خريطة المزوّد يبقى لأنّ لا كاتبَ له.
  v_map := COALESCE(public._taki_provider_map(v_i.provider), '{}'::jsonb)
           || COALESCE(v_i.field_map, '{}'::jsonb);
  IF v_map = '{}'::jsonb THEN v_map := NULL; END IF;
  IF v_map IS NOT NULL THEN
    v_id  := public._taki_jpath(p_body, v_map->>'id');
    v_qty := public._taki_jpath(p_body, v_map->>'qty');
  END IF;

  IF v_id IS NULL OR v_qty IS NULL THEN
    -- 🪤 مرشّحاتٌ لا حقائق: كلُّ زوجٍ يُجرَّب على الرسالة الحقيقية، وما ينجح
    --    يُحفظ خريطةً. ولا يُدَّعى أن نظاماً بعينه يستعمل شكلاً بعينه.
    v_cand := ARRAY[
      ARRAY['data.id',            'data.quantity'],
      ARRAY['data.id',            'data.stock_quantity'],
      ARRAY['data.id',            'data.available_quantity'],
      ARRAY['data.product.id',    'data.product.quantity'],
      ARRAY['data.sku',           'data.quantity'],
      ARRAY['id',                 'quantity'],
      ARRAY['id',                 'stock_quantity'],
      ARRAY['sku',                'quantity'],
      ARRAY['product.id',         'product.quantity'],
      ARRAY['payload.id',         'payload.quantity'],
      ARRAY['external_id',        'on_hand']
    ];
    FOR i IN 1 .. array_length(v_cand, 1) LOOP
      v_pair := v_cand[i:i][1:2];
      v_id  := public._taki_jpath(p_body, v_cand[i][1]);
      v_qty := public._taki_jpath(p_body, v_cand[i][2]);
      IF v_id IS NOT NULL AND v_qty IS NOT NULL AND v_qty ~ '^[0-9]+$' THEN
        v_map := jsonb_build_object('id', v_cand[i][1], 'qty', v_cand[i][2], 'learned', true);
        UPDATE public.stock_integrations SET field_map = v_map WHERE id = v_i.id;
        -- v15.16 merge2 — ويبقى حارسُ المزوّد سارياً في هذا النداء نفسه
        v_map := COALESCE(public._taki_provider_map(v_i.provider), '{}'::jsonb) || v_map;
        EXIT;
      END IF;
      v_id := NULL; v_qty := NULL;
    END LOOP;
  END IF;

  -- v15.15 — هل يقول المزوّدُ إنّ جذرَ رسالته ليس الحقيقة؟
  --           (زد: منتجٌ له أصناف جذرُ كمّيته صفرٌ دائماً.)
  IF v_qty IS NOT NULL AND jsonb_typeof(COALESCE(v_map->'skip_when','null'::jsonb)) = 'array'
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_map->'skip_when') c
                  WHERE lower(COALESCE(public._taki_jpath(p_body, c->>'path'), '~absent~'))
                        = lower(c->>'equals')) THEN
    -- يُقلَّد الفرعُ القائم حرفياً: وسمٌ على الاتصال، والحمولةُ محفوظةٌ
    -- في `last_payload` بمشغّلٍ قائم. ولا جدولَ آخر — `stock_inbox`
    -- سجلُّ تكرارٍ لا مخزنُ حمولات (قِيس قبل الكتابة).
    UPDATE public.stock_integrations SET last_note = 'PARENT_OR_UNLIMITED' WHERE id = v_i.id;
    RETURN jsonb_build_object('ok', true, 'stored', true, 'unmapped', true,
      'reason', 'PARENT_OR_UNLIMITED',
      'hint', 'this product keeps its real stock per variant or per location, not at the root');
  END IF;
  IF v_id IS NULL OR v_qty IS NULL OR v_qty !~ '^[0-9]+$' THEN
    -- 🔴 يُقال صراحةً، ولا يُردّ خطأً: رسالةٌ لم نفهمها ليست خطأً عند المرسل،
    --    ورفضُها يجعل نظامه يُعيدها إلى الأبد. تُحفظ ويُطلب ربطُ حقولها.
    UPDATE public.stock_integrations SET last_note = 'UNMAPPED' WHERE id = v_i.id;
    RETURN jsonb_build_object('ok', true, 'stored', true, 'unmapped', true,
      'hint', 'open your TAKI stock-link card and map the fields of the message we just received');
  END IF;

  -- معرّفُ الحدث: من الرسالة إن حملته، وإلّا **بصمةُ محتواها**.
  -- 🔴 وأوّلُ نسخةٍ كتبتُها بنَته بـ`jpath(body,'id') || ':' || …` — و`NULL`
  --    مضروبةً في نصٍّ تعطي `NULL` في SQL، فخرج المعرّف فارغاً ورُفضت كلُّ
  --    رسالةٍ بـ`EVENT_ID_REQUIRED`. أمسكه القياسُ السلوكيّ لا القراءة.
  -- 🪤 والبصمةُ وحدها تكفي: رسالتان متطابقتان تماماً تكرارٌ بالتعريف، وضبطُ
  --    نفس الرقم مرّتين لا أثر له أصلاً (الكمّيات مطلقة).
  -- 🔴 v15.80 ⑤ — والدلوُ من **زمنِ الرسالة** لا من `now()`: جسمٌ موقَّعٌ
  --    يُعاد بعد النافذة كان يدخل دلواً جديداً فيُطبَّق ثانياً، ولا يمسكه
  --    `STALE_OBSERVATION` لأنّ زمنَه كان يُولَد عند الاستقبال لا عند الرصد.
  v_ev := COALESCE(NULLIF(btrim(COALESCE(p_event_id, '')), ''),
                   NULLIF(btrim(COALESCE(public._taki_jpath(p_body, 'event_id'), '')), ''),
                   -- v15.16 window — بصمةٌ + نافذةُ خمس دقائق. وبلا النافذة
                   -- كانت كمّيةٌ تعود لقيمةٍ سبقت (٥ ⇐ ٨ ⇐ ٥) تُهمَل أبداً
                   -- فتبقى تاكي على ٨ والواقعُ ٥ ⇒ بيعٌ زائدٌ دائم.
                   'h:' || encode(extensions.digest(p_body::text, 'sha256'), 'hex')
                        || ':' || (floor(extract(epoch from v_obs) / 300))::bigint::text);

  v_res := public.taki_stock_push(p_key,
             jsonb_build_array(jsonb_build_object('external_id', v_id, 'on_hand', v_qty::int)),
             v_obs, v_ev);

  UPDATE public.stock_integrations
     SET last_note = CASE WHEN COALESCE((v_res->>'applied')::int, 0) > 0 THEN 'OK'
                          WHEN COALESCE((v_res->>'duplicate')::boolean, false) THEN 'DUPLICATE'
                          WHEN jsonb_array_length(COALESCE(v_res->'unmatched','[]'::jsonb)) > 0 THEN 'NOT_LINKED'
                          ELSE 'NO_EFFECT' END
   WHERE id = v_i.id;

  RETURN jsonb_build_object('ok', true, 'external_id', v_id, 'on_hand', v_qty::int, 'push', v_res);
END
$function$
;


-- ═══ FUNCTION taki_store_grandfathered(p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_store_grandfathered(p_store_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.store_verification_grace g
                  WHERE g.store_id = p_store_id AND g.until > now());
$function$
;


-- ═══ FUNCTION taki_store_profiles_subscription_notify() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_store_profiles_subscription_notify()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  s jsonb; vars jsonb; v_new boolean := false; v_cancel boolean := false;
  v_name text; v_plan text; v_title text; v_body text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_new := lower(COALESCE(NEW.subscription_plan,'free')) <> 'free'
             AND NEW.subscription_expires_at IS NOT NULL;
  ELSE
    v_new := lower(COALESCE(NEW.subscription_plan,'free')) <> 'free' AND (
         lower(COALESCE(OLD.subscription_plan,'free')) = 'free'
      OR (NEW.subscription_started_at IS DISTINCT FROM OLD.subscription_started_at
          AND NEW.subscription_started_at IS NOT NULL)
      OR (NEW.subscription_expires_at IS DISTINCT FROM OLD.subscription_expires_at
          AND NEW.subscription_expires_at > COALESCE(OLD.subscription_expires_at, NOW()))
    );
    v_cancel := COALESCE(OLD.auto_renew, true) AND NEW.auto_renew IS FALSE;
  END IF;

  IF NOT v_new AND NOT v_cancel THEN RETURN NEW; END IF;
  SELECT u.name INTO v_name FROM users u WHERE u.id = NEW.store_id;

  IF v_new THEN
    s := public.taki_msg_setting('sub_new');
    IF COALESCE((s->>'enabled')::boolean, true) THEN
      v_plan := CASE
        WHEN lower(COALESCE(NEW.subscription_plan,'')) = 'premium' AND COALESCE(NEW.max_branches,0) > 0
          THEN 'باقة حتى ' || NEW.max_branches || ' مواقع'
        ELSE COALESCE(NEW.subscription_plan,'') END;
      vars := jsonb_build_object(
        'store',   COALESCE(v_name,''),
        'plan',    v_plan,
        'price',   trim(to_char(COALESCE(NEW.subscription_amount,0), 'FM999999990.00')),
        'expires', to_char(NEW.subscription_expires_at, 'YYYY-MM-DD'));
      IF COALESCE((s->'channels'->>'inapp')::boolean, true) THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.store_id,
                public.taki_render_template(s->>'title_ar', vars),
                public.taki_render_template(s->>'title_en', vars),
                public.taki_render_template(s->>'body_ar', vars),
                public.taki_render_template(s->>'body_en', vars),
                'subscription', jsonb_build_object('audience','seller','event','sub_new'), NOW());
      END IF;
      -- email for sub_new is queued by the payment trigger (real invoice data);
      -- admin-granted subscriptions have no payment, hence in-app only.
    END IF;
  END IF;

  IF v_cancel THEN
    s := public.taki_msg_setting('sub_cancelled');
    IF COALESCE((s->>'enabled')::boolean, true) THEN
      vars := jsonb_build_object(
        'store',   COALESCE(v_name,''),
        'expires', COALESCE(to_char(NEW.subscription_expires_at, 'YYYY-MM-DD'), '—'));
      v_title := public.taki_render_template(s->>'title_ar', vars);
      v_body  := public.taki_render_template(s->>'body_ar',  vars);
      IF COALESCE((s->'channels'->>'inapp')::boolean, true) THEN
        INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (NEW.store_id, v_title,
                public.taki_render_template(s->>'title_en', vars),
                v_body,
                public.taki_render_template(s->>'body_en', vars),
                'subscription', jsonb_build_object('audience','seller','event','sub_cancelled'), NOW());
      END IF;
      IF COALESCE((s->'channels'->>'email')::boolean, false) THEN
        PERFORM public.taki_queue_email(NEW.store_id, 'sub_cancelled', v_title,
            public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
      END IF;
    END IF;
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- notifications are best-effort: NEVER block a subscription write
  RAISE WARNING 'taki_store_profiles_subscription_notify: %', SQLERRM;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_store_verified(p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_store_verified(p_store_id text)
 RETURNS boolean
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT EXISTS (SELECT 1 FROM public.store_verifications v
                  WHERE v.store_id = p_store_id AND v.status = 'approved'
                    AND (v.doc_expiry IS NULL OR v.doc_expiry >= current_date));
$function$
;


-- ═══ FUNCTION taki_subscription_maintenance() DEFINER owner=postgres search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_subscription_maintenance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$

DECLARE
    v_enabled boolean;
    s_warn jsonb; s_exp jsonb; s_renew jsonb;
    v_days int;
    v_warned  int := 0; v_expired int := 0; v_frozen int := 0; v_banners int := 0;
    v_renewed int := 0;
    r record; vars jsonb; v_title text; v_body text; v_body_en text;
BEGIN
    SELECT (value = 'true'::jsonb) INTO v_enabled
      FROM platform_settings WHERE key = 'payment_gateway_enabled';
    IF v_enabled IS NOT TRUE THEN
        RETURN jsonb_build_object('mode','free','warned',0,'renewed',0,'expired',0,'frozen',0,'banners_hidden',0);
    END IF;

    s_warn  := public.taki_msg_setting('sub_warning');
    s_exp   := public.taki_msg_setting('sub_expired');
    s_renew := public.taki_msg_setting('sub_renewed');
    v_days := LEAST(GREATEST(COALESCE((s_warn->>'days_before')::int, 3), 1), 60);

    IF COALESCE((s_warn->>'enabled')::boolean, true) THEN
        FOR r IN
            UPDATE store_profiles sp
            SET last_expiry_warning_at = NOW()
            WHERE sp.subscription_expires_at IS NOT NULL
              AND lower(COALESCE(sp.subscription_plan,'free')) IN ('premium','trial')
              AND sp.subscription_expires_at > NOW()
              AND sp.subscription_expires_at <= NOW() + (v_days || ' days')::interval
              -- v13.97 (طلب ناصر): لا تحذير لمن سيتجدّد اشتراكه تلقائياً — لا شيء
              -- مطلوبٌ منه، وإنذار «جدّد الآن» لمن لن ينقطع اشتراكه يُدرّب المستخدم
              -- على تجاهل إشعارات المنصة. التجارب تبقى تُحذَّر لأنها تنتهي فعلاً.
              AND NOT (lower(COALESCE(sp.subscription_plan,'')) = 'premium'
                       AND sp.auto_renew IS NOT FALSE
                       AND sp.subscription_canceled_at IS NULL)
              AND (sp.last_expiry_warning_at IS NULL
                   OR sp.last_expiry_warning_at < sp.subscription_expires_at - (v_days || ' days')::interval)
            RETURNING sp.store_id, sp.subscription_expires_at, sp.subscription_plan,
                      sp.auto_renew, sp.subscription_canceled_at, sp.subscription_amount
        LOOP
            vars := jsonb_build_object(
                'store',   COALESCE((SELECT u.name FROM users u WHERE u.id = r.store_id), ''),
                'days',    v_days::text,
                'expires', to_char(r.subscription_expires_at, 'YYYY-MM-DD'));
            v_title   := public.taki_render_template(s_warn->>'title_ar', vars);
            v_body    := public.taki_render_template(s_warn->>'body_ar',  vars);
            v_body_en := public.taki_render_template(s_warn->>'body_en',  vars);
            IF COALESCE((s_warn->'channels'->>'inapp')::boolean, true) THEN
                INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (r.store_id, v_title,
                        public.taki_render_template(s_warn->>'title_en', vars),
                        v_body,
                        v_body_en,
                        'system', jsonb_build_object('audience','seller','event','sub_warning'), NOW());
            END IF;
            IF COALESCE((s_warn->'channels'->>'email')::boolean, false) THEN
                PERFORM public.taki_queue_email(r.store_id, 'sub_warning', v_title,
                    public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
            END IF;
            v_warned := v_warned + 1;
        END LOOP;
    END IF;

    -- (a2) v12.67 auto-renew; v12.68 notification gated by sub_renewed setting
    FOR r IN
        UPDATE store_profiles sp
        SET subscription_started_at = NOW(),
            subscription_expires_at = NOW() + (
                GREATEST(1, LEAST(730, COALESCE(
                    ROUND(EXTRACT(EPOCH FROM (sp.subscription_expires_at - sp.subscription_started_at)) / 86400.0)::int,
                    30)))::text || ' days')::interval,
            updated_at = NOW()
        WHERE sp.subscription_expires_at IS NOT NULL
          AND sp.subscription_expires_at <= NOW()
          AND lower(COALESCE(sp.subscription_plan,'free')) = 'premium'
          AND sp.auto_renew IS NOT FALSE
          AND sp.subscription_canceled_at IS NULL
          AND sp.subscription_started_at IS NOT NULL
          -- 🔴 v15.40 — باقةٌ **مسعَّرة** لا تُجدَّد مجّاناً. كان هذا الكرون
          --    (كلّ ساعة، الدقيقة ٢٠) يمدّ اشتراكَ كلّ تاجرٍ «بريميوم» بلا
          --    أيّ خصمٍ من بطاقة، ويكتب صفَّ دفعةٍ «مدفوعة» بمبلغ الباقة.
          --    وقِيس أنه **عمل مرّتين فعلاً** على الإنتاج (١٣ أغسطس و٦ سبتمبر،
          --    ٢٩٩٫٩٩ ر.س لكلٍّ) — وهما كلُّ «إيراد» تاكي المسجَّل.
          --    والتجديدُ الحقيقيّ يلزمه رمزُ بطاقةٍ محفوظٌ عند المزوّد، ولا
          --    يملكه أحدٌ اليوم. فالمسعَّرُ **ينقضي** ويُنبَّه صاحبُه.
          AND COALESCE(sp.subscription_amount, 0) <= 0
        RETURNING sp.store_id, sp.subscription_started_at AS new_start,
                  sp.subscription_expires_at AS new_end,
                  sp.subscription_amount, sp.max_branches
    LOOP
        v_renewed := v_renewed + 1;
        -- 🪤 v15.40 — تجديدٌ بلا مالٍ لا فاتورةَ له: حُذف إدراجُ الدفعة.
        --    وبعد الشرط أعلاه لا يصل هنا إلا ما سعرُه صفر، وصفرٌ لا يُفوتَر.
        UPDATE merchant_subscriptions ms
        SET current_period_start = r.new_start, current_period_end = r.new_end,
            last_renewed_at = NOW(), updated_at = NOW()
        WHERE ms.merchant_id = r.store_id AND ms.status = 'active';
        IF COALESCE((s_renew->>'enabled')::boolean, true) THEN
            vars := jsonb_build_object(
                'store',   COALESCE((SELECT u.name FROM users u WHERE u.id = r.store_id), ''),
                'price',   round(COALESCE(r.subscription_amount,0),2)::text,
                'expires', to_char(r.new_end, 'YYYY-MM-DD'));
            v_title := public.taki_render_template(s_renew->>'title_ar', vars);
            v_body  := public.taki_render_template(s_renew->>'body_ar',  vars);
            IF COALESCE((s_renew->'channels'->>'inapp')::boolean, true) THEN
                INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (r.store_id, v_title,
                        public.taki_render_template(s_renew->>'title_en', vars),
                        v_body,
                        public.taki_render_template(s_renew->>'body_en', vars),
                        'system', jsonb_build_object('audience','seller','event','sub_renewed'), NOW());
            END IF;
            IF COALESCE((s_renew->'channels'->>'email')::boolean, false) THEN
                PERFORM public.taki_queue_email(r.store_id, 'sub_renewed', v_title,
                    public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
            END IF;
        END IF;
    END LOOP;

    -- (b) freeze deals of just-expired merchants (unchanged business rule)
    WITH froze AS (
        UPDATE deals d
        SET status = 'paused', subscription_frozen = TRUE
        WHERE d.status = 'active'
          AND d.store_id IN (
              SELECT store_id FROM store_profiles
              WHERE subscription_expires_at IS NOT NULL
                AND subscription_expires_at <= NOW()
                AND lower(COALESCE(subscription_plan,'free')) <> 'free'
          )
        RETURNING d.id
    )
    SELECT COUNT(*) INTO v_frozen FROM froze;

    -- (b2) v12.31 — hide the expired merchant's BANNERS too.
    WITH bfroze AS (
        UPDATE banners b
        SET is_active = FALSE, frozen_reason = 'subscription_expired'
        WHERE b.is_active
          AND b.store_id IS NOT NULL
          AND b.store_id IN (
              SELECT store_id FROM store_profiles
              WHERE subscription_expires_at IS NOT NULL
                AND subscription_expires_at <= NOW()
                AND lower(COALESCE(subscription_plan,'free')) <> 'free'
          )
        RETURNING b.id
    )
    SELECT COUNT(*) INTO v_banners FROM bfroze;

    -- (c) flip expired profiles to free + configurable notice
    FOR r IN
        UPDATE store_profiles
        SET subscription_plan = 'free', updated_at = NOW()
        WHERE subscription_expires_at IS NOT NULL
          AND subscription_expires_at <= NOW()
          AND lower(COALESCE(subscription_plan,'free')) <> 'free'
        RETURNING store_id, subscription_expires_at
    LOOP
        v_expired := v_expired + 1;
        IF COALESCE((s_exp->>'enabled')::boolean, true) THEN
            vars := jsonb_build_object(
                'store',   COALESCE((SELECT u.name FROM users u WHERE u.id = r.store_id), ''),
                'expires', to_char(r.subscription_expires_at, 'YYYY-MM-DD'));
            v_title := public.taki_render_template(s_exp->>'title_ar', vars);
            v_body  := public.taki_render_template(s_exp->>'body_ar',  vars);
            IF COALESCE((s_exp->'channels'->>'inapp')::boolean, true) THEN
                INSERT INTO notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
                VALUES (r.store_id, v_title,
                        public.taki_render_template(s_exp->>'title_en', vars),
                        v_body,
                        public.taki_render_template(s_exp->>'body_en', vars),
                        'system', jsonb_build_object('audience','seller','event','sub_expired'), NOW());
            END IF;
            IF COALESCE((s_exp->'channels'->>'email')::boolean, false) THEN
                PERFORM public.taki_queue_email(r.store_id, 'sub_expired', v_title,
                    public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
            END IF;
        END IF;
    END LOOP;

    RETURN jsonb_build_object('mode','paid','warned',v_warned,'renewed',v_renewed,'expired',v_expired,'frozen',v_frozen,'banners_hidden',v_banners,'warn_days',v_days);
END;

$function$
;


-- ═══ FUNCTION taki_sync_deal_shop_name() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_sync_deal_shop_name()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_name text;
BEGIN
  SELECT COALESCE(NULLIF(btrim(u.shop), ''), NULLIF(btrim(u.name), ''), 'متجر')
    INTO v_name FROM public.users u WHERE u.id = NEW.store_id;
  NEW.shop_name := COALESCE(v_name, 'متجر');
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION taki_traffic_channel(p_host text, p_utm_source text) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_traffic_channel(p_host text, p_utm_source text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN COALESCE(btrim(p_utm_source), '') <> '' THEN lower(btrim(p_utm_source))
    WHEN COALESCE(btrim(p_host), '') = ''        THEN 'direct'
    WHEN p_host ~ '(^|\.)takisa\.net$'           THEN 'internal'
    WHEN p_host ~ '(^|\.)(google|bing|duckduckgo|yandex|yahoo)\.' THEN 'search'
    WHEN p_host ~ '(^|\.)instagram\.com$'        THEN 'instagram'
    WHEN p_host ~ '(^|\.)(twitter\.com|x\.com|t\.co)$' THEN 'twitter'
    WHEN p_host ~ '(^|\.)(facebook\.com|fb\.me)$'THEN 'facebook'
    WHEN p_host ~ '(^|\.)snapchat\.com$'         THEN 'snapchat'
    WHEN p_host ~ '(^|\.)tiktok\.com$'           THEN 'tiktok'
    WHEN p_host ~ '(^|\.)linkedin\.com$'         THEN 'linkedin'
    WHEN p_host ~ '(^|\.)(t\.me|telegram\.org|telegram\.me)$' THEN 'telegram'
    WHEN p_host ~ '(^|\.)(wa\.me|whatsapp\.com)$' THEN 'whatsapp'
    ELSE 'referral'
  END;
$function$
;


-- ═══ FUNCTION taki_unfreeze_deals_within_cap(p_store_id text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_unfreeze_deals_within_cap(p_store_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_max        int;
  v_keys       text[] := ARRAY[]::text[];
  v_deal_keys  text[];
  r            record;
  v_unfrozen   int := 0;
  v_republished int := 0;
BEGIN
  SELECT max_branches INTO v_max FROM public.store_profiles WHERE store_id = p_store_id;
  IF v_max IS NULL OR v_max <= 0 THEN
    RETURN jsonb_build_object('ok', false, 'reason', 'no_cap');
  END IF;

  -- الأساس: مفاتيح ما هو **حيّ** اليوم (فروع نشطة + عروض نشطة) — هي ما يشغل
  -- الخانات فعلاً، ولا يُفكّ عرضٌ يدفع الاتحاد فوق السقف.
  SELECT COALESCE(array_agg(DISTINCT k), ARRAY[]::text[]) INTO v_keys
    FROM (
      SELECT k FROM public.deals d
        CROSS JOIN LATERAL public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k
       WHERE d.store_id = p_store_id AND d.status = 'active'
      UNION ALL
      SELECT CASE WHEN b.location_id IS NOT NULL AND b.location_id <> 'other'
                   AND b.location_id NOT LIKE 'custom\_%' ESCAPE '\'
                  THEN 'loc:' || b.location_id
                  ELSE 'geo:' || ROUND(COALESCE(b.map_lat,0)::numeric,3)::text || ',' ||
                                 ROUND(COALESCE(b.map_lng,0)::numeric,3)::text END
        FROM public.store_branches b
       WHERE b.merchant_id = p_store_id AND COALESCE(b.is_active, true)
    ) t;

  FOR r IN
    SELECT d.id,
           ARRAY(SELECT DISTINCT k
                   FROM public._taki_deal_loc_keys(d.location_id, d.map_lat, d.map_lng, d.locations) k) AS keys,
           d.status
      FROM public.deals d
     WHERE d.store_id = p_store_id AND COALESCE(d.subscription_frozen, false)
     ORDER BY d.created_at ASC NULLS FIRST, d.id ASC
  LOOP
    -- العرض بذاته أكبر من السقف ⇒ يبقى مجمّداً (لا خانة تكفيه أصلاً)
    CONTINUE WHEN array_length(r.keys, 1) IS NOT NULL AND array_length(r.keys, 1) > v_max;

    v_deal_keys := ARRAY(SELECT DISTINCT x FROM unnest(v_keys || r.keys) x);
    CONTINUE WHEN array_length(v_deal_keys, 1) > v_max;

    v_keys := v_deal_keys;

    -- (١) تُفكّ العلامة دائماً: القرار يعود للتاجر.
    UPDATE public.deals SET subscription_frozen = false WHERE id = r.id;
    v_unfrozen := v_unfrozen + 1;

    -- (٢) ويُحاول الإحياء — وحارس النشر هو من يبتّ، لا نحن.
    IF r.status = 'paused' THEN
      BEGIN
        UPDATE public.deals SET status = 'active' WHERE id = r.id;
        v_republished := v_republished + 1;
      EXCEPTION WHEN OTHERS THEN
        NULL;   -- اشتراكٌ غير فعّال أو حارسٌ آخر: يبقى موقوفاً بلا تجميد
      END;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('ok', true, 'unfrozen', v_unfrozen,
                            'republished', v_republished, 'cap', v_max);
END $function$
;


-- ═══ FUNCTION taki_user_in_campaign(p_uid text, p_city text, p_region text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_user_in_campaign(p_uid text, p_city text, p_region text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_city text := NULLIF(btrim(COALESCE(p_city, '')), '');
  v_reg  text := NULLIF(btrim(COALESCE(p_region, '')), '');
  v_lat double precision; v_lng double precision;
  v_near text; v_near_reg text;
BEGIN
  IF v_city IS NULL AND v_reg IS NULL THEN RETURN true; END IF;   -- بلا استهداف = الجميع

  -- (ب) سابقة الحجز — أرخص وأدقّ من الإحداثيات، فنبدأ بها.
  IF EXISTS (
    SELECT 1 FROM public.bookings b JOIN public.deals d ON d.id = b.deal_id
    WHERE b.user_id = p_uid
      AND (v_city IS NULL OR d.city   = v_city)
      AND (v_reg  IS NULL OR d.region = v_reg)
  ) THEN RETURN true; END IF;

  -- وللتاجر: مدينة عروضه هو.
  IF EXISTS (
    SELECT 1 FROM public.deals d
    WHERE d.store_id = p_uid
      AND (v_city IS NULL OR d.city   = v_city)
      AND (v_reg  IS NULL OR d.region = v_reg)
  ) THEN RETURN true; END IF;

  -- (أ) أقرب مدينة لإحداثياته.
  SELECT lat, lng INTO v_lat, v_lng FROM public.users WHERE id = p_uid;
  IF v_lat IS NULL OR v_lng IS NULL THEN RETURN false; END IF;
  SELECT g.city_id, g.region_id INTO v_near, v_near_reg
  FROM public.sa_cities_geo g
  ORDER BY ((g.lat - v_lat) ^ 2 + (g.lng - v_lng) ^ 2) ASC
  LIMIT 1;
  RETURN (v_city IS NULL OR v_near = v_city) AND (v_reg IS NULL OR v_near_reg = v_reg);
END $function$
;


-- ═══ FUNCTION taki_user_spend(p_uid text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_user_spend(p_uid text)
 RETURNS numeric
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT COALESCE(SUM(b.total_amount), 0)::numeric
  FROM public.bookings b
  WHERE b.user_id = p_uid AND b.status = 'completed';
$function$
;


-- ═══ FUNCTION taki_utf8_clip(p_text text, p_max integer) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_utf8_clip(p_text text, p_max integer DEFAULT 255)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE s text := COALESCE(p_text, ''); n int;
BEGIN
  IF octet_length(s) <= p_max THEN RETURN s; END IF;
  n := length(s);
  WHILE n > 0 AND octet_length(left(s, n)) > p_max LOOP
    n := n - 1;
  END LOOP;
  RETURN left(s, n);
END $function$
;


-- ═══ FUNCTION taki_variant_off(p_el jsonb) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_variant_off(p_el jsonb)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
AS $function$ SELECT COALESCE((p_el->>'off')::boolean, false); $function$
;


-- ═══ FUNCTION taki_verification_mode() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_verification_mode()
 RETURNS text
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT CASE
    WHEN (public.taki_verification_policy()->>'mode') = 'required'
     AND (public.taki_verification_policy()->>'vacation')::boolean THEN 'advisory'
    ELSE public.taki_verification_policy()->>'mode' END;
$function$
;


-- ═══ FUNCTION taki_verification_policy() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_verification_policy()
 RETURNS jsonb
 LANGUAGE sql
 STABLE SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
  SELECT jsonb_build_object(
    'mode', COALESCE((SELECT CASE WHEN value->>'mode' IN ('off','advisory','required')
                                  THEN value->>'mode' END
                        FROM public.platform_settings WHERE key='verification'), 'off'),
    'sla_hours', GREATEST(1, LEAST(720, COALESCE((
        SELECT floor((value->>'sla_hours')::numeric)::int FROM public.platform_settings
         WHERE key='verification' AND jsonb_typeof(value->'sla_hours')='number'), 24))),
    'vacation',  COALESCE((SELECT value->'vacation'   = 'true'::jsonb FROM public.platform_settings WHERE key='verification'), false),
    'show_badge',COALESCE((SELECT value->'show_badge' = 'true'::jsonb FROM public.platform_settings WHERE key='verification'), false)
  );
$function$
;


-- ═══ FUNCTION taki_verification_sla_alert() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_verification_sla_alert()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_h int; v_old int; n int := 0; v_msg text;
BEGIN
  IF public.taki_verification_mode() = 'off' THEN RETURN 0; END IF;
  v_h := (public.taki_verification_policy()->>'sla_hours')::int;
  SELECT ROUND(EXTRACT(EPOCH FROM (now() - MIN(submitted_at)))/3600)::int INTO v_old
    FROM public.store_verifications WHERE status = 'submitted';
  IF v_old IS NULL OR v_old < v_h THEN RETURN 0; END IF;
  IF EXISTS (SELECT 1 FROM public.notifications
              WHERE type='system' AND meta_data->>'kind' = 'ver_sla'
                AND created_at > now() - interval '12 hours') THEN RETURN 0; END IF;
  v_msg := '⏰ طلب توثيقٍ تجاوز المهلة المعلنة (أقدم طلب منذ ' || v_old || ' ساعة). افتح «توثيق التجّار».';
  INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
  SELECT u.id, '⏰ تجاوزُ مهلة التوثيق', '⏰ Verification SLA breached', v_msg, v_msg, 'system',
         jsonb_build_object('audience','admin','kind','ver_sla',
                            'actionUrl','/admin?tab=verification','action_url','/admin?tab=verification')
    FROM public.users u
   WHERE u.user_type='admin' AND u.deleted_at IS NULL
     AND (COALESCE(u.is_super_admin,false) OR 'tab_verification' = ANY(COALESCE(u.admin_permissions,'{}'::text[])));
  GET DIAGNOSTICS n = ROW_COUNT;
  RETURN n;
END
$function$
;


-- ═══ FUNCTION taki_wathq_collect(p_cap integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_wathq_collect(p_cap integer DEFAULT 200)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_row record; v_resp record; v_body jsonb; v_p jsonb; v_cfg jsonb;
  v_price numeric; v_nat text; v_ver record; v_names text[]; v_match boolean;
  v_ok int := 0; v_retry int := 0; v_dead int := 0; v_wait int := 0;
  MAX_TRIES constant int := 5;
BEGIN
  v_cfg := public._taki_wathq_cfg();

  FOR v_row IN
    SELECT c.* FROM public.store_verification_checks c
     WHERE c.status = 'awaiting'
     ORDER BY c.sent_at NULLS FIRST, c.id
     LIMIT GREATEST(COALESCE(p_cap, 200), 1)
  LOOP
    -- (أ) حُجز ولم يُرسل
    IF v_row.request_id IS NULL THEN
      IF v_row.sent_at < now() - interval '3 minutes' THEN
        UPDATE public.store_verification_checks
           SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
               last_error = 'CLAIMED_NOT_SENT',
               done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
               due_at = now() + make_interval(secs => (60 * power(2, LEAST(attempts, 5)))::int)
         WHERE id = v_row.id;
        v_retry := v_retry + 1;
      ELSE v_wait := v_wait + 1; END IF;
      CONTINUE;
    END IF;

    SELECT * INTO v_resp FROM net._http_response WHERE id = v_row.request_id;

    -- (ب) لم يهبط بعد — أو ضاع
    IF NOT FOUND THEN
      IF v_row.sent_at < now() - interval '5 minutes' THEN
        UPDATE public.store_verification_checks
           SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
               last_error = 'RESPONSE_LOST',
               done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
               due_at = now() + make_interval(secs => (60 * power(2, LEAST(attempts, 5)))::int)
         WHERE id = v_row.id;
        v_retry := v_retry + 1;
      ELSE v_wait := v_wait + 1; END IF;
      CONTINUE;
    END IF;

    -- (ج) شبكةٌ أو مهلة
    IF COALESCE(v_resp.timed_out, false) OR v_resp.error_msg IS NOT NULL THEN
      UPDATE public.store_verification_checks
         SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
             last_error = 'NET:' || left(COALESCE(v_resp.error_msg, 'TIMEOUT'), 120),
             http_status = v_resp.status_code,
             done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
             due_at = now() + make_interval(secs => (60 * power(2, LEAST(attempts, 5)))::int)
       WHERE id = v_row.id;
      v_retry := v_retry + 1; CONTINUE;
    END IF;

    -- (د) ٤٢٩ — لا يُستهلك رصيدُ المحاولات، والسقفُ ٥/ثانية فالتأجيلُ قصير
    IF v_resp.status_code = 429 THEN
      UPDATE public.store_verification_checks
         SET status = 'pending', http_status = 429, last_error = 'RATE_LIMITED',
             attempts = GREATEST(attempts - 1, 0), due_at = now() + interval '60 seconds'
       WHERE id = v_row.id;
      v_retry := v_retry + 1; CONTINUE;
    END IF;

    -- (هـ) مفتاحٌ مرفوض أو رصيدٌ نافد — لا يُعاد بغبائه، ويُنبَّه الأدمن مرّةً
    IF v_resp.status_code IN (401, 403) THEN
      UPDATE public.store_verification_checks
         SET status = 'failed', http_status = v_resp.status_code,
             last_error = 'KEY_REJECTED', done_at = now()
       WHERE id = v_row.id;
      v_dead := v_dead + 1;
      -- 🪤 ولا يُغرَق الأدمن: إشعارٌ واحد كلَّ ١٢ ساعة على الأكثر.
      IF NOT EXISTS (SELECT 1 FROM public.notifications
                      WHERE meta_data->>'code' = 'WATHQ_KEY_REJECTED'
                        AND created_at > now() - interval '12 hours') THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
        SELECT u.id, '⚠️ واثق ترفض المفتاح', '⚠️ Wathq rejected the key',
               'ترفض واثق مفتاحَنا (أو نفد رصيدُ الباقة) — فحصُ السجلّات التجارية موقوفٌ حتى يُحدَّث المفتاح.',
               'Wathq rejected our key (or the balance ran out) — commercial-registration checks are paused.',
               'system',
               jsonb_build_object('audience', 'admin', 'code', 'WATHQ_KEY_REJECTED',
                                  'actionUrl', '/admin', 'action_url', '/admin')
          FROM public.users u WHERE u.user_type = 'admin';
      END IF;
      CONTINUE;
    END IF;

    -- (و) ٤٠٤ / ٤٠٠ — رقمٌ غير موجود. **لا يُخصَم** (نصُّ واثق)، فالكلفةُ صفر.
    --     وهنا تقع الخطوةُ الذكيّة: الإنتاجُ لا يقبل رقمَ السجل العشَريّ
    --     للسجلّات السارية، فيُحوَّل مرّةً واحدةً ثمّ يُعاد السؤال.
    IF v_resp.status_code IN (400, 404) THEN
      UPDATE public.store_verification_checks
         SET status = 'done', http_status = v_resp.status_code,
             last_error = 'NOT_FOUND', cost_sar = 0, done_at = now(),
             result = jsonb_build_object('not_found', true)
       WHERE id = v_row.id;

      IF v_row.kind = 'status'
         AND (v_cfg->>'convert_cr')::boolean
         AND v_row.arg ~ '^[0-9]{10}$' AND left(v_row.arg, 1) <> '7'
         AND NOT EXISTS (SELECT 1 FROM public.store_verification_checks
                          WHERE ver_id = v_row.ver_id AND kind = 'crnational') THEN
        PERFORM public._taki_wathq_enqueue(v_row.ver_id, 'crnational', v_row.arg);
      ELSE
        UPDATE public.store_verifications
           SET registry_state = jsonb_build_object('found', false, 'asked', v_row.arg),
               registry_at = now()
         WHERE id = v_row.ver_id;
      END IF;
      v_ok := v_ok + 1; CONTINUE;
    END IF;

    IF v_resp.status_code < 200 OR v_resp.status_code >= 300 THEN
      UPDATE public.store_verification_checks
         SET status = CASE WHEN attempts >= MAX_TRIES THEN 'failed' ELSE 'pending' END,
             http_status = v_resp.status_code, last_error = 'HTTP_' || v_resp.status_code,
             done_at = CASE WHEN attempts >= MAX_TRIES THEN now() END,
             due_at = now() + make_interval(secs => (60 * power(2, LEAST(attempts, 5)))::int)
       WHERE id = v_row.id;
      v_retry := v_retry + 1; CONTINUE;
    END IF;

    -- ── ٢٠٠: هنا وحدها تُحتسب الكلفة ───────────────────────────────────
    BEGIN v_body := v_resp.content::jsonb;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.store_verification_checks
         SET status = 'failed', http_status = 200, last_error = 'BODY_NOT_JSON', done_at = now()
       WHERE id = v_row.id;
      v_dead := v_dead + 1; CONTINUE;
    END;

    v_price := COALESCE((v_cfg->'endpoints'->v_row.kind->>'price')::numeric, 0);
    SELECT * INTO v_ver FROM public.store_verifications WHERE id = v_row.ver_id;

    IF v_row.kind = 'status' THEN
      v_p := public._taki_wathq_parse_status(v_body);
      UPDATE public.store_verification_checks
         SET status = 'done', http_status = 200, cost_sar = v_price,
             result = v_p, done_at = now() WHERE id = v_row.id;

      UPDATE public.store_verifications
         SET registry_state = COALESCE(registry_state, '{}'::jsonb)
                              || jsonb_build_object('found', true)
                              || v_p
                              || jsonb_build_object('asked', v_row.arg),
             registry_at = now(),
             cr_national = CASE WHEN v_row.arg ~ '^7[0-9]{9}$' THEN v_row.arg ELSE cr_national END,
             confirmation_due = COALESCE((v_p->>'confirmation_due')::date, confirmation_due)
       WHERE id = v_row.ver_id;

      -- سلسلةُ المُلّاك — مُطفأةٌ افتراضاً لأنها مدفوعة
      IF (v_cfg->>'check_owners')::boolean AND (v_p->>'active')::boolean THEN
        PERFORM public._taki_wathq_enqueue(v_row.ver_id, 'owners', v_row.arg);
      END IF;
      v_ok := v_ok + 1;

    ELSIF v_row.kind = 'crnational' THEN
      v_nat := public._taki_wathq_parse_crnational(v_body);
      UPDATE public.store_verification_checks
         SET status = 'done', http_status = 200, cost_sar = v_price,
             result = jsonb_build_object('cr_national', v_nat), done_at = now()
       WHERE id = v_row.id;
      IF v_nat IS NOT NULL THEN
        UPDATE public.store_verifications SET cr_national = v_nat WHERE id = v_row.ver_id;
        PERFORM public._taki_wathq_enqueue(v_row.ver_id, 'status', v_nat);
      ELSE
        UPDATE public.store_verifications
           SET registry_state = jsonb_build_object('found', false, 'why', 'NO_NATIONAL_NUMBER'),
               registry_at = now()
         WHERE id = v_row.ver_id;
      END IF;
      v_ok := v_ok + 1;

    ELSE  -- owners
      v_p := public._taki_wathq_parse_owners(v_body);
      SELECT array_agg(x) INTO v_names
        FROM jsonb_array_elements_text(COALESCE(v_p->'names', '[]'::jsonb)) x;
      -- 🪤 المطابقةُ **تُحسب ولا تحكم**: تطابقُ الأسماء العربية بالتطبيع
      --    وحده يُخطئ في كلا الاتجاهين، فالقرارُ للمراجع والرقمُ معلومةٌ له.
      v_match := EXISTS (
        SELECT 1 FROM unnest(COALESCE(v_names, '{}')) n
         WHERE public.taki_norm(n) = public.taki_norm(COALESCE(v_ver.legal_name, v_ver.claimed_name, '')));
      UPDATE public.store_verification_checks
         SET status = 'done', http_status = 200, cost_sar = v_price,
             result = v_p || jsonb_build_object('name_match', v_match), done_at = now()
       WHERE id = v_row.id;
      UPDATE public.store_verifications
         SET registry_state = COALESCE(registry_state, '{}'::jsonb)
                              || jsonb_build_object('owner_names', COALESCE(v_p->'names', '[]'::jsonb),
                                                    'owner_name_match', v_match),
             registry_at = now()
       WHERE id = v_row.ver_id;
      v_ok := v_ok + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object('done', v_ok, 'retried', v_retry, 'dead', v_dead, 'waiting', v_wait);
END
$function$
;


-- ═══ FUNCTION taki_wathq_confirmation_sweep() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_wathq_confirmation_sweep()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_q int := 0; v_w int := 0; v_row record; v_msg text; v_left int; v_stage smallint;
BEGIN
  -- (أ) إعادةُ السؤال المجّانيّة لكلّ سجلٍّ موثَّقٍ لم يُسأل عنه منذ أسبوع
  IF public._taki_wathq_key() IS NOT NULL THEN
    FOR v_row IN
      SELECT v.id, COALESCE(v.cr_national, v.doc_number) AS num
        FROM public.store_verifications v
       WHERE v.status = 'approved' AND v.doc_kind = 'cr'
         AND (v.registry_at IS NULL OR v.registry_at < now() - interval '7 days')
       ORDER BY v.registry_at NULLS FIRST
       LIMIT 200
    LOOP
      IF public._taki_wathq_enqueue(v_row.id, 'status', v_row.num) IS NOT NULL THEN
        v_q := v_q + 1;
      END IF;
    END LOOP;
  END IF;

  -- (ب) تنبيهُ التأكيد السنويّ — بالمدى وعلامةٍ، كدرس v15.29
  FOR v_row IN
    SELECT id, store_id, (confirmation_due - current_date)::int AS days_left, warn_stage_conf
      FROM public.store_verifications
     WHERE status = 'approved' AND confirmation_due IS NOT NULL
       AND confirmation_due >= current_date
       AND (confirmation_due - current_date) <= 30
       AND warn_stage_conf < 2
     ORDER BY confirmation_due
  LOOP
    v_stage := CASE WHEN v_row.days_left <= 7 THEN 2 ELSE 1 END;
    CONTINUE WHEN v_stage <= v_row.warn_stage_conf;
    v_left := GREATEST(v_row.days_left, 0);
    -- 🪤 ولا يُكتب العددُ نصّاً: يُصاغ من الباقي الحقيقي.
    v_msg := 'ℹ️ يستحقّ **التأكيد السنويّ** لبيانات سجلك التجاري خلال '
          || public.taki_ar_days(v_left)
          || '. أكّده من منصّة المركز السعودي للأعمال — ولا يلزمك تجديدُ السجل، فالنظامُ الجديد ألغى تاريخَ الانتهاء.';
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data)
    VALUES (v_row.store_id, 'ℹ️ التأكيد السنويّ لسجلك', 'ℹ️ Annual CR confirmation due',
            v_msg, v_msg, 'system',
            jsonb_build_object('audience', 'seller', 'actionUrl', '/seller',
                               'action_url', '/seller', 'days_left', v_left,
                               'code', 'CR_ANNUAL_CONFIRMATION'));
    UPDATE public.store_verifications SET warn_stage_conf = v_stage WHERE id = v_row.id;
    v_w := v_w + 1;
  END LOOP;

  RETURN jsonb_build_object('queued', v_q, 'warned', v_w);
END
$function$
;


-- ═══ FUNCTION taki_wathq_dispatch(p_cap integer) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_wathq_dispatch(p_cap integer DEFAULT NULL::integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cfg jsonb; v_key text; v_row record; v_ep jsonb; v_url text; v_req bigint;
  v_cap int; v_spent numeric; v_sent int := 0; v_fail int := 0;
BEGIN
  v_cfg := public._taki_wathq_cfg();
  v_key := public._taki_wathq_key();
  IF v_key IS NULL THEN
    -- 🪤 ولا تُوسَم الصفوفُ فاشلةً: الاشتراكُ قد يأتي غداً، والطابورُ ينتظر.
    RETURN jsonb_build_object('sent', 0, 'skipped', 'NO_KEY');
  END IF;

  -- 🔴 سقفُ أمانٍ شهريّ: باقةُ واثق رصيدٌ يُستهلك، وخطأٌ في حلقةٍ قد يحرقه
  --    في ساعة. فالطابورُ يتوقّف — ولا يفشل — عند تجاوز السقف.
  SELECT COALESCE(sum(cost_sar), 0) INTO v_spent
    FROM public.store_verification_checks
   WHERE done_at >= date_trunc('month', now());
  IF v_spent >= (v_cfg->>'monthly_cap_sar')::numeric THEN
    RETURN jsonb_build_object('sent', 0, 'skipped', 'MONTHLY_CAP', 'spent', v_spent);
  END IF;

  v_cap := GREATEST(COALESCE(p_cap, (v_cfg->>'per_run_cap')::int, 60), 1);

  FOR v_row IN
    SELECT c.id, c.kind, c.arg
      FROM public.store_verification_checks c
     WHERE c.status = 'pending' AND c.due_at <= now()
     ORDER BY c.due_at, c.id
     LIMIT v_cap
  LOOP
    v_ep := v_cfg->'endpoints'->v_row.kind;
    IF v_ep IS NULL THEN
      UPDATE public.store_verification_checks
         SET status = 'failed', last_error = 'NO_DESCRIPTOR', done_at = now()
       WHERE id = v_row.id;
      v_fail := v_fail + 1; CONTINUE;
    END IF;

    -- الحجزُ قبل الإرسال، و`request_id IS NULL` علامةُ «حُجز ولم يُرسل».
    UPDATE public.store_verification_checks
       SET status = 'awaiting', request_id = NULL, sent_at = now(), attempts = attempts + 1
     WHERE id = v_row.id AND status = 'pending';
    IF NOT FOUND THEN CONTINUE; END IF;

    v_url := (v_cfg->>'base')
          || replace(v_ep->>'path', '{id}', public._taki_urlenc(v_row.arg))
          || CASE WHEN COALESCE(v_ep->>'query', '') = '' THEN ''
                  ELSE '?' || (v_ep->>'query') END;

    BEGIN
      -- 🔴 الترويسةُ اسمُها حرفياً `apiKey` — وتعريفُ الأمان في وثيقتهم
      --    مسمّىً «Authorization» وهو اسمٌ مُضلِّل لا ترويسة.
      v_req := net.http_get(
        url := v_url,
        headers := jsonb_build_object('apiKey', v_key, 'Accept', 'application/json'),
        timeout_milliseconds := 12000);
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.store_verification_checks
         SET status = 'pending', last_error = 'DISPATCH:' || left(SQLERRM, 120),
             due_at = now() + make_interval(secs => (60 * power(2, LEAST(attempts, 5)))::int)
       WHERE id = v_row.id;
      v_fail := v_fail + 1; CONTINUE;
    END;

    UPDATE public.store_verification_checks SET request_id = v_req WHERE id = v_row.id;
    v_sent := v_sent + 1;
  END LOOP;

  RETURN jsonb_build_object('sent', v_sent, 'failed', v_fail, 'spent_this_month', v_spent);
END
$function$
;


-- ═══ FUNCTION taki_worse(a text, b text) INVOKER owner=supabase_admin search_path=NOT_SET anon=YES ═══
CREATE OR REPLACE FUNCTION public.taki_worse(a text, b text)
 RETURNS text
 LANGUAGE sql
 IMMUTABLE
AS $function$
  -- 🪤 `GREATEST('crit','warn')` يُعيد 'warn' لأن المقارنة **أبجدية** — فحالةٌ
  -- حرجة تُخفَّض إلى تحذير بمجرّد وجود تحذيرٍ آخر معها. التصعيد يحتاج رتبةً
  -- صريحة لا ترتيب حروف.
  SELECT CASE WHEN 'crit' IN (a,b) THEN 'crit'
              WHEN 'warn' IN (a,b) THEN 'warn'
              ELSE 'ok' END;
$function$
;


-- ═══ FUNCTION taki_write_heartbeat(p_disk_pct integer, p_mem_pct integer, p_backup_age_hours numeric, p_site_code integer, p_bot_ok boolean) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_write_heartbeat(p_disk_pct integer, p_mem_pct integer, p_backup_age_hours numeric, p_site_code integer DEFAULT NULL::integer, p_bot_ok boolean DEFAULT NULL::boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_cron    jsonb := public.taki_cron_health();
  v_sat     jsonb := public.taki_saturation();
  v_dbmb    numeric := round(pg_database_size(current_database()) / 1048576.0, 1);
  v_issues  jsonb := '[]'::jsonb;
  v_status  text := 'ok';
  v_prev    text;
  v_notif   timestamptz;
  v_sent    int := 0;
  v_streak  int := 0;          -- v15.33 — نبضاتُ فشلِ البوت المتتالية
  v_dbwarn  numeric;           -- v15.80 ⟵ سقفُ الحجم من الإعداد لا من الكود
  r         record;
BEGIN
  SELECT coalesce(h.bot_fail_streak,0) INTO v_streak FROM public.system_heartbeat h WHERE h.id = 1;
  IF p_disk_pct >= 90 THEN v_status := 'crit'; v_issues := v_issues || to_jsonb(format('القرص ممتلئ %s%%', p_disk_pct));
  ELSIF p_disk_pct >= 75 THEN v_status := 'warn'; v_issues := v_issues || to_jsonb(format('القرص %s%%', p_disk_pct)); END IF;

  IF p_mem_pct >= 92 THEN v_status := 'crit'; v_issues := v_issues || to_jsonb(format('الذاكرة %s%%', p_mem_pct));
  ELSIF p_mem_pct >= 85 THEN v_status := public.taki_worse(v_status,'warn'); v_issues := v_issues || to_jsonb(format('الذاكرة %s%%', p_mem_pct)); END IF;

  IF p_backup_age_hours >= 36 THEN v_status := 'crit';
    v_issues := v_issues || to_jsonb(format('آخر نسخة احتياطية قبل %s ساعة', round(p_backup_age_hours))); END IF;

  IF (v_cron->>'failed_24h')::int > 0 THEN v_status := 'crit';
    v_issues := v_issues || to_jsonb(format('وظائف فشلت خلال ٢٤ ساعة: %s', v_cron->>'failed_names')); END IF;
  -- v15.24 neverran — `never_ran` كانت تُحسب ولا تُقرأ إطلاقاً: وظيفةٌ
  --   لم تعمل ولا مرّةً واحدة كانت **غيرَ مرئيّة**، وهي أسوأُ من
  --   المتوقّفة (تلك عملت يوماً ما). وتُقال برسالتها هي لا بتلك.
  IF (v_cron->>'never_ran_overdue')::int > 0 THEN v_status := 'crit';
    v_issues := v_issues || to_jsonb(format('وظائف لم تعمل ولا مرّة: %s', v_cron->>'never_ran_overdue_names')); END IF;
  IF (v_cron->>'stalled')::int > 0 THEN v_status := 'crit';
    v_issues := v_issues || to_jsonb(format('وظائف توقّفت عن العمل: %s', v_cron->>'stalled_names')); END IF;

  -- الموقع: NULL يعني «لم يُفحص» لا «سليم». 🪤 الفرق جوهري — لو عُوملت NULL
  -- نجاحاً لصار تعطّلُ أداة الفحص نفسها يُنتج «كل شيء بخير».
  IF p_site_code IS NULL THEN v_status := public.taki_worse(v_status,'warn');
    v_issues := v_issues || to_jsonb('الموقع لم يُفحص (أداة الفحص لم تُبلّغ)'::text);
  ELSIF p_site_code <> 200 THEN v_status := 'crit';
    v_issues := v_issues || to_jsonb(format('الموقع يردّ %s', p_site_code)); END IF;

  -- ── v15.33 · ارتدادٌ على نبضتين ────────────────────────────────────────
  -- قِيس على ٣٧٢٨ نبضةً في سجلّ الخادم: فشلُ البوت وقع **مرّةً واحدة**
  -- (٠٫٠٢٧٪)، والنبضتان المحيطتان بها `ok` — أي أنه لم يكن عطلاً بل لحظةَ
  -- إعادةِ تشغيلٍ تفعلها Render من تلقائها (الخطّة free، وقد أقلع البوت
  -- ٣٠ أكتوبر ٠٥:٣٤ وآخرُ نشرٍ كان ٢٨ أكتوبر). وكلفةُ تلك الصرخة الواحدة
  -- أنها تُدرّب ناصراً على تجاهل القناة التي يجب أن تصرخ يوم يقع عطلٌ حقّ.
  -- ⇒ نبضةٌ واحدة فاشلة ليست دليلاً؛ نبضتان (≈٢٠ دقيقة) دليل.
  -- 🪤 والتأخّرُ ثمنٌ مقصود: الكشفُ صار ≤٢٠ دقيقة بدل ≤١٠.
  -- 🪤 والموقعُ **لا يُمسّ**: فشلُه في السجلّ نفسه = صفر، فلا ضجيجَ يُسكَت،
  --    وعطلُه يراه المشتري. يُقاس قبل أن يُضبط.
  IF p_bot_ok IS NULL THEN
    -- لا معلومة ⇒ لا تغيير في العدّاد (لا تصفيرَ يُضيّع فشلاً سابقاً، ولا
    -- زيادةَ تتّهم البوت بعطل أداةِ الفحص). والتحذيرُ قائمٌ كما كان.
    v_status := public.taki_worse(v_status,'warn');
    v_issues := v_issues || to_jsonb('البوت لم يُفحص (أداة الفحص لم تُبلّغ)'::text);
  ELSIF NOT p_bot_ok THEN
    v_streak := v_streak + 1;
    IF v_streak >= 2 THEN v_status := 'crit';
      v_issues := v_issues || to_jsonb(format('البوت لا يستجيب منذ %s نبضات متتالية (≈%s دقيقة) — أو إحدى خدماته ساقطة',
        v_streak, v_streak * 10)::text);
    END IF;
  ELSE
    v_streak := 0;
  END IF;

  -- v15.80 ⟵ السقفُ من `capacity_limits` (الحيُّ ٣٩٤٦٣ م.ب)، وارتدادُه ٤٠٩٦
  -- فالسلوكُ لا يتغيّر إن غاب المفتاح. وكانت ٤٠٩٦ مثبَّتةً في الكود تخالف
  -- الإعدادَ الحيّ ⇒ تحذيرٌ دائمٌ ينتظر مرورَ الزمن.
  SELECT (value->>'db_size_warn_mb')::numeric INTO v_dbwarn
    FROM public.platform_settings WHERE key = 'capacity_limits';
  IF v_dbmb >= COALESCE(v_dbwarn, 4096) THEN v_status := public.taki_worse(v_status,'warn');
    v_issues := v_issues || to_jsonb(format('حجم القاعدة %s ميجابايت', v_dbmb)); END IF;

  -- ── v14.85: الاقتراب من السقف ─────────────────────────────────────────────
  -- سقفُ التزامن هو `max_connections`، ومسبح PostgREST يأكل منه. تجاوزُه يعني
  -- أن المستخدم التالي يُردّ بـ«too many connections» — وهو عطلٌ كامل لا بطء.
  IF (v_sat->>'conn_pct')::int >= 85 THEN v_status := 'crit';
    v_issues := v_issues || to_jsonb(format('اتصالات القاعدة %s%% من السقف (%s من %s) — المستخدم التالي قد يُردّ',
      v_sat->>'conn_pct', v_sat->>'conn', v_sat->>'max_conn'));
  ELSIF (v_sat->>'conn_pct')::int >= 70 THEN v_status := public.taki_worse(v_status,'warn');
    v_issues := v_issues || to_jsonb(format('اتصالات القاعدة %s%% من السقف — يقترب', v_sat->>'conn_pct'));
  END IF;

  -- استعلامٌ عالق يخنق المسبح قبل أن يمتلئ: عشر ثوانٍ لا مبرّر لها هنا،
  -- فأثقل استعلامٍ حقيقي قِيس **٩٫٤ ميلي ثانية**.
  IF (v_sat->>'longest_ms')::int >= 30000 THEN v_status := 'crit';
    v_issues := v_issues || to_jsonb(format('استعلام عالق منذ %s ثانية', round((v_sat->>'longest_ms')::numeric/1000)));
  ELSIF (v_sat->>'longest_ms')::int >= 10000 THEN v_status := public.taki_worse(v_status,'warn');
    v_issues := v_issues || to_jsonb(format('استعلام بطيء %s ثانية', round((v_sat->>'longest_ms')::numeric/1000)));
  END IF;

  SELECT last_status, notified_at INTO v_prev, v_notif FROM public.system_heartbeat WHERE id = 1;

  UPDATE public.system_heartbeat SET
    seen_at = now(), status = v_status, issues = v_issues, last_status = v_status,
    bot_fail_streak = v_streak,
    metrics = jsonb_build_object('disk_pct', p_disk_pct, 'mem_pct', p_mem_pct,
                                 'db_mb', v_dbmb, 'backup_age_hours', round(p_backup_age_hours,1),
                                 'site_code', p_site_code, 'bot_ok', p_bot_ok, 'cron', v_cron,
                                 'bot_fail_streak', v_streak,
                                 'saturation', v_sat)
  WHERE id = 1;

  -- التنبيه: عند **دخول** حالة حرجة، أو مرّة كل ست ساعات ما دامت قائمة.
  IF v_status = 'crit'
     AND (v_prev IS DISTINCT FROM 'crit' OR v_notif IS NULL OR v_notif < now() - interval '6 hours') THEN
    FOR r IN SELECT u.id FROM public.users u WHERE u.user_type = 'admin' AND u.deleted_at IS NULL LOOP
      INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
      VALUES (r.id, '🚨 تنبيه الخادم', '🚨 Server alert',
              array_to_string(ARRAY(SELECT jsonb_array_elements_text(v_issues)), E'\n'),
              array_to_string(ARRAY(SELECT jsonb_array_elements_text(v_issues)), E'\n'),
              'system', jsonb_build_object('audience','admin','heartbeat',true), now());
      v_sent := v_sent + 1;
    END LOOP;

    -- v15.80 ⟵ ساقٌ ثانية، **إضافيّةٌ** لا بديلة: الإشعارُ أعلاه يبقى كما هو
    -- (مركزُ الإشعارات ودفعُ الويب)، وهذا بريدٌ لا يمرّ بالبوت ولا بمفتاح
    -- إطفائه ولا بصندوقه الصادر. ومرّةً واحدةً لكلّ دخولِ حالةٍ حرجة لا
    -- لكلّ أدمن — فهو **داخلَ** التهدئة لا داخلَ الحلقة.
    -- 🪤 ومحاطٌ بمعالِجٍ خاصٍّ به: النبضُ لا يسقط لأجل بريدٍ فاشل، والسببُ
    --    مسجَّلٌ في `taki_alert_log` فلا يصير الابتلاعُ عمًى.
    BEGIN
      PERFORM public.taki_alert_dispatch(
        '🚨 تنبيه خادم تاكي · TAKI server alert',
        array_to_string(ARRAY(SELECT jsonb_array_elements_text(v_issues)), E'\n'),
        'crit', 'heartbeat');
    EXCEPTION WHEN OTHERS THEN
      NULL;
    END;

    UPDATE public.system_heartbeat SET notified_at = now() WHERE id = 1;
  END IF;

  RETURN jsonb_build_object('status', v_status, 'issues', v_issues, 'notified', v_sent, 'saturation', v_sat);
END $function$
;


-- ═══ FUNCTION taki_zatca_tlv(p_seller text, p_vat text, p_iso text, p_total text, p_vat_amt text) INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.taki_zatca_tlv(p_seller text, p_vat text, p_iso text, p_total text, p_vat_amt text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  vals  text[] := ARRAY[
    public.taki_utf8_clip(p_seller),  public.taki_utf8_clip(p_vat),
    public.taki_utf8_clip(p_iso),     public.taki_utf8_clip(p_total),
    public.taki_utf8_clip(p_vat_amt)
  ];
  buf   bytea := '\x'::bytea;
  b     bytea;
  i     int;
BEGIN
  FOR i IN 1..5 LOOP
    b := convert_to(COALESCE(vals[i], ''), 'UTF8');
    buf := buf
        || set_byte('\x00'::bytea, 0, i)                      -- الوسم
        || set_byte('\x00'::bytea, 0, octet_length(b))        -- الطول (بايت واحد)
        || b;                                                 -- القيمة
  END LOOP;
  -- 🪤 `encode(...,'base64')` يلفّ كل ٧٦ محرفاً — والرمز يجب أن يكون سطراً واحداً.
  RETURN translate(encode(buf, 'base64'), E'\n\r', '');
END $function$
;


-- ═══ FUNCTION tg_branch_cap_on_package_change() DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tg_branch_cap_on_package_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_pkg_max integer;
BEGIN
  IF NEW.subscription_package_id IS NULL THEN RETURN NEW; END IF;

  SELECT GREATEST(1, (e->>'max')::int) INTO v_pkg_max
    FROM jsonb_array_elements(
           (SELECT value FROM platform_settings WHERE key = 'location_packages')) e
   WHERE NULLIF(e->>'id','') IS NOT NULL
     AND (e->>'id')::int = NEW.subscription_package_id
   LIMIT 1;

  IF v_pkg_max IS NULL THEN RETURN NEW; END IF;

  IF NEW.max_branches IS DISTINCT FROM v_pkg_max THEN
    UPDATE public.store_profiles
       SET max_branches = v_pkg_max, updated_at = NOW()
     WHERE store_id = NEW.store_id;
  END IF;
  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tg_branch_display_on_plan_change() DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tg_branch_display_on_plan_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    PERFORM public.taki_reconcile_branch_display(NEW.store_id);
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tg_enforce_branch_display_cap() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tg_enforce_branch_display_cap()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_cap integer; v_shown integer;
BEGIN
    IF NOT NEW.show_on_store_page THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND OLD.show_on_store_page THEN RETURN NEW; END IF;

    SELECT max_branches INTO v_cap FROM public.store_profiles WHERE store_id = NEW.merchant_id;
    IF v_cap IS NULL OR v_cap <= 0 THEN RETURN NEW; END IF;

    SELECT count(*) INTO v_shown FROM public.store_branches
     WHERE merchant_id = NEW.merchant_id AND show_on_store_page
       AND COALESCE(is_active, true) AND id <> NEW.id;

    IF v_shown >= v_cap THEN
        RAISE EXCEPTION 'BRANCH_DISPLAY_CAP:%', v_cap USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tg_sellers_public_readonly() INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tg_sellers_public_readonly()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    RAISE EXCEPTION
        'sellers_public هو دليل قراءة فقط — الكتابة تتم على جدول users عبر سياساته'
        USING ERRCODE = 'insufficient_privilege';
END;
