-- ═══ FUNCTION tg_unfreeze_on_upgrade() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tg_unfreeze_on_upgrade()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.max_branches IS NOT NULL AND OLD.max_branches IS NOT NULL
     AND NEW.max_branches > OLD.max_branches THEN
    PERFORM public.taki_unfreeze_deals_within_cap(NEW.store_id);
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION toggle_rating_like(p_rating_id text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.toggle_rating_like(p_rating_id text)
 RETURNS TABLE(rating_id text, like_count integer, liked boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid text := (auth.uid())::text;
    v_already boolean;
BEGIN
    IF v_uid IS NULL THEN
        RAISE EXCEPTION 'auth required';
    END IF;
    SELECT v_uid = ANY (r.liked_by) INTO v_already FROM public.ratings r WHERE r.id = p_rating_id;
    IF v_already IS NULL THEN
        RAISE EXCEPTION 'rating not found';
    END IF;
    IF v_already THEN
        UPDATE public.ratings
            SET liked_by = array_remove(liked_by, v_uid),
                like_count = GREATEST(like_count - 1, 0),
                updated_at = now()
            WHERE id = p_rating_id;
        RETURN QUERY SELECT p_rating_id, GREATEST((SELECT like_count FROM public.ratings WHERE id = p_rating_id), 0), false;
    ELSE
        UPDATE public.ratings
            SET liked_by = array_append(liked_by, v_uid),
                like_count = like_count + 1,
                updated_at = now()
            WHERE id = p_rating_id;
        RETURN QUERY SELECT p_rating_id, (SELECT like_count FROM public.ratings WHERE id = p_rating_id), true;
    END IF;
END $function$
;


-- ═══ FUNCTION tr_ad_set_booking_hold() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_ad_set_booking_hold()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_booked bigint;
BEGIN
  v_booked := COALESCE(NEW.booked_at, (EXTRACT(EPOCH FROM NOW())*1000)::bigint);
  NEW.booked_at   := v_booked;
  -- ⚠️ الدرس المدفوع (v12.07): لا تُقصّ المهلة إلى نهاية العرض إطلاقاً.
  -- v15.43 — والمهلةُ مهلةُ **هذا المتجر**: استثناؤه إن وُجد، وإلّا المنصّة.
  NEW.expiry_time := v_booked
    + (public.taki_booking_hold_hours(COALESCE(NEW.fulfillment,'pickup'), NEW.store_id) * 3600000)::bigint;
  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_ae_set_booking_total() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_ae_set_booking_total()
