END
$function$
;


-- ═══ FUNCTION tr_af_order_invoice_draft() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_af_order_invoice_draft()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_total  numeric;
  v_rate   numeric;
  v_base   numeric;
  v_vat    numeric;
  v_vat_no text;
  v_cr     text;
  v_addr   text;
  v_name   text;
BEGIN
  v_total := round(COALESCE(NEW.total_amount, 0), 2);

  SELECT sp.vat_number, sp.cr_number, sp.address
    INTO v_vat_no, v_cr, v_addr
    FROM public.store_profiles sp WHERE sp.store_id = NEW.store_id;

  SELECT COALESCE(NULLIF(u.shop, ''), u.name)
    INTO v_name
    FROM public.users u WHERE u.id = NEW.store_id;

  -- الضريبة تظهر **برقم التاجر وحده**. ولا خيار «فوق السعر» في التجزئة:
  -- السعر المعلن للمستهلك شامل الضريبة، فالضريبة تُستخرج منه لا تُضاف إليه.
  IF public.taki_is_saudi_vat(v_vat_no) AND v_total > 0 THEN
    v_rate := public.taki_merchant_vat_rate();
    v_base := round(v_total / (1 + v_rate / 100), 2);
    v_vat  := round(v_total - v_base, 2);
  END IF;

  INSERT INTO public.order_invoices
    (barcode, store_id, buyer_id, total, vat_rate, vat_base, vat_amount, seller)
  VALUES (
    NEW.barcode, NEW.store_id, NEW.user_id, v_total, v_rate, v_base, v_vat,
    jsonb_strip_nulls(jsonb_build_object(
      'name',       NULLIF(btrim(COALESCE(v_name, '')), ''),
      'vat_number', NULLIF(btrim(COALESCE(v_vat_no, '')), ''),
      'cr_number',  NULLIF(btrim(COALESCE(v_cr, '')), ''),
      'address',    NULLIF(btrim(COALESCE(v_addr, '')), '')
    )))
  ON CONFLICT (barcode) DO NOTHING;

  RETURN NULL;
END
$function$
;


-- ═══ FUNCTION tr_ag_stamp_ack() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_ag_stamp_ack()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.acknowledged_at := NULL;          -- كلُّ حجزٍ يبدأ `pending`
    RETURN NEW;
  END IF;
  IF NEW.status = 'acknowledged' AND COALESCE(OLD.status,'') <> 'acknowledged' THEN
    NEW.acknowledged_at := now();
  ELSE
    NEW.acknowledged_at := OLD.acknowledged_at;
  END IF;
  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_assign_invoice_no() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_assign_invoice_no()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_no bigint;
BEGIN
  IF NEW.invoice_no IS NOT NULL THEN RETURN NEW; END IF;
  INSERT INTO public.taki_invoice_counter (id, last_seq)
  VALUES (true, 1)
  ON CONFLICT (id) DO UPDATE
    SET last_seq = public.taki_invoice_counter.last_seq + 1, updated_at = now()
  RETURNING last_seq INTO v_no;
  NEW.invoice_no := v_no;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_bm_force_sender() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_bm_force_sender()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_party text;
BEGIN
  SELECT CASE WHEN NEW.sender_role = 'buyer' THEN b.user_id ELSE b.store_id END
    INTO v_party
    FROM public.bookings b
   WHERE b.barcode = NEW.barcode;

  -- حجزٌ غيرُ موجود: يُترك العمودُ كما هو ليفشلَ الإدراجُ بخطأ المفتاح
  -- الأجنبيّ الصريح، لا بخطأ `NULL` مُضلِّل.
  IF v_party IS NOT NULL THEN
    NEW.sender_id := v_party;
  END IF;

  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_booking_message_recipient() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_booking_message_recipient()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    SELECT CASE WHEN NEW.sender_role = 'buyer' THEN b.store_id ELSE b.user_id END
      INTO NEW.recipient_id
      FROM bookings b
     WHERE b.barcode = NEW.barcode;
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_close_delivery_track() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_close_delivery_track()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status IN ('completed','cancelled') AND coalesce(OLD.status,'') <> NEW.status THEN
    UPDATE public.delivery_tracks
       SET status = CASE WHEN NEW.status = 'completed' THEN 'delivered' ELSE 'cancelled' END,
           lat = NULL, lng = NULL, accuracy_m = NULL, heading = NULL, speed_kmh = NULL,
           remaining_km = NULL, eta_min = NULL,
           ended_at = now(), updated_at = now()
     WHERE barcode = NEW.barcode;
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_guard_booking_delete() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_booking_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF EXISTS (SELECT 1 FROM public.order_invoices oi
              WHERE oi.barcode = OLD.barcode AND oi.invoice_no IS NOT NULL) THEN
    RAISE EXCEPTION
      'TAKI_INVOICE_ISSUED: صدرت لهذا الطلب فاتورة ضريبية مرقَّمة، وحذفه يُسقطها ويترك فجوة في تسلسل التاجر.'
      USING ERRCODE = 'P0001', HINT = 'P0016';
  END IF;
  RETURN OLD;
END
$function$
;


-- ═══ FUNCTION tr_guard_booking_delivery() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_booking_delivery()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_q     jsonb;
  v_sell  jsonb;
  v_lat   float8;
  v_lng   float8;
  v_min   numeric;
  v_est   numeric;
BEGIN
  -- v14.08 (بلاغ ناصر ٨): لا بيع قبل أن يُقرّ التاجر كيف يُحاسِب. يسري على
  -- الاستلام والتوصيل معاً — متجرٌ بلا طريقة حساب لا يُحجز منه أصلاً.
  v_sell := public.store_can_sell(NEW.store_id);
  IF NOT coalesce((v_sell->>'ok')::boolean, false) THEN
    RAISE EXCEPTION 'TAKI_STORE_NO_PAYMENT:%', coalesce(v_sell->>'reason','not_declared')
      USING ERRCODE = 'P0001', HINT = 'P0013';
  END IF;
  -- ونقدٌ لا يقبله التاجر لا يُفرض عليه.
  -- 🔴 v15.44 — والمرجعُ صار `deal_payment_mode()` لا `accepts_cod` الخام، لأن
  --    الثاني **ينحرف عن المعروض للمشتري**. قِيس على متجر ناصر يوم ٢ نوفمبر:
  --    `accepts_cod=false` بينما `payment_modes='both'` ⇒ صفحةُ العرض تعرض
  --    «الدفع عند الاستلام» (تقرأ `deal_payment_mode`) والحارسُ يرفضه (يقرأ
  --    `accepts_cod`) ⇒ كلُّ مشترٍ يختار النقد يُرفض حجزُه بلا سببٍ مفهوم.
  --    و`deal_payment_mode` هو المصدرُ الذي تقرؤه الواجهة فعلاً، وهو يُسقط
  --    البوّابةَ المعطوبة إلى 'cod' وحده — فقراءتُه تُغلق الباب على الانحراف
  --    كلِّه بدل ترقيع قارئٍ بعد قارئ.
  -- 🪤 والحالةُ «أقرّ بطاقةً فقط بلا بوّابة» لا تمرّ من هنا أصلاً:
  --    `store_can_sell` تردّها قبلَه بـ`no_method`.
  IF coalesce(NEW.payment_method,'cod') = 'cod'
     AND public.deal_payment_mode(NEW.store_id) = 'online' THEN
    RAISE EXCEPTION 'TAKI_STORE_CARD_ONLY' USING ERRCODE = 'P0001', HINT = 'P0013';
  END IF;

  IF coalesce(NEW.fulfillment, 'pickup') <> 'delivery' THEN
    NEW.fulfillment := 'pickup';
    NEW.delivery_address := NULL;
    NEW.delivery_fee := NULL;
    RETURN NEW;
  END IF;

  IF NEW.delivery_address IS NULL OR jsonb_typeof(NEW.delivery_address) <> 'object' THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_NO_ADDRESS' USING ERRCODE = 'P0001', HINT = 'P0013';
  END IF;
  v_lat := nullif(NEW.delivery_address->>'lat', '')::float8;
  v_lng := nullif(NEW.delivery_address->>'lng', '')::float8;
  IF v_lat IS NULL OR v_lng IS NULL THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_NO_ADDRESS' USING ERRCODE = 'P0001', HINT = 'P0013';
  END IF;

  -- ⚠️ v14.08 (بلاغ ناصر ١): النطاق يُقاس بفرع **هذا الحجز** لا بالمتجر كله،
  -- فلا يوصّل فرعُ الباحة إلى عنوانٍ داخل نطاق فرع الخبر.
  v_q := public.delivery_quote(NEW.store_id, v_lat, v_lng, NEW.location_id);
  IF NOT coalesce((v_q->>'enabled')::boolean, false) THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_OFF' USING ERRCODE = 'P0001', HINT = 'P0013';
  END IF;
  IF NOT coalesce((v_q->>'available')::boolean, false) THEN
    RAISE EXCEPTION 'TAKI_DELIVERY_OUT_OF_ZONE' USING ERRCODE = 'P0001', HINT = 'P0013';
  END IF;

  IF v_q->>'payment' = 'card' THEN
    IF coalesce(NEW.payment_method, 'cod') <> 'online' THEN
      RAISE EXCEPTION 'TAKI_DELIVERY_CARD_ONLY' USING ERRCODE = 'P0001', HINT = 'P0013';
    END IF;
  ELSIF v_q->>'payment' = 'cod' THEN
    NEW.payment_method := 'cod';
  END IF;

  -- v14.11 — قيمة البضاعة من الصيغة الواحدة (بضاعة + إضافات، بلا رسوم).
  v_min := coalesce((v_q->>'min_order')::numeric, 0);
  IF v_min > 0 THEN
    v_est := (public.taki_booking_amount(NEW.deal_id, NEW.booked_quantity, NEW.selected_options, 0)->>'goods')::numeric;
    IF coalesce(v_est, 0) < v_min THEN
      RAISE EXCEPTION 'TAKI_DELIVERY_MIN_ORDER:%', v_min USING ERRCODE = 'P0001', HINT = 'P0013';
    END IF;
  END IF;

  NEW.delivery_fee := coalesce((v_q->>'fee')::numeric, 0);
  NEW.delivery_address := jsonb_strip_nulls(jsonb_build_object(
    'label',   left(coalesce(NEW.delivery_address->>'label', ''), 60),
    'details', left(coalesce(NEW.delivery_address->>'details', ''), 300),
    'city',    left(coalesce(NEW.delivery_address->>'city', ''), 60),
    'phone',   left(coalesce(NEW.delivery_address->>'phone', ''), 20),
    'lat',     v_lat,
    'lng',     v_lng,
    'zone_id', v_q->>'zone_id'));
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_guard_booking_integrity() INVOKER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_guard_booking_integrity()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- The lifecycle RPCs, pg_cron and the payment function all run as the owner.
  -- 🪤 `INVOKER` عمداً: `current_user` هنا هو المنادي الحقيقيّ.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF coalesce(NEW.status, 'pending') <> 'pending' THEN
      RAISE EXCEPTION 'forbidden: a new booking must start as pending'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.paid_at          IS NOT NULL
    OR NEW.paid_amount      IS NOT NULL
    OR NEW.payment_provider IS NOT NULL
    OR NEW.payment_ref      IS NOT NULL
    OR NEW.payment_expected IS NOT NULL
    OR NEW.total_amount     IS NOT NULL
    OR NEW.completed_at     IS NOT NULL
    OR NEW.completed_by     IS NOT NULL
    OR NEW.cancelled_by     IS NOT NULL
    OR NEW.merchant_note    IS NOT NULL THEN
      RAISE EXCEPTION 'forbidden: payment and lifecycle fields are set by the server'
        USING ERRCODE = '42501';
    END IF;
    RETURN NEW;
  END IF;

  -- UPDATE from a client session: identity, money, stock and lifecycle frozen.
  -- 🪤 سياسةُ RLS **لا تستطيع** قولَ هذا: بوستجرس لا يُمرّر `OLD` إلى
  --    السياسات، فهذه القائمةُ هي الموضعُ الوحيدُ الممكن. عمودٌ يُحذف منها
  --    يصير مكتوباً للطرفين فوراً وبلا أيّ صوت.
  IF NEW.barcode          IS DISTINCT FROM OLD.barcode
  OR NEW.backup_code      IS DISTINCT FROM OLD.backup_code
  OR NEW.deal_id          IS DISTINCT FROM OLD.deal_id
  OR NEW.user_id          IS DISTINCT FROM OLD.user_id
  OR NEW.store_id         IS DISTINCT FROM OLD.store_id
  OR NEW.booked_quantity  IS DISTINCT FROM OLD.booked_quantity
  OR NEW.booked_at        IS DISTINCT FROM OLD.booked_at
  OR NEW.expiry_time      IS DISTINCT FROM OLD.expiry_time
  OR NEW.status           IS DISTINCT FROM OLD.status
  OR NEW.completed_at     IS DISTINCT FROM OLD.completed_at
  OR NEW.completed_by     IS DISTINCT FROM OLD.completed_by
  OR NEW.paid_at          IS DISTINCT FROM OLD.paid_at
  OR NEW.paid_amount      IS DISTINCT FROM OLD.paid_amount
  OR NEW.payment_provider IS DISTINCT FROM OLD.payment_provider
  OR NEW.payment_ref      IS DISTINCT FROM OLD.payment_ref
  OR NEW.payment_expected IS DISTINCT FROM OLD.payment_expected
  OR NEW.total_amount     IS DISTINCT FROM OLD.total_amount
  OR NEW.payment_method   IS DISTINCT FROM OLD.payment_method
  OR NEW.selected_options IS DISTINCT FROM OLD.selected_options
  OR NEW.cancelled_by     IS DISTINCT FROM OLD.cancelled_by
  OR NEW.merchant_note    IS DISTINCT FROM OLD.merchant_note
  OR NEW.location_id      IS DISTINCT FROM OLD.location_id
  OR NEW.fulfillment      IS DISTINCT FROM OLD.fulfillment
  OR NEW.delivery_address IS DISTINCT FROM OLD.delivery_address
  OR NEW.refund_state     IS DISTINCT FROM OLD.refund_state
  OR NEW.refund_claimed_at IS DISTINCT FROM OLD.refund_claimed_at
  OR NEW.refunded_at      IS DISTINCT FROM OLD.refunded_at
  OR NEW.refund_ref       IS DISTINCT FROM OLD.refund_ref
  OR NEW.refund_amount    IS DISTINCT FROM OLD.refund_amount
  OR NEW.refund_reason    IS DISTINCT FROM OLD.refund_reason
  OR NEW.refund_by        IS DISTINCT FROM OLD.refund_by
  OR NEW.delivery_fee     IS DISTINCT FROM OLD.delivery_fee
  -- v15.79 — هويّةُ المشتري وملاحظتُه وتاريخُ الطلب
  OR NEW.user_name        IS DISTINCT FROM OLD.user_name
  OR NEW.user_phone       IS DISTINCT FROM OLD.user_phone
  OR NEW.notes            IS DISTINCT FROM OLD.notes
  OR NEW.created_at       IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'forbidden: booking payment and lifecycle fields are server-managed'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_guard_bot_channel_disclosure() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_bot_channel_disclosure()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_on boolean; v_disclosed boolean;
BEGIN
  IF NEW.key NOT IN ('telegram_bot_enabled', 'whatsapp_bot_enabled') THEN
    RETURN NEW;
  END IF;

  -- قيمةٌ ليست بوليانيّةً تُعَدّ إطفاءً فلا تُحرَس (وتُرفض لاحقاً عند القراءة)
  BEGIN
    v_on := COALESCE(NEW.value::boolean, false);
  EXCEPTION WHEN others THEN
    RETURN NEW;
  END;
  IF NOT v_on THEN RETURN NEW; END IF;                 -- الإطفاءُ حرٌّ دائماً

  v_disclosed := COALESCE(
    (SELECT value::boolean FROM public.platform_settings WHERE key = 'bot_channels_disclosed'),
    false);

  IF NOT v_disclosed THEN
    RAISE EXCEPTION
      'BOT_CHANNEL_NOT_DISCLOSED'
      USING HINT = 'BOT_CHANNEL_NOT_DISCLOSED',
            DETAIL = 'تشغيلُ «' || NEW.key || '» يُعيد معالجةَ بياناتٍ شخصيةٍ عبر قناةٍ '
                   || 'أُسقط إفصاحُها من سياسة الخصوصية في v15.80 بقرار المالك. '
                   || 'أعِد الإفصاحَ أوّلاً في src/pages/legal/Privacy.tsx (نطاقُ السياسة · '
                   || 'ما نجمعه · مصادرُ الجمع · النقلُ خارج المملكة) ووصفَ التجّار في '
                   || 'index.html، وارفع LEGAL_VERSION، ثمّ اضبط '
                   || 'platform_settings.bot_channels_disclosed = true وأعِد المحاولة.';
  END IF;
  RETURN NEW;
END $function$
;


-- ═══ FUNCTION tr_guard_delivery_zone() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_delivery_zone()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_n int;
  v_pt jsonb;
  v_cnt int;
BEGIN
  IF NEW.store_id IS NULL THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:store' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = NEW.store_id AND u.user_type IN ('seller','admin')) THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:not_store' USING ERRCODE = '42501';
  END IF;

  NEW.name := nullif(left(btrim(coalesce(NEW.name, '')), 60), '');
  NEW.branch_id := nullif(btrim(coalesce(NEW.branch_id, '')), '');
  -- v14.08 — الفرع إمّا 'primary' (موقع المتجر) أو فرعٌ يملكه هذا المتجر.
  IF NEW.branch_id IS NOT NULL AND NEW.branch_id <> 'primary'
     AND NOT EXISTS (SELECT 1 FROM public.store_branches b
                      WHERE b.id = NEW.branch_id AND b.merchant_id = NEW.store_id) THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:branch' USING ERRCODE = '23514';
  END IF;

  IF NEW.fee IS NOT NULL AND (NEW.fee < 0 OR NEW.fee > 1000) THEN
    RAISE EXCEPTION 'TAKI_ZONE_BAD:fee' USING ERRCODE = '23514';
  END IF;

  IF NEW.kind = 'circle' THEN
    IF NEW.center_lat IS NULL OR NEW.center_lng IS NULL OR NEW.radius_km IS NULL
       OR NEW.center_lat NOT BETWEEN -90 AND 90 OR NEW.center_lng NOT BETWEEN -180 AND 180
       OR NEW.radius_km < 0.2 OR NEW.radius_km > 200 THEN
      RAISE EXCEPTION 'TAKI_ZONE_BAD:circle' USING ERRCODE = '23514';
    END IF;
    NEW.points := NULL;
  ELSE
    IF NEW.points IS NULL OR jsonb_typeof(NEW.points) <> 'array' THEN
      RAISE EXCEPTION 'TAKI_ZONE_BAD:points' USING ERRCODE = '23514';
    END IF;
    v_n := jsonb_array_length(NEW.points);
    IF (NEW.kind = 'rect' AND v_n <> 2) OR (NEW.kind = 'polygon' AND (v_n < 3 OR v_n > 80)) THEN
      RAISE EXCEPTION 'TAKI_ZONE_BAD:points_count' USING ERRCODE = '23514';
    END IF;
    FOR v_pt IN SELECT * FROM jsonb_array_elements(NEW.points) LOOP
      IF jsonb_typeof(v_pt) <> 'array' OR jsonb_array_length(v_pt) <> 2
         OR jsonb_typeof(v_pt->0) <> 'number' OR jsonb_typeof(v_pt->1) <> 'number'
         OR (v_pt->>0)::float8 NOT BETWEEN -90 AND 90 OR (v_pt->>1)::float8 NOT BETWEEN -180 AND 180 THEN
        RAISE EXCEPTION 'TAKI_ZONE_BAD:point' USING ERRCODE = '23514';
      END IF;
    END LOOP;
    NEW.center_lat := NULL; NEW.center_lng := NULL; NEW.radius_km := NULL;
  END IF;

  IF TG_OP = 'INSERT' OR (NEW.is_active AND NOT OLD.is_active) THEN
    SELECT count(*) INTO v_cnt FROM public.store_delivery_zones z
     WHERE z.store_id = NEW.store_id AND z.is_active AND z.id <> NEW.id;
    IF v_cnt >= 10 THEN
      RAISE EXCEPTION 'TAKI_ZONE_CAP:10' USING ERRCODE = '23514';
    END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_guard_fake_sub_payment() INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_fake_sub_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- `simulated` تعني حرفياً «لم يمرّ مال». وصفٌّ بمبلغٍ موجب وحالة «مدفوعة»
  -- يدخل الإيرادَ والإقرارَ الضريبيّ ويحرق رقمَ فاتورة — فلا يُقبل بلا مزوّد.
  -- 🪤 ويُسمح بـ`admin_grant` (تحويلٌ بنكيّ قبضه ناصر وسجّله)، وبالمبلغ صفر،
  --    وبحالة `gifted`، وبأيّ مزوّدٍ حقيقيّ (ميسر/تاب/باي‑تابس…).
  IF lower(COALESCE(NEW.status, '')) = 'paid'
     AND COALESCE(NEW.amount, 0) > 0
     AND lower(COALESCE(NEW.gateway_provider, '')) IN ('', 'simulated', 'sim') THEN
    RAISE EXCEPTION 'دفعةُ اشتراكٍ «مدفوعة» بمبلغ % بلا مزوّدٍ حقيقيّ — لا تُسجَّل', NEW.amount
      USING ERRCODE = 'P0001', HINT = 'P0030';
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_guard_message_block() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_message_block()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_b      public.bookings;
  v_actor  text;
  v_other  text;
  v_since  timestamptz;
  v_allow  int;
  v_sent   int;
  v_att    text := NULLIF(btrim(COALESCE(NEW.attachment_path, '')), '');
BEGIN
  SELECT * INTO v_b FROM public.bookings WHERE barcode = NEW.barcode;
  -- حجزٌ غيرُ موجود: يُترك للمفتاح الأجنبيّ ليرفضه بخطأٍ صريح، لا يُبتلع هنا.
  IF NOT FOUND THEN RETURN NEW; END IF;

  -- (أ) محادثةٌ مغلقة. نصُّ الرفض ورمزُه منسوخان حرفياً من `send_booking_message`
  --     الحيّة (`P0001` بلا HINT) — مفرداتُ الأخطاء لا تُخترع نسخةٌ ثانية منها.
  IF v_b.status IN ('cancelled', 'completed', 'expired') THEN
    RAISE EXCEPTION 'انتهى هذا الطلب — المحادثة للقراءة فقط' USING ERRCODE = 'P0001';
  END IF;

  -- (ب) المرفق: تحت مجلّد هذا الحجز، وموجودٌ فعلاً.
  --     🪤 ولا فحصَ مِلكيّةٍ هنا: البوتُ لا يحمل `auth.uid()` إطلاقاً، فشرطُ
  --        `o.owner = auth.uid()` يبقى في دالّة الويب حيث يصحّ وحدها.
  IF v_att IS NOT NULL THEN
    IF split_part(v_att, '/', 1) <> NEW.barcode THEN
      RAISE EXCEPTION 'المرفق لا يخصّ هذا الطلب' USING ERRCODE = 'P0001', HINT = 'P0017';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM storage.objects o
                    WHERE o.bucket_id = 'chat' AND o.name = v_att) THEN
      RAISE EXCEPTION 'المرفق غير موجود' USING ERRCODE = 'P0001', HINT = 'P0017';
    END IF;
  END IF;

  -- (ج) 🔴 الفاعلُ من `sender_role` لا من `sender_id`: الثاني يكتبه العميل،
  --     والأوّلُ وحده ما تربطه سياسةُ RLS بـ`uid()` وما يعتمده
  --     `tr_booking_message_recipient`.
  v_actor := CASE WHEN NEW.sender_role = 'buyer' THEN v_b.user_id  ELSE v_b.store_id END;
  v_other := CASE WHEN NEW.sender_role = 'buyer' THEN v_b.store_id ELSE v_b.user_id  END;

  v_since := public.taki_block_since(v_actor, v_other);
  IF v_since IS NULL THEN RETURN NEW; END IF;

  -- محجوبان. والاستثناءُ الوحيد: طلبٌ مفتوحٌ (ثبت أعلاه) **ومدفوعٌ أو توصيل**.
  IF v_b.paid_at IS NULL AND COALESCE(v_b.fulfillment, '') <> 'delivery' THEN
    RAISE EXCEPTION 'لا يمكن إرسال رسالة في هذه المحادثة'
      USING ERRCODE = 'P0001', HINT = 'P0032';
  END IF;

  -- والعددُ **من لحظة الحجب**: لو حُسب من أوّل المحادثة لبلغ سقفَه فوراً من
  -- تحدّث قبل الحجب — فيعود التوصيلُ عالقاً وهو ما جاء الاستثناءُ لأجله.
  v_allow := (public.taki_chat_limits()->>'blocked_inflight')::int;
  SELECT count(*) INTO v_sent
    FROM public.booking_messages
   WHERE barcode = NEW.barcode
     AND sender_role = NEW.sender_role
     AND created_at >= v_since;

  IF v_allow <= 0 OR v_sent >= v_allow THEN
    RAISE EXCEPTION 'تعذّر إرسال المزيد من الرسائل على هذا الطلب — تواصل مع الطرف الآخر مباشرة'
      USING ERRCODE = 'P0001', HINT = 'P0033';
  END IF;

  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_guard_order_code_numeric() INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_order_code_numeric()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.barcode IS NULL OR NEW.barcode !~ '^[1-9][0-9]{5,}$' THEN
    -- الرسالة مكتوبةٌ للمشتري لا للمطوّر: أكثرُ من سيصطدم بها هو متصفّحٌ
    -- عالقٌ على نسخةٍ قديمة من التطبيق (iOS يثبت على البناء القديم)، وما
    -- يحتاجه ليس تشخيصاً بل فعلاً واحداً واضحاً.
    RAISE EXCEPTION 'رقم الطلب يجب أن يكون أرقاماً فقط. حدِّث التطبيق ثم أعد المحاولة.'
      USING ERRCODE = 'P0001', HINT = 'P0026';
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_guard_rating_purchase() INVOKER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_guard_rating_purchase()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- Trusted server paths: the bot RPCs, admin tooling and pg_cron all run as
  -- the owner. The bot's own flow is barcode-driven, so it is gated already.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  -- v15.79 — هويّةُ المراجعة مجمّدةٌ بعد الإنشاء (قبل أيّ إعفاء).
  IF TG_OP = 'UPDATE' THEN
    IF NEW.user_id  IS DISTINCT FROM OLD.user_id
    OR NEW.deal_id  IS DISTINCT FROM OLD.deal_id
    OR NEW.store_id IS DISTINCT FROM OLD.store_id THEN
      RAISE EXCEPTION 'forbidden: a review cannot be moved to another deal, store or user'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  -- أدواتُ البلاغات (كان هنا `is_admin()` — راجع أعلاه).
  IF public.taki_admin_perm('tab_reports') THEN
    RETURN NEW;
  END IF;

  -- Belt and braces next to the RLS policy: never review as somebody else.
  IF NEW.user_id IS DISTINCT FROM auth.uid()::text THEN
    RAISE EXCEPTION 'forbidden: cannot review on behalf of another user'
      USING ERRCODE = '42501';
  END IF;

  -- البوّابةُ الفعليّة: شراءٌ مكتملٌ **لهذا العرض** من هذا المتجر.
  IF NOT EXISTS (
    SELECT 1 FROM public.bookings b
     WHERE b.user_id  = NEW.user_id
       AND b.store_id = NEW.store_id
       AND b.deal_id  = NEW.deal_id
       AND b.status   = 'completed'
  ) THEN
    RAISE EXCEPTION 'forbidden: only a completed purchase of this deal allows a review'
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_guard_sim_gateway() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_sim_gateway()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF lower(COALESCE(NEW.provider, '')) IN ('sim', 'simulated')
     AND COALESCE(NEW.is_enabled, false)
     AND NOT public.taki_is_lab() THEN
    RAISE EXCEPTION 'مزوّدُ المحاكاة لا يُفعَّل على قاعدة الإنتاج — لا مال يمرّ فيه'
      USING ERRCODE = 'P0001', HINT = 'P0031';
  END IF;
  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_guard_stock_direction() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_stock_direction()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  -- يُطبَّق على مزوّدٍ **نقرأ منه** (سلّة · زد): هو وحده الذي تعني الكتابةُ
  -- العكسيّةُ عنده شيئاً، وهو وحده المشمولُ بقرار ٢٥ أكتوبر.
  IF public._taki_provider_read(NEW.provider) IS NOT NULL
     AND COALESCE(NEW.direction, 'in') <> 'in' THEN
    RAISE EXCEPTION 'الكتابةُ العكسية موقوفةٌ بقرارٍ من مالك المنصّة (٢٥ أكتوبر ٢٠٢٦): القراءةُ فقط في النسخة الأولى.'
      USING ERRCODE = 'P0001', HINT = 'P0027', HINT = 'READ_ONLY_BY_OWNER_DECISION';
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_guard_store_billing() INVOKER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_guard_store_billing()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_touches boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_touches :=
         NEW.subscription_plan       IS NOT NULL
      OR NEW.subscription_expires_at IS NOT NULL
      OR NEW.subscription_started_at IS NOT NULL
      OR NEW.subscription_amount     IS NOT NULL
      OR NEW.subscription_package_id IS NOT NULL
      OR NEW.max_branches            IS NOT NULL
      OR coalesce(NEW.discount_percentage, 0) <> 0
      OR coalesce(NEW.is_pinned, false)
      OR coalesce(NEW.is_suspended, false)
      OR NEW.custom_features IS NOT NULL
      OR NEW.admin_notes     IS NOT NULL
      -- v15.46 — أعمدةٌ فاتت الحارسَ الأصلي، وقِيس أنّ تاجراً غيرَ أدمن يكتبها:
      OR coalesce(NEW.delivery_blocked_by_admin, false)
      OR NEW.delivery_block_reason   IS NOT NULL
      OR NEW.delivery_blocked_at     IS NOT NULL
      OR NEW.payment_declared_at     IS NOT NULL
      OR NEW.subscription_canceled_at IS NOT NULL
      OR NEW.last_expiry_warning_at  IS NOT NULL;
  ELSE
    v_touches :=
         NEW.subscription_plan       IS DISTINCT FROM OLD.subscription_plan
      OR NEW.subscription_expires_at IS DISTINCT FROM OLD.subscription_expires_at
      OR NEW.subscription_started_at IS DISTINCT FROM OLD.subscription_started_at
      OR NEW.subscription_amount     IS DISTINCT FROM OLD.subscription_amount
      OR NEW.subscription_package_id IS DISTINCT FROM OLD.subscription_package_id
      OR NEW.max_branches            IS DISTINCT FROM OLD.max_branches
      OR NEW.discount_percentage     IS DISTINCT FROM OLD.discount_percentage
      OR NEW.is_pinned               IS DISTINCT FROM OLD.is_pinned
      OR NEW.is_suspended            IS DISTINCT FROM OLD.is_suspended
      OR NEW.custom_features         IS DISTINCT FROM OLD.custom_features
      OR NEW.admin_notes             IS DISTINCT FROM OLD.admin_notes
      -- 🔴 v15.46 — الأخطرُ فيها الأوّل: الإدارةُ تحظر توصيلَ متجرٍ لسبب،
      --    والمتجرُ كان يرفع الحظرَ عن نفسه بـPATCH واحد. وقِيس على جدّة.
      OR NEW.delivery_blocked_by_admin IS DISTINCT FROM OLD.delivery_blocked_by_admin
      OR NEW.delivery_block_reason   IS DISTINCT FROM OLD.delivery_block_reason
      OR NEW.delivery_blocked_at     IS DISTINCT FROM OLD.delivery_blocked_at
      -- وتزويرُ الإقرار يفتح البيعَ لمتجرٍ لم يقل كيف يُحاسِب (بوّابةُ v14.08)
      OR NEW.payment_declared_at     IS DISTINCT FROM OLD.payment_declared_at
      OR NEW.accepts_cod             IS DISTINCT FROM OLD.accepts_cod
      OR NEW.subscription_canceled_at IS DISTINCT FROM OLD.subscription_canceled_at
      OR NEW.last_expiry_warning_at  IS DISTINCT FROM OLD.last_expiry_warning_at;
  END IF;

  -- v15.46 — ومدى مهلة الحجز يُفحص لكلّ كتابةٍ من المتجر نفسه: كانت
  -- `merchant_set_booking_holds` ترفض ما فوق السقف و`PATCH` مباشرٌ يكتبه،
  -- فيُخزَّن ٨٧٦٠ ويُطبَّق ٧٢ وتكذب بطاقةُ التاجر عليه. (قِيس على جدّة.)
  IF current_user NOT IN ('postgres', 'service_role', 'supabase_admin') THEN
    IF NEW.hold_pickup_hours IS NOT NULL
       AND (NEW.hold_pickup_hours < public.taki_booking_hold_min() OR NEW.hold_pickup_hours > public.taki_booking_hold_max()) THEN
      RAISE EXCEPTION 'forbidden: pickup hold outside the allowed range'
        USING ERRCODE = '42501';
    END IF;
    IF NEW.hold_delivery_hours IS NOT NULL
       AND (NEW.hold_delivery_hours < public.taki_booking_hold_min() OR NEW.hold_delivery_hours > public.taki_booking_hold_max()) THEN
      RAISE EXCEPTION 'forbidden: delivery hold outside the allowed range'
        USING ERRCODE = '42501';
    END IF;
  END IF;

  IF NOT v_touches THEN
    RETURN NEW;   -- ordinary profile edits (bio, phone, VAT number…) pass through
  END IF;

  -- The activation RPC, admin RPCs, pg_cron renewals and the service role all
  -- run as the owner; the merchant's own session does not.
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'forbidden: subscription, limit, admin-block and declaration fields are not self-editable'
    USING ERRCODE = '42501';
END;
$function$
;


-- ═══ FUNCTION tr_guard_user_address() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_user_address()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE v_cnt int;
BEGIN
  IF NEW.lat IS NULL OR NEW.lng IS NULL
     OR NEW.lat NOT BETWEEN 16 AND 33 OR NEW.lng NOT BETWEEN 34 AND 56 THEN
    RAISE EXCEPTION 'TAKI_ADDR_BAD:point' USING ERRCODE = '23514';
  END IF;
  NEW.label   := nullif(left(btrim(coalesce(NEW.label, '')), 60), '');
  NEW.details := nullif(left(btrim(coalesce(NEW.details, '')), 300), '');
  NEW.city    := nullif(left(btrim(coalesce(NEW.city, '')), 60), '');
  NEW.phone   := nullif(left(btrim(coalesce(NEW.phone, '')), 20), '');
  IF TG_OP = 'INSERT' THEN
    SELECT count(*) INTO v_cnt FROM public.user_addresses WHERE user_id = NEW.user_id;
    IF v_cnt >= 10 THEN RAISE EXCEPTION 'TAKI_ADDR_CAP:10' USING ERRCODE = '23514'; END IF;
    -- أول عنوان يصير الافتراضي بلا سؤال — لا يُعقل أن يملك المشتري عنواناً واحداً
    -- ولا يكون افتراضياً، فيرى «لا عنوان محدد» وعنده عنوان.
    IF v_cnt = 0 THEN NEW.is_default := true; END IF;
  END IF;
  NEW.updated_at := now();
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_guard_user_delete() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_guard_user_delete()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_n bigint;
BEGIN
  SELECT count(*) INTO v_n FROM public.bookings
   WHERE user_id = OLD.id OR store_id = OLD.id;
  IF v_n > 0 THEN
    RAISE EXCEPTION
      'TAKI_USER_HAS_ORDERS: هذا الحساب طرفٌ في % طلباً. الطلبات وفواتيرها الضريبية سجلٌّ لا يُمحى بحذف حساب — استعمل حذف الحساب المعتمد (تعطيل ثم تجهيل بعد ٣٠ يوماً).', v_n
      USING ERRCODE = 'P0001', HINT = 'P0015';
  END IF;
  RETURN OLD;
END
$function$
;


-- ═══ FUNCTION tr_guard_user_privileges() INVOKER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_guard_user_privileges()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_touches_privilege boolean;
BEGIN
  IF TG_OP = 'INSERT' THEN
    -- 🪤 `admin_permissions` عمودٌ `NOT NULL DEFAULT '{}'`، فهذا الشرطُ
    --    صادقٌ دائماً — وهو سلوكُ الإنتاج اليوم، أُبقي حرفياً. والأعمدةُ
    --    المضافةُ بعده للصحّة لا للسلوك (أثرُها صفر ما بقي الشرطُ أعلاه).
    v_touches_privilege :=
         NEW.user_type = 'admin'
      OR coalesce(NEW.is_super_admin, false)
      OR NEW.admin_permissions IS NOT NULL
      OR coalesce(NEW.is_suspended, false)
      OR coalesce(NEW.under_review, false)
      OR coalesce(NEW.is_anonymized, false)
      OR NEW.under_review_at      IS NOT NULL
      OR NEW.booking_banned_until IS NOT NULL
      OR NEW.booking_ban_reason   IS NOT NULL
      OR NEW.deleted_at           IS NOT NULL
      OR NEW.purge_after          IS NOT NULL
      OR NEW.anonymized_at        IS NOT NULL
      OR NEW.admin_notes          IS NOT NULL;
  ELSE
    v_touches_privilege :=
      -- الامتيازات (كما كانت)
         NEW.user_type            IS DISTINCT FROM OLD.user_type
      OR NEW.is_super_admin       IS DISTINCT FROM OLD.is_super_admin
      OR NEW.admin_permissions    IS DISTINCT FROM OLD.admin_permissions
      -- v15.79 — أعمدةُ الفرض: العقوبةُ والمراجعةُ والحذفُ والتجهيلُ
      OR NEW.is_suspended         IS DISTINCT FROM OLD.is_suspended
      OR NEW.under_review         IS DISTINCT FROM OLD.under_review
      OR NEW.under_review_at      IS DISTINCT FROM OLD.under_review_at
      OR NEW.booking_banned_until IS DISTINCT FROM OLD.booking_banned_until
      OR NEW.booking_ban_reason   IS DISTINCT FROM OLD.booking_ban_reason
      OR NEW.deleted_at           IS DISTINCT FROM OLD.deleted_at
      OR NEW.purge_after          IS DISTINCT FROM OLD.purge_after
      OR NEW.is_anonymized        IS DISTINCT FROM OLD.is_anonymized
      OR NEW.anonymized_at        IS DISTINCT FROM OLD.anonymized_at
      OR NEW.admin_notes          IS DISTINCT FROM OLD.admin_notes;
  END IF;

  -- كتابةٌ لا تمسّ شيئاً من ذلك تمرّ كما هي (فالحفظُ الجزئيّ للملفّ الشخصيّ
  -- ونداءُ «احفظ» مكرَّراً بنفس القيمة لا يُرفضان).
  IF NOT v_touches_privilege THEN
    RETURN NEW;
  END IF;

  -- المنادونَ الموثوقون: الدوالُّ الإداريّة (`DEFINER` ⇒ المالك)، والكرون
  -- (قِيس: `cron.job.username = supabase_admin` في الوظائف كلِّها)، ودورُ
  -- الخدمة. 🪤 يبقى `current_user` لأنّ هذه الدالّةَ `INVOKER` — ولو كانت
  -- `DEFINER` لصار الشرطُ صادقاً في كلّ نداءٍ ولم يمنع أحداً (v14.93).
  IF current_user IN ('postgres', 'service_role', 'supabase_admin') THEN
    RETURN NEW;
  END IF;

  -- الأدمنُ الأعلى يُدير الأدوار. (وبعد ⑦ صارت `is_super_admin()` ترفض
  -- الأدمنَ المحذوفَ ناعماً أيضاً.)
  IF public.is_super_admin() THEN
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    RAISE EXCEPTION 'forbidden: cannot create a privileged account'
      USING ERRCODE = '42501';
  END IF;

  -- v15.79 — الرفضُ الجديد **قبل** الذيل القديم، فلا يُمسّ الذيل.
  IF NEW.is_suspended         IS DISTINCT FROM OLD.is_suspended
  OR NEW.under_review         IS DISTINCT FROM OLD.under_review
  OR NEW.under_review_at      IS DISTINCT FROM OLD.under_review_at
  OR NEW.booking_banned_until IS DISTINCT FROM OLD.booking_banned_until
  OR NEW.booking_ban_reason   IS DISTINCT FROM OLD.booking_ban_reason
  OR NEW.deleted_at           IS DISTINCT FROM OLD.deleted_at
  OR NEW.purge_after          IS DISTINCT FROM OLD.purge_after
  OR NEW.is_anonymized        IS DISTINCT FROM OLD.is_anonymized
  OR NEW.anonymized_at        IS DISTINCT FROM OLD.anonymized_at
  OR NEW.admin_notes          IS DISTINCT FROM OLD.admin_notes THEN
    RAISE EXCEPTION 'forbidden: account enforcement fields are server-managed'
      USING ERRCODE = '42501';
  END IF;

  -- ── الذيلُ القديم، حرفياً: ترقيةُ المشتري تاجراً تبقى تعمل ─────────────
  IF NEW.is_super_admin IS DISTINCT FROM OLD.is_super_admin THEN
    RAISE EXCEPTION 'forbidden: is_super_admin is not self-editable'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.admin_permissions IS DISTINCT FROM OLD.admin_permissions THEN
    RAISE EXCEPTION 'forbidden: admin_permissions is not self-editable'
      USING ERRCODE = '42501';
  END IF;
  IF NEW.user_type IS DISTINCT FROM OLD.user_type
     AND NEW.user_type NOT IN ('buyer', 'seller') THEN
    RAISE EXCEPTION 'forbidden: cannot grant yourself the % role', NEW.user_type
      USING ERRCODE = '42501';
  END IF;

  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_notify_delivery_started() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_notify_delivery_started()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_shop text; v_item text;
BEGIN
  IF NEW.status = 'on_the_way'
     AND coalesce(OLD.status, '') <> 'on_the_way'
     AND OLD.started_at IS NULL THEN
    SELECT coalesce(nullif(u.shop,''), u.name, 'المتجر') INTO v_shop FROM public.users u WHERE u.id = NEW.store_id;
    SELECT coalesce(d.item_name, 'طلبك') INTO v_item
      FROM public.bookings b LEFT JOIN public.deals d ON d.id = b.deal_id WHERE b.barcode = NEW.barcode;
    INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
    VALUES (NEW.user_id,
      '🚚 طلبك في الطريق إليك!', '🚚 Your order is on the way!',
      'انطلق ' || v_shop || ' بطلبك (' || v_item || '). تابع موقعه على الخريطة من «حجوزاتي».',
      v_shop || ' set off with your order (' || v_item || '). Track it on the map in “My bookings”.',
      'booking',
      jsonb_build_object('audience','buyer','event','delivery_started','barcode',NEW.barcode,'track',true),
      NOW());
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_on_hand_on_sale() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_on_hand_on_sale()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_need int; v_sel jsonb;
BEGIN
  -- 🪤 `<>` و`=` كلاهما يُعطي NULL أمام NULL، وNULL ليست TRUE فلا يقع الخروج
  --    المبكّر ⇒ كان يُنقص المخزون لحجزٍ حالتُه NULL. و`IS DISTINCT FROM`
  --    لا تعرف NULL فتُجيب دائماً TRUE أو FALSE.
  IF NEW.status IS DISTINCT FROM 'completed' THEN RETURN NEW; END IF;
  IF OLD.status IS NOT DISTINCT FROM 'completed' THEN RETURN NEW; END IF;

  v_need := GREATEST(COALESCE(NEW.booked_quantity, 1), 1);

  UPDATE public.deals
     SET on_hand = GREATEST(0, on_hand - v_need),
         stock_source = 'sale'   -- v15.06: العلامةُ للملاحظات الخارجية وحدها
   WHERE id = NEW.deal_id AND on_hand IS NOT NULL
     AND COALESCE(is_unlimited, false) = false;

  IF NEW.location_id IS NOT NULL THEN
    UPDATE public.deals d SET locations = (
      SELECT jsonb_agg(
        CASE WHEN e->>'id' = NEW.location_id AND (e ? 'onHand')
                  AND NULLIF(e->>'onHand','') IS NOT NULL
             THEN jsonb_set(e, '{onHand}', to_jsonb(GREATEST(0, (e->>'onHand')::int - v_need)))
             ELSE e END ORDER BY t.ord)
      FROM jsonb_array_elements(d.locations) WITH ORDINALITY AS t(e, ord))
     WHERE d.id = NEW.deal_id AND d.loc_qty_mode = 'per_location'
       AND d.locations IS NOT NULL AND jsonb_typeof(d.locations) = 'array';
  END IF;

  IF NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
    FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
      CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';

      UPDATE public.deals d SET variants = (
        SELECT jsonb_agg(
          CASE WHEN e->>'id' = v_sel->>'c' AND (e ? 'onHand')
                    AND NULLIF(e->>'onHand','') IS NOT NULL
               THEN jsonb_set(e, '{onHand}', to_jsonb(GREATEST(0, (e->>'onHand')::int
                      - GREATEST(COALESCE((v_sel->>'qty')::int, 1), 1))))
               ELSE e END ORDER BY t.ord)
        FROM jsonb_array_elements(d.variants) WITH ORDINALITY AS t(e, ord))
       WHERE d.id = NEW.deal_id
         AND d.variants IS NOT NULL AND jsonb_typeof(d.variants) = 'array';

      IF NEW.location_id IS NOT NULL THEN
        UPDATE public.deals d SET locations = (
          SELECT jsonb_agg(
            CASE WHEN e->>'id' = NEW.location_id AND (e ? 'variantOnHand')
                      AND ((e->'variantOnHand') ? (v_sel->>'c'))
                      AND NULLIF(e->'variantOnHand'->>(v_sel->>'c'),'') IS NOT NULL
                 THEN jsonb_set(e, ARRAY['variantOnHand', v_sel->>'c'],
                        to_jsonb(GREATEST(0, (e->'variantOnHand'->>(v_sel->>'c'))::int
                          - GREATEST(COALESCE((v_sel->>'qty')::int, 1), 1))))
                 ELSE e END ORDER BY t.ord)
          FROM jsonb_array_elements(d.locations) WITH ORDINALITY AS t(e, ord))
         WHERE d.id = NEW.deal_id AND d.loc_qty_mode = 'per_location'
           AND d.locations IS NOT NULL AND jsonb_typeof(d.locations) = 'array';
      END IF;
    END LOOP;
  END IF;

  -- v15.08: يُخبَر نظامُ التاجر بأن قطعةً خرجت
  PERFORM public._taki_stock_event(NEW.deal_id, NULL, NEW.location_id, 'sale', -v_need, (SELECT on_hand FROM public.deals WHERE id = NEW.deal_id), NEW.barcode);
  RETURN NEW;
END
$function$
;


