-- ═══ FUNCTION tr_reserve_booking_stock() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_reserve_booking_stock()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deal   deals%ROWTYPE;
  v_sel    jsonb;
  v_var    jsonb;
  v_need   int;
  v_avail  int;
  v_bname  text;
  v_capped boolean;
BEGIN
  SET LOCAL lock_timeout = '5s';

  v_need := GREATEST(COALESCE(NEW.booked_quantity, 1), 1);

  SELECT * INTO v_deal FROM deals WHERE id = NEW.deal_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'العرض لم يعد موجوداً' USING ERRCODE = 'P0001', HINT = 'P0010';
  END IF;

  IF v_deal.status IS DISTINCT FROM 'active' THEN
    RAISE EXCEPTION 'DEAL_NOT_ACTIVE' USING ERRCODE = 'P0001', HINT = 'P0010';
  END IF;

  -- v15.07 — مفتاحُ «نفد» اليدويّ: يوقف البيع ولا يمسّ الأرقام.
  IF COALESCE(v_deal.sold_out, false) THEN
    RAISE EXCEPTION 'نفدت الكمية — أوقف التاجر البيع مؤقتاً' USING ERRCODE = 'P0001', HINT = 'P0010';
  END IF;
  IF NEW.location_id IS NOT NULL AND v_deal.locations IS NOT NULL
     AND jsonb_typeof(v_deal.locations) = 'array'
     AND EXISTS (SELECT 1 FROM jsonb_array_elements(v_deal.locations) e
                  WHERE e->>'id' = NEW.location_id AND public.taki_variant_off(e)) THEN
    RAISE EXCEPTION 'نفدت الكمية في هذا الفرع — أوقف التاجر البيع فيه مؤقتاً' USING ERRCODE = 'P0001', HINT = 'P0010';
  END IF;
  IF NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
    IF EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.selected_options) s
               JOIN jsonb_array_elements(COALESCE(v_deal.variants,'[]'::jsonb)) e
                 ON e->>'id' = s->>'c'
              WHERE s->>'g' = '__variant__' AND public.taki_variant_off(e)) THEN
      RAISE EXCEPTION 'نفد هذا النوع — أوقف التاجر بيعه مؤقتاً' USING ERRCODE = 'P0001', HINT = 'P0010';
    END IF;
    IF NEW.location_id IS NOT NULL AND v_deal.locations IS NOT NULL
       AND jsonb_typeof(v_deal.locations) = 'array'
       AND EXISTS (SELECT 1 FROM jsonb_array_elements(NEW.selected_options) s,
                        jsonb_array_elements(v_deal.locations) e
                   WHERE s->>'g' = '__variant__' AND e->>'id' = NEW.location_id
                     AND COALESCE((e->'variantOff'->>(s->>'c'))::boolean, false)) THEN
      RAISE EXCEPTION 'نفد هذا النوع في الفرع المختار — أوقف التاجر بيعه مؤقتاً' USING ERRCODE = 'P0001', HINT = 'P0010';
    END IF;
  END IF;


  v_capped := NOT COALESCE(v_deal.is_unlimited, false)
              AND COALESCE(v_deal.initial_quantity, 0) > 0;

  IF v_capped AND COALESCE(v_deal.quantity, 0) < v_need THEN
    RAISE EXCEPTION 'نفدت الكمية — سبقك مشترون آخرون إليها (المتاح الآن: %)',
      GREATEST(COALESCE(v_deal.quantity, 0), 0) USING ERRCODE = 'P0001', HINT = 'P0010';
  END IF;

  IF NEW.location_id IS NOT NULL
     AND v_deal.loc_qty_mode = 'per_location'
     AND v_deal.locations IS NOT NULL AND jsonb_typeof(v_deal.locations) = 'array' THEN
    SELECT NULLIF(e->>'quantity','')::int, COALESCE(NULLIF(e->>'name',''), 'الفرع')
      INTO v_avail, v_bname
      FROM jsonb_array_elements(v_deal.locations) e
     WHERE e->>'id' = NEW.location_id
     LIMIT 1;
    IF v_avail IS NOT NULL AND v_avail < v_need THEN
      RAISE EXCEPTION 'نفدت كمية «%» — المتاح الآن بهذا الفرع: %',
        v_bname, GREATEST(v_avail, 0) USING ERRCODE = 'P0001', HINT = 'P0010';
    END IF;
  END IF;

  IF v_deal.variants IS NOT NULL AND jsonb_typeof(v_deal.variants) = 'array'
     AND NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
    FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
      CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
      SELECT e INTO v_var FROM jsonb_array_elements(v_deal.variants) e
       WHERE e->>'id' = v_sel->>'c' LIMIT 1;
      CONTINUE WHEN v_var IS NULL OR NOT (v_var ? 'qty') OR NULLIF(v_var->>'qty','') IS NULL;
      IF (v_var->>'qty')::int < GREATEST(COALESCE((v_sel->>'qty')::int, 1), 1) THEN
        RAISE EXCEPTION 'نفدت كمية «%» — المتاح الآن: %',
          COALESCE(v_var->>'label', 'هذا النوع'), GREATEST((v_var->>'qty')::int, 0)
          USING ERRCODE = 'P0001', HINT = 'P0010';
      END IF;
    END LOOP;
  END IF;

  IF NEW.location_id IS NOT NULL
     AND v_deal.loc_qty_mode = 'per_location'
     AND v_deal.locations IS NOT NULL AND jsonb_typeof(v_deal.locations) = 'array'
     AND NEW.selected_options IS NOT NULL AND jsonb_typeof(NEW.selected_options) = 'array' THEN
    FOR v_sel IN SELECT * FROM jsonb_array_elements(NEW.selected_options) LOOP
      CONTINUE WHEN v_sel->>'g' IS DISTINCT FROM '__variant__';
      SELECT NULLIF(e->'variantQtys'->>(v_sel->>'c'),'')::int
        INTO v_avail
        FROM jsonb_array_elements(v_deal.locations) e
       WHERE e->>'id' = NEW.location_id AND (e ? 'variantQtys')
       LIMIT 1;
      IF v_avail IS NOT NULL AND v_avail < GREATEST(COALESCE((v_sel->>'qty')::int, 1), 1) THEN
        RAISE EXCEPTION 'نفد هذا النوع في الفرع المختار — المتاح الآن: %',
          GREATEST(v_avail, 0) USING ERRCODE = 'P0001', HINT = 'P0010';
      END IF;
    END LOOP;
  END IF;

  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_reset_verification_warn() INVOKER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_reset_verification_warn()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.doc_expiry IS DISTINCT FROM OLD.doc_expiry THEN
    NEW.warn_stage := 0;
  END IF;
  IF NEW.confirmation_due IS DISTINCT FROM OLD.confirmation_due THEN
    NEW.warn_stage_conf := 0;
  END IF;
  RETURN NEW;
END
$function$
;


