-- ═══ FUNCTION tr_single_default_address() DEFINER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_single_default_address()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.is_default THEN
    UPDATE public.user_addresses SET is_default = false, updated_at = now()
     WHERE user_id = NEW.user_id AND id <> NEW.id AND is_default;
    -- `users.delivery_address` تبقى مرآةً للعنوان الافتراضي: البوتان وكل ما
    -- كُتب قبل هذه النسخة يقرؤها، فمزامنتها هنا تُبقيهما يعملان بلا تعديل.
    UPDATE public.users SET delivery_address = jsonb_strip_nulls(jsonb_build_object(
        'label', NEW.label, 'details', NEW.details, 'city', NEW.city,
        'phone', NEW.phone, 'lat', NEW.lat, 'lng', NEW.lng, 'addr_id', NEW.id))
     WHERE id = NEW.user_id;
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_stamp_dispatch() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_stamp_dispatch()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- أيُّ حالةِ انطلاقٍ تطبع، و`started_at` المطبوع سابقاً يطبع أيضاً.
  IF NEW.status IN ('on_the_way','arrived','delivered') OR NEW.started_at IS NOT NULL THEN
    NEW.dispatched_at := COALESCE(NEW.dispatched_at, now());
  END IF;
  -- ولا يُمحى بعد طبعه — ولو كتبها الكودُ صراحةً NULL.
  IF TG_OP = 'UPDATE' AND OLD.dispatched_at IS NOT NULL THEN
    NEW.dispatched_at := OLD.dispatched_at;
  END IF;
  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_stock_declare() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_stock_declare()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_id text := NEW.id;
BEGIN
  -- كتابةٌ من داخل مشغّلٍ آخر = عدّادُ المتاح (حجز/إلغاء) — لا تُلمَس.
  IF pg_trigger_depth() > 1 THEN RETURN NEW; END IF;
  -- وكتابةٌ من `taki_set_on_hand` = المشتقّ محسوبٌ أصلاً.
  IF COALESCE(current_setting('taki.stock_derived', true), '') = '1' THEN RETURN NEW; END IF;

  -- عرضٌ بلا حدّ: لا كاملَ له — وصفرٌ فيه يعني «نفد».
  IF COALESCE(NEW.is_unlimited, false) THEN
    NEW.on_hand := NULL;
    RETURN NEW;
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.on_hand := GREATEST(0, COALESCE(NEW.quantity, 0));   -- عرضٌ جديد: لا محجوزَ بعد
    NEW.stock_observed_at := now(); NEW.stock_source := 'merchant';
    RETURN NEW;
  END IF;

  -- ── الإجمالي ────────────────────────────────────────────────────────────
  -- 🪤 الشرط `IS DISTINCT FROM OLD` مقصود: حفظٌ لا يمسّ الكمّية (تغييرُ صورة،
  --    وصف، سعر) لا يُعيد الاشتقاق ولا يلمس شيئاً — فلا أثرَ جانبيّ لحفظٍ بريء.
  IF NEW.quantity IS DISTINCT FROM OLD.quantity THEN
    NEW.on_hand := GREATEST(0, COALESCE(NEW.quantity, 0));
    NEW.quantity := GREATEST(0, NEW.on_hand - public.taki_open_holds(v_id, NULL, NULL));
    NEW.stock_observed_at := now(); NEW.stock_source := 'merchant';
  END IF;

  -- ── الأصناف ─────────────────────────────────────────────────────────────
  IF NEW.variants IS DISTINCT FROM OLD.variants
     AND NEW.variants IS NOT NULL AND jsonb_typeof(NEW.variants) = 'array' THEN
    NEW.variants := COALESCE((
      SELECT jsonb_agg(
        CASE WHEN (e ? 'qty') AND NULLIF(e->>'qty','') IS NOT NULL
             THEN jsonb_set(jsonb_set(e, '{onHand}', to_jsonb(GREATEST(0, (e->>'qty')::int))),
                            '{qty}', to_jsonb(GREATEST(0, (e->>'qty')::int
                              - public.taki_open_holds(v_id, e->>'id', NULL))))
             ELSE e END ORDER BY t.ord)
      FROM jsonb_array_elements(NEW.variants) WITH ORDINALITY AS t(e, ord)), NEW.variants);
  END IF;

  -- ── الفروع وأصنافُها ────────────────────────────────────────────────────
  IF NEW.locations IS DISTINCT FROM OLD.locations
     AND NEW.locations IS NOT NULL AND jsonb_typeof(NEW.locations) = 'array' THEN
    NEW.locations := COALESCE((
      SELECT jsonb_agg(public._taki_loc_declare(v_id, t.e) ORDER BY t.ord)
      FROM jsonb_array_elements(NEW.locations) WITH ORDINALITY AS t(e, ord)), NEW.locations);
  END IF;

  RETURN NEW;
END
$function$
;


-- ═══ FUNCTION tr_sync_accepts_cod() INVOKER owner=supabase_admin search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_sync_accepts_cod()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  -- 🔴 لا يُقِرُّ المشغّلُ عن تاجرٍ لم ينطق: `payment_declared_at` تبقى بيد
  --    `merchant_set_payment_declaration` وحدها. وكانت الصيغةُ الأولى تختمها
  --    هنا، و`merchant_gateways.payment_modes` افتراضُها `'cod'` NOT NULL
  --    و`merchant_set_gateway` لا تذكرها — فتاجرٌ يحفظ مفاتيح بوّابته **قبل**
  --    أن يُقرّ كان يصير «يقبل النقد» بإقرارٍ لم يقله، ثمّ تختفي عنه البطاقةُ
  --    التي كانت ستسأله. (والمتجر `fa5e533c` على هذه الحافة اليوم: بلا إقرار.)
  -- 🪤 ولذلك المشغّلُ `UPDATE OF` وحده — بلا `INSERT`: عند الإدراج تكون `OLD`
  --    فارغةً فيبدو الافتراضيُّ تغييراً وهو ليس اختياراً من أحد.
  IF NEW.payment_modes IS DISTINCT FROM OLD.payment_modes THEN
    UPDATE public.store_profiles
       SET accepts_cod = (NEW.payment_modes <> 'online'),
           updated_at = now()
     WHERE store_id = NEW.merchant_id
       AND payment_declared_at IS NOT NULL;
  END IF;
  RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION tr_user_blocks_mirror() DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.tr_user_blocks_mirror()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_blocker text; v_blocked text; v_type text;
BEGIN
  v_blocker := COALESCE(NEW.blocker_id, OLD.blocker_id);
  v_blocked := COALESCE(NEW.blocked_id, OLD.blocked_id);
  SELECT user_type INTO v_type FROM public.users WHERE id = v_blocked;

  -- 🪤 بـ«ليس مشترياً» لا بـ«بائع»: متجرُ ناصر يملكه حسابٌ أدمن، ومرشِّحُ
  --    `user_type='seller'` كان يُخفيه دائماً.
  IF COALESCE(v_type, '') = 'buyer' THEN
    RETURN NULL;                       -- حجبُ مشترٍ لا مرآةَ له: العمودُ للمتاجر
  END IF;

  IF TG_OP = 'INSERT' THEN
    UPDATE public.users
       SET blocked_merchants  = ARRAY(SELECT DISTINCT e
                                        FROM unnest(COALESCE(blocked_merchants, '{}'::text[])
                                                    || ARRAY[v_blocked]) e),
           followed_merchants = array_remove(COALESCE(followed_merchants, '{}'::text[]), v_blocked)
     WHERE id = v_blocker;
  ELSE
    UPDATE public.users
       SET blocked_merchants = array_remove(COALESCE(blocked_merchants, '{}'::text[]), v_blocked)
     WHERE id = v_blocker;
  END IF;
  RETURN NULL;
END;
$function$
;


-- ═══ FUNCTION tr_validate_booking_options() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_validate_booking_options()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_fault text;
BEGIN
  v_fault := public.taki_booking_options_fault(NEW.deal_id, NEW.selected_options);
  IF v_fault IS NULL THEN RETURN NEW; END IF;
  IF v_fault = 'NEEDS_OPTIONS' THEN
    RAISE EXCEPTION 'NEEDS_OPTIONS' USING ERRCODE = 'P0001', HINT = 'NEEDS_OPTIONS';
  END IF;
  -- `VARIANT_STOCK:<الاسم>:<المتبقّي>` — عقدٌ نصّيٌّ تقرؤه الواجهةُ والبوتان
  RAISE EXCEPTION '%', v_fault USING ERRCODE = 'P0001', HINT = 'VARIANT_STOCK';
END
$function$
;


-- ═══ FUNCTION tr_validate_deal_season() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.tr_validate_deal_season()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_camp  jsonb;
    v_from  date;
    v_to    date;
    v_today date := (now() AT TIME ZONE 'Asia/Riyadh')::date;
BEGIN
    IF NEW.season_id IS NULL THEN RETURN NEW; END IF;
    IF TG_OP = 'UPDATE' AND NEW.season_id IS NOT DISTINCT FROM OLD.season_id THEN
        RETURN NEW; -- وسم قائم لم يتغيّر — تعديلات الحقول الأخرى لا تُعاد محاكمتها
    END IF;
    IF public.is_admin() THEN RETURN NEW; END IF;

    SELECT value INTO v_camp FROM platform_settings WHERE key = 'season_campaign';
    IF v_camp IS NULL OR (v_camp->>'season_id') IS DISTINCT FROM NEW.season_id THEN
        RAISE EXCEPTION 'إضافة العروض لهذا الموسم غير متاحة حالياً — انتظر إعلان فتح باب المشاركة';
    END IF;
    v_from := NULLIF(v_camp->>'seller_from','')::date;
    v_to   := NULLIF(v_camp->>'seller_to','')::date;
    IF v_from IS NULL OR v_to IS NULL OR v_today < v_from OR v_today > v_to THEN
        RAISE EXCEPTION 'نافذة إضافة عروض الموسم من % إلى % — التاريخ الحالي خارجها', COALESCE(v_from::text,'؟'), COALESCE(v_to::text,'؟');
    END IF;
    RETURN NEW;
END $function$
;


