-- ═══ FUNCTION track_app_open(p_source text, p_lat double precision, p_lng double precision) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.track_app_open(p_source text DEFAULT 'web'::text, p_lat double precision DEFAULT NULL::double precision, p_lng double precision DEFAULT NULL::double precision)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := auth.uid()::text;
        v_src text := CASE WHEN p_source IN ('web','telegram','whatsapp') THEN p_source ELSE 'web' END;
        -- v15.79 — تدويرٌ عند الكتابة لا عند العرض.
        v_lat double precision := CASE WHEN p_lat BETWEEN -90  AND 90  THEN round(p_lat::numeric, 2)::double precision END;
        v_lng double precision := CASE WHEN p_lng BETWEEN -180 AND 180 THEN round(p_lng::numeric, 2)::double precision END;
BEGIN
    -- v15.79 — الموافقةُ تُفحص على الخادم فتصير قراراً لا تفضيلَ متصفّح.
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.users WHERE id = v_uid AND COALESCE(analytics_opt_out, false)
    ) THEN RETURN; END IF;

    -- نفس المستخدم خلال ٣٠ دقيقة = جلسة واحدة (المجهول يعتمد على كبح العميل).
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind='app_open' AND user_id=v_uid AND source=v_src
          AND created_at > now() - interval '30 minutes'
    ) THEN RETURN; END IF;
    INSERT INTO analytics_events (kind, user_id, source, lat, lng)
    VALUES ('app_open', v_uid, v_src, v_lat, v_lng);
END;
$function$
;


-- ═══ FUNCTION track_search(p_query text, p_scope text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.track_search(p_query text, p_scope text DEFAULT 'home'::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_q text := lower(btrim(COALESCE(p_query, '')));
        v_uid text := auth.uid()::text;
BEGIN
    IF length(v_q) < 2 OR length(v_q) > 80 THEN RETURN; END IF;

    -- v15.79 — الموافقةُ على الخادم.
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.users WHERE id = v_uid AND COALESCE(analytics_opt_out, false)
    ) THEN RETURN; END IF;

    -- نفس المستخدم + نفس الكلمة خلال ١٠ دقائق = بحث واحد (يمنع تضخيم العدّاد أثناء الكتابة)
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind='search' AND user_id=v_uid AND query=v_q
          AND created_at > now() - interval '10 minutes'
    ) THEN RETURN; END IF;
    INSERT INTO analytics_events (kind, user_id, query, source)
    VALUES ('search', v_uid, v_q,
            CASE WHEN p_scope IN ('home','deals','nearby') THEN p_scope ELSE 'home' END);
END;
$function$
;


-- ═══ FUNCTION track_site_visit(p_session text, p_path text, p_referrer text, p_utm jsonb, p_device text, p_pwa boolean, p_lang text) DEFINER owner=supabase_admin search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.track_site_visit(p_session text, p_path text, p_referrer text DEFAULT NULL::text, p_utm jsonb DEFAULT '{}'::jsonb, p_device text DEFAULT NULL::text, p_pwa boolean DEFAULT false, p_lang text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
    v_sid   text := left(btrim(COALESCE(p_session, '')), 64);
    v_uid   text := auth.uid()::text;
    v_path  text;
    v_host  text;
    v_src   text := left(btrim(COALESCE(p_utm->>'source',   '')), 64);
    v_med   text := left(btrim(COALESCE(p_utm->>'medium',   '')), 64);
    v_camp  text := left(btrim(COALESCE(p_utm->>'campaign', '')), 64);
    v_ref   text := left(btrim(COALESCE(p_utm->>'ref',      '')), 32);
    v_dev   text := CASE WHEN p_device IN ('mobile','tablet','desktop') THEN p_device END;
    v_lang  text := CASE WHEN p_lang IN ('ar','en') THEN p_lang END;
    v_new   integer;
BEGIN
    -- معرّف جلسةٍ مشوّه أو غائب ⇒ لا نكتب شيئاً (ولا نُخطئ: القياس لا يُفشل تصفّحاً).
    IF v_sid !~ '^[A-Za-z0-9_.-]{8,64}$' THEN RETURN; END IF;

    -- v15.79 — الموافقةُ على الخادم.
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.users WHERE id = v_uid AND COALESCE(analytics_opt_out, false)
    ) THEN RETURN; END IF;

    -- المسار: بلا مضيف، وبلا أي استعلام (فلا يُخزَّن باركود ولا رمز في العنوان).
    v_path := left(split_part(split_part(COALESCE(p_path, '/'), '?', 1), '#', 1), 120);
    IF v_path = '' THEN v_path := '/'; END IF;
    IF left(v_path, 1) <> '/' THEN v_path := '/' || v_path; END IF;

    -- المُحيل: **اسم المضيف وحده**.
    IF COALESCE(btrim(p_referrer), '') <> '' THEN
        v_host := left(lower(split_part(split_part(regexp_replace(p_referrer, '^[a-z]+://', '', 'i'), '/', 1), ':', 1)), 120);
        IF v_host !~ '^[a-z0-9.-]+\.[a-z]{2,}$' THEN v_host := NULL; END IF;
    END IF;

    -- تحديثُ جلسةٍ قائمة: لا صفّ جديد، ولا يُعاد كتابة مصدر الوصول
    -- (الإسناد لأوّل لمسة — وهو الصحيح: القناة التي جلبته لا التي تنقّل فيها).
    UPDATE public.site_sessions
       SET last_seen_at = now(),
           page_count   = LEAST(page_count + 1, 500),
           last_path    = v_path,
           user_id      = COALESCE(user_id, v_uid)
     WHERE session_id = v_sid;
    IF FOUND THEN RETURN; END IF;

    -- 🪤 الدالّة مفتوحة للزائر، فإنشاء الجلسات محدودٌ عالمياً: أسوأ حالةٍ
    --    مسقوفة بدل نموٍّ بلا حدّ. والتحديث أعلاه لا يمرّ من هنا إطلاقاً.
    SELECT count(*) INTO v_new FROM public.site_sessions
     WHERE started_at > now() - interval '1 minute';
    IF v_new >= 300 THEN RETURN; END IF;

    INSERT INTO public.site_sessions (
        session_id, landing_path, referrer_host, channel,
        utm_source, utm_medium, utm_campaign, ref_code,
        device, is_pwa, lang, last_path, user_id
    ) VALUES (
        v_sid, v_path, v_host, public.taki_traffic_channel(v_host, v_src),
        NULLIF(v_src,''), NULLIF(v_med,''), NULLIF(v_camp,''), NULLIF(v_ref,''),
        v_dev, COALESCE(p_pwa, false), v_lang, v_path, v_uid
    )
    ON CONFLICT (session_id) DO NOTHING;   -- سباقُ تبويبين على نفس الجلسة
END
$function$
;


-- ═══ FUNCTION track_store_view(p_store_id text) DEFINER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.track_store_view(p_store_id text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_uid text := auth.uid()::text;
BEGIN
    IF p_store_id IS NULL OR btrim(p_store_id) = '' THEN RETURN; END IF;
    -- Dedupe: one event per visitor per store per 30 minutes (signed-in only;
    -- guests always count — the client also dedupes per session).
    IF v_uid IS NOT NULL AND EXISTS (
        SELECT 1 FROM analytics_events
        WHERE kind = 'store_view' AND store_id = p_store_id AND user_id = v_uid
          AND created_at > now() - interval '30 minutes'
    ) THEN RETURN; END IF;
    INSERT INTO analytics_events (kind, user_id, store_id)
    VALUES ('store_view', v_uid, p_store_id);
END;
$function$
;


-- ═══ FUNCTION update_rating(p_rating_id text, p_score integer, p_comment text) DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.update_rating(p_rating_id text, p_score integer, p_comment text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_uid text := (auth.uid())::text;
    v_owner text;
BEGIN
    IF v_uid IS NULL THEN RAISE EXCEPTION 'auth required'; END IF;
    IF p_score IS NULL OR p_score < 1 OR p_score > 5 THEN RAISE EXCEPTION 'bad score'; END IF;
    SELECT r.user_id INTO v_owner FROM public.ratings r WHERE r.id = p_rating_id AND r.deleted_at IS NULL;
    IF v_owner IS NULL THEN RAISE EXCEPTION 'rating not found'; END IF;
    IF v_owner <> v_uid AND NOT EXISTS (SELECT 1 FROM public.users u WHERE u.id = v_uid AND u.user_type = 'admin') THEN
        RAISE EXCEPTION 'forbidden';
    END IF;
    UPDATE public.ratings
       SET score = p_score,
           comment = NULLIF(btrim(COALESCE(p_comment, '')), ''),
           updated_at = now()
     WHERE id = p_rating_id;
END $function$
;


-- ═══ FUNCTION update_updated_at() INVOKER owner=postgres search_path=search_path=public anon=YES ═══
CREATE OR REPLACE FUNCTION public.update_updated_at()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    NEW.updated_at = NOW();
    RETURN NEW;
END;
$function$
;


-- ═══ FUNCTION urlencode(p_in text) INVOKER owner=postgres search_path=search_path=public, pg_temp anon=YES ═══
CREATE OR REPLACE FUNCTION public.urlencode(p_in text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_bytes bytea := convert_to(coalesce(p_in,''),'UTF8'); v_out text := ''; i int; b int; c text;
BEGIN
  FOR i IN 0..octet_length(v_bytes)-1 LOOP
    b := get_byte(v_bytes, i);
    c := chr(b);
    IF c ~ '[A-Za-z0-9_.~-]' THEN v_out := v_out || c;
    ELSE v_out := v_out || '%' || upper(lpad(to_hex(b),2,'0'));
    END IF;
  END LOOP;
  RETURN v_out;
END; $function$
;


