-- ═══ FUNCTION warn_expiring_bookings() DEFINER owner=postgres search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.warn_expiring_bookings()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_now bigint := (EXTRACT(EPOCH FROM NOW())*1000)::bigint;
  v_count int := 0; r record; v_item text;
  s jsonb; v_min int; vars jsonb; v_title text; v_body text;
BEGIN
  s := public.taki_msg_setting('booking_reminder');
  IF NOT COALESCE((s->>'enabled')::boolean, true) THEN RETURN 0; END IF;
  v_min := LEAST(GREATEST(COALESCE((s->>'minutes_before')::int, 15), 5), 240);

  FOR r IN SELECT b.* FROM public.bookings b
           WHERE b.status IN ('pending','acknowledged')
             AND COALESCE(b.expiry_warned,false) = false
             AND b.expiry_time > v_now
             AND b.expiry_time <= v_now + (v_min::bigint * 60000)   -- bigint: no int32 overflow
             AND b.paid_at IS NULL
             AND NOT public.taki_autocancel_blocked(b.barcode, b.booked_at, b.expiry_time, b.paid_at IS NOT NULL)
  LOOP
    SELECT item_name INTO v_item FROM public.deals WHERE id = r.deal_id;
    -- v15.54 — النصُّ المصوغ لا الرقمُ الخام: «3 دقيقة» خطأٌ نحويّ،
    -- والمحرّكُ واحدٌ في البيئات الثلاث (قاعدة v14.92).
    vars := jsonb_build_object('minutes', public.taki_ar_minutes(v_min),
                               'minutes_num', v_min::text,
                               'item', COALESCE(v_item, 'العرض'));
    v_title := public.taki_render_template(s->>'title_ar', vars);
    v_body  := public.taki_render_template(s->>'body_ar',  vars);
    IF COALESCE((s->'channels'->>'inapp')::boolean, true) THEN
        INSERT INTO public.notifications (user_id, title_ar, title_en, body_ar, body_en, type, meta_data, created_at)
        VALUES (r.user_id, v_title,
                public.taki_render_template(s->>'title_en', vars),
                v_body,
                public.taki_render_template(s->>'body_en', vars),
                'booking',
                jsonb_build_object('audience','buyer','event','warning','barcode',r.barcode,'dealId',r.deal_id),
                NOW());
    END IF;
    IF COALESCE((s->'channels'->>'email')::boolean, false) THEN
        PERFORM public.taki_queue_email(r.user_id, 'booking_reminder', v_title,
            public.taki_email_wrap(v_title, '<p>' || replace(v_body, E'\n', '<br>') || '</p>'));
    END IF;
    UPDATE public.bookings SET expiry_warned = true WHERE barcode = r.barcode;
    v_count := v_count + 1;
  END LOOP;
  RETURN v_count;
END;
$function$
;


-- ═══ FUNCTION withdraw_booking_refund(p_barcode text) DEFINER owner=supabase_admin search_path=search_path=public anon=no ═══
CREATE OR REPLACE FUNCTION public.withdraw_booking_refund(p_barcode text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_me text := (SELECT auth.uid()::text); v_r public.booking_refunds%ROWTYPE;
BEGIN
  IF v_me IS NULL THEN RETURN jsonb_build_object('ok', false, 'error', 'AUTH_REQUIRED'); END IF;
  SELECT * INTO v_r FROM public.booking_refunds WHERE barcode = upper(btrim(p_barcode));
  IF NOT FOUND THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_FOUND'); END IF;
  IF v_me <> v_r.buyer_id THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_BUYER'); END IF;
  IF v_r.status <> 'requested' THEN RETURN jsonb_build_object('ok', false, 'error', 'NOT_PENDING', 'status', v_r.status); END IF;
  UPDATE public.booking_refunds SET status = 'withdrawn', updated_at = now() WHERE barcode = v_r.barcode;
  PERFORM public._refund_notify(v_r.store_id,
    '↩️ سحب المشتري طلب الاسترداد', 'The buyer withdrew the refund request',
    'سحب المشتري طلب الإلغاء والاسترداد للطلب ' || v_r.barcode || '. الطلب قائم كما هو.',
    'The buyer withdrew the cancellation/refund request for order ' || v_r.barcode || '. The order stands.',
    v_r.barcode, 'seller', 'refund_withdrawn');
  RETURN jsonb_build_object('ok', true, 'status', 'withdrawn');
END
$function$
;


