-- ═══ RLS POLICIES (storage) ═══
-- storage.objects · Authenticated users delete own deal images
CREATE POLICY "Authenticated users delete own deal images" ON storage.objects FOR DELETE TO authenticated
  USING (((bucket_id = 'deals'::text) AND (owner = uid())));
-- storage.objects · Authenticated users replace own deal images
CREATE POLICY "Authenticated users replace own deal images" ON storage.objects FOR UPDATE TO authenticated
  USING (((bucket_id = 'deals'::text) AND (owner = uid())))
  WITH CHECK (((bucket_id = 'deals'::text) AND (owner = uid())));
-- storage.objects · Authenticated users upload deal images
CREATE POLICY "Authenticated users upload deal images" ON storage.objects FOR INSERT TO public
  WITH CHECK (((bucket_id = 'deals'::text) AND (owner = uid()) AND (split_part(name, '/'::text, 1) = (uid())::text) AND (name !~ '\.\.'::text) AND (array_length(string_to_array(name, '/'::text), 1) = 2) AND ((lower(name) ~~ '%.jpg'::text) OR (lower(name) ~~ '%.jpeg'::text) OR (lower(name) ~~ '%.png'::text) OR (lower(name) ~~ '%.webp'::text)) AND taki_can_upload_deal_image()));
-- storage.objects · chat_read_members
CREATE POLICY chat_read_members ON storage.objects FOR SELECT TO authenticated
  USING (((bucket_id = 'chat'::text) AND taki_chat_member(name)));
-- storage.objects · chat_write_members
CREATE POLICY chat_write_members ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'chat'::text) AND taki_chat_member(name) AND (owner = uid()) AND (name !~ '\.\.'::text) AND (array_length(string_to_array(name, '/'::text), 1) = 2)));
-- storage.objects · complaints_files_del
CREATE POLICY complaints_files_del ON storage.objects FOR DELETE TO authenticated
  USING (((bucket_id = 'complaints'::text) AND taki_complaint_party(name)));
-- storage.objects · complaints_files_read
CREATE POLICY complaints_files_read ON storage.objects FOR SELECT TO authenticated
  USING (((bucket_id = 'complaints'::text) AND taki_complaint_party(name)));
-- storage.objects · complaints_files_write
CREATE POLICY complaints_files_write ON storage.objects FOR INSERT TO authenticated
  WITH CHECK (((bucket_id = 'complaints'::text) AND (split_part(name, '/'::text, 1) = (uid())::text) AND (owner = uid()) AND (name !~ '\.\.'::text) AND (array_length(string_to_array(name, '/'::text), 1) = 3)));


-- ═══ VIEWS ═══
-- app_secrets
CREATE OR REPLACE VIEW public.app_secrets AS
 SELECT SUBSTRING(name FROM 12) AS key,
    decrypted_secret AS value
   FROM vault.decrypted_secrets s
  WHERE (name ~~ 'app\_secret:%'::text);
-- sellers_public
CREATE OR REPLACE VIEW public.sellers_public AS
 SELECT id,
    name,
    shop,
    avatar_url,
    bio,
    contact_phone,
        CASE
            WHEN (user_type = 'buyer'::text) THEN 'buyer'::text
            ELSE 'seller'::text
        END AS user_type,
    lat,
    lng,
    google_maps_link,
    working_hours,
    preferred_lang,
    created_at
   FROM users u
  WHERE ((user_type <> 'buyer'::text) AND (deleted_at IS NULL) AND (COALESCE(is_suspended, false) = false));
-- v_top_buyers
CREATE OR REPLACE VIEW public.v_top_buyers AS
 SELECT u.id,
    u.name,
    u.phone,
    (count(b.barcode))::integer AS bookings_count,
    sum((d.discounted_price * (b.booked_quantity)::numeric)) AS total_spent,
    u.last_active_at,
    u.created_at
   FROM ((users u
     LEFT JOIN bookings b ON ((b.user_id = u.id)))
     LEFT JOIN deals d ON ((d.id = b.deal_id)))
  WHERE (u.user_type = 'buyer'::text)
  GROUP BY u.id, u.name, u.phone, u.last_active_at, u.created_at
  ORDER BY ((count(b.barcode))::integer) DESC;
-- v_top_sellers
CREATE OR REPLACE VIEW public.v_top_sellers AS
 SELECT u.id,
    u.name,
    u.shop,
    count(DISTINCT d.id) FILTER (WHERE ((d.status IS NULL) OR (d.status <> 'deleted'::text))) AS deals_count,
    count(DISTINCT b.barcode) AS bookings_count,
    sp.subscription_plan,
    sp.subscription_amount,
    sp.subscription_expires_at,
    u.last_active_at
   FROM (((users u
     LEFT JOIN deals d ON ((d.store_id = u.id)))
     LEFT JOIN bookings b ON ((b.store_id = u.id)))
     LEFT JOIN store_profiles sp ON ((sp.store_id = u.id)))
  WHERE (u.user_type = 'seller'::text)
  GROUP BY u.id, u.name, u.shop, sp.subscription_plan, sp.subscription_amount, sp.subscription_expires_at, u.last_active_at
  ORDER BY (count(DISTINCT b.barcode)) DESC;


